/* twine-user-stylesheet #1: "computer.css" */
.computer-monitor {
    font: Arial;
    /* font-family: "Helvetica Neue"; */
    padding: 0 0.625em;
    margin-top: 0;
    min-width: 10em;
    max-width: 32em;
    min-height: 26em;
    margin: auto;
    -webkit-border-radius: 2em 2em 2em 2em;
    -moz-border-radius: 2em 2em 2em 2em;
    -o-border-radius: 2em 2em 2em 2em;
    -ms-border-radius: 2em 2em 2em 2em;
    border-radius: 2em 2em 2em 2em;
    border-style: solid;
    border-width: 1em 1em 1em;
    border-color: rgb(48, 48, 49);
    background-color: #161616;
    line-height: 100%;
    color: #1f1f1f;
    background-image: url("https://cdn.jsdelivr.net/gh/PEEPEEBOY69/nohbdy-assets@obscura-v20/obscura/img/phone_bg.jpg");
}
/* twine-user-stylesheet #2: "elkbook.css" */
.elkbook-container {
    min-width: 19em;
    -webkit-border-radius: 0.5em 0.5em 0.5em 0.5em;
    -moz-border-radius: 0.5em 0.5em 0.5em 0.5em;
    -o-border-radius: 0.5em 0.5em 0.5em 0.5em;
    -ms-border-radius: 0.5em 0.5em 0.5em 0.5em;
    border-radius: 0.5em 0.5em 0.5em 0.5em;
    border-style: solid;
    border-width: 0.125em 0.125em 0.125em 0.125em;
    border-color: rgb(124, 124, 124);
    margin: 0.5em;
    padding: 0.25em;
    background-color: #242424;
    line-height: 100%;
    color: #e6e6e6;
}

.elkbook-name {
    color: #e6e6e6;
    font-weight: bold;
    line-height: 120%;
}

.elkbook-text {
    color: #e6e6e6;
    line-height: 120%;
}

/* timeline */

.elkbook-timeline-container {
    color: #e0e0e0;
    background-color: #283848;
    margin: 0.5em;
    padding: 0.25em;
    border-radius: 6px;
}

.elkbook-timeline-container a {
    color: #88b2ce;
}

.elkbook-timeline-entry {
    background-color: #1e2e3e;
    border-radius: 6px;
    border-style: solid;
    border-width: 1px;
    border-color: rgb(34, 48, 61);
    margin: 0.5em 0.5em 1em 0.5em;
    padding: 0.75em;
    color: #d0d7dd;
}
.elkbook-timeline-entry-system
{
    background-color: transparent;
    border: none;
    padding: 0.5em 0.75em;
    font-weight: normal;
    font-size: 0.85em;
    color: #8a9baa;
    display: flex;
    align-items: center;
    gap: 0.5em;
    margin: 0.75em 0.5em;
}

.elkbook-timeline-entry-system .elkbook-timeline-header-date {
    margin-left: auto;
    font-size: 0.85em;
    color: #4d5e6b;
}

.elkbook-timeline-entry-system a {
    color: #88b2ce;
    font-weight: 600;
}

.elkbook-timeline-name {
    font-weight: bold;
}

.elkbook-timeline-header-user
{
    padding-bottom: 0em;
    margin-bottom: 0em;
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 0.625em;
}

.elkbook-post-avatar {
    width: 3.5em;
    height: 3.5em;
    font-size: 1.1em;
    border-radius: 50%;
    background: #2a4a5a;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    color: #76a9b8;
    flex-shrink: 0;
    border: 1.5px solid #3a5a6a;
}

.elkbook-post-header-container {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.elkbook-timeline-entry-post .elkbook-post-body {
    padding-left: 4.5em;
}

.elkbook-showmore {
    text-align: center;
    padding: 0.5em 0;
}

.elkbook-timeline-entry-hidden {
    display: none;
}

.elkbook-timeline-header-date {
    color: #6d7e8c;
    font-size: small;
}

.elkbook-timeline-name,
.elkbook-timeline-header-date,
.elkbook-timeline-header-divider {
  margin: 0;
  padding: 0;
  line-height: 1.0;
}

.elkbook-timeline-emoji {
    font-size: 1.2em;
    text-shadow: rgba(0, 0, 0, 0.8) 0px 0px 4px;
}

.elkbook-overlay {
    background: #1c2d3b;
    border-radius: 6px;
    overflow: hidden;
    border: 1px solid #3b4d5c;
}

.elkbook-profile-card-container {
    color: #e0e0e0;
    background-color: #1e2e3e;
    border-width: 1px;
    border-style: solid;
    border-color: #354758;
    border-radius: 6px;
    margin: 0.5em;
    padding: 0.75em;
}

.elkbook-overlay .elkbook-profile-card-container {
    margin: 0;
    padding: 1em;
    border-radius: 6px 6px 0 0;
    border-bottom: 1px solid #3b4d5c;
}

.elkbook-profile-item-container {
    display: flex;
    flex-wrap: wrap;
    padding: 0.25em 0em;
}

.elkbook-overlay .elkbook-timeline-container {
    margin: 0;
}

.elkbook-profile-item-label {
    color: #7b8d9c;
    flex: 1;
    margin: 0;
}

.elkbook-profile-item-content {
    flex: 1;
    margin: 0;
    font-weight: bold;
    color: #bfc9d1;
}

.elkbook-profile-card-header {
    display: flex;
    align-items: center;
    gap: 0.875em;
}

.elkbook-profile-avatar {
    width: 3.5em;
    height: 3.5em;
    font-size: 1.1em;
}

.elkbook-profile-card-name {
    font-size: 1.2em;
    font-weight: 700;
    color: #cdd7df;
    margin-bottom: 0.125em;
}

.elkbook-profile-card-body {
    font-size: 0.85em;
    color: #7b8d9c;
}

.elkbook-profile-card-body .elkbook-profile-item-container {
    display: inline;
}

.elkbook-profile-card-body .elkbook-profile-item-container + .elkbook-profile-item-container::before {
    content: " · ";
    color: #4d5e6b;
}

.elkbook-section-label {
    font-size: 0.75em;
    letter-spacing: 0.1em;
    color: #6d7e8c;
    padding: 0.75em 1em 0.25em;
    text-transform: uppercase;
}

.elkbook-topbar {
    background: #1a2d3d;
    padding: 0.5em 1em;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid #3b4d5c;
}

.elkbook-logo {
    font-weight: 700;
    font-size: 1.2em;
    color: #76a9b8;
    display: flex;
    align-items: center;
}

.elkbook-logo-primary {
    color: #76a9b8;
}

.elkbook-logo-secondary {
    color: #4a7a8a;
}

.elkbook-logo-icon {
    width: 1.25em;
    height: 1.25em;
    border-radius: 3px;
    margin-right: 0.5em;
}

/* overrides for displaying in View Person dialog */

.display-npc-elkbook-timeline .elkbook-timeline-container {
    background-color: transparent;
    padding: 0;
    margin: 0;
    color: inherit;
}

.display-npc-elkbook-timeline .elkbook-timeline-entry {
    background-color: rgb(34, 34, 34);
    border-color: rgb(44, 44, 44);
    color: #cdcdcf;
}

.display-npc-elkbook-timeline .elkbook-timeline-container a {
    color: rgba(76, 108, 196, 0.9);
}

.display-npc-elkbook-timeline .elkbook-timeline-header-date {
    color: #636368;
}

.display-npc-elkbook-timeline .elkbook-timeline-header-user {
    border-bottom-color: rgb(41, 41, 41);
}
