/* twine-user-stylesheet #4: "input_range.css" */
input[type=range] {
    width: 100%;
    margin: 0.6em 0;
    background-color: transparent;
    appearance: none;
    -webkit-appearance: none;
  }
  input[type=range]:focus {
    outline: none;
  }
  input[type=range]::-webkit-slider-runnable-track {
    background: rgba(221, 76, 88, 0.5);
    border: 0.7px solid #010101;
    border-radius: 14px;
    width: 100%;
    height: 0.57em;
    cursor: pointer;
  }
  input[type=range]::-webkit-slider-thumb {
    margin-top: -10.15px;
    width: 1.2em;
    height: 1.75em;
    background: rgb(109, 109, 109);
    border: 1.8px solid rgb(26, 4, 6);
    border-radius: 15px;
    cursor: pointer;
    -webkit-appearance: none;
  }
  input[type=range]:focus::-webkit-slider-runnable-track {
    background: rgb(225, 97, 108);
  }
  input[type=range]::-moz-range-track {
    background: rgba(221, 76, 88, 0.5);
    border: 0.7px solid #010101;
    border-radius: 14px;
    width: 100%;
    height: 0.57em;
    cursor: pointer;
  }
  input[type=range]::-moz-range-thumb {
    width: 1.2em;
    height: 1.75em;
    background: rgb(109, 109, 109);
    border: 1.8px solid rgb(26, 4, 6);
    border-radius: 15px;
    cursor: pointer;
  }
  input[type=range]::-ms-track {
    background: transparent;
    border-color: transparent;
    border-width: 10.85px 0;
    color: transparent;
    width: 100%;
    height: 0.57em;
    cursor: pointer;
  }
  input[type=range]::-ms-fill-lower {
    background: rgb(217, 55, 68);
    border: 0.7px solid #010101;
    border-radius: 28px;
  }
  input[type=range]::-ms-fill-upper {
    background: rgba(221, 76, 88, 0.5);
    border: 0.7px solid #010101;
    border-radius: 28px;
  }
  input[type=range]::-ms-thumb {
    width: 0.76em;
    height: 1.75em;
    background: rgb(109, 109, 109);
    border: 1.8px solid rgb(26, 4, 6);
    border-radius: 15px;
    cursor: pointer;
    margin-top: 0;
    /*Needed to keep the Edge thumb centred*/
  }
  input[type=range]:focus::-ms-fill-lower {
    background: rgba(221, 76, 88, 0.5);
  }
  input[type=range]:focus::-ms-fill-upper {
    background: rgb(225, 97, 108);
  }
  /*TODO: Use one of the selectors from https://stackoverflow.com/a/20541859/7077589 and figure out
  how to remove the virtical space around the range input in IE*/
  @supports (-ms-ime-align:auto) {
    /* Pre-Chromium Edge only styles, selector taken from hhttps://stackoverflow.com/a/32202953/7077589 */
    input[type=range] {
      margin: 0;
      /*Edge starts the margin from the thumb, not the track as other browsers do*/
    }
  }

/* twine-user-stylesheet #5: "map.css" */
.hasmap {
    min-height: 600px !important;
    /* height: 600px; */
    /* padding-bottom: 285px !important; */
}

#mapimg {
    position: relative;
    z-index: 1;
}

#imgmap {
    visibility: visible;
}

#maparrowimg {
    position: absolute;
    z-index: 2;    
    animation: markerbounce 0.95s ease-in-out infinite;
}

@keyframes markerbounce {
    0% { transform: translateY(0); }
    50% { transform: translateY(-4px); }
    100% { transform: translateY(0); }
}

#maparrowclassimg {
    position: absolute;
    z-index: 2;    
    animation: markerbouncediag 0.95s ease-in-out infinite;
}

@keyframes markerbouncediag {
    0% { transform: translateY(0) translateX(0); }
    50% { transform: translateY(-4px) translateX(4px); }
    100% { transform: translateY(0) translateX(0); }
}

#mapcontainer {
    position: relative;
    bottom: 0;
}

#mapcontainerfloating {
    position: relative;
}

#mapimg-mobile {
    position: relative;
    z-index: 1;
    visibility: hidden;
}

#maparrowimg-mobile {
    position: absolute;
    z-index: 2;    
    animation: markerbounce 0.95s ease-in-out infinite;
    visibility: hidden;
}

#maparrowclassimg-mobile {
    position: absolute;
    z-index: 2;    
    animation: markerbouncediag 0.95s ease-in-out infinite;
    visibility: hidden;
}

#mapcontainer-mobile {
    position: relative;
    bottom: 0;
    visibility: hidden;
    display: none;
}

#mapcontainerfloating-mobile {
    position: relative;
    visibility: hidden;
    display: none;
}

#imgmap-modile {
    visibility: hidden;
    display: none;
}
/* twine-user-stylesheet #6: "mobile-exceptions.css" */
