    }

    #mapimg {
        visibility: hidden;
    }

    #maparrowimg {
        visibility: hidden;
    }

    #maparrowclassimg {
        visibility: hidden;
    }

    #mapcontainer {
        visibility: hidden;
        display: none;
    }

    #mapcontainerfloating {
        visibility: hidden;
        display: none;
    }

    #imgmap {
        visibility: hidden;
        display: none;
    }

    #mapimg-mobile {
        visibility: visible;
    }

    #maparrowimg-mobile {
        visibility: visible;
    }

    #maparrowclassimg-mobile {
        visibility: visible;
    }

