/* twine-user-stylesheet #7: "odometer.css" */
.odometer.odometer-auto-theme, .odometer.odometer-theme-default {
  display: inline-block;
  vertical-align: middle;
  position: relative;
}
.odometer.odometer-auto-theme .odometer-digit, .odometer.odometer-theme-default .odometer-digit {
  display: inline-block;
  vertical-align: middle;
  position: relative;
}
.odometer.odometer-auto-theme .odometer-digit .odometer-digit-spacer, .odometer.odometer-theme-default .odometer-digit .odometer-digit-spacer {
  display: inline-block;
  vertical-align: middle;
  visibility: hidden;
}
.odometer.odometer-auto-theme .odometer-digit .odometer-digit-inner, .odometer.odometer-theme-default .odometer-digit .odometer-digit-inner {
  text-align: left;
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  overflow: hidden;
}
.odometer.odometer-auto-theme .odometer-digit .odometer-ribbon, .odometer.odometer-theme-default .odometer-digit .odometer-ribbon {
  display: block;
}
.odometer.odometer-auto-theme .odometer-digit .odometer-ribbon-inner, .odometer.odometer-theme-default .odometer-digit .odometer-ribbon-inner {
  display: block;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
}
.odometer.odometer-auto-theme .odometer-digit .odometer-value, .odometer.odometer-theme-default .odometer-digit .odometer-value {
  display: block;
  -webkit-transform: translateZ(0);
  transform: translateZ(0);
}
.odometer.odometer-auto-theme .odometer-digit .odometer-value.odometer-last-value, .odometer.odometer-theme-default .odometer-digit .odometer-value.odometer-last-value {
  position: absolute;
}
.odometer.odometer-auto-theme.odometer-animating-up .odometer-ribbon-inner, .odometer.odometer-theme-default.odometer-animating-up .odometer-ribbon-inner {
  -webkit-transition: -webkit-transform 600ms;
  -moz-transition: -moz-transform 600ms;
  -ms-transition: -ms-transform 600ms;
  -o-transition: -o-transform 600ms;
  transition: transform 600ms;
}
.odometer.odometer-auto-theme.odometer-animating-up.odometer-animating .odometer-ribbon-inner, .odometer.odometer-theme-default.odometer-animating-up.odometer-animating .odometer-ribbon-inner {
  -webkit-transform: translateY(-100%);
  -moz-transform: translateY(-100%);
  -ms-transform: translateY(-100%);
  -o-transform: translateY(-100%);
  transform: translateY(-100%);
}
.odometer.odometer-auto-theme.odometer-animating-down .odometer-ribbon-inner, .odometer.odometer-theme-default.odometer-animating-down .odometer-ribbon-inner {
  -webkit-transform: translateY(-100%);
  -moz-transform: translateY(-100%);
  -ms-transform: translateY(-100%);
  -o-transform: translateY(-100%);
  transform: translateY(-100%);
}
.odometer.odometer-auto-theme.odometer-animating-down.odometer-animating .odometer-ribbon-inner, .odometer.odometer-theme-default.odometer-animating-down.odometer-animating .odometer-ribbon-inner {
  -webkit-transition: -webkit-transform 600ms;
  -moz-transition: -moz-transform 600ms;
  -ms-transition: -ms-transform 600ms;
  -o-transition: -o-transform 600ms;
  transition: transform 600ms;
  -webkit-transform: translateY(0);
  -moz-transform: translateY(0);
  -ms-transform: translateY(0);
  -o-transform: translateY(0);
  transform: translateY(0);
}

.odometer.odometer-auto-theme, .odometer.odometer-theme-default {
  font-family: "Helvetica Neue", sans-serif;
  line-height: 1.1em;
}
.odometer.odometer-auto-theme .odometer-value, .odometer.odometer-theme-default .odometer-value {
  text-align: center;
}

.odometer, .odometer * {
    font-family: var(--font-family, sans-serif) !important;
}
/* twine-user-stylesheet #8: "phone.css" */
/* General Styling */

:root {
    --phone-content-border-color: #979799;
    --phone-content-border: 2px solid var(--phone-content-border-color);
    --phone-content-border-radius: 5px;
    --phone-content-padding: 0.6em;
    --phone-background-color: #d8e6ff;
    --phone-text-color: #1f1f1f;
    --phone-background-color-emphasis: #274a85;
    --phone-contacts-color: #c2d8ff;
    --phone-calendar-padding: 0.3em;
    --phone-texting-text-color: rgb(240, 240, 240);;
    --phone-texting-background-color: #181818;
    --phone-texting-phonelinks-background-color: rgba(53, 53, 53, 0.479);
    --phone-texting-header-background-color: rgba(53, 53, 53, 1);
    --phone-texting-receive-background-color: rgba(53, 53, 53, 1);
    --phone-texting-send-background-color: rgb(56, 72, 163);
    --phone-badge-texts-color: #c81e1e;
    --phone-badge-elkbook-color: #274a85;
    --phone-badge-text-color: #ffffff;
    --phone-shortcut-menu-bg: #1a1a1a;
    --phone-shortcut-menu-border-color: #444;
}

/* this is the sugarcube dialog box */
div.phone-dialog {
    width: 25em;
}
/* no, THIS is the sugarcube dialog box */
div.phone-dialog-large {
    width: 100%;
}

.phone-container, .phone-container-large {
    font: Arial;
    margin: auto;
    line-height: 100%;
    background-color: var(--phone-background-color);
    /* background: linear-gradient(to right, #161616, #080707), linear-gradient(to bottom, #161616, #080707); */
    color: var(--phone-text-color);
    display: flex;
    flex-flow: column nowrap;
    box-sizing: border-box;
    overflow: hidden;
}

.phone-container hr,
.phone-container-large hr {
    border-top: var(--phone-content-border);
    height: 0;
    margin: 0;
}

.phone-container a,
.phone-container-large a {
    color: rgb(0, 81, 134);
}

.phone-container {
    width: 40%;
    min-width: 20em;
    height: 38em;
    -webkit-border-radius: 2em 2em 2em 2em;
    -moz-border-radius: 2em 2em 2em 2em;
    -o-border-radius: 2em 2em 2em 2em;
    -ms-border-radius: 2em 2em 2em 2em;
    border-radius: 2em 2em 2em 2em;
    border-style: solid;
    border-width: 2em 0.5em 2em 0.5em;
    border-color: rgb(48, 48, 49);
    /* Other things are starting to use border-box but this breaks the phone for now, so back to context-box */
    box-sizing: content-box;
}

.phone-container-large {
    /* where we give up some styling for the purposes of practicality */
    width: 98%;
    min-width: 50em;
    min-height: 44em;
    background-color: var(--phone-background-color);
}

.phone-bg {
    background-image: url("https://cdn.jsdelivr.net/gh/PEEPEEBOY69/nohbdy-assets@obscura-v20/obscura/img/phone_bg.jpg");
    background-repeat: no-repeat;
    background-size: cover;
}

.phone-header {
    display: flex;
    align-items: center;
    justify-content: center;
    color: rgb(27, 27, 27);
    background-color: rgba(219, 219, 223, 0.5);
    border-bottom: var(--phone-content-border);
    padding: 0.9em 0 0.8em 0;
    width: 100%;
}

.phone-content {
    display: flex;
    flex-flow: column nowrap;
    flex: 1;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    padding: 0 var(--phone-content-padding);
}

.phone-footer {
    margin-top: auto;
    padding-top: 1em;
    margin-bottom: 1em;
}

.phone-nav-button {
    font-size: 150%;
}

/* Home Screen */

a.phone-icon {
    display: inline-block;
    text-decoration: none;
    color: white;
    /* text-shadow: -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000, 1px 1px 0 #000; */
    padding: 1em;
    padding-left: 0.75em;
    padding-right: 0.75em;
}

.phone-icons {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    justify-content: center;
    padding: 1em;
}

.computer-monitor .phone-icons {
    grid-template-columns: repeat(auto-fit, minmax(88px, 1fr));
}

.phone-icon-img {
    width: 64px;
}

.phone-icon-name {
    text-align: center;
}

.phone-icon:hover {
    text-decoration: none;
}

.phone-icon-container {
    text-align: center;
}

.phone-screen-internet .phone-content {
    padding: 0;
}
.phone-screen-internet .phone-footer {
    padding: 0 var(--phone-content-padding);
}

/* Contacts */

.phone-screen-contacts .phone-header, .phone-screen-text .phone-header {
    background-color: var(--phone-contacts-color);
}
.phone-screen-contacts .phone-content {
    padding: 0;
}
.phone-screen-contacts .phone-footer {
    padding: 0 var(--phone-content-padding);
}

.phone-contact-category-selected {
    color: #15294c;
}

.phone-contact-categories-container {
    margin-bottom: 0.5em;
    padding: 0 var(--phone-content-padding);
}

.phone-contact-categories {
    display: flex;
    flex-flow: row wrap;
    margin-left: auto;
    margin-right: auto;
    justify-content: space-between;
    gap: 0.625em;
}

.phone-contact-category {
    text-align: center;
    cursor: default;
}

.phone-contact-category.selected .phone-contact-category-icon,
.phone-contact-category:hover .phone-contact-category-icon {
    background-color: var(--phone-background-color-emphasis);
}

.phone-contact-category:not(.selected):hover {
    cursor: pointer;
}

.phone-contact-category:not(.selected):hover .phone-contact-category-name {
    text-decoration: underline;
}

.phone-contact-category-icon {
    background-color: var(--phone-contacts-color);
    border: var(--phone-content-border);
    -webkit-border-radius: var(--phone-content-border-radius);
    -moz-border-radius: var(--phone-content-border-radius);
    -o-border-radius: var(--phone-content-border-radius);
    -ms-border-radius: var(--phone-content-border-radius);
    border-radius: var(--phone-content-border-radius);
    min-width: 1em;
    min-height: 1em;
    font-size: 200%;
    line-height: 1;
    padding-top: 0.1em;
    padding-bottom: 0.1em;
    transition: background-color ease 0.1s;
}

.phone-contact-category-name {
    font-size: 75%;
}

.phone-contact-search-container {
    margin-top: 0.6em;
    margin-bottom: 0.6em;
    padding: 0 var(--phone-content-padding);
}

.phone-contact-search {
    border: var(--phone-content-border);
    background-color: var(--phone-contacts-color);
    -webkit-border-radius: var(--phone-content-border-radius);
    -moz-border-radius: var(--phone-content-border-radius);
    -o-border-radius: var(--phone-content-border-radius);
    -ms-border-radius: var(--phone-content-border-radius);
    border-radius: var(--phone-content-border-radius);
    display: flex;
    flex-flow: row nowrap;
    align-items: center;
    padding: 0.4em 0;
}

.phone-contact-search-icon {
    margin-left: 0.25em;
    margin-right: 0.25em;
}

.phone-contact-clear-button a {
    display: inline-block;
    font-size: 120%;
    width: 1.5em;
    font-weight: bold;
    text-align: center;
    user-select: none;
    -webkit-user-select: none;
    -ms-user-select: none;
    color: #8b0000;
}

.phone-contact-clear-button a:hover {
    cursor: pointer;
    text-decoration: none;
}

.phone-contact-search-input {
    flex-grow: 1;
    overflow: hidden;
}

.phone-contact-search input[type=text] {
    border: none;
    background-color: transparent;
    color: var(--phone-text-color);
    min-width: 0;
    outline: none;
    padding: 0;
    width: 100%;
}

.phone-contacts-list {
    display: flex;
    flex-shrink: 1;
    min-height: 0;
    flex-flow: column nowrap;
    margin-top: 0.5em;
}

.phone-contacts-none-error {
    padding: 0 var(--phone-content-padding);
}

.phone-contact-line {
    display: flex;
    height: 1.5em;
    flex-flow: row nowrap;
    justify-content: space-between;
    align-items: center;
    padding: 0 var(--phone-content-padding);
    transition: background-color ease 0.1s;
}

.phone-contact-line:hover {
    cursor: pointer;
    background-color: var(--phone-contacts-color);
}

.phone-contact-line:hover .phone-contact-line-link a {
    text-decoration: underline;
}

.phone-contact-line a {
    color: var(--phone-text-color) !important;
}

.phone-page-control {
    display: flex;
    flex-flow: row nowrap;
    justify-content: center;
    text-align: center;
    margin-bottom: 0.75em;
}

.phone-page-control-arrow {
    width: 2em;
    user-select: none;
    -webkit-user-select: none;
    -ms-user-select: none;
}

/* Texting */

.phone-header-texting {
    background-color: var(--phone-texting-header-background-color) !important;
}

.phone-text-header-texting {
    font-weight: normal;
    text-align: center;
    font-size: 120%;
    margin: 0;
}

.phone-text-header-texting a {
    color: var(--phone-texting-text-color) !important;
}

#phone-convo {
    width: 100%;
    overflow-y: auto;
    overflow-x: hidden;
    scrollbar-width: thin;
    scrollbar-color: rgba(255,255,255,0.4) transparent;
}

.phone-content-texting {
    background-color: var(--phone-texting-background-color) !important;
}

.phonelinks-container {
    background-color: var(--phone-texting-phonelinks-background-color);
    border: var(--rounded-border-style);
    border-radius: var(--rounded-border-radius);
    padding: 0.3em;
    max-height: 5em;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: rgba(255,255,255,0.4) transparent;
}
.phonelinks-container::-webkit-scrollbar {
    width: 6px;
}
.phonelinks-container::-webkit-scrollbar-track {
    background: transparent;
}
.phonelinks-container::-webkit-scrollbar-thumb {
    background-color: rgba(255, 255, 255, 0.4);
    border-radius: 3px;
}

.phonelinks-container-minimized {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.phone-image-icon {
    height: 1.2em;
    width: auto;
    margin-left: auto;
    filter: brightness(0) invert(0.94);
}

.phonelinks-container a {
    color: var(--phone-texting-text-color);
}

.phone-text-bubbled-left,
.phone-text-bubbled-right {
    margin-top: 1.25em;
    padding: 0.3em 0.55em;
    max-width: 50%;
    clear: both;
    position: relative;
}

.phone-text-bubbled-left {
    float: left;
    margin-right: auto;
    -webkit-border-radius: 0.5em 0.5em 0.5em 0;
    -moz-border-radius: 0.5em 0.5em 0.5em 0;
    -o-border-radius: 0.5em 0.5em 0.5em 0;
    -ms-border-radius: 0.5em 0.5em 0.5em 0;
    border-radius: 0.5em 0.5em 0.5em 0;
    background-color: var(--phone-texting-receive-background-color);
    color: var(--phone-texting-text-color);
}

.phone-text-bubbled-left:before {
    border-bottom: 0.6em solid var(--phone-texting-receive-background-color);
    border-left: 0.55em solid rgba(0, 0, 0, 0);
    position: absolute;
    bottom: 0;
    left: -0.5em;
    content: "";
}

.phone-text-bubbled-right {
    float: right;
    margin-left: auto;
    text-align: right;
    -webkit-border-radius: 0.5em 0.5em 0 0.5em;
    -moz-border-radius: 0.5em 0.5em 0 0.5em;
    -o-border-radius: 0.5em 0.5em 0 0.5em;
    -ms-border-radius: 0.5em 0.5em 0 0.5em;
    border-radius: 0.5em 0.5em 0 0.5em;
    background-color: var(--phone-texting-send-background-color);
    color: var(--phone-texting-text-color);
}

.phone-text-bubbled-right:before {
    border-bottom: 0.55em solid var(--phone-texting-send-background-color);
    border-right: 0.55em solid rgba(0, 0, 0, 0);
    position: absolute;
    bottom: 0;
    right: -0.5em;
    content: "";
}

/* Reminders */

.phone-screen-reminders .phone-header {
    background-color: #ffd5b9;
}

.phone-reminders-container {
    display: flex;
    flex-flow: column nowrap;
}

.phone-reminder {
    background-color: #ffeadc;
    color: var(--phone-text-color);
    border: var(--phone-content-border);
    -webkit-border-radius: var(--phone-content-border-radius);
    -moz-border-radius: var(--phone-content-border-radius);
    -o-border-radius: var(--phone-content-border-radius);
    -ms-border-radius: var(--phone-content-border-radius);
    border-radius: var(--phone-content-border-radius);
    text-align: left;
    padding: 0.4em;
    margin-top: 0.75em;
    line-height: 1.15;
}

.phone-screen-reminders .phone-page-control-number {
    color: #ffffff;
}

/* Calendar */

.phone-screen-calendar .phone-header {
    background-color: #BFE19B;
}

.phone-calendar {
    box-sizing: border-box;
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    grid-template-rows: 1.5em repeat(4, 1fr);
    border-left: 1px solid var(--phone-content-border-color);
    border-top: 1px solid var(--phone-content-border-color);
    width: 100%;
}

.phone-calendar-row {
    display: table-row;
}

.phone-calendar-month-header {
    display: flex;
    flex-flow: row nowrap;
    justify-content: center;
    font-size: larger;
    background-color: white;
    margin-top: 0.3em;
    width: 100%;
    padding: 0.35em 0;
    user-select: none;
    -webkit-user-select: none;
    -ms-user-select: none;
    border-top: 1px solid var(--phone-content-border-color);
    border-left: 1px solid var(--phone-content-border-color);
    border-right: 1px solid var(--phone-content-border-color);
}

.phone-calendar-month-header a {
    color: #3f704d;
}

.phone-calendar-month-text {
    text-align: center;
    width: 6.5em;
    font-weight: bold;
}

.phone-calendar-day-label {
    display: flex;
    flex-flow: row nowrap;
    justify-content: flex-end;
    align-items: flex-end;
    font-weight: bold;
    background-color: #d3d3d3;
    border-right: 1px solid var(--phone-content-border-color);
    border-bottom: 1px solid var(--phone-content-border-color);
    padding-right: var(--phone-calendar-padding);
    padding-bottom: 0.1em;
}

.phone-calendar-day {
    display: flex;
    flex-flow: column nowrap;
    padding-left: 0.1em;
    padding-right: var(--phone-calendar-padding);
    padding-top: var(--phone-calendar-padding);
    border-right: 1px solid var(--phone-content-border-color);
    border-bottom: 1px solid var(--phone-content-border-color);
    min-height: 7em;
    background-color: white;
    vertical-align: top;
}

.phone-calendar-day-past {
    background-color: #aaaaaa;
}

.phone-calendar-day-past .phone-calendar-day-content {
    color: #444444;
}

.phone-calendar-day-today {
    background-color: #B0D589;
}

.phone-calendar-day-content {
    font-size: small;
    text-align: left;
}

.phone-calendar-sports-event {
    color: #ba8923;
}

.phone-calendar-day-content br {
    content: "";
    display: block;
    margin-bottom: 0.2em;
}

.phone-calendar-day-number {
    align-self: flex-end;
    font-size: smaller;
    font-weight: bold;
}

.phone-forecast-cell img {
    width: 4em;
    height: auto;
    border-radius: 16px;
}

/* Weather forecast */

.phone-screen-forecast .phone-header {
    background-color: #7eb3e3;
}
.phone-forecast-wrapper {
    width: 100%;
    box-sizing: border-box;
    margin-top: 1em;
    scrollbar-color: #7eb3e3 #c0e1ff;
    scrollbar-width: thin;
}
.phone-text-header-selected {
    text-decoration: underline;
}
.phone-forecast-cell {
    background-color: #c0e1ff;
}
/* Not used right now, but maybe if we want to align the hourly forecast and grey out
   the hours that have already passed? */
.phone-forecast-cell.disabled {
    background-color: #8eb3d6;
}

/* Ten day forecast */

.phone-forecast-container.tenday {
    display: flex;
    flex-flow: column nowrap;
    flex: 1;
    gap: 0.5em;
    box-sizing: inherit;
    align-items: center;
    justify-content: flex-start;
}

.phone-forecast-container.tenday .phone-forecast-cell {
    width: 30em;
    display: flex;
    flex-flow: row nowrap;
    align-items: center;
    justify-content: space-between;
    border-radius: 1em;
    padding: 0.5em;
    gap: 1em;
    box-sizing: border-box;
}

.phone-forecast-container.tenday .phone-forecast-cell-content {
    display: flex;
    flex-flow: row nowrap;
    gap: 2em;
    justify-content: center;
}

.phone-forecast-cell-timeofday {
    display: flex;
    flex-flow: column nowrap;
    justify-content: center;
}

.phone-forecast-cell-timeofday-header {
    text-align: center;
}

.phone-forecast-cell-timeofday-content {
    display: flex;
    flex-flow: row nowrap;
    justify-content: center;
    gap: 0.25em;
}

.phone-forecast-cell-header-weekday, .phone-forecast-cell-timeofday-header {
    font-weight: bold;
}

/* Twenty-four hour forecast */


.phone-forecast-container.twentyfour {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    grid-template-rows: repeat(2, 1fr);
    gap: 0.5em;
    box-sizing: border-box;
    overflow-x: scroll;
    width: 100%;
    padding: 1em;
}

.phone-forecast-container.twentyfour .phone-forecast-cell {
    width: 7.5em;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    border-radius: 1em;
    padding: 0.5em;
    align-self: flex-start;
    box-sizing: border-box;
}

.ui-dialog.phonewide {
    min-width: 1024px;
    width: auto;
    max-width: 100vw;
}

.ui-dialog.phonewide .ui-dialog-content {
    overflow-x: auto;
    width: 100%;
    min-width: 1024px;
}

.fertilityapp-bg {
    border-radius: 1em;
    padding: 0.5em;
    margin: 1em;
    gap: 1em;
    box-sizing: border-box;
    color: #aaaaaa;
    background-color: #303030;
    background-image: linear-gradient(to bottom right, #303030, #4b4b4b, #303030);
}

.phone-button-container {
    position: relative;
    display: flex;
    width: 100%;
    gap: 0;
}

.phone-main-button {
    flex: 1 1 auto;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5em;
    border-top-right-radius: 0;
    border-bottom-right-radius: 0;
}

.phone-badges {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.15em;
    flex-direction: column;
}

.phone-badges-disabled {
    opacity: 0.55;
}

.phone-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.5em;
    height: 1.5em;
    padding: 0 0.4em;
    border-radius: 999em;
    font-size: 0.75em;
    font-weight: bold;
    line-height: 1;
    color: #fff;
    box-sizing: border-box;
}

