/* force spaces to show up between widgets for screen reader users, but keep them invisible to everybody else */
.inline-natural-language::before {
    content: " ";
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

.tabgroup {
	display: flex;
	flex-direction: column;
}

.tabgroup-bar {
	display: flex;
	border-bottom: 1px solid rgba(255, 255, 255, 0.08);
	overflow-x: auto;
	scrollbar-width: none;
    gap: 4px;
    flex-wrap: wrap;
}
.tabgroup-bar::-webkit-scrollbar {
	display: none;
}

.tabgroup-button {
	flex: 1 1 auto;
	padding: 8px 12px;
	background: none;
	border: none;
	position: relative;
	font-size: 0.8em;
	font-weight: medium;
	letter-spacing: 0.04em;
	color: rgba(255, 255, 255, 0.65);
	transition: color 0.2s ease;
	white-space: nowrap;
}
.tabgroup-button:hover {
	color: rgba(255, 255, 255, 0.9);
    background: transparent;
}
.tabgroup-button.active {
	color: rgba(255, 255, 255, 0.9);
}
.tabgroup-button.active::after {
	content: '';
	position: absolute;
	bottom: 0;
	left: 20%;
	right: 20%;
	height: 2px;
	background: rgb(196, 76, 86);
	border-radius: 2px 2px 0 0;
}

.tabgroup-button-emoji {
	margin-right: 4px;
	font-size: 1.15em;
	vertical-align: middle;
}

