    padding: 18px 0;
}

.accordion {
	border: var(--rounded-border-style);
	border-radius: var(--rounded-border-radius);
    padding: 0.3em;
	overflow: hidden;
	margin-bottom: 6px;
}

.accordion-header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 10px;
    cursor: pointer;
	user-select: none;
    background: rgba(255, 255, 255, 0.025);
}
.accordion-header:hover {
	background: rgba(196, 76, 86, 0.1);
}

.accordion-header-label {
	font-size: 0.95em;
	font-weight: 600;
	color: rgba(255, 255, 255, 0.85);
}

.accordion-minrestore {
    font-family: tme-fa-icons!important;
	font-size: 1.5em;
	color: rgba(255, 255, 255, 0.65);
	transition: transform 0.25s ease;
    transform: rotate(-90deg);
}
.accordion.open .accordion-minrestore {
	transform: rotate(0deg);
}

.accordion-contents-wrapper {
	display: grid;
	grid-template-rows: 0fr;
	transition: grid-template-rows 0.25s ease;
}
.accordion.open .accordion-contents-wrapper {
	grid-template-rows: 1fr;
}

.accordion-contents {
