/* ── Obscura theme ───────────────────────────────────────────────────────────
   Built on BlizzardUI's visual grammar, translated to red/black/grey/white:
   layered near-black surfaces, 1px translucent borders, uppercase letterspaced
   controls, translateY(-1px) on hover, spring-out easing.

   The important borrowing: Blizzard NEVER fills a control with its accent.
   Accent lives in borders, hover tints and small highlights. A saturated fill
   reads as an error state, which is exactly why the first red pass looked
   broken. Appended after the hue-rotation pass, so it wins. */
:root{
  --ob-canvas:#07080a; --ob-panel:#0e1013; --ob-surface:#151619; --ob-raised:#1c1e22;
  --ob-text:#edeef0;   --ob-muted:#a8abb0; --ob-dim:#6f737a;
  --ob-accent:#e0313f; --ob-accent-soft:rgba(224,49,63,.13); --ob-accent-line:rgba(224,49,63,.55);
  --ob-border:rgba(235,238,242,.11); --ob-border-hi:rgba(240,244,248,.30);
  --ob-radius:12px; --ob-radius-btn:9px;
  --ob-shadow:0 22px 60px rgba(0,0,0,.72);
  --ob-ui:'Lexend-Regular','Helvetica Neue',sans-serif; /* embedded in the chassis; the
     family names are Lexend-Regular / Lexend-Bold, NOT 'Lexend' - a stack asking for
     'Lexend' matches nothing and silently falls back. */
  --ob-ui-bold:'Lexend-Bold','Helvetica Neue',sans-serif;
  --ob-eo:cubic-bezier(.22,1,.36,1);
  --font-size:17px;
}

/* ── surfaces ─────────────────────────────────────────────────────────── */
body{background:var(--ob-canvas)!important;color:var(--ob-text)!important;font-size:17px!important;
  font-family:var(--ob-ui)!important;}
#story{background:transparent!important;}
/* The chassis already cards #passages (#111, 10px radius). Style THAT rather than adding
   a second card on .passage — doing both nests one box inside another. */
#passages{background:var(--ob-panel)!important;border:1px solid var(--ob-border)!important;
  border-radius:var(--ob-radius)!important;box-shadow:var(--ob-shadow)!important;
  padding:2.1em 2.3em!important;font-size:1.02rem;line-height:1.75;}
.passage{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important;}

/* ── sidebar ──────────────────────────────────────────────────────────── */
#ui-bar{background:var(--ob-panel)!important;border-right:1px solid var(--ob-border)!important;}
#ui-bar-body{padding-top:.4em;}
#story-caption{font-size:.94rem;color:var(--ob-muted);}
/* The chassis sidebar menu is .storymenu-*, driven by --storymenu-button-border-style,
   which draws a table grid of half-borders. Kill the token, then style the real
   buttons as separate controls. #menu itself is display:none in this build. */
:root{--storymenu-button-border-style:none;}
.storymenu-button-block{border:0!important;margin-bottom:6px!important;}
.storymenu-button-container button,.storymenu-button-container a{
  width:100%;background:rgba(255,255,255,.03)!important;
  border:1px solid var(--ob-border)!important;border-radius:var(--ob-radius-btn)!important;
  color:var(--ob-muted)!important;font-family:var(--ob-ui)!important;
  font-size:.76rem!important;letter-spacing:.09em;text-transform:uppercase;
  padding:10px 8px!important;
  transition:color .15s var(--ob-eo),background .15s var(--ob-eo),border-color .15s var(--ob-eo),transform .15s var(--ob-eo);}
.storymenu-button-container button:hover,.storymenu-button-container a:hover{
  background:var(--ob-accent-soft)!important;border-color:var(--ob-accent-line)!important;
  color:#fff!important;transform:translateY(-1px);}
#menu-story a,#menu-core a{color:var(--ob-muted)!important;font-family:var(--ob-ui);}

/* ── controls: the overhaul ───────────────────────────────────────────── */
#story button,.macro-button,.link-internal,button[data-passage],input[type=button],#story a.link-internal{
  background:rgba(255,255,255,.035)!important;
  border:1px solid var(--ob-border)!important;
  color:var(--ob-text)!important;
  font-family:var(--ob-ui)!important;
  font-size:.86rem!important;
  letter-spacing:.055em;
  text-transform:uppercase;
  padding:11px 22px!important;
  border-radius:var(--ob-radius-btn)!important;
  cursor:pointer;
  text-decoration:none!important;
  transition:background .15s var(--ob-eo),border-color .15s var(--ob-eo),
             color .15s var(--ob-eo),transform .15s var(--ob-eo);}
#story button:hover,.macro-button:hover,.link-internal:hover,button[data-passage]:hover{
  background:var(--ob-accent-soft)!important;
  border-color:var(--ob-accent-line)!important;
  color:#fff!important;
  transform:translateY(-1px);}
#story button:active,.macro-button:active,.link-internal:active{transform:translateY(0) scale(.985);}
#story button:focus-visible,.macro-button:focus-visible{outline:2px solid var(--ob-accent-line);outline-offset:2px;}

/* Inline prose links stay text, not boxes. */
#story p a:not(.macro-button):not(.link-internal),#ui-dialog-body a{
  color:var(--ob-accent)!important;text-decoration:none;border-bottom:1px solid var(--ob-accent-line);}
#story p a:not(.macro-button):hover,#ui-dialog-body a:hover{color:#ff5666!important;}

/* ── dialogs ──────────────────────────────────────────────────────────── */
#ui-dialog-body{background:var(--ob-surface)!important;color:var(--ob-text)!important;}
#ui-dialog-titlebar{background:var(--ob-raised)!important;border-bottom:1px solid var(--ob-border)!important;}
#ui-dialog{border:1px solid var(--ob-border)!important;border-radius:var(--ob-radius)!important;
  box-shadow:var(--ob-shadow)!important;}

