        if (player.middlewear_covering(part) != null) _result2 = player.clothing_name(player.middlewear_covering(part));
    }
    if (_result1 == null) return _result2;
    if (_result2 == null) return _result1;
    return _result1 + " and " + _result2;
}

setup.ob_stripPoker.get_under_description = function(player, part, short = false)
{
    if (player.underwear_covering(part) == null) return;
