    if (_action_temp != null && (_action == null || _action_temp.level < _action.level)) _action = _action_temp;
    _action_temp = this.get_strip_action(player, "underwear");
    if (_action_temp != null && (_action == null || _action_temp.level < _action.level)) _action = _action_temp;
    if (_action == null) return;
    _action.probability = 0.5;
    if (player.has_any_inclination("basic_exhibitionist")) _action.probability *= 2;
    if (player.has_any_inclination("shyaboutsex")) _action.probability /= 2;
    _action.probability /= _action.level;
    return _action;
}

setup.ob_stripPoker.get_all_strip_actions = function(player, levelmax)
{
    let _actions = [];
    let _action = this.get_next_strip_action(player);
    let _pushed = false;
    while (_action)
    {
        if (_action.level > levelmax)
        {
            if (player.is_pc && !_pushed) _pushed = true;
            else break;
        }
        _actions.push(_action);
        this.perform_strip_action(player, _action);
        _action = this.get_next_strip_action(player);
    }
    return _actions;
