    const exposing_part = "shirt" === action.item || action.item == "bra" ? "chest" : "crotch";
    const strip_to_underwear = ["shirt", "pants"].includes(action.item)
    let underwear = player.underwear_covering(exposing_part);
    let covering = player.outermost_covering(exposing_part);

