        covering = player.outermost_covering(exposing_part);
        if (!covering && exposing_part == "crotch" && !player.is_pc)
            setup.people.learn_gender(player);
    }
}

setup.ob_stripPoker.can_strip = function(player)
{
    if (typeof player == "string") player = player == "PC" ? V.pc : new Person({person: player});
