setup.ob_riverRat.promote = function(newjob)
{
    V.riverrat.jobs.push(newjob);
    if (!this.jobs[newjob].unselectable)
        this.select_job(newjob);

    V.riverrat.dayssincepromotion = 0;
}

setup.ob_riverRat.select_job = function(job)
{
    const info = this.jobs[job];
    if (!info.unselectable)
    {
        V.riverrat.job = info.job;
        V.riverrat.jobtitle = job;
    }

    V.riverrat.tippedwage = this.get_tipped_wage();
    V.riverrat.standardwage = this.get_standard_wage();
}

setup.ob_riverRat.get_tipped_wage = function(job = V.riverrat.jobtitle)
{
    const info = this.jobs[job];
    if (info.takewagefrom && V.riverrat.jobs.includes(info.takewagefrom))
    {
        const info2 = this.jobs[info.takewagefrom];
        return info2.tippedwage;
    }
    else
    {
        return info.tippedwage;
    }
}

setup.ob_riverRat.get_standard_wage = function(job = V.riverrat.jobtitle)
{
    const info = this.jobs[job];
    if (info.takewagefrom && V.riverrat.jobs.includes(info.takewagefrom))
    {
        const info2 = this.jobs[info.takewagefrom];
        return info2.standardwage;
    }
    else
    {
        return info.standardwage;
    }
}

setup.ob_riverRat.get_next_available_job = function() {
  const allJobs = new Set(V.riverrat.jobs);

  const lockedJobsByPerformance = Object.entries(setup.ob_riverRat.jobs)
    .filter(([job]) => !allJobs.has(job))
    .sort(([, a], [, b]) => (a.promoteperformance || 0) - (b.promoteperformance || 0));

  return lockedJobsByPerformance.length ? lockedJobsByPerformance[0][0] : null;
}

setup.ob_riverRat.promotion_due = function() {
    const job_if_promoted = this.get_next_available_job();
    if (!job_if_promoted) return null;

    const new_job_info = setup.ob_riverRat.jobs[job_if_promoted];
    const meetsPerformance = V.riverrat.performance >= (new_job_info.promoteperformance || 0);
    const waitedLongEnough = V.riverrat.dayssincepromotion >= (new_job_info.promotedays || 0);

    return meetsPerformance && waitedLongEnough ? job_if_promoted : null;
}

setup.ob_riverRat.days_remaining_until_promotion = function() {
    const job_if_promoted = this.get_next_available_job();
    if (!job_if_promoted) return null;

    const new_job_info = setup.ob_riverRat.jobs[job_if_promoted];
    const days_until = new_job_info.promotedays - V.riverrat.dayssincepromotion;

    return days_until;
}

setup.ob_riverRat.get_promotion_line = function () {
    const promotionLines = {
        performance: {
            low: ["Looking at your coworkers, you can tell your experience is still lacking."],
            mid: ["Your job performance is steadily improving and is easily better than average."],
            high: ["Your actual workload is feeling noticeably easier as you almost have the hang of everything."],
            eligible: ["Excelling at your job, performance isn't a concern."]
        },
        time: {
            under3: ["Just need to work a couple more shifts for a formal review."],
            under7: ["It will be several shifts before your position will be available for review."],
            over7: ["It will be many more shifts of working before you can ask about a promotion."]
        },
        combined: {
            low_over7: ["It is clear you do not have the experience for a promotion yet - in job performance or daily shifts."],
            eligible_under3: ["You feel on top of your game and need to work only a couple more days before management recognizes it."]
        }
    };

    const job = this.get_next_available_job();
    if (!job) return "";

    const performance = V.riverrat.performance;
    const required_performance =  setup.ob_riverRat.jobs[job].promoteperformance || 0;
    const ratio = required_performance ? performance / required_performance : 0;
    const daysRemaining = ( setup.ob_riverRat.jobs[job].promotedays || 0) - V.riverrat.dayssincepromotion;

    const perfKey =
        ratio >= 1 ? "eligible" :
        ratio >= 0.8 ? "high" :
        ratio >= 0.6 ? "mid" :
        "low";

    const timeKey =
        daysRemaining < 3 ? "under3" :
        daysRemaining <= 7 ? "under7" :
        "over7";

    const combinedKey = `${perfKey}_${timeKey}`;
    const combinedLines = promotionLines.combined[combinedKey];

    if (combinedLines?.length) {
        return combinedLines[0]; // Use the first (and likely only) matching combined line
    }

    const perfLine = promotionLines.performance[perfKey]?.[0] || "";
    const timeLine = promotionLines.time[timeKey]?.[0] || "";

    return `${perfLine} ${timeLine}`;
};

setup.ob_riverRat.can_manage = function()
{
    if (!V.riverrat) return false;
    for (let job of V.riverrat.jobs)
        if (this.jobs[job].management) return true;
    return false;
}

setup.ob_riverRat.available_jobs = function()
{
    return V.riverrat.jobs.filter(job => !this.jobs[job].unselectable);
}

setup.ob_riverRat.client_type = function(name)
{
    let typelist = [];

    let wealth = setup.people.get_wealth(name);
    if (wealth >= 500)
        typelist.push("Elite", wealth);

    if (setup.people.skill_level(name, "Physical") >= 5)
        typelist.push("Sports Fan", setup.people.skill_level(name, "Physical") * 50);

    if (setup.people.skill_level(name, "Intellectual") >= 5)
        typelist.push("Geek", setup.people.skill_level(name, "Intellectual") * 50);

    if (setup.people.skill_level(name, "Sexual Knowledge") >= 5 || setup.people.has_any_inclination(name, "casualsex"))
        typelist.push("Punter", setup.people.skill_level(name, "Sexual Knowledge") * 50);

    if (setup.people.has_any_inclination(name, "insecure") || setup.people.has_any_inclination(name, "bragger"))
        typelist.push("Escapist", 500);
    else
        typelist.push("Reveler", 500);

    return setup.ob_randomrelfreq(typelist);
}

setup.ob_riverRat.upgrade = function(category)
{
    if (!V.riverrat || !V.riverrat.upgrades || !V.riverrat.upgrades[category])
    {
        // find default
        for (const [upname, upinfo] of Object.entries(setup.ob_riverRat.upgrades))
        {
            if (upinfo.category == category && upinfo.default)
                return upname;
        }
    }
    else
    {
        return V.riverrat.upgrades[category];
    }
}

setup.ob_riverRat.upgrade_list = function(category)
{
    return Object.keys(this.upgrades).filter(item => this.upgrades[item].category == category);
}

setup.ob_riverRat.set_upgrade = function(category, upgrade, narrative=false)
{
    let prev = this.upgrade(category);
    if (!V.riverrat.upgrades) V.riverrat.upgrades = {};
    V.riverrat.upgrades[category] = upgrade;

    if (!narrative)
    {
        V.riverrat.undoupgrade = {
            category: category,
            item: prev,
            price: this.upgrades[upgrade].price,
        }
    }

    return V.riverrat.upgrades;
}

setup.ob_riverRat.sub = function(category)
{
    let upgrade = this.upgrade(category);
    return this.upgrades[upgrade].sub;
}

setup.ob_riverRat.description = function(category)
{
    let upgrade = this.upgrade(category);
    return this.upgrades[upgrade].description;
}

setup.ob_riverRat.categories = function()
{
    const retval = [];
    for (const [upname, upinfo] of Object.entries(this.upgrades))
        if (!retval.includes(upinfo.category))
            retval.push(upinfo.category);
    return retval;
}

setup.ob_riverRat.attraction_for_demo = function(demo)
{
    let total = 0;
    let count = 0;
    for (const cat of this.categories())
    {
        let upgrade = this.upgrade(cat);
        const upinfo = this.upgrades[upgrade];
        if (upinfo.neutral) continue;
        total += upinfo.attraction[demo];
        count++;
    }
    return Math.floor((total / count) * 1000);
}

setup.ob_riverRat.attraction = function()
{
    let retval = {};
    for (const demo of Object.keys(this.clientele))
        retval[demo] = this.attraction_for_demo(demo);
    return retval;
}

setup.ob_riverRat.highest_attraction = function()
{
    let top, topn;
    for (const [demo, demon] of Object.entries(this.attraction()))
        if (topn == undefined || demon > topn)
        {
            top = demo;
            topn = demon;
        }
    return top;
}

setup.ob_riverRat.barsize = 5;
setup.ob_riverRat.sort_customers = function(exclude = [])
{
    let closed = setup.ob_is_closed("RiverRat");
    if (closed) return;
    let seed = V.day.toString() + V.hour.toString();
    let rng = setup.ob_newRNG(seed);

    V.riverrat.bar = [];
    V.riverrat.tables = [];

    let peopletoplace = rng.shuffle([...V.peopleatlocation]);

    let todelete = [];
    for (let name of peopletoplace)
    {
        if (exclude.includes(name)) continue;
        if (setup.people.is_employee(name, "River Rat") || !setup.people.allow_free_interaction(name))
        {
            todelete.push(name);
        }
        else
        {
            let barchance = this.bar_chance(name);
            if ((rng.random() < barchance || (V.riverrat.job == "bartender" && V.riverrat.bar.length < 2)) && V.riverrat.bar.length < this.barsize)
            {
                /* initialize bar stuff here */

                let newbar = {
                    person: name,
                    type: "bar",
                    interest: this.individual_interest(name),
                    approval: 0,
                    impatience: 0,
                    rounds: 0,
                    tip: 0,
                };

                V.riverrat.bar.push(newbar);
                todelete.push(name);
            }
        }
    }

    for (let name of todelete)
        peopletoplace.delete(name);

    while (peopletoplace.length > 0)
    {
        let name = peopletoplace[0];
        if (exclude.includes(name))
        {
            peopletoplace.delete(name);
        }
        else
        {
            let table = {people: [name]};
            peopletoplace.delete(name);
            if (peopletoplace.length == 1)
            {
                V.riverrat.tables.push(table);
            }
            else
            {
                let tablesize = rng.randomrelfreq([
                    1, 5,
                    2, 20,
                    3, 40,
                    4, 30,
                    5, 20,
                    6, 5,
                    7, 5,
                ]);
                if (tablesize == 1)
                {
                    V.riverrat.tables.push(table);
                }
                else
                {
                    for (let i  = 0; i <= tablesize; i++)
                    {
                        let name2 = this.find_table_match(name, peopletoplace, rng);
                        if (name2)
                        {
                            table.people.push(name2);
                            peopletoplace.delete(name2);
                        }
                    }
                    V.riverrat.tables.push(table);
                }
            }
            /* initialize table stuff here */
            table.interest = this.rate_table_interest(table);
            if (table.star)
            {
                let all = [...table.people];
                all.delete(table.star);
                table.people = [table.star, ...all];
            }
            table.type = "table";
            table.approval = 0;
            table.impatience = 0;
            table.rounds = 0;
            table.tip = 0;
        }
    }

    V.riverrat.bar = V.riverrat.bar.sort((a, b) => b.interest - a.interest);
    V.riverrat.tables = V.riverrat.tables.sort((a, b) => b.interest - a.interest);
    return [V.riverrat.bar, V.riverrat.tables];
}

setup.ob_riverRat.bar_chance = function(name)
{
    let chance = 0;
    if (setup.people.has_inclination(name, "Insecure"))
        chance += 0.1;
    if (setup.people.has_inclination(name, "Shy"))
        chance += 0.1;
    if (!setup.ob_relationships.in_relationship(name))
        chance += 0.1;

    return chance;
}

setup.ob_riverRat.find_table_match = function(name, others, rng)
{
    let relfreq = [];
    for (let name2 of others)
        if (name != name2)
        {
            let chance = setup.people.npc_association_factor(name, name2);
            if (chance > 0.4)
                relfreq.push(name2, Math.floor(1000 * chance));
        }
    return rng.randomrelfreq(relfreq);
}

setup.ob_riverRat.individual_interest = function(p)
{
    let interest = 0;
    if (setup.ob_relationships.partner(p) == "PC")
        interest += 1000;
    else if (V.crush == p)
        interest += 800;
    else if (setup.people.mutual_attraction(p))
        interest += 600;
    else if (setup.people.pc_attracted_to(p))
        interest += 300;
    else if (setup.ob_relationships.relationship_with(p))
        interest += 200;

    // todo maybe: other factors... like: is professor, classmate, coworker

    let turnon = setup.people.pc_attracted_to(p) ? setup.people.pc_turnon_factor(p) : 0;
    if (turnon == 2)
        interest += 400;
    else if (turnon == 1)
        interest += 200;

    if (V.riverrat.served && V.riverrat.served.includes(p)) // reduce the chances of obvious repeats
        interest /= 10;

    return interest;
}

setup.ob_riverRat.rate_table_interest = function(table)
{
    let total = 0;
    let topperson = null;
    let topinterest = -1;
    for (let p of table.people)
    {
        let interest = this.individual_interest(p);
        total += interest;

        if (interest > topinterest)
        {
            topinterest = interest;
            topperson = p;
        }
    }
    table.star = topperson;
    return Math.floor(total / table.people.length) + (25 * table.people.length);
}

setup.ob_riverRat.featured_tables = function(count = setup.ob_riverRat.number_of_worked_tables())
{
    count = Math.min(count, V.riverrat.tables.length);
    let tables = V.riverrat.tables.slice(0, count);
    return tables;
}

setup.ob_riverRat.init_tables = function()
{
    let anynew = false;
    let featured = this.featured_tables();
    for (let table of V.riverrat.tables)
        if (featured.includes(table))
        {
            table.featured = true;
            table.status = setup.ob_randomrelfreq(["new", 40, "pending", 20, "active", 20, "clearing", 10]);
            if (table.status == "new") anynew = true;
            table.laststatuschange = [V.gameday, V.hour, V.minute - setup.rir(0, 5)];
        }

    if (!anynew)
    {
        for (let table of V.riverrat.tables)
            if (table.featured && table.status != "new")
            {
                table.status = "new";
                break;
            }
    }
    let maxcount = setup.ob_riverRat.number_of_worked_tables();
    while (V.riverrat.tables.length < maxcount)
    {
        let table = {people: [], status: "empty"};
        table.featured = true;
        table.interest = 0;
        table.type = "table";
        table.approval = 0;
        table.impatience = 0;
        table.rounds = 0;
        table.tip = 0;
        V.riverrat.tables.push(table);
    }
    return V.riverrat.tables;
}

setup.ob_riverRat.init_barseats = function()
{
    let anynew = false;
    for (let seat of V.riverrat.bar)
    {
        seat.status = setup.ob_randomrelfreq(["new", 40, "active", 20, "clearing", 10]);
        if (seat.status == "new") anynew = true;
        seat.laststatuschange = [V.gameday, V.hour, V.minute - setup.rir(0, 5)];
    }

    if (!anynew)
    {
        for (let seat of V.riverrat.bar)
            if (seat.featured && seat.status != "new")
            {
                seat.status = "new";
                break;
            }
    }
    return V.riverrat.bar;
}

setup.ob_riverRat.number_of_worked_tables = function()
{
    return setup.ob_riverRat.jobs[V.riverrat.jobtitle].tables || 2;
}

setup.ob_riverRat.table_waiting_time = function(table, actual = false)
{
    // how many minutes since this table's last status change

    let day = table.laststatuschange[0];
    let hour = table.laststatuschange[1];
    let minute = table.laststatuschange[2];

    let tableminssincemidnight = (hour * 60) + minute;
    let currentminssincemidnight = (V.hour * 60) + (V.minute);

    if (V.gameday > day)
        currentminssincemidnight += 24 * 60;

    let wait = currentminssincemidnight - tableminssincemidnight;

    if (!actual && table.status == "pending") // pending orders get some leeway
        return Math.max(wait - 10, 0);
    else
        return wait;
}
setup.ob_riverRat.bar_waiting_time = setup.ob_riverRat.table_waiting_time;

setup.ob_riverRat.maybe_ask_another_round = function()
{
    let time = 60 - V.riverrat.roundtimepassed;
    if (time < 30) return; // helps keep timing consistent... now that other rounds are mostly deliberately built in
    for (let table of V.riverrat.tables)
        if (table.featured)
        {
            if (table.status == "active" && (this.table_waiting_time(table) >= 15 || table.forceanotherround))
            {
                delete table.forceanotherround;
                if (this.table_waiting_time(table) >= 30)
                    continue;
                else if (this.table_waiting_time(table) >= 20)
                    if (State.random() < 0.5) this.another_round(table);
                else if (this.table_waiting_time(table) >= 15)
                    if (State.random() < 0.25) this.another_round(table);
            }
            else if (table.status == "another round" && this.table_waiting_time(table) >= 15)
            {
                this.add_impatience(table, 250);
                table.status = "active";
            }
        }

    let performance = 0;
    let count = 0;
    for (let seat of V.riverrat.bar)
    {
        if (seat.status == "active" && this.bar_waiting_time(seat) >= 15)
        {
            if (this.bar_waiting_time(seat) >= 30 || seat.rounds >= 2)
            {
                performance += this.clear_barseat(seat);
                count++;
            }
            else if (this.bar_waiting_time(seat) >= 20)
                if (State.random() < 0.5)
                {
                    this.another_round(seat);
                }
                else if (State.random() < 0.25)
                {
                    performance += this.clear_barseat(seat);
                    count++;
                }
            else if (this.bar_waiting_time(seat) >= 15)
                if (State.random() < 0.25)
                {
                    this.another_round(seat);
                }
                else if (State.random() < 0.25)
                {
                    performance += this.clear_barseat(seat);
                    count++;
                }
        }
        else if (seat.status == "another round" && this.bar_waiting_time(seat) >= 15)
        {
            this.add_impatience(seat, 250);
            performance += this.clear_barseat(seat);
            count++;
        }
    }
    if (count)
    {
        performance /= count;
        this.change_performance(performance);
    }
}

setup.ob_riverRat.advance_to_another_round = function(set = false)
{
    let time = 60 - V.riverrat.roundtimepassed;
    if (time >= 30)
    {
        if (V.riverrat.job == "server")
        {
            for (let table of V.riverrat.tables)
            {
                if (table.status == "active" && table.rounds <= 1)
                {
                    if (set) this.another_round(table);
                    return true;
                }
            }
        }
        else
        {
            for (let seat of V.riverrat.bar)
            {
                if (seat.status == "active" && seat.rounds <= 1)
                {
                    if (set) this.another_round(seat);
                    return true;
                }
            }
        }
    }
}

setup.ob_riverRat.only_empty_or_clearing = function()
{
    // all featured tables or bar seats are status empty or clearing
    if (V.riverrat.job == "server")
    {
        for (let table of V.riverrat.tables)
        {
            if (table.featured && table.status != "clearing" && table.status != "empty" && table.status != "cleared")
                return false;
        }
        return true;
    }
    else
    {
        for (let seat of V.riverrat.bar)
        {
            seat = this.reference(seat);
            if (seat.status != "clearing" && seat.status != "empty" && seat.status != "cleared")
                return false;
        }
        return true;
    }
}

setup.ob_riverRat.can_seat_new_table = function()
{
    // returns true if all tables are empty or clearing and there is a table with people to replace one with
    let time = 60 - V.riverrat.roundtimepassed;
    if (time < 30 || !this.only_empty_or_clearing()) return false;
    for (let table of V.riverrat.tables)
        if (table.featured && (table.status == "empty" || table.status == "cleared" || table.status == "clearing"))
        {
            for (let table2 of V.riverrat.tables)
                if (!table2.featured && table2.people.length > 0)
                {
                    return true;
                }
        }
    return false;
}

setup.ob_riverRat.seat_new_table = function()
{
    // actually do the above
    // (similar method as advance_tables, but only one)
    for (let table of V.riverrat.tables)
        if (table.featured && V.riverrat.job == "server")
        {
            if ((table.status == "empty" || table.status == "cleared" || table.status == "clearing"))
            {
                // we include clearing status here for consistency but all tables should be cleared before this is run (otherwise tips vanish)
                for (let table2 of V.riverrat.tables)
                    if (!table2.featured && table2.people.length > 0)
                    {
                        table.people = [...table2.people];
                        table.star = table2.star;
                        table.status = "new";
                        table.laststatuschange = [V.gameday, V.hour, V.minute];
                        table.rounds = table2.rounds;
                        table.tip = table2.tip || 0;
                        table.impatience = table2.impatience;
                        table.interest = table2.interest;

                        table2.people = [];
                        table2.star = null;
                        table2.status = "empty";
                        table2.rounds = 0;
                        table2.tip = 0;
                        table.approval = 0;
                        table2.impatience = 0;
                        table2.interest = 0;
                        return;
                    }
            }
        }
}

setup.ob_riverRat.force_another_round = function()
{
    if (V.riverrat.job == "server")
    {
        for (let table of setup.ob_shuffle([...V.riverrat.tables]))
        {
            table = this.reference(table);
            if (table.status == "active" && table.rounds <= 1)
            {
                this.another_round(table);
                return table;
            }
        }
    }
    else
    {
        for (let seat of setup.ob_shuffle([...V.riverrat.bar]))
        {
            seat = this.reference(seat);
            if (seat.status == "active" && seat.rounds <= 1)
            {
                this.another_round(seat);
                return true;
            }
        }
    }
}

setup.ob_riverRat.clear_barseat = function(seat)
{
    let performance = 0;

    if (seat.status == "active" || seat.status == "another round")
    {
        seat.status = "clearing";
        if (seat.notip) seat.tip = 0;
        else seat.tip += this.tip_amount(seat);
        if (seat.tip)
            performance += setup.ob_riverRat.performance_amount(seat);
    }
    else
    {
        seat.status = "empty";
    }
    seat.rounds = 0;
    seat.approval = 0;
    seat.impatience = 0;
    seat.interest = 0;
    delete seat.person;
    delete seat.forceanotherround;

    return performance;
}

setup.ob_riverRat.another_round = function(table)
{
    table.laststatuschange = [V.gameday, V.hour, V.minute];
    table.rounds++;
    table.status = "another round";
}

setup.ob_riverRat.advance_tables = function()
{
    // if a table is empty, move somebody else into it
    // (for the start of a new shift round)

    let closed = setup.ob_is_closed("RiverRat");

    // keep track of bar people and featured table people
    let alreadyhere = [];
    let bar = [...V.riverrat.bar];
    let barpeople = bar.map(seat => seat.person);
    alreadyhere = [...barpeople];
    let featuredtables = [];
    for (let table of V.riverrat.tables)
    {
        if (table.featured)
        {
            featuredtables.push(table);
        }
        alreadyhere = [...alreadyhere, ...table.people];
        delete table.forceanotherround;
    }

    // recalculate people here
    V.peopleatlocation = setup.ob_people_at_location();

    // whoever was at the bar and is still here should remain at the bar
    // and if they left, we'll find new people to fill in
    for (let p of alreadyhere.reverse())
        if (barpeople.includes(p))
        {
            if (!V.peopleatlocation.includes(p))
            {
                for (let seat of bar)
                    if (seat.person == p)
                    {
                        this.clear_barseat(seat);
                        break;
                    }
            }
        }
        else if (!V.peopleatlocation.includes(p))
        {
            // anybody still at a featured table, sort them back into peopleatlocation
            V.peopleatlocation.unshift(p);
        }

    // rebuild bar and table people lists
    this.sort_customers(alreadyhere);

    // place saved bar people back at the bar
    for (let p of bar.reverse())
        V.riverrat.bar.unshift(p);

    // delete barseats that aren't relevant or exceed bar size
    let barcount = 0;
    for (let bar of V.riverrat.bar)
    {
        if (!bar.person && !bar.tip)
            V.riverrat.bar.delete(bar);
        else if (barcount > this.barsize && !bar.tip)
            V.riverrat.bar.delete(bar);
        else
            barcount++;
    }

    // sort featured tables back in at the beginning of the array
    for (let table of featuredtables.reverse())
        if (!V.riverrat.tables.includes(table))
            V.riverrat.tables.unshift(table);

    // replace any empty featured tables with a populated table
    let featuredcount = 0;
    let performance = 0;
    let perfchangecount = 0;
    for (let table of V.riverrat.tables)
        if (table.featured && V.riverrat.job == "server")
        {
            if ((table.status == "empty" || table.status == "cleared") && !closed)
            {
                for (let table2 of V.riverrat.tables)
                    if (!table2.featured && table2.people.length > 0)
                    {
                        table.people = [...table2.people];
                        table.star = table2.star;
                        table.status = "new";
                        table.laststatuschange = [V.gameday, V.hour, V.minute];
                        table.rounds = table2.rounds;
                        table.tip = table2.tip || 0;
                        table.impatience = table2.impatience;
                        table.interest = table2.interest;

                        table2.people = [];
                        table2.star = null;
                        table2.status = "empty";
                        table2.rounds = 0;
                        table2.tip = 0;
                        table.approval = 0;
                        table2.impatience = 0;
                        table2.interest = 0;
                        break;
                    }
            }
            else if (table.status == "active")
            {
                perfchangecount++;
                table.status = "clearing";
                if (table.notip) table.tip = 0;
                else table.tip += this.tip_amount(table);
                if (table.tip)
                    performance += setup.ob_riverRat.performance_amount(table);
            }
            else if (table.status == "another round")
            {
                // wanted another round, but were ignored
                perfchangecount++;
                this.add_impatience(table, 500);
                table.status = "clearing";
                performance -= 1;
                if (table.notip) table.tip = 0;
                else table.tip += this.tip_amount(table);
            }
            featuredcount++;
        }

    if (perfchangecount)
    {
        performance /= perfchangecount;
        this.change_performance(performance);
    }

    // delete any empty non-featured tables, they're just clutter at this point
    for (let table of [...V.riverrat.tables].reverse())
        if (!table.featured && table.people.length == 0)
            V.riverrat.tables.delete(table);

    if (featuredcount < this.number_of_worked_tables() && !closed)
    {
        for (let table of V.riverrat.tables)
            if (!table.featured && table.people.length > 0)
            { // new table
                table.featured = true;
                table.laststatuschange = [V.gameday, V.hour, V.minute - setup.rir(0, 5)];
                table.status = "new";
                featuredcount++;
                if (featuredcount >= this.number_of_worked_tables())
                    break;
            }
    }

    let seatcount = 0;
    for (let seat of V.riverrat.bar)
    {
        delete seat.forceanotherround;
        if (!seat.status || seat.status == "empty" || !seat.person)
        { // new bar customer
            if (!closed)
            {
                seat.laststatuschange = [V.gameday, V.hour, V.minute - setup.rir(0, 5)];
                seat.status = "new";
            }
            else
            {
                this.clear_barseat(seat);
            }
        }
        else if (seat.status == "another round" || seat.status == "new")
        {
            seatcount++;
            this.add_impatience(seat, 500);
            performance -= 1;
            seat.status = "clearing";
            if (seat.notip) seat.tip = 0;
            else seat.tip += this.tip_amount(seat);
        }
        else if (seat.status == "active")
        {
            seatcount++;
            seat.status = "clearing";
            if (seat.notip) seat.tip = 0;
            else seat.tip += this.tip_amount(seat);

            if (seat.tip)
                performance += setup.ob_riverRat.performance_amount(seat);
        }
    }
    if (V.riverrat.job == "bartender" && seatcount)
    {
        performance /= seatcount;
        this.change_performance(performance);
    }
}

setup.ob_riverRat.return_clothes = function(clothes)
{
    if (!clothes) return;
    for (let item of clothes)
    {
        if (item.type == "table" || item.type == "bar") continue; // an already-fixed bug that persisted into a save i was testing
        V.pc.get_storage_location("dormcloset").push(item);
    }
}

setup.ob_riverRat.change_performance = function(amt)
{
    if (V.riverrat.performance == undefined) V.riverrat.performance = 0;
    V.riverrat.performance += amt * V.optriverratperfmult;
    V.riverrat.performance = Math.clamp(V.riverrat.performance, 0, 1000);
}

setup.ob_riverRat.tip_amount = function(table)
{
    // determine the base tip amount (doesn't include extra tips earned through events, but is often indirectly influenced by their outcomes)
    // based on table mood and satisfaction

    let base = table.type == "table" ? Math.clamp(3 * table.people.length, 5, 10) : 7;
    let star = table.type == "table" ? table.star : table.person;
    if (this.is_impatient(table))
    {
        if (this.is_impressed(table))
        {
            base *= 1.2;
        }
        else if (this.is_mildly_impressed(table))
        {
            base *= 1.1;
        }
        else
        {
            base *= 0.5;
        }
    }
    else if (this.is_impressed(table))
    {
        base *= 1.5;
    }
    else if (this.is_mildly_impressed(table))
    {
        base *= 1.25;
    }

    let attitude = this.table_reaction_type(table);
    if (["enemy", "angry"].includes(attitude))
    {
        if (State.random() < 0.5)
            return 0;
        else
            base *= 0.5;
    }
    else if (attitude == "mean flirt")
    {
        if (this.is_impressed(table))
            base *= 1.25;
        else if (this.is_mildly_impressed(table))
            base *= 1.1;
        else
            base *= 0.667;
    }
    else if (["partner", "friend"].includes(attitude))
    {
        base *= 1.25;
    }
    else if (["friendly", "friendly flirt"].includes(attitude))
    {
        base *= 1.1;
    }

