// #region methods

setup.ob_clickbaitTV.info = function(segment)
{
    return this.segments[segment];
}

setup.ob_clickbaitTV.equipment = function()
{
    const categoryitems = ["microphone", "camera", "overhead camera"];
    const individualitems = ["hot plate"];

    const retval = [];

    if (setup.ob_computer())
    {
        for (let pos of categoryitems)
            if (setup.ob_locationInventory.category_item(setup.ob_locationInventory.myloc(), pos))
                retval.push(pos);
    }

    if (V.pc.has_phone())
    {
        if (!retval.includes("microphone")) retval.push("microphone");
        if (!retval.includes("camera")) retval.push("camera");
    }

    for (let pos of individualitems)
        if (setup.ob_locationInventory.has(setup.ob_locationInventory.myloc(), pos))
            retval.push(pos);

    return retval;
}

setup.ob_clickbaitTV.available_videotypes = function()
{
    return Object.keys(this.videotypes).filter(type => this.equipment().includesAll(this.videotypes[type].equipment) && (!this.videotypes[type].needcomputer || setup.ob_computer()));
}

setup.ob_clickbaitTV.resolve_segment = function(segment)
{
    const info = this.info(segment);
    let critsuccess = info.success;
    let critfailure = info.failure;

    let success = true;
    let fail = false;

    for (const [skill, lvl] of Object.entries(info.skillcheck))
    {
        if (!V.pc.skillcheck(skill, lvl * 2))
        {
            success = false;
        }
        else
        {
            V.pc.raise_skill(skill, lvl * 2);
        }
        if (!V.pc.skillcheck(skill, lvl))
        {
            fail = true;
        }
        else
        {
            V.pc.raise_skill(skill, lvl);
        }
    }

    if (fail)
    {
        return critfailure;
    }
    else if (success)
    {
        return critsuccess;
    }
    else
    {
        return segment;
    }
}

setup.ob_clickbaitTV.pick_happenstance = function(videotype, exclude = [])
{
    let possible = [];
    for (let pos of Object.keys(this.segments).filter(seg =>
        this.segments[seg].type == "happenstance" &&
        (!this.segments[seg].videotypes || this.segments[seg].videotypes.includes(videotype)) &&
        (!this.segments[seg].checkvar || Scripting.evalTwineScript(this.segments[seg].checkvar)) &&
        (!this.segments[seg].equipment || this.equipment().includesAll(this.segments[seg].equipment)) &&
        State.random() < this.segments[seg].frequency
    ))
    {
        if (!exclude.includes(pos))
            possible.push(pos);
    }

    return setup.ob_randel(possible);
}

setup.ob_clickbaitTV.get_segments = function(video)
{
    const retval = [];
    retval.push(video.intro);
    retval.push(video.body);
    if (video.happenstance)
        retval.push(...video.happenstance);
    retval.push(video.outro);
    return retval;
}

setup.ob_clickbaitTV.video_rating = function(video)
{
    let totalrating = 0;
    let ratings = 0;

    let videotype = video.videotype;
    const videoinfo = this.videotypes[videotype];

    for (let seg of this.get_segments(video))
    {
        const info = this.info(seg);
        let character = info.character;

        let mult = (videoinfo.characters[character] || 1) * (info.multiplier || 1);

        let rating = Math.round(1000 * mult);

        if (info.type == "body")
        {
            totalrating += rating * 3;
            ratings += 3;
        }
        else
        {
            totalrating += rating;
            ratings++;
        }
    }

    return Math.clamp(Math.round(totalrating / ratings), 0, 1200);
}

setup.ob_clickbaitTV.base_views = function(video)
{
    let pop = setup.ob_streaming.popularity("ClickbaitTV");
    let rating = this.video_rating(video);

    let base = Math.min(rating, Math.round(pop * 1.2));

    let mult = 0.8 + (0.4 * State.random());

    return Math.max(Math.round(base * mult), Math.round(4 + 6 * State.random()));
}

setup.ob_clickbaitTV.views_today = function(video)
{
    let dayssince = V.gameday - video.dayposted;
    let decay = Math.pow(dayssince + 1, -0.5);

    let baseviews = this.base_views(video);

    if (video.viral)
        baseviews *= 5;

    let postedonday = this.videos_posted_on_day(video.dayposted);
    if (postedonday > 2)
    {
        baseviews *= (2 + (1 - Math.pow(0.5, postedonday - 2))) / postedonday;
    }

    return Math.round(baseviews * decay);
}

setup.ob_clickbaitTV.money_today = function(video, views)
{
    if (video.demonetized) return 0;

    return setup.ob_adjust_income(Math.round(Math.max(views / 50.0, 1 + 9 * State.random())), "streaming");
}

setup.ob_clickbaitTV.popularity_today = function(video)
{
    let views = this.views_today(video);
    return Math.round(views / 100.0) + setup.ob_randel([2, 3, 4, 5, 5, 5, 6, 6, 6, 7, 7, 8, 8, 9, 10]);
}

setup.ob_clickbaitTV.add_video = function(video)
{
    if (!V.streaming.videos) V.streaming.videos = [];

    video.views = 0;
    video.money = 0;
    video.dayposted = V.gameday;

    let quality = this.video_rating(video);
    if (quality < 500)
        video.virality = 0;
    else if (quality >= 1000)
        video.virality = 0.1;
    else if (quality >= 900)
        video.virality = 0.05;
    else if (quality >= 800)
        video.virality = 0.025;
    else if (quality >= 700)
        video.virality = 0.015;
    else if (quality >= 600)
        video.virality = 0.01;
    else
        video.virality = 0.001;

    V.streaming.videos.push(video);
}

setup.ob_clickbaitTV.demonetization_chance = function(video)
{
    let chance = 0;
    for (let seg of this.get_segments(video))
        if (seg.demonetization)
            chance += seg.demonetization;

    return chance;
}

setup.ob_clickbaitTV.removal_chance = function(video)
{
    let chance = 0;
    for (let seg of this.get_segments(video))
        if (seg.removal)
            chance += seg.removal;

    return chance;
}

setup.ob_clickbaitTV.videos_posted_on_day = function(day)
{
    let count = 0;
    for (let video of V.streaming.videos)
    {
        if (video.dayposted == day)
            count++;
    }
    return count;
}

setup.ob_clickbaitTV.daily_tick = function()
{
    if (!V.streaming || !V.streaming.videos) return;

    V.streaming.ctvprevpopularity = setup.ob_streaming.popularity("ClickbaitTV");

    const remove = [];
    for (let video of V.streaming.videos)
    {
        let dayssince = V.gameday - video.dayposted;
        if (dayssince > 15)
        {
            remove.push(video);
        }
        else if (dayssince > 7)
        {
            video.remove = true;
        }
        else
        {
            if (!V.streaming.videomoney) V.streaming.videomoney = 0;

            let newviews = this.views_today(video);
            let newmoney = this.money_today(video, newviews);

            if (!video.demonetized)
            {
                let chance = this.demonetization_chance(video);
                if (State.random() < chance)
                {
                    video.demonetized = true;
                    newmoney = 0;
                }
            }
            if (!video.removed)
            {
                let chance = this.removal_chance(video);
                if (State.random() < chance)
                {
                    video.removed = true;
                    newmoney = 0;
                    newviews = 0;
                }
            }

            if (!video.removed && !video.demonetized && video.virality && !video.viral && V.gameday - setup.ob_streaming.last_viral("ClickbaitTV") >= 7 && setup.ob_streaming.popularity("ClickbaitTV") >= 100)
            {
                if (dayssince <= 3)
                {
                    let viralchance = [0, video.virality / 2, video.virality, video.virality / 2][dayssince];
                    if (State.random() < viralchance)
                    {
                        video.viral = true;
                        setup.ob_streaming.gone_viral("ClickbaitTV");
                    }
                }
            }

            video.newviews = newviews;
            video.newmoney = newmoney;
            video.views += newviews;
            video.money += newmoney;

            V.streaming.videomoney += newmoney;

            if (!video.removed)
            {
                let newpop = this.popularity_today(video);
                setup.ob_streaming.add_popularity("ClickbaitTV", newpop);
            }
        }
    }

    for (let video of remove)
        V.streaming.videos.delete(video);
}
