setup.ob_findr = {};

setup.ob_findr.username = function(name)
{
    name = setup.people.get_name(name);
    let rng = setup.ob_newRNG(name + "findr")
    let rand = rng.random();
    if (rand < 0.3)
        return setup.people.nickname(name);
    else if (rand < 0.6)
        return setup.people.firstname(name) + setup.people.lastname(name)[0];
    else
        return rng.randomchoice(setup.ob_names.usernames);
}

setup.ob_findr.uses = function(name)
{
    // whether this npc uses findr at all

    const disallowedtypes = ["outsider", "faculty"];
    if (disallowedtypes.includes(setup.people.get_type(name))) return false;

    if (!setup.people.allow_free_interaction(name)) return false;

    if (setup.ob_relationships.in_exclusive_relationship(name) && !setup.people.has_inclination(name, "Cheater")) return false;

    if (setup.people.has_any_inclination(name, "slut")) return true;

    let rng = setup.ob_newRNG(name + "findr")
    let rand = rng.random();

    if (setup.people.get_age(name) >= 35) rand *= 2;

    if (setup.people.has_any_inclination(name, "casualsex")) return rand < 0.8;
    else if (setup.people.has_any_inclination(name, "shyaboutsex")) return rand < 0.02;

    return rand < 0.4;
}

setup.ob_findr.on_now = function(name)
{
    // whether this npc is on findr at the present moment

    if (!this.uses(name)) return false;

    if (!setup.people.mutual_attraction(name)) return false; // they might be on but we don't care

    let rng = setup.ob_newRNG(name + "findr" + V.day + V.hour);
    if (V.hour > 18 || V.hour < 3)
        return rng.random() < 0.08;
    else if (V.hour < 12)
        return rng.random() < 0.01;
    else
        return rng.random() < 0.04;
}

setup.ob_findr.people_on = function()
{
    // all npcs currently on findr

    const retval = [];
    for (const p of Object.keys(V.people))
        if (this.on_now(p))
            retval.push(p);

    return retval;
}

setup.ob_findr.likes_tags = function(name, tags)
{
    // whether the npc likes these tags

    if (tags.includes("Poly"))
    {
        if (setup.people.has_inclination(name, "Polyamorous")) return true;
    }
    if (tags.includes("Open"))
    {
        if (setup.people.has_inclination(name, "Open Relationships")) return true;
    }
    if (tags.includes("Hookups"))
    {
        //if (setup.people.has_any_inclination(name, "romantic")) return false;
        if (setup.people.has_any_inclination(name, "casualsex")) return true;
    }
    if (tags.includes("Romance"))
    {
        //if (setup.people.has_any_inclination(name, "nodating")) return false;
        if (setup.people.has_any_inclination(name, "romantic")) return true;
    }
    if (tags.includes("Dominant"))
    {
        if (setup.people.has_any_inclination(name, "submissive")) return true;
        //if (setup.people.has_any_inclination(name, "just_dominant")) return false;
    }
    if (tags.includes("Submissive"))
    {
        //if (setup.people.has_any_inclination(name, "just_submissive")) return false;
        if (setup.people.has_any_inclination(name, "dominant")) return true;
    }
    if (tags.includes("Exhibitionist"))
    {
        if (setup.people.has_any_inclination(name, "voyeur")) return true;
    }
    if (tags.includes("Voyeur"))
    {
        if (setup.people.has_any_inclination(name, "basic_exhibitionist")) return true;
    }
    return false;
}

setup.ob_findr.likes = function(name)
{
    // whether the npc likes the pc's profile

    if (!this.likes_tags(name, V.findr.tags)) return false;

    if (setup.people.is_known(name) && setup.ob_relationships.in_exclusive_relationship(name))
    {
        return false;
    }
    if (setup.people.npc_turnon_factor(name) >= 0 && setup.people.get_attitude(name, "lust") < 100)
        setup.people.set_attitude(name, "lust", 100);
    return setup.people.willing_date(name) || setup.people.willing_sex(name);
}

setup.ob_findr.npc_tags = function(name)
{
    // the npc's findr tags

    const tags = [];

    let rng = setup.ob_newRNG(name + "findr")

    if (setup.people.has_inclination(name, "Open Relationships"))
    {
        tags.push("Open");
    }
    if (setup.people.has_inclination(name, "Polyamorous"))
    {
        tags.push("Poly");
    }

    if (setup.people.has_any_inclination(name, "romantic"))
    {
        tags.push("Romance");
    }
    else if (setup.people.has_any_inclination(name, "casualsex"))
    {
        tags.push("Hookups");
    }
    else if (setup.people.has_any_inclination(name, "forward") && rng.random() < 0.7)
    {
        tags.push("Hookups");
    }
    else if (rng.random() < 0.4)
    {
        tags.push("Romance");
    }

    if (setup.people.has_any_inclination(name, "just_dominant")) tags.push("Dominant");

    if (setup.people.has_any_inclination(name, "just_submissive")) tags.push("Submissive");

    if (setup.people.has_any_inclination(name, "basic_exhibitionist")) tags.push("Exhibitionist");

    if (setup.people.has_any_inclination(name, "basic_voyeur")) tags.push("Voyeur");

    return tags;
}

setup.ob_findr.get_new_match = function()
{
    let possible = [];
    for (let p of this.people_on())
        if (!V.findr.liked.includes(p) && !V.findr.disliked.includes(p))
            possible.push(p);
    return setup.ob_randel(possible);
}
