setup.ob_thrift.MAX_DAYS_IN_THRIFT = 8;
setup.ob_thrift.STARTING_DISCOUNT = 0.5;
setup.ob_thrift.DAYS_PER_DISCOUNT_STEP = 1;
setup.ob_thrift.DISCOUNT_STEP = 0.1;
setup.ob_thrift.MAX_DISCOUNT = 0.9;
setup.ob_thrift.MIN_PRICE = 1;

setup.ob_thrift.update_items = function()
{
    //console.log("Thrift Update! Day "+V.gameday);
    // Get the contents of the thrift location
    // determine if any of the items have been taken (based on age)
    // populate new items up to random max number (10-15?)
    let current_thrift = V.pc.get_storage_location("thriftshop");

    // check everything in the thrift laundry and move it into inventory if appropriate
    let thrift_laundry = V.pc.get_storage_location("thriftlaundry");
    let transfer_list = []
    for (const lItem of thrift_laundry)
    {
        let laundry_day = lItem.get_property("Thrift Laundry") || 0;
        if (laundry_day < V.gameday)
        {
            //console.log(lItem.get_name()+" is now clean!",laundry_day);
            lItem.delete_property("stains");
            lItem.delete_property("Thrift Laundry");
            transfer_list.push(lItem);
        }
    }
    for (const lItem of transfer_list)
    {
        thrift_laundry.transfer_item_to(lItem,current_thrift);
    }

    const current_time = ((V.gameday*24 + V.hour)*60 + V.minute);
    let remove_list = [];
    for (const cItem of current_thrift)
    {
        // Convert to "Thrift Sale"
        let thrift_time = cItem.get_property("Thrift Time");
        if (!thrift_time || thrift_time > current_time)
        {
            thrift_time = Math.max(0,current_time - setup.rir(0,setup.ob_thrift.MAX_DAYS_IN_THRIFT*24*60));
            cItem.set_property("Thrift Time",thrift_time);
            cItem.delete_property("Thrift Day");
            cItem.delete_property("Thrift Minute");
        }

        let exit_time = cItem.get_property("Thrift Exit");
        if (!exit_time)
        {
            // Exit some time up to 14 days in the future
            exit_time = thrift_time + setup.rir(0,setup.ob_thrift.MAX_DAYS_IN_THRIFT*24*60);
            cItem.set_property("Thrift Exit",exit_time);
        }

        if (exit_time < current_time)
        {
            remove_list.push(cItem);
        }
        else
        {
            let days_in_thrift = Math.floor((current_time - thrift_time)/(60*24));
            let additional_discount = Math.floor(days_in_thrift/setup.ob_thrift.DAYS_PER_DISCOUNT_STEP)*setup.ob_thrift.DISCOUNT_STEP;
            let discount = setup.ob_thrift.STARTING_DISCOUNT + additional_discount;
            // max discount 90%
            discount = Math.min(discount, setup.ob_thrift.MAX_DISCOUNT);
            let discounted_price = Math.max(setup.ob_thrift.MIN_PRICE, Math.floor(cItem.get_archetype_prop("price") * (1 - discount)))
            cItem.set_property("Thrift Price", discounted_price);
        }
    }
    for (const rItem of remove_list)
    {
        current_thrift.remove(rItem);
    }
    let RNG = setup.ob_newRNG();
    let thrift_size = RNG.rir(10,16);

    //console.log("Populating to "+thrift_size+" items.");
    thrift_size = Math.max(0, thrift_size-current_thrift.get_item_count())
    //console.log("Adding "+thrift_size+" items.");
    for (let i = 0; i < thrift_size; i++)
    {
        //console.log("Item ",i);
        let cItem_name = RNG.randomchoice(Object.keys(setup.clothes))
        //console.log("Selected item: ",cItem_name);
        if (typeof(setup.clothes[cItem_name]) != 'function')
        {
            let cItem = new ClothingItem(cItem_name);
            if ((current_thrift.find_item_idx(cItem) == -1) && !cItem.get_archetype_prop("temporary"))
            {
                cItem.add_sub_prefixes(["thrift","sub","ubook"]);

                let sub_info = cItem.get_subs();
                let sub_selections = {}
                for (const [sub_name,sub_values] of Object.entries(sub_info))
                {
                    sub_selections[sub_name] = RNG.randomchoice(sub_values);
                }
                cItem.set_subs(sub_selections);
                //console.log("Item "+i+": "+setup.ob_capitalize(cItem.get_name())+".")
                // Exit some time up to 14 days in the future
                let exit_time = current_time + RNG.rir(0,setup.ob_thrift.MAX_DAYS_IN_THRIFT*24*60);
                cItem.set_property("Thrift Time",current_time);
                cItem.set_property("Thrift Exit",exit_time);
                cItem.set_property("Thrift Price",Math.max(Math.floor(cItem.get_archetype_prop("price")*setup.ob_thrift.STARTING_DISCOUNT), 1));

                setup.ob_thrift.maybe_stain(cItem);

                //console.log(cItem);
                current_thrift.add(cItem);
            }
        }
    }
    return current_thrift;
}

setup.ob_thrift.can_purchase = function(cItem, price)
{
    //console.log("Thrift can_purchase", cItem, price);
    let retval = {};
    if (setup.pc().already_has_clothing(cItem.get_data_structure()))
    {
        retval.result = false;
        retval.reason = "You already own something exactly like that."
    }
    else if (price > 0 && V.pcmoney < price)
    {
        retval.result = false;
        retval.reason = "You don't have enough money."
    }
    else
    {
        retval.result = true;
    }
    return retval;
}

setup.ob_thrift.purchase = function(cItem, price, usenow = false)
{
    let retval = "";
    //console.log("Thrift purchase", cItem, price, usenow);

    if (Number.isFinite(price))
        State.setVar("$pcmoney", V.pcmoney - price);
    retval = "You pay $" + price + " for " + setup.ob_a_or_an(cItem.get_name()) + " " + cItem.get_name();

    cItem.delete_property("Thrift Time");
    cItem.delete_property("Thrift Exit");
    cItem.delete_property("Thrift Price");

    if (usenow)
    {
        // safely wear clothing will put things in the closet if it is not safe to wear them.
        let test = V.pc.safely_wear_clothing(cItem);
        if (test[0])
        {
            // wear it right now!
            retval += " and put it on.";
            var clothing_configuration = cItem.get_configuration_descriptions()
            if (clothing_configuration.length > 0)
            {
                var config_str = setup.ob_and(clothing_configuration)
                config_str = setup.ob_capitalize(config_str)
                retval += "<br>"+config_str+".";
            }
        }
        else if (test[1] == "exposed")
        {
            retval += " and put it on, but after replacing what you were wearing before, you find yourself a bit exposed. You'll just have to change later after all.";
        }
        else if (test[1] == "anonymous")
        {
            retval += " and put it on, but you decide that suddenly pulling on a mask might be taken the wrong way. You'll just have to change later after all.";
        }
    }
    else
    {
        V.pc.get_storage_location("dormcloset").push(cItem); // add to closet so it's available to wear
        retval += " for your dorm room's closet.";
    }
    return retval;
}

// Assumes that it is a clothing item
setup.ob_thrift.maybe_purchase = function(cItem, price, usenow = false)
{
    //console.log("Thrift maybe_purchase!", cItem, price, usenow);
    let check = this.can_purchase(cItem, price);
    //console.log("can purchase result: ",check);
    if (!check.result)
    {
        State.setVar("$shopbuyresult", "<<highlight bad>>" + check.reason + "<</highlight>>");
    }
    else
    {
        let buy = this.purchase(cItem, price, usenow);
        //console.log("purchase result: ", buy);
        State.setVar("$shopbuyresult", "<<highlight cash>>" + buy + "<</highlight>>");
        V.pc.get_storage_location("thriftshop").remove(cItem);``
    }
}

