// returns true if the item was stained
setup.ob_thrift.maybe_stain = function(cItem, force_stain=false)
{
    let result = false;
    if (!setup.ob_clothes_stainless.includes(cItem.get_archetype_prop("category")))
    {
        let stain_percentage = 1;
        let possible_stains = ["sweat","cum","pee","arousal","grass"];

        if (cItem.get_archetype_prop("category") == "underwear")
        {
            // additional 5% chance of stains
            stain_percentage += 5;
        }
        // unless it's medical... :D
        if (cItem.get_archetype_prop("flags").includes("medical"))
        {
            //console.log("Medical Item!")
            // additional 10% chance of stains
            stain_percentage += 10;
            possible_stains.push("blood");
        }
        if (cItem.get_archetype_prop("flags").includes("food service"))
        {
            //console.log("Food Service Item!")
            // additional 10% chance of stains
            stain_percentage += 10;
            possible_stains = possible_stains.concat(["grease","ketchup"]);
        }

        // determine if it should be stained :)
        if (force_stain || (setup.rir(0,100) < stain_percentage))
        {
            let stain_type = setup.ob_randomchoice(possible_stains);
            cItem.set_property("stains",[stain_type]);
            result = true;
            //console.log(cItem.get_name()+" is stained: "+cItem.get_property("stains")[0])
        }
    }
    return result;
}

setup.ob_thrift.to_laundry = function(cItem)
{
    let thrift_laundry = V.pc.get_storage_location("thriftlaundry");
    let current_thrift = V.pc.get_storage_location("thriftshop");
