class BulletinBoard
{
    constructor(object_info)
    {
        this.identifier = "";
        this.bulletins = {}; // bulletins that it is holding since last bulletin board inspection
        this.last_checked = -1; //gameday last time it updated
        this.max_bulletins_shown = 4;   // The max amount of bulletins showed in the preview.
                                        // So either 4 short descriptions or 2 short 1 long or 2 long descriptions.
        setup.ob_revive_class(this,object_info);
    }

    bulletin_tags = ["stallroom", "board", "graffiti"];

    get bulletin_amount(){return Object.keys(this.bulletins).length};

    get_bulletins(){
        return Object.keys(this.bulletins).map((key) => this.bulletins[key])
    }

    get_bulletin_events()
    {
        return this.get_bulletins().map((bulletin) => bulletin.event)
    }

    get_bulletin_events_and_see(){ // get an array of the events of the bulletins and mark the bulletins as seen by the player.
        return this.get_bulletins().map((bulletin) => {
            bulletin.has_seen = true;
            return bulletin.event;
        })
    }

    add_bulletin(bulletin_event, day_added = V.gameday, has_seen = false)
    {
        this.bulletins[bulletin_event.passage] = {event: bulletin_event, "day_added": day_added, "has_seen": has_seen};
        setup.ob_events.register_event(bulletin_event.passage);
    }

    update_bulletins(tags, forced = false)
    {
        const gameday = V.gameday;

        if (this.last_checked == gameday && !forced) return this.bulletins; //already updated today

        this.last_checked = gameday;

        const searched_tags = tags.concat(["bulletin"]);
        const to_exclude = this.bulletin_tags.filter(elem => !tags.includes(elem));

        const current_bulletin_events = setup.ob_events.assemble_set(searched_tags, to_exclude);
        const to_be_added = [];

        for (const event of current_bulletin_events)
        {
            if (!(this.get_bulletin_events().map(old_event => old_event.passage).includes(event.passage))) // event not yet in bulletins list by comparing passages
            {
                to_be_added.push(event);
            }
        }

        for (const old_bulletin of this.get_bulletins())
        {
            const bulletin_event = old_bulletin.event;

            if (current_bulletin_events.map(old_event => old_event.passage == bulletin_event.passage)) // is old bulletin still valid
            {
                if (!("metadata" in bulletin_event && "expire_time" in bulletin_event.metadata)){continue;} // can old bulletin expire, no? skip

                const delta_time = gameday - old_bulletin.day_added;
                const expire_time = bulletin_event.metadata.expire_time;

                if(delta_time > expire_time) // is expired?
                {
                    this.remove_bulletin_by_event(bulletin_event);
                }
            }
            else if (bulletin_event.metadata && bulletin_event.metadata.recheck) // rechecked event conditions and they no longer apply
            {
                this.remove_bulletin_by_event(bulletin_event);
            }
        }
        for (const event of to_be_added)
        {
            this.add_bulletin(event);
        }

        return this.bulletins;
    }

    remove_bulletin_by_event(event) // remove bulletin from the board and register the event in setup.ob_events so when it has a minimum time requirement before being displayed again, it won't be displayed instantly again.
    {
        delete this.bulletins[event.passage];
        setup.ob_events.register_event(event.passage);
        if ("metadata" in event && "unset" in event.metadata)
        {
            for (const variable_name of event.metadata.unset)
            {
                delete V[variable_name];
            }
        }
    }

    remove_bulletin_by_passage(passage) // remove bulletin from the board and register the event in setup.ob_events so when it has a minimum time requirement before being displayed again, it won't be displayed instantly again.
    {
        const event = this.bulletins[passage];
        delete this.bulletins[passage];
        setup.ob_events.register_event(passage);
        if ("metadata" in event && "unset" in event.metadata)
        {
            for (const variable_name of event.metadata.unset)
            {
                delete V[variable_name];
            }
        }
    }

    remove_bulletin(bulletin)
    {
        const event = bulletin.event;
        delete this.bulletins[passage];
        setup.ob_events.register_event(passage);
        if ("metadata" in event && "unset" in event.metadata)
        {
            for (const variable_name of event.metadata.unset)
            {
                delete V[variable_name];
            }
        }
    }

    make_stale()
    {
        this.last_checked = -1;
    }

    get_bulletin_preview(tags) // get the text for the preview of new and old bulletins.
    {
        this.update_bulletins(tags);
        const bulletins = this.get_bulletins();
        const new_bulletins = bulletins.filter(bulletin => !bulletin.has_seen);

        const slots = { // to keep track of bulletin candidates
            shorts: [],
            old_shorts:[],
            get amount_shorts(){return this.shorts.length + this.old_shorts.length},
            longs: [],
            old_longs:[],
            get slots_filled(){return this.amount_shorts + (this.longs.length + this.old_longs.length) * 2}
        }

        const second_choice = []; // potential candidates if no other more suitable exists.

        // fill with events that have short descriptions so as many as possible can be shown
        for (const bulletin of new_bulletins)
        {
            const new_event = bulletin.event;
            if (!("metadata" in new_event)){continue}

            if ("short_text" in new_event.metadata)
            {
                slots.shorts.push(new_event);

            }
            else if("long_text" in new_event.metadata){second_choice.push(new_event)}

            // currently replaced by simplified preview in _create_bulletin_preview
            //if (slots.slots_filled >= this.max_bulletins_shown){break}
        }

        if (slots.slots_filled+2 <= this.max_bulletins_shown) // fill the rest with long description events
        {
            for (const event of second_choice)
            {
                slots.longs.push(event);
                if (this.slots_filled >= max_bulletins_shown){break}
            }
        }

        return this._create_bulletin_preview(slots)
    }

    _create_bulletin_preview(slots) // actually creating the preview text
    {
        if (this.bulletin_amount == 0){return "is nothing of interest."}
        else if (slots.slots_filled == 0 && this.get_bulletins().filter(bulletin => !bulletin.has_seen).length > 0){return "are some ''new things''."}

        // in case of too many new items just display the number
        if (slots.slots_filled > this.max_bulletins_shown)
            return "is a dizzying array of <b>" + slots.slots_filled + " new items</b> in various shapes and sizes.";

        // fill the rest slots with old events
        if (slots.slots_filled < this.max_bulletins_shown){

            const old_bulletins = this.get_bulletins().filter(bulletin => bulletin.has_seen)

            for (const bulletin of old_bulletins)
            {
                const event = bulletin.event;

                if ("metadata" in event)
                {
                    if ("short_text" in event.metadata) // fill with short texts of old bulletins. shorts are alway prefered over longs, but not as strictly for old bulletins
                    {
                        slots.old_shorts.push(event);
                    }
                    else if(slots.slots_filled + 2 <= this.max_bulletins_shown && "long_text" in event.metadata) // if it has space for a long when the bulletin has no short text.
                    {
                        slots.old_longs.push(event)
                    }
                }

                if (slots.slots_filled >= this.max_bulletins_shown){break}
            }
        }

        // expand shorts to longs if possible
        if (slots.slots_filled < this.max_bulletins_shown)
        {
            let how_many_long_possible = this.max_bulletins_shown - slots.slots_filled;

            while (how_many_long_possible > 0 && slots.amount_shorts > 0)
            {
                if (slots.shorts.length > 0 && "long_text" in slots.shorts[0].metadata)
                {
                    slots.longs.push(slots.shorts.shift())
                }
                else if(slots.old_shorts.length > 0  && "long_text" in slots.old_shorts[0].metadata)
                {
                    slots.old_longs.push(slots.old_shorts.shift())
                }
                else
                {
                    // cycle shorts when the top ones don't have long text
                    if (slots.shorts.length > 0) slots.shorts.push(slots.shorts.shift());
                    if (slots.old_shorts.length > 0) slots.old_shorts.push(slots.old_shorts.shift());
                    // decrease the how many long possible anyway to not get an infinite loop at the cost of less fancy preview text
                }
                how_many_long_possible -= 1;
            }
        }

        //Text displayed in the passage should be in the format of: On the board ... Written onto the wall ...
        let result = "";
        let short_filled = 0; // units of bulletin text inserted into result. Short_text = 1 unit and Long_text = 2

        const connection_phrases = [" Additionally, there "];

        while (slots.slots_filled > 0)
        {
            if (short_filled % 2 == 0) // beginning of new sentence
            {
                if (short_filled > 0){result += connection_phrases[Math.min(short_filled/2, connection_phrases.length) - 1]} // add connection word if at least second sentence

                if (slots.old_longs.length == 0 && slots.amount_shorts >= 2){ result += "are "} // while adding short and enough of them left to bind them together use are
                else{result += "is "}
            }

            let bulletin_text = "";

            if(slots.old_longs.length > 0)
            {
                bulletin_text = slots.old_longs.pop().metadata.long_text;
                short_filled += 2;
            }
            else if (slots.old_shorts.length > 0)
            {
                bulletin_text = slots.old_shorts.pop().metadata.short_text;
                short_filled += 1;
            }
            else if (slots.shorts.length > 0)
            {
                bulletin_text = "''" + slots.shorts.pop().metadata.short_text + "''";
                short_filled += 1;
            }
            else
            {
                bulletin_text = "''" + slots.longs.pop().metadata.long_text + "''";
                short_filled += 2;
            }

            result += bulletin_text;

            if(short_filled % 2 == 1)
            {
                if (slots.amount_shorts > 0) result += " and ";  // unpaired short but still shorts available add and
                else
                {
                    short_filled += 1; // no shorts to pair
                }
            }

            if(short_filled % 2 == 0){result += "."} // sentence end


        }

        return result;
    }
}

