  #####  ######  ####    #   #    # # #    #  ####   #####  #    #  ####   ####  #
*/

class ClothingGroup
{
    constructor(config)
    {
        this.clothes = []; // Limit internal memory use!
        if (!config)
        {
            //console.log("ClothingGroup - New!")
            config = {clothes:[]}
        }
        else if (Array.isArray(config))
        {
            // Did we get an array?  Upgrade the array to a ClothingGroup!
            //console.log("ClothingGroup - Upgrading:",config)
            this.add(config);
        }
        else if ("name" in config || config.constructor.name == "ClothingItem")
        {
            // init from single clothing item
            //console.log("ClothingGroup - from clothing item:",config)
            this.add(config);
        }
        else
        {
            // restore ourselves!
            //console.log("ClothingGroup - Reviving: ",config)
            setup.ob_revive_class(this, config)
        }
    }

    add(add_item)
    {
        //console.log("Adding ",add_item);

        if (Array.isArray(add_item))
        {
            for (const item of add_item)
            {
                this.push(item);
            }
        }
        else
        {
            this.push(add_item);
        }
        return true;
    }

    push(item)
    {
        let start_item = clone(item);
        //console.log("PUSH ",typeof(item),item,this)
        if (!Array.isArray(item))
        {
            if (typeof(item) == 'string' || (typeof(item) == 'object' && item.constructor.name != "ClothingItem"))
            {
                //console.log("Push converting to ClothingItem",item);
                item = new ClothingItem(item);
                item.repair_subs();
            }
            if (!item)
            {
                console.error("Push Error!",start_item,item);
            }
            else
            {
                this.clothes.push(item);
            }
            this.validate_items();
        }
        else
        {
            console.error("ClothingGroup.push() does not accept arrays.  Use .add(<array>) instead.",item);
        }
    }

    validate_items()
    {
        const valid = [];
        for (let item of this.clothes)
            if (item != undefined)
                valid.push(item);

        this.clothes = valid;

        if (this.varname)
            V[this.varname] = this.clothes;
    }

    find_item_idx(item)
    {
        var find_item = new ClothingItem(item);
        //console.log("Attempting to find: ",find_item)
        // look at our entire list and see if item matches
        for (var clothing_item_idx in this.clothes)
        {
            //console.log("Looking at ",this.clothes[clothing_item_idx])
            //console.log("DEBUG: ",this.clothes[clothing_item_idx])
            try
            {
                if (this.clothes[clothing_item_idx].equals(find_item))
                {
                    return clothing_item_idx;
                }
            }
            catch (error)
            {
                console.error(`Failed to find index of ${item}`);
                console.error(this);
                continue;
            }
        }
        return -1;
    }

    remove(item_to_remove)
    {
        let result = null;
        //console.log("Attempting to remove ",item_to_remove,this.clothes);
        const item_idx = this.find_item_idx(item_to_remove);
        //console.log("Found at: ",item_idx,clone(this.clothes[item_idx]));
        //console.log(this.varname)
        if (item_idx >= 0)
        {
            result = this.clothes.splice(item_idx,1);
            this.validate_items();
            if (Array.isArray(result))
            {
                result = result[0];
            }
        }
        return result;
    }

    get_item_count()
    {
        this.validate_items();
        return this.clothes.length;
    }

    get_item(item_idx)
    {
        var result = null;
        if (item_idx < this.get_item_count())
        {
            result = this.clothes[item_idx]
        }
        return result
    }

    recover_item(lonely_item)
    {
        lonely_item = setup.ob_check_revive(lonely_item);
        let idx = this.find_item_idx(lonely_item);
        if (idx >= 0 && idx < this.get_item_count())
        {
            lonely_item = this.clothes[idx];
        }
        return lonely_item;
    }

    get_items()
    {
        this.validate_items();
        return this.clothes;
    }

    get_all_of_category(category)
    {
        var result = []
        try
        {
            for (const tItem of this.clothes)
            {
                try
                {
                    if (tItem.get_archetype_prop("category") == category)
                    {
                        result.push(tItem);
                    }
                }
                catch (error)
                {
                    console.error(`Failed to navigate category ${category}`);
                }
            }
        }
        catch (error)
        {
            console.error("get_all_category error:", error);
        }
        return result;
    }

    [Symbol.iterator]()
    {
        var index = -1;
        var data = this.clothes;

        //console.log("ClothingGroup Iterator!")

        return {
            next: () => ({ value: data[++index], done: !(index in data)})
        }
    }

    transfer_item_to(item_or_idx, new_location)
    {
        var result = null;
        //console.log("Transferring ",item_or_idx,new_location)
        if (typeof(item_or_idx) != "number")
        {
            item_or_idx = this.find_item_idx(item_or_idx);
        }
        if (item_or_idx >= 0 && item_or_idx < this.clothes.length)
        {
            const add_item = this.clothes[item_or_idx];
            //console.log("Transfer_Item - ",item_or_idx,add_item);
            new_location.push(add_item);
            result = this.clothes.splice(item_or_idx,1);
            this.validate_items();
        }
        else
        {
            console.error("Attempt to transfer unknown item: ",item_or_idx, new_location);
        }
        return result;
    }

    transfer_all_to(new_location, excludetemp = false)
    {
        // new_location is assumed to be a ClothingGroup!
        if (new_location && new_location.constructor.name == "ClothingGroup")
        {
            for (var entry_id in this.clothes)
            {
                if (this.clothes[entry_id] == undefined)
                {
                    console.error(`Undefined item in clothing group: ${entry_id}`);
                    continue;
                }
                if (excludetemp && setup.clothes[this.clothes[entry_id].item].temporary) continue;
                new_location.add(this.clothes[entry_id])
            }
        }

        this.clothes = [];
        this.validate_items();

        return true;
    }
}


