/* This class handles 'worn' clothing - checking logic for layers, covers,
and anything else necessary to manage worn clothing.

Array order is important for this class - the items are from the inside to
the outside - Closest to Skin to furthest away from the skin.

*/
class ClothingWearMgr extends ClothingGroup
{
    constructor(config)
    {
        if (!config)
        {
            console.log("New ClothingWearMgr!")
            config = {ClothingWearMgr:{}}
        }
        super(config);
        // restore ourselves!
        console.log("Reconstructing ClothingWearMgr: ",config)
        setup.ob_revive_class(this,config);
    }

    // determines if an item conflicts with other worn items
    // returns a list of conflicting items
    // DOES NOT UPDATE WORN CLOTHING
    /*
    When adding a new item we look at each area that item covers, searching the
    array from back-to-front (outside to inside):
    1. If the NEW item has "skintight exception" for that area, good to go!
    2. If nothing else covers that area, we're good to go!
    3. If something 'below' covers that area:
        A: Is the item below 'skintight' in that areas?  YES: good to go
    */
    conflicts(new_item)
    {
        let result = [];
        // look at every item that is currently worn
        if (new_item.constructor.name == "ClothingItem")
        {
            const new_item_layergroup = Math.floor(new_item.get_archetype_prop("layer")/10);
            const cover_locs = new_item.get_archetype_prop("covers");
            const skintight_exceptions = new_item.get_archetype_prop("skintight exception") ?? [];
            for (const cover_loc of cover_locs)
            {
                if (!skintight_exceptions.includes(cover_loc))
                {
                    for (let item_idx = this.clothes.length-1;item_idx >= 0; item_idx--)
                    {
                        let citem = this.clothes[item_idx];
                        let citem_flags = citem.get_archetype_prop("flags");
                        if (!citem_flags.includes("skintight"))
                        {
                            // check layers - if the layergroups are different, then we're good to go!
                            const citem_layergroup = Math.floor(citem.get_archetype_prop("layer")/10);
                            if (citem_layergroup == new_item_layergroup)
                            {
                                let citem_covers = citem.get_archetype_prop("covers");
                                let citem_covers_skintight = citem.get_archetype_prop("covers skintight") ?? [];
                                if (!citem_covers_skintight.includes(cover_loc) && citem_covers.includes(cover_loc))
                                {
                                    if (!result.includes(citem))
                                    {
                                        result.push(citem);
                                    }
                                    console.log("Both items cover \""+cover_loc+"\":",new_item,citem);
                                }
                            }
                        }
                    }
                }
            }
        }
        else
        {
            console.error("conflicts requires a ClothingItem",new_item)
        }
        return result;
    }

    // put items on - return conflicting items.
    // expected use:
    // closet.add(wearmgr.wear(ClothingItem));
    wear(new_item)
    {
        let conflict_items = this.conflicts(new_item);
        for (const conflict_item of conflict_items)
        {
            this.remove(conflict_item);
        }
        //remember to use

        // we probably want to splice instead, after finding the 'top' if the
        // layergroup that the item belongs to...
        // this.clothes.splice(<location>,<delete count>,<new item>)
        // this.clothes.splice(<location>,0,new_item)
        let insert_pos = this.clothes.length;
        const new_item_layergroup = Math.floor(new_item.get_archetype_prop("layer")/10);
        for (let citem_idx = this.clothes.length-1; citem_idx >= 0; citem_idx--)
        {
            const citem = this.clothes[citem_idx];
            const citem_layergroup = Math.floor(citem.get_archetype_prop("layer")/10);
            if (citem_layergroup > new_item_layergroup)
            {
                insert_pos = citem_idx;
            }
            else
            {
                break;
            }
        }
        //super.push(new_item);
        this.clothes.splice(insert_pos,0,new_item);
        return conflict_items;
    }

    remove_all_clothing(to_location)
    {
        this.transfer_all_to(to_location);
    }

    // block use of 'push' and 'add'
    push(item)
    {
        console.error("Please use 'wear(item)' instead of push:",item);
    }

    add(item)
    {
        console.error("Please use 'wear(item)' instead of add:",item);
    }
}

