  #####  ######  ####    #   #    # # #    #  ####  ###   #   ###### #    #

*/


class ClothingItem
{
    constructor(item_id, subs_in = null)
    {
        // selected substitutions (e.g. "color":"red")
        this.subs = {};
        this.sub_prefixes = [];
        // selected configurations
        this.configs = {};
        // current displacement(s)
        this.displacements = [];
        // Cache the current clothing configuration
        this.currently_cache = {};
        this.valid_cache = false;
        this.properties = {};
        this.is_ClothingItem = true;

        //console.log("ClothingItem Constructor: ",item_id)

        if (typeof(item_id) == "string")
        {
            //console.log("New ClothingItem: "+item_id)
            this.item = item_id // Item name from setup.ob_clothes
            if (!(item_id in setup.clothes))
            {
                console.error("Attempted to create ClothingItem that doesn't exist in setup.clothes (attempting to recover): ",item_id);
                let thisid = item_id.toLowerCase();
                for (let otherid of Object.keys(setup.clothes))
                    if (otherid.toLowerCase() == thisid)
                    {
                        console.warn(`${item_id} corrected to ${otherid}`)
                        item_id = otherid;
                        break;
                    }
            }
        }
        else
        {
            // Examine the object - is it an attempt to recreate ourselves, or
            // an attempt to convert from an old-style Clothing structure?
            // Easiest difference - the old-style has *name* and new does not.
            // Additionally, Old does not have *configs* and new does.
            const incoming_keys = Object.keys(item_id);

            if (!(item_id.item in setup.clothes))
            {
                console.error("Attempted to create ClothingItem that doesn't exist in setup.clothes (attempting to recover): ",item_id);
                let thisid = item_id.item.toLowerCase();
                for (let otherid of Object.keys(setup.clothes))
                    if (otherid.toLowerCase() == thisid)
                    {
                        console.warn(`${item_id.item} corrected to ${otherid}`)
                        item_id.item = otherid;
                        break;
                    }
            }

            if ("configs" in item_id)
            {
                for (let config of Object.keys(item_id.configs))
                {
                    if (!setup.clothes[item_id.item].configurations || !(config in setup.clothes[item_id.item].configurations))
                    {
                        console.warn("Deleting bad config: " + config + " on " + item_id.item);
                        delete item_id.configs[config];
                    }
                }
            }

            //console.log("Incoming Keys: ",incoming_keys)
            if (incoming_keys.indexOf("name") != -1 && incoming_keys.indexOf("is_ClothingItem") == -1)
            {
                //console.log("Converting ClothingItem:",item_id)
                // It's an older data structure, convert it
                this.item = item_id.item;
                if ("displacements" in item_id)
                {
                    this.displacements = item_id.displacements;
                }
                else
                {
                    this.displacements = [];
                }
                if ("configs" in item_id)
                {
                    this.configs = item_id.configs;
                }
                if ("properties" in item_id)
                {
                    this.properties = item_id.properties;
                }
                if ("sub_prefixes" in item_id)
                {
                    this.sub_prefixes = item_id.sub_prefixes;
                }
                if ("subs" in item_id)
                {
                    this.subs = item_id.subs;
                }
                else if (item_id.name && typeof item_id.name == "string")
                {
                    // Attempt to determine the substitutions:
                    // Multiple substitutions make this more interesting.
                    // Additionally, the 'sub' list may not contain the value, so
                    // we need to pull it out of the name string itself.
                    // We _can_ look at the name from the database to identify where
                    // the substitutions go into the string.
                    // At time of writing "Animal-Print Leg Warmers" looks to be a worst-case.

                    // Search through each sub option to see if we can find a match.  If more than one
                    // matches, use the one with the most characters.  (Handle "blue" and "navy blue")
                    var deep_search_needed = [];
                    var sub_info = this.get_subs()
                    var temp_name = item_id.name.toLowerCase();
                    for (const [sub_name, sub_options] of Object.entries(sub_info))
                    {
                        var found = false;
                        // Search the setup.ob_outfits object to see if there are any additional options
                        var all_options = sub_options.concat(this.search_setup_for_options(sub_name))
                        for (const test_option of all_options)
                        {
                            //console.log("Looking for "+test_option+" in "+temp_name)
                            var option_loc = temp_name.indexOf(test_option.toLowerCase());
                            if (option_loc != -1)
                            {
                                //console.log("found: ",option_loc)
                                // Favor matches that are earlier in the string
                                if (!this.subs[sub_name] || (option_loc < temp_name.indexOf(this.subs[sub_name])))
                                {
                                    //console.log("It's earlier!");
                                    found = true;
                                    this.subs[sub_name] = test_option
                                }
                            }
                        }
                        if (!found)
                        {
                            deep_search_needed.push(sub_name);
                        }
                        else
                        {
                            // Remove the one we found so we don't double-find things
                            // Things like 'striped socks' have two color choices, so get them right.
                            temp_name = temp_name.replace(this.subs[sub_name],"");

                        }
                    }
                    if (deep_search_needed.length > 0)
                    {
                        //console.warn("ClothingItem Creation - unknowns:\nItem: "+item_id.item+"\nName: "+item_id.name+"\nUnknowns:",deep_search_needed,item_id);
                        if (deep_search_needed.length == 1)
                        {
                            var known_name = this.get_name()
                            var left_side = 1000
                            var right_side = 0
                            for (var sub_name of deep_search_needed)
                            {
                                var found_loc = known_name.indexOf("%"+sub_name)
                                if (found_loc < left_side)
                                {
                                    left_side = found_loc;
                                }
                                if ((found_loc+sub_name.length+1) > right_side)
                                {
                                    right_side = found_loc+sub_name.length+1;
                                }
                            }
                            // Slice off the ends we (probably) don't care about.
                            // right side
                            var right_to_end = known_name.length - right_side
                            var temp_name = item_id.name.substring(0,item_id.name.length-right_to_end)
                            // left side
                            var temp_name = temp_name.substring(left_side)
                            console.log("Narrowed down to: \""+temp_name+"\"")
                            this.subs[deep_search_needed[0]] = temp_name;
                        }
                    }
                }
                else
                {
                    console.error(`Received bad item_id "${item_id}`);
                }
            }
            else
            {
                // restore ourselves!
                //console.log("Reconstructing ClothingItem: "+item_id.item)
                setup.ob_revive_class(this,item_id);
            }
        }
        if (subs_in != null)
        {
            this.set_subs(subs_in)
        }

        //console.log("About to update cache!",this);
        this.update_current_cache();

    }

    search_setup_for_options(sub_name)
    {
        var result_array = []
        for (const [outfit,outfit_details] of Object.entries(setup.ob_outfits))
        {
            for (const item_entry of outfit_details.items)
            {
                if (item_entry.item == this.item)
                {
                    if (item_entry["sub "+sub_name])
                    {
                        result_array = result_array.concat(item_entry["sub "+sub_name])
                    }
                }
            }
        }
        return result_array
    }

    update_current_cache()
    {
        // check to make sure all configurations have been identified and selected
        // Select first configurations by default
        const categories = this.get_configuration_categories()

        // First, clone current "base" fields
        // then go through each selected configuration for the same field(s)
        //  Per field, there are 3 options:
        //  1. Identical name - replace entirely with the one from the configuration
        //
        //  2. "<name>+" - concatenate configuration field onto base field
        //
        //  3. "<name>-" - remove items listed in configuration field from base field
        //
        //  IF a field is present in the configuration but not the base, it is added
        //      to the base.

        let mod_fields = {};
        for (const [key, value] of Object.entries(setup.clothes[this.item]))
        {
            // we don't need to clone configurations because we will be applying them.
            if (key != "configurations")
            {
                if (key.indexOf(" mods") >= 0)
                {
                    mod_fields[key] = value;
                }
                else
                {
                    //console.log("Caching \""+key+"\": ",value)
                    this.currently_cache[key] = clone(value);
                }
            }
            else
            {

            }
        }

        const item_name = this.get_name();
        //console.log("update_current_cache mod fields:",mod_fields)
        for (const [key,value] of Object.entries(mod_fields))
        {
            let base_key = key.replace(" mods","");
            if (!this.currently_cache[base_key])
            {
                console.log(this.get_item()+": Missing "+base_key+"!");
            }
//console.log(this.get_item()+": Modding "+base_key+" with "+key,this.currently_cache[base_key],value);
            if (Array.isArray(this.currently_cache[base_key]))
            {  // we have an array of values (like "covers" or "flags")
                //console.log("Array 1");
                let temp_array = [];
                for (const [check_str,factors] of Object.entries(value))
                {
                    if (item_name.includes(check_str))
                    {
                         this.currently_cache[base_key] =  this.currently_cache[base_key].concat(factors);
                    }
                }
            }
            else if (typeof( this.currently_cache[base_key]) == 'string')
            {  // it's a description or shortname or something - not handled right now
                //console.log("String 1");
                for (const [check_str,new_str] of Object.entries(value))
                {
                    if (item_name.includes(check_str))
                    {
                         this.currently_cache[base_key] =  new_str;
                    }
                }
            }
            else if (typeof( this.currently_cache[base_key]) == 'object')
            {  // probably 'style factor'
                //console.log("Object 1")
                let temp_obj = {};
                for (const [check_str,factors] of Object.entries(value))
                {
                    if (item_name.includes(check_str))
                    {
                        for (const [key, value] of Object.entries(factors))
                            temp_obj[key] = (temp_obj[key] ?? 0) + value;
                    }
                }
                //console.log("Object 2",this.currently_cache[base_key])
                for (const [key, value] of Object.entries(temp_obj))
                {
                    //console.log("Adding: ",key,value);
                    if ( this.currently_cache[base_key][key])
                         this.currently_cache[base_key][key] += value;
                    else
                         this.currently_cache[base_key][key] = value;
                }
                //console.log("Object 3")
                for (const [key, value] of Object.entries( this.currently_cache[base_key]))
                {
                     this.currently_cache[base_key][key] = Math.max(0,value);
                }
            }
            //console.log("Mod complete: ", this.currently_cache[base_key]);
        }


        // Remove any categories from this.configs that are not present in categories
        for (const [config_key, config_value] of Object.entries(this.configs))
        {
            //console.log("Config in Categories? ",config_key,categories,typeof(config_key));
            if (categories.indexOf(config_key) == -1 || !setup.clothes[this.item]?.configurations?.[config_key]?.[config_value])
            {
                //console.log("Couldn't find ",config_key);
                delete this.configs[config_key];
                //console.log("configs: ",this.configs);
            }
        }

        // Now apply each of the configurations
        for (const category of categories)
        {
            if (category.indexOf("config_") == 0)
            {
                //console.log("configuration: ",category);
                continue;
            }

            if (!(category in this.configs))
            {
                let default_config = this.get_configuration_options(category)[0];
                // look through all of the options to see if one has 'config_default:true'
                // - if not, select the first option.
                for (const [config_key, config_value] of Object.entries(setup.clothes[this.item].configurations[category]))
                {
                    //console.log("Config: ",this, category, config_key, config_value);
                    if (config_key.indexOf("config_") != 0)
                    {
                        //console.log("looking for default in: ",config_key, config_value, this);
                        if ("config_default" in config_value && config_value.config_default)
                        {
                            default_config = config_key;
                        }
                    }
                }
                this.set_configuration(category, default_config);
            }

            // Look through each field of the configuration and process appropriately
            const category_config = this.get_configuration(category);
            //console.log("Category \""+category+"\", Config: "+category_config)
            for (const [config_key,config_value] of Object.entries(setup.clothes[this.item].configurations[category][category_config]))
            {
                // notch out configuration 'settings' propoerties
                if (config_key.indexOf("config_") != 0)
                {
                    const last_char = config_key.slice(-1)
                    // Do we overwrite or calculate field values?
                    //console.log(config_key, " Field end: ", last_char)
                    if (last_char == '+')
                    {
                        const base_field_name = config_key.substring(0,config_key.length-1)
                        //console.log("ADD! ",config_key,config_value,base_field_name)
                        if (this.currently_cache[base_field_name])
                        {
                            if (Array.isArray(this.currently_cache[base_field_name]))
                            {
                                this.currently_cache[base_field_name] = this.currently_cache[base_field_name].concat(config_value)
                            }
                            else if (typeof(this.currently_cache[base_field_name]) == "object")
                            {
                                for (const [add_key,add_val] of Object.entries(config_value))
                                {
                                    //console.log("OBJ Process: ",add_key,add_val)
                                    if (this.currently_cache[base_field_name][add_key])
                                    {
                                        this.currently_cache[base_field_name][add_key] += add_val
                                    }
                                    else
                                    {
                                        this.currently_cache[base_field_name][add_key] = add_val
                                    }
                                }
                            }
                            else
                            {
                                this.currently_cache[base_field_name] += config_value;
                            }
                        }
                        else
                        {
                            console.warn("Field not found:",base_field_name,this)
                        }
                    }
                    else if (last_char == '-')
                    {
                        const base_field_name = config_key.substring(0,config_key.length-1)
                        //console.log("SUB!",config_key,config_value,base_field_name)
                        if (this.currently_cache[base_field_name])
                        {
                            if (Array.isArray(this.currently_cache[base_field_name]))
                            {
                                for (const value of config_value)
                                {
                                    const value_index = this.currently_cache[base_field_name].indexOf(value)
                                    if (value_index != -1)
                                    {
                                        this.currently_cache[base_field_name].splice(value_index,1);
                                    }
                                }
                            }
                            else if (typeof(this.currently_cache[base_field_name]) == "object")
                            {
                                for (const [sub_key,sub_val] of Object.entries(config_value))
                                {
                                    //console.log("SUB OBJ Process: ",sub_key,sub_val)
                                    if (this.currently_cache[base_field_name][sub_key])
                                    {
                                        this.currently_cache[base_field_name][sub_key] -= sub_val
                                    }
                                }
                            }
                            else
                            {
                                this.currently_cache[base_field_name] -= config_value;
                            }
                        }
                    }
                    else
                    {
                        //console.log("Replace!",config_key,config_value)
                        this.currently_cache[config_key] = clone(config_value);
                    }
                }

                //console.log("Applying Config \""+config_key+"\" Field:", config_value);
            }
        }

        // Now apply displacements.  It's not an error if a displacement exposes
        // something that was already exposed (since displacements aren't aware
        // of configurations)
        for (const displace of this.get_displacements())
        {
            //console.log("applying displacement: ",displace)
            let displace_name = "displace "+displace;
            let displace_uncovers = this.get_archetype_prop(displace_name);
            if (displace_uncovers)
            {
                for (const displace_coverage of displace_uncovers)
                {
                    let coverage_loc = this.currently_cache.covers.indexOf(displace_coverage);
                    if (coverage_loc != -1)
                    {
                        this.currently_cache.covers.splice(coverage_loc,1);
                        //console.log("exposing ",displace_coverage);
                    }
                }
            }
        }

        // Clean up style factors - they shouldn't go negative
        if (this.currently_cache.hasOwnProperty("style factor"))
        {
            for (let [factor, value] of Object.entries(this.currently_cache['style factor']))
            {
                if (value <= 0)
                {
                    delete(this.currently_cache['style factor'][factor]);
                }
            }

        }

        this.valid_cache = true;
    }

    // Are these two items the same?
    // compare as either "type", "subs", "all"
    // "type" just sees if they are the same general clothing ("Necktie" == "Necktie")
    // "subs" includes comparison of substitutions ("Red Necktie" == "Red Necktie")
    // "all" includes comparison of configurations ("Loose Red Necktie" == "Loose Red Necktie")
    equals(compare_to, compare_type="subs")
    {
        // Convert it to a ClothingItem whatever it is
        if (compare_to == undefined) return false;
        var compare_item = new ClothingItem(compare_to)
        var equal = (this.item == compare_item.get_item())
        if (equal && ["subs", "all"].indexOf(compare_type) != -1)
        {
            var match = true;
            for (const [sub_name,sub_value] of Object.entries(this.subs))
            {
                if (this.subs[sub_name] != compare_item.subs[sub_name])
                {
                    match = false;
                }
            }
            equal = match;
        }
        if (equal && ["all"].indexOf(compare_type) != -1)
        {
            var match = true;
            for (const [config_key, config_value] of Object.entries(this.configs))
            {
                if (this.configs[config_key] != compare_item.configs[config_key])
                {
                    match = false;
                }
            }
            equal = match;
        }
        return equal;
    }

    get_current_archetype()
    {
        return clone(this.currently_cache);
    }

    get_archetype_prop(property)
    {
        var result = null;
        if (property in this.currently_cache)
        {
            result = clone(this.currently_cache[property])
        }
        return result;
    }

    get_data_structure()
    {
        var result = {}
        result.name = this.get_name();
        result.item = this.get_item();
        result.displacements = this.displacements;
        if (!Array.isArray(result.displacements))
        {
            result.displacements = [];
        }
        result.subs = this.subs;
        result.sub_prefixes = this.sub_prefixes;
        result.properties = this.properties;
        result.configs = this.configs;
        return result;
    }

    get_item(for_code=false)
    {
        var result = this.item
        if (for_code)
        {
            result = result.replace(/[^0-9a-z]/gi, '')
        }
        return result
    }

    add_sub_prefixes(new_prefixes)
    {
        if (!Array.isArray(new_prefixes))
        {
            // make it an array :)
            new_prefixes = [new_prefixes];
        }
        for (const prefix of new_prefixes)
        {
            this.sub_prefixes.push(prefix);
        }
    }

    remove_sub_prefixes(remove_prefixes)
    {
        if (!remove_prefixes)
        {
            this.sub_prefixes = [];
        }
        else
        {
            if (!Array.isArray(remove_prefixes))
            {
                remove_prefixes = [remove_prefixes];
            }

            for (const prefix of remove_prefixes)
            {
                let prefix_idx = this.sub_prefixes.indexOf(prefix);
                if (prefix_idx >= 0)
                {
                    this.sub_prefixes.splice(prefix_idx,1);
                }
            }
        }
    }

    get_sub_prefixes()
    {
        return this.sub_prefixes;
    }

    // return a dictionary of subs with arrays of values
    get_subs(selected_subs = false)
    {
        if (selected_subs)
        {
            return this.subs;
        }
        else
        {
            const all_prefixes = this.sub_prefixes;
            //console.log("All Prefixes: ",all_prefixes)
            var clothing_definition = setup.clothes[this.item];
            var sub_info = {}
            // Go through all setup object keys looking for "sub "
            // if found, add the remaining string after "sub " as the
            // key, then copy the value over.
            if (this.valid_cache)
            {
                clothing_definition = this.currently_cache;
            }
            for (const key of Object.keys(clothing_definition))
            {
                if (key.indexOf("sub ") == 0)
                {
                    sub_info[key.substring(4)] = [];
                }
            }
            //console.log("All subs found:", Object.keys(sub_info));

            for (const sub of Object.keys(sub_info))
            {
                for (const prefix of all_prefixes)
                {
                    let sub_str = prefix+" "+sub;
                    if (Object.keys(clothing_definition).includes(sub_str))
                    {
                        sub_info[sub] = sub_info[sub].concat(clothing_definition[sub_str]);
                    }
                }
                if (sub_info[sub].length == 0)
                {
                    sub_info[sub] = sub_info[sub].concat(clothing_definition["sub "+sub]);
                }
                if (sub_info[sub].length == 1)
                {
                    this.subs[sub] = sub_info[sub][0];
                    delete sub_info[sub];
                }
            }

            return sub_info;
        }
    }

    get_sub_names()
    {
        return Object.keys(this.get_subs());
    }

    get_sub_values(sub_name)
    {
        return this.get_subs()[sub_name];
    }

    set_subs(sub_dict)
    {
        for (const [key, value] of Object.entries(sub_dict))
        {
            this.set_sub(key,value, false, false)
        }
        this.update_current_cache();
    }

    // make sure that the type exists and make sure it is a valid
    // value.  To force non-standard values set 'arbitrary_value' to
    // true.
    set_sub(type, value, arbitrary_value = false, update_cache = true)
    {
        const possible_subs = this.get_subs();
        if (possible_subs[type])
        {
            if (arbitrary_value || (possible_subs[type].indexOf(value) != -1))
            {
                this.subs[type] = value;
                if (update_cache)
                {
                    this.update_current_cache();
                }
                return true;
            }
        }
        return false;
    }

    get_sub(type)
    {
        const subs = this.get_subs(true);
        return subs[type];
    }

    process_subs(on_text)
    {
        //console.log("Process_Subs: ",on_text)
        if (!on_text)
        {
            on_text = "";
        }
        for (const [key,value] of Object.entries(this.subs))
        {
            on_text = on_text.replace("%"+key, value)
        }
        for (const [key,value] of Object.entries(this.configs))
        {
            on_text = on_text.replace("%"+key, value)
        }
        on_text = on_text.replace("  "," ") // remove double spaces

        if (on_text.match("%theme") && "color" in this.subs) // hack to fix some clothing items that got changed unwisely at some point
            on_text = on_text.replace("%theme", this.subs["color"]);
        if (on_text.match("%house") && V.pchouse) // hack to fix some greek items that were broken at one point
            on_text = on_text.replace("%house", setup.ob_houses.db[V.pchouse].greek);

        return on_text.trim() // remove leading & trailing spaces
    }

    repair_subs()
    {
        // set any subs that have no pick for whatever reason
        const rng = setup.ob_newRNG(V.pcname + this.item);
        for (const [key, value] of Object.entries(this.get_subs()))
        {
            if (!this.subs[key])
            {
                if (value.length > 0)
                    this.set_sub(key, rng.randomchoice(value), false, false);
            }
        }
        this.update_current_cache();
        return this;
    }

    get_name(no_pair = false, include_properties = false)
    {
        var base_name = setup.clothes[this.item].name;
        if (this.valid_cache)
        {
            base_name = this.currently_cache.name;
        }
        if (no_pair)
        {
            base_name = base_name.replace("pair of ", "");
        }
        if (include_properties)
        {
            let stains = this.get_property("stains");
            let wet = this.is_wet(true);
            if (wet)
            {
                base_name = this.get_wet_description() + " " + base_name;
                if (stains) base_name = "and " + base_name;
            }
            if (stains)
            {
                let stainname = "";
                if (stains.length > 1)
                    stainname = "thoroughly stained";
                else if (stains[0] == "pee")
                    stainname = "urine-stained";
                else
                    stainname = stains[0]+"-stained";

                if (stainname != "")
                base_name = stainname + " " + base_name;
            }
        }
        let result = this.process_subs(base_name);
        return result;
    }

    get_shortname()
    {
        return this.process_subs(this.currently_cache.shortname)
    }

    set_property(prop, value)
    {
        this.properties[prop] = value;
    }

    get_property(prop)
    {
        var result = null;
        if (this.properties[prop] != null)
            result = this.properties[prop];
        return result;
    }

    delete_property(prop)
    {
        if (this.properties[prop] != null)
            delete this.properties[prop];
    }

    add_wetness(wetness = 1000)
    {
        if (setup.ob_clothes_waterproof.includes(this.get_archetype_prop("category")) || this.get_archetype_prop("flags").includes("waterproof")) return;

        let wet = this.get_property("wetness");
        wet = Math.min((wet ? wet : 0) + wetness, 1000);
        if (wet > 0)
            this.set_property("wetness", wet);
        else
            this.delete_property("wetness");
    }

    is_wet(anywetness = false)
    {
        //returns true if wetness is greater than 50%, unless looking for any amount of wetness
        const wet = this.get_property("wetness");
        if (!wet) return false;
        return anywetness ? true : wet >= 500;
    }

    get_wet_description()
    {
        const wet = this.get_property("wetness");

        if (!wet) return "dry";
        else if (wet < 250) return "damp";
        else if (wet < 500) return "soggy";
        else if (wet < 750) return "wet";
        else return "soaked";
    }

    is_wet_transparent()
    {
        //returns true if wet, transparent when wet and has a light color
        if (!this.get_archetype_prop("flags").includes("wet transparency") || !this.is_wet())
            return false;

        for (const [sub_key, sub_value] of Object.entries(this.subs))
        {
            if (sub_key.indexOf("color") != 0) continue;
            if (setup.ob_clothes_wet_transparency_colors.includes(sub_value))
                return true;
        }
        return false;
    }

    is_wet_skintight()
    {
        return this.get_archetype_prop("flags").includes("wet cling") && this.is_wet();
    }

    is_glasses()
    {
        return this.get_archetype_prop("flags").includes("glasses");
    }

    get_descriptions_list()
    {
        var result = []
        for (const key of Object.keys(this.currently_cache))
        {
            //console.log("Looking at: ",key)
            if (key.indexOf("description") == 0)
            {
                result.push(key.replace("description","").trim())
            }
        }
        return result;
    }

    _description_helper(description_name)
    {
        let result = this.currently_cache[description_name];
        if (Array.isArray(result))
        {
            result = setup.ob_randomchoice(result);
        }
        return result;
    }

    // if 'type' is present, returns "description <type>"
    // from setup structure.  Intended for "store" or similar
    // If substitutions are present and needed, they are performed.
    // also handles type being the full description name
    get_description(types = [""])
    {
        let result = "";
        let description_name = "";
        if (!Array.isArray(types))
        {
            types = [types];
        }
        for (const type of types)
        {
            description_name = "description"
            if (type.length > 0)
            {
                if (type.indexOf("description") == 0)
                {
                    description_name = type;
                }
                else
                {
                    description_name += " " + type;
                }
            }
            if (description_name in this.currently_cache)
            {
                result = this.process_subs(this._description_helper(description_name));
                break;
            }
        }

        if (result.length == 0)
        {
            if ("description" in this.currently_cache)
            {
                result = this.process_subs(this._description_helper("description"));
            }
            else
            {
                let description_names = this.get_descriptions_list();
                for (description_name of description_names)
                {
                    let temp_result = this.process_subs(this._description_helper("description"));
                    if (!temp_result.includes("%"))
                    {
                        result = temp_result;
                        break;
                    }
                }
            }
        }

        //console.log("get_description: \""+description_name+"\": "+result);
        return result;
    }

    // The calculated 'covers' array based on all current
    // displacements and configurations
    get_covers()
    {
        // TODO: Calculate the right 'covers' based on everything
        return this.currently_cache["covers"]
    }

    get_possible_displacements()
    {
        let result = [];
        for (const [key,value] of Object.entries(this.currently_cache))
        {
            if (key.indexOf("displace") == 0)
            {
                let displace_name = key.substring(9);
                for (const c_loc of value)
                {
                    if (this.get_covers().includes(c_loc))
                    {
                        if (this.displacements.indexOf(displace_name) == -1)
                        {
                            result.push(displace_name);
                        }
                        break;
                    }
                }

            }
        }
        //console.log("Displacements possible:",result);
        return result;
    }

    get_displacement_uncovers(displacement)
    {
        let displace_name = "displace "+displacement;
        let displace_uncovers = this.get_archetype_prop(displace_name);
        return displace_uncovers || [];
    }

    // return current displacement names
    get_displacements()
    {
        return this.displacements;
    }

    add_displacement(displacement)
    {
        //console.log("Adding displacement: ",displacement);
        if (this.displacements.indexOf(displacement) == -1)
        {
            this.displacements.push(displacement)
        }
        this.update_current_cache();
    }

    remove_displacement(displacement)
    {
        var displacement_location = this.displacements.indexOf(displacement)
        if (displacement_location != -1)
        {
            this.displacements.splice(displacement_location, 1);
            this.update_current_cache();
            return true;
        }
        return false;
    }

    remove_all_displacements()
    {
        this.displacements = [];
        this.update_current_cache();
        return true;
    }

    // return possible configuration categories ("fit", "hood", etc.)
    get_configuration_categories()
    {
        var result = []
        if (setup.clothes[this.item].configurations)
        {
            for (const item of Object.keys(setup.clothes[this.item].configurations))
            {
                if (item.indexOf("config_") != 0)
                {
                    result.push(item);
                }
            }
        }
        return result;
    }

    // What are the possible options for a configuration category
    // (for "hood": ["down", "up"], etc.)
    get_configuration_options(category, except_current = false)
    {
        var key_list = []
        if (this.get_configuration_categories().indexOf(category) != -1)
        {
            // remove any keys that start with "config_"
            for (const key of Object.keys(setup.clothes[this.item].configurations[category]))
            {
                if (key.indexOf("config_") != 0)
                {
                    if (!(except_current && key == this.get_configuration(category)))
                    {
                        key_list.push(key)
                    }
                }
            }
        }
        return key_list;
    }

    get_configuration(category)
    {
        // make sure category exists, then set configuration
        if (this.get_configuration_categories().indexOf(category) != -1)
        {
            if (this.configs[category])
            {
                return this.configs[category];
            }
        }
        return false;
    }

    set_configurations(config_dict)
    {
        for (const [key, value] of Object.entries(config_dict))
        {
            this.set_configuration(key,value)
        }
    }

    set_configuration(category, configuration)
    {
        // make sure category exists, then set configuration
        if (this.get_configuration_categories().indexOf(category) != -1)
        {
            if (this.get_configuration_options(category).indexOf(configuration) != -1)
            {
                //console.log("SET CONFIG: ",this.get_item(),category,configuration)
                this.configs[category] = configuration
                this.update_current_cache()
                return true
            }
        }
        return false
    }

    get_configuration_descriptions()
    {
        var result = []
        var configs = this.configs;
        for (const [key,value] of Object.entries(configs))
        {
            if (key in setup.clothes[this.item].configurations)
            {
                //console.log("get_c_d ",key,value,setup.clothes[this.item].configurations[key][value])
                if (setup.clothes[this.item].configurations[key][value].config_description)
                {
                    result.push(this.process_subs(setup.clothes[this.item].configurations[key][value].config_description));
                }
                else if (setup.clothes[this.item].configurations[key].config_description)
                {
                    result.push(this.process_subs(setup.clothes[this.item].configurations[key].config_description));
                }
                else
                {
                    result.push(`the ${key} ${setup.clothes[this.item].configurations[key]?.config_isare ?? "is"} ${value}`);
                }
            }
        }
        return result;
    }

    get(property_name)
    {
        return this.currently_cache[property_name]
    }
}

