};

setup.ob_conjugator.patterns = [
  {
    pattern: /^have$/,
    process: function(pronoun, verb) {
      return setup.ob_conjugator.isThirdPerson(pronoun) ? 'has' : verb;
    }
  },
  {
    pattern: /^don't$/,
    process: function(pronoun, verb) {
      return setup.ob_conjugator.isThirdPerson(pronoun) ? "doesn't" : verb;
    }
  },
