    }
  },
  {
    pattern: /(o|s|sh|ch|z|j|x)$/,
    process: function(pronoun, verb) {
      return setup.ob_conjugator.isThirdPerson(pronoun) ? verb + 'es' : verb;
    }
  },
  {
    pattern: /(a|e|u|i|o)y$/,
    process: function(pronoun, verb) {
      return setup.ob_conjugator.isThirdPerson(pronoun) ? verb + 's' : verb;
    }
  },
  {
    pattern: /y$/,
    process: function(pronoun, verb) {
      return setup.ob_conjugator.isThirdPerson(pronoun) ? verb.replace(/y$/, 'ies') : verb;
    }
  },
  {
    pattern: /^(be|are)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'am';
        case 'he':
        case 'she':
        case 'it':
          return 'is';
        default:
          return 'are';
      }
    }
  },
  {
    pattern: /^(Be|Are)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'Am';
        case 'he':
        case 'she':
        case 'it':
          return 'Is';
        default:
          return 'Are';
      }
    }
  },
  {
    pattern: /^(were)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'was';
        case 'he':
        case 'she':
        case 'it':
          return 'was';
        default:
          return 'were';
      }
    }
  },
  {
    pattern: /^(Were)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'Was';
        case 'he':
        case 'she':
        case 'it':
          return 'Was';
        default:
          return 'Were';
      }
    }
  },
  {
    pattern: /^(weren't)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'wasn\'t';
        case 'he':
        case 'she':
        case 'it':
          return 'wasn\'t';
        default:
          return 'weren\'t';
      }
    }
  },
  {
    pattern: /^(Weren't)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'Wasn\'t';
        case 'he':
        case 'she':
        case 'it':
          return 'Wasn\'t';
        default:
          return 'Weren\'t';
      }
    }
  },
  {
    pattern: /^(haven't)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'haven\'t';
        case 'he':
        case 'she':
        case 'it':
          return 'hasn\'t';
        default:
          return 'haven\'t';
      }
    }
  },
  {
    pattern: /^(Haven't)$/,
    process: function(pronoun, verb) {
      switch (pronoun) {
        case 'I':
          return 'Haven\'t';
        case 'he':
        case 'she':
        case 'it':
          return 'Hasn\'t';
        default:
          return 'Haven\'t';
      }
    }
  },
  {
    pattern: /.*/,
    process: function(pronoun, verb) {
      return setup.ob_conjugator.isThirdPerson(pronoun) ? verb + 's' : verb;
    }
  }
];

setup.ob_conjugator.conjugate = function(pronoun, verb, append) {
  if (/^to /.test(verb)) {
    verb = verb.replace('to ', '');
  }

  var result;
  let patterns = this.patterns;
  for (var i = 0; i < patterns.length; i++) {
    if (patterns[i].pattern.test(verb)) {
      result = patterns[i].process(pronoun, verb);
      break;
    }
  }

  return append ? pronoun + ' ' + result : result;
};

