setup.ob_creating.best_camera = function()
{
    let cameras = this.available_cameras();
    if (cameras.length == 0) return;

    let maxq = 0;
    let camera;
    for (let avail of cameras)
    {
        let q = this.cameras[avail].maxQuality;
        if (q > maxq)
        {
            maxq = q;
            camera = avail;
        }
    }
    return camera;
}

setup.ob_creating.available_art_tools = function()
{
    let stored = setup.ob_is_homebase() || V.pc.has_art_storage();
    let alltools = stored ? Object.values(setup.ob_creating.artTypes).map(e => e.tool) : [];
    let allrevisetools = stored ? Object.values(setup.ob_creating.artTypes).filter(e => e.reviseTool).map(e => e.reviseTool) : [];
    alltools.push(...allrevisetools);

    let retval = {};
    for (let dormthing of [...setup.ob_locationInventory.contents(setup.ob_locationInventory.last_location()), ...setup.ob_locationInventory.contents("universal")])
    {
        let item = dormthing.item;
        let iteminfo = setup.ob_dormstuff[item];
        if (iteminfo?.artTool && iteminfo.artTool != "camera")
        {
            if (!iteminfo.computerRequired || setup.ob_computer())
            {
                retval[item] = {tool: iteminfo.artTool, medium: iteminfo.artMedium, mediumType: iteminfo.artMediumType};
            }
        }
    }

    if (V.lastloctags.includes("computerlab"))
    {
        for (let [item, iteminfo] of Object.entries(setup.ob_dormstuff))
            if (iteminfo.availableInComputerLab && !(item in retval))
                retval[item] = {tool: iteminfo.artTool, medium: iteminfo.artMedium, mediumType: iteminfo.artMediumType};
    }

    let cameraexample = setup.ob_dormstuff["entry-level DSLR camera"]; // cameras are basically the same in this respect
    for (let camera of this.available_cameras())
    {
        retval[camera] = {tool: cameraexample.artTool, medium: cameraexample.artMedium, mediumType: cameraexample.artMediumType};
    }

    return retval;
}

setup.ob_creating.available_actions = function()
{
    let tools = this.available_art_tools();

    let retval = [];
    for (const [type, typeinfo] of Object.entries(this.artTypes))
    {
        for (const [tool, toolinfo] of Object.entries(tools))
        if (toolinfo.tool.includes(typeinfo.tool))
        {
            retval.push({action: `Create ${type} using ${tool}`, artType: type, tool: tool, medium: toolinfo.medium, mediumType: toolinfo.mediumType});
        }
    }

    return retval;
}

