        }
    }

    return retval;
}

setup.ob_creating.available_poses = function(npc)
{
    // what poses are available for this npc at this time
    npc = setup.people.expand(npc);

    const hasbreasts = npc.has_breasts();
    const breastsvisible = npc.is_part_visible("breasts");
    const crotchvisible = npc.is_part_visible("crotch");
    const buttvisible = npc.is_part_visible("butt");
    const chestvisible = npc.is_part_visible("chest");
    const exhib = npc.has_any_inclination("just_exhibitionist");
    const sexshy = npc.has_any_inclination("sexshy");
    const diff = setup.people.command_difficulty(npc);
    const pcisdom = V.pc.skillcheck("Dominance", diff);
    const pcisdomhard = pcisdom && V.pc.skillcheck("Dominance", diff + 2);
    const willingnude = setup.people.willing_nude(npc);

    let willshowchest = (hasbreasts && (breastsvisible || exhib || pcisdom)) || (!hasbreasts && (chestvisible || !sexshy || exhib || pcisdom));
    let willshowcrotch = crotchvisible || exhib || pcisdomhard;

    // we can skip these checks if they're already exposed because that was already gated behind the dialogue stuff
    willshowchest = willshowchest || (chestvisible && willingnude);
    willshowcrotch = willshowcrotch || (crotchvisible && willingnude);

    let retval = [];

    if (!chestvisible && !crotchvisible && !buttvisible)
        retval.push({action: "Just a regular pose", willdo: true, showparts: []});

    if (!crotchvisible && !buttvisible)
        retval.push({action: "Pose topless", willdo: willshowchest, showparts: ["chest"]});

    retval.push({action: "Pose nude", willdo: willshowchest && willshowcrotch, showparts: ["chest", "crotch", "butt"]});

    return retval;
}

setup.ob_creating.find_art_info = function(name)
{
    // find the art item associated with a name string
    // probably coming from the gift-giving system, or possibly something to do with dorm inventory

    if (!V.createdart) return;

    name = setup.ob_strip_a_or_an(name);
