setup.ob_creating.maxQuality = function(art)
{
    // expects an art object
    if (art.artType == "photograph")
    {
        let camera = art.tool;
        return this.cameras[camera].maxQuality;
    }
    else
    {
        let typeinfo = this.artTypes[art.artType];
        return typeinfo.maxQuality;
    }
}

setup.ob_creating.label_art_quality = function(art)
{
    let perc = art.quality / 1000;
    if (perc < 0.05)
        return "barely recognizable";
    else if (perc < 0.1)
        return "very rough";
    else if (perc < 0.2)
        return "rough";
    else if (perc < 0.3)
        return "crude";
    else if (perc < 0.45)
        return "low quality";
    else if (perc < 0.6)
        return "passable";
    else if (perc < 0.7)
        return "decent";
    else if (perc < 0.8)
        return "good";
    else if (perc < 0.9)
        return "high quality";
    else if (perc < 0.95)
        return "excellent";
    else if (perc < 0.99)
        return "exquisite";
    else
        return "masterpiece";
}

setup.ob_creating.set_art_name = function(art)
{
    let quality = this.label_art_quality(art);
    let name;

    let type = art.artType;
    if (type == "photograph" && art.mediumType == "digital")
        type = "digital photograph";

    if (art.subjectType == "portrait" && art.subject.length == 1 && V.pc.equals(art.subject[0]))
    {
        let exposedparts = art.exposed[0];
        let costume = art.costume ? art.costume[0] : null;

        exposedparts = setup.ob_decode_bitwise_array(setup.ob_creating.possiblePartsExposed, exposedparts);

        let descriptors = [];
        if (exposedparts.includesAny(["penis", "vagina"]))
        {
            descriptors.push("nude");
        }
        else if (exposedparts.includes("chest"))
        {
            descriptors.push("topless");
        }
        if (!exposedparts.includes("face"))
        {
            descriptors.push("masked");
        }

        let descriptor = setup.ob_and(descriptors, "", "", " ");

        name = `${quality} ${descriptor} self-portrait ${type}`;
    }
    else if (art.subjectType == "portrait")
    {
        let subjectnames = [];
        for (let subject of art.subject)
        {
            let i = art.subject.indexOf(subject);

            let exposedparts = art.exposed[i];
            let costume = art.costume ? art.costume[i] : null;

            exposedparts = setup.ob_decode_bitwise_array(setup.ob_creating.possiblePartsExposed, exposedparts);

            let config = {
                assumeclothes: true,
            }
            let descriptors = [];
            if (exposedparts.includesAny(["penis", "vagina"]))
            {
                descriptors.push("nude");
                config.nudelabel = true;
            }
            else if (exposedparts.includes("chest"))
            {
                descriptors.push("topless");
            }
            if (!exposedparts.includes("face"))
            {
                descriptors.push("masked");
                config.includedmark = false;
            }
            if (costume)
            {
                config.costume = costume;
            }

            let descriptor = setup.ob_and(descriptors, "", "", " ");

            let pname;
            if (V.pc.equals(subject))
            {
                if (descriptors.length > 0)
                    pname = `your ${descriptors} self`;
                else
                    pname = "yourself";
            }
            else if (setup.people.is_known(subject))
            {
                pname = setup.people.fullname(subject);
                if (descriptors.length > 0)
                    pname = `${setup.ob_a_or_an(descriptor)} ${descriptor} ${pname}`;
            }
            else
            {
                let npc = setup.people.expand(subject);
                pname = npc.get_anonymous_name(config);
                if (descriptors.length > 0)
                    pname = `${setup.ob_a_or_an(descriptor)} ${descriptor} ${pname}`;
                else
                    pname = `${setup.ob_a_or_an(pname)} ${pname}`;
            }
            subjectnames.push(pname);
        }
        name = `${quality} ${art.subType} ${type} of ${setup.ob_and(subjectnames)}`;
    }
    else if (art.subjectType == "landscape")
    {
        let subject = setup.ob_get_location_name(art.subject[0]);
        name = `${quality} ${art.subjectType} ${type} of ${subject}`;
    }
    else if (art.subjectType == "abstract")
    {
        // also handle art commissions here
        if (art.commission)
        {
            name = `${quality} ${art.commission}`;
        }
        else
        {
            let subject = setup.ob_get_location_name(art.subject[0]);
            name = `${quality} ${art.subjectType} ${type} of ${subject}`;
        }
    }
    else
    {
        let subject = art.subject[0];
        name = `${quality} ${art.subjectType} ${type} of ${subject}`;
    }

    if (art.mediumType == "physical")
        name += ` on ${art.medium}`;

    name = name.replace('  ', ' ');

    art.name = name;

    return name;
}

setup.ob_creating.convert_type = function(art, newtype, add = true)
{
    let newart = Object.assign({}, art);
    newart.mediumType = newtype;
    if (newtype == "physical")
    {
        newart.medium = "paper";
    }
    else
    {
        newart.medium = "memory disk";
    }

    newart.onSale = false;
    delete newart.dayPublished;

    this.set_art_name(newart);
    if (add) V.createdart.push(newart);
    return newart;
}

setup.ob_creating.matching_art = function(art1, art2, crossmedium = true)
{
    const check = ["artType", "subject", "subType", "quality", "dayFinished", "finished"];
    if (!crossmedium) check.push("medium", "mediumType");
    for (let key of check)
        if (art1[key] != art2[key])
            return false;
    return true;
}

setup.ob_creating.has_digital_copy = function(art)
{
    return this.has_copy_of_medium_type(art, "digital");
}

setup.ob_creating.has_physical_copy = function(art)
{
