}

setup.ob_creating.has_copy_of_medium_type = function(art, type)
{
    return V.createdart.some(otherart => this.matching_art(art, otherart) && otherart.mediumType == type);
}

setup.ob_creating.art_published_on_day = function(day = V.gameday)
{
    let count = 0;
    for (let art of V.createdart)
    {
        if (art.dayPublished == day)
            count++;
    }
    return count;
}

setup.ob_creating.art_currently_on_sale = function()
{
    if (!V.createdart) return 0;
    return V.createdart.filter(art => art.onSale && V.gameday - art.dayPublished <= 30).length;
}

setup.ob_creating.base_art_sales = function(art)
{
    let rating = art.quality;

    let mult = 0.8 + (0.4 * State.random());

    mult *= 0.025; // base balancing adjustment

    mult *= Math.max(V.artistnotoriety / 1500, 0.05); // divide by 1500 to make passive art income simply less than book income (commissions should make up difference)

    return Math.max(rating * mult, 1/28);
}

setup.ob_creating.art_sales_today = function(art)
{
    let dayssince = V.gameday - art.dayPublished;
    let decay = Math.pow(dayssince + 1, -0.25);

    let basesales = this.base_art_sales(art);

    let pubonday = this.art_published_on_day(art.dayPublished); // penalize for publishing multiple times a day
    if (pubonday > 2)
    {
        basesales *= (2 + (1 - Math.pow(0.5, pubonday - 2))) / pubonday;
    }
    let allpubbed = this.art_currently_on_sale(); // diminishing returns for having a huge portfolio
    if (allpubbed > 3)
    {
        let penalty = Math.sqrt(3 / allpubbed);
        basesales *= penalty;
    }

    if (!art.fractionalSales) art.fractionalSales = 0;
    art.fractionalSales += (basesales * decay);

    let wholesales = Math.floor(art.fractionalSales);
    art.fractionalSales -= wholesales;

    return [wholesales, art.fractionalSales];
}

setup.ob_creating.art_money_today = function(art, sales)
{
    return setup.ob_adjust_income(sales * 15, "creative");
}

setup.ob_creating.daily_tick_art = function()
{
    if (!V.createdart || V.createdart.length == 0) return;

    if (!V.artistnotoriety) V.artistnotoriety = 0;

    let totalsalestoday = 0;

    const remove = [];
    let currentart = 0;
    let totalquality = 0;
    for (let art of V.createdart.filter(art => art.onSale && V.gameday - art.dayPublished > 0))
    {
        let dayssince = V.gameday - art.dayPublished;
        if (dayssince > 90)
        {
            if (!tags().includes("util")) remove.push(art); // checking for this tag should ensure we're not working on art when the array index changes
        }
        else if (dayssince > 30)
        {
            delete art.newmoney;
            delete art.newsales;

            if (idb.active)
                continue;
            else
                if (!tags().includes("util")) remove.push(art);
        }
        else
        {
            currentart++;

            if (!V.artincome) V.artincome = 0;

            let wholeandfracsales = this.art_sales_today(art);
            let newsales = wholeandfracsales[0];
            let newmoney = this.art_money_today(art, newsales);

            art.newsales = newsales;
            art.newmoney = newmoney;
            art.numberSold += newsales;
            art.earned += newmoney;

            V.artincome += newmoney;

            totalsalestoday += newsales + wholeandfracsales[1];

            let decay = Math.pow(dayssince + 1, -0.25);
            totalquality += (art.quality * decay);
        }
    }

    let addnoto = totalsalestoday / 5;
    if (Number.isFinite(addnoto) && currentart > 0)
    {
        let qualitybasedfloor = Math.max(Math.round((totalquality / currentart) / 100), 1);

        V.prevartistnotoriety = V.artistnotoriety;
        V.artistnotoriety += Math.round(Math.max(addnoto, qualitybasedfloor));
        V.artistnotoriety = Math.clamp(V.artistnotoriety, 0, 1000);
    }

    for (let art of remove)
        V.createdart.delete(art);

    this.remove_old_commissions();
    if (this.due_for_commission())
    {
        let photoorart = setup.ob_randomrelfreq(["art", V.pc.skill_level("Artistic") * 100, "photo", V.pc.skill_level("Photography") * 100]);
        if (photoorart == "art")
        {
            this.add_random_art_commission();
        }
        else
        {
            this.add_random_photo_commission();
        }
    }
}

setup.ob_creating.refresh_art_names = function()
{
