        V.createdart.forEach(art => this.set_art_name(art));
}

setup.ob_creating.pick_commission_points = function(commtype, gender, count = 2)
{
    const comminfo = this.artCommissions[commtype];
    const refpoints = comminfo.referencePoints;
    let retval = [];
    let categoriesused = [];
    while (retval.length < count)
    {
        let newpoint = setup.ob_randomchoice(refpoints.filter(point => !categoriesused.includes(setup.turnons[point].category) && (!setup.turnons[point].part || setup.ob_get_gender_node(gender, "parts").includes(setup.turnons[point].part))));
        retval.push(newpoint);
        categoriesused.push(setup.turnons[newpoint].category);
    }
    return retval;
}

setup.ob_creating.pick_commission_subs = function(commtype)
{
    const comminfo = this.artCommissions[commtype];
    let retval = [];
    for (const [subname, subs] of Object.entries(comminfo))
        if (subname.indexOf("sub ") == 0)
            retval.push([subname.substring(4), setup.ob_randomchoice(subs)]);
    return retval;
}

setup.ob_creating.pick_commission_gender = function(commtype)
{
    return setup.ob_randomrelfreq(V.towniegenderdistribution);
}

setup.ob_creating.pick_commission_subject_dress = function(commtype)
{
