    return setup.ob_randomrelfreq(comminfo.dress);
}

setup.ob_creating.pick_commission_arttype = function(commtype)
{
    let freqpick = [];
    for (let [arttype, artinfo] of Object.entries(setup.ob_creating.artTypes))
        if (artinfo.commissionFrequency)
            freqpick.push(arttype, artinfo.commissionFrequency);
    return setup.ob_randomrelfreq(freqpick);
}

setup.ob_creating.has_feature_in_reference = function(art, turnon)
{
    for (let subj of art.subject)
    {
        if (setup.turnons[turnon].part && ["penis", "vagina", "nipples"].includes(setup.turnons[turnon].part))
        {
            let exposedparts = art.exposed[art.subject.indexOf(subj)];
            exposedparts = setup.ob_decode_bitwise_array(setup.ob_creating.possiblePartsExposed, exposedparts);
            if (!exposedparts.includes(setup.turnons[turnon].part)) return false;
        }

        if (V.pc.equals(subj) && V.pc.has_turnon_characteristic(turnon))
            return true;
        else if (subj in V.people && setup.people.has_turnon(subj, turnon))
            return true;
    }
    return false;
}

setup.ob_creating.has_gender_in_reference = function(art, gender)
{
    for (let subj of art.subject)
        if (setup.people.get_gender(subj) == gender) return true;
    return false;
}

setup.ob_creating.describe_commission = function(commission)
{
    // basically we need to sub in the arttype and whatever else

    if (commission.artType == "photograph")
    {
        return setup.ob_creating.photoCommissions[commission.type].label;
    }

    let name = this.artCommissions[commission.type].name;

    let gender = commission.gender;
    let subjname = setup.people.pronouns(setup.ob_nearest_cisgender(gender)).noun;
    if (subjname == "person") subjname = "non-binary person";

    if (gender == "nonbinary afab" || gender == "nonbinary amab")
        gender = "non-binary";
    else if (gender == "transgender male")
        gender = "male";
    else if (gender == "transgender female")
        gender = "female";

    if (commission.dress != "clothed")
        subjname = commission.dress + " " + subjname;

    name = name.replace("%artType", commission.artType).replace("%subject", `${setup.ob_a_or_an(subjname)} ${subjname}`).replace("%gender", `${setup.ob_a_or_an(gender)} ${gender}`);

    for (let [subkey, subval] of commission.subs)
        name = name.replace('%' + subkey, subval);

    return name;
}

setup.ob_creating.suitability_as_reference = function(comm, art)
{
    if (art.artType == "doodle" || art.subjectType != "portrait") return 0;
    let total = 0;
    let matched = 0;
    for (let ref of comm.referencePoints)
    {
        total++;
        if (this.has_feature_in_reference(art, ref))
            matched++;
    }

    total++;
    if (this.has_gender_in_reference(art, comm.gender))
        matched++;

    if (!total) return 1;
    else return matched / total;
}

setup.ob_creating.due_for_commission = function()
{
    // will we get a new commission today?
    if (!V.artcommissions || !V.artcommissions.open) return false;

    if (V.artcommissions.commissions.length >= 3) return false;

    if (V.pc.skill_level("Artistic") < 1 && V.pc.skill_level("Photography") < 1) return false;

    let factor = (((Math.max(V.pc.skill_level("Artistic") / 10, V.pc.skill_level("Photography") / 10)) * 0.3) + ((V.artistnotoriety / 1000)) * 0.7);

    let since = V.gameday - V.artcommissions.lastCommission;

    let cooldown = 7 - (factor * 2);

    if (since < cooldown) return false;

    return State.random() < 0.2 + (factor * 0.2);
}

setup.ob_creating.add_random_art_commission = function()
{
    let refpoints;
    if (V.artistnotoriety < 250)
        refpoints = setup.ob_randomrelfreq([1, 150, 2, 50]);
    else if (V.artistnotoriety < 500)
        refpoints = setup.ob_randomrelfreq([1, 100, 2, 50, 3, 10]);
    else if (V.artistnotoriety < 750)
        refpoints = setup.ob_randomrelfreq([1, 50, 2, 100, 3, 50]);
    else
        refpoints = setup.ob_randomrelfreq([1, 20, 2, 100, 3, 100]);

    let commtype = setup.ob_randomchoice(Object.keys(setup.ob_creating.artCommissions));
    let gender = this.pick_commission_gender(commtype);
    let comm = {
        type: commtype,
        artType: this.pick_commission_arttype(commtype),
        gender: gender,
        dress: this.pick_commission_subject_dress(commtype),
        subs: this.pick_commission_subs(commtype),
        referencePoints: this.pick_commission_points(commtype, gender, refpoints),
        viewed: false,
    };

    V.artcommissions.commissions.push(comm);

    V.artcommissions.lastCommission = V.gameday;

    return comm;
}

setup.ob_creating.add_random_photo_commission = function()
{
    let picks = [];
    for (let [type, info] of Object.entries(setup.ob_creating.photoCommissions))
        if (V.artistnotoriety >= info.notorietyReq)
            picks.push(type, info.frequency);

    let commtype = setup.ob_randomrelfreq(picks);
    let client = setup.ob_creating.find_photo_client(commtype);
    let comm = {
        type: commtype,
        artType: "photograph",
        viewed: false,
        client: client,
    };

    V.artcommissions.commissions.push(comm);

    V.artcommissions.lastCommission = V.gameday;

    return comm;
}

setup.ob_creating.any_unviewed_commissions = function()
{
    if (!V.artcommissions) return false;
    return V.artcommissions.commissions.some(comm => !comm.viewed);
}

setup.ob_creating.art_for_reference = function(comm)
{
    let retval = [];
    for (let art of V.createdart)
    {
        let rating = this.suitability_as_reference(comm, art);
        if (rating)
            retval.push([art, rating]);
    }
    retval.sort((a, b) => b[1] - a[1]);
    return retval.slice(0, 3);
}

setup.ob_creating.find_photo_client = function(type, tries = 0)
{
    if (tries > 50) return;

    let config = {likes: true, type: ["student", "townie"]};

    switch (type)
    {
        case "pet":
        {
            if (State.random() < 0.5)
                config.cat = true;
            else
                config.dog = true;

            break;
        }
        case "cosplay":
        {
            if (State.random() < 0.4)
                config.type = "student";
            else
                config.type = "townie";

            config.skills = ["Intellectual"];
            config.hobby = "nerd stuff";

            if (State.random() < 0.65)
            {
                config.attractionfrompc = true;
            }

            break;
        }
        case "boudoir":
        {
            if (State.random() < 0.3)
                config.type = "student";
            else
                config.type = "townie";

            if (State.random() < 0.2)
            {
                config.haspartner = true;
                config.notpartner = true;
                config.inclinations = "just_submissive";
            }
            else
            {
                config.notpartner = true;
                config.inclinations = "just_exhibitionist";
            }
            config.strictinclinations = tries < 30;

            if (State.random() < 0.8 && V.pcsexualprefs.includesAny(["female", "transgender female"]))
            {
                config.femme = true;
            }
            config.attractionfrompc = true;

            break;
        }
        case "nude":
        {
            if (State.random() < 0.5)
                config.type = "student";
            else
                config.type = "townie";

            if (State.random() < 0.2)
            {
                config.haspartner = true;
                config.notpartner = true;
                config.inclinations = "just_submissive";
            }
            else
            {
                config.notpartner = true;
                config.inclinations = "just_exhibitionist";
            }
            config.strictinclinations = tries < 30;

            if (State.random() < 0.7 && V.pcsexualprefs.includesAny(["female", "transgender female"]))
            {
                config.femme = true;
            }
            config.attractionfrompc = true;

            break;
        }
        default:
        {

        }

    }

    if (V.artcommissions?.commissions)
        config.exclude = V.artcommissions.commissions.filter(comm => comm.artType == "photograph").map(comm => comm.client);

    let retval = setup.ob_events.pick_person(config, Object.keys(V.people));
    if (retval) return retval;

    delete config.likes;
    retval = setup.ob_events.pick_person(config, Object.keys(V.people));

    if (!retval) return setup.ob_creating.find_photo_client(type, tries + 1);
    else return retval;
}

setup.ob_creating.pc_is_art_subject = function(art)
{
    if (art.subjectType != "portrait") return false;
    return art.subject.some(subj => V.pc.equals(subj));
}

setup.ob_creating.exhibitionism_to_post = function(art)
{
    if (!this.pc_is_art_subject(art)) return 0;

    let exposedparts = art.exposed[art.subject.indexOf("PC")];
    exposedparts = setup.ob_decode_bitwise_array(setup.ob_creating.possiblePartsExposed, exposedparts);

    let exhib = 0;
    if (exposedparts.includesAny(["vagina", "penis"]))
        exhib = 5;
    else if (exposedparts.includesAny(["butt", "breasts"]))
        exhib = 4;

    if (exhib > 0 && !exposedparts.includes("face"))
        exhib -= 2;

    if (art.artType != "photograph")
        exhib -= 1;

    exhib = Math.clamp(exhib, 0, 10);

    return exhib;
}

setup.ob_creating.remove_old_commissions = function()
{
    if (V.artcommissions?.commissions)
        V.artcommissions.commissions = V.artcommissions.commissions.filter(comm => !comm.issued || V.gameday - comm.issued <= 7);
}
