setup.ob_creating.rest_cost = function(skill)
{
    // things are more draining when you're inexperienced
    if (typeof skill == "string")
        skill = V.pc.skill_level(skill);

    return [-30, -25, -20, -18, -17, -15, -14, -13, -12, -11, -10][skill];
}

setup.ob_creating.books_published_on_day = function(day = V.gameday)
{
    let count = 0;
    for (let book of V.createdbooks)
    {
        if (book.dayPublished == day)
            count++;
    }
    return count;
}

setup.ob_creating.books_currently_on_sale = function()
{
    if (!V.createdbooks) return 0;
    return V.createdbooks.filter(book => book.onSale && V.gameday - book.dayPublished <= 30).length;
}

setup.ob_creating.base_book_sales = function(book)
{
    let rating = book.quality;

    let mult = 0.8 + (0.4 * State.random());

    mult *= 0.025;

    mult *= (0.25 + (0.75 * (V.authornotoriety / 1000)));

    return Math.round(Math.max(rating * mult, 1 + 2 * State.random()));
}

setup.ob_creating.book_sales_today = function(book)
{
    let dayssince = V.gameday - book.dayPublished;
    let decay = Math.pow(dayssince + 1, -0.25);

    let basesales = this.base_book_sales(book);

    let pubonday = this.books_published_on_day(book.dayPublished);  // penalize for publishing multiple times a day
    if (pubonday > 2)
    {
        basesales *= (2 + (1 - Math.pow(0.5, pubonday - 2))) / pubonday;
    }
    let allpubbed = this.books_currently_on_sale(); // diminishing returns for having a huge portfolio
    if (allpubbed > 3)
    {
        let penalty = Math.sqrt(3 / allpubbed);
        basesales *= penalty;
    }

    return Math.round(basesales * decay);
}

setup.ob_creating.book_money_today = function(book, sales)
{
    return setup.ob_adjust_income(sales * 5, "creative");
}

setup.ob_creating.daily_tick_books = function()
{
    if (!V.createdbooks || V.createdbooks.length == 0) return;

    if (!V.authornotoriety) V.authornotoriety = 0;

    let totalsalestoday = 0;

    const remove = [];
    for (let book of V.createdbooks.filter(book => book.onSale && V.gameday - book.dayPublished > 0))
    {
        let dayssince = V.gameday - book.dayPublished;
        if (dayssince > 90)
        {
            if (!tags().includes("util")) remove.push(book); // checking for this tag should ensure we're not working on a book when the array index changes
        }
        else if (dayssince > 30)
        {
            delete book.newmoney;
            delete book.newsales;

            if (idb.active)
                continue;
            else
                if (!tags().includes("util")) remove.push(book);
        }
        else
        {
            if (!V.bookincome) V.bookincome = 0;

            let newsales = this.book_sales_today(book);
            let newmoney = this.book_money_today(book, newsales);

            book.newsales = newsales;
            book.newmoney = newmoney;
            book.numberSold += newsales;
            book.earned += newmoney;

            V.bookincome += newmoney;

            totalsalestoday += newsales;
        }
    }

    let addnoto = totalsalestoday / 5;
    if (Number.isFinite(addnoto) && addnoto > 0)
    {
        V.prevauthornotoriety = V.authornotoriety;
        V.authornotoriety += Math.round(Math.max(addnoto, 20));
        V.authornotoriety = Math.clamp(V.authornotoriety, 0, 1000);
    }

    for (let book of remove)
        V.createdbooks.delete(book);
}

setup.ob_creating.store_crosssave_book = function(book)
{
    if (idb.active)
    {
        let catinfo = setup.ob_creating.bookTypes[book.type];
        let newbook = {
            name: book.title,
            description: book.description,
            length: catinfo.length,
            needs: catinfo.needs,
            price: 20,
            type: book.type,
        }

        let crosssavebooks = recall("crosssavebooks") || [];

        if (!crosssavebooks.some(book => book.name == newbook.name))
        {
            crosssavebooks.push(newbook);
            memorize("crosssavebooks", crosssavebooks);
        }

        return crosssavebooks;
    }
}
