setup.ob_gender_db = function(species = "human")
{
    return V.species[species]["genders"];
}

setup.get_gender = function(gender, species = "human")
{
    if (gender in setup.species[species].genders)
        return setup.species[species].genders[gender];
    else
        return setup.ob_gender_db(species)[gender];
}

setup.ob_get_gender_node = function(gender,node,species = "human")
{
    return this.get_gender(gender, species)[node];
}

setup.ob_init_genders = function()
{
    State.setVar("$species", {});

    console.log("WorldGen: generating preset genders");

    setup.ob_generate_gender_presets();
}

setup.ob_generate_gender_presets = function()
{
    // only function here now is to prepare data structure for custom gender
    if (!("human" in V.species))
    {
        V.species["human"] = {};
    }

    let human_db = V.species["human"];

    if (!("genders" in human_db))
    {
        human_db["genders"] = {};
    }
}

setup.ob_add_custom_gender = function(label, labelyoung, pronouns, parts, grows_beard, attraction, roommate_genders)
{
    let db = setup.ob_gender_db();
    let gender = "";
    let i = 0;

    // If we want the user to be able to create multiple custom genders, we'll need to generate unique nodes for those.
    // For now, we just overwrite the "custom" node with whatever the user just set.

    db["custom"] = {
        "label": label,
        "choice label": "a " + label,
        "labelyoung": labelyoung,
        "pronouns": pronouns,
        "parts": this.assemble_parts(parts),
        "grows_beard": grows_beard,
        "attraction": attraction,
        "roommate genders": roommate_genders,
    }

    // We also need to make the appropriate preset attractions attracted to the custom gender
    for (gender in db)
    {
        if (gender != "custom")
        {
            for (i in db[gender]["attraction"])
            {
                if (typeof db[gender]["attraction"][i] == "object")
                {
                    // We treat all attractions as attracted to any nonbinary custom gender (only straight cisgender presets aren't attracted to
                    // both nonbinary afab and nonbinary amab, and it's probably better to err on the side of attraction to the player).
                    // For now we can be a little hacky and check for pronouns ("male" or "female", since we already covered "nonbinary")
                    // in the attraction's genders array because "male" and "female" are used for cisgender male and cisgender female respectively as well.
                    if (pronouns == "nonbinary" || db[gender]["attraction"][i]["genders"].includes(pronouns))
                    {
                        db[gender]["attraction"][i]["genders"].push("custom");
                    }
                }
            }
        }
    }
}

setup.assemble_parts = function(configured_parts)
{
    let parts = ["chest", "stomach", "back", "wrist", "wrist", "forearm", "forearm", "upper arm", "upper arm", "hand", "hand", "neck", "head", "face", "mouth",
        "shoulder", "shoulder", "waist", "hip", "hip", "thigh", "thigh", "crotch", "calf", "calf", "ankle", "ankle", "foot", "foot", "butt", "anus", "nipples"];

    if (configured_parts.includes("breasts"))
    {
        parts.push("breasts");
    }
    if (configured_parts.includes("vagina"))
    {
        parts.push("vagina");
        parts.push("clitoris");
    }
    if (configured_parts.includes("penis"))
    {
        parts.push("penis");
        parts.push("balls");
    }

    return parts;
}

setup.ob_generate_attraction = function(label, genders)
{
    return [ {
         "label": label,
         "genders": genders
    }];
}

setup.is_femme = function(gender, include_nonbinary = false)
{
    // Use include_nonbinary to return nonbinary afab and similar custom genders in addition to female, transgender female, and custom genders with female pronouns

    return (gender == "female" || gender == "transgender female" || (include_nonbinary && gender == "nonbinary afab") || (gender == "custom" && this.custom_is_femme(gender, include_nonbinary)));
}

setup.is_masc = function(gender, include_nonbinary = false)
{
    // Use include_nonbinary to return nonbinary amab and similar custom genders in addition to male, transgender male, and custom genders with male pronouns

    return (gender == "male" || gender == "transgender male" || (include_nonbinary && gender == "nonbinary amab") || (gender == "custom" && this.custom_is_masc(gender, include_nonbinary)));
}

setup.is_enby = function(gender)
{
    return (gender == "nonbinary amab" || gender == "nonbinary afab" || (gender == "custom" && setup.ob_get_gender_node(gender, "pronouns") == "nonbinary"));
}

setup.custom_is_femme = function(gender = "custom", include_nonbinary = false)
{
    let pronouns = setup.ob_get_gender_node(gender, "pronouns");

    if (pronouns == "female")
    {
        return true;
    }
    else if (include_nonbinary && pronouns == "nonbinary")
    {
        let parts = setup.ob_get_gender_node(gender, "parts");
        return (parts.includes("breasts") || parts.includes("vagina"));
    }

    return false;
}

setup.custom_is_masc = function(gender = "custom", include_nonbinary = false)
{
    let pronouns = setup.ob_get_gender_node(gender, "pronouns");

    if (pronouns == "male")
    {
        return true;
    }
    else if (include_nonbinary && pronouns == "nonbinary")
    {
        let parts = setup.ob_get_gender_node(gender, "parts");
        return (!parts.includes("breasts") && parts.includes("penis"));
    }

    return false;
}

setup.ob_pcgender = function()
{
    // returns the pc's gender
    // or the nearest equivalent preset if custom
    if (V.pcgender == "custom")
    {
        const parts = setup.ob_get_gender_node("custom", "parts");
        if (this.custom_is_femme())
        {
            if (parts.includes("penis"))
                return "transgender female";
            else
                return "female";
        }
        else if (this.custom_is_masc())
            if (parts.includes("vagina"))
                return "transgender male";
            else
                return "male";
        else
            if (parts.includes("vagina"))
                return "nonbinary afab";
            else
                return "nonbinary amab";
    }
    else return V.pcgender;
}


