setup.ob_books.book_progress = function(book)
{
    if (!V.bookmemory) return 0;
    if (!V.bookmemory[book]) return 0;
    return V.bookmemory[book];
}

setup.ob_books.add_book_progress = function(book, progress = 1)
{
    if (!V.bookmemory) V.bookmemory = {};
    if (!V.bookmemory[book])
        V.bookmemory[book] = progress;
    else
        V.bookmemory[book] += progress;
    return V.bookmemory[book];
}

setup.ob_books.completed = function(book)
{
    const info = this.get_info(book);
    return this.book_progress(book) >= info.length;
}

setup.ob_books.get_info = function(book)
{
    return this.book_info(book);
}

setup.ob_books.reading_result = function(book, countcap=true)
{
    if (this.completed(book))
        return [false, "You've already read this book."];

    const info = this.get_info(book);

    let anyuncapped = false;
    let anytoraise = false;

    if (info.skills)
    {
        for (const [skill, level] of Object.entries(info.skills))
        {
            const sklevel = V.pc.skill_level(skill);
            const cap = V.optdailyskillcap ? setup.ob_skills.daily_caps[sklevel] : 1000;

            let overleveled = sklevel - level;
            if (overleveled > -3 && overleveled < 3)
                anytoraise = true;

            if (V.skillsraisedtoday == undefined)
            {
                State.setVar("$skillsraisedtoday", {});
            }
            let raisedtoday = V.skillsraisedtoday;
            if (!(skill in raisedtoday))
            {
                anyuncapped = true;
            }
            else
            {
                let allowed = cap - raisedtoday[skill];
                allowed = allowed < 0 ? 0 : allowed;
                if (allowed > 0) anyuncapped = true;
            }
        }
    }

    if (!anytoraise && info.skills)
        return [false, "There is nothing you can learn from reading this."];
    else if (!anyuncapped && countcap && info.skills)
        return [false, "You're a bit fried on this stuff for today. Maybe tomorrow."];
    else
        return [true, ""];
}

setup.ob_books.read = function(book, progress = 1)
{
    const info = this.get_info(book);
    const readresult = this.reading_result(book);
    if (readresult[0])
    {
        if (info.skills)
            for (const [skill, level] of Object.entries(info.skills))
            {
                V.pc.raise_skill(skill, level);
            }
    }
    if (info.needs)
        for (const [need, amount] of Object.entries(info.needs))
        {
            if (amount > 0)
                setup.ob_needs.increase_need(need, amount);
            else
                setup.ob_needs.decrease_need(need, amount);
        }
    this.add_book_progress(book, progress);
}

setup.ob_books.book_info = function(title, findgeneric = true)
{
    return this.books_db()[title] || (
        findgeneric ?
            {
                description: "[description — unwritten #400]",
                length: 60,
                price: 20,
                needs: { "Relaxation": 50 }
            }
            : undefined
    );
}

setup.ob_books.books_db = function()
{
    const now = Date.now();
    if (this.cached_booksdb && now - this.cached_booksdb[0] < 100)
        return this.cached_booksdb[1];

    let db = Object.assign({}, this.db);

    let crosssavebooks = recall("crosssavebooks") || [];
    for (let book of crosssavebooks)
        db[book.name] = book;

    this.cached_booksdb = [now, db];

    return db;
}

setup.ob_books.inventory = function()
{
    if (!setup.ob_dorm_has("bookshelf")) return [];

    const bookshelf = setup.ob_dorm_get("bookshelf");
    return bookshelf.collection || [];
}

setup.ob_books.has = function(book)
{
    return this.inventory().includes(book);
}

setup.ob_books.add = function(book)
{
    if (!setup.ob_dorm_has("bookshelf"))
        setup.ob_dorm_add("bookshelf")
    let bookshelf = setup.ob_dorm_get("bookshelf");
    if (!bookshelf.collection) bookshelf.collection = [];
    bookshelf.collection.push(book);
    setup.ob_set_dormstuff_collection_name(bookshelf);
    return bookshelf.collection;
}

setup.ob_books.remove = function(book)
{
    let bookshelf = setup.ob_dorm_get("bookshelf");
    bookshelf.collection.delete(book);
    if (bookshelf.collection.length == 0)
    {
        setup.ob_dorm_remove("bookshelf");
        return [];
    }
    else
    {
        setup.ob_set_dormstuff_collection_name(bookshelf);
        if (bookshelf.featured && bookshelf.featured.includes(book))
            bookshelf.featured.delete(book);

        return bookshelf.collection;
    }
}
