setup.ob_business.update_save = function(vars)
{
    if (!vars.businesses)
    {
        vars.businesses = {};
        const people = Object.keys(vars.people);
        for (let business of Object.keys(setup.ob_business.db))
        {
            const emps = people.filter(p => vars.people[p].job == business);
            if (emps.length > 0 && this.db[business].count)
            {
