setup.ob_business.attraction_condition_rating = function(condition, name)
{
    const [k, v] = Object.entries(condition)[0];
    const vs = Array.isArray(v) ? v : [v];

    switch (k)
    {
        case "inclination":
        {
            let total = 0;
            vs.forEach(iv => { if (setup.people.has_any_inclination(name, iv)) total += 200 });
            return total;
        }
        case "inclinations":
        {
            let total = 0;
            vs.forEach(iv => { if (setup.people.has_any_inclination(name, iv)) total += 400 });
            return total;
        }
        case "skill":
        {
            let total = 0;
            vs.forEach(iv => { total += setup.people.skill_level(name, iv) * 100 });
            return total;
        }
        case "type":
        {
            return vs.includes(setup.people.get_type(name)) ? 200 : 0;
        }
        case "style":
        {
            return vs.includesAny(setup.people.get_styles(name)) ? 400 : 0;
        }
    }
}

setup.ob_business.raw_attraction_rating = function(config, name)
{
    let rating = 100;

    if (config.studentOnly && setup.people.get_type(name) != "student") return 0;

    if (config.disqualify)
    {
        for (let condition of config.disqualify)
            if (this.attraction_condition_rating(condition, name) > 0) return 0;
    }

    for (let condition of config.pull)
        rating += this.attraction_condition_rating(condition, name);
    for (let condition of config.push)
        rating -= this.attraction_condition_rating(condition, name);

    if (config.baseLikelihood) Math.round(rating *= config.baseLikelihood);

    rating = Math.clamp(rating, 0, 1000);

    return rating;
}

