}

setup.ob_business.entertainment_choice_frequency = function(name, weekend = false)
{
    const relfreq = [];

    for (const business of Object.keys(this.db))
    {
        const binfo = this.db[business];
        if (binfo.entertainment)
        {
            let rating = this.attraction_rating(business, name);

            if (weekend)
            {
                if (binfo.entertainment.weekendMultiplier)
                    rating *= binfo.entertainment.weekendMultiplier;
            }
            else
            {
                if (binfo.entertainment.weekdayMultiplier)
                    rating *= binfo.entertainment.weekdayMultiplier;
            }

            if (rating > 0)
            {
                relfreq.push(business, Math.round(rating));
            }
        }
    }

    const homebodymult = setup.ob_nPCSimulation.homebody_rating(name, weekend ? "Saturday" : "Monday");
    for (const activity of Object.keys(setup.ob_nPCSimulation.homeActivities))
    {
        const ainfo = setup.ob_nPCSimulation.homeActivities[activity];
        let rating = setup.ob_nPCSimulation.activity_attraction_rating(activity, name) * homebodymult;

        if (weekend)
        {
            if (activity.weekendMultiplier)
                rating *= activity.weekendMultiplier;
        }
        else
        {
            if (activity.weekdayMultiplier)
                rating *= activity.weekdayMultiplier;
        }

        if (rating > 0)
        {
            relfreq.push(activity, Math.round(rating));
        }
    }

    return relfreq;
}

