setup.ob_business.open_length = function(business)
{
    // number of houts that a business is open
    const binfo = this.db[business];
    const [open, close] = binfo.hours;
    return (close > open) ? close - open : (24 - open) + close;
}

setup.ob_business.shift_length = function(business)
{
    // shift length in hours (8-5 type jobs are a single shift, places open longer divide their days up more)
    const binfo = this.db[business];
    if (binfo.shiftLength) return binfo.shiftLength;

    const openlength = this.open_length(business);
    if (openlength <= 9)
        return openlength;

    return 6;
}

setup.ob_business.shifts = function(business)
{
    // all shift slots for a business (same for any day)
    const openlength = this.open_length(business);
    const shiftlength = Math.min(openlength, this.shift_length(business));

    const blocks = [];
    let blockcount = Math.ceil(openlength / shiftlength);

    const openhour = this.db[business].hours[0];
    for (let i = 0; i < blockcount; i++)
    {
        let shiftstart = shiftlength * i;
        let shiftend = shiftstart + shiftlength;

        if (shiftend > openlength)
        {
            shiftstart -= shiftend - openlength;
            shiftend = openlength;
        }

        blocks.push([(openhour + shiftstart) % 24, (openhour + shiftend) % 24]);
    }
    return blocks;
}

setup.ob_business.place_npc_in_job = function(npc, business)
{
    // update savedata to give an npc a job and assign their shifts
    let pdata = setup.people.get_person(npc);
