    this.find_and_assign_shifts(npc, business);
}

setup.ob_business.find_and_assign_shifts = function(npc, business)
{
    // assign an npc their shifts while granting them at least two days off
    npc = setup.people.get_name(npc);
    let rng = setup.ob_newRNG(`shift_${business}_${npc}`);
    const blocks = this.shifts(business); // grab shift blocks for this business
    if (!blocks.length) return;

    const shift = [null, null, null, null, null, null, null]; // shifts by day of the week (Sun-Sat)

    const maxdays = 5;
    const occ = this.shift_occupancy(business, [npc]); // grab number of npcs working each shift
    const slots = rng.shuffle(this.eligible_shifts(npc, business)); // grab shifts this npc is able to work (not conflicting with class etc) and shuffle

    // find the emptiest day/shift
    for (let day = 0; day < 7; day++)
    {
        let emptiest = null;
        let emptiest_count = Infinity;
        for (const [d, bi] of slots)
        {
            if (d == day)
            {
                if (occ[d][bi] < emptiest_count)
                {
                    emptiest_count = occ[d][bi];
                    emptiest = bi;
                }
            }
        }

        if (emptiest == null) continue;

        shift[day] = emptiest;
        occ[day][emptiest]++;
    }

    // for each possible day, find a shift this npc can work
    let working = [];
    for (let day = 0; day < 7; day++)
        if (shift[day] != null)
            working.push(day);

    if (working.length > maxdays)
    {
        working = rng.shuffle(working).sort((a, b) => occ[b][shift[b]] - occ[a][shift[a]]); // find the most occupied shifts this npc is working

        for (let day of working.slice(0, working.length - maxdays)) // then drop the two most occupied (least needed) days (if the npc doesn't already have two days off)
        {
            occ[day][shift[day]]--;
            shift[day] = null;
        }
    }

    // finally, assign the shift info
    let pdata = setup.people.get_person(npc);
    pdata.shifts = shift;
    return shift;
}

setup.ob_business.shift_occupancy = function(business, exclude = [])
{
    // get the number of npcs working each shift for each day
    const blocks = this.shifts(business);
    const occ = Array.from({length: 7}, () => new Array(blocks.length).fill(0)); // build a thing where we can track each shift for each day

    for (let p of setup.ob_find_employees(business))
    {
        if (exclude.includes(p)) continue;

        let shift = setup.people.get_person(p).shifts;
        if (!shift) continue;

        for (let day = 0; day < 7; day++)
            if (shift[day] != null && shift[day] < blocks.length)
                occ[day][shift[day]]++;
    }
    return occ;
}

setup.ob_business.eligible_shifts = function(npc, business)
{
    // get all shifts this npc can possibly work (working around classes etc)
    // this is also where weekends are excluded for jobs that are off on weekends (offices etc)
    const blocks = this.shifts(business);
    const lastbell = setup.School.last_bell();
    const student = setup.people.is_student(npc);
    const weekendsoff = !!this.db[business].weekendsOff;
    let slots = [];

    for (let day = 0; day < 7; day++)
    {
        let weekend = day == 0 || day == 6;
        if (weekendsoff && weekend) continue;

        let classestoday = !weekend;

        for (let bi = 0; bi < blocks.length; bi++)
        {
            if (classestoday && student && this.student_hours_left(blocks[bi], lastbell) < 2) // don't overlap with classes, but allow closing shifts (they can arrive late)
                continue;

            slots.push([day, bi]);
        }
    }
    return slots;
}

setup.ob_business.student_hours_left = function(block, earliestarrivalhour)
{
    // number of hours left in a closing shift if we have to truncate it for their class schedule
    const [start, end] = block;
    const e = (end > start) ? end : end + 24;
    return Math.max(0, e - Math.max(start, earliestarrivalhour));
}

setup.ob_business.shift_hours = function(npc, business, day)
{
    // get actually scheduled shift hours
    // (this mostly exists to adjust student closing shifts so they can arrive later)
    if (day == undefined)
        day = setup.ob_time.day_of_week.indexOf(setup.ob_time.weekday());

    const pdata = setup.people.get_person(npc);
    if (!pdata.shifts) return;

    const blocks = this.shifts(business);
    const bi = pdata.shifts[day];
    if (bi == null || bi < 0 || bi >= blocks.length) return;

    let [start, end] = blocks[bi];
    const weekend = day == 0 || day == 6;

    if (setup.people.is_student(npc) && !weekend)
    {
        const lastbell = setup.School.last_bell();
        const e = (end > start) ? end : end + 24;
        if (lastbell > start && lastbell < e)
            start = lastbell;
    }

    return [start, end];
}

setup.ob_business.is_working = function(npc, business, day, hour)
{
    // top-level method: is this npc working now?
    // (all parameters except npc are optional)
    // (if given only npc, it will check if npc is working at their job)
    // (if given a job too, it will check if npc is working -that- job specifically)
    let pdata = setup.people.get_person(npc);

    if (business == undefined)
        business = pdata.job;
    if (day == undefined)
        day = setup.ob_time.day_of_week.indexOf(setup.ob_time.weekday());
    if (hour == undefined)
        hour = V.hour;

    if (business != pdata.job) return false;

    let actualshift = this.shift_hours(npc, business, day);
    if (!actualshift) return false;

    let [start, end] = actualshift;
    return (end > start) ? (hour >= start && hour < end) : (hour >= start || hour < end);
}

setup.ob_business.get_job = function(npc)
{
    return setup.people.get_job(npc);
}
