setup.clothes.validate = function(log_to_console = true)
{
    const validation_log = setup.clothes.validateClothingDatabase(setup.clothes);
    const result = { info: [], errors: [], warnings: [], count: Object.keys(setup.clothes).length };

    validation_log.forEach(entry => {
        if (entry.Severity === "info") {
            result.info.push(entry);
        } else if (entry.Severity === "warning") {
            result.warnings.push(entry);
        } else { // "critical" and "error" both go into errors
            result.errors.push(entry);
        }
    });

    if (log_to_console) {
        if (result.info.length > 0) {
            console.log("INFO:");
            console.table(result.info);
        }
        if (result.warnings.length > 0) {
            console.warn("WARNINGS:");
            console.table(result.warnings);
        }
        if (result.errors.length > 0) {
            console.error("ERRORS:");
            console.table(result.errors);
        }
        console.log(result.count + " items analyzed.");
        console.log(result.errors.length > 0 ? "Clothes Validation FAILED." : "Clothes Validation PASSED.");
    }

    let shop_result = setup.ob_shops.validate(log_to_console);
    result.info = result.info.concat(shop_result.info);
    result.warnings = result.warnings.concat(shop_result.warnings);
    result.errors = result.errors.concat(shop_result.errors);

    result.success = (result.errors.length === 0);
    return result;
}

