setup.clothes.validateClothingDatabase = function(clothes_db = setup.clothes) {
    const isTypo = (a, b, threshold = 3) => {
        // Normalize: Lowercase, remove spaces
        const normalize = str => str.toLowerCase().replace(/\s+/g, '');
        a = normalize(a);
        b = normalize(b);

        // Count character frequencies inline, weighting early characters more
        const weights = [3, 2, 2, 2];
        const freq = {};
        for (let i = 0; i < a.length; i++) freq[a[i]] = (freq[a[i]] || 0) + (weights[i] ?? 1);
        for (let i = 0; i < b.length; i++) freq[b[i]] = (freq[b[i]] || 0) - (weights[i] ?? 1);

        // Total difference across all characters
        let edits = Object.values(freq).reduce((sum, diff) => sum + Math.abs(diff), 0);
        return edits <= threshold;
    }

    const validateFieldEntryWithTypoCheck = (clothing_key, field, value, validValues, severity = "error") => {
        if (validValues.includes(value)) return [];

        const closestMatch = validValues.find(valid => isTypo(value, valid));
        return [{ Severity: severity, Clothing: clothing_key, Field: field,
            Note: closestMatch
                ? `Found "${value}". Did you mean "${closestMatch}"?`
                : `"${value}" is not a valid entry.`
        }];
    };

    const validateFlags = (clothing_key, clothing_item, flags_field) => {
        return clothing_item[flags_field].flatMap(flag => validateFieldEntryWithTypoCheck(clothing_key, flags_field, flag, setup.ob_clothes_flags));
    };

    const validateStyleFactor = (clothing_key, clothing_item, style_field) => {
        return Object.entries(clothing_item[style_field]).flatMap(([style, value]) => [
            ...validateFieldEntryWithTypoCheck(clothing_key, style_field, style, setup.ob_clothes_styles),
            ...(typeof value !== "number"
                ? [{ Severity: "error", Clothing: clothing_key, Field: style_field, Note: `"${style}" should be a number, found "${typeof value}"` }]
                : [])
        ]);
    };

    const validateCategory = (clothing_key, clothing_item, category_field) => {
        return [...setup.ob_clothes_categories, "other"].includes(clothing_item[category_field]) ? [] :
        [{ Severity: "critical", Clothing: clothing_key, Field: category_field, Note: `"${clothing_item[category_field]}" is not a recognized category.` }];
    };

    const validatePartsList = (clothing_key, clothing_item, parts_field) => {
        const parts_remaining = [...clothing_item[parts_field]];

        for (const part of setup.ob_clothes_parts_complete) {
            const index = parts_remaining.indexOf(part);
            if (index !== -1) parts_remaining[index] = null;
        }

        return parts_remaining.filter(Boolean).map(part => ({
            Severity: "error", Clothing: clothing_key, Field: parts_field,
            Note: setup.ob_clothes_parts_complete.includes(part)
                ? `"${part}" appears too many times."`
                : validateFieldEntryWithTypoCheck(clothing_key, parts_field, part, setup.ob_clothes_parts_complete)[0]?.Note || `"${part}" is not a valid 'part' per the 'gender' arrays."`
        }));
    };

    const validateLayerValues = (clothing_key, clothing_item, layer_field) => {
        const layer = clothing_item[layer_field];
        return layer >= 10 && layer < 50 ? []
            : [{ Severity: "error", Clothing: clothing_key, Field: layer_field, Note: `"${layer}" is out of range. Must be between 10 and 50.` }];
    };

    const validateNameReplacements = (clothing_key, clothing_item, name_field) => {
        const validation_log = [];

        const name_words = clothing_item[name_field].split(/[ ,\'-]/);
        const sub_words = name_words.filter(word => word.startsWith('%')).map(word => word.substring(1));
        const config_names = clothing_item.configurations ? Object.keys(clothing_item.configurations) : [];
        const sub_fields = Object.keys(clothing_item).filter(field => field.startsWith("sub ")).map(field => field.substring(4));

        sub_words.forEach(sub_type => {
            const sub_string = `sub ${sub_type}`;
            if (!config_names.includes(sub_type) && !clothing_item[sub_string]) {
                validation_log.push({ Severity: "error", Clothing: clothing_key, Field: sub_type, Note: `"${sub_string}" missing - needs to be either a "sub" field or configuration.` });
            } else if (clothing_item[sub_string] && typeof clothing_item[sub_string] !== "object") {
                validation_log.push({ Severity: "error", Clothing: clothing_key, Field: sub_string, Note: `"${sub_string}" type "${typeof clothing_item[sub_string]}" found (expected "object").` });
            }
        });

        const unused_subs = sub_fields.filter(sub_type => !sub_words.includes(sub_type));
        unused_subs.forEach(sub_type => {
            validation_log.push({ Severity: "error", Clothing: clothing_key, Field: sub_type, Note: `"sub ${sub_type}" exists but was never referenced in the name.` });
        });

        return validation_log;
    };

    const validateColorArray = (() => {
        let cached_valid_colors = new Set([
            ...setup.ob_clothes_standard_cloth_colors,
            ...setup.ob_clothes_standard_denim_colors,
            ...setup.ob_clothes_standard_leather_colors,
            ...setup.ob_clothes_standard_metals,
            ...setup.ob_clothes_advanced_cloth_colors,
            ...setup.ob_clothes_neon_colors,
            ...Object.keys(setup.ob_color_table),
        ]);
        return Object.assign((clothing_key, clothing_item, color_field) => {
            const seen_colors = new Set();
            const color_log = [];

            clothing_item[color_field]?.forEach(color => {
                if (seen_colors.has(color)) {
                    color_log.push({ Severity: "warning", Clothing: clothing_key, Field: "color validation", Note: `"${color}" is duplicated in ${clothing_key}'s "${color_field}".` });
                }
                seen_colors.add(color);

                if (!cached_valid_colors.has(color)) {
                    color_log.push({ Severity: "error", Clothing: clothing_key, Field: "color validation", Note: `"${color}" is not recognized in ${clothing_key}'s "${color_field}". (edit setup.ob_color_table)` });
                }
            });

            return color_log;
        })
    })();

    const validateConfigurations = (clothing_key, clothing_item, config_field) => {
        const log = [];

        for (const [groupName, groupConfig] of Object.entries(clothing_item[config_field])) {
            if (typeof groupConfig !== "object") {
                log.push({ Severity: "error", Clothing: clothing_key, Field: `${config_field}.${groupName}`, Note: `Expected a sub-object for configuration group "${groupName}".` });
                continue;
            }

            let defaultCount = 0;
            for (const [subKey, subConfig] of Object.entries(groupConfig)) {
                if (subKey === "config_isare" || subKey === "config_description") {
                    if (typeof subConfig !== "string") log.push({ Severity: "error", Clothing: clothing_key, Field: `${config_field}.${groupName}.config_isare`, Note: `Expected "${subKey}" to be a string.` });
                    continue;
                }

                if (typeof subConfig !== "object" || Array.isArray(subConfig)) {
                    log.push({ Severity: "error", Clothing: clothing_key, Field: `${config_field}.${groupName}.${subKey}`, Note: `Expected configuration "${subKey}" to be an object.` });
                    continue;
                }

                for (const [modField, _] of Object.entries(subConfig)) {
                    if (modField === "config_description") continue;
                    if (modField === "config_default") {
                        defaultCount++;
                        continue;
                    }
                    const isModifier = /[+-]$/.test(modField);
                    const baseField = modField.replace(/[+-]$/, "");

                    if (!isModifier) {
                        log.push({ Severity: "error", Clothing: clothing_key, Field: `${config_field}.${groupName}.${subKey}.${modField}`, Note: `Modifier "${modField}" must end with '+' or '-' to indicate intent.` });
                    } else if (!(baseField in clothing_item)) {
                        log.push({ Severity: "error", Clothing: clothing_key, Field: `${config_field}.${groupName}.${subKey}.${modField}`, Note: `Unrecognized base field "${baseField}". No such field on clothing item.` });
                    }
                }
            }

            if (defaultCount > 1) log.push({ Severity: "error", Clothing: clothing_key, Field: `${config_field}.${groupName}`, Note: `Only one "config_default: true" allowed per configuration group.` });
        }

        return log;
    };

    const all_valid_item_fields = {
        "name": { type: String, isRequired: true, validator: validateNameReplacements },
        "shortname": { type: String, isRequired: true },
        "covers": { type: Array, isRequired: true, validator: validatePartsList },
        "category": { type: String, isRequired: true, validator: validateCategory },
        "layer": { type: Number, isRequired: true, validator: validateLayerValues },
        "flags": { type: Array, isRequired: true, validator: validateFlags },
        "price": { type: Number, isRequired: true },

        // Optional fields (Included but not required)
        "style factor": { type: Object, validator: validateStyleFactor },
        "skintight exception": { type: Array, validator: validatePartsList },
        "storage": { type: Array },
        "occupies": { type: Array },
        "style factor mods": { type: Object },
        "configurations": { type: Object, validator: validateConfigurations },
        "dialogue tags": { type: Array },
        "sheer": { type: Array, validator: validatePartsList },
        "gift": { type: Boolean },
        "appeal": { type: Object },
        "covers mods": { type: Object },
        "flags mods": { type: Object },
        "costume factor": { type: Object },
        "name mods": { type: Object },
        "displace": { type: Array, is_prefix: true, validator: validatePartsList },
        "sub": { type: Array, is_prefix: true },
        "sub color": { type: Array, is_prefix: true, validator: validateColorArray },
        "description": { type: String, is_prefix: true },
        "thrift": { type: Array, is_prefix: true },
        "temporary": { type: Boolean },
    };

    const validateItemShopAvailability = (clothing_key, clothing_item, outfits_for_sale) => {
        const validation_log = [];

        const in_outfits = Object.entries(setup.ob_outfits).filter(([_, outfit_contents]) =>
                outfit_contents.items.some(item => item.item === clothing_key)
            ).map(([outfit]) => outfit);
        const not_for_sale_ok = in_outfits.some(outfit => setup.ob_outfits[outfit]?.flags?.includes("not for sale"));

        const available_at = Object.entries(setup.ob_shops.db)
            .flatMap(([shop_name, shop_data]) =>
                shop_data.items?.filter(item => item.type === "clothes" && item.item === clothing_key).map(() => shop_name) || []);

        if (!available_at.length && !clothing_item.temporary) {
            if (!in_outfits.length) {
                validation_log.push({
                    Severity: clothing_item.flags?.some(flag => ["deprecated", "NoShops"].includes(flag)) ? "info" : "error",
                    Clothing: clothing_key, Field: "setup.ob_shops.db",
                    Note: "Not available for purchase or in outfit." +
                        (clothing_item.flags?.includes("NoShops") || clothing_item.flags?.includes("deprecated") ? " (NoShops/deprecated)" : "")
                });
            } else {
                const for_sale = in_outfits.some(outfit => outfits_for_sale.includes(outfit));

                validation_log.push({
                    Severity: for_sale ? "info" : not_for_sale_ok ? "info" : "error",
                    Clothing: clothing_key, Field: "setup.ob_shops.db",
                    Note: `Only available in ${for_sale ? "" : "not-for-sale "}outfits: ${setup.ob_and(in_outfits)}`
                });
            }
        }

        if (available_at.length > 1) {
            validation_log.push({ Severity: "info", Clothing: clothing_key, Field: "setup.ob_shops.db", Note: `Multiple Shops: ${setup.ob_and(available_at)}` });
        }

        return validation_log;
    };

    const validateRequiredFieldsArePresent = (clothing_key, clothing_item) => {
        const required_fields_log = [];
        Object.entries(all_valid_item_fields).forEach(([field, { isRequired }]) => {
            if (isRequired && !(field in clothing_item)) {
                required_fields_log.push({ Severity: "critical", Clothing: clothing_key, Field: field, Note: `"${field}" is a required field.` });
            }
        });
        return required_fields_log;
    }

    const validation_log = [];
    const outfits_for_sale = Object.values(setup.ob_shops.db).flatMap(shop => shop.items?.filter(item => item.type === "outfit").map(item => item.item) || []);

    for (const [clothing_key, clothing_item] of Object.entries(clothes_db)) {
        if (typeof clothing_item === "function") continue; // Ignore setup.clothes helper functions

        validation_log.push(...validateRequiredFieldsArePresent(clothing_key, clothing_item));
        validation_log.push(...validateItemShopAvailability(clothing_key, clothing_item, outfits_for_sale));

        Object.entries(clothing_item).forEach(([field, value]) => {
            const valid_field = all_valid_item_fields[field] ||
                Object.entries(all_valid_item_fields)
                    .filter(([prefix_word, field_config]) => field_config.is_prefix && field.startsWith(prefix_word))
                    .sort(([a], [b]) => b.length - a.length) // Prioritize the longest matching prefix
                    .shift()?.[1];
            if (!valid_field) {
                validation_log.push({ Severity: "warning", Clothing: clothing_key, Field: field, Note: `"${field}" is not a recognized field."` });
                return;
            }

            const actualType = Array.isArray(value) ? Array : value?.constructor;
            if (actualType !== valid_field.type) {
                validation_log.push({ Severity: "critical", Clothing: clothing_key, Field: field, Note: `"${field}" must be of type ${valid_field.type.name}, found "${actualType?.name || "undefined"}".` });
            } else if (valid_field.validator) {
                validation_log.push(...valid_field.validator(clothing_key, clothing_item, field));
            }
        });
    }

    for (const [outfit_key, outfit_info] of Object.entries(setup.ob_outfits))
        for (const outfit_item of outfit_info.items)
            if (!(outfit_item.item in setup.clothes))
                validation_log.push({ Severity: "critical", Clothing: outfit_key, Field: "items", Note: `"${outfit_item.item}" not present in setup.clothes.` });

    return validation_log;
};

