        "cool":"Cool.",
        "slightly warming":"Slightly warming.",
        "moderately warming":"Moderately warming.",
        "heavily warming":"Heavily warming,",
        "very heavily warming":"Very heavily warming,",
        "umbrella":"Protects from rain.",
    };

    if (clothing.flags)
    {
        clothing.flags.forEach(flag => {
            if (flag in flagtext)
            {
                retval.push(flagtext[flag]);
            }
            else if (flag === "dresscode qb" && V.jobs.includes("QuickieBurger"))
            {
                if (!clothingitem)
                    retval.push("Appropriate to wear at QuickieBurger (if solid black).");
                else if (clothingitem.subs)
                {
                    for (const [subkey, subvalue] of Object.entries(clothingitem.subs))
                        if (subkey == "color" && subvalue == "black")
                        {
                            retval.push("Appropriate to wear at QuickieBurger.");
                            break;
