setup.ob_cosmetics.colors_of = function(type)
{
    if (!V.makeup) return [];
    let retval = [];
    for (const [makeup, makeupinfo] of Object.entries(V.makeup))
        if (makeupinfo.slots.includes(type))
            retval.push(makeupinfo.applied.replace(" " + type, ""));
    return retval;
}
