// #region methods

setup.ob_dialogue.lines = function(tags, npc, job = setup.job_at_location())
{
    npc = setup.people.get_name(npc);
    const npcniche = setup.people.find_niche(npc);
    const allniches = Object.keys(V.niches);

    const picks = [];

    for (let i = 0; i < this.db.length; i++)
    {
        if (this.db[i].tags.includesAll(tags))
        {
            if (this.db[i].tags.includesAny(allniches) && !this.db[i].tags.includes(npcniche)) continue; // skip this dialogue if it's for a specific NPC

            let event = Object.assign({}, this.db[i]);

            if (event.inclinations && !("strictinclinations" in event)) event.strictinclinations = true;
            if (event.archetypes && !("strictarchetypes" in event)) event.strictarchetypes = true;
            if (!("specialok" in event)) event.specialok = true;

            if (event.tags.includes("pc") && npc != "PC") continue;
            else if (event.tags.includes("npc") && npc == "PC") continue;

            if (event.furniture)
            {
                let enc = V.encounter;
                if (!enc) continue;
                else
                {
                    let furniture = V.pc.equals(npc) ? V.pc.on_furniture(npc) : enc.pobj(npc).on_furniture(enc.encounter_target);
                    if (event.furniture != furniture) continue;
                }
            }

            if (event.position)
            {
                let enc = V.encounter;
                if (!enc) continue;
                else
                {
                    let pobj = enc.pobj(npc);
                    let enctarget = pobj.encounter_target();
                    let pos = pobj.encounter_target().equals(pobj) ? pobj.position_with(V.partner1) : pobj.position_with(enctarget);
                    const posinfo = setup.ob_sexpositions[pos];

                    let tags = V.pc.equals(npc) ? (V.pc.role_with(npc) == "top" ? posinfo["top dialogue tags"] : posinfo["bottom dialogue tags"]) || []
                                                : (V.pc.role_with(npc) == "top" ? posinfo["bottom dialogue tags"] : posinfo["top dialogue tags"]) || [];

                    if (!event.position.includesAny(tags)) continue;
                }
            }

            const exclusivetags = ["be dominant", "be submissive"];
            let skip = false;
            for (let tag of event.tags)
                if (exclusivetags.includes(tag) && !tags.includes(tag))
                {
                    skip = true;
                    break;
                }

            if (skip) continue;

            if (event.kink && !V.kinkcontent.includes(event.kink)) continue;

            let rating = 0;
            if (npc == "PC")
            {
                if (event.inclinations)
                {
                    if (V.pc.has_any_inclination(event.inclinations))
                        rating += 1000;
                    else if (event.strictinclinations)
                        continue;
                }
                if (event.noinclinations)
                    if (V.pc.has_any_inclination(event.noinclinations))
                        continue;
            }
            else if (npc)
            {
                rating = setup.ob_events.pick_person(event, [npc], job, false);
                if (rating.length == 0) continue;
                rating = rating[1];
            }

            if (event.checkvar && !Scripting.evalTwineScript(event.checkvar)) continue;

            for (let line of event.content)
            {
                let infopackage = Object.assign({}, event);
                delete infopackage.content;
                infopackage.rating = rating * (event.frequencyMultiplier || 1);
                infopackage.npc = setup.people.get_name(npc);
                infopackage.job = job;
                infopackage.line = line;
                picks.push(infopackage);
            }
        }
    }
    return picks;
}

setup.ob_dialogue.pick = function(tags, npc, job = setup.job_at_location(), rng = setup.ob_newRNG())
{
    const picks = this.lines(tags, npc, job);
    if (false && picks.length == 0)
    {
        /* taking this warning out since there are intentionally no lines in a lot of cases these days
        console.warn("No dialogue line found!",
        "tags = ", tags,
        "npc = ", setup.people.get_name(npc),
        );
        */
    }
    return this.pick_from_lines(picks, rng);
}

setup.ob_dialogue.pick_from_lines = function(lines, rng = setup.ob_newRNG())
{
    if (lines.length == 0) return null;
    lines = rng.shuffle(lines);
    lines.sort((a,b) => (b.rating*rng.random() - a.rating*rng.random()));
    return lines[0];
}

setup.ob_dialogue.parse = function(info, npc, subs = [])
{
    let line;
    if (typeof info == "object")
    {
        line = info.line;
    }
    else
    {
        line = info;
        info = {};
    }
    const words = line.split(/[ ,\'-]/);
    const sub_words = words.filter((word) => word[0] == '%');
    const npcname = setup.people.get_name(npc);
    for (let sub of sub_words)
    {
        if (sub.indexOf("%dialogue_") == 0)
        {
            let tags = sub.split('_');
            tags.deleteAt(0);
            while ([".", ",", "!", "?"].includes(tags[tags.length - 1][tags[tags.length - 1].length - 1]))
                tags[tags.length - 1] = tags[tags.length - 1].substring(0, tags[tags.length - 1].length - 1);
            const replacewith = this.pick(tags, npc);
            line = line.replace(sub, replacewith.line);
        }
        else if (sub == "%n")
        {
            line = line.replace(sub, `<<encountername "${npcname}">>`);
        }
        else if (sub == "%N")
        {
            line = line.replace(sub, `<<encounternamec "${npcname}">>`);
        }
        else if (sub.indexOf("%p") == 0)
        {
            // pronoun widget
            let widget = sub.substring(1);
            if ([".", ",", "!", "?"].includes(widget[widget.length - 1]))
                widget = widget.substring(0, widget.length - 1);
            line = line.replace(sub, `<<${widget} "${npcname}">>`);
        }
        else if (sub.indexOf("%conj_") == 0)
        {
            const tags = sub.split('_');
            tags.deleteAt(0);
            let verb = tags[0];
            if ([".", ",", "!", "?"].includes(verb[verb.length - 1]))
                verb = verb.substring(0, verb.length - 1);
            line = line.replace(sub, `<<conjname "${npcname}" ${verb}>>`);
        }
        else if (sub.indexOf("%conjp_") == 0)
        {
            // pronoun version of conj
            const tags = sub.split('_');
            tags.deleteAt(0);
            let verb = tags[0];
            if ([".", ",", "!", "?"].includes(verb[verb.length - 1]))
                verb = verb.substring(0, verb.length - 1);
            line = line.replace(sub, `<<conj "${npcname}" ${verb}>>`);
        }
    }
    for (let sub of subs)
    {
        while (line.includes(sub[0]))
            line = line.replace(sub[0], sub[1]);
    }
    info.line = line;
    return info;
}

setup.ob_dialogue.visible_clothing_tags = function()
{
    // return an array of dialogue tags utilized by visible clothing items
    const clothes = V.pc.visible_clothing_items();
    const retval = [];
    for (let item of clothes)
    {
        const tags = setup.clothes[item.item]["dialogue tags"];
        if (tags)
        {
            retval.push([item, tags]);
        }
    }
    return retval;
}

setup.ob_dialogue.visible_tattoo_tags = function()
{
    const tats = V.pc.visible_tattoos();
    const retval = [];
    for (let tat of tats)
    {
        const tags = setup.ob_cosmetics.tattoos[tat[0]]["dialogue tags"];
        if (tags)
        {
            retval.push([tat, tags]);
        }
    }
    return retval;
}

setup.ob_dialogue.has_something_to_say = function(npc, friendlytag = "friendly")
{
    for (let ctags of this.visible_clothing_tags())
    {
        for (let tag of ctags[1])
        {
            let lines = this.lines(["clothes", friendlytag, tag], npc);
            if (lines.length > 0) return true;
        }
    }

    for (let ttags of this.visible_tattoo_tags())
    {
        for (let tag of ttags[1])
        {
            let lines = this.lines(["tattoo", friendlytag, tag], npc);
            if (lines.length > 0) return true;
        }
    }

    for (let sttags of V.pc.evident_styles())
        {
            for (let tag of sttags)
            {
                let lines = this.lines(["style", friendlytag, tag], npc);
                if (lines.length > 0) return true;
            }
        }

    return false;
}

setup.ob_dialogue.commentary_line = function(npc, friendlytag = "friendly")
{
    const retval = [];

    for (let ctags of this.visible_clothing_tags())
    {
        for (let tag of ctags[1])
        {
            let pick = this.pick(["clothes", friendlytag, tag], npc);
            if (pick)
            {
                pick.clothing = ctags[0];
                retval.push(pick);
            }
        }

    }

    for (let ttags of this.visible_tattoo_tags())
    {
        for (let tag of ttags[1])
        {
            let pick = this.pick(["tattoo", friendlytag, tag, ttags[0][1]], npc);
            if (pick)
            {
                pick.tattoo = ttags[0][0];
                retval.push(pick);
            }
            else
            {
                pick = this.pick(["tattoo", friendlytag, tag, "nolocation"], npc);
                if (pick)
                {
                    pick.tattoo = ttags[0][0];
                    retval.push(pick);
                }
            }
        }

    }

    for (let tag of V.pc.evident_styles())
    {
        let pick = this.pick(["style", friendlytag, tag], npc);
        if (pick)
        {
            pick.style = tag;
            retval.push(pick);
        }
    }

    return setup.ob_randomchoice(retval);
}

setup.ob_dialogue.encounter_lines = function(npc)
{
    if (!V.encounter) return [];

    const retval = [];

    const extratags = npc.encounter_dialogue_tags || [];

    if (V.pc.equals(npc))
        V.dialoguetarget = V.partner1;
    else
        V.dialoguetarget = V.pc;

    let enc = V.encounter;
    for (let i = 0; i < enc.acts.length; i++)
    {
        let act = enc.acts[i];
        if (act.narrate)
        {
            let subj = enc.find_state_entity(enc.acts[i].subject);
            let obj = enc.find_state_entity(enc.acts[i].object);

            if (!subj.equals(npc) && !obj.equals(npc)) continue;

            let tags;
            let partner;
            if (subj.equals(npc))
            {
                tags = act["subject dialogue tags"];
                partner = obj;
            }
            else
            {
                tags = act["object dialogue tags"];
                partner = subj;
            }
            tags = tags || [];

            for (let tag of tags)
            {
                let lines = [];

                if (V.pc.equals(npc))
                    lines = this.lines(["encounter", "dirty talk", "pc", tag, ...extratags], npc);

                if (lines.length == 0)
                    lines = this.lines(["encounter", "dirty talk", tag, ...extratags], npc);

                for (let line of lines)
                    if (!retval.some(tline => tline.line == line.line))
                        retval.push(line);
            }
        }
    }

    let partner = enc.pobj(npc);

    let lines = [];

    if (V.pc.equals(partner))
        lines = this.lines(["encounter", "dirty talk", "pc", "generic", ...extratags], npc);

    if (lines.length == 0)
        lines = this.lines(["encounter", "dirty talk", "generic", ...extratags], npc);

    for (let line of lines)
        if (!retval.includes(lines))
            retval.push(line);

    return retval;
}

setup.ob_dialogue.encounter_line = function(npc)
{
    const lines = this.encounter_lines(npc);
    if (lines.length == 0) return;
    return this.pick_from_lines(lines);
}

setup.ob_dialogue.mood_line = function(npc, mood)
{
    const tags = ["mood", mood];
    const lines = this.lines(tags, npc);
    if (lines.length == 0) return;
    return this.parse(this.pick_from_lines(lines), npc).line;
}

setup.ob_dialogue.can_talk_submissively = function()
{
    // can the pc talk submissively?
    return V.pc.role_with(V.partner1) != "top";
}

setup.ob_dialogue.can_talk_dominantly = function()
{
    return V.pc.role_with(V.partner1) != "bottom";
}

setup.ob_dialogue.for_pc = function(line, npc)
{
    // expects line object from dialogue line database
    // returns whether this is appropriate for PC to say

    if (!line.response) return false;

    if (line.simadvice) return false;

    if (line.type)
    {
        let types = Array.isArray(line.type) ? line.type : [line.type];
        if (!types.includes("student")) return false;
    }

    if (line.noinclinations && V.pc.has_any_inclination(line.noinclinations)) return false;

    if (line.inclinations && !V.pc.has_any_inclination(line.inclinations)) return false;

    if (line.sexpartner && !setup.people.is_sexpartner(npc)) return false;

    return true;
}

setup.ob_dialogue.pc_text_response_menu = function(tags, npc)
{
    // returns a menu of possible response options

    const keys = Object.keys(setup.ob_dialogue.db);

    let possible = keys.filter(key => {
        const info = setup.ob_dialogue.db[key];
        return info.tags.includesAll(tags) && this.for_pc(info, npc);
    });

    let menu = {};
    for (let menuentry of possible)
    {
        const info = setup.ob_dialogue.db[menuentry];
        let menukey = this.parse(info.response.label, npc).line;
        if (menukey in menu)
            menu[menukey].push(info);
        else
            menu[menukey] = [info];
    }

    return menu;
}

setup.ob_dialogue.parse_pc_text_response = function(responses, npc)
{
    // for 'responses' we expect an array of entries from setup.ob_dialogue.db (usually of length 1 but sometimes more)

    let lines = [];
    for (let response of responses)
        lines.push(...response.content);

    let line = setup.ob_randomchoice(lines);

    if (V.phonetexter == npc)
        line = line.replace("$pc", "$phonetexter");
    else
    {
        T.thistextnpc = setup.people.get_name(npc);
        line = line.replace("$pc", "_thistextnpc");
    }

    line = this.parse(line, "PC").line;

    return line;
}
