setup.inclinations.validate = function()
{
    const required_fields = {"description":"string", "dream":"string", "requires":"object"}
    const optional_fields = {"lockif":"object"}
    var key_list = Object.keys(setup.inclinations)
    var fail_count = 0
    console.log("Validating inclinations.")
    var error_list = []
    var warning_list = []
    var item_count = 0
    var all_mainskills = setup.ob_skills.mainskills.map(function(skill) {return skill['name'];})
    var all_inclinations = []
    for (const [inc_key, inc_entry] of Object.entries(setup.inclinations))
    {
        if (typeof(inc_entry) != "function")
        {
            all_inclinations.push(inc_key)
        }
    }
    for (const [entry_key, entry] of Object.entries(setup.inclinations))
    {
        if (typeof(entry) != "function")
        {
            item_count++
            for (const [check_field, check_type] of Object.entries(required_fields))
            {
                if (!entry[check_field])
                {
                    error_list.push({"Inclination":entry_key, "Field":check_field, "Note":"Missing"})
                } else if (typeof(entry[check_field]) != check_type)
                {
                    var note = "\"Type \""+typeof(entry[check_field])+"\" (\""+check_type+"\" expected)"
                    error_list.push({"Inclination":entry_key, "Field":check_field, "Note":note})
                }
                else
                { // field validated, dig deeper if necessary
                    switch (check_field)
                    {
                        case "requires":
                        case "lockif":
                            for (const [req_field, req_value] of Object.entries(entry[check_field]))
                            {
                                if (req_field == "inclinations")
                                {
                                    // Make sure every item in the "inclinations" list is a valid inclination
                                    for (const req_inc of req_value)
                                    {
                                        if (all_inclinations.indexOf(req_inc) == -1)
                                        {
                                            var note = "\""+req_inc+"\" is not a valid inclination."
                                            error_list.push({"Inclination":entry_key, "Field":check_field, "Note":note})
                                        }
                                    }
                                }
                                else if (all_mainskills.indexOf(req_field) == -1)
                                {
                                    // not a valid skill!
                                    var note = "\""+req_field+"\" is not a valid mainskill."
                                    error_list.push({"Inclination":entry_key, "Field":check_field, "Note":note})
                                }
                            }
                            break;
                    }

                }
            }
            for (const [check_field, check_type] of Object.entries(optional_fields))
            {
                if (!entry[check_field])
                {
                    warning_list.push({"Inclination":entry_key, "Field":check_field, "Note":"Missing(optional)"})
                } else if (typeof(entry[check_field]) != check_type)
                {
                    var note = "\"Type \""+typeof(entry[check_field])+"\" (\""+check_type+"\" expected)"
                    error_list.push({"Inclination":entry_key, "Field":check_field, "Note":note})
                }
            }
        }
    }
    if (warning_list.length > 0)
    {
        console.warn("WARNINGS:")
        console.table(warning_list)
    }
    if (error_list.length > 0)
    {
        console.error("ERRORS:")
        console.table(error_list)
    }
    console.log(item_count+" items analyzed.")
    if (error_list.length > 0)
    {
        console.error("Inclinations Validation FAILED.")
    }
    else
    {
        console.log("Inclinations Validation PASSED.")
    }
}

