// Will check the requirements of an inclination, then unlock
// the inclination if all requirements are met.
// Returns TRUE if unlocked, FALSE if not unlocked.
setup.inclinations.unlock_with_req = function(inclination, lock = false)
{
    if (!("inclinationsunlocked" in State.variables)) State.setVar("$inclinationsunlocked", {});
    const unlocked = V.inclinationsunlocked;
    var the_pc = setup.pc()
    var unlock_ok = true
    if (!(inclination in unlocked))
    {
        if (!this.matches_prereqs(inclination) || !this.matches_skills(inclination) || !this.matches_parts(inclination))
            unlock_ok = false;

        if (unlock_ok)
        {
            console.log("Unlocking "+inclination)
            this.unlock(inclination, lock)
        }
    }
    return unlock_ok;
}

setup.inclinations.matches_parts = function(inclination)
{
    let the_pc = setup.pc();
    let unlock_ok = true;
    for (const [check_key,check_value] of Object.entries(this[inclination].requires))
        {
            if (check_key == "part")
            {
                if (!the_pc.has_part(check_value))
                    unlock_ok = false;
            }
        }
    return unlock_ok;
}

setup.inclinations.matches_skills = function(inclination)
{
    let the_pc = setup.pc();
    let unlock_ok = true;
    const allskills = setup.ob_skills.all_skills();
    for (const [check_key,check_value] of Object.entries(this[inclination].requires))
        {
            if (allskills.includes(check_key))
            {
                if (the_pc.skill_level(check_key) < check_value)
                    unlock_ok = false;
            }
        }
    return unlock_ok;
}

setup.inclinations.matches_prereqs = function(inclination)
{
    let the_pc = setup.pc();
    let unlock_ok = true;
    const allskills = setup.ob_skills.all_skills();
    for (const [check_key,check_value] of Object.entries(this[inclination].requires))
        {
            if (check_key == "inclinations")
            {
                for (const req_inc of check_value)
                {
                    if (!the_pc.has_inclination(req_inc))
                    {
                        unlock_ok = false;
                    }
                }
            }
        }
    return unlock_ok;
}

setup.inclinations.unlock = function(inclination, lock = false, dreamed = false, grantnow = false)
{
    if (!("inclinationsunlocked" in State.variables)) State.setVar("$inclinationsunlocked", {});

    const unlocked = V.inclinationsunlocked;
    if (!(inclination in unlocked))
    {
        if (lock)
        {
            unlocked[inclination] = {dreamed: true, locked: true};
            V.pcinclinations.push(inclination);
            if (!tags().includes("chargen"))
                setup.add_notification("You have permanently gained the <<highlight>>" + inclination + "<</highlight>> inclination.");
        }
        else
        {
            unlocked[inclination] = {dreamed: dreamed};
            if (tags().includes("chargen") || grantnow)
                V.pcinclinations.push(inclination);
        }
    }
}

setup.inclinations.dreamable = function()
{
    const retval = [];
    for (const [inclination, idata] of Object.entries(V.inclinationsunlocked))
    {
        if (!setup.pc().has_inclination(inclination) && !idata.dreamed)
        {
            retval.push(inclination);
        }
    }
    return retval;
}

setup.inclinations.remove = function(inclination)
{
    if (!("inclinationsunlocked" in State.variables)) State.setVar("$inclinationsunlocked", {});

    let unlocked = V.inclinationsunlocked;
    delete unlocked[inclination];
    V.pcinclinations.delete(inclination);
}

