setup.ob_maps.pathfind = function(map, startNode, endNode)
{
    // get map info
    const mapinfo = this[map];

    // Create an open set to store nodes to be evaluated
    const openSet = [startNode];

    // Create a dictionary to store the parent of each node
    const cameFrom = {};

    // Create a dictionary to store the cost of reaching each node from the start node
    const gScore = { [startNode]: 0 };

    // Create a dictionary to store the total estimated cost for each node (f-score)
    const fScore = { [startNode]: this.pathheuristic(map, startNode, endNode) };

    while (openSet.length > 0) {
      // Find the node with the lowest f-score in the open set
      const currentNode = openSet.reduce((minNode, node) =>
        fScore[node] < fScore[minNode] ? node : minNode
      );

      if (currentNode === endNode) {
        // Reconstruct the path and return it
        return this.pathreconstruct(cameFrom, startNode, endNode);
      }

      // Remove the current node from the open set
      openSet.splice(openSet.indexOf(currentNode), 1);

      // Iterate through the neighbors of the current node
      if (!mapinfo.nodes[currentNode].exits) return null;
      for (const neighbor of mapinfo.nodes[currentNode].exits) {
        // Calculate the tentative g-score
        const tentativeGScore = gScore[currentNode] + 1; // Assuming uniform cost

        if (
          tentativeGScore < (gScore[neighbor] || Infinity)
        ) {
          // This path is better than any previous one, so record it
          cameFrom[neighbor] = currentNode;
          gScore[neighbor] = tentativeGScore;
          fScore[neighbor] = gScore[neighbor] + this.pathheuristic(map, neighbor, endNode);

          if (!openSet.includes(neighbor)) {
            openSet.push(neighbor);
          }
        }
      }
    }

    // No path found
    return null;
}

setup.ob_maps.pathheuristic = function(map, node, endNode)
{
    return 1;
}

setup.ob_maps.pathreconstruct = function(cameFrom, startNode, current)
{
    const path = [current];
    while (cameFrom[current]) {
    current = cameFrom[current];
    path.unshift(current);

    if (current == startNode)
        return path;
    }
    return path;
}

setup.ob_maps.repair_campus_map = function()
{
    let origwidth = 945;
    let newwidth = 600;
    let mod = newwidth/origwidth;
    const keys = Object.keys(this.Campus.nodes);
    for (let i = 0; i < keys.length; i++)
    {
        if ("imgcoords" in this.Campus.nodes[keys[i]])
        {
            let coordsarr = this.Campus.nodes[keys[i]].imgcoords.split(',');
            for (let j = 0; j < coordsarr.length; j++)
            {
                coordsarr[j] *= mod;
                coordsarr[j] = Math.round(coordsarr[j]);
            }
            this.Campus.nodes[keys[i]].imgcoords = coordsarr.join(',');

            this.Campus.nodes[keys[i]].markercoords[0] *= mod;
            this.Campus.nodes[keys[i]].markercoords[1] *= mod;
            this.Campus.nodes[keys[i]].markercoords[0] = Math.round(this.Campus.nodes[keys[i]].markercoords[0]);
            this.Campus.nodes[keys[i]].markercoords[1] = Math.round(this.Campus.nodes[keys[i]].markercoords[1]);
        }
    }

}

setup.ob_maps.find_mobile_coords = function()
{
    let origwidth = 600;
    let newwidth = 300;
    let mod = newwidth/origwidth;
    for (let map of Object.values(setup.ob_maps))
    {
        if (map.img && map.nodes)
        {
            for (let node of Object.values(map.nodes))
            {
                if ("imgcoords" in node)
                {
                    let coordsarr = node.imgcoords.split(',');
                    for (let j = 0; j < coordsarr.length; j++)
                    {
                        coordsarr[j] *= mod;
                        coordsarr[j] = Math.round(coordsarr[j]);
                    }
                    node.imgcoords_mobile = coordsarr.join(',');

                    node.markercoords_mobile = [0, 0];
                    node.markercoords_mobile[0] = node.markercoords[0] * mod;
                    node.markercoords_mobile[1] = node.markercoords[1] * mod;
                    node.markercoords_mobile[0] = Math.round(node.markercoords_mobile[0]);
                    node.markercoords_mobile[1] = Math.round(node.markercoords_mobile[1]);
                }
            }
        }
    }
}

setup.ob_maps.location_name = function(location = V.location)
{
    let locblock = setup.ob_get_location_block(location);
	if (locblock in setup.ob_maps)
    {
		let loc = setup.ob_get_location(location);
		if (loc in setup.ob_maps[locblock].nodes)
			return setup.ob_maps[locblock].nodes[loc].name;
    }
}

