setup.ob_shops.validate = function(log_to_console = true)
{
    var result = {}
    result.run_info = {}
    result.info = []
    result.errors = []
    result.warnings = []
    let check_count = 0;
    for (const [entry_key, entry] of Object.entries(setup.ob_shops.db))
    {
        if (typeof(entry) != "function")
        {
            let label_list = [];
            let item_list = [];
            //console.log("Checking ",entry_key);//,entry);
            if (entry.items)
                for (const item of entry.items)
                {
                    try
                    {
                        check_count++;
                        //console.log("\tItem: ",item);
                        if ("type" in item) // make sure it's not a section header
                        {
                            if (label_list.indexOf(item.label) != -1)
                            {
                                result.warnings.push({"Clothing":entry_key+"(shop)", "Field":"label", "Note":"Duplicate label: "+item.label+" ("+item.item+")"});
                            }
                            label_list.push(item.label);

                            if (item_list.indexOf(item.item) != -1 && !["alcohol", "food"].includes(item.type))
                            {
                                result.warnings.push({"Clothing":entry_key+"(shop)", "Field":"item", "Note":"Duplicate item: "+item.item+" ("+item.label+")"});
                            }
                            item_list.push(item.item);

                            let db_entry;
                            if (item.type == "books")
                                db_entry = setup.ob_books.books_db()[item.item];
                            else
                                db_entry = (setup.ob_shops.databases[item.type])[item.item];

                            //console.log("Entry: ",db_entry);
                            if (!db_entry)
                            {
                                result.errors.push({"Clothing":entry_key+"(shop)", "Field":"database: "+item.type, "Note":"No db entry for: "+item.label+" (item: \""+item.item+"\")"});
                            }
                        }
                    }
                    catch (error)
                    {
                        console.error(`Invalid shop item or unaccounted-for shop item database: ${error}`)
                        console.error(item);
                    }
                }
        }
    }

    if (log_to_console)
    {

        if (result.info.length > 0)
        {
            console.log("INFO:")
            console.table(result.info)
        }
        if (result.warnings.length > 0)
        {
            console.warn("WARNINGS:")
            console.table(result.warnings)
        }
        if (result.errors.length > 0)
        {
            console.error("ERRORS:")
            console.table(result.errors)
        }
        console.log(check_count+" items analyzed.")
        if (result.errors.length > 0)
        {
            console.error("Shop Validation FAILED.")
        }
        else
        {
            console.log("Shop Validation PASSED.")
        }
    }

    result.run_info.count = check_count;
    result.run_info.success = (result.errors.length == 0);
    return result;
}
