setup.ob_skills.is_main = function(skill)
{
    for (let i = 0; i < this.mainskills.length; i++)
    {
        if (this.mainskills[i].name == skill) return true;
    }
    return false;
}

setup.ob_skills.is_secondary = function(skill)
{
    for (let i = 0; i < this.otherskills.length; i++)
    {
        if (this.otherskills[i].name == skill) return true;
    }
    return false;
}

setup.ob_skills.is_valid = function(skill)
{
    return this.is_main(skill) || this.is_secondary(skill);
}

setup.ob_skills.all_skills = function()
{
    return [...this.mainskills.map(skill => skill.name), ...this.otherskills.map(skill => skill.name)];
}
