    fire_midevent()
    {
        // shall we fire the mid-encounter event this round?
        if (this.rounds < 5) return false;
        else if (this.rounds > 10) return true;
        else
        {
            let t = (this.rounds - 5) / (10 - 5);
            let chance = 0.2 + (1 - 0.2) * (t * t);
            return State.random() < chance;
        }
    }

    removed_underwear(npc, item)
    {
        if (!this.possible_trophies)
            this.possible_trophies = {};

        npc = setup.people.get_name(npc);
        if (npc)
        {
            this.possible_trophies[npc] = item;
        }

