            participants: this.partners(true).map(p => this.unpobj(p)),
            witnesses: this.witnesses,
            revealed: {},
            ideas: V.pc.encounter_ideas_used(),
            flags: 0,
            orgasmflags: 0,
        };

        for (let partner of this.partners(true))
        {
            let key = this.unpobj(partner);
            recording.revealed[key] = this.encode_revealed_parts(partner);
        }

