        if (this.has_peed_on) usedflags.push("has peed on");
        if (this.been_peed_on) usedflags.push("been peed on");
        if (V.pc.pain() >= 250) usedflags.push("pain inflicted on");
        if (V.pc.humiliation() >= 250) usedflags.push("humiliation inflicted on");
        if (this.partners().length == 0)
        {
