        }
        else
        {
            if (V.pc.is_masc() && V.partner1.is_masc())
                usedflags.push("gay");
            else if (V.pc.is_femme() && V.partner1.is_femme())
                usedflags.push("lesbian");
            else if ((V.pc.is_femme() && V.partner1.is_masc()) || (V.pc.is_masc() && V.partner1.is_femme()))
                usedflags.push("straight");
            else if (V.pc.is_enby() && V.partner1.is_enby())
                usedflags.push("enby on enby");

            if (this.partners().length == 2)
                usedflags.push("threesome");
            else if (this.partners().length > 2)
                usedflags.push("group");
            else
                usedflags.push("couple");

            if (V.partner1.pain() >= 250) usedflags.push("inflicted pain");
            if (V.partner1.humiliation() >= 250) usedflags.push("inflicted humiliation");
        }
        if (recording.witnesses.length > 0)
            usedflags.push("audience");

        const allflags = setup.ob_amateurPornTown.allflags;
        recording.flags = setup.ob_encode_bitwise_array(allflags, usedflags);

        // now to track orgasms... this somewhat replicates what we do for sex stats but we're going to cut it down into more general porn stuff
        const orgasms = V.orgasmsthisencounter || this.orgasms;
        let orgasmflags = [];
        for (let orgasm of orgasms)
        {
            if ((orgasm.subject == "PC" || orgasm.object == "PC") && orgasm.location)
            {
                let flag;
                switch (orgasm.location)
                {
                    case "face":
                    {
                        flag = "facial";
                        break;
                    }
                    case "mouth":
                    {
                        flag = "oral creampie";
                        break;
                    }
                    case "vagina":
                    {
                        flag = "creampie";
                        break;
                    }
                    case "anus":
                    {
                        flag = "anal creampie";
                        break;
                    }
                    default:
                    {
                        flag = "cumshot";
                    }
                }
                if (orgasm.subject == "PC")
                    flag += " given";

                orgasmflags.push(flag);
            }
            else if (orgasm.subject == "PC" && (V.pc.has_part("vagina") || this.partners().length == 0))
            {
                orgasmflags.push("had an orgasm");
            }
        }

        const allorgasmflags = setup.ob_amateurPornTown.orgasmflags;
        recording.orgasmflags = setup.ob_encode_bitwise_array(allorgasmflags, orgasmflags);

        return recording;
    }
