Encounter.prototype.clone = function()
{
    // Return a new instance containing our own data.
    return new Encounter(this);
}

Encounter.prototype.toJSON = function()
{
    // Return a code string that will create a new instance containing our
	// own data.
	var ownData = {};
	Object.keys(this).forEach(function (pn) {
		ownData[pn] = clone(this[pn]);
	}, this);
	return JSON.reviveWrapper('new Encounter($ReviveData$)', ownData);
}

