                                        }

                                        this.tattoos[tatloc] = tstyle;
                                    }
                                }
                            }
                        }

                        if (debuggen) console.log("16");

                        // generate natural level of hairiness for this NPC (this is not the final hair levels)
                        this.body_hair_growth = rng.randomrelfreq(setup.ob_cosmetics.body_hair_odds);
                        let body_hair_group = setup.ob_cosmetics.body_hair_growth[this.body_hair_growth];
                        // choose pubic hair based on archetype (or predefined pube data if any)
                        let rndpubicstyle = rng.randomrelfreq(styleinfo[genderexpression + " pubes"]);
                        let overridepubicstyle = pdata["pubes"] || pdata["pubic_style"];
                        if (setup.ob_relationships.get_subrules(this).includes("shaved pubes"))
                            overridepubicstyle = "shaved";
                        this.pubic_style = (overridepubicstyle || rndpubicstyle) || "trimmed";
                        // generate desired body hair levels based on archetype
                        // we'll shave our hair to desired levels if it grows that much per location
                        let desired_shave = rng.randomrelfreq(styleinfo[genderexpression + " desired shave level"]);
                        /*
                        // give chest hair to masc-presenting folks
                        if (this.is_masc()) { this.body_hair["chest"] = "average"; }
                        else { desired_shave = Math.max(desired_shave - 2, 0); } // femme-presenting folks are given a lower maximum hairiness
                        */

                        // generate actual body hair levels
                        // this system is definitely overcomplicated
                        // but it serves to allow NPCs to have fairly unified body hair levels
                        // while still offering some variation between each part
                        // and between different NPCs with different (or even the same) archetypes
                        for (const hair of Object.keys(this.body_hair)){
                            let lookup = hair + "_hair_styles";
                            let all_styles = setup.ob_cosmetics[lookup];
                            let lockedstyle = pdata.body_hair && pdata.body_hair[hair] ? pdata.body_hair[hair] : undefined;
                            // how much hair naturally grows on this body part, given the natural hair level of the NPC?
                            let base_desired_hair = lockedstyle || rng.randomrelfreq(body_hair_group[lookup]);
                            // if we want more hair than we naturally grow, leave it natural
                            if (lockedstyle)
                            {
                                this.body_hair[hair] = lockedstyle;
                            }
                            else if (desired_shave >= all_styles[base_desired_hair].shavelevel)
                            {
                                this.body_hair[hair] = base_desired_hair;
                            }
                            // if we want less hair than we have, shave it down
                            else
                            {
                                for (const style of Object.keys(all_styles)) {
                                    if (all_styles[style].shavelevel == desired_shave){
                                        this.body_hair[hair] = style;
                                        break;
                                    }
                                }
                            }

                        }
                        delete this.hairiness; // this is only used for players to choose their hairiness, it has no use for NPCs

                        if (this.grows_beard && this.is_masc()){
                            if (debuggen) console.log("entity beard generation");
                            let rndbeard_style = rng.randomrelfreq(styleinfo[genderexpression + " beardstyles"]);
                            let beard_style = "beard_style" in pdata ? pdata["beard_style"] : rndbeard_style;
                            if (beard_style){
                                let beard_style_info = setup.ob_cosmetics.beard_styles[beard_style];
                                let max_length = "max_length" in beard_style_info ? beard_style_info["max_length"] : setup.ob_cosmetics.beard_lengths.length - 1;
                                let min_length = "min_length" in beard_style_info ? beard_style_info["min_length"] : 0;
                                this.beard_style = beard_style;
                                this.beard_length = rng.rir(min_length,max_length);
                            }
                            else{
                                this.beard_style = "shaved";
                                this.beard_length = 0;
                            };
                        };
                    }

                    if (debuggen) console.log("17");

                    this.set_pronouns();

                    if (debuggen) console.log("18");

                    if (pdata.distinguishing_marks)
                        this.distinguishing_marks = pdata.distinguishing_marks;
                    else
                    {
                        const possibledmarks = this.possible_distinguishing_marks();
                        let rng3 = setup.ob_newRNG(this.name + "dmark");
                        this.distinguishing_marks = [rng3.randomchoice(possibledmarks)];
                    }

                    if (debuggen) console.log("19");

                    this.set_anonymous_name({assumeclothes: config.onlyname});

                    if (debuggen) console.log("20");

                    if (!config.onlyname && (V.encounter || config.generatesextoys)) this.generate_sextoys();

                    if (debuggen) console.log("21");

                    this.fleeting_stats = {"arousal": 0, "satisfaction": 0, "pain": 0, "humiliation": 0, "drunkenness": 0};
                }
            }

            this.cum_request = "";
            this.attempt_pullout = false;
            this.ignore_cum_request = false;
            this.forced_cum_location_attempted = false;
            this.forced_cum_location_fought = false;
            this.forced_cum_location_defied = false;
            this.attempted_clothing_act = null;
            this.attempted_position = null;
            this.attempted_penetration = null;
            this.attempted_pullaway = null;
            this.cum_covering = {};
            this.event_removed_clothing = [];
            this.encounter_removed_clothing = [];
            if (!this.sextoys) this.sextoys = [];
            this.storage_locations = {};
            this.resisted_orgasm = 0;
            this.edged = 0;

            this.built = true;
        }

        setup.ob_revive_class(this, config);
        if (this.storage_locations)
            for (const key of Object.keys(this.storage_locations))
            {
                this.storage_locations[key] = setup.ob_check_revive(this.storage_locations[key])
            }


        this.age = Math.max(18, this.age);

        if (debuggen) console.log("22");
        if (debuggen) console.log(this.person);

    }

