    get_anonymous_name(config)
    {
        let assumeclothes = config.assumeclothes || false;
        let costume = (!("costume" in config) || config.costume) ? (this.temporary ? false : setup.people.costume(this.name)) : false;
            // if 'costume' not present, assume true
            // if true, look up costume
            // if a string, it's an overridden costume so use that
        let nudelabel = config.nudelabel;
        let nude = false;
        let includedmark = !("includedmark" in config) ? true : config.includedmark;

        let name = "";
        let agedesc = this.age_descriptor();

        let physique = this.physique_descriptor();

        if (this.height < 300 || this.height > 700)
        {
            physique = this.height_descriptor();
        }
        else if (physique == "toned")
        {
            physique = "";
        }

        // let us now retrieve their style descriptor
        let styledesc = "";
        if (!this.is_pc)
        {
            if (nudelabel)
            {
                nude = true;
                styledesc = setup.ob_styles[this.style]["nudelabel"];
            }
            else
            {
                nude = !(assumeclothes || this.clothes.length > 0);
                styledesc = !nude ? setup.ob_styles[this.style]["label"] : setup.ob_styles[this.style]["nudelabel"];
            }
        }
        if (nude)
            costume = "none";

        let hairdesc = this.hair_descriptor_simple();

        // combine natural language descriptors into a name for when the pc doesn't know their name, will not be unique ofc but hopefully decent variety
        if (this.is_anonymous())
        {
            let label = agedesc.indexOf("college") >= 0 ? "college " + this.label : this.label;
            if (this.hair_visible())
                name = physique + " " + hairdesc + " " + label;
            else
                name = physique + " " + label;
        }
        else if (agedesc == "college")
            name = physique + " " + styledesc + " " + hairdesc + " " + agedesc + " " + this.label;
        else
            name = physique + " " + agedesc + " " + styledesc + " " + hairdesc + " " + this.label;

        if (costume && costume != "none")
        {
            let costumelabel = typeof costume == "string" ? costume : this.most_evident_costume();
            if (costumelabel != "none")
            {
                name += " in " + setup.ob_a_or_an(costumelabel) + " " + costumelabel + " costume";
                name.replace(styledesc, "");
                includedmark = false;
            }
        }

        if (includedmark && this.distinguishing_marks && this.distinguishing_marks.length > 0)
        {
            let rng = setup.ob_newRNG(this.name + "dmark");
            let dmark = rng.randomchoice(this.distinguishing_marks);
            name += " with " +
                (setup.distinguishing_marks[dmark].plural ? "" : setup.ob_a_or_an(dmark) + " ") +
                dmark;
        }

        name = name.replace(/\s+/g, ' ').trim();

        return name;
    }

    set_anonymous_name(config = null)
    {
        let defaultconfig = {
            assumeclothes: false,
            costume: true,
        };
        this.anonymous_name = this.get_anonymous_name(config || defaultconfig);
    }

