        return words.length > 1 ? words.slice(1).join(" ") : "";
    }

    get_nickname()
    {
        return this.nickname != "" ? this.nickname : this.firstname();
    }

    equals(other)
    {
        // necessary because of the way story state variables work
        // specifically, if we store this object somewhere and it's also declared as a story variable
        // then those will actually be two different objects rather than references to the same object
        // which is FINE as long as we're aware of it
        if (other == null || other == undefined)
            return false;
        else if (typeof other == "object")
            return this.name == other.name;
        else if (other == "PC" || other == V.pcname)
            return this.is_pc;
        else if (other in V.niches)
            return this.equals(V.niches[other]);
        else
            return other == this.person || other == this.name;
    }

    possible_distinguishing_marks(ignorecoding = false, ignorerestrict = false)
    {
        const slotsused = [];
        if (this.distinguishing_marks)
        {
            for (const mark of this.distinguishing_marks)
                slotsused.push(setup.distinguishing_marks[mark].slot);
        }
        if (!this.is_pc && this.distinguishing_marks.length > 0) return [];
        const retval = [];
        let coding = this.is_femme() ? "femme" : (this.is_masc() ? "masc" : "enby");
        for (const [mark, markinfo] of Object.entries(setup.distinguishing_marks))
        {
            if (
                (markinfo.pconly && !this.is_pc && !ignorerestrict) ||
                (markinfo.npconly && this.is_pc && !ignorerestrict) ||
                (!ignorecoding && markinfo.coding && !this.is_pc && !markinfo.coding.includes(coding)) ||
                (slotsused.includes(markinfo.slot))
            )
                continue;
            else
                retval.push(mark);
        }
        return retval;
    }
