    generate_outfit(rng = new RNG(inthash(this.name + "outfit")))
    {
        let debuggen = false;
        if (debuggen) console.log("---");

        //let possibleexistingobjects = Object.values(V).filter(obj => obj instanceof Person && obj.name == this.name && obj != this);
        let possibleexistingobjects = [];

        if (V.npcclothingmemory && V.npcclothingmemory[this.name])
        {
            // a memory for NPC clothes that might be maintained during a sequence of events
            if (debuggen) console.log("Retrieving clothes from memory");
            this.clothes = [...V.npcclothingmemory[this.name]];
        }
        else if (possibleexistingobjects.length > 0)
        {
            // this is not the way.......
            if (debuggen) console.log("Found clothes on extant expanded NPC; retrieving those");
            this.clothes = possibleexistingobjects[0].clothes;
        }
        else
        {

            if (debuggen) console.log(this.style);
            let styleinfo = setup.ob_styles[this.style];
            if (debuggen) console.log(styleinfo);
            const lastloctags = V.lastloctags || [];
            const constantblock = !V.attemptednavigation || setup.ob_get_location_block(V.attemptednavigation) == V.locationblock;

            const swimwear = lastloctags && (lastloctags.includes("swimwearallowed") || tags().includes("swimwear")) && !tags().includes("findr") && V.peopleatlocation.includes(this.name);
            const athleticwear = !swimwear && lastloctags && (lastloctags.includes("athleticwear") || tags().includes("athleticwear")) && !tags().includes("findr") && V.peopleatlocation.includes(this.name);
            const formalwear = lastloctags && (lastloctags.includes("formalwear") || (lastloctags.includes("formalwearatrenfest") && setup.School.current_eventday() == "Renewal Festival") && V.hour >= 18) && !tags().includes("findr") && V.peopleatlocation.includes(this.name);
            const underwear = lastloctags && (lastloctags.includes("underwear") || tags().includes("underwear")) && !tags().includes("findr") && V.peopleatlocation.includes(this.name);
            const lingerie = lastloctags && (lastloctags.includes("lingerie") || tags().includes("lingerie")) && !tags().includes("findr") && V.peopleatlocation.includes(this.name);
            const reshall = lastloctags.includes("locblockResidenceHall") && constantblock;
            const costume = (this.temporary || swimwear) ? null : setup.people.costume(this.name);
            let outfits;
            if (formalwear)
                outfits = styleinfo.formalwear;
            else if (swimwear)
                outfits = styleinfo.swimwear;
            else if (athleticwear)
                outfits = styleinfo.athleticwear;
            else if (lingerie)
                outfits = styleinfo.lingerie;
            //temperature specific outfits - currently not used
            //else if (setup.ob_weather_is_cold() && styleinfo["cold outfits"])
            //    outfits = styleinfo["cold outfits"];
            //else if (setup.ob_weather_is_hot() && styleinfo["hot outfits"])
            //    outfits = styleinfo["hot outfits"];
            else if (setup.ob_petitions.npc_swimwear(this.name))
                outfits = styleinfo.swimwear;
            else if (this.has_inclination("Slut") && styleinfo["slutty outfits"])
                outfits = styleinfo["slutty outfits"];
            else
                outfits = styleinfo.outfits;
            const naked = (lastloctags.includes("nakednpc") || tags().includes("nakednpc")) && V.peopleatlocation.includes(this.name);
            let outfitrelfreq = outfits;
            const atgame = V.sport || tags().includes("sportsuniforms") || lastloctags.includes("sportsuniforms");
            let coloroverride = [];
            let sport = null;
            if (debuggen) console.log("outfits:", outfits);
            const subrules = setup.ob_relationships.get_subrules(this);
            const exceptions = V.outfitexceptions ? (V.outfitexceptions[this.person] || []) : [];
            let outfit;

            let calc_outfits = false; // outfits calculation is needed

            let exhib = !this.temporary && setup.people.has_any_inclination(this, setup.ob_archetypes.inclination_sets.basic_exhibitionist);

            if (naked)
            {
                outfit = "naked";
            }
            else if (atgame)
            {
                // ongoing sports game

                if (this.temporary || setup.people.get_type(this) == "outsider")
                {
                    // opposing team, probably, but let's find out
                    try
                    {
                        for (const [otherteamtype, otherteam] of Object.entries(atgame.opposingteams))
                        {
                            for (const member of otherteam)
                                if (this.equals(member))
                                {
                                    sport = otherteamtype;
                                    break;
                                }
                        }
                        let against = Array.isArray(atgame.against) ? atgame.against[0] : atgame.against;
                        coloroverride = setup.School.other_teams[(this.sportsteam || against)].colors;
                    }
                    catch (error)
                    {
                        // if we're here, it's generally only while looking at a Falcons player outside of an actual game
                        // (i.e. in a post-game event passage)
                        // since (afaik) no other circumstance causes this exact problem in this exact place
                        for (const [otherteamtype, otherteam] of Object.entries(V.rivalsportsteams))
                        {
                            if (otherteam.team.includes(this.name))
                            {
                                sport = otherteamtype;
                                coloroverride = setup.School.other_teams["Falcons"].colors;
                                break;
                            }
                        }
                    }
                }
                else
                {
                    const ourteams = V.sportsteams;
                    if (atgame == true)
                    {
                        const people = setup.people_db();
                        if (people[this.person] && people[this.person].sports)
                            sport = people[this.person].sports[0];
                        else
                            sport = null;
                    }
                    else if (ourteams[atgame.type].team.includes(this.person))
                        sport = atgame.type;
                    else
                        for (const asport of atgame.attached)
                        {
                            if (ourteams[asport] && ourteams[asport].team.includes(this.person))
                            {
                                sport = asport;
                                break;
                            }
                        }
                }
            }
            else if (V.inclass && setup.School.sports[V.inclass] && setup.people.is_enrolled(this, V.inclass))
            {
                sport = V.inclass;
            }

            if (!naked)
            {
                if (!this.temporary && setup.ob_business.is_employee_here(this.person) && !this.equals(V.niches["The River Rat Owner"]))
                {
                    if (debuggen) console.log("EMPLOYEE HERE!",this);
                    let t_outfits = setup.ob_business.get_job_outfits(setup.ob_business.job_here(), this.person) || outfit;
                    if (t_outfits && t_outfits.length > 0 && t_outfits.length % 2 == 0)
                    {
                        outfits = t_outfits;
                        outfitrelfreq = outfits;
                    }
                    calc_outfits = true;
                    if (debuggen) console.log("Using business outfits: ", outfits);
                }
                else if (sport)
                {
                    if (atgame || setup.School.sports[sport].uniformatpractice)
                    {
                        // this will be a little unconventional but really the best way to determine this without duplicating effort
                        let possible = [];
                        let shop = setup.ob_shops.db["Varsity Sports Uniforms"];
                        for (let item of shop.items)
                            if (item.sport && item.sport == sport)
                                if (sport == "cheerleading" && !this.temporary)
                                {
                                    let useskimpy = V.cheerleading && V.cheerleading.skimpy;
                                    if (useskimpy && item.label.indexOf("Skimpy") > -1)
                                        possible.push(item.item);
                                    else if (!useskimpy && item.label.indexOf("Skimpy") == -1)
                                        possible.push(item.item);
                                }
                                else
                                {
                                    possible.push(item.item);
                                }

                        if (possible.length == 0)
                            outfit = "Sporty";
                        else
                            outfit = setup.ob_randomchoice(possible);
                    }
                    else if (sport == "swimming")
                    {
                        const swimming = V.swimming;
                        if (swimming && swimming.allnaked && !atgame && setup.people.get_type(this.person) == "student")
                            outfit = "naked";
                        else
                            outfit = "Competitive Swimming Outfit";
                    }
                    else if (setup.School.sports[sport].skills.includes("Physical"))
                    {
                        outfit = "Sporty";
                    }
                    else
                    {
                        outfit = rng.randomrelfreq(outfits);
                    }
                }
                else if (costume)
                {
                    outfit = costume;
                }
                else
                {
                    calc_outfits = true;
                }
            }

            let adjustedforsubrules = false;
            if (calc_outfits)
            {
                if (exhib && swimwear)
                    outfit = "Bold Swimwear";

                else
                {
                    const filterOutfits = function(outfitlist, condition)
                    {
                        const retval = [];
                        for (let i = 0; i < outfitlist.length; i+=2)
                            if (condition(outfitlist[i]))
                                retval.push(outfitlist[i], outfitlist[i + 1]);

                        if (retval.length == 0) console.log(`bypassing ${condition} -- no valid outfit`);
                        else adjustedforsubrules = true;

                        return retval.length == 0 ? outfitlist : retval;
                    };

                    let searchforskirt = exhib || (subrules.includes("only skirt") && !subrules.includes("skintight pants"));
                    let searchforskinpants = subrules.includes("skintight pants");
                    let searchforskintop = subrules.includes("skintight top");
                    let searchforbellytop = subrules.includes("show belly");

                    let filteredoutfitrelfreq = [...outfitrelfreq];

                    if (debuggen) console.log("outfits before subrules:", outfitrelfreq);

                    if (!this.temporary && !setup.people.is_bratty_today(this.person))
                    {
                        if (searchforbellytop)
                        {
                            filteredoutfitrelfreq = filterOutfits(filteredoutfitrelfreq, outfit => setup.ob_outfit_shows_belly(outfit));
                            if (debuggen) console.log("after show belly rule", filteredoutfitrelfreq);
                        }

                        if (searchforskintop)
                        {
                            filteredoutfitrelfreq = filterOutfits(filteredoutfitrelfreq, outfit => setup.ob_outfit_has_skintight_top(outfit));
                            if (debuggen) console.log("after skintight top rule", filteredoutfitrelfreq);
                        }

                        if (searchforskinpants)
                        {
                            filteredoutfitrelfreq = filterOutfits(filteredoutfitrelfreq, outfit => setup.ob_outfit_has_skintight_pants(outfit));
                            if (debuggen) console.log("after skintight pants rule", filteredoutfitrelfreq);
                        }

                        if (searchforskirt)
                        {
                            filteredoutfitrelfreq = filterOutfits(filteredoutfitrelfreq, outfit => setup.ob_outfit_has_under_access(outfit));
                            if (debuggen) console.log("after skirt rule", filteredoutfitrelfreq);
                        }
                    }
                    else if (debuggen) console.log("ignoring subrules due to brattiness");

                    if (debuggen) console.log("outfits after subrules:", filteredoutfitrelfreq);
                    outfit = rng.randomrelfreq(filteredoutfitrelfreq);
                }

                if (debuggen) console.log("outfit:", outfit);
            }

            if (outfit == "naked")
            {
                this.clothes = [];
                //this.clothes.transfer_all_to();
            }
            else
            {
                if (debuggen) console.log("picked outfit:", outfit);
                let forcetight = [];
                if (!this.temporary && !setup.people.is_bratty_today(this.person))
                {
                    if (subrules.includes("skintight pants")) forcetight.push("pants");
                    if (subrules.includes("skintight top")) forcetight.push("top");
                }
                let clothes = setup.build_outfit(this.gender, this.body_parts, outfit, rng, coloroverride, false, V.day, this.person, forcetight);
                if (debuggen) console.log("raw clothes", [...clothes]);
                let remove = [];
                let removedtop = false;
                let removedpants = false;
                let removedbra = false;
                let removedunderwear = false;
                let swapbraforbinder = this.is_enby() && this.has_part("breasts") && rng.random() <= 0.7;
                let rng2 = setup.ob_newRNG(this.person + "glasses");
                let addglasses = rng2.random() <= 0.2;
                if ("optnpcglasses" in V && !V.optnpcglasses) addglasses = false;
                let lostunderwear = !this.temporary && V.gameday == setup.people.get_person(this.person).lastLostUnderwear;

                this.clothes = clothes; // setting this temporarily so we can use standard clothes functions but will be blanked before we actually set final outfit

                if (underwear)
                {
                    for (let i = 0; i < clothes.length; i++)
                    {
                        let cinfo = new ClothingItem(clothes[i]).get_current_archetype();

                        if (!this.has_breasts() && cinfo.covers.includes("chest") && !cinfo.covers.includes("crotch"))
                            remove.push(clothes[i]);
                        else if (this.has_breasts() && cinfo.covers.includes("chest") && this.clothing_layergroup(cinfo) > 1 && this.underwear_covering("chest"))
                            remove.push(clothes[i]);
