                            {
                                removedtop = true;
                                remove.push(clothes[i]);
                            }
                            else if (exceptions.includes("no top") && cinfo.covers.includes("chest") && !cinfo.covers.includes("crotch") && !removedbra && !removedtop)
                            {
                                removedtop = true;
                                remove.push(clothes[i]);
                            }
                            else if (setup.people.has_inclination(this.person, "Proud Exhibitionist") && cinfo.covers.includes("crotch") && !cinfo.covers.includes("chest") && this.wearing_underwear() && rng.random() < 0.5 && !removedunderwear && !removedpants)
                            {
                                removedpants = true;
                                remove.push(clothes[i]);
                            }
                            else if (exceptions.includes("no bottom") && !cinfo.covers.includes("chest") && cinfo.covers.includes("crotch") && !removedunderwear && !removedpants)
                            {
                                removedpants = true;
                                remove.push(clothes[i]);
                            }
                        }
                        else if (this.clothing_layergroup(cinfo) == 1 && (!cinfo.flags.includesAny(["non-underwear"]) || (cinfo.covers.includes("breasts") && clothes[i] != this.outermost_covering("breasts")) || (cinfo.covers.includes("crotch") && clothes[i] != this.outermost_covering("crotch"))))
                        {
                            let nobra = (exhib || subrules.includes("no bra") || exceptions.includes("no bra"));
                            let nounderwear = ((exhib || subrules.includes("no underwear")) && (setup.people.has_inclination(this.person, "Proud Exhibitionist") || subrules.includes("no underwear") || exceptions.includes("no underwear")) || lostunderwear);

                            if (debuggen) console.log("nobra=", nobra, "nounderwear=", nounderwear);

                            if (nobra && this.has_part("breasts") && clothes[i].item == this.underwear_covering("breasts")?.item && !cinfo.covers.includes("crotch") && !cinfo.flags.includes("hide breasts") && this.wearing_shirt() && !removedtop && this.underwear_covering("nipples")?.item != this.outermost_covering("nipples")?.item && !removedbra)
                            {
                                removedbra = true;
                                remove.push(clothes[i]);
                            }
                            else if (nounderwear && clothes[i].item == this.underwear_covering("crotch")?.item && !cinfo.covers.includes("breasts") && this.wearing_pants() && !removedpants && this.underwear_covering("crotch")?.item != this.outermost_covering("crotch")?.item && !removedunderwear)
                            {
                                removedunderwear = true;
                                remove.push(clothes[i]);
                            }
                            //else if (rng.random() < 0.5 && quadparty.includes(V.location) && this.has_part("breasts") && setup.people.has_inclination(this.person, "Proud Exhibitionist") && cinfo.covers.includes("breasts") && !cinfo.covers.includes("crotch"))
                            //    remove.push(clothes[i]);
                        }
                    }
                }
                else if (V.location == "NutmegSt" && V.quickieburgerjob && V.quickieburgerjob.strike && V.quickieburgerjob.toplessprotest && setup.people.is_employee(this.person, "QuickieBurger") && this.person != setup.people_niches()["The QuickieBurger Franchise Owner"] && (["male", "transgender male"].includes(this.gender) || this.age < 30))
                {
                    for (let i = 0; i < clothes.length; i++)
                    {
                        let cinfo = new ClothingItem(clothes[i]).get_current_archetype();
                        if (cinfo.covers.includes("chest") && !cinfo.covers.includes("crotch"))
                        {
                            remove.push(clothes[i]);
                        }
                    }
                }
                if (swapbraforbinder)
                {
                    for (let i = 0; i < clothes.length; i++)
                    {
                        let cinfo = new ClothingItem(clothes[i]).get_current_archetype();
                        if (cinfo.covers.includes("breasts") && this.clothing_layergroup(cinfo) == 1 && !cinfo.flags.includesAny(["non-underwear", "hide breasts"]))
                        {
                            remove.push(clothes[i]);
                            let binder = setup.build_outfit(this.gender, this.body_parts, "Binder", rng);
                            clothes.push(binder[0]);
                            break;
                        }
                    }
                }
                if (addglasses && !this.is_part_covered("face"))
                {
                    let glassesoutfit = rng2.randomchoice(Object.keys(setup.ob_outfits).filter(outfit => outfit.startsWith("Glasses")));
                    let glasses = setup.build_outfit(this.gender, this.body_parts, glassesoutfit, rng2);
                    clothes.push(glasses[0]);
                }

                if (!this.temporary)
                {
                    let gifted = setup.people.get_person(this.person).giftedClothing;
                    if (gifted && ["friendship", "romantic"].includes(setup.ob_relationships.relationship_type_with(this.person)))
                    {
                        for (let gitem of gifted)
                        {
                            const citem = setup.clothes[gitem.item];
                            let anycovered = false;
                            for (let slot of citem.covers)
                                if (this.is_part_covered(slot))
                                {
                                    anycovered = true;
                                    break;
                                }
                            if (citem.category == "accessories" || !anycovered)
                            {
                                let gifteditem = {item: gitem.item};
                                gifteditem.name = citem.name;
                                for (const [subname, subvalue] of Object.entries(gitem.subs))
                                    gifteditem.name = gifteditem.name.replace('%' + subname, subvalue);
                                gifteditem.displacements = [];
                                gifteditem.subs = gitem.subs;
                                clothes.push(gifteditem);
                                if (debuggen) console.log("adding gifted item:", gifteditem);
                            }
                        }
                    }
                }

                if (debuggen) console.log("removing", [...remove]);
                this.clothes = [];
                for (let i = 0; i < remove.length; i++)
                {
                    let i2 = clothes.indexOf(remove[i]);
                    if (i2 >= 0)
                        clothes.splice(i2, 1);
                }
                if (debuggen) console.log("clothes immediately before applying", [...clothes]);

                //this.clothes.transfer_all_to() // Empty current clothes
                let tries = 0;
                while ((tries == 0 || !this.fully_dressed()) && tries < 10)
                {
                    tries++;
                    this.clothes = [];
                    for (const clothes_data of clothes)
                    {
                        let cItem = new ClothingItem(clothes_data);
                        /*
                        // this is producing odd results occasionally now that we have more consequential configs
                        for (const config_category of cItem.get_configuration_categories())
                        {
                            cItem.set_configuration(config_category, rng.randomchoice(cItem.get_configuration_options(config_category)));
                        }
                        */
                        let datastruct = cItem.get_data_structure();
                        this.clothes.push(datastruct);
                    }
                }
            }
        }
        if (debuggen) console.log("final clothes", [...this.clothes]);
        // all the debugging here is sometimes necessary because the archetype/outfit stuff is easy to fuck up
        // if you get lots of errors about a person being 'undefined' then often the problem is a typo in their outfits
    }

