    clothing_layergroup(clothing_info)
    {
        if (!clothing_info.layer && clothing_info.item)
            clothing_info = new ClothingItem(clothing_info).get_current_archetype();
        return Math.floor(clothing_info.layer/10)
    }

    clothing_part_already_occupied_by(newitem, olditem)
    {
        // determine which body parts are occupied by clothing
        // check if the given item interferes

        if (!newitem.occupies || !olditem.occupies) return false;
        else if (!newitem.occupies.includesAny(olditem.occupies)) return false;
        else if (olditem.occupies.includes("neck") && newitem.layer != olditem.layer) return false; // collar over necklace exception

        let unoccupied = [...this.body_parts];
        unoccupied.delete(olditem.occupies);
        return !unoccupied.includesAll(newitem.occupies);
    }

    wear_clothing(obj, closet = this.get_storage_location("dormcloset"))
    {
        let citem = (obj.constructor.name == "ClothingItem") ? obj : new ClothingItem(obj);
        citem.repair_subs();
        obj = citem.get_data_structure();

        let removed = this.clothing_would_displace(obj);

        this.clothes.push(obj);

        const to_remove = [...new Set(removed)];
        for (const tremove of to_remove)
        {
            for (let j = this.clothes.length - 1; j >= 0; j--)
            {
                let worn = new ClothingItem(this.clothes[j]);;
                if (worn.equals(tremove))
                {
                    this.clothes.splice(j, 1);
                    break;
                }
            }
            if (!setup.clothes[tremove.item].temporary)
                closet.push(tremove);
        }
    }

    clothing_would_displace(obj)
    {
        //console.log("wear_clothing: ",clone(obj));
        if (obj.constructor.name == "ClothingItem")
        {
            obj = obj.get_data_structure();
        }
        // add an item of clothing to inventory
        let cinfo = new ClothingItem(obj).get_current_archetype();
        const removed = [];

        let layer_items = []

        for (let i = this.clothes.length - 1; i >= 0; i--)
        {
            let cinfo2 = new ClothingItem(this.clothes[i]).get_current_archetype();
            // Identify all clothes that match the same 10's place for layer
            if (Math.floor(cinfo2.layer/10) == Math.floor(cinfo.layer/10))
            {
                layer_items.push([this.clothes[i],cinfo2])
            }

        }

        // sort layer items outside to inside (large to small layer)
        layer_items = layer_items.sort((a,b) => (b[1].layer - a[1].layer))

        for (let i = layer_items.length -1; i >= 0; i--)
        {
            let cinfo2_item = layer_items[i][0]
            let cinfo2 = layer_items[i][1]
            // Same Layer
            if (cinfo.layer == cinfo2.layer && cinfo2.covers.includesAny(cinfo.covers))
            {
                removed.push(cinfo2_item);
            }
            if (this.clothing_part_already_occupied_by(cinfo, cinfo2))
            {
                removed.push(cinfo2_item);
            }
            // Lower Layer
            else if (cinfo.layer < cinfo2.layer)
            {
                // skintight required
                if (!cinfo.flags.includes("skintight"))
                {
                    let skintight_required = [...cinfo2.covers]
                    if ("skintight exception" in cinfo2)
                    {
                        skintight_required = cinfo2.covers.filter(n => !cinfo2['skintight exception'].includes(n))
                    }
                    if (cinfo.covers.includesAny(skintight_required))
                    {
                        removed.push(cinfo2_item);
                    }
                }
            }
            // Higher Layer
            else if (cinfo.layer > cinfo2.layer)
            {
                // skintight required
                if (!cinfo2.flags.includes("skintight"))
                {
                    let skintight_required = [...cinfo.covers]
                    if ("skintight exception" in cinfo)
                    {
                        skintight_required = cinfo.covers.filter(n => !cinfo['skintight exception'].includes(n))
                    }
                    if (cinfo2.covers.includesAny(skintight_required))
                    {
                        removed.push(cinfo2_item);
                    }
                }
            }
        }

        return removed;
    }


remove_clothing(i, temp = true)
    {
        i = this.get_clothing_index(i);
        if (i < 0) return;
        if (temp && this.is_pc && this.clothes[i] != undefined)
        {
            var remove_list = [i];
            const base_item = this.clothing_archetype(i);
            // Identify all clothing above this item (by 'occupies')
            // remove those items as well!
            for (var clothing_item_idx in this.clothes)
            {
                try
                {
                    const temp_item = this.clothing_archetype(this.clothes[clothing_item_idx]);

                    if (temp_item.occupies && (base_item.layer < temp_item.layer))
                    {
                        var overlapping = base_item["covers"].filter(value => temp_item.occupies.includes(value));
                        if (overlapping.length > 0)
                        {
                            remove_list.push(clothing_item_idx)
                        }
                    }
                }
                catch (error)
                {
                    console.error(error);
                }
            }

            // Sort list largest to smallest so re-ordering doesn't matter
            remove_list = remove_list.sort((a,b) => b-a)

            for (var remove_item of remove_list)
            {
                // save temp removed clothes so we can restore them
                if (this.in_encounter() || tags().includes("preencounter"))
                {
                    this.encounter_removed_clothing.push(this.clothes[remove_item]);
                }
                else if (tags().includes("event"))
                {
                    this.event_removed_clothing.push(this.clothes[remove_item]);
                }
                this.clothes.splice(remove_item,1)
            }
        }
        else
        {
            this.clothes.splice(i, 1);
        }

        if (!this.is_pc && this.clothes.length == 0)
            this.set_anonymous_name();
    }

    remove_all_clothing(temp = true)
    {
        // mostly intended for automatic pre-encounter stripping
        for (let i = this.clothes.length - 1; i >= 0; i--)
        {
            this.remove_clothing(i, temp);
        }
    }

    delete_clothing(item, closet = this.get_storage_location("dormcloset"))
    {
        // removes clothing from player inv or dormcloset storage, whichever it's in, permanently
        let i = this.get_clothing_index(item);
        if (typeof i == "number")
        {
            // in player inv
            this.remove_clothing(i, false);
        }
        else
        {
            // remove from dormcloset
            if (typeof closet == "string") closet = this.get_storage_location(closet);
            closet.remove(item);
        }
    }

    fix_clothing(onlyencounter = false)
    {
        // restores normal state of clothing after an encounter or event

        if (this.encounter_removed_clothing)
        {
            for (let i = 0; i < this.encounter_removed_clothing.length; i++)
            {
                if (this.encounter_removed_clothing[i] != undefined)
                    this.clothes.push(this.encounter_removed_clothing[i]);
            }
            this.encounter_removed_clothing = [];
        }

        if (this.event_removed_clothing && !onlyencounter)
        {
            for (let i = 0; i < this.event_removed_clothing.length; i++)
            {
                if (this.event_removed_clothing[i] != undefined)
                    this.clothes.push(this.event_removed_clothing[i]);
            }
            this.event_removed_clothing = [];
        }

        for (let i = 0; i < this.clothes.length; i++)
        {
            let cinfo = new ClothingItem(this.clothes[i]);
            cinfo.remove_all_displacements();
            this.clothes[i] = cinfo.get_data_structure();
        }
    }

    only_wearing_towel()
    {
        let top = this.outermost_covering("chest");
        if (top && top.item == "Towel") return true;
        let bottom = this.outermost_covering("crotch");
        if (bottom && bottom.item == "Towel") return true;
        return false;
    }

    only_wearing_temp()
    {
        let top = this.outermost_covering("chest");
        if (top && setup.clothes[top.item].temporary) return true;
        let bottom = this.outermost_covering("crotch");
        if (bottom && setup.clothes[bottom.item].temporary) return true;
        return false;
    }

    swap_clothing_to_closet(i, closet = this.get_storage_location("dormcloset"))
    {
        if (typeof closet == "string") closet = this.get_storage_location(closet);
        i = this.get_clothing_index(i);
        let clothes = this.clothes[i];
        let temp = this.clothing_archetype(i).temporary;
        this.remove_clothing(i, false);
        if (closet.find_item_idx(clothes) == -1 && !temp)
            closet.push(clothes);
    }

    matching_items_in_closet(item, closet = this.get_storage_location("dormcloset"))
    {
        if (typeof closet == "string") closet = this.get_storage_location(closet);
        let retval = [];
        for (let i = 0; i < closet.get_item_count(); i++)
        {
            if (closet.get_item(i).item == item) retval.push(closet.get_item(i));
        }
        return retval;
    }

    matching_items_worn(item)
    {
        let retval = [];
        for (let i = 0; i < this.clothes.length; i++)
        {
            if (this.clothes[i].item == item) retval.push(this.clothes[i]);
        }
        return retval;
    }

    matching_item_worn(item)
    {
        for (let i = 0; i < this.clothes.length; i++)
        {    if (this.clothes[i].item === item) return true;
        }
        return false;
    }

    swap_all_clothing_to_closet(save = true, closet = this.get_storage_location("dormcloset"))
    {
        if (typeof closet == "string") closet = this.get_storage_location(closet);
        if (save && tags().includes("shower") && this.clothes.length > 0)
        {
            State.setVar("$clothesleftinshower", [...this.clothes]);
        }

        var tClothes = new ClothingGroup(this.clothes);
        tClothes.transfer_all_to(closet, true);

        this.remove_all_clothing(false);
    }

    wear_from_closet(item, closet = this.get_storage_location("dormcloset"))
    {
        if (typeof closet == "string") closet = this.get_storage_location(closet);
        //console.log("Wearing from closet: ", item, closet);
        var result = false;
        var tItem = closet.remove(item);
        if (tItem)
        {
            //console.log("Time to wear it!",tItem);
            this.wear_clothing(tItem);
            result = true;
        }
        return result;
    }

    wear_from_closet_approx(item, closet = this.get_storage_location("dormcloset"))
    {
        if (typeof closet == "string") closet = this.get_storage_location(closet);
        //console.log("Wearing from closet: ", item, closet);
        var result = false;

        for (let closetitem of closet.clothes)
        {
            if (closetitem.item == item.item)
            {
                result = true;
                item = closetitem;
                break;
            }
        }
        if (!result) return false;

        var tItem = closet.remove(item);
        if (tItem)
        {
            //console.log("Time to wear it!",tItem);
            this.wear_clothing(tItem);
            result = true;
        }
        return result;
    }

    has_clothing_item(clothing, closet = this.get_storage_location("dormcloset"))
    {
        if (typeof closet == "string") closet = this.get_storage_location(closet);
        for (let i = 0; i < closet.get_item_count(); i++)
        {
            if (closet.get_item(i).item == clothing.item && closet.get_item(i).name == clothing.name)
            {
                return true;
            }
        }

        for (let i = 0; i < closet.get_item_count(); i++)
        {
            if (closet.get_item(i).item == clothing.item)
            {
                return true;
            }
        }

        for (let i = 0; i < this.clothes.length; i++)
        {
            if (this.clothes[i].item == clothing.item && this.clothes[i].name == clothing.name)
            {
                return true;
            }
        }

        for (let i = 0; i < this.clothes.length; i++)
        {
            if (this.clothes[i].item == clothing.item)
            {
                return true;
            }
        }

        return false;
    }

    has_all_clothing_items(items)
    {
        for (let i = 0; i < items.length; i++)
            if (!this.has_clothing_item(items[i]))
                return false;

        return true;
    }

    has_outfit(outfitname)
    {
        const outfits = V.outfits || [];
        for (let i = 0; i < outfits.length; i++)
        {
            if (outfits[i].name == outfitname)
            {
                for (let j = 0; j < outfits[i].clothes.length; j++)
                {
                    if (!this.has_clothing_item(outfits[i].clothes[j]))
                        return false;
                }
            }
        }
        return true;
    }

    save_outfit(outfitname, clothes, outfittype="Casual")
    {
        const outfit = [];
        for (let i = 0; i < clothes.length; i++)
        {
            let outclothes = Object.assign({}, clothes[i]);
            outfit.push(outclothes);
        }

        let outfitobj = {"name": outfitname, "type": outfittype, "clothes": clothes};

        if (!V.outfits) V.outfits = [];
        V.outfits.push(outfitobj);
    }

    overwrite_outfit(outfitname, clothes)
    {
        const outfit = [];
        for (let i = 0; i < clothes.length; i++)
        {
            let outclothes = Object.assign({}, clothes[i]);
            outfit.push(outclothes);
        }

        let outfits = V.outfits || [];

        for (let i = 0; i < outfits.length; i++)
        {
            if (outfits[i].name == outfitname)
            {
                outfits[i].clothes = outfit;
            }
        }
    }

    delete_outfit(outfitname)
    {
        let outfits = V.outfits || [];

        for (let i = 0; i < outfits.length; i++)
        {
            if (outfits[i].name == outfitname)
            {
                outfits.splice(i, 1);
            }
        }

        if (outfitname == V.sleepoutfit)
        {
            delete State.variables.sleepoutfit;
        }
    }

    wear_outfit(outfitname, allowapprox = true)
    {
        this.swap_all_clothing_to_closet();
        const outfits = V.outfits || [];
        const notfound = [];
        //console.log("outfits: ",outfits)
        for (let i = 0; i < outfits.length; i++)
        {
            if (outfits[i].name == outfitname)
            {
                for (let j = 0; j < outfits[i].clothes.length; j++)
                {
                    //console.log("Wearing from closet: ",outfits[i].clothes[j]);
                    if (!this.wear_from_closet(outfits[i].clothes[j]))
                        if (!allowapprox || !this.wear_from_closet_approx(outfits[i].clothes[j]))
                            notfound.push(outfits[i].clothes[j].name);
                }
            }
        }
        return notfound;
    }

    wear_all_clothes(clothes)
    {
        for (let j = 0; j < clothes.length; j++)
        {
            this.wear_from_closet(clothes[j]);
        }
    }

    is_outfit_name_taken(outfitname)
    {
        return outfitname == "!Strip" || this.find_outfit(outfitname) != null;
    }

    find_outfit(outfitname)
    {
        const outfits = V.outfits || [];
        for (let i = 0; i < outfits.length; i++)
        {
            if (outfits[i].name == outfitname)
            {
                return outfits[i];
            }
        }
        return null;
    }

    get_clothing_index(i)
    {
        // turns a clothing item name into an index of this.clothes if it isn't already
        if (typeof i == "string")
        {
            for (let j = 0; j < this.clothes.length; j++)
            {
                if (this.clothes[j].name == i || (new ClothingItem(this.clothes[j]).get_archetype_prop("shortname")) == i)
                {
                    return j;
                }
            }
            // search for the best match
            // march from the left until a match failure, then march from the right
            // count how many steps we marched.  Highest number wins

            //console.log("get_clothing_index earching for: ",i);
            let scores = [];
            let reverse_i = i.split("").reverse().join("");
            for (let j = 0; j < this.clothes.length; j++)
            {
                scores[j] = 0;
                for (const char_idx in this.clothes[j].name)
                {
                    if (i[char_idx] != this.clothes[j].name[char_idx])
                    {
                        scores[j] = Number(char_idx);
                        break;
                    }
                }
                let reverse_name = this.clothes[j].name.split("").reverse().join("");
                for (const char_idx in reverse_name)
                {
                    if (reverse_i[char_idx] != reverse_name[char_idx])
                    {
                        scores[j] += Number(char_idx);
                        break;
                    }
                }
                //console.log("string: \""+this.clothes[j].name+"\", score: "+scores[j])
            }

            //console.log("all scores: ",scores,scores.length);
            let best_idx = 0;
            for (let score_idx = 0; score_idx < scores.length; score_idx++)
            {
                if (scores[score_idx] > scores[best_idx])
                {
                    best_idx = score_idx;
                }
            }
            //console.error("Failed to find clothing_index: ",i,this.clothes);
            return best_idx;
        }
        else if (i != null && typeof i == "object")
        {
            let iname = "get_name" in i ? i.get_name() : i.name;
            for (let j = 0; j < this.clothes.length; j++)
            {
                if (this.clothes[j].name == iname && this.clothes[j].item == i.item)
                {
                    return j;
                }
            }
            //console.error("Failed to find clothing_index: ",i,this.clothes);
        }
        return i;
    }

    clothing_slots(i)
    {
        // what slots does this clothing item cover, displacements taken into account
        i = this.get_clothing_index(i);

        let cItem = new ClothingItem(this.clothes[i]);
        let result = cItem.get_archetype_prop("covers");
        return result;
    }

    occupied_clothing_slots(i)
    {
        // what slots does this clothing item occupy (distinct from covering)
        i = this.get_clothing_index(i);

        let cItem = new ClothingItem(this.clothes[i]);
        return cItem.get_archetype_prop("occupies") || [];
    }

    sheer_clothing_slots(i)
    {
        // what slots does this clothing item occupy (distinct from covering)
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);

        if (cItem.is_wet_transparent())
            return cItem.get_archetype_prop("covers") || [];
        return cItem.get_archetype_prop("sheer") || [];
    }

    clothing_shortname(i)
    {
        return this.get_clothing_property(i,"shortname");
    }

    get_clothing_property(item, prop)
    {
        if (typeof item == "object")
            if (prop in item)
                return item[prop];
            else if (item.item && item.item in setup.clothes && prop in setup.clothes[item.item])
                return setup.clothes[item.item][prop];

        let index = this.get_clothing_index(item);
        return index ? this.clothing_archetype(index)[prop] : setup.clothes[item.item][prop];
    }

    set_clothing_property(i, prop, value)
    {
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        cItem.set_property(prop,value);
        this.clothes[i] = cItem.get_data_structure();
    }

    delete_clothing_property(i, prop)
    {
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        cItem.delete_property(prop);
        this.clothes[i] = cItem.get_data_structure();
    }

    add_clothing_displacement(i, displacement)
    {
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        cItem.add_displacement(displacement);
        this.clothes[i] = cItem.get_data_structure();
    }

    remove_clothing_displacement(i, displacement)
    {
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        cItem.remove_displacement(displacement);
        this.clothes[i] = cItem.get_data_structure();
    }

    remove_all_clothing_displacements(i)
    {
                i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        cItem.remove_all_displacements();
        this.clothes[i] = cItem.get_data_structure();
    }

    available_clothing_displacements(i)
    {
        let result = [];
        // what displacements are available for this clothing item that haven't already been done
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        let potential_displacements = cItem.get_possible_displacements();
        for (const test_displacement of potential_displacements)
        {
            if (this.has_any_of_parts(cItem.get_displacement_uncovers(test_displacement)))
            {
                result.push(test_displacement);
            }
        }
        return result;
    }

    active_clothing_displacements(i)
    {
        // what displacements have been done to this clothing item
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        return cItem.get_displacements();
    }

    get_covering_clothes(part, clothes = this.clothes) {
        const results = [];

        for (let index = 0; index < clothes.length; index++) {
            const item = new ClothingItem(clothes[index]);
            const covers = item.get_archetype_prop("covers") || [];
            const layer = item.get_archetype_prop("layer") || 0;

            if (!covers.includes(part)) continue;

            const isSheer = item.is_glasses()
                || (item.is_wet_transparent() ? covers.includes(part) : (item.get_archetype_prop("sheer") || []).includes(part));

            results.push({ index, item, layer, isSheer });
        }

        return results.sort((a, b) => b.layer - a.layer);
    }

    is_part_covered(part) {
        return this.get_covering_clothes(part).length > 0;
    }

    is_part_covered_sheer(part) {
        const clothes_on_part = this.get_covering_clothes(part);
        return clothes_on_part.length > 0 && clothes_on_part.every(cloth => cloth.isSheer);
    }

    is_part_visible(part) {
        const clothes_on_part = this.get_covering_clothes(part);
        return clothes_on_part.length === 0 || clothes_on_part.every(cloth => cloth.isSheer) || clothes_on_part.every(cloth => setup.clothes[cloth.item.item].flags.includes("glasses"));
    }

    covered_parts() {
        return this.body_parts.filter(part => this.is_part_covered(part));
    }

    outermost_covering(part, clothes = this.clothes) {
        // TODO: Refactor the consumers to not take in clothes optionally - either we are in this object or we aren't
        const clothes_on_part = this.get_covering_clothes(part, clothes);
        return clothes_on_part[0]?.item ?? null;
    }

    innermost_covering(part) {
        const clothes_on_part = this.get_covering_clothes(part);
        return clothes_on_part.at(-1)?.item ?? null;
    }

    clothing_under_outermost(part) {
        // intended for things like seeing if just underwear is under a skirt
        const clothes_on_part = this.get_covering_clothes(part);
        return clothes_on_part.length >= 2 ? clothes_on_part[1].item : null;
    }

    clothing_under_middlewear(part) {
        // intended for things like seeing if just underwear is under a skirt (this one helps us deal with (read: ignore) long coats)
        const clothes_on_part = this.get_covering_clothes(part).filter(item => item.layer < 30);
        return clothes_on_part.length >= 2 ? clothes_on_part[1].item : null;
    }

    is_clothing_exhibitionist(i)
    {
        // basically, is this item underwear and the innermost covering of an important bit?
        let item = this.clothes[this.get_clothing_index(i)];

        if (item == this.underwear_covering("crotch") || (this.has_part("breasts") && item == this.underwear_covering("breasts")))
        {
            let arch = this.clothing_archetype(item);
            return !arch.flags.includes("not exhibitionist");
        }
    }

    clothes_covering_part(part, clothes = this.clothes) {
        return this.get_covering_clothes(part, clothes).map(({ item }) => item);
    }

    clothes_occupying_part(part)
    {
        let retval = [];
        for (let i = 0; i < this.clothes.length; i++)
        {
            const slots = this.occupied_clothing_slots(i);
            if (slots.indexOf(part) != -1)
                retval.push(this.clothes[i]);
        }
        return retval;
    }

    clothing_displacements_to_expose(part, lowestlayer = 1, ps = this.is_pc ? "you" : this.ps, pp = this.is_pc ? "your" : this.pp, allowdisplacements = true) {
        const retval = [];
        const sorted_clothes = this.get_covering_clothes(part);

        for (const { item, index, layer } of sorted_clothes) {
            if (layer < lowestlayer * 10) continue;

            const archetype = item.get_current_archetype();
            let displacements = allowdisplacements ? this.available_clothing_displacements(index) : [];
            displacements.push("remove");

            for (const current_displacement of displacements) {
                if (current_displacement === "remove" || (archetype["displace " + current_displacement] || []).includes(part)) {
                    const words = current_displacement.split(" ");
                    const verb = words[0];
                    const remainder = words.length > 1 ? " " + words.slice(1).join(" ") : "";

                    retval.push(setup.ob_conjugator.conjugate(ps, verb) + remainder + " " + pp + " " + item.get_name?.());
                    break; // Only use one displacement per clothing item
                }
            }
        }
        return retval;
    }

    clothing_removal_to_expose(part, lowestlayer = 1, ps = this.is_pc ? "you" : this.ps, pp = this.is_pc ? "your" : this.pp)
    {
        return this.clothing_displacements_to_expose(part, lowestlayer, ps, pp, false);
    }

    expose_part(partToExpose, protectedParts = [], untilItem = null) {
        const clothes = this.get_covering_clothes(partToExpose);

        const to_remove = [];
        for (const { item, index } of clothes) {
            if (item.item == untilItem?.item) break;

            const clothing_parts = this.clothing_slots(item);
            const intersectsProtected = protectedParts.some(part => clothing_parts.includes(part));

            if (intersectsProtected) {
                const archetype = item.get_current_archetype();
                const displacements = this.available_clothing_displacements(index);
                displacements.push("remove");

                for (const disp of displacements) {
                    if (disp === "remove" || (archetype["displace " + disp] || []).includes(partToExpose)) {
                        item.add_displacement(disp);
                        break;
                    }
                }
            } else {
                to_remove.push(item);
            }
        }
        for (let item of to_remove)
            this.remove_clothing(item);
    }

    displace_to_expose(part) {
        this.expose_part(part);
    }

    expose_bra() {
        const part = "chest";
        const bra = this.underwear_covering(part);
        this.expose_part(part, ["crotch"], bra);
    }

    expose_only_chest() {
        this.expose_part("chest", ["crotch"]);
    }

    expose_underwear() {
        const part = "crotch";
        const underwear = this.underwear_covering(part);
        this.expose_part(part, ["chest"], underwear);
    }

    expose_only_crotch() {
        this.expose_part("crotch", ["chest"]);
    }

    expose_only_ass() {
        this.expose_part("butt", ["chest"]);
    }
    expose_only_foot() {
        this.expose_part("foot", ["crotch"]);
    }

    fingernails_visible()
    {
        if (this.is_part_visible("hand")) return true;
        let gloves = this.get_covering_clothes("hand");
        for (let glove of gloves)
            if (!this.clothing_archetype(glove.index).flags.includes("fingerless"))
                return false;
        return true;
    }

    toenails_visible()
    {
        if (this.is_part_visible("foot")) return true;
        let footwear = this.get_covering_clothes("foot");
        for (let shoe of footwear)
            if (!this.clothing_archetype(shoe.index).flags.includes("open toe"))
                return false;
        return true;
    }

    clothing_layer(i)
    {
        return this.clothing_archetype(i).layer;
    }

    sort_clothing_by_layer(clothes)
    {
        const retval = [...clothes];
        retval.sort((a, b) => this.clothing_layer(a) - this.clothing_layer(b));
        return retval;
    }

    clothing_by_part_layergroup(part, layergroup, reversesort = false)
    {
        var result = [];
        if (this.is_part_covered(part))
        {
            var clothing_list = []
            for (let i = 0; i < this.clothes.length; i++)
            {
                const slots = this.clothing_slots(i);
                if (slots.indexOf(part) != -1)
                {
                    let tlayer = this.clothing_layergroup(this.clothes[i]);
                    if (tlayer == layergroup)
                    {
                        clothing_list.push(this.clothes[i])
                        //return this.clothes[i];
                    }
                }
            }
            if (clothing_list)
            {
                // put the most-outer clothing at the beginning of the list (unless using optional 'reversesort' parameter)
                var clothing_list_sorted = this.sort_clothing_by_layer(clothing_list);
                if (!reversesort) clothing_list_sorted.reverse(); // we're expecting outermost => innermost so not reversing is reversed so... well, you understand
                result = clothing_list_sorted;
            }
        }
        return result;
    }

    underwear_covering(part, findinnermost = true)
    {
        return this.clothing_by_part_layergroup(part, 1, findinnermost)[0];
    }

    middlewear_covering(part, findinnermost = false)
    {
        return this.clothing_by_part_layergroup(part, 2)[0];
    }

    outerwear_covering(part, findinnermost = false)
    {
        return this.clothing_by_part_layergroup(part, 3)[0];
    }

    wearing_bra()
    {
        return this.has_breasts() && !!this.underwear_covering("breasts");
    }

    wearing_only_bra()
    {
        return this.wearing_bra() && this.underwear_covering("breasts").item === this.outermost_covering("breasts")?.item;
    }

    lacking_bra()
    {
        return this.has_breasts() && !this.wearing_bra() && !this.topless();
    }

    wearing_bra_top()
    {
        // whether wearing something called "bra top"
        // not of much mechanical relevance but it solves a display issue
        let item = this.middlewear_covering("chest");
        if (!item) return false;
        return item.name.includes(" bra top");
    }

    hiding_breasts()
    {
        let binder = this.underwear_covering("breasts");
        if (binder != null)
        {
            return this.clothing_archetype(binder).flags.includes("hide breasts");
        }
        else
        {
            return false;
        }
    }

    wearing_underwear()
    {
        return !!this.underwear_covering("crotch");
    }

    wearing_shirt()
    {
        return !!this.middlewear_covering("chest");
    }

    can_remove_just_top()
    {
        return this.wearing_shirt() &&
                (!this.outerwear_covering("chest") || this.outerwear_covering("chest") != this.outerwear_covering("crotch")) &&
                (!this.middlewear_covering("chest") || this.middlewear_covering("chest") != this.middlewear_covering("crotch")) &&
                (!this.underwear_covering("chest") || this.underwear_covering("chest") != this.underwear_covering("crotch"));
    }

    wearing_top()
    {
        return this.shirt_equiv() != null;
    }

    wearing_swimwear_top()
    {
        let top = this.underwear_covering("breasts");
        return !!(top && this.clothing_archetype(top).category == "swimwear");
    }

    wearing_swimwear_bottom()
    {
        let bot = this.underwear_covering("crotch");
        return !!(bot && this.clothing_archetype(bot).category == "swimwear");
    }

    topless()
    {
        return !this.wearing_bra() && !this.wearing_top();
    }

    bottomless()
    {
        return !this.wearing_underwear() && !this.wearing_pants();
    }

    wearing_pants()
    {
        return (!!this.middlewear_covering("crotch") ||
                !!this.outerwear_covering("crotch")  ||
                (!!this.underwear_covering("crotch") && this.underwear_ok_as_outerwear()))
            && (!!this.middlewear_covering("butt") ||
                !!this.outerwear_covering("butt")  ||
                (!!this.underwear_covering("butt") && this.underwear_ok_as_outerwear()));
    }

    wearing_jacket()
    {
        return !!this.jacket();
    }

    wearing_shoes()
    {
        return !!this.outerwear_covering("foot");
    }

    shirt_equiv()
    {
        if (!!this.outerwear_covering("chest"))
            return this.outerwear_covering("chest");
        else if (!!this.middlewear_covering("chest"))
            return this.middlewear_covering("chest");
        else if (!!this.underwear_covering("chest") && !this.is_bra_a_bra())
            return this.underwear_covering("chest");
        else if (this.underwear_covering("chest")?.item == this.underwear_covering("crotch")?.item)
            return this.underwear_covering("chest");
        else
            return null;
    }

    pants_equiv()
    {
        if (this.outerwear_covering("crotch") != null)
            return this.outerwear_covering("crotch");
        else if (this.middlewear_covering("crotch") != null)
            return this.middlewear_covering("crotch");
        else if (this.underwear_covering("crotch", false) != null && (!this.is_underwear_underwear() || this.underwear_ok_as_outerwear()))
            return this.underwear_covering("crotch", false);
        else
            return null;
    }

    pants_or_underwear()
    {
        return this.pants_equiv() || this.underwear_covering("crotch");
    }

    chest_exposed()
    {
        return this.clothes_covering_part("chest").length == 0;
    }

    crotch_exposed()
    {
        return this.clothes_covering_part("crotch").length == 0;
    }

    bra_visible()
    {
        return this.wearing_bra() && this.outermost_covering("breasts").item === this.underwear_covering("breasts").item && (this.is_bra_a_bra() || this.bra_ok_as_outerwear());
    }

    swim_top_visible()
    {
        return this.wearing_bra() && this.outermost_covering("breasts").item === this.underwear_covering("breasts").item && this.wearing_swimwear_top();
    }

    underwear_visible()
    {
        return this.wearing_underwear() && this.outermost_covering("crotch").item === this.underwear_covering("crotch").item && this.is_underwear_underwear();
    }

    swim_bottom_visible()
    {
        return this.wearing_underwear() && this.outermost_covering("crotch").item === this.underwear_covering("crotch").item && this.wearing_swimwear_bottom();
    }

    wearing_dress()
    {
        return this.middlewear_covering("chest") != null && this.middlewear_covering("chest") == this.middlewear_covering("crotch") && this.under_access();
    }

    wearing_fullbody()
    {
        if (this.middlewear_covering("chest") != null)
            return this.middlewear_covering("chest") == this.middlewear_covering("crotch") && !this.under_access();
        else if (this.outerwear_covering("chest") != null)
            return this.outerwear_covering("chest") == this.outerwear_covering("crotch") && !this.under_access();
        else if (this.underwear_covering("chest") != null)
            return this.underwear_covering("chest") == this.underwear_covering("crotch") && !this.under_access();
        else
            return false;
    }

    not_wearing_dress_or_fullbody()
    {
        return !this.wearing_dress() && !this.wearing_fullbody();
    }

    occupying_part(part)
    {
        return this.clothes_occupying_part(part)[0];
    }

    is_part_occupied_by_clothing(part)
    {
        // not to be confused with a part being occupied in an encounter
        // which is a different system
        for (let i = 0; i < this.clothes.length; i++)
        {
            const slots = this.occupied_clothing_slots(i);
            if (slots.indexOf(part) != -1) return true;
        }
        return false;
    }

    can_flash_bra()
    {
        // end up writing this same check a lot, let's condense
        // is flashing the bra meaningful? does the bra exist, is it not already visible, is it not actually just swimwear, is it not sheer?
        return this.wearing_bra() && !this.bra_visible() && !this.is_bra_sheer() && (this.is_bra_a_bra() || this.wearing_swimwear_top() || this.bra_ok_as_outerwear());
    }

    can_flash_underwear()
    {
        return this.wearing_underwear() && !this.underwear_visible() && !this.is_underwear_sheer() && (this.is_underwear_underwear() || this.wearing_swimwear_bottom());
    }

    can_flash_belly()
    {
        // is flashing the stomach an easy lift of a shirt?
        if (!this.is_part_covered("stomach"))
            return false;
        else
        {
            for (let item of this.clothes_covering_part("stomach"))
            {
                if (this.clothing_slots(item).includes("crotch"))
                    return false;
            }
            return true;
        }
    }

    is_bra_exhibitionist()
    {
        let item = this.underwear_covering("chest");
        if (!item) return true;
        let arch = this.clothing_archetype(item);
        return !arch.flags.includesAny(["not exhibitionist", "non-underwear"]);
    }

    is_layer_under_shirt_exhibitionist()
    {
        let outer = this.outermost_covering("chest");
        if (!outer)
            return true;
        else if (outer == this.underwear_covering("chest"))
            return this.is_bra_exhibitionist();
        else
        {
            let underneath = this.clothing_under_outermost("chest");
            if (!underneath)
                return true;
            else if (underneath.item == this.underwear_covering("chest")?.item)
                return this.is_bra_exhibitionist();
            else
                return false;
        }
    }

    is_underwear_exhibitionist()
    {
        let item = this.underwear_covering("crotch");
        if (!item) return true;
        let arch = this.clothing_archetype(item);
        return !arch.flags.includesAny(["not exhibitionist", "non-underwear"]);
    }

    is_upskirt_exhibitionist()
    {
        return this.underwear_access() && (!this.wearing_underwear() || this.is_underwear_exhibitionist());
    }

    is_upshorts_exhibitionist()
    {
        return (!this.anything_under_pants() || this.underwear_covering("crotch") == this.clothing_under_outermost("crotch")) && (!this.wearing_underwear() || this.is_underwear_exhibitionist());
    }

    under_access()
    {
        let flags = this.get_clothing_flags("crotch", 4);
        return flags.includes("under access");
    }

    elastic_waistband()
    {
        let flags = this.get_clothing_flags("crotch");
        return flags.includes("elastic waistband") && !this.outerwear_covering("crotch");
    }

    underwear_access()
    {
        // close cousin to under_access in this new many-layered world
        // returns true if underwear is the next thing under a skirt
        // (note it'll also return true if wearing nothing under a skirt)
        if (this.under_access())
        {
            let within = this.clothing_under_outermost("crotch");
            return !within || within.equals(this.underwear_covering("crotch"));
        }
        return false;
    }

