    clothing_item_safe_to_delete(item)
    {
        const archetype = new ClothingItem(item).get_current_archetype();
        let checkcover, checklayer;
        if (archetype.covers.includes("chest") && Math.floor(archetype.layer/10) == 2)
        {
            checkcover = "chest";
            checklayer = 2;
        }
        else if (archetype.covers.includes("crotch") && Math.floor(archetype.layer/10) == 2)
        {
            checkcover = "crotch";
            checklayer = 2;
        }
        else if (archetype.covers.includes("foot") && Math.floor(archetype.layer/10) == 3)
        {
            checkcover = "foot";
            checklayer = 3;
        }
        else if (archetype.covers.includes("chest") && Math.floor(archetype.layer/10) == 1 && this.has_part("breasts") && !this.skillleveled("Exhibitionism", 2))
        {
            checkcover = "chest";
            checklayer = 1;
        }
        else if (archetype.covers.includes("crotch") && Math.floor(archetype.layer/10) == 1 && !this.skillleveled("Exhibitionism", 3))
        {
            checkcover = "crotch";
            checklayer = 1;
        }
        else
        {
            checkcover = null;
        }

        if (checkcover)
        {
            let found = false;
            for (const clothes of this.clothes)
            {
                let cinfo = new ClothingItem(clothes).get_current_archetype();
                if (cinfo.covers.includes(checkcover) && Math.floor(cinfo.layer/10) == checklayer && !cinfo.temporary)
                {
                    found = true;
                    break;
                }
            }
            for (const clothes of this.get_storage_location("dormcloset"))
            {
                let cinfo = new ClothingItem(clothes).get_current_archetype();
                if (cinfo.covers.includes(checkcover) && Math.floor(cinfo.layer/10) == checklayer && !cinfo.temporary && (clothes.item != item.item || clothes.name != item.name))
                {
                    found = true;
                    break;
                }
            }
            return found;
        }
        else
        {
            return true;
        }
    }

    fully_dressed(shoelessok = false)
