    not_fully_dressed_reason(countsheer = false)
    {
        if (!this.wearing_top() && !this.wearing_pants())
            return "You're not wearing a top or bottom.";
        else if (!this.wearing_top())
            return "You're not wearing a top.";
        else if (!this.wearing_pants())
            return "You're not wearing a bottom.";
        else if (this.has_breasts() && this.is_part_visible("nipples") && countsheer)
            return "Your nipples are visible.";
        else if (this.is_part_visible("crotch") && countsheer)
            return "Your " + (this.has_part("penis") ? "dick" : "vag") + " is visible.";
        else if (this.has_part("penis") && !this.is_part_covered("penis"))
            return "Your penis is visible.";
        else if (!this.wearing_shoes())
            return "You're not wearing shoes.";
    }

    all_storage_flags()
    {
        let storage_flags = []
        for (let i = 0; i < this.clothes.length; i++)
        {
            let cinfo = new ClothingItem(this.clothes[i]).get_current_archetype();
            if (cinfo.storage)
            {
                storage_flags.push(...cinfo.storage)
            }
        }
        if (this.encounter_removed_clothing)
            for (let i = 0; i < this.encounter_removed_clothing.length; i++)
            {
                let cinfo = new ClothingItem(this.encounter_removed_clothing[i]).get_current_archetype();
                if (cinfo.storage)
                {
                    storage_flags.push(...cinfo.storage)
                }
            }
        if (this.event_removed_clothing)
            for (let i = 0; i < this.event_removed_clothing.length; i++)
            {
                let cinfo = new ClothingItem(this.event_removed_clothing[i]).get_current_archetype();
                if (cinfo.storage)
                {
                    storage_flags.push(...cinfo.storage)
                }
            }
        return [...new Set(storage_flags)]
    }

    has_storage()
    {
        let all_storage = this.all_storage_flags()
        return all_storage.length > 0
    }

    // Extend this to take an argument of a piece of clothing?
    has_pockets(clothing_items=this.clothes)
    {
        // if given a single item put it into an array.
        if (clothing_items.constructor !== Array)
        {
            clothing_items = [clothing_items]
        }
        let pocketcount = 0;
        for (let i = 0; i < clothing_items.length; i++)
        {
            let cinfo = new ClothingItem(clothing_items[i]).get_current_archetype();
            if (this.clothing_layergroup(cinfo) != 4) // Ignore the 'bags' layers - we're just looking for pockets
            {
                if (cinfo.storage && (cinfo.storage.includes("cards") || cinfo.storage.includes("phone")))
                {
                    pocketcount++;
                }
            }
        }
        //console.log("Pockets Found: "+pocketcount)
        return pocketcount > 0;
    }

    // Extend this to take an argument of a piece of clothing?
    has_hidden_storage()
    {
        let all_storage = this.all_storage_flags()
        return (all_storage.includes("cards hide") || all_storage.includes("phone hide"));
    }

    has_laptop_storage()
    {
        let all_storage = this.all_storage_flags()
        return (all_storage.includes("laptop"));
    }

