    has_storage_sized(keyword)
    {
        let all_storage = this.all_storage_flags()
        let sized_storage = all_storage.filter(s => s.includes(keyword))
        if ((sized_storage.filter(s => s.includes("large"))).length > 0)
        {
            return 3;
        }
        else if ((sized_storage.filter(s => s.includes("medium"))).length > 0)
        {
            return 2;
        }
        else if ((sized_storage.filter(s => s.includes("small"))).length > 0)
        {
            return 1;
        }
        else if (sized_storage.length > 0) // dare we assume a keyword with non-specified size is at least small?
        {
            return 1;
        }
        return 0;
    }

    primary_storage_item()
    {
        let moststorage = null;
        let moststoragecount = 0;
        for (const item of this.clothes)
        {
