    is_in_outfit(clothes, exactname = false)
    {
        // checks against the archetype outfits from setup.ob_outfits and makes sure outermost stuff matches
        const shouldbecovered = [];
        const acceptedpieces = [];
        const ignore = ["foot", "stomach", "face"];
        for (const clothing of clothes)
        {
            const cinfo = new ClothingItem(clothing).get_current_archetype();
            for (let c of cinfo.covers)
                if (!shouldbecovered.includes(c) && !ignore.includes(c))
                    shouldbecovered.push(c);

            acceptedpieces.push(exactname ? clothing.name : clothing.item);
        }
        for (let slot of shouldbecovered)
        {
            let outermost = this.outermost_covering(slot);
            if (!outermost || !(exactname ? acceptedpieces.includes(outermost.name) : acceptedpieces.includes(outermost.item)))
                return false;
        }
        return true;
    }

    is_in_uniform(uniform)
    {
        if (setup.ob_outfits[uniform].mustbeexposed)
        {
            for (let slot of setup.ob_outfits[uniform].mustbeexposed)
                if (this.is_part_covered(slot))
                    return false;
        }
        const femmeoutfit = setup.build_outfit("female", this.body_parts, uniform);
        const mascoutfit = setup.build_outfit("male", this.body_parts, uniform);
        return this.is_in_outfit(femmeoutfit) || this.is_in_outfit(mascoutfit);
    }

    in_character_costume()
    {
        for (let costume of Object.keys(setup.ob_outfits).filter(costume => setup.ob_outfits[costume].costume))
        {
            const femmeoutfit = setup.build_outfit("female", this.body_parts, costume);
            const mascoutfit = setup.build_outfit("male", this.body_parts, costume);
            if (this.is_in_outfit(femmeoutfit) || this.is_in_outfit(mascoutfit))
                return costume;
        }
    }

    is_dressed_for_sport(sport, isgameday = false)
    {
        const sportinfo = setup.School.sports[sport];

        if (!isgameday && !sportinfo.uniformatpractice)
        {
            return true;
        }

        let possible = [];
        let shop = setup.ob_shops.db["Varsity Sports Uniforms"];
        for (let item of shop.items)
            if (item.checkvar && Scripting.evalTwineScript(item.checkvar))
                possible.push(item.item);

        if (possible.length == 0)
            return true;
        else
            for (let outfit of possible)
                if (this.is_in_uniform(outfit))
                    return true;
            return false;
    }

