    wearing_skintight_pants()
    {
        let items = this.clothes;

        if (items.some(item => {
            const cinfo = setup.clothes[item.item];
            return cinfo.category == "bottoms" && (cinfo.flags.includes("skintight") || !cinfo.flags.includes("hide bulge"));
        })) return true;

        if (!items.some(item => setup.clothes[item.item].category == "bottoms") && items.some(item => {
            const cinfo = setup.clothes[item.item];
            return cinfo.covers.includes("crotch") && cinfo.category == "underwear" && cinfo.flags.includesAny(["non-underwear", "outerwear ok"]);
        })) return true;

        return false;
    }

    jacket()
    {
        // return a jacket, if the person is wearing one
        // what's a jacket? well that's a little subjective...

        let jacket = this.outerwear_covering("back");
        if (jacket)
        {
            const cinfo = setup.clothes[jacket.item];
            if (cinfo.flags.includesAny(["slightly warming", "moderately warming", "heavily warming", "very heavily warming"]))
                return jacket;
