    fully_dressed_outfits()
    {
        //console.log("fully_dressed_outfits")
        const reject = ["QuickieBurger Polo"];
        const retval = [];
        for (const outfit of (V.outfits || []))
        {
            if (outfit.name == V.lastpickedoutfit || outfit.type != "Casual") continue;

            let shoes = false;
            let top =  false;
            let bottom = false;
            const clothes = outfit.clothes;
            for (const clothing of clothes)
            {
                try
                {
                    if (reject.includes(clothing.item)) continue;

                    const cinfo = new ClothingItem(clothing).get_current_archetype();
                    if (cinfo.covers.includes("chest") && this.clothing_layergroup(cinfo) >= 2)
                        top = true;
                    if (cinfo.covers.includes("crotch") && this.clothing_layergroup(cinfo) >= 2)
                        bottom = true;
                    if (cinfo.covers.includes("foot") && this.clothing_layergroup(cinfo) >= 2)
                        shoes = true;

                    if (top && bottom && shoes)
                    {
                        retval.push(outfit);
                        break;
                    }
                }
                catch (error)
                {
                    console.log(error, clothing);
                }
            }
        }
        return retval;
    }

