    add_stain(i, stain)
    {
        i = this.get_clothing_index(i);
        if (setup.ob_clothes_stainless.includes(this.clothing_archetype(i).category) || this.clothing_has_flag(i, "waterproof")) return;

        let cItem = new ClothingItem(this.clothes[i]);
        let stains = cItem.get_property("stains") || [];
        if (!stains.includes(stain))
            stains.push(stain);
        cItem.set_property("stains",stains);
        this.clothes[i] = cItem.get_data_structure();
    }

    clear_stains(i)
    {
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        cItem.delete_property("stains");
        this.clothes[i] = cItem.get_data_structure();
    }

    add_wetness(i, wetness = 1000)
    {
        i = this.get_clothing_index(i);
        let cItem = new ClothingItem(this.clothes[i]);
        cItem.add_wetness(wetness);
        this.clothes[i] = cItem.get_data_structure();
