    add_wetness_part(part, outer = true, wetness = 1000)
    {
        let item;
        if (outer)
            item = this.outermost_covering(part);
        else
            item = this.innermost_covering(part);

        if (!item) return;
        this.add_wetness(item, wetness);
    }

    add_wetness_all(wetness = 1000, visibleonly = false)
    {
        let items;
        if (visibleonly)
            items = this.visible_clothing_items(null);
        else
            items = this.clothes;

        for (let i = 0; i < items.length; i++)
        {
            this.add_wetness(items[i], wetness);
        }
    }

