    already_has_clothing(item)
    {
        var result = false;
        var currently_wearing = new ClothingGroup(this.clothes);

        result = (currently_wearing.find_item_idx(item) >= 0)
        if (!result)
        {
            result = (this.get_storage_location("dormcloset").find_item_idx(item) >= 0)
        }
        return result;
    }

    already_has_clothing_item(item)
    {
        var currently_wearing = this.clothes;

        if (currently_wearing.filter(citem => citem.item == item).length > 0) return true;

        if (V.clothingStorage_dormcloset.filter(citem => citem.item == item).length > 0) return true;

        return false;
