    outfit_clothing_names(outfit)
    {
        // get the names of all clothing items in an outfit
        if (typeof outfit == "object")
            return outfit.clothes.map(item => item.name);

        for (let soutfit of (V.outfits || []))
        {
            if (soutfit.name == outfit)
                return soutfit.clothes.map(item => item.name);
        }

        return [];
    }

    wearing_an_outfit()
    {
        // return whether we are wearing any saved outfit (and provides outfit name if true)
        const worn = this.worn_clothing_names().sort();

        for (let outfit of (V.outfits || []))
        {
            const oclothes = this.outfit_clothing_names(outfit).sort();
            if (oclothes.length != worn.length) continue;
            const match = worn.every((item, i) => {
                const oitem = oclothes[i];
                const twords = item.split(' ');
                const owords = oitem.split(' ');

                if (twords.length != owords.length) return false;

                return owords.every((oword, wi) => {
                    return oword.startsWith("%") || oword == twords[wi];
                });
            });

            if (match)
                return outfit.name;
        }
        return false;
    }

    wearing_swimwear()
    {
        // if we're properly dressed in swimwear (no other type of clothing, no bits showing)
        const allowedcategories = ["swimwear", "accessories", "hats", "bags", "masks"];
        if (!this.is_part_covered("crotch") || (this.has_part("breasts") && !this.is_part_covered("breasts")))
            return false;
        else
            for (let i = 0; i < this.clothes.length; i++)
                if (!allowedcategories.includes(new ClothingItem(this.clothes[i]).get_archetype_prop("category")))
                    return false;

        return true;
    }

    wearing_some_swimwear()
    {
        return this.wearing_swimwear_top() || this.wearing_swimwear_bottom();
    }

    wearing_gloves()
    {
        return !!this.outermost_covering("hand");
