    // Returns true/false on if the clothing on the given layerset(see above)
    // that covers 'covers' can do 'do_this'.
    // For example, clothing_might("chest","nipslip") would return if the
    // middlewear clothing that covers the chest might nipslip.
    clothing_might(covers, do_this, layerset = 2)
    {
        if (covers == "breasts" && !this.has_breasts()) return false;
        else if (!this.has_part(covers)) return false;

        let flags = this.get_clothing_flags(covers, layerset);

        if (!do_this.includes("chance"))
            do_this = do_this+" chance";

        let type = do_this.replace(" chance", "");

        return flags.filter(s => s.includes(do_this) && this.clothing_malfunction_chance(type, s.replace(`${do_this} `, ""))).length > 0;
    }

    // Returns true/false on if the clothing on the given layerset that covers 'covers'
    //  will do 'do_this'.
    // This includes a random element with 80% chance for 'high', 50% chance for 'medium',
    //  and 20% chance for 'low'.
    // For example, clothing_will("chest","nipslip") would have an 80% chance of
    // returning true if the middlewear item on the chest has the flag "nipslip chance high".
    clothing_will(covers, do_this, layerset = 2)
    {
        if (covers == "breasts" && !this.has_breasts()) return false;
        else if (!this.has_part(covers)) return false;

        let flags = this.get_clothing_flags(covers, layerset);

        if (!do_this.includes("chance"))
            do_this = do_this+" chance";

        let type = do_this.replace(" chance", "");

        let action_flags = flags.filter(s => s.includes(do_this))

        if (action_flags.some(s => s.includes("certain")))
            return true;
        if (action_flags.some(s => s.includes("high")))
            return State.random() <= this.clothing_malfunction_chance(type, "high");
        if (action_flags.some(s => s.includes("medium")))
            return State.random() <= this.clothing_malfunction_chance(type, "medium");
        if (action_flags.some(s => s.includes("low")))
            return State.random() <= this.clothing_malfunction_chance(type, "low");
        return false;
    }

    clothing_might_difficulty(covers, do_this, layerset = 2)
    {
        // turns the chances of a thing happening into a difficulty level for skillchecks
        // more likely = higher difficulty (to avoid)
        // to check against Voyeurism, do 10 - return value

        if (covers == "breasts" && !this.has_breasts()) return 99;
        else if (!this.has_part(covers)) return 99;

        let chanceindex = 0;
        if (this.has_inclination("Lucky"))
            chanceindex = 1;
        else if (this.has_inclination("Unlucky") || this.has_inclination("Lewd Exhibitionist"))
            chanceindex = 2;

        let flags = this.get_clothing_flags(covers, layerset);
        if (!do_this.includes("chance"))
            do_this = do_this+" chance";

        let type = do_this.replace(" chance", "");

        let action_flags = flags.filter(s => s.includes(do_this))

        let basediff;
        if (action_flags.some(s => s.includes("certain")))
            basediff = [10, 8, 12][chanceindex];
        else if (action_flags.some(s => s.includes("high")))
            basediff = [8, 6, 10][chanceindex];
        else if (action_flags.some(s => s.includes("medium")))
            basediff = [6, 4, 8][chanceindex];
        else if (action_flags.some(s => s.includes("low")))
            basediff = [4, 2, 6][chanceindex];
        else
            return 99;

        let mod = this.clothing_malfunction_modifier(type);
        if (mod <= 0) return 99;
        else if (mod >= 1) return basediff;

        return Math.max(1, Math.round(basediff * mod));
    }

    clothing_malfunction_chance(type, magnitude)
    {
        if (magnitude == "certain") return 1;

        let chanceindex = 0;
        if (this.has_inclination("Lucky"))
            chanceindex = 1;
        else if (this.has_inclination("Unlucky"))
            chanceindex = 2;

        let chance;
        if (magnitude == "high")
            chance = [0.8, 0.6, 0.95][chanceindex];
        else if (magnitude == "medium")
            chance = [0.5, 0.35, 0.65][chanceindex];
        else
            chance = [0.2, 0.1, 0.3][chanceindex];

        return chance * this.clothing_malfunction_modifier(type);
    }

    clothing_malfunction_modifier(type)
    {
        switch (type)
        {
            case "shirtbust":
            {
                // returns a modifying factor (generally 0-1) for shirtbust chances, taking breast size into account
                if (!this.has_breasts()) return 0;
                let size = this["breast size"];
                if (size < 600) return 0; // sorry, this pretty much only makes sense for being on the larger side!
                if (size >= 1000) return 1;

                let mod = (size - 600) / 400;
                return mod * mod * (3 - 2 * mod);
            }
            default:
                return 1;
        }
    }

    has_visible_muscles(maleonly = true)
    {
        // this is by default only for masc types...
        // because we're doing "traditionally attractive" here and society is what it is
        // and also in terms of balance, male PCs don't get the sort of passive attraction that fem PCs do
        // so this makes up for it somewhat
        if (maleonly && !setup.people.is_masc(this)) return false;
        if (this.has_muscles(maleonly))
        {
            if (!this.is_part_covered("chest"))
            {
                return true;
            }
            else
            {
                let visible = false;
                for (let i = 0; i < this.clothes.length; i++)
                {
                    let slots = this.clothing_slots(i);

                    if (slots.includes("chest"))
                    {
                        if (!this.is_skintight(i) && slots.includes("upper arm"))
                        {
                            visible = false;
                            break;
                        }
                        else
                        {
                            visible = true;
                        }
                    }
                }
                return visible;
            }
        }
        return false;
    }

    has_muscles(maleonly = true)
    {
        if (maleonly && !setup.people.is_masc(this)) return false;
        return this["muscle"] >= 500 && this["plumpness"] < 500;
    }

    // This identifies the clothing that covers 'covers' and is on the given
    // layerset (1=underwear, 2=middlewear, 3=outerwear, if any other value,
    // finds the outermost clothing that covers covers) -
    // then it returns the flags array for that clothing.
    get_clothing_flags(covers, layerset=2)
    {
        let item = null;
        switch(layerset)
        {
            case 1:
                item = this.underwear_covering(covers);
                break;
            case 2:
                item = this.middlewear_covering(covers);
                break;
            case 3:
                item = this.outerwear_covering(covers);
                break;
            default:
                item = this.outermost_covering(covers);
        }
        if (item == null)
            return [];
        return new ClothingItem(item).get_archetype_prop("flags");
    }

    get_occupying_clothing_flags(covers)
    {
        let alloccupying = this.clothes_occupying_part(covers);
        let flags = new Set();

        alloccupying.forEach(item => {
            let tflags = new ClothingItem(item).get_archetype_prop("flags") || [];
            tflags.forEach(flag => flags.add(flag));
        });

        return [...flags];
    }

    get_clothing_name(covers, layerset=2)
    {
        let item = null;
        switch(layerset)
        {
            case 1:
                item = this.underwear_covering(covers);
                break;
            case 2:
                item = this.middlewear_covering(covers);
                break;
            case 3:
                item = this.outerwear_covering(covers);
                break;
            default:
                item = this.outermost_covering(covers);
        }
        if (item == null)
            return [];
        return new ClothingItem(item).get_name();
    }

