    is_clothing_obscured(i)
    {
        // is this bit of clothing completely covered by other clothing at higher layers?
        i = this.get_clothing_index(i);
        const slots = this.clothing_slots(i);
        if (slots.length == 0) return false;
        let cinfo = this.clothes[i];
        let layer = new ClothingItem(cinfo).get_archetype_prop("layer");

        const exposedslots = [...slots];
        for (let j = 0; j < this.clothes.length; j++)
        {
            let tcinfo = this.clothes[j];
            let tgenericlayer = new ClothingItem(tcinfo).get_archetype_prop("layer");
            if (tgenericlayer > layer)
            {
                const tslots = this.clothing_slots(j);
                for (let k = 0; k < tslots.length; k++)
                {
                    let l = exposedslots.indexOf(tslots[k]);
                    if (l != -1) exposedslots.splice(l, 1);
                }
            }
        }
        return exposedslots.length == 0;
    }

    is_clothing_partially_obscured(i)
    {
        // is this bit of clothing partially covered by other clothing at higher layers?
        i = this.get_clothing_index(i);
        const slots = this.clothing_slots(i);
        let cinfo = this.clothes[i];
        let layer = new ClothingItem(cinfo).get_archetype_prop("layer");
        const exposedslots = [...slots];
        for (let j = 0; j < this.clothes.length; j++)
        {
            let tcinfo = this.clothes[j];
            let tgenericlayer = new ClothingItem(tcinfo).get_archetype_prop("layer");
            if (tgenericlayer > layer)
            {
                let tslots = this.clothing_slots(j);
                if (tslots.includes("crotch") && this.clothing_has_flag(j, "under access"))
                    tslots.delete("crotch");
                for (let k = 0; k < tslots.length; k++)
                {
                    let l = exposedslots.indexOf(tslots[k]);
                    if (l != -1) exposedslots.splice(l, 1);
                }
            }
        }
        return exposedslots.length != slots.length;
    }

    visible_clothing_items(viewer = this, categories)
    {
        // returns list of visible clothes, sorted by category

        let sortbox = {};
        for (let i = 0; i < setup.ob_clothes_categories.length; i++)
        {
            sortbox[setup.ob_clothes_categories[i]] = [];
        }
        sortbox["other"] = [];

        for (let i = 0; i < this.clothes.length; i++)
        {
            if ((viewer && viewer.equals(this)) || !this.is_clothing_obscured(i))
            {
                let cinfo = new ClothingItem(this.clothes[i]).get_current_archetype();
                if (categories && !categories.includes(cinfo.category)) continue;
                if (!sortbox[cinfo.category])
                    sortbox["other"].push([this.clothes[i], cinfo.layer]);
                else
                    sortbox[cinfo.category].push([this.clothes[i], cinfo.layer]);
            }
        }

        const retval = [];
        for (const [cat, catclothes] of Object.entries(sortbox))
        {
            // go through and sort by layer within each category (higher layer first)
            catclothes.sort((a,b) => (b[1]-a[1]))
            for (let i = 0; i < catclothes.length; i++)
            {
                retval.push(catclothes[i][0]);
            }
        }

        return retval;
    }

    visible_clothing(viewer = this, plainnames = false)
    {
        // returns list of names of visible clothes, sorted by category

        const retval = [];

        let items = this.visible_clothing_items(viewer);
        for (let item of items)
        {
            let cinfo = new ClothingItem(item).get_current_archetype();
            retval.push(this.clothing_name(item, false, plainnames));
        }

        return retval;
    }

    visible_clothing_with_flag(flag)
