    clothing_swap_sellable(item)
    {
        // returns if clothing item can be sold to npc

        let temp_pc = new Person(this);
        temp_pc.remove_clothing(item);
        return temp_pc.clothing_swap_dressed_ok();
    }

    clothing_swap_tradable(item, npc)
    {
        // returns if clothing item can be traded to npc

        let npc_item = this.clothing_swap_compatible_item(item, npc);
        if (!npc_item) return false;
        if (setup.pc().already_has_clothing(npc_item)) return false;
        if (!setup.pc().clothing_item_safe_to_delete(item)) return false;

        let temp_pc = new Person(this);
        temp_pc.remove_clothing(item);
        temp_pc.wear_clothing(npc_item);
        return temp_pc.clothing_swap_dressed_ok();
    }

    clothing_swap_dressed_ok()
    {
        if (!this.clothes_ok(V.location, V.locationblock, false)) return false;
        if (!this.is_part_covered("foot")) return false;

        // copied from setup.ob_base_exhibitionism_requirement, since that method is hardcoded for setup.pc
        let exhibreq = 0;
        if (this.is_part_visible("crotch"))
            exhibreq = 5;
        else if (this.has_breasts() && (this.is_part_visible("breasts") || this.is_part_visible("nipples")))
            exhibreq = 4;
        else if (this.outermost_covering("crotch") == this.underwear_covering("crotch"))
            exhibreq = 3;
        else if (this.under_access() && this.underwear_covering("crotch") == null && this.owns_any_underwear())
            exhibreq = 3;
        else if (this.has_breasts() && (!this.wearing_bra() || this.outermost_covering("breasts") == this.underwear_covering("breasts")) && !this.wearing_bra_replacement())
            exhibreq = 2;
        return this.skillleveled("Exhibitionism", exhibreq);
    }

    clothing_swap_compatible_item(item, npc)
    {
        // returns tradable clothing item with same category (e.g. "tops")

        const category = new ClothingItem(item).get_current_archetype().category;
        const npc_items = npc.visible_clothing_items(this, [category]);

        for (let i = 0; i < npc_items.length; i++)
        {
            return npc_items[i];
        }
    }

