    clothing_swap_price_comparison(item, npc_item)
    {
        const price = new ClothingItem(item).get_current_archetype().price;
        if (!price || price == 0) return;
        const npc_price = new ClothingItem(npc_item).get_current_archetype().price;
        if (!npc_price || npc_price == 0) return;
        const perc = (npc_price / price - 1) * 100;
        if (perc >= 100) return "a lot more than";
        if (perc >= 50) return "more than";
        if (perc > 0) return "a little more than";
        if (perc <= -50) return "a lot less than";
        if (perc <= -25) return "less than";
        if (perc < 0) return "a little less than";
        return "about the same as";
    }

    clothing_swap_data(npc)
    {
        // returns data for the clothing swap event

        if (npc == this || !this.is_pc || npc.is_pc) return;

        let items = this.visible_clothing_items(npc, setup.ob_clothes_tradable);
        if (items.length == 0) return;
        let items_trade = [];
        let items_look = [];

        for (let i = 0; i < items.length; i++)
        {
            if (items[i].properties && items[i].properties["stains"]) continue;
            items_look.push(items[i]);
            if (this.clothing_swap_sellable(items[i]) || this.clothing_swap_tradable(items[i], npc))
            {
                items_trade.push(items[i]);
            }
        }

        // prefer items with something to do
        if (items_trade.length > 0) items = items_trade;
        else items = items_look;

        let item = setup.ob_newRNG().randomchoice(items);
        if (!item) return;
        let retval = { };
        retval.item = item;
        retval.shortname = this.clothing_shortname(item);
        if (setup.ob_isare(retval.shortname) == "is")
            retval.itemref = "it";
        else
            retval.itemref = "them";
        if (this.clothing_swap_sellable(item))
        {
            retval.price = Math.floor(new ClothingItem(item).get_current_archetype().price / 2);
        }
        if (this.clothing_swap_tradable(item, npc))
        {
            retval.npc_item = this.clothing_swap_compatible_item(item, npc);
            retval.npc_shortname = this.clothing_shortname(retval.npc_item);
            if (setup.ob_isare(retval.npc_shortname) == "is")
                retval.npc_itemref = "it";
            else
                retval.npc_itemref = "them";
            retval.tradable_outside = setup.ob_clothes_tradable_outside.includes(new ClothingItem(item).get_current_archetype().category);
            retval.price_comparison = this.clothing_swap_price_comparison(item, retval.npc_item);
        }
        return retval;
    }

