    clothing_warming_factor(i)
    {
        // warming factor (0-1) of an individual piece of clothing
        let flags = this.clothing_flags(i);
        return this.clothing_warming_factor_from_flags(flags);
    }

    clothing_warming_factor_from_flags(flags)
    {
        for (let flag of flags)
            if (setup.ob_clothes_warming_factors[flag])
                return setup.ob_clothes_warming_factors[flag];

        return 0;
    }

    warming_factor()
    {
        // returns a final all-body warming factor 0-1

        let warmobj = {};
        for (let part of this.body_parts)
        {
            warmobj[part] = [];
        }

        for (let c of this.clothes)
        {
            let slots = this.clothing_slots(c);
            let warmfactor = this.clothing_warming_factor(c);
            warmfactor = this.adjusted_warming_factor(warmfactor);
            for (let slot of slots)
                if (warmobj[slot])
                    warmobj[slot].push(warmfactor);
        }

        for (let part of new Set(this.body_parts))
            warmobj[part] = warmobj[part].length > 0 ?
                                Math.min(warmobj[part].reduce((a, b) => a + b, 0), 1) :
                                0;

        let avgwarm = Object.values(warmobj).reduce((a, b) => a + b, 0) / Object.values(warmobj).length;

        return avgwarm;
    }

    warming_degrees()
    {
        // how many degrees are added to the player's felt temperature by clothing
        return setup.ob_weather.max_warmth_from_clothing * this.warming_factor();
    }

    temperature_felt()
    {
        // returns the temperature felt by the player
        // - 21C (always comfortable) when indoors
        // - otherwise, outdoor temperature + clothing effects
        if (!V.lastloctags || !V.lastloctags.includes("outdoors") || !V.weather)
            return 21;
        else
        {
            let temp = V.weather.temperature;
            temp += this.warming_degrees();

            if (V.warmingbuff && temp < 21)
                temp = Math.min(temp + 3, 21);
            else if (V.coolingbuff && temp > 32)
                temp = Math.max(temp - 3, 32);

            return temp;
        }
    }

    temperature_state()
    {
        // returns string representing player's temperature state
        // possible results: comfortable, chilly, freezing, warm, hot (best for top level decisions)
        return setup.ob_get_temperature(this.temperature_felt());
    }

    adjusted_warming_factor(factor, outsidetemp)
    {
        // adjust clothing effect based on external temp
        // "cooler" items shouldn't really make you hotter in warm temps, it makes it a bit unmanageable
        // but they should still insulate in cold weather

        if (!outsidetemp) outsidetemp = V.weather ? V.weather.temperature : 21;

        if (factor > 0.3) return factor;

        const cutoffmin = 10;
        const cutoffmax = 27;

        if (outsidetemp <= cutoffmin) return factor;
        if (outsidetemp >= cutoffmax) return 0;

        const scale = (cutoffmax - outsidetemp) / (cutoffmax - cutoffmin);

        return factor * scale;
    }

    predicted_warming_factor(clothes)
    {
        // returns a predicted warming factor from a list of clothes (expecting outfit)

        let warmobj = {};
        for (let part of this.body_parts)
        {
            warmobj[part] = [];
        }

        for (let c of clothes)
        {
            const cinfo = setup.clothes[c.item];
            let cinstance = new ClothingItem(c);
            let slots = cinstance.get_covers();
            let warmfactor = this.clothing_warming_factor_from_flags(cinfo.flags);
            warmfactor = this.adjusted_warming_factor(warmfactor);
            for (let slot of slots)
                if (warmobj[slot])
                    warmobj[slot].push(warmfactor);
        }

        for (let part of new Set(this.body_parts))
            warmobj[part] = warmobj[part].length > 0 ?
                                Math.min(warmobj[part].reduce((a, b) => a + b, 0), 1) :
                                0;

        let avgwarm = Object.values(warmobj).reduce((a, b) => a + b, 0) / Object.values(warmobj).length;

        return avgwarm;
    }

    predicted_temperature_felt(clothes)
    {
        // returns a predicted felt temperature from a list of clothes (expecting outfit)

        if (!V.weather)
            return 21;
        else
        {
            let temp = V.weather.temperature;
            temp += this.predicted_warming_degrees(clothes);
            return temp;
        }
    }

    predicted_warming_degrees(clothes)
    {
        // returns predicted warming degrees from a list of clothes (expecting outfit)
        return setup.ob_weather.max_warmth_from_clothing * this.predicted_warming_factor(clothes);
    }

    predicted_temperature_state(clothes)
    {
        return setup.ob_get_temperature(this.predicted_temperature_felt(clothes));
    }

    collar()
    {
        return this.clothes.filter(c => setup.clothes[c.item].flags.includes("collar"))[0];
    }

