            let show_description = false;
            if (this.is_pc && V.optextrabodyhair) {show_description = true;}
            else if (!this.is_part_covered(setup.ob_cosmetics[lookup]["covered by"])){
                if (morehair) { show_description = true; }
                // add up all visible body hair so the player can take note
                hairlevel += styleinfo.shavelevel; // using this instead of body_hair_level().value to avoid doing basically the same loop multiple times
            }
            if (show_description && !bodyhairexclude.includes(hair)){
                if (styleinfo.shavelevel > 0){
                    // only mention the hairy parts that we can see
                    let decriptor = styleinfo.descriptor.replaceAll("%pp", pp);

                    let string = "";
                    string += (ppc + " " + hair + " hair is " + decriptor);

                    // try to reduce repetition by describing similar body parts with similar hair at the same time
                    let similar = [];
                    for (const hairtype in setup.ob_cosmetics[lookup]["similar"]){
                        let hair = setup.ob_cosmetics[lookup]["similar"][hairtype];
                        if (Object.keys(this.body_hair).includes(hair)){ // if the player has this body hair type...
                            let otherlookup = hair + "_hair_styles";
                            let otherstyleinfo = setup.ob_cosmetics[otherlookup][this.body_hair[hair]];
                            let diff = Math.abs(styleinfo.shavelevel - otherstyleinfo.shavelevel);
                            if (diff < 2){ // ...and the hair level is similar
                                // add it onto the description
                                bodyhairexclude.push(hair);
                                similar.push(hair);
                            }
                        }
                    }
                    if (similar.length > 0){
                        let hairs = "";
                        let plural = similar.length > 1;
                        for (const sim in similar){
                            if (sim != 0){
                                hairs += "and";
                            }
                            let s = ""
                            if (["arm", "leg", "armpit"].includes(similar[sim])){
