                        string += (", and " + pp + hairs + isorare + " similarly " + styleinfo.shortdescriptor)
                    }
                    string += (".");
                    desc.push(string);

                } else if (this.is_pc) {
                    hairless.push(hair);
                }
            }
        }
        // try to reduce repetition further by describing shaved parts in bulk
        // this is player only, for NPCs we just don't describe the hair if there's no hair
        if (V.optextrabodyhair)
        {
            if (hairless.length >= 2){
                desc.push("The rest of your body is hairless.");
            } else if (hairless.length == 1) {
                let isorare = ["arm", "leg", "armpit"].includes(hairless[0]) ? "s are" : " is";
                desc.push("Your " + hairless[0] + isorare + " hairless.");
            }
            // if the NPC is exceptionally hairy, the player takes note of it
            if (!this.is_pc && hairlevel >= (this.is_masc() ? 12 : 11)){ // masc people have body_hair.chest, so the number will almost always be higher for them
                let pssc = ps == "they" ? "They're" : ps.toUpperFirst() + "'s";
                desc.push(pssc + " pretty hairy.");
            }
        }

        desc = desc.join(" ");

        if (dmarkstr)
        {
            desc += "<br><br>" + dmarkstr;
        }

        if (makeupdesc.length > 0)
        {
            desc += "<br><br>" + makeupdesc.join(' ');
        }

        if (piercingdesc.length > 0)
        {
            desc += "<br><br>" + piercingdesc.join(' ');
        }

        if (tattoodesc.length > 0)
        {
            desc += "<br><br>" + tattoodesc.join(' ');
        }

        return desc;
    }

