    targetable_clothing(viewer = this)
    {
        // returns list of names of targetable clothes, sorted by category
        // used in encounters

        let sortbox = {};
        for (let i = 0; i < setup.ob_clothes_categories.length; i++)
        {
            sortbox[setup.ob_clothes_categories[i]] = [];
        }
        sortbox["other"] = [];

        const accessorycategories = ["accessories", "hats", "bags"];

        for (let i = 0; i < this.clothes.length; i++)
        {
            if (viewer.equals(this) || !this.is_clothing_obscured(i))
            {
                let cinfo = new ClothingItem(this.clothes[i]).get_current_archetype();
                if (!sortbox[cinfo.category])
                {
                    continue;
                    //sortbox["other"].push(this.clothing_name(i, false, true));
                }
                else
                {
                    if (!accessorycategories.includes(cinfo.category) || cinfo.flags.includes("targetable"))
                        sortbox[cinfo.category].push(this.clothing_name(i, false, true));
                }
            }
        }

        const alreadytargeted = [];
        let enc = this.encounter();
        if (enc)
        {
            for (const partner of enc.partners())
                if (partner.attempted_clothing_act && this.equals(partner.attempted_clothing_act.target))
                    alreadytargeted.push(partner.attempted_clothing_act.clothing);
        }

        const retval = [];
        for (const [cat, catclothes] of Object.entries(sortbox))
        {
            for (let i = 0; i < catclothes.length; i++)
            {
                if (!alreadytargeted.includes(catclothes[i]))
                    retval.push(catclothes[i]);
            }
        }

        return retval;
    }

    is_part_occupied(part)
    {
        // is this part currently occupied with doing something specific?
        // not as simple as checking if the part is in the occupied list, since as you might know people mostly have TWO hands

        if (part == "hair") return this.is_part_occupied("head");

        const avail = [...this.body_parts];
        const occ = [];

        let acts = this.encounter().acts;
        for (let i = 0; i < acts.length; i++)
        {
            if (this.equals(acts[i].subject))
            {
                occ.push(acts[i]["subject parts"][0]);
            }
            if (this.equals(acts[i].object))
            {
                occ.push(acts[i]["object parts"][0]);
            }
        }

        if (this.is_orifice_plugged(part)) return true;

        if (this.chastity_parts().includes(part)) return true;

        for (const part of occ)
            avail.splice(avail.indexOf(part), 1);

        return avail.indexOf(part) == -1;
    }

    is_orifice_plugged(part)
