        //      test if position is a primary
        // if multiple partners are in encounter:
        //      if this is primary partner:
        //          test if position is a primary
        //      if this is secondary partner
        //          test if position is in primary position's secondary positions

        if (position == undefined) return false;

        const enctarget = this.encounter_target();
        const primary = this.is_primary_partner() || this.equals(enctarget);

        const pinfo = setup.ob_sexpositions[position];
        if (!this.multiple_partners())
            return pinfo.primary;
        else if (primary)
            return pinfo["secondary positions"] && pinfo["secondary positions"].length > 0;
        else
        {
            let target = this.encounter_target();
            let primarypos = target.position_with(V.partner1);
            let secondarypos = setup.ob_sexpositions[primarypos]["secondary positions"] || [];
            let enc = this.encounter();
            if (enc.secondary_position_shortlist)
            {
                let intersection = secondarypos.filter(pos => enc.secondary_position_shortlist.includes(pos));
                if (intersection.length > 0) secondarypos = intersection;
            }
            return secondarypos.includes(position);
        }
    }

