            // roll the dice once, to figure out what part-part combinations will be allowed
            let rng = new RNG(inthash(this.name + "inhib"));
            const disinhibition_cutoff = rng.random() * 100;

            for (let part1 in part_part_disinhibition)
            {
                for (let part2 in part_part_disinhibition[part1])
                {
                    part_part_disinhibition[part1][part2] = [part_part_disinhibition[part1][part2], part_part_disinhibition[part1][part2] > disinhibition_cutoff];
