    add_arousal(val, max=this.max_arousal())
    {
        if (val > 0)
        {
            if (this.has_inclination("Hair Trigger"))
                val /= 0.8;
            if (this.has_inclination("Takes Patience"))
                val *= 0.8;
        }

        if (this.in_encounter() && this.is_pc)
        {
            // gradually reduce sensitivity... else we end up having continuous orgasms which is kind of cool but also kind of tedious to click through
            if (this.orgasms >= 20)
                val *= 0.01;
            else if (this.orgasms >= 15)
                val *= 0.05;
            else if (this.orgasms >= 10)
                val *= 0.1;
            else if (this.orgasms >= 5)
                val *= 0.4;
            else if (this.orgasms >= 2)
                val *= 0.6;
            else if (this.orgasms >= 1)
                val *= 0.8;
        }

        if (this.fleeting_stats["arousal"] + val > max)
            this.fleeting_stats["arousal"] = max;
        else
            this.fleeting_stats["arousal"] += val;

        if (this.is_pc) V.pcneeds["Arousal"] = this.fleeting_stats["arousal"];
    }

