    calcstyle(type = "style")
    {
        // first check for a cache... this is expensive and sometimes done repeatedly (like when looking up turnons)
        const now = Date.now();
        if (this.cached_calcstyle && now - this.cached_calcstyle[0] < 100 && this.cached_calcstyle[1] == type)
            return this.cached_calcstyle[2];

        let styles = {};

        // Do all of our "extra" style processing first since we know
        // the values will not be in the list, so we can just push them on
        // without searching.
        let extra_slutty_amt = 0;
        if (this.lacking_bra())
            extra_slutty_amt += 2;
        else if (this.bra_visible())
            extra_slutty_amt += 3;
        if (this.underwear_visible())
            extra_slutty_amt += 3;
        if (this.nipple_erectness_visible() && this.nipples_hard())
            extra_slutty_amt += 4;

        if (extra_slutty_amt > 0)
        {
            styles.slutty = extra_slutty_amt;
        }

        for (const citem of this.clothes)
        {
            let citem_style = new ClothingItem(citem).get_archetype_prop(`${type} factor`) || {};

            for (const [style, amt] of Object.entries(citem_style))
            {
                if (styles[style])
                    styles[style] += amt;
                else
                    styles[style] = amt;
            }
        }
        //console.log("Styles: ",styles);

        const hairstyle = this["hair style"];
        const hairinfo = setup.ob_hairstyles[hairstyle];

        if (hairinfo[`${type} factor`])
        {
            for (const [style, amt] of Object.entries(hairinfo[`${type} factor`]))
            {
                if (styles[style])
                    styles[style] += amt;
                else
                    styles[style] = amt;
            }
        }

        if (this.grows_beard)
        {
            let bstyle = this.beard_style || "shaved";
            let bstyleinfo = setup.ob_cosmetics.beard_styles[bstyle];
            if (`${type} factor` in bstyleinfo)
            {
                for (const [style,amt] of Object.entries(bstyleinfo[`${type} factor`]))
                {
                    if (style in styles)
                    {
                        styles[style] += amt;
                    }
                    else{
                        styles[style] = amt;
                    }
                }
            }
        }

        if (type == "style")
        {
            for (const [tatloc, tat] of Object.entries(this.tattoos))
            {
                const tatlocinfo = setup.ob_cosmetics.tattoo_locations[tatloc];
                const tatinfo = setup.ob_cosmetics.tattoos[tat];

                let anyuncovered = false;
                for (let part of tatlocinfo.part)
                    if (!this.is_part_covered(part))
                        anyuncovered = true;
                if (!anyuncovered) continue;

                if (tatinfo && tatinfo.style)
                    for (const [tatstyle, tatstyleamt] of Object.entries(tatinfo.style))
                        if (tatstyle in styles)
                        {
                            styles[tatstyle] += tatstyleamt;
                        }
                        else{
                            styles[tatstyle] = tatstyleamt;
                        }
            }
        }

        // handle character costumes during harvest eve
        if (type == "costume" && setup.ob_is_harvesteve() && this.in_character_costume())
        {
            styles["character"] = 10;
            for (let a of this.calcstyle())
                if (a[0] == "slutty")
                    styles["slutty"] = a[1];
        }

        // convert from dictionary to array
        var style_array = []
        for (const style_info of Object.entries(styles))
            style_array.push(style_info)

        style_array.sort(function(a,b) {
            return b[1]-a[1]
        });

        this.cached_calcstyle = [now, type, style_array];
        return style_array;
    }

    style_factor(style)
    {
        const styles = this.calcstyle();
        for (const styleinfo of styles)
            if (styleinfo[0] == style)
                return styleinfo[1];

        return 0;
    }

