    skill_level(skill)
    {
        // skills are stored 0-1000 so there's room for gradual progression
        // but gameplay will present them as 0-10 and that's how things unlock, so that is what we will provide

        const skills = this.is_pc ? V.pcskills : this.skills;

        if (!(skill in skills))
        {
            return 0;
        }
        else
        {
            return Math.floor(skills[skill] / 100);
        }
    }

    seed_skill(skill, amount) {
        if (!setup.ob_skills.is_valid(skill)) {
            console.error("Invalid skill: " + skill);
            return;
        }
        V.pcskills[skill] = Math.min(Math.round(+V.pcskills[skill] || 0) + amount, 1000);
    }

    raise_skill(skill, level_check, multiplier = 1, amount)
    {
        if (!setup.ob_skills.is_valid(skill))
        {
            console.error("invalid skill reference: " + skill);
            return;
        }

        const current_level = this.skill_level(skill);
        amount = amount || setup.ob_skills.default_increase[current_level] * multiplier;

        const cap = V.optdailyskillcap ? (setup.ob_skills.daily_caps[current_level] * V.optskillgainmultiplier) : 1000;
        amount = Math.min(amount * V.optskillgainmultiplier, cap);

        if (level_check >= 0)
        {
            // less learning if this is too easy or too difficult
            let overleveled = current_level - level_check;
            if (overleveled >= 3) amount /= 3;  // todo: change to 0 once higher skill content exists generally
            else if (overleveled <= -3) amount /= 4;
            else if (overleveled == 2) amount /= 2.5;
            else if (overleveled == 1 && current_level > 1) amount /= 1.5;
            else if (overleveled == -1) amount /= 2;
            else if (overleveled == -2) amount /= 3;
        }

        let capped_out_on_this_gain = false;
        if (this.is_pc) {
            if (!V.skillsraisedtoday) {
                State.setVar("$skillsraisedtoday", {});
            }
            const skillraise_sofar = V.skillsraisedtoday[skill] ?? 0;
            const allowed = Math.max(0, cap - skillraise_sofar);
            amount = Math.min(amount, allowed);

            V.skillsraisedtoday[skill] = skillraise_sofar + amount;
            capped_out_on_this_gain = amount && amount === allowed;
        }

        const skills = this.is_pc ? V.pcskills : this.skills;
        const current_valid_skill_value = +skills[skill] || 0;
        const was_learned = current_valid_skill_value === 0;

        if (!Number.isFinite(amount))
        {
            console.error(`Attempting to raise skill ${skill} by NaN amount`);
            return;
        }

        skills[skill] = Math.min(Math.round(current_valid_skill_value + amount), 1000);
        const new_level = this.skill_level(skill);

        if (this.is_pc) {
            if (was_learned) {
                setup.ob_add_catnotification("skilllearn", setup.ob_skill_label(skill));
            }
            if (new_level > current_level) {
                setup.ob_add_catnotification("skilllevel", setup.ob_skill_label(skill), ` Level ` + this.skill_level(skill));
            }
            if (capped_out_on_this_gain) {
                setup.ob_add_catnotification("skillcap", setup.ob_skill_label(skill));
            }
        }
    }

    skillcheck_rate(skill, difficulty = 3, ignoreboost = false)
    {
        if (difficulty < 0) difficulty = 0;

        let lvl;
        if (typeof skill == "string")
        {
            lvl = this.skill_level(skill);
            if (skill != "Charisma" && skill != "Dancing")
                difficulty += this.drunkenness() / 200;
            if (this.is_pc)
            {
                let boostchance = setup.ob_dormstuff_bonus('improveRollChance');

                if (this.has_inclination("Lucky")) boostchance += 0.1;
                else if (this.has_inclination("Unlucky")) boostchance -= 0.1;

                if (!ignoreboost && boostchance > 0 && State.random() < boostchance)
                    lvl++;
                else if (!ignoreboost && boostchance < 0 && State.random() < Math.abs(boostchance))
                    lvl--;

                if (skill == "Willpower")
                {
                    if (this.has_inclination("Iron Will"))
                        lvl += (Math.max(1, Math.round(lvl * 0.35)));
                    else if (this.has_inclination("Easily Pressured"))
                        lvl -= (Math.max(1, Math.round(lvl * 0.35)));
                }
            }
        }
        else
        {
            lvl = skill;
        }

        let diff = Math.floor(difficulty - lvl);
        if (diff == 0)
        {
            return 0.55;
        }
        else if (diff > 0)
        {
            // difficulty > skill level
            if (diff == 1)
            {
                return 0.45;
            }
            else if (diff == 2)
            {
                return 0.375;
            }
            else if (diff == 3)
            {
                return 0.3;
            }
            else if (diff == 4)
            {
                return 0.2;
            }
            else if (diff == 5)
            {
                return 0.1;
            }
            else
            {
                return 0;
            }
        }
        else
        {
            // difficulty < skill level
            if (diff == -1)
            {
                return 0.65;
            }
            else if (diff == -2)
            {
                return 0.8;
            }
            else if (diff == -3)
            {
                return 0.95;
            }
            else
            {
                return 1.0;
            }
        }
    }

    skillcheck_descriptor(difficulty) {
        const difficulty_to_descriptor = [
            [1.0, "certain"],
            [0.95, "trivial"],
            [0.7, "easy"],
            [0.6, "moderate"],
            [0.5, "demanding"],
            [0.4, "hard"],
            [0.2, "very hard"],
            [0.0, "nearly impossible"],
        ];

        for (let [cutoff, label] of difficulty_to_descriptor) {
            if (difficulty >= cutoff) return label;
        }
        return "impossible";
    }


    skillcheck(skill, difficulty = 3, raiseskillonsuccess = false)
    {
        if (V.nextrolldifficultymod && typeof difficulty == "number")
        {
            difficulty += V.nextrolldifficultymod;
            delete V.nextrolldifficultymod;
        }

        let rate = this.skillcheck_rate(skill, difficulty);
        let roll = State.random();
        let success = rate >= roll;

        if (this.is_pc && rate <= 0.2 && success)
        {
            if (!V.luckyrolls) V.luckyrolls = 1;
            else V.luckyrolls++;

            if (V.luckyrolls >= 6)
                setup.inclinations.unlock_with_req("Lucky");

            if (skill == "Willpower")
                setup.inclinations.unlock_with_req("Iron Will");
        }
        else if (this.is_pc && rate >= 0.8 && !success)
        {
            if (!V.unluckyrolls) V.unluckyrolls = 1;
            else V.unluckyrolls++;

            if (V.unluckyrolls >= 6)
                setup.inclinations.unlock_with_req("Unlucky");

            if (skill == "Willpower")
                setup.inclinations.unlock_with_req("Easily Pressured");
        }

        //console.log("Skillcheck pass chance: " + parseInt(rate * 100) + "% Roll: " + (100 - parseInt(roll * 100)) + "/" + (100 - parseInt(rate * 100)) + " (" + (success ? "success" : "fail") + ")");
        if (raiseskillonsuccess && success && this.is_pc && typeof skill == "string") this.raise_skill(skill, difficulty);
        return success;
    }

