            diff += V.pchorny;
            if (doer != null && setup.people.has_inclination(doer, "Dominant Vibe")) diff += 1;
            if (doer != null && setup.people.has_inclination(doer, "Hard to Resist")) diff += 1;
            if (this.has_inclination("Hair Trigger")) diff += 1;
            if (this.fleeting_stats.arousal >= 1000) diff += 1;
            if (V.crush && doer && setup.people.get_name(doer) == V.crush) diff += 3;
            return diff;
