    resist_exhibitionism_difficulty(doer = null, part = "crotch", level = "naked")
    {
        // base chance to resist showing yourself off, mostly based on predilection to exhibitionism
        // usually checked against willpower

        if (doer == undefined) doer = null;

        const crotch = ["crotch", "vagina", "penis", "butt"];

        let baselvl = 0;
        if (crotch.includes(part))
            if (level == "naked")
                baselvl = 5;
            else
                baselvl = 3;
        else if (part == "breasts")
            if (level == "naked")
                baselvl = 4;
            else
                baselvl = 2;

        let diff = this.skill_level("Exhibitionism") - baselvl;
        if (level == "underwear" && !this.has_inclination("Cautious Exhibitionist")) diff -= 1;
        if (level == "naked" && !this.has_inclination("Proud Exhibitionist")) diff -= 1;
        if (this.has_any_inclination(["Lewd Exhibitionist", "Submissive"])) diff += 1;
        if (this.has_inclination("Helpless Exhibitionist")) diff += 2;
        if (doer != null && setup.people.has_inclination(doer, "Dominant Vibe")) diff += 1;
        if (V.crush && doer && setup.people.get_name(doer) == V.crush) diff += 1;

        let adiff = Math.floor((this.fleeting_stats.arousal / 100) / 3);

        if (this.has_any_inclination(setup.ob_archetypes.inclination_sets.exhibitionist))
        {
            diff += adiff;
            if (this.is_pc)
            {
                diff += V.pchorny;
            }
        }

        return diff;
    }

