    inclinations_opposing(inc)
    {
        // what inclinations do we have that oppose the given inclination?
        const myincs = this.is_pc ? V.pcinclinations : setup.people.inclinations(this);
        const incinfo = setup.inclinations[inc];
        if (!incinfo.requires || !incinfo.requires.noinclinations) return [];
        const retval = [];
        for (let myinc of myincs)
            if (incinfo.requires.noinclinations.includes(myinc))
                retval.push(myinc);
        return retval;
    }

    inclination_prereqs(inc)
    {
        // what inclinations do we have that are prereqs of the given inclination?
        const myincs = this.is_pc ? V.pcinclinations : setup.people.inclinations(this);
        const incinfo = setup.inclinations[inc];
        if (!incinfo.requires || !incinfo.requires.inclinations) return [];
        const retval = [];
        for (let myinc of myincs)
            if (incinfo.requires.inclinations.includes(myinc))
                retval.push(myinc);
        return retval;
    }

    supporting_inclinations(inc)
    {
        // which inclinations do we have that have the given inclination for a prereq?
        const myincs = this.is_pc ? V.pcinclinations : setup.people.inclinations(this);
        const supporting = setup.people.supporting_inclinations(inc);
        const retval = [];
        for (let myinc of myincs)
            if (supporting.includes(myinc))
                retval.push(myinc);
        return retval;
    }


