            let lookup = hair + "_hair_styles";
            total += setup.ob_cosmetics[lookup][this.body_hair[hair]].shavelevel;
            count++;
        }

        const hairs = ["pretty smooth", "kinda smooth", "a bit hairy", "pretty hairy", "pretty damn hairy"];
        return { "descriptor": total == 0 ? "completely smooth" : hairs[Math.floor(Math.min(4, total/count))], "value": total };
