    bulk_shave(desired_shave_level = 0)
    {
        if (!V.lastbodyhairstyles){
            let day = V.gameday;
            State.setVar("$lastbodyhairstyles",
            {
                "butt": day,
                "armpit": day,
                "tummy": day,
                "leg": day,
                "arm": day,
            });
        }
        // body hair
        let newbodyhairstyle = V.lastbodyhairstyles;
        for (const hair of Object.keys(this.body_hair)){
            let lookup = hair + "_hair_styles";
            let current = setup.ob_cosmetics[lookup][this.body_hair[hair]];
            if (desired_shave_level < current.shavelevel) {
                for (const style of Object.keys(setup.ob_cosmetics[lookup])){
                    if (setup.ob_cosmetics[lookup][style].shavelevel == desired_shave_level){
                        this.body_hair[hair] = style;
                        newbodyhairstyle[hair] = V.gameday;
                        break;
                    }
                }
            }
        }
        // pubes
        let pubes = setup.ob_cosmetics.pubic_styles[this.pubic_style];
        if (desired_shave_level < pubes.shavelevel) {
            for (const style of Object.keys(setup.ob_cosmetics.pubic_styles)){
