                    this.pubic_style = style == "smooth" ? "shaved" : style;
                    State.setVar("$lastpubicstyle",  V.gameday);
                    break;
                }
            }
        }
        State.setVar("$lastbodyhairstyles", newbodyhairstyle);
    }

