    get_dress_codes(location = V.lastlocpassage)
    {
        try
        {
            if (!location) return [];
            const passage = Story.get(location);
            const loctags = passage ? Story.get(location).tags : [];
            return loctags.filter((tag) => tag.substring(0, 2) == "dc");
        }
        catch (error)
        {
            return [];
        }
    }

    clothes_ok(location = V.lastlocpassage, locblock = V.locationblock, check_exh = true, streaking_allowed = true)
    {
        return typeof this.get_error_clothes(location, locblock, check_exh, streaking_allowed) !== "string";
    }

    get_error_clothes(location = V.lastlocpassage, locblock = V.locationblock, check_exh = true, streaking_allowed = true)
    {
        const dress_codes = this.get_dress_codes(location);

        let error = this.get_error_dress_code(dress_codes, location, streaking_allowed);
        if (error) return error;

        error = this.get_error_anonymous(dress_codes, location);
        if (error) return error;

        if (check_exh)
        {
            error = this.get_error_exhibitionism(location, locblock);
            if (error) return error;
        }

        return null;
    }

    get_error_dress_code(dress_codes, location = V.lastlocpassage, streaking_allowed = true)
    {
        const streaking = V.exhibitionsneak && streaking_allowed;

        // is there an exception to the general dress code?
        if (dress_codes.includes("dcExcStreaking"))
        {
            if (setup.ob_free_exhibitionism_allowed() && streaking_allowed)
                return null;
        }

        if (dress_codes.includes("dcExcRiverRat"))
        {
            if (V.jobs.includes("River Rat") && setup.ob_riverrat_dresscode())
                return null;
        }

        if (dress_codes.includes("dcExcHarvestEve"))
        {
            if (setup.ob_is_harvesteve_party_time() && (this.fully_dressed() || this.inoffensive_topless()))
                return null;
        }

        if (dress_codes.includes("dcExcSpringrilSplash"))
        {
            if (setup.ob_is_springrilsplash() && this.wearing_swimwear())
                return null;
        }

        // locations with special error messages
        if (location == "MainHall")
        {
            if (!V.pc.is_part_covered("crotch"))
            {
                const bit = V.pc.has_part("vagina") ? setup.ob_get_bits_option(setup.ob_pcgender(), "vagina") : setup.ob_get_bits_option(setup.ob_pcgender(), "penis");
                let retval = "You're not about to go linger in the hall with your " + bit + " out.";
                if (V.pc.has_any_inclination(setup.ob_archetypes.inclination_sets.basic_exhibitionist) && setup.ob_time.timeofday() != "night")
                    retval += " <<highlight sexy>>Not in the daylight, anyway...<</highlight>>";
                return retval;
            }
            if (V.pc.has_breasts() && !V.pc.is_part_covered("breasts") && !V.pc.inoffensive_topless(true))
            {
                let retval = "You're not about to go linger in the hall with your tits out.";
                if (V.pc.has_any_inclination(setup.ob_archetypes.inclination_sets.basic_exhibitionist) && setup.ob_time.timeofday() != "night")
                    retval += " <<highlight sexy>>Not in the daylight, anyway...<</highlight>>";
                return retval;
            }
        }

        // check dress codes
        if (dress_codes.includes("dcDorm"))
        {
            const allcovered = V.pc.is_part_covered("crotch") && (!V.pc.has_breasts() || V.pc.is_part_covered("breasts"));
            if (!allcovered && !this.fully_dressed(true) && !this.inoffensive_topless(true) && !streaking)
                return this.not_fully_dressed_reason();
        }

        if (dress_codes.includes("dcCampusOutside") || dress_codes.includes("dcCampusWorkout"))
        {
            // check shoes separately to prevent misleading error messages
            if (!this.fully_dressed(true) && !this.inoffensive_topless(true) && !streaking)
                return this.not_fully_dressed_reason();
            else if (!this.wearing_shoes() && !streaking)
                return "You're not wearing shoes.";
        }

        if (dress_codes.includes("dcCampusInside"))
        {
            if (!this.fully_dressed() && !streaking)
                return this.not_fully_dressed_reason();
        }

        if (dress_codes.includes("dcPool"))
        {
            if (!this.wearing_swimwear() && !V.breakingin)
                return "You need to be dressed in just swimwear (with all your bits covered). Gym rules!";
        }

        if (dress_codes.includes("dcTown"))
        {
            if (!this.fully_dressed())
                return this.not_fully_dressed_reason();
        }

        return null;
    }


    get_error_anonymous(dress_codes, location = V.lastlocpassage)
    {
        if (!this.is_anonymous()) return null;

        // is there an exception where a mask is ok?
        if (setup.ob_is_homebase() && V.lastlocpassage == location)
        {
            return null;
        }

        if (dress_codes.includesAny(["dcCampusOutside", "dcDorm"]))
        {
            return null;
        }

        if (dress_codes.includes("dcExcSport"))
        {
            if (setup.ob_anonymous_allowed_for_sport())
                return null;
        }

        if (dress_codes.includes("dcExcHarvestEve"))
        {
            if (setup.ob_is_near_harvesteve_party_time())
                return null;
        }

        // no => return error
        if (["MainHall", "HouseAXAMainRoom", "HouseDDRMainRoom", "HouseSOTMainRoom", "HouseZKXMainRoom"].includes(location))
            return "Somebody's probably going to think you're up to something <i>really</i> serious if you're wandering around with a mask that completely obscures your face.";
        else if (location == "BusInterior")
            return "It seems you're not allowed on the bus with a full face-obscuring mask on. Guess it makes people nervous, for some reason!";
        else if (dress_codes.includes("dcCampusInside") || dress_codes.includes("dcCampusWorkout"))
            return 'A sign outside says, "No full face-obscuring masks." Lame.';
        else
            return "Wearing a mask here may get you into trouble.";
    }

    get_error_exhibitionism(location = V.lastlocpassage, locblock = V.locationblock)
    {
        let exh = setup.ob_base_exhibitionism_requirement(location, locblock);

        if (this.skillleveled("Exhibitionism", exh))
            return null;

        // locations with special error messages
        if (location == "MainHall")
        {
            return "You're not about to go linger in the hall this undressed. (Need <<hovertip setup.ob_skill_hovertip('Exhibitionism')>><span class='mainskill skillcheck'><<skilllabel Exhibitionism " + exh + ">></span><</hovertip>> <span class='skillcheck small'><<= " + exh + ">></span>)";
        }

        return "(Need <<hovertip setup.ob_skill_hovertip('Exhibitionism')>><span class='mainskill skillcheck'><<skilllabel Exhibitionism " + exh + ">></span><</hovertip>> <span class='skillcheck small'><<= " + exh + ">></span>)";
    }

