                if ("horny" in event && event.horny == 1 && V.pchorny == 2)
                    event.frequency = Math.floor(event.frequency * 1.5);

                if ("days overdue" in event)
                {
                    let overdue = -1;
                    if (setup.ob_events.last_event_day(event.passage) > 0)
                    {
                        overdue = setup.ob_events.days_since_event(event.passage) - event["days overdue"];
                    }
                    else if (event["from day"])
                    {
                        overdue = (V.gameday - event["from day"]) - event["days overdue"];
                    }
                    else
                    {
                        overdue = V.gameday - event["days overdue"];
                    }

                    if (overdue > 0)
                        event.frequency = Math.floor(event.frequency * (1.25 ** overdue));
                }

                if (event.sport && sport && event.sport == sport.playing)
                {
                    event.frequency = Math.floor(event.frequency * 2);
                }

                if (V.kinkcontentboost && V.kinkcontentboost.includes(event.kink))
                {
                    event.frequency = Math.floor(event.frequency * 2);
                }

                if (this_npc1) { npcforevent[event.passage] = this_npc1; event.eventnpc = this_npc1; }
                if (this_npc2) { npc2forevent[event.passage] = this_npc2; event.eventnpc2 = this_npc2; }
                if (this_npc3) { npc3forevent[event.passage] = this_npc3; event.eventnpc3 = this_npc3; }
                if (this_npc4) { npc4forevent[event.passage] = this_npc4; event.eventnpc4 = this_npc4; }
                if (this_eventsim) { simeventforevent[event.passage] = this_eventsim; event.eventsim = this_eventsim; }

                set.push(event);
            }
        }
        catch (error)
        {
            console.error("Malformed event: " + this.db[i].passage);
            console.error(error);
        }
        if (profileevents) eventtimes.push([this.db[i].passage, performance.now() - start]);
    }

    if (Object.keys(npcforevent).length > 0)
        State.setVar("$npcforevent", npcforevent);
    if (Object.keys(npc2forevent).length > 0)
        State.setVar("$npc2forevent", npc2forevent);
    if (Object.keys(npc3forevent).length > 0)
        State.setVar("$npc3forevent", npc3forevent);
    if (Object.keys(npc4forevent).length > 0)
        State.setVar("$npc4forevent", npc4forevent);
    if (Object.keys(simeventforevent).length > 0)
        State.setVar("$simeventforevent", simeventforevent);

    if (profileevents)
    {
        eventtimes.sort((a, b) => {
            return b[1] - a[1]
        });
        console.log(eventtimes);
    }

    if (hangout && !hangout.secondpass && set.length == 0)
    {
        hangout.secondpass = true;
        return this.assemble_set(tags);
    }
    else if (hangout) delete hangout.secondpass;

    return set;
}

setup.ob_events.choose_from_set = function(set)
{
    // pick one event from a given array of events using relative frequency (aka weighting)
    const relfreq = [];
    for (let i = 0; i < set.length; i++)
    {
        relfreq.push(set[i]);
        relfreq.push(set[i].frequency);
    }
    //console.log(relfreq);
    if (relfreq.length == 0) return null;
    else return setup.ob_randomrelfreq(relfreq);
}

setup.ob_events.pick = function()
{
    // pick an event out of the database given a list of tags
    // returns event object (esp. useful if you need event metadata)
    const set = this.assemble_set(...arguments);
    let pick = this.choose_from_set(set);
    if (pick == null)
    {
        delete State.variables.npcforevent;
        delete State.variables.npc2forevent;
        delete State.variables.npc3forevent;
        delete State.variables.npc4forevent;
        delete State.variables.simeventforevent;
        return null;
    }
    else
    {
        let npcforevent = V.npcforevent;
        if (npcforevent && npcforevent[pick.passage])
            State.setVar("$eventnpc", npcforevent[pick.passage]);
        delete State.variables.npcforevent;

        let npc2forevent = V.npc2forevent;
        if (npc2forevent && npc2forevent[pick.passage])
            State.setVar("$eventnpc2", npc2forevent[pick.passage]);
        delete State.variables.npc2forevent;

        let npc3forevent = V.npc3forevent;
        if (npc3forevent && npc3forevent[pick.passage])
            State.setVar("$eventnpc3", npc3forevent[pick.passage]);
        delete State.variables.npc3forevent;

        let npc4forevent = V.npc4forevent;
        if (npc4forevent && npc4forevent[pick.passage])
            State.setVar("$eventnpc4", npc4forevent[pick.passage]);
        delete State.variables.npc4forevent;

        let simeventforevent = V.simeventforevent;
        if (simeventforevent && simeventforevent[pick.passage])
            State.setVar("$eventsim", simeventforevent[pick.passage]);
        delete State.variables.simeventforevent;

        if (V.eventsim)
            setup.ob_nPCSimulation.process_surfaced_event(V.eventsim);

        return pick;
    }
}

setup.ob_events.passage = function()
{
    // top-level method to pick an event out of the database given a list of tags and return its passage
    let pick = this.pick(...arguments);
    return pick ? pick.passage : null;
}

setup.ob_events.register_event = function(event, day = V.gameday)
{
    // registers an event that happened on a particular game day

    let memory = V.eventmemory;
    memory[event] = day;
    let recent = V.eventrecent || [];
    recent.push(event);
    if (recent.length > 3) recent.splice(0, 1);
    State.setVar("$eventrecent", recent);
    let sneak = V.exhibitionsneak;
    if (sneak && !sneak.events.includes(event))
    {
        sneak.events.push(event);
    }
}

setup.ob_events.is_recent = function(event)
{
    let recent = V.eventrecent || [];
    return recent.includes(event);
}

setup.ob_events.last_event_day = function(event)
{
    let memory = V.eventmemory;
    if (event in memory)
        return memory[event];
    else
        return -100;
}

setup.ob_events.days_since_event = function(event)
{
    return V.gameday - this.last_event_day(event);
}

setup.ob_events.base_event_chance = function(otherfactors = true)
{
    // the base chance for ~something~ to happen when otherwise minding your own business
    // perhaps one day relate to how provocative the player looks or something

    if (V.exhibitionsneak && otherfactors) return 1.0;

    if (V.nextbaseeventchance)
    {
        let amt = V.nextbaseeventchance;
        delete State.variables.nextbaseeventchance;
        return amt;
    }

    let base = 1.0/6.0;
    if (setup.ob_equipped_wearable_toys().length > 0)
        base *= 2.0;
    else if (V.pchorny == 2)
        base *= 1.33;
    else if (V.pchorny == 1)
        base *= 1.15;

    return base;
}

