setup.ob_events.pick_several = function(config, count, people = V.peopleatlocation, job = setup.job_at_location())
{
    // call pick_person several times to end up with multiple unique people
    // will attempt to guarantee the given number but will abort after too many failed picks
    const picklist = [...people];
    const retval = [];
    let tries = 0;
    while (retval.length < count && picklist.length > 0 && tries < 30)
    {
        let pick = this.pick_person(config, picklist.length > 20 ? setup.ob_shuffle(picklist).slice(0, 20) : picklist, job);
        if (!retval.includes(pick) && pick != null)
        {
            retval.push(pick);
            picklist.splice(picklist.indexOf(pick), 1);
        }
        else
        {
            tries++;
        }
    }
    return retval;
}

