setup.ob_events.register_voyeurism = function(npc, event)
{
    if (!("voyeurmemory" in State.variables)) State.setVar("$voyeurmemory", []);

    let events = V.voyeurmemory;
    let eventid = -1;
    let newid = -1;

    if (!Array.isArray(event.parts)) event.parts = [event.parts];

    for (let i = 0; i < events.length; i++)
    {
        let sameparts = events[i].parts.every(value => event.parts.includes(value))
            && event.parts.every(value => events[i].parts.includes(value));

        if (sameparts
                && events[i].act == event.act
                && events[i].type == event.type
                && events[i].subtype == event.subtype
                && events[i].consensual == event.consensual)
        {
            eventid = events[i].id;
            break;
        }
        else if (events[i].id >= newid)
            newid = events[i].id;
    }

    if (eventid == -1)
    {
        event.id = newid + 1;
        eventid = event.id;
        events.push(event);
    }
    else
    {
        event = events[eventid];
    }

    npc = setup.people.get_name(npc);
    if (!event.npcs) event.npcs = [];
    if (!event.npcs.includes(npc)) event.npcs.push(npc);
    events[eventid] = event;

    return eventid;
}

setup.ob_events.register_witnessing = function(event, witnesses)
{
    if (!("witnessedevents" in State.variables)) State.setVar("$witnessedevents", []);

    let events = V.witnessedevents;
    let eventid = -1;
    let newid = -1;

    if (!Array.isArray(event.parts)) event.parts = [event.parts];

    for (let i = 0; i < events.length; i++)
    {
        let sameparts = events[i].parts.every(value => event.parts.includes(value))
            && event.parts.every(value => events[i].parts.includes(value));

        if (sameparts
                && events[i].act == event.act
                && events[i].type == event.type
                && events[i].subtype == event.subtype
                && events[i].consensual == event.consensual)
        {
            eventid = events[i].id;
            break;
        }
        else if (events[i].id >= newid)
            newid = events[i].id;
    }

    if (eventid == -1)
    {
