setup.ob_debug.kd_handler = function(event)
{
    const tag = event.target.tagName;
    if (tag === "INPUT" || tag === "TEXTAREA" || event.target.isContentEditable)
    {
        return;
    }

    //console.log("Keydown!",event);
    if (event.code ==="KeyD")
    {
        let linksFound = false;
        for (const [k,v] of Object.entries(document.styleSheets))
        {
            for (const [rk,rv] of Object.entries(v.cssRules))
            {
                if (typeof(rv.selectorText) == 'string' && rv.selectorText.indexOf("debug-hidden") >= 0)
                {
                    linksFound = true;
                    let post_string = rv.selectorText.substring(14);
                    let current_display = rv.style.getPropertyValue("display");
                    //console.log(k,rk,rv.selectorText,"Display: "+current_display,post_string, rv)
                    if (current_display == "none")
                    {
                        let new_display = "block";
                        if (post_string.length > 0)
                        {
                            new_display = post_string;
                        }
                        rv.style.setProperty("display",new_display)
                    }
                    else
                    {
                        rv.style.setProperty("display","none")
                    }
                }
            }
        }
        if (linksFound) Links.generate();
    }
}

