setup.ob_randomrelfreq = function(array) {
    // accepts a strided array in form [thing, 20, thing, 80]
    // in order to make one thing 20% likely and the other 80% likely
    // or however you want to weight it, hence relative frequency
    // then returns the winning element

    let randomized = [...array];
    let sumsofar = 0;
    for (let i = 0; i < randomized.length; i += 2)
    {
		let factor = randomized[i + 1];
        if (factor == 0) continue;
		factor = factor == 0 ? 1 : factor;
        sumsofar += factor;
        randomized[i + 1] = sumsofar;
    }

    let roll = this.rir(0, sumsofar, true);

    for (let i = 0; i < randomized.length; i += 2)
    {
        if (roll <= randomized[i + 1])
        {
            return randomized[i];
        }
    }

    return randomized[0];
}

setup.ob_maxrelfreq = function(array) {
    // accepts a strided array in form [thing, 20, thing, 80]
    // in order to make one thing 20% likely and the other 80% likely
    // or however you want to weight it, hence relative frequency
    // however, this just returns the highest frequency element, which is occasionally useful

    let randomized = [...array];
    let pick;
    let max = -1;

    for (let i = 0; i < randomized.length; i += 2)
    {
        let factor = randomized[i + 1];
        if (max == -1 || factor > max)
        {
            pick = randomized[i];
            max = factor;
        }
    }

    return pick;
}

setup.ob_randomrelfreqasproperty = function(array) {
    // accepts a strided array in form [thing, 20, thing, 80]
    // in order to make one thing 20% likely and the other 80% likely
    // or however you want to weight it, hence relative frequency
    // then returns the winning element

    let randomized = [];
    for (let item of array)
        randomized.push(item, item.frequency);

    let sumsofar = 0;
    for (let i = 0; i < randomized.length; i += 2)
    {
