}

setup.ob_shuffle = function(array)
{
    let currentIndex = array.length,  randomIndex;

    // While there remain elements to shuffle.
    while (currentIndex != 0) {

        // Pick a remaining element.
        randomIndex = Math.floor(State.random() * currentIndex);
        currentIndex--;

        // And swap it with the current element.
        [array[currentIndex], array[randomIndex]] = [
        array[randomIndex], array[currentIndex]];
    }

    return array;
}

const inthash = str => {
    let arr = str.split('');
    return Math.abs(arr.reduce(
        (hashCode, currentVal) =>
        (hashCode = currentVal.charCodeAt(0) + (hashCode << 6) + (hashCode << 16) - hashCode),
        0
    ));
};
setup.ob_inthash = inthash;

class RNG {
    constructor(seed) {
        // LCG using GCC's constants
        this.m = 0x80000000; // 2**31;
        this.a = 1103515245;
        this.c = 12345;

        this.state = seed ? seed : Math.floor(State.random() * (this.m - 1));
        this.seed = this.state;
    }
    randomint() {
        this.state = (this.a * this.state + this.c) % this.m;
        return this.state;
    }
    random() {
        // returns in range [0,1]
        return this.randomint() / (this.m - 1);
    }
    lastrandom()
    {
        // returns the last found range [0,1]
        return this.state / (this.m - 1);
    }
    rir(start, end, inclusive = false) {
        // returns in range [start, end): including start, excluding end
        // can't modulu nextInt because of weak randomness in lower bits
        var rangeSize = end - start + (inclusive ? 1 : 0);
        var randomUnder1 = this.randomint() / this.m;
        return start + Math.floor(randomUnder1 * rangeSize);
    }
    randomchoice(array) {
        return array[this.rir(0, array.length)];
    }
    randomrelfreq(array) {
        // accepts a strided array in form [thing, 20, thing, 80]
        // in order to make one thing 20% likely and the other 80% likely
        // or however you want to weight it, hence relative frequency
        // then returns the winning element
        let randomized = [...array];

        let sumsofar = 0;
        for (let i = 0; i < randomized.length; i += 2)
        {
            sumsofar += randomized[i + 1];
            randomized[i + 1] = sumsofar;
        }

        let roll = this.rir(0, sumsofar, true);

        for (let i = 0; i < randomized.length; i += 2)
        {
            if (roll <= randomized[i + 1])
            {
                return randomized[i];
            }
        }

        return randomized[0];
    }
    shuffle(array) {
        let currentIndex = array.length,  randomIndex;

        // While there remain elements to shuffle.
        while (currentIndex != 0) {

          // Pick a remaining element.
          randomIndex = Math.floor(this.random() * currentIndex);
          currentIndex--;

          // And swap it with the current element.
          [array[currentIndex], array[randomIndex]] = [
            array[randomIndex], array[currentIndex]];
        }

        return array;
    }
    random_bm(mean = 0.5, stddev = 0.1, resample = true)
    {
        let u = 0, v = 0;
        while(u === 0) u = this.random();
        while(v === 0) v = this.random();
        let num = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
        num = num * stddev + mean;
        if (resample && (num > 1 || num < 0)) return this.random_bm(mean, stddev); // resample if out of bounds
        return num;
    }
    rir_bm(start, end, inclusive = false, mean = 0.5, stddev = 0.1, resample = true, clampstart = null, clampend = null)
    {
            // returns in range [start, end): including start, excluding end
            let rangeSize = end - start + (inclusive ? 1 : 0);
            let diff = rangeSize * this.random_bm(mean, stddev, resample);
            let value = start + Math.floor(diff);

            if (clampstart != null) value = Math.max(clampstart, value);
            if (clampend != null) value = Math.min(clampend, value);

            return value;
    }
}
