setup.ob_and = function(stuff, nothing = "nothing", and = "and", sep = ", ")
{
    stuff = stuff.map(item => typeof item == "string" && item.indexOf("pair of ") == 0 ? item.substring(8) : item);
    let retval = "";
    if (stuff.length == 0)
    {
        retval = nothing;
    }
    else if (stuff.length == 1)
    {
        retval = stuff[0];
    }
    else if (stuff.length == 2)
    {
        retval = stuff[0] + " " + and + " " + stuff[1];
    }
    else
    {
        for (let i  = 0; i < stuff.length - 1; i++)
        {
            retval += stuff[i] + sep;
        }
        retval += and + " " + stuff[stuff.length - 1];
    }
    return retval.replace(" ,", ",").replace("  ", " ");
}

setup.ob_arrRemove = function(arr, value)
{
    for( var i = 0; i < arr.length; i++)
    {
        if ( arr[i] === value) {

            arr.splice(i, 1);
            return arr;
        }
    }
    return arr;
}

const upToTwenty = ['', "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten","eleven",
                    "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];

const tens = ['', "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

const thousands = ['', 'thousand', 'million', 'billion'];

setup.english_number = function(num)
{
  // convert the input number to a string
  // if the number is bigger than 12 places
    // return 0 it would be too big
  if (num.toString().length > 12) return 'very numerous';

  if (num === 0) {
    return 'zero';
  }
  else if (num < 0)
  {
	return 'negative ' + this.english_number(Math.abs(num));
  }

  let counter = 0;
  // crete a results string ''
  let res = '';
  // We have strings representations

  // while the number is > 0
  while (num > 0) {
    // the number is % 1000 not 0
      // set out results sting equal to helper(current Num%1000) + counter a res
    if (num % 1000 !== 0) {
      res = `${getNums(num%1000)} ${thousands[counter]} ${res}`;
    }
      // num = num/1000
  // counter++
    num = Math.floor(num / 1000);
    counter++;
  }

  res = res.trim();
  if (res.substring(res.length - 5) == "-zero") res = res.substring(0, res.length - 5);
  if (res.substring(res.length - 5) == " zero") res = res.substring(0, res.length - 5);
  if (res.substring(res.length - 1) == "-") res = res.substring(0, res.length - 1);
  return res;
}

const getNums = number =>
{
  if (number === 0) {
    return 'zero';
  }
  else if (number < 20) {
    return upToTwenty[number];
  }
  else if (number < 100) {
    return `${tens[Math.floor(number/10)]}-${getNums(number % 10)}`;
  }
  else {
    return `${upToTwenty[Math.floor(number/100)]} hundred ${getNums(number%100)}`;
  }
}

setup.ob_rbg_from_string = function(name)
{
    let hash = inthash(name).toString();

    while (hash.length < 9)
        hash += " ";

    let r = parseInt(hash.substring(0, 3));
    let g = parseInt(hash.substring(3, 6));
    let b = parseInt(hash.substring(6, 9));

    r = Math.trunc(128 + (128 * (r / 999)));
    g = Math.trunc(128 + (128 * (g / 999)));
    b = Math.trunc(128 + (128 * (b / 999)));

    return "rgb(" + r + ", " + g + ", " + b + ")";
}

setup.pluralize = function(word, amount = 2) {
    if (amount !== undefined && amount === 1) {
        return word
    }
    const plural = {
        '(quiz)$'               : "$1zes",
        '^(ox)$'                : "$1en",
        '([m|l])ouse$'          : "$1ice",
        '(matr|vert|ind)ix|ex$' : "$1ices",
        '(x|ch|ss|sh)$'         : "$1es",
        '([^aeiouy]|qu)y$'      : "$1ies",
        '(hive)$'               : "$1s",
        '(?:([^f])fe|([lr])f)$' : "$1$2ves",
        '(shea|lea|loa|thie)f$' : "$1ves",
        'sis$'                  : "ses",
        '([ti])um$'             : "$1a",
        '(tomat|potat|ech|her|vet)o$': "$1oes",
        '(bu)s$'                : "$1ses",
        '(alias)$'              : "$1es",
        '(octop)us$'            : "$1i",
        '(ax|test)is$'          : "$1es",
        '(us)$'                 : "$1es",
        '([^s]+)$'              : "$1s"
    }
    const irregular = {
        'move'   : 'moves',
        'foot'   : 'feet',
        'goose'  : 'geese',
        'sex'    : 'sexes',
        'child'  : 'children',
        'man'    : 'men',
        'tooth'  : 'teeth',
        'person' : 'people'
    }
    const uncountable = [
        'sheep',
        'fish',
        'deer',
        'moose',
        'series',
        'species',
        'money',
        'rice',
        'information',
        'equipment',
        'bison',
        'cod',
        'offspring',
        'pike',
        'salmon',
        'shrimp',
        'swine',
        'trout',
        'aircraft',
        'hovercraft',
        'spacecraft',
        'sugar',
        'tuna',
        'you',
        'wood',
        'lettuce',
        'basil',
        'parsley',
    ]
    // save some time in the case that singular and plural are the same
    if (uncountable.indexOf(word.toLowerCase()) >= 0) {
        return word
    }
    // check for irregular forms
    for (const w in irregular) {
        const pattern = new RegExp(`${w}$`, 'i')
        const replace = irregular[w]
        if (pattern.test(word)) {
            return word.replace(pattern, replace)
        }
    }
    // check for matches using regular expressions
    for (const reg in plural) {
        const pattern = new RegExp(reg, 'i')
        if (pattern.test(word)) {
            return word.replace(pattern, plural[reg])
        }
    }
    return word
}

