setup.ob_parse_adjnoun_lists = function(stuff)
{
    // take something like ["long hair", "red hair"] and return ["long and red hair"]
    let dict = {};
    for (let item of stuff)
    {
        let words = item.split(' ');
        let noun = words.pop();
        let adj = words.join(' ');
        if (adj != '')
        {
            if (dict[noun])
                dict[noun].push(adj);
            else
                dict[noun] = [adj];
        }
        else if (!dict[noun])
            dict[noun] = [];
    }
    const retval = [];
    for (const [noun, adjs] of Object.entries(dict))
    {
        let newword = setup.ob_and(adjs, "", "") + ' ' + noun;
        retval.push(newword.trim());
    }
    return retval;
}

