setup.ob_validate_colors = function(check_objs = [setup.clothes,setup.ob_food,setup.ob_dormstuff,setup.sextoys,setup.ob_cosmetics.makeup,setup.ob_cosmetics.piercings,setup.ob_outfits])
{
    let invalid_colors = {};
    // check for 'legal' colors.
    for (const check_obj of check_objs)
    {
        for (const [item,properties] of Object.entries(check_obj))
        {
            //console.log(item,properties);
            for (const [field,field_vals] of Object.entries(properties))
            {
                if (field.indexOf("color") >= 0)
                {
                    for (const color of field_vals)
                    if (!setup.str_to_color(color,true).result)
                    {
                        if (invalid_colors[color])
                        {
                            invalid_colors[color].push(item);
                        }
                        else
                        {
                            invalid_colors[color] = [item];
                        }
                    }
                }
            }
        }
    }
    return invalid_colors;
}

