setup.str_to_color = function(strColor, just_result = false)
{
    strColor = strColor.toLowerCase();
    let result = false;
    let color = strColor;
    let luma = 0;
    let style = "display:none;";
    let text_color = "";
    let shadow = "";
    let border = "";
    //console.log("checking if color: ",strColor)

    result = (strColor in setup.ob_color_table);
    if (result)
    {
        color = setup.ob_color_table[strColor];
    }
    else
    {
        const s = new Option().style;
        s.color = strColor;
        result = s.color != '';
    }

    if (result && !just_result)
    {
        if (typeof(color) == 'string')
        {
            let preColor = color;
            color = setup.ob_standardize_color(color);
            //console.log("from "+strColor+" to "+preColor+" to "+color);
            // calculate luminance
            var c = color.substring(1);      // strip #
            var rgb = parseInt(c, 16);   // convert rrggbb to decimal
            var r = (rgb >> 16) & 0xff;  // extract red
            var g = (rgb >>  8) & 0xff;  // extract green
            var b = (rgb >>  0) & 0xff;  // extract blue

            luma = 0.2126 * r + 0.7152 * g + 0.0722 * b; // per ITU-R BT.709

            style = "color:"+color+";";
            let shadow_color = color;
            text_color = "#101010";
            if (luma < 50)
            {
                text_color = "#eeeeee"
                shadow_color = "#606060";
                style = style + "text-shadow: -1px 0 "+shadow_color+", 0 1px "+shadow_color+", 1px 0 "+shadow_color+", 0 -1px "+shadow_color+";"
            }
            let hsl_color = setup.ob_hex_to_hsl(color);
            shadow = clone(hsl_color);
            shadow.l = Math.max(0,hsl_color.l-10);
            border = clone(hsl_color);
            border.l = Math.min(100,hsl_color.l+10);
            shadow = setup.ob_hsl_str(shadow);
            border = setup.ob_hsl_str(border);
        }
        else
        {
            let colorobj = color;
            //console.log("Color is object!!");
            color = colorobj.background;
            text_color = colorobj.text;
            shadow = colorobj.shadow;
            border = colorobj.border;
            style = "text-shadow: -1px 0 "+colorobj.text_shadow+", 0 1px "+colorobj.text_shadow+", 1px 0 "+colorobj.text_shadow+", 0 -1px "+colorobj.text_shadow;
            if (colorobj.animation)
                style += " animation: " + colorobj.animation;
            style += ";";

        }

    }
    //console.log("checking if color: ",strColor,result, color);
    return {"result":result,"value":color,"luma":luma,"style":style, "text_color":text_color, "shadow":shadow,"border":border};
}

setup.ob_colorize_string = function(string_in)
{
    var result = "";
    //console.log("Colorizing String: ",string_in);
    let max_color_words = 3;
    // split the string apart
    let replace_list = {}
    let words = string_in.split(/(\W+)/);//match(/\b(\w+)\b/g);//split(/([\s,.]+)/)
    let idx = 0;
    //console.log("split string:",words);
    for (idx = 0; idx < words.length; idx++)
    {
        // make sure we're looking at a word (or something that starts with a letter at least :D)
        if (words[idx].first().toUpperCase() != words[idx].first().toLowerCase())
        {
            for (let current_color_words = max_color_words; current_color_words > 0; current_color_words--)
            {
                let word_group = words.slice(idx,idx+current_color_words);
                let test_str = word_group.join("");
                let color_result = setup.str_to_color(test_str);
                //console.log("Test Str: ",word_group, "\""+test_str+"\"");
                if (color_result.result)
                {
                    //console.log("Found color: ",test_str, color_result);
                    result = result + "<span style=\""+color_result.style+"\">"+test_str+"</span>";
                    idx = idx + current_color_words - 1;
                    break;
                }
                else if (current_color_words == 1)
                {
                    result = result + test_str;
                }
            }
        }
        else
        {
            result = result + words[idx];
        }
    }
    return result;
}

setup.ob_hsl_str = function(hsl_obj)
{
    return 'hsl('+ hsl_obj.h + ',' + hsl_obj.s + '%,' + hsl_obj.l + '%)'
}

setup.ob_hex_to_hsl = function(hex,hslmod={'h':0,'s':0,'l':0})
{
    var result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);

    var r = parseInt(result[1], 16);
    var g = parseInt(result[2], 16);
    var b = parseInt(result[3], 16);

    r /= 255, g /= 255, b /= 255;
    let cmin = Math.min(r,g,b),
    cmax = Math.max(r,g,b),
    delta = cmax - cmin,
    h = 0,
    s = 0,
    l = 0;

    if (delta == 0)
    h = 0;
    else if (cmax == r)
    h = ((g - b) / delta) % 6;
    else if (cmax == g)
    h = (b - r) / delta + 2;
    else
    h = (r - g) / delta + 4;

    h = Math.round(h * 60);

    if (h < 0)
    h += 360;

    l = (cmax + cmin) / 2;
    s = delta == 0 ? 0 : delta / (1 - Math.abs(2 * l - 1));
    s = Math.round(s * 100);
    l = Math.round(l * 100);

    var HSL = new Object();
    HSL['h']=h;
    HSL['s']=s;
    HSL['l']=l;
    return HSL;
}

/* go through a string and highlight keywords */
setup.ob_highlight_keywords = function(string_in)
{
    const highlight_containing = {
        "bad":[],
        "unbad":[],
        "ungood":["stained"]
    }
    let result = "";
    let words = string_in.split(/(\s+)/);
    for (let word of words)
    {
        for (const [highlight,strings] of Object.entries(highlight_containing))
        {
            for (const check_str of strings)
            {
                if (word.indexOf(check_str) >= 0)
                {
                    word = "<span class='"+highlight+"'>"+word+"</span>";
                }
            }
        }
        result = result + word;
    }
    return result;
}

if (!String.prototype.replaceAll)
    String.prototype.replaceAll = function(searchValue, replaceValue)
    {
        // Escape special characters in searchValue to ensure proper matching
        const escapedSearchValue = searchValue.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        // Create a regular expression with global flag to match all occurrences
        const regex = new RegExp(escapedSearchValue, 'g');
        // Use the regular expression to replace all occurrences with replaceValue
        return this.replace(regex, replaceValue);
    }

