function AddLinkEmojis(Container)
{
    if (!V.optshowemojis) return;
    let links;
    if (typeof Container === "undefined") {
        Container = document;
        links = $("#passages a").toArray();
    } else {
        links = $(Container).find("a").toArray();
    }

    for (let link of links)
    {
        let emoji = $(link).data('emoji');
        if (emoji)
        {
            let emojispan = $('<span class="link-emoji">' + emoji + ' </span>');
            $(link).before(emojispan);
        }
    }
}
