setup.ob_passage_kink = function(passage)
{
    if (Story.has(passage))
    {
        const tags = Story.get(passage).tags;
        for (let tag of tags)
        {
            if (tag.indexOf("kink") == 0)
                return tag.substring(4).replaceAll('_', ' ');
        }
    }
}

function AddLinkKinkWarnings(Container)
{
    if (!V.kinkcontentaware) return;
    let links;
    if (typeof Container === "undefined") {
        Container = document;
        links = $("#passages a").toArray();
    } else {
        links = $(Container).find("a").toArray();
    }

    for (let link of links)
    {
        let kink = $(link).data('kink');
        if (kink && (V.kinkcontentaware.includes(kink) || !V.kinkcontent.includes(kink)))
        {
            // it may occasionally be the case that we're displaying a link despite its content having been turned off
            // for example, the hypnosis events in psych class
            // because this content is avoidable in other ways
            let awarethispassage = [];
            if (!V.recentlyawarekinks) V.recentlyawarekinks = [];
            if (!V.recentlyawarekinks.includes(kink) || awarethispassage.includes(kink))
            {
                V.recentlyawarekinks.push(kink);
                awarethispassage.push(kink);
                let kinkspan = $('<span class="small link-kink"> (Content: <span class="sexy">' + setup.kink_content[kink].name + '</span>)</span>');
                $(link).after(kinkspan);
            }
        }
    }
}

setup.ob_containsDuplicates = function(arr, checkobjects = false)
{
    if (arr.length == 0)
        return false;
    else if (new Set(arr).size !== arr.length)
        return true;
    else if (checkobjects)
        return this.containsDuplicateObjects(arr);
    else
        return false;
}

setup.ob_removeDuplicates = function(arr)
{
    return [...new Set(arr)];
}

setup.numberOfObjectInstances = function(arr, obj)
{
    if (arr.length == 0) return 0;
    let n = 0;
    for (let obj2 of arr)
    {
        if (typeof obj2 == "object")
        {
            let dup = true;
            for (const [k, v] of Object.entries(obj))
                if (obj2[k] != v)
                {
                    dup = false;
                    break;
                }
            if (dup) n++;
        }
    }
    return n;
}

setup.containsDuplicateObjects = function(arr)
{
    if (arr.length == 0) return false;
    for (let obj of arr)
    {
        if (typeof obj == "object" && this.numberOfObjectInstances(arr, obj) > 1)
            return true;
    }
    return false;
}

