setup.ob_scanForDataIssues = function(target = V) {
    // Currently our deepest depth is only 6. Leave some wiggle room. A fixed Stack size should save us a lot of array manipulation
    const maxDepth = 12;
    const stack = new Array(maxDepth);
    let stackIndex = 0;


    stack[stackIndex++] = [target, "V"];


    while (stackIndex > 0) {
        const [obj, path] = stack[--stackIndex];


        for (const key in obj) {
            const value = obj[key];
            if (value == null) continue;


            const newPath = `${path}['${key}']`;


            if (Number.isNaN(value) || (Array.isArray(value) && value.some(v => v == null))) {
                console.warn(`${newPath} is (${Array.isArray(value) ? "Array" : typeof value}) with value (${value})`);
            } else if (typeof value === "object" && stackIndex < maxDepth) {
                stack[stackIndex++] = [value, newPath];
            }
        }
    }
};

