setup.arrEquals = function(arr1, arr2)
{
    if (!Array.isArray(arr1) || !Array.isArray(arr2) || arr1.length != arr2.length) return false;

    return arr1.every((val, i) => {
        if (Array.isArray(val) && Array.isArray(arr2[i]))
        {
            return this.arrEquals(val, arr2[i]);
        }
        else if (typeof val == "object" && val != null && typeof arr2[i] == "object" && arr2[i] != null)
        {
            return JSON.stringify(val) == JSON.stringify(arr2[i]);
        }
        else
        {
            return val == arr2[i];
        }
    });
}

