setup.ob_encode_bitwise_array = function(basearray, valuesarray)
{
    // take an array and return an integer
    let encoded = 0;
    for (let el of valuesarray)
    {
        let i = basearray.indexOf(el);
        encoded |= 1 << i;
    }
    return encoded;
}

setup.ob_decode_bitwise_array = function(basearray, encoded)
{
    // take an integer and decode it into an array
    let valuesarray = [];
    for (let i = 0; i < basearray.length; i++) {
        if ((encoded & (1 << i)) !== 0) {
            valuesarray.push(basearray[i]);
        }
    }
    return valuesarray;
}

setup.ob_getOrdinal = function(n)
{
  let ord = 'th';

  if (n % 10 == 1 && n % 100 != 11)
  {
    ord = 'st';
  }
  else if (n % 10 == 2 && n % 100 != 12)
  {
    ord = 'nd';
  }
  else if (n % 10 == 3 && n % 100 != 13)
  {
    ord = 'rd';
  }

  return n.toString() + ord;
}

