setup.ob_gifts = {};

setup.ob_gifts.giftinfo = function(name)
{
    // compile relevant info into a gift object

    let retval = {};

    if (name in setup.ob_dormstuff)
    {
        const iteminfo = setup.ob_dormstuff[name];
        if (!iteminfo.gift) return undefined;

        retval.item = name;
        retval.db = "dormstuff";
        retval.appeal = iteminfo.appeal || {};
        retval.price = iteminfo.price;
        if (setup.ob_locationInventory.has("packed", name, false, false))
        {
            retval.name = setup.ob_locationInventory.get("packed", name).name || setup.ob_locationInventory.get("packed", name).item;
        }
        else
        {
            retval.name = name;
        }
        retval.name = setup.ob_a_or_an(retval.name) + " " + retval.name;
    }
    else if (setup.ob_books.book_info(name, false))
    {
        const iteminfo = setup.ob_books.book_info(name);

        retval.item = name;
        retval.db = "books";

        if (iteminfo.appeal)
            retval.appeal = iteminfo.appeal;
        else if (iteminfo.skills)
            retval.appeal = {skill: Object.keys(iteminfo.skills)};
        else
            retval.appeal = {};

        retval.price = iteminfo.price;
        retval.name = 'a book called "' + name + '"';
    }
    else if (name in setup.clothes)
    {
        const iteminfo = setup.clothes[name];
        if (!iteminfo.gift) return undefined;

        retval.item = name;
        retval.db = "clothes";
        retval.appeal = iteminfo.appeal || {};
        retval.price = iteminfo.price;
        retval.name = setup.ob_a_or_an(name) + " " + name.toLowerCase();
    }
    else if (name.indexOf("plush") > 0)
    {
        retval.item = name;
        retval.name = name;
        retval.db = "plushies";
        retval.appeal = setup.ob_dormstuff["plushie collection"].appeal || {};
        retval.price = 10;
    }
    else if (setup.ob_dormstuff["rock collection"]["sub mineral"].includes(name))
    {
        retval.item = name;
        retval.name = setup.ob_a_or_an(name) + " " + name;
        retval.db = "rocks";
        retval.appeal = setup.ob_dormstuff["rock collection"].appeal || {};
        retval.price = 20;
    }
    else if (name.indexOf("anime figurine") > 0)
    {
        retval.item = name;
        retval.name = name;
        retval.db = "anime figurines";
        retval.appeal = setup.ob_dormstuff["anime figurine collection"].appeal || {};
        retval.price = setup.ob_dormstuff["anime figurine collection"].price;
    }
    else if (name.indexOf("video game figurine") > 0)
    {
        retval.item = name;
        retval.name = name;
        retval.db = "video game figurines";
        retval.appeal = setup.ob_dormstuff["video game figurine collection"].appeal || {};
        retval.price = setup.ob_dormstuff["video game figurine collection"].price;
    }
    else if (name.indexOf("movie figurine") > 0)
    {
        retval.item = name;
        retval.name = name;
        retval.db = "movie figurines";
        retval.appeal = setup.ob_dormstuff["movie figurine collection"].appeal || {};
        retval.price = setup.ob_dormstuff["movie figurine collection"].price;
    }
    else if (name.indexOf("crime boys figurine") > 0 || name.indexOf("Crime Boys figurine") > 0 || name.indexOf("Crimeboys figurine") > 0)
    {
        retval.item = name;
        retval.name = name;
        retval.db = "crime boys figurines";
        retval.appeal = setup.ob_dormstuff["crime boys figurine collection"].appeal || {};
        retval.price = setup.ob_dormstuff["crime boys figurine collection"].price;
    }
    else if (name.indexOf("tokyo grift figurine") > 0 || name.indexOf("Tokyo Grift figurine") > 0)
    {
        retval.item = name;
        retval.name = name;
        retval.db = "tokyo grift figurines";
        retval.appeal = setup.ob_dormstuff["tokyo grift figurine collection"].appeal || {};
        retval.price = setup.ob_dormstuff["tokyo grift figurine collection"].price;
    }
    else if (Object.keys(setup.ob_creating.artTypes).some(artname => name.indexOf(artname) >= 0))
    {
        retval.item = name;
        retval.name = name;
        retval.db = "art";
        let arttype = Object.keys(setup.ob_creating.artTypes).find(artname => name.indexOf(artname) >= 0);
        retval.appeal = setup.ob_creating.artTypes[arttype].appeal || {};
        retval.price = setup.ob_creating.artTypes[arttype].price;
        retval.art = V.createdart.filter(art => art.name == setup.ob_strip_a_or_an(name) && art.mediumType == "physical")[0];
        if (retval.art)
        {
            retval.exhibitionism = setup.ob_creating.exhibitionism_to_post(retval.art);
        }
    }
    else
    {
        return undefined;
    }

    return retval;
}

setup.ob_gifts.is_romantic = function(gift)
{
    const giftinfo = typeof gift == "object" ? gift : this.giftinfo(gift);

    if (giftinfo.appeal)
    {
        for (let [field, value] of Object.entries(giftinfo.appeal))
        {
            if (!Array.isArray(value)) value = [value];

            if (field == "relationship")
            {
                for (let rel of value)
                {
                    if (setup.ob_relationships.db[rel].type == "romantic")
                        return true;
                }
            }
            else if (field == "relationshiptype")
            {
                if (value.includes("romantic"))
                    return true;
            }
        }
    }
    return false;
}

setup.ob_gifts.is_for_relationship = function(gift, relationship)
{
    const giftinfo = typeof gift == "object" ? gift : this.giftinfo(gift);

    if (giftinfo.appeal)
    {
        for (let [field, value] of Object.entries(giftinfo.appeal))
        {
            if (!Array.isArray(value)) value = [value];

            if (field == "relationship")
            {
                if (value.includes(relationship)) return true;
            }
        }
    }
    return false;
}

setup.ob_gifts.accept_romantic = function(name)
{
    if (setup.ob_relationships.relationship_type_with(name) == "romantic")
        return true;
    else if (setup.people.is_dating(name))
        return true;
    else if ((setup.people.is_professor(name, true) || setup.people.is_coach(name, true)) && setup.people.professor_intimacy(name) >= 2)
        return true;
    else
        return false;
}

setup.ob_gifts.receive_appeal = function(gift, name)
{
    // the appeal of a gift to an NPC (as in, the PC giving it to them), 0-1000

    const giftinfo = typeof gift == "object" ? gift : this.giftinfo(gift);

    let totalappeal = 0;
    let items = 0;

    let rng = setup.ob_newRNG(setup.people.get_name(name) + "gift");

    if (giftinfo.appeal)
    {
        for (let [field, value] of Object.entries(giftinfo.appeal))
        {
            if (!Array.isArray(value)) value = [value];

            if (field == "presentation")
            {
                items++;
                if ((value.includes("femme") && setup.people.is_femme(name)) || (value.includes("masc") && setup.people.is_masc(name)) || (value.includes("enby") && setup.people.is_enby(name)))
                    totalappeal += 1000;

            }
            else if (field == "skill")
            {
                for (let skill of value)
                {
                    totalappeal += setup.people.skill_level(name, skill) * 100;
                    items++;
                }
            }
            else if (field == "archetype")
            {
                items++;
                if (value.includes(setup.people.archetype(name)))
                    totalappeal += 1000;
            }
            else if (field == "type")
            {
                items++;
                if (value.includes(setup.people.get_type(name)))
                    totalappeal += 1000;
            }
            else if (field == "inclination")
            {
                items++;
                let incappeal = 0;
                for (let inc of value)
                    if (setup.people.has_inclination(name, inc))
                        incappeal += 400;

                totalappeal += Math.min(incappeal, 1000);
            }
            else if (field == "relationship")
            {
                items++;
                if (value.includes(setup.ob_relationships.relationship_with(name)))
                    totalappeal += 1000;
            }
            else if (field == "relationshiptype")
            {
                items++;
                if (value.includes(setup.ob_relationships.relationship_type_with(name)))
                    totalappeal += 1000;
            }
            else if (field == "single")
            {
                if (!setup.ob_relationships.partner(name))
                    totalappeal += value;
            }
            else if (field == "dating")
            {
                if (setup.ob_relationships.partner(name))
                    if (setup.ob_relationships.partner_type(name) == "spouse")
                        totalappeal += (value / 2);
                    else
                        totalappeal += value;
            }
            else if (field == "married")
            {
                if (setup.ob_relationships.partner(name) && setup.ob_relationships.partner_type(name) == "spouse")
                    totalappeal += value;
            }
            // since this is a gift we invert these
            else if (field == "poor")
            {
                totalappeal += setup.people.get_wealth(name) * (value / 1000);
            }
            else if (field == "rich")
            {
                totalappeal += (1000 - setup.people.get_wealth(name)) * (value / 1000);
            }
            else if (field == "random")
            {
                items++;
                let maxamt = value[0];
                totalappeal += rng.random() * maxamt;
            }
        }
    }

    if (giftinfo.db == "art")
    {
        let artitem = setup.ob_creating.find_art_info(giftinfo.name)
        if (artitem)
        {
            if (artitem.subjectType == "portrait" && setup.people.get_name(name) == artitem.subject)
            {
                items++;
                let qualityperc = artitem.quality / 1000;
                if (setup.people.likes_pc(name))
                    totalappeal += 1000 * qualityperc;
                else
                    totalappeal -= 250;
            }
            else
            {
                let qualityperc = artitem.quality / 1000;
                totalappeal += 600 * qualityperc;
            }
        }
    }

    if (giftinfo.price)
    {
        let priceappeal = 0;
        if (giftinfo.price <= 10)
            priceappeal = 100;
        else if (giftinfo.price <= 25)
            priceappeal = 200;
        else if (giftinfo.price <= 50)
            priceappeal = 300;
        else if (giftinfo.price <= 75)
            priceappeal = 400;
        else if (giftinfo.price <= 100)
            priceappeal = 500;
        else if (giftinfo.price <= 150)
            priceappeal = 600;
        else if (giftinfo.price <= 200)
            priceappeal = 700;
        else if (giftinfo.price <= 300)
            priceappeal = 800;
        else if (giftinfo.price <= 400)
            priceappeal = 900;
        else
            priceappeal = 1000;

        items++;
        totalappeal += priceappeal;
    }

    if (items == 0) return 200;

    return Math.max(Math.floor(totalappeal / items), 0);
}

setup.ob_gifts.give_appeal = function(gift, name)
{
    // the appeal of giving a gift to the PC for an NPC, 0-1000

    const giftinfo = typeof gift == "object" ? gift : this.giftinfo(gift);

    let totalappeal = 0;
    let items = 0;

    let rng = setup.ob_newRNG(setup.people.get_name(name) + giftinfo.name);

    if (this.is_romantic(giftinfo) && (name == "parents" || !this.accept_romantic(name))) return 0;

    if (this.is_for_relationship(gift, "submissive") && (name == "parents" || setup.ob_relationships.relationship_with(name) == "submissive")) return 0;
    if (this.is_for_relationship(gift, "dominant") && (name == "parents" || setup.ob_relationships.relationship_with(name) == "dominant")) return 0;
        // this is confusing but given the relationship appeal is inversed (because this gift is NPC => PC) then we need them to NOT match

    if (giftinfo.appeal)
    {
        for (let [field, value] of Object.entries(giftinfo.appeal))
        {
            if (!Array.isArray(value)) value = [value];

            if (field == "presentation")
            {
                items++;
                if ((value.includes("femme") && setup.people.is_femme("PC")) || (value.includes("masc") && setup.people.is_masc("PC")) || (value.includes("enby") && setup.people.is_enby("PC")))
                    totalappeal += 1000;

            }
            else if (field == "skill")
            {
                for (let skill of value)
                {
                    totalappeal += setup.people.skill_level("PC", skill) * 100;
                    items++;
                }
            }
            else if (field == "archetype")
            {

            }
            else if (field == "type")
            {

            }
            else if (field == "inclination")
            {
                items++;
                let incappeal = 0;
                for (let inc of value)
                    if (V.pc.has_inclination(inc))
                        incappeal += 400;

                totalappeal += Math.min(incappeal, 1000);
            }
            else if (field == "relationship")
            {
                items++;

                // certain relationships are inverses of each other
                // by default 'appeal' is quantifying the NPC's relationship to the PC
                // but now we have to consider the reverse
                let invvalue = [];
                for (let rel of value)
                {
                    if (setup.ob_relationships.db[rel].inverse)
                        invvalue.push(setup.ob_relationships.db[rel].inverse);
                    else
                        invvalue.push(rel);
                }

                if (name != "parents" && invvalue.includes(setup.ob_relationships.relationship_with(name)))
                    totalappeal += 1000;
            }
            else if (field == "relationshiptype")
            {
                items++;
                if (name != "parents" && value.includes(setup.ob_relationships.relationship_type_with(name)))
                    totalappeal += 1000;
            }
            else if (field == "random")
            {
                items++;
                let maxamt = value[0];
                totalappeal += rng.random() * maxamt;
            }
        }
    }

    if (name == "parents" && giftinfo.db == "dormstuff")
    {
        totalappeal += 1000;
        items++;
    }

    if (giftinfo.price && totalappeal > 0)
    {
        // this is different also because very cheap and very expensive gifts should both be kinda rare
        let priceappeal = 0;
        if (giftinfo.price <= 10)
            priceappeal = 100;
        else if (giftinfo.price <= 25)
            priceappeal = 300;
        else if (giftinfo.price <= 50)
            priceappeal = 600;
        else if (giftinfo.price <= 75)
            priceappeal = 1000;
        else if (giftinfo.price <= 100)
            priceappeal = 500;
        else if (giftinfo.price <= 150)
            priceappeal = 300;
        else if (giftinfo.price <= 200)
            priceappeal = 200;
        else if (giftinfo.price <= 300)
            priceappeal = 100;
        else if (giftinfo.price <= 400)
            priceappeal = 50;
        else
            priceappeal = 10;

        items++;
        totalappeal += priceappeal;
    }

    if (items == 0) return 0;

    return Math.floor(totalappeal / items);
}

setup.ob_gifts.available_gifts = function(onlycheck = false)
{
    // all the gifts that the PC has available to give

    // if onlycheck arg is true... returns immediately at first gift add, so use that if you want to cheaply check whether the pc has any gifts to give

    const retval = [];

    let dormstuff = setup.ob_locationInventory.contents("packed");
    if (dormstuff)
    {
        for (let item of dormstuff)
        {
            let gi = this.giftinfo(item.item);
            if (gi)
            {
                retval.push(gi);
                if (onlycheck) return retval;
            }
        }
    }

    let closet = V.pc.get_storage_location("dormcloset");
    for (let clothes of closet.clothes)
    {
        let giftinfo = this.giftinfo(clothes.item);
        if (giftinfo)
        {
            giftinfo.subs = clothes.subs;
            giftinfo.clothingitem = clothes;
            giftinfo.clothingname = clothes.get_name();
            retval.push(giftinfo);
            if (onlycheck) return retval;
        }
    }

    let bookshelf = setup.ob_dorm_get("bookshelf");
    if (bookshelf)
