        for (let book of bookshelf.collection)
        {
            retval.push(this.giftinfo(book));
            if (onlycheck) return retval;
        }
    }

    let plushcollection = setup.ob_dorm_get("plushie collection");
    if (plushcollection && plushcollection.collection)
    {
        for (let plush of plushcollection.collection)
        {
            retval.push(this.giftinfo(plush))
            if (onlycheck) return retval;
        }
    }

    let afigurecollection = setup.ob_dorm_get("anime figurine collection");
    if (afigurecollection && afigurecollection.collection)
    {
        for (let plush of afigurecollection.collection)
        {
            retval.push(this.giftinfo(plush))
            if (onlycheck) return retval;
        }
    }

    let vfigurecollection = setup.ob_dorm_get("video game figurine collection");
    if (vfigurecollection && vfigurecollection.collection)
    {
        for (let plush of vfigurecollection.collection)
        {
            retval.push(this.giftinfo(plush))
            if (onlycheck) return retval;
        }
    }

    let mfigurecollection = setup.ob_dorm_get("movie figurine collection");
    if (mfigurecollection && mfigurecollection.collection)
    {
        for (let plush of mfigurecollection.collection)
            retval.push(this.giftinfo(plush))
    }

    let cbfigurecollection = setup.ob_dorm_get("crime boys figurine collection");
    if (cbfigurecollection && cbfigurecollection.collection)
    {
        for (let plush of cbfigurecollection.collection)
        {
            retval.push(this.giftinfo(plush))
            if (onlycheck) return retval;
        }
    }

    let tgfigurecollection = setup.ob_dorm_get("tokyo grift figurine collection");
    if (tgfigurecollection && tgfigurecollection.collection)
    {
        for (let plush of tgfigurecollection.collection)
        {
            retval.push(this.giftinfo(plush))
            if (onlycheck) return retval;
        }
    }

    let rockcollection = setup.ob_dorm_get("rock collection");
    if (rockcollection && rockcollection.collection)
    {
        for (let rock of rockcollection.collection)
        {
            retval.push(this.giftinfo(rock))
            if (onlycheck) return retval;
        }
    }

    let artcollection = setup.ob_dorm_get("art collection");
    if (artcollection)
    {
        for (let art of setup.ob_dormstuff_collection_inventory(artcollection))
        {
            retval.push(this.giftinfo(art))
            if (onlycheck) return retval;
        }
    }

    return retval.filter(item => item != undefined);
}

setup.ob_gifts.possible_npc_gifts = function(name, categorylimit=10, returnimmediately=false)
{
    // all gifts that the PC presently doesn't have (that NPCs can give)

    const now = Date.now();
    if (!returnimmediately)
    {
        if (!this.giftCache)
            this.giftCache = {};
        else if (this.giftCache[name] && now - this.giftCache[name][0] < 1000)
        {
            return this.giftCache[name][1];
        }
    }

    const retval = [];

    // dormstuff
    let added = 0;
    for (const [dormstuff, iteminfo] of setup.ob_shuffle(Object.entries(setup.ob_dormstuff)))
    {
        if (added >= categorylimit || ["wall decor"].includes(iteminfo.category)) break;
        if (iteminfo.gift && !setup.ob_locationInventory.has("packed", dormstuff, true) && !setup.ob_locationInventory.has(setup.ob_locationInventory.lastloc(), dormstuff, true))
        {
            added++;
            let giftinfo = this.giftinfo(dormstuff);
            giftinfo.npcgiveappeal = this.give_appeal(giftinfo, name);
            giftinfo.name = setup.ob_shops.randomize_name(iteminfo, "gift")[0];
            if (setup.pluralize(giftinfo.name) != giftinfo.name)
                giftinfo.name = setup.ob_a_or_an(giftinfo.name) + " " + giftinfo.name;
            if (giftinfo.npcgiveappeal > 0) retval.push(giftinfo);

            if (returnimmediately && retval.length > 1) return retval;
        }
    }

    // books
    added = 0;
    for (const book of Object.keys(setup.ob_books.books_db()))
    {
        if (added >= categorylimit) break;
        if (!setup.ob_books.has(book))
        {
            added++;
            let giftinfo = this.giftinfo(book);
            giftinfo.npcgiveappeal = this.give_appeal(giftinfo, name);
            if (giftinfo.npcgiveappeal > 0) retval.push(giftinfo);

            if (returnimmediately && retval.length > 1) return retval;
        }
    }

    // clothes
    added = 0;
    for (const [clothes, cinfo] of Object.entries(setup.clothes).filter(item => item[1].gift))
    {
        if (added >= categorylimit) break;
        let giftinfo = this.giftinfo(clothes);

        if (giftinfo && !V.pc.already_has_clothing_item(clothes))
        {
            added++;
            giftinfo.npcgiveappeal = this.give_appeal(giftinfo, name);
            if (giftinfo.npcgiveappeal > 0)
            {
                let namesubs = setup.ob_shops.randomize_name(cinfo, "gift");
                giftinfo.name = setup.ob_a_or_an(namesubs[0]) + " " + namesubs[0];
                giftinfo.subs = namesubs[1];
                retval.push(giftinfo);
            }

            if (returnimmediately && retval.length > 1) return retval;
        }
    }

    // plushies
    // (needs some special handling, otherwise there's a million of them)
    for (let i = 0; i < categorylimit; i++)
    {
        let type = setup.ob_randomchoice(setup.ob_dormstuff["plushie collection"]["sub type"]);
