setup.ob_gifts.pick_gift_for_pc = function(name, minspend = -1, maxspend = -1)
{
    // gift-picking with retries because it is finicky sometimes, especially with price clamps
    let tries = 0;
    let pick = null;
    while (tries < 10 && !pick)
    {
        tries++;
        pick = this.raw_pick_gift_for_pc(name, minspend, maxspend);
    }
    return pick;
}

setup.ob_gifts.raw_pick_gift_for_pc = function(name, minspend = -1, maxspend = -1)
{
    // compile list of possible gifts that NPC could give to PC
    // limit based on spending clamps
    // pick one

    let allgifts = setup.ob_gifts.possible_npc_gifts(name);

    const picklist = [];
    for (let gift of allgifts)
    {
        if (minspend != -1 && gift.price < minspend)
            continue;
        else if (maxspend != -1 && gift.price > maxspend)
            continue;
        else
            picklist.push(gift, gift.npcgiveappeal);
    }

    return setup.ob_randomrelfreq(picklist);
}

setup.ob_gifts.register_gift_given = function(name, gift, amount)
{
    /* received by NPC, given by PC */
    let pdata = setup.people.get_person(name);
    pdata.lastgiftreceived = V.gameday;
    let appeal = amount;
    if (!pdata.bestgiftreceivedscore || pdata.bestgiftreceivedscore < appeal)
    {
        pdata.bestgiftreceivedscore = appeal;
        pdata.bestgiftreceived = [gift.item, gift.name];
    }
    pdata.lastgiftgiven = V.gameday;
    if (gift.db == "clothes")
    {
        let citem = {item: gift.item, subs: gift.subs};
        if (!pdata.giftedClothing) pdata.giftedClothing = [];
        pdata.giftedClothing.push(citem);
        pdata.giftedClothing = [...new Map(pdata.giftedClothing.map(item => [JSON.stringify(item), item])).values()]; // remove duplicates
    }
}

setup.ob_gifts.days_since_gift_received = function(name)
{
    // days since a gift was received by this NPC
    let pdata = setup.people.get_person(name);
    if (!pdata.lastgiftreceived) return V.gameday;
    else return V.gameday - pdata.lastgiftreceived;
}

setup.ob_gifts.register_gift_received = function(name, gift)
{
    /* received by PC, given by NPC */
    let pdata = setup.people.get_person(name);
    pdata.lastgiftgiven = V.gameday;
    if (!V.giftstoday)
        V.giftstoday = 1;
    else
        V.giftstoday++;
}

setup.ob_gifts.days_since_gift_given = function(name)
{
    // days since a gift was given to the PC by this NPC
    let pdata = setup.people.get_person(name);
    if (!pdata.lastgiftgiven) return V.gameday;
    else return V.gameday - pdata.lastgiftgiven;
}

setup.ob_gifts.giftable_collars = function()
{
    // find collars we can gift to an NPC
    // a bit of duplicated code, which i don't really like, but the main gift method is fucking expensive
    let retval = [];
    let closet = V.pc.get_storage_location("dormcloset");
    for (let clothes of closet.clothes.filter(c => setup.clothes[c.item].flags.includes("collar")))
    {
        let giftinfo = this.giftinfo(clothes.item);
        if (giftinfo)
        {
            giftinfo.subs = clothes.subs;
            giftinfo.clothingitem = clothes;
            giftinfo.clothingname = clothes.get_name();
            retval.push(giftinfo);
        }
    }
    return retval;
}
