setup.ob_houses.house_from_letters = function(letters)
{
    let matching = Object.keys(this.db).filter(house => letters.indexOf(this.db[house].latin) >= 0);
    if (matching.length > 0) return matching[0];
}

setup.ob_houses.is_fraternity = function(house)
{
    let genders = this.houseinfo(house).genders;
    return genders.includes("male") && !genders.includes("female");
}

setup.ob_houses.is_sorority = function(house)
{
    let genders = this.houseinfo(house).genders;
    return genders.includes("female") && !genders.includes("male");
}

setup.ob_houses.house_label = function(house)
{
    if (!V.tradgreeks)
        return "house";
    else if (this.is_fraternity(house))
        return "fraternity";
    else if (this.is_sorority(house))
        return "sorority";
    else
        return "house";
}

setup.ob_houses.can_join = function(house, npc = "PC")
{
    // whether this house can be joined based on gender traditions (if there are any)
    let gender = V.pc.equals(npc) ? setup.ob_pcgender() : setup.people.get_gender(npc);
    if (V.lefthouse && V.lefthouse.includes(house))
        return false;
    else if (!V.tradgreeks)
        return true;
    else if (this.is_fraternity(house))
        return ["male", "transgender male", "nonbinary afab", "nonbinary amab"].includes(gender);
    else if (this.is_sorority(house))
        return ["female", "transgender female", "nonbinary afab", "nonbinary amab"].includes(gender);
    else
        return true;
}

setup.ob_houses.get_house = function(npc)
{
    return setup.people.get_person(npc).house;
}

setup.ob_houses.init_houses = function()
{
    V.houses = {};
    const houses = Object.keys(this.db);
    for (let house of houses)
    {
        V.houses[house] = {
            members: [],
        };
    }
}

setup.ob_houses.find_member = function(house, year = -1, rng = setup.ob_newRNG(V.seed + "house"), exclude = [])
{
    let students = Object.keys(V.people).filter(p =>
        !exclude.includes(p) &&
        setup.people.get_type(p) == "student" &&
        !this.get_house(p) &&
        (year == -1 || setup.people.get_year(p) == year) &&
        (!V.tradgreeks || this.houseinfo(house).genders.includes(setup.people.get_gender(p)))
    );

    const archetypes = this.houseinfo(house).archetypes;

    let tries = 0;
    let pick;
    while (!pick && tries < 100)
    {
        tries++;
        let archetype = rng.randomrelfreq(archetypes);
        let possible = students.filter(p => setup.people.archetype(p) == archetype);
        pick = rng.randomchoice(possible);
    }

    return pick;
}

setup.ob_houses.place = function(npc, house)
{
    const person = setup.people.get_person(npc);
    person.house = house;
    if (person?.roommate && setup.people.has_greek_house_room(npc)) {
        const roommate = setup.people.get_person(person.roommate);
        delete person.roommate;
        delete roommate.roommate;
    }
    V.houses[house].members.push(npc);
    console.log(`placing ${npc} in ${house}`);
}

setup.ob_houses.house = function(npc, excludepledges = false)
{
    if (V.pc.equals(npc))
    {
        let house = excludepledges ? V.pchouse : V.pchouse || V.greekpledge;
        return house;
    }
    else
    {
        const pdata = setup.people.get_person(npc);
        if (pdata.type != "student") return;
        let house = excludepledges ? pdata.house : pdata.house || pdata.pledged;
        return house;
    }
}

setup.ob_houses.in_other_house = function(npc)
{
    let house = this.house(V.pc);
    if (!house) return false;
    let npchouse = this.house(npc);
    return npchouse && npchouse != house;
}

setup.ob_houses.in_same_house = function(npc)
{
    let house = this.house(V.pc);
    if (!house) return false;
    let npchouse = this.house(npc);
    return npchouse && house == npchouse;
}

setup.ob_houses.in_rival_house = function(npc)
{
    let house = this.house(V.pc);
    if (!house) return false;
    let npchouse = this.house(npc);
    return npchouse && this.db[house].rivals.includes(npchouse);
}

setup.ob_houses.in_allied_house = function(npc)
{
    let house = this.house(V.pc);
    if (!house) return false;
    let npchouse = this.house(npc);
    return npchouse && (house == npchouse || this.db[house].allies.includes(npchouse));
}

setup.ob_houses.fill_houses = function(rng = setup.ob_newRNG(V.seed + "house"))
{
    let found = {};
    let allfound = [];
    const houses = Object.keys(this.db);
    for (let house of houses)
    {
        found[house] = [];
        for (let year of [2, 3, 4])
        {
            let count = 3 + (rng.random() < 0.5 ? 0 : 1);
            if (setup.ob_npc_generation_multiplier() > 1)
                count *= setup.ob_npc_generation_multiplier();

            for (let i = 0; i < count; i++)
            {
                let pick = this.find_member(house, year, rng, allfound);
                if (pick)
                {
                    allfound.push(pick);
                    found[house].push(pick);
                }
            }
        }
    }

    if (V.tradgreeks)
    {
        for (let [house, finds] of Object.entries(found))
            if (finds.length < 6)
            {
                V.tradgreeks = false;
                return setup.ob_houses.fill_houses(rng);
            }
    }

    for (let [house, finds] of Object.entries(found))
    {
        for (let student of finds)
        {
            this.place(student, house);
        }
        this.assign_president_and_rushchair(house, rng);
    }
}

setup.ob_houses.top_archetype = function(house)
{
    const houseinfo = this.houseinfo(house);
    return setup.ob_maxrelfreq(houseinfo.archetypes);
}

setup.ob_houses.assign_president_and_rushchair = function(house, rng = setup.ob_newRNG(V.seed + "houses"))
{
    const houseData = V.houses[house];
    if (!houseData || !Array.isArray(houseData.members) || houseData.members.length === 0) {
        console.warn(`Cannot assign roles: "${house}" has no members.`);
        return;
    }

    const members = rng.shuffle(houseData.members);
    const toparchetype = this.top_archetype(house);

    // Sort by desirability: higher year, matching archetype, not special
    const sorted = members.sort((a, b) => {
        const score = p => (
            setup.people.get_year(p) * 100 +
            (setup.people.archetype(p) === toparchetype ? 10 : 0) +
            (!setup.people.is_special(p) ? 1 : 0)
        );
        return score(b) - score(a);
    });

    houseData.president = houseData.president ?? sorted[0];
    houseData.rushchair = houseData.rushchair ?? sorted[1];
    console.log(`${house} president is ${houseData.president}`);
    console.log(`${house} rush chair is ${houseData.rushchair}`);
}

