setup.ob_houses.is_rush_week = function(day = V.day, month = V.month)
{
    if (typeof month == "string")
        month = setup.ob_time.months.indexOf(month);

    if (V.laterushday)
    {
        return V.gameday - V.laterushday <= 7;
    }
    else
    {
        return month == this.rushDay[0] && day >= this.rushDay[1] && day < this.rushDay[1] + 7;
    }
}

setup.ob_houses.is_rush_week_ending = function()
{
    if (V.laterushday)
    {
        return V.gameday >= V.laterushday + 7;
    }
    else
    {
        if (setup.ob_time.seasons[V.month] == "summer")
            return false;
        else if (V.month != this.rushDay[0])
            return true;
        else if (V.day >= this.rushDay[1] + 7)
            return true;
        else
            return false;
    }
}

setup.ob_houses.is_pledging_open = function()
{
    if (V.latepledgeday)
    {
        return V.gameday >= V.latepledgeday;
    }
    else
    {
        if (setup.ob_time.seasons[V.month] == "summer")
            return false; // not open in summer;
        else if (V.month != this.pledgeDay[0])
            return true; // always true if we're past the opening month
        else if (V.day >= this.pledgeDay[1])
            return true; // finally, also true if we're in the opening month and past the opening day
        else
            return false;
    }
}

