setup.ob_houses.set_task_flag = function(flag)
{
    if (!V.greekpledge || V.pchouse) return;
    if (!V.pledgetasks) V.pledgetasks = {};
    if (!V.pledgetasks[flag])
    {
        const tasks = setup.ob_houses.available_tasks(true)
        for (let i = 0; i < tasks.length; i++)
        {
            const task = setup.ob_houses.pledgeTasks[tasks[i]];
            if (!task.completedIf || task.completedIf.indexOf("$pledgetasks." + flag) < 0) continue;
            setup.add_notification("Pledge task completed: " + tasks[i]);
        }
        V.pledgetasks[flag] = true;
    }
}

