setup.ob_houses.create_oral_contest_teams = function(pcgiver)
{
    // create a giving and receiving team for an oral contest
    // accommodating the player's preferences plus npc preferences is uh harder than it might seem
    // or does that already sound like it's kinda hard? because it is
    // but let's do our best!!
    pcgiver = pcgiver == undefined ? State.random() < 0.5 : pcgiver;
    let givers = [];
    let receivers = [];

    let targetbit;
    if (pcgiver)
    {
        let pclikes = [];
        if (V.pcsexualprefs.includesAny(["female", "transgender male", "nonbinary amab"]))
            pclikes.push("vagina");
        if (V.pcsexualprefs.includesAny(["male", "transgender female", "nonbinary afab"]))
            pclikes.push("penis");

        targetbit = setup.ob_randomchoice(pclikes);
    }
    else if (V.pc.has_part("penis"))
    {
        targetbit = "penis";
    }
    else
    {
        targetbit = "vagina";
    }

    let givergender;
    if (pcgiver)
        givergender = [setup.ob_pcgender()];
    else
    {
        let genders = targetbit == "vagina" ? ["male", "transgender female", "nonbinary afab"] : ["female", "transgender male", "nonbinary amab"];
        let genderdist = [];
        for (let gender of genders)
            genderdist.push(gender, V.studentgenderdistribution[V.studentgenderdistribution.indexOf(gender) + 1]);
        givergender = [setup.ob_randomrelfreq(genderdist)];
    }

    let receivergender;
    if (!pcgiver)
        receivergender = [setup.ob_pcgender()];
    else
    {
        let genders = targetbit == "penis" ? ["male", "transgender female", "nonbinary afab"] : ["female", "transgender male", "nonbinary amab"];
        let genderdist = [];
        for (let gender of genders)
            genderdist.push(gender, V.studentgenderdistribution[V.studentgenderdistribution.indexOf(gender) + 1]);
        receivergender = [setup.ob_randomrelfreq(genderdist)];
    }

    let targetcount = 6;
    const students = setup.people.people_of_type("student");

    let allgenders = ["male", "transgender female", "nonbinary afab"].includes(givergender[0]) ? ["male", "transgender female", "nonbinary afab"] : ["female", "transgender male", "nonbinary amab"];
    givers = setup.ob_events.pick_several({gender: givergender, genderpref: receivergender, attractiontopc: !pcgiver, attractionfrompc: !pcgiver, inclinations: "casualsex", noinclinations: "nocasualsex", nopartneroropen: true}, targetcount, students);
    if (givers.length < targetcount)
    {
        givers = [...givers, ...setup.ob_events.pick_several({gender: allgenders, attractiontopc: !pcgiver, attractionfrompc: !pcgiver, noinclinations: "nocasualsex", nopartneroropen: true, exclude: givers}, targetcount - givers.length, students)];
    }
    if (givers.length < targetcount)
    {
        givers = [...givers, ...setup.ob_events.pick_several({gender: allgenders, attractionfrompc: !pcgiver, noinclinations: "nocasualsex", nopartneroropen: true, exclude: givers}, targetcount - givers.length, students)];
    }
    if (givers.length < targetcount)
    {
        givers = [...givers, ...setup.ob_events.pick_several({gender: allgenders, noinclinations: "nocasualsex", nopartneroropen: true, exclude: givers}, targetcount - givers.length, students)];
    }

    allgenders = ["male", "transgender female", "nonbinary afab"].includes(receivergender[0]) ? ["male", "transgender female", "nonbinary afab"] : ["female", "transgender male", "nonbinary amab"];
    receivers = setup.ob_events.pick_several({gender: receivergender, genderpref: givergender, attractiontopc: pcgiver, attractionfrompc: pcgiver, inclinations: "casualsex", noinclinations: "nocasualsex", nopartneroropen: true, exclude: givers}, targetcount, students);
    if (receivers.length < targetcount)
    {
        receivers = [...receivers, ...setup.ob_events.pick_several({gender: allgenders, attractiontopc: pcgiver, attractionfrompc: pcgiver, noinclinations: "nocasualsex", nopartneroropen: true, exclude: [...givers, ...receivers]}, targetcount - receivers.length, students)];
    }
    if (receivers.length < targetcount)
    {
        receivers = [...receivers, ...setup.ob_events.pick_several({gender: allgenders, attractionfrompc: pcgiver, noinclinations: "nocasualsex", nopartneroropen: true, exclude: [...givers, ...receivers]}, targetcount - receivers.length, students)];
    }
    if (receivers.length < targetcount)
    {
        receivers = [...receivers, ...setup.ob_events.pick_several({gender: allgenders, noinclinations: "nocasualsex", nopartneroropen: true, exclude: [...givers, ...receivers]}, targetcount - receivers.length, students)];
    }

    if (givers.length < 2 || receivers.length < 2)
        return [[], [], null];

    return [givers, receivers, targetbit];
}

