    let targetcount = 6;
    const students = setup.people.people_of_type("student");

    let givers = setup.ob_events.pick_several({part: "penis", gender: ["male"], genderpref: ["female"], inclinations: "casualsex", noinclinations: "nocasualsex", nopartneroropen: true}, targetcount - (State.random() < 0.1 ? 1 : 0), students);
    // we try to avoid sorting people solely by anatomy, but allow an occasional exception for inclusiveness
    if (givers.length < targetcount)
        givers = [...givers, ...setup.ob_events.pick_several({part: "penis", genderpref: ["female"], inclinations: "casualsex", noinclinations: "nocasualsex", exclude: givers, nopartneroropen: true}, targetcount - givers.length, students)];

    let receivers = setup.ob_events.pick_several({part: "vagina", gender: ["female"], genderpref: ["male"], inclinations: "casualsex", noinclinations: "nocasualsex", nopartneroropen: true, exclude: givers}, targetcount - (State.random() < 0.1 ? 1 : 0), students);
    if (receivers.length < targetcount)
        receivers = [...receivers, ...setup.ob_events.pick_several({part: "vagina", gender: ["female"], genderpref: ["male"], inclinations: "casualsex", noinclinations: "nocasualsex", nopartneroropen: true, exclude: [...givers, ...receivers]}, targetcount - receivers.length, students)];

    if (givers.length < 2 || receivers.length < 2)
        return [[], []];

    return [givers, receivers];
}

