setup.ob_houses.create_beer_pong_teams = function()
{
    let plrhouse = setup.ob_houses.house("PC") || setup.ob_randomchoice(Object.keys(this.db).filter(house => this.can_join(house)));
    let rivalhouse = setup.ob_randomchoice(Object.keys(this.db).filter(house => this.db[house].rivals.includes(plrhouse)));
    let pcgender = setup.ob_pcgender();
    const students = setup.people.people_of_type("student");

    const teamsize = 2;

    let team1 = setup.ob_events.pick_several({gender: [pcgender], genderpref: V.pcsexualprefs, house: plrhouse}, teamsize, students);
    if (team1.length < teamsize)
        team1 = [...team1, ...setup.ob_events.pick_several({genderpref: V.pcsexualprefs, house: plrhouse, exclude: team1}, teamsize - team1.length, students)];
    if (team1.length < teamsize)
        team1 = [...team1, ...setup.ob_events.pick_several({house: plrhouse, exclude: team1}, teamsize - team1.length, students)];
    if (team1.length < teamsize)
        team1 = [...team1, ...setup.ob_events.pick_several({exclude: team1}, teamsize - team1.length, students)];

    let team2 = setup.ob_events.pick_several({attractiontopc: true, attractionfrompc: true, house: rivalhouse, exclude: team1}, teamsize, students);
    if (team2.length < teamsize)
        team2 = [...team2, ...setup.ob_events.pick_several({attractionfrompc: true, house: rivalhouse, exclude: [...team1, ...team2]}, teamsize - team2.length, students)];
    if (team2.length < teamsize)
        team2 = [...team2, ...setup.ob_events.pick_several({attractiontopc: true, attractionfrompc: true, exclude: [...team1, ...team2]}, teamsize - team2.length, students)];
    if (team2.length < teamsize)
        team2 = [...team2, ...setup.ob_events.pick_several({attractionfrompc: true, exclude: [...team1, ...team2]}, teamsize - team2.length, students)];
    if (team2.length < teamsize)
        team2 = [...team2, ...setup.ob_events.pick_several({exclude: [...team1, ...team2]}, teamsize - team2.length, students)];

    return [team1, team2, plrhouse, rivalhouse];
}

setup.ob_houses.beerpong_shots_available = function(cups)
{
    let retval = {};
    const shottypes = {
        "front cup": setup.ob_houses.beerpong_cups_in_row("front cup"),
        "second row": setup.ob_houses.beerpong_cups_in_row("second row"),
        "third row": setup.ob_houses.beerpong_cups_in_row("third row"),
        "back row": setup.ob_houses.beerpong_cups_in_row('back row'),
    };

    for (const [shot, shotcups] of Object.entries(shottypes))
    {
        let actual = shotcups.filter(i => cups[i] && !this.beerpong_cup_isolated(cups, i));
        if (actual.length > 0)
            retval[shot] = actual;
    }

    let isolated = cups
        .map((present, i) => (present && this.beerpong_cup_isolated(cups, i)) ? i : null)
        .filter(i => i != null);
    if (isolated.length > 0)
        retval["isolated cup"] = isolated;

    return retval;
}

setup.ob_houses.beerpong_cup_neighbors = function(i)
{
    const neighbors = {
        0: [1, 2],
        1: [0, 2, 3, 4],
        2: [0, 1, 4, 5],
        3: [1, 4, 6, 7],
        4: [1, 2, 3, 5, 7, 8],
        5: [2, 4, 8, 9],
        6: [3, 4, 7],
        7: [3, 4, 6, 8],
        8: [4, 5, 7, 9],
        9: [5, 8],
    };
    return neighbors[i];
}

setup.ob_houses.beerpong_cups_in_row = function(row)
{
    switch (row)
    {
        case "front cup":
            return [0];
        case "second row":
            return [1, 2];
        case "third row":
            return [3, 4, 5];
        case "back row":
            return [6, 7, 8, 9];
        default:
            return [];
    }
}

setup.ob_houses.beerpong_cups_left_in_row = function(row, cups)
{
    return this.beerpong_cups_in_row(row).filter(i => cups[i]);
}

setup.ob_houses.beerpong_cup_isolated = function(cups, i)
{
    let neighbors = this.beerpong_cup_neighbors(i);
    return neighbors.every(i => !cups[i]);
}

setup.ob_houses.beerpong_shooting_skill = function(npc)
{
    let hand = setup.people.skill_level(npc, "Hand");
    let phys = setup.people.skill_level(npc, "Physical");
    return Math.round((hand + hand + phys) / 3);
}

setup.ob_houses.beerpong_cup_neighbors_left = function(cups, i)
{
    return this.beerpong_cup_neighbors(i).filter(i => cups[i]);
}

setup.ob_houses.beerpong_multi_neighbors_left = function(cups, is)
{
    let retval = [];
    for (let i of is)
    {
        retval = [...retval, ...this.beerpong_cup_neighbors_left(cups, i)];
    }
    return [...new Set(retval)];
}

setup.ob_houses.beerpong_shot_difficulty = function(shottype)
{
    return {
        "front cup": 3,
        "second row": 4,
        "third row": 5,
        "back row": 6,
        "isolated cup": 8,
    }[shottype];
}

setup.ob_houses.beerpong_pick_shot = function(npc, cups)
{
    let skill = this.beerpong_shooting_skill(npc) + (setup.people.has_any_inclination(npc, "arrogant") ? 2 : 0);
    let shots = this.beerpong_shots_available(cups);

    let shotdiffs = [];

    for (let [shot, cupsleft] of Object.entries(shots))
    {
        if (cupsleft.length == 0) continue;

        let diff = this.beerpong_shot_difficulty(shot);

        let neighborcount = this.beerpong_multi_neighbors_left(cups, cupsleft).length;

        diff -= Math.min(neighborcount, 3);

        let score = Math.abs(skill - diff); // why abs, you might ask? we don't want NPCs to just always take the easiest shot -- more skilled NPCs should favor shots closer to their skill level. they want to win as a team, so more skilled NPCs will take the more difficult shots

        shotdiffs.push([shot, score]);
    }
    shotdiffs = setup.ob_shuffle(shotdiffs);
    shotdiffs.sort((a, b) => a[1] - b[1]);

    return shotdiffs[0][0];
}

setup.ob_houses.beerpong_make_shot = function(npc, shot, cups)
{
    let skill = this.beerpong_shooting_skill(npc);
    let diff = this.beerpong_shot_difficulty(shot);

    let possiblecups, targetcup, neighbors;
    if (shot == "isolated cup")
    {
        possiblecups = this.beerpong_shots_available(cups)["isolated cup"];
        targetcup = setup.ob_randomchoice(possiblecups);
        neighbors = [];
    }
    else
    {
        possiblecups = this.beerpong_cups_left_in_row(shot, cups);
        targetcup = setup.ob_randomchoice(possiblecups);
        neighbors = this.beerpong_cup_neighbors_left(cups, targetcup);
    }
    let result = ["miss", -1];

    // some chance of totally random success, else games might just never end
    if (setup.people.skillcheck(npc, skill, diff) || (shot == "isolated cup" && State.random() < 0.1))
    {
        result[0] = "hit";
        result[1] = targetcup;
    }
    else if (State.random() < neighbors.length * 0.15)
    {
        if (neighbors.length > 0)
        {
            result[1] = setup.ob_randomchoice(neighbors);
        }
    }

    return result;
}

setup.ob_houses.beerpong_remove_cup = function(cups, i)
