setup.ob_houses.beerpong_obj = function(npc)
{
    if (V.pc.equals(npc))
        return V.pc;
    else
    {
        for (let npcobj of [V.npcexp1, V.npcexp2, V.npcexp3, V.npcexp4])
        {
            if (npcobj && npcobj.equals(npc))
                return npcobj;
        }
    }
}

setup.ob_houses.find_copledgers = function(house, count = 3, forpc = false)
{
    let copledgers = [];
    let allcopledgers = [];

    for (let [house, houseinfo] of Object.entries(V.houses))
    {
        if (houseinfo.pledgers)
            allcopledgers = [...allcopledgers, ...houseinfo.pledgers];
    }

    if (forpc)
    {
        let bff = V.niches["The Best Friend"];
        if (this.can_join(house, bff))
            copledgers.push(bff);
    }

    let tries = 0;
    while (copledgers.length < count && tries < count * 2)
    {
        let rng = setup.ob_newRNG();
        let pledger = this.find_member(house, setup.ob_randomchoice([1, 1, 2]), rng, [...allcopledgers, ...copledgers]);
        if (pledger)
            copledgers.push(pledger);
        tries++;
    }

    return copledgers;
}

setup.ob_houses.set_pledgers = function(plrhouse)
{
    // set some NPCs also pledging, to be called when the player pledges
    let copledgers = this.find_copledgers(plrhouse, 3, true);
    V.houses[plrhouse].pledgers = copledgers;

    for (let house of Object.keys(V.houses))
    {
        if (house == plrhouse) continue;
        let pledgers = this.find_copledgers(house);
        V.houses[house].pledgers = pledgers;
    }
}

