setup.ob_houses.sort_members_for_initiation = function(house)
{
    let members = setup.ob_shuffle(this.people_of_houses(house));
    let pres = this.get_president(house);
    let rush = this.get_rushchair(house);

    let i = members.indexOf(rush);
    members.deleteAt(i);
    members.push(rush);

    i = members.indexOf(pres);
    members.deleteAt(i);
    members.push(pres);

    return members;
}

