setup.ob_houses.pick_attracted_rival_house = function(house)
{
    const rivals = setup.ob_shuffle(this.houseinfo(house).rivals);
    if (!V.tradgreeks)
        return rivals[0];

    for (let rival of rivals)
    {
        const genders = this.houseinfo(rival).genders;
        if (genders.filter(g => !g.match("nonbinary")).includesAny(V.pcsexualprefs))
            // we discount nonbinary initially because otherwise on default settings every house would be equally valid
            // making this just a random pick, meaning a hetero player in a frat would be targeting another frat half the time
            return rival;
        else if (genders.includesAny(V.pcsexualprefs))
            return rival;
    }

    return rivals[0];
}

setup.ob_houses.get_raid_team = function(house)
{
    let retval = [];
    if (house == V.greekpledge || house == V.pchouse)
    {
        retval.push(V.niches["The Greek Mentor"]);
    }

    if (V.greekpledge == house)
    {
        retval = [...retval, ...this.get_copledgers()];
    }

    let raiders = setup.ob_events.pick_several({}, 7, setup.ob_houses.people_of_houses([house]));
    for (let raider of setup.ob_shuffle(raiders))
    {
        if (retval.length >= 7)
            break;
        else
            retval.push(raider);
    }

    return retval;
}

setup.ob_houses.progress_raid = function(minutes)
{
    const progressperminute = 10;
    const stealthperminute = 5;

    V.greekunderwearraid.timetaken += minutes;

    if (V.greekunderwearraid.backdoorbroken)
    {
        V.greekunderwearraid.success += (progressperminute * minutes);
    }
    V.greekunderwearraid.stealth -= (stealthperminute * minutes);
}

setup.ob_houses.upgrade_tier = function(house, upgrade)
{
    let upgradetiers = this.houseinfo(house).upgrades;
    for (let i = 0; i < upgradetiers.length; i++)
        if (upgradetiers[i].includes(upgrade))
            return i + 1;
}

setup.ob_houses.highest_purchased_tier = function(house)
{
    if (!V.greekhouseupgrades || V.greekhouseupgrades.length == 0) return 0;
    let max = 0;
    for (let upgrade of V.greekhouseupgrades)
        if (this.upgrade_tier(house, upgrade) > max)
            max = this.upgrade_tier(house, upgrade);
    return max;
}

setup.ob_houses.upgrades_purchased_on_tier = function(house, tier)
{
    if (!V.greekhouseupgrades || V.greekhouseupgrades.length == 0) return [];
    let retval = [];
    for (let upgrade of V.greekhouseupgrades)
        if (this.upgrade_tier(house, upgrade) == tier)
            retval.push(upgrade);
    return retval;
}

setup.ob_houses.has_upgrade = function(upgrade)
{
    if (!V.greekhouseupgrades || V.greekhouseupgrades.length == 0) return false;
    return V.greekhouseupgrades.includes(upgrade);
}

setup.ob_houses.add_renown = function(amt)
{
    if (!V.pchouse) return;

    if (!V.greekrenown || !Number.isFinite(V.greekrenown))
        V.greekrenown = 0;

    if (!Number.isFinite(V.optgreekrenownmult))
        V.optgreekrenownmult = 1;

    if (!Number.isFinite(amt))
    {
        console.warn("Invalid Greek renown amount added");
        return V.greekrenown;
    }

    V.greekrenown = Math.clamp(V.greekrenown + (amt * V.optgreekrenownmult), 0, 1000);
    return V.greekrenown;
}

setup.ob_houses.max_upgrade_points = function()
{
    if (!V.greekrenown)
        return 0;

    if (V.greekrenown >= 1000)
        return 10;
    else if (V.greekrenown >= 800)
        return 9;
    else if (V.greekrenown >= 700)
        return 8;
    else if (V.greekrenown >= 600)
        return 7;
    else if (V.greekrenown >= 500)
        return 6;
    else if (V.greekrenown >= 400)
        return 5;
    else if (V.greekrenown >= 300)
        return 4;
    else if (V.greekrenown >= 200)
        return 3;
    else if (V.greekrenown >= 100)
        return 2;
    else if (V.greekrenown >= 50)
        return 1;
    else
        return 0;
}

setup.ob_houses.upgrade_points_in_use = function()
{
    return V.greekhouseupgrades ? V.greekhouseupgrades.length : 0;
}

setup.ob_houses.restock_free_basic_ingredients = function()
