// #region validation

setup.ob_housing.validate = function()
{
    for (const [plan, planinfo] of Object.entries(setup.ob_housing.plans))
    {
        let allrooms = Object.keys(planinfo.rooms);
        for (const room of allrooms)
        {
            const roominfo = planinfo.rooms[room];
            if (!(roominfo.class in setup.ob_housing.roomClasses))
                console.error(`${plan} > ${room} set to invalid room class`);
            for (const exit of roominfo.exits)
            {
                if (!allrooms.includes(exit))
                    console.error(`${plan} > ${room} has invalid exit: ${exit}`);
                else if (!planinfo.rooms[exit].exits.includes(room))
                    console.error(`${plan} > ${room} > ${exit} does not have reciprocal exit`);
            }
        }
    }

    for (const [roomclass, classinfo] of Object.entries(setup.ob_housing.roomClasses))
    {
        if (!(classinfo.roomtype in setup.ob_roomTypes.db))
            console.error(`Room class ${roomclass} set to invalid roomtype`);
    }
}
setTimeout(setup.ob_housing.validate, 0);

// #region methods

setup.ob_housing.get_room_info = function(plan, roomid)
{
    // grab object for a specific room id from a specific plan

    const rooms = this.plans[plan].rooms;
    return rooms[roomid];
}

setup.ob_housing.npc_housing_plan = function(npc)
{
    // from an npc name, determine the housing plan they'll live in

    let name1 = setup.people.get_name(npc);

    if (setup.ob_relationships.is_married(npc))
    {
        let name2 = setup.people.get_name(setup.ob_relationships.partner(npc));

        if (name2 == [name1, name2].sort()[0])
        {
            // use spouse's plan
            return setup.ob_housing.npc_housing_plan(name2);
        }
    }

    let lives = setup.people.lives(npc);
    let rng = setup.ob_newRNG(`house_${name1}`);

    let budget = setup.people.wealth_to_income(setup.people.get_wealth(name1)) * 0.5;
    // todo: algo to determine whether partners live together (altered by simulation system)
    for (let partner of setup.ob_relationships.all_partners(name1))
        if (partner != "PC")
            budget += setup.people.wealth_to_income(setup.people.get_wealth(partner)) * 0.5;

    budget = Math.round(budget);

    const npctype = setup.people.get_type(npc);
    const picklist = [];
    const validplans = Object.keys(this.plans)
        .filter(plan => {
            const planinfo = this.plans[plan];
            if (!planinfo.NPCTypes || !planinfo.NPCTypes.includes(npctype)) return false;
            return planinfo.tags.includes(lives);
        });
    validplans.forEach(plan => {
            const planinfo = this.plans[plan];
            const ratio = planinfo.cost / budget;
            let freq = 0;
            if (ratio > 1.1)
                return;
            else if (ratio < 0.35)
                return;
            else
                freq = Math.round(100 * Math.pow(ratio, 2));

            if (freq > 0)
                picklist.push(plan, freq);
        });

    if (picklist.length == 0)
    {
        // probably here because we couldn't afford any
        const cheaplist = [];
        validplans.forEach(plan => {
                const planinfo = this.plans[plan];
                const ratio = planinfo.cost / budget;
                cheaplist.push([plan, ratio]);
            });

        picklist.push(cheaplist.sort((a, b) => a[1] - b[1])[0][0], 100);
    }

    return rng.randomrelfreq(picklist);
}

setup.ob_housing.find_description = function(building, roomclass, othertags = [])
{
    // determine which description to use from setup.ob_housing.descriptions
    // entry with the most matching tags wins, so we can be specific but also have generic fallbacks

    let roomtags = [building, roomclass, ...othertags];
    let possibles = [];
    for (const [desc, descinfo] of Object.entries(this.descriptions))
    {
        let matchingtags = 0;
        descinfo.tags.forEach(tag => {
            if (roomtags.includes(tag))
                matchingtags++;
        });

        if (matchingtags > 0)
            possibles.push([desc, matchingtags]);
    }

    if (possibles.length == 0) return;

    possibles.sort((a, b) => b[1] - a[1]);
    return possibles[0][0];
}

setup.ob_housing.get_room_class = function(plan, roomid)
