setup.ob_housing.set_unit_property = function(key, value)
{
    const hkey = V.housing.key;
    return this.set_unit_property_raw(hkey, key, value);
}

setup.ob_housing.clear_unit_property_raw = function(hkey, key)
{
    const unitinfo = V.pchousing[hkey];

    return delete unitinfo.properties[key];
}
setup.ob_housing.clear_unit_property = function(key)
{
    const hkey = V.housing.key;
    return this.clear_unit_property_raw(hkey, key);
}

setup.ob_housing.get_unit_property_raw = function(hkey, key)
{
    const unitinfo = V.pchousing[hkey];

    return unitinfo.properties[key];
}
setup.ob_housing.get_unit_property = function(key)
{
    const hkey = V.housing.key;
    return this.get_unit_property_raw(hkey, key);
}

setup.ob_housing.restricted_actions = function()
{
    if (!this.is_housing())
        return [];
    else
        return V.restrictedHousingActions || [];
}

setup.ob_housing.add_restricted_action = function(action)
{
    if (!V.restrictedHousingActions)
        V.restrictedHousingActions = [];
    return V.restrictedHousingActions.push(action);
}

setup.ob_housing.is_restricted_action = function(action)
{
    if (!this.is_housing() || !V.restrictedHousingActions)
        return false;
    else
        return V.restrictedHousingActions.includes(action);
}

setup.ob_housing.infer_housing_exit = function()
{
    // get the exterior location of our current housing
    if (V.housing)
        return this.buildings[V.housing.building].exteriorLocation;
    else if (V.lasthousingexit)
        return V.lasthousingexit;
    else
    {
        for (let housekey of Object.keys(V.pchousing))
            if (V.pchousing[housekey].temporary)
                return this.buildings[V.pchousing[housekey].building].exteriorLocation;

        for (let housekey of Object.keys(V.pchousing))
            if (V.pchousing[housekey].owner == "PC")
                return this.buildings[V.pchousing[housekey].building].exteriorLocation;

        return "HannaRdN";
    }
}

setup.ob_housing.unit_owner_raw = function(hkey)
{
    return V.pchousing[hkey].owner;
}
setup.ob_housing.unit_owner = function()
{
    const hkey = V.housing.key;
    return this.unit_owner_raw(hkey);
}

setup.ob_housing.room_owner_raw = function(hkey, roomid)
{
    return this.get_room_property_raw(hkey, roomid, "owner");
}

setup.ob_housing.room_owners = function(hkey = V.housing.key, roomid = V.housing.roomID)
{
    // get all owners of this room
    // (if room is not private, this means all housing unit owners)
    // (otherwise, just individual room owners)

    if (!this.is_ownable_room(hkey, roomid))
        return [...new Set([this.unit_owner_raw(hkey), ...(this.get_roommates_raw(hkey) || [])])];
    else
        return this.room_owner_raw(hkey, roomid) || [this.unit_owner_raw(hkey)];
}

setup.ob_housing.is_ownable_room = function(hkey = V.housing.key, roomid = V.housing.roomID)
{
    const classinfo = this.roomClasses[this.room_class_raw(hkey, roomid)];
    return classinfo.hasOwner || false;
}

setup.ob_housing.room_player_owned = function()
{
    return this.room_owners().includes("PC");
}

setup.ob_housing.nonroommate_access = function()
{
    if (!V.housing) return false;
    const hinfo = V.pchousing[V.housing.key];
    return !V.pc.equals(hinfo.owner) && setup.people.residence_access(hinfo.owner) && !this.is_roommate(hinfo.owner);
}

setup.ob_housing.add_room_owner = function(hkey, roomid, owner)
{
    let owners = this.room_owner_raw(hkey, roomid) || [];
    if (!owners.includes(owner)) owners.push(owner);
    return this.set_room_property_raw(hkey, roomid, "owner", owners);
}

setup.ob_housing.remove_room_owner = function(hkey, roomid, owner)
{
    let owners = this.room_owner_raw(hkey, roomid) || [];
    owners.delete(owner);
    if (owners.length == 0)
        return this.clear_room_property_raw(hkey, roomid, "owner");
    else
        return this.set_room_property_raw(hkey, roomid, "owner", owners);
}

setup.ob_housing.get_roommates_raw = function(hkey)
{
    return this.get_unit_property_raw(hkey, "roommates");
}
setup.ob_housing.get_roommates = function()
{
    const hkey = V.housing.key;
    return this.get_roommates_raw(hkey) || [];
}
setup.ob_housing.get_roommates_actual = function()
{
    // return people the pc lives with
    // (codewide, roommates are people besides the owner who have access to the place)
    // (so if the pc is living in npc-owned housing, the pc is a roommate while the npc owner is not)
    // (but never fear, this method exists to convert these situations into the actual concept of roommates)

    const hkey = V.housing.key;
    const owner = this.unit_owner();
    if (V.pc.equals(owner))
        return this.get_roommates();
    else
    {
        let roommates = this.get_roommates();
        roommates.delete("PC");
        roommates.unshift(owner);
        return roommates;
    }
}

setup.ob_housing.add_roommate = function(hkey, roomid, name)
{
    // add a roommate (as both the owner of a specific bedroom and one of the roommates assigned to the unit)
    // roomid should be their bedroom!
    name = V.pc.equals(name) ? "PC" : setup.people.get_name(name);

    let roommates = this.get_roommates_raw(hkey) || [];
    if (!roommates.includes(name))
        roommates.push(name);
    this.set_unit_property_raw(hkey, "roommates", roommates);

    let rowners = this.room_owner_raw(hkey, roomid) || [];
    if (!rowners.includes(name))
        rowners.push(name);
    this.set_room_property_raw(hkey, roomid, "owner", rowners);
}

setup.ob_housing.remove_roommate = function(hkey, roomid, name)
{
    // roomid should be their bedroom!
    name = V.pc.equals(name) ? "PC" : setup.people.get_name(name);

    let roommates = this.get_roommates_raw(hkey) || [];
    roommates.delete(name);
    if (roommates.length == 0)
        this.clear_unit_property_raw(hkey, "roommates");
    else
        this.set_unit_property_raw(hkey, "roommates", roommates);

    let rowners = this.room_owner_raw(hkey, roomid) || [];
    rowners.delete(name);
    if (rowners.length == 0)
        this.clear_room_property_raw(hkey, roomid, "owner");
    else
        this.set_room_property_raw(hkey, roomid, "owner", rowners);

    if (!this.is_roommate(name))
    {
        let pdata = setup.people.get_person(name);
        delete pdata.playerOwedRent;
    }
}

setup.ob_housing.all_roomids = function(hkey)
{
    // get all roomids in a specific housing unit (via looking up its plan)
    const unitinfo = V.pchousing[hkey];
    const planinfo = this.plans[unitinfo.plan];
    return Object.keys(planinfo.rooms);
}

setup.ob_housing.clear_room_owners = function(hkey)
{
    // clear all npc room owners in preparation for rearranging them
    const rooms = this.all_roomids(hkey);
    for (const roomid of rooms)
    {
        let owners = this.room_owner_raw(hkey, roomid) || [];
        if (owners.includes("PC"))
            this.set_room_property_raw(hkey, roomid, "owner", ["PC"]);
        else
            this.clear_room_property_raw(hkey, roomid, "owner");
    }
}

setup.ob_housing.is_room_vacant = function(hkey, roomid)
{
    // does the given room have any owners?
    const owners = this.room_owner_raw(hkey, roomid) || [];
    return owners.length == 0;
}

setup.ob_housing.are_room_owners_partners_of = function(hkey, roomid, npc)
{
    // are all owners of this room a romantic partner of the given npc?
    const owners = this.room_owner_raw(hkey, roomid) || [];
    if (owners.length == 0) return false;
    return owners.every(owner => {
        if (V.pc.equals(npc))
            return setup.ob_relationships.relationship_type_with(owner) == "romantic";
        else if (V.pc.equals(owner))
            return setup.ob_relationships.relationship_type_with(npc) == "romantic";
        else
            return setup.ob_nPCSimulation.get_relationship_type(npc, owner) == "romantic";
    });
}

setup.ob_housing.find_player_bedroom = function(hkey)
{
    // find the bedroom the pc has claimed

    return this.bedroom_for_npc(hkey, "PC");
}

setup.ob_housing.reserved_bedroom_for_pc = function(hkey)
{
    // find the bedroom the pc has claimed or, if none...
    // ...if pc housing, reserve the first empty bedroom for them
    // ...if npc housing, out of luck
    let current = this.find_player_bedroom(hkey);
    if (current) return current;

    if (V.pchousing[hkey].owner != "PC") return;

    const roomids = this.all_roomids(hkey);
    for (const roomid of roomids)
    {
        if (this.room_class_raw(hkey, roomid) == "bedroom")
        {
            let owners = this.room_owner_raw(hkey, roomid);
            if (!owners || owners.length == 0)
                return roomid;
        }
    }
}

setup.ob_housing.find_bedroom_for_npc = function(hkey, npc)
{
    // find a bedroom for the given npc in the given unit with these priorities:
    // 1) if partner of the pc, return the pc's room
    // 2) if partner of an npc who already has a room, return that room
    // 3) return the first available room

    if (setup.ob_relationships.all_partners(npc).includes("PC"))
    {
        let pcroom = this.reserved_bedroom_for_pc(hkey);
        if (pcroom)
            return pcroom;
    }

    const bedrooms = this.all_roomids(hkey).filter(rid => this.room_class_raw(hkey, rid) == "bedroom");
    for (const roomid of bedrooms)
        if (this.are_room_owners_partners_of(hkey, roomid, npc))
            return roomid;

    for (const roomid of bedrooms)
        if (this.is_room_vacant(hkey, roomid) && this.reserved_bedroom_for_pc(hkey) != roomid)
            return roomid;
}

setup.ob_housing.assign_pc_to_their_bedroom = function(hkey)
{
    // the pc gets a default reserved bedroom, but it's easier to keep things working smoothly if we make an explicit assignment

    if (!this.bedroom_for_npc(hkey, "PC"))
    {
        let roomid = this.reserved_bedroom_for_pc(hkey);
        if (roomid)
            this.add_room_owner(hkey, roomid, "PC");
    }
}

setup.ob_housing.maybe_rearrange_player_bedroom = function(hkey, newbedroom)
{
    // see if the player is sleeping in an available bedroom yet has a different one assigned, in which case we should reassign them to this one
    let currentbedroom = this.bedroom_for_npc(hkey, "PC");
    if (!currentbedroom || currentbedroom == newbedroom) return;

    let newroomowners = this.room_owner_raw(hkey, newbedroom);
    if (!Array.isArray(newroomowners) || newroomowners.length == 0)
    {
        let currentroomowners = [...this.room_owner_raw(hkey, currentbedroom)];
        this.clear_room_property_raw(hkey, currentbedroom, "owner");
        this.set_room_property_raw(hkey, newbedroom, "owner", currentroomowners);
    }
}

setup.ob_housing.rearrange_roommates = function(hkey)
{
    // clear and re-sort a unit's roommates into bedrooms
    // to be used when relationships change

    const roommates = this.get_roommates_raw(hkey) || [];

    let pcbedroom = this.bedroom_for_npc(hkey, "PC");

    this.clear_room_owners(hkey);

    if (pcbedroom)
        this.add_room_owner(hkey, pcbedroom, "PC");
    else
        this.assign_pc_to_their_bedroom(hkey);

    const unplaced = [];

    for (const npc of roommates)
    {
        const room = this.find_bedroom_for_npc(hkey, npc);
        if (room)
            this.add_roommate(hkey, room, npc);
        else
            unplaced.push(npc);
    }

    return unplaced;
}

setup.ob_housing.rearrange_roommates_for = function(npc)
{
    // rearrange roommates in all player-owned housing involving the given npc
    if (!V.pchousing) return;
    npc = setup.people.get_name(npc);
    const hkeys = Object.keys(V.pchousing).filter(hkey => V.pchousing[hkey].owner == "PC" && this.get_roommates_raw(hkey)?.includes(npc));
    for (const hkey of hkeys)
        this.rearrange_roommates(hkey);
}

setup.ob_housing.unplaced_roommates = function(hkey)
{
    // get all roommates that lack a bedroom

    const roommates = this.get_roommates_raw(hkey) || [];
    const unplaced = [];

    for (const rm of roommates)
        if (!this.bedroom_for_npc(hkey, rm))
            unplaced.push(rm);

    return unplaced;
}

setup.ob_housing.npc_sleeping_location = function(hkey, npc)
{
    // usually their bedroom, but the living room if they lack one

    let bedroom = this.bedroom_for_npc(hkey, npc);
    if (bedroom) return bedroom;

    const roomids = this.all_roomids(hkey);
    for (const roomid of roomids)
        if (["living room", "entertainment room"].includes(this.room_class_raw(hkey, roomid)))
            return roomid;
}

setup.ob_housing.move_out_of_pc_housing = function(npc)
{
    // move this npc out of pc housing they might inhabit
    if (!V.pchousing) return;
    npc = setup.people.get_name(npc);
    const hkeys = Object.keys(V.pchousing).filter(hkey => V.pchousing[hkey].owner == "PC" && this.get_roommates_raw(hkey)?.includes(npc));
    for (const hkey of hkeys)
        this.remove_npc_from_housing_unit(hkey, npc);
}

setup.ob_housing.add_npc_to_housing_unit = function(hkey, npc)
{
    // top-level method: add npc to a housing unit owned by the pc, give them a room, and set everything
    // return success or failure

    this.assign_pc_to_their_bedroom(hkey);

    npc = setup.people.get_name(npc);

    let room = this.find_bedroom_for_npc(hkey, npc);
    if (!room) return false;

    this.add_roommate(hkey, room, npc);

    const building = V.pchousing[hkey].building;
    const housingtype = this.buildings[building].placeType;
    let pdata = setup.people.get_person(npc);
    pdata.residenceType = housingtype;
    setup.people.rescind_residence_access(npc);

    /*
    for (const [hkey, hinfo] of Object.entries(V.pchousing))
        if (hinfo.owner == npc)
            hinfo.temporary = true;

    perhaps not necessarily do this... we'll see
    (also we need to pack up the player's belongings if we do)
    */

    return true;
}

setup.ob_housing.remove_npc_from_housing_unit = function(hkey, npc)
{
    // remove an npc from a specific housing unit and return them to default housing behavior

    npc = setup.people.get_name(npc);

    const roomids = this.all_roomids(hkey);
    for (const roomid of roomids)
        if (this.room_class_raw(hkey, roomid) == "bedroom" && this.room_owner_raw(hkey, roomid)?.includes(npc))
            this.remove_roommate(hkey, roomid, npc);

    let pdata = setup.people.get_person(npc);
    delete pdata.residenceType;

    if (!this.is_roommate(npc))
    {
        delete pdata.playerOwedRent;
    }

    return true;
}

setup.ob_housing.evict_roommate = function(npc)
{
    // find the player-owned unit this npc is in and evict them

    npc = setup.people.get_name(npc);

    const hkey = Object.keys(V.pchousing).find(unit =>
        V.pchousing[unit].owner == "PC" && this.get_roommates_raw(unit)?.includes(npc)
    )

    if (hkey)
        return this.remove_npc_from_housing_unit(hkey, npc);
    else
        return false;
}

setup.ob_housing.is_pc_roommate = function(hkey)
{
    return this.get_roommates_raw(hkey)?.includes("PC");
}

setup.ob_housing.is_npc_roommate = function(hkey)
{
    return this.get_roommates_raw(hkey)?.some(r => r in V.people);
}

setup.ob_housing.bedroom_for_npc = function(hkey, npc)
{
    // find the first bedroom this npc owns
    npc = V.pc.equals(npc) ? "PC" : setup.people.get_name(npc);
    const houseinfo = V.pchousing[hkey];
    const planinfo = setup.ob_housing.plans[houseinfo.plan];
    for (const [roomid, roominfo] of Object.entries(planinfo.rooms))
        if (this.room_class_raw(hkey, roomid) == "bedroom" && this.room_owner_raw(hkey, roomid)?.includes(npc))
            return roomid;
}

setup.ob_housing.bathroom_for_npc = function(hkey, npc)
{
    // find the bathroom this npc prefers
    npc = V.pc.equals(npc) ? "PC" : setup.people.get_name(npc);
    const houseinfo = V.pchousing[hkey];
    const planinfo = setup.ob_housing.plans[houseinfo.plan];

    const bedroom = this.bedroom_for_npc(hkey, npc);
    if (bedroom)
    {
        const exits = this.get_room_info(houseinfo.plan, bedroom).exits;
        let bathroom = exits.find(rid => this.room_class_raw(hkey, rid) == "bathroom");
        if (bathroom) return bathroom;
    }

    const sharedbathroom = this.all_roomids(hkey).find(rid => this.room_class_raw(hkey, rid) == "bathroom" && !planinfo.rooms[rid].exits.some(exit => this.room_class_raw(hkey, exit) == "bedroom"));
    if (sharedbathroom) return sharedbathroom;

    for (const [roomid, roominfo] of Object.entries(planinfo.rooms))
        if (this.room_class_raw(hkey, roomid) == "bathroom")
            return roomid;
}

setup.ob_housing.bathroom_for_pc = function(hkey)
{
    // find the most natural to use bathroom for the pc
    return this.bathroom_for_npc(hkey, "PC");
}

setup.ob_housing.first_room_with_flag = function(hkey, flag)
{
    const houseinfo = V.pchousing[hkey];
    const planinfo = setup.ob_housing.plans[houseinfo.plan];
    if (!Array.isArray(flag)) flag = [flag];

    for (const [roomid, roominfo] of Object.entries(planinfo.rooms))
    {
        let owners = this.room_owners(hkey, roomid);
        let owner = owners.includes("PC") ? "PC" : owners[0];
        const flags = this.get_flags(hkey, roomid, owner);
        if (flags.includesAny(flag))
            return roomid;
    }
}

setup.ob_housing.first_room_of_class = function(hkey, roomclass)
{
    const roomids = this.all_roomids(hkey);
    return roomids.find(roomid => this.room_class_raw(hkey, roomid) == roomclass);
}

setup.ob_housing.roommate_doing = function(npc)
{
    // return an activity string for what this person is doing

    const pinfo = setup.people.get_person(npc);
    const rng = setup.ob_newRNG(`${setup.people.get_name(npc)}_${setup.ob_time.nearest_x_minute(30)}`);
    const slotinfo = setup.people.schedule_slot(npc);
    const slot = slotinfo?.location;
    const now = (V.hour * 60) + V.minute;
    const rawtime = slotinfo
        ? (slotinfo.hour * 60) + (slotinfo.minute ?? 0)
        : (V.hour * 60);
    const minutesintosegment = now - rawtime;

    if (slot == "home" || slot == "free time")
    {
        const actions = [];
        if (setup.people.get_type(npc) == "student" && setup.School.classes_tomorrow() && V.hour >= 18 && V.hour <= 20)
        {
            const major = setup.people.get_major(npc);
            switch (major)
            {
                case "history":
                {
                    actions.push("skimming through a wiki");
                    actions.push("reading an article");
                    break;
                }
                case "psychology":
                {
                    actions.push("reading a book");
                    actions.push("reading an article");
                    break;
                }
                case "science":
                {
                    actions.push("drawing some sort of chart");
                    actions.push("reading an article");
                    break;
                }
                case "business":
                {
                    actions.push("staring at a spreadsheet");
                    actions.push("reading an article");
                    break;
                }
                case "english":
                {
                    actions.push("reading a book");
                    actions.push("writing a paper");
                    break;
                }
                case "math":
                {
                    actions.push("drawing some sort of chart");
                    actions.push("staring at a spreadsheet");
                    break;
                }
                case "compsci":
                {
                    actions.push("writing some code");
                    actions.push("staring at a spreadsheet");
                    break;
                }
                case "art":
                {
                    actions.push("sketching something");
                    actions.push("watching an art stream");
                    break;
                }
                case "sports management":
                {
                    actions.push("looking over a playbook");
                    actions.push("constructing a stadium model");
                    break;
                }
            }
            actions.push("studying");
            actions.push("doing homework");
        }
        else if (setup.ob_time.is_weekend() && V.hour < 8)
            return minutesintosegment <= 30 ? "getting ready for bed" : "sleeping";
        else if (!setup.ob_time.is_weekend() && (V.hour >= 22 || V.hour < 8))
            return minutesintosegment <= 30 ? "getting ready for bed" : "sleeping";
        else
        {
            const nightlife = setup.people.nightlife_choice_today(npc);
            if (setup.ob_business.is_business(nightlife))
            {
                const hobbies = setup.people.all_hobbies(npc);
                if (hobbies.includes("video games"))
                    actions.push("playing video games");
                else if (hobbies.includes("dancing"))
                    actions.push("watching dance streams");
                else if (hobbies.includes("nerd stuff"))
                    actions.push("watching a movie");
                else if (hobbies.includes("working out"))
                    actions.push("working out");
                else
                    actions.push("killing time");
            }
            else
            {
                actions.push(setup.ob_nPCSimulation.homeActivities[nightlife].doing || nightlife);
            }
        }
        return rng.randomchoice(actions);
    }
    else if (slot == "sleep")
        return minutesintosegment <= 30 ? "getting ready for bed" : "sleeping";
    else if (slot == "food")
    {
        if (minutesintosegment < 5 && rng.random() < setup.people.skill_level(npc, "Cooking") / 10)
            return "cooking";
        else
            return "eating";
    }
    else if (slot == "showers")
        return "showering";
    else if (slot == "restroom")
    {
        if (minutesintosegment < 5)
            return "using the bathroom";
        else
            return "at the bathroom sink";
    }
    else
        return "doing nothing in particular"; // shouldn't really reach this branch but we probably will
}

setup.ob_housing.roommate_location = function(hkey, npc)
{
    // which room this npc should be in within the housing unit based on their current activity

    if (setup.ob_business.is_working(npc))
        return;
    else if (setup.people.get_type(npc) == "student" && setup.School.classes_today() && V.hour > 7 && V.hour < setup.School.last_bell())
        return;
    else if (setup.ob_time.nightlife_time() && setup.ob_business.is_business(setup.people.nightlife_choice_today(npc)))
        return;

    const doing = this.roommate_doing(npc);
    const slot = setup.people.schedule_slot(npc)?.location;
    const homeactivity = Object.keys(setup.ob_nPCSimulation.homeActivities).find(act => act == doing || setup.ob_nPCSimulation.homeActivities[act].doing == doing);
	const homeactivityroom = homeactivity ? setup.ob_housing.first_room_with_flag(hkey, setup.ob_nPCSimulation.homeActivities[homeactivity].roomFlags) : null;

    if (["showering", "using the bathroom", "at the bathroom sink"].includes(doing))
        return this.bathroom_for_npc(hkey, npc);
    else if (["cooking", "eating"].includes(doing) || slot == "food")
        return setup.ob_housing.first_room_of_class(hkey, "kitchen");
    else if (["getting ready for bed", "sleeping"].includes(doing) || slot == "sleep")
        return this.npc_sleeping_location(hkey, npc);
    else if (homeactivityroom)
        return homeactivityroom;
    else if (["home", "free time"].includes(slot))
        return setup.ob_housing.first_room_of_class(hkey, "living room") || setup.ob_housing.first_room_of_class(hkey, "entertainment room") || this.npc_sleeping_location(hkey, npc);
    else
        return this.npc_sleeping_location(hkey, npc);
}

