setup.ob_housing.event = function(hkey, roomid)
{
    // return an event related to walking through housing

    let roommate = setup.ob_events.pick_person({specialok: true});
    let eventchance = State.random() < setup.ob_events.base_event_chance();
    let events = [];
    if (roommate)
    {
        V.eventnpc = roommate;
        let doing = this.roommate_doing(roommate);
        if (doing)
        {
            events = [...setup.ob_events.assemble_set(["housing", "roommate", doing]), ...setup.ob_events.assemble_set(["housing", "roommate", "present"])];
        }
    }

    let roomclass = this.room_class_raw(hkey, roomid);
    events = [...events, ...setup.ob_events.assemble_set(["housing", "room", roomclass])];

    events = events.filter(e => {
        if (e.metadata?.useBaseEventChance && !eventchance)
            return false;

        if (!e.metadata?.filter)
            return true;

        let config = Object.assign({}, e.metadata.filter);
        if (!("specialok" in config)) config.specialok = true;
        return !!setup.ob_events.pick_person(config, [roommate]);
    });

    let setpick = setup.ob_events.choose_from_set(events);

    if (setpick)
    {
        event = setpick.passage;
        if (setpick.eventnpc) V.eventnpc = setpick.eventnpc;
        if (setpick.eventnpc2) V.eventnpc2 = setpick.eventnpc2;
        if (setpick.eventsim) V.eventsim = setpick.eventsim;

        delete V.npcforevent;
        delete V.npc2forevent;
        delete V.npc3forevent;
        delete V.npc4forevent;
        delete V.simeventforevent;

        setup.ob_events.register_event(event);
        return event;
    }
}

setup.ob_housing.roll_rent_this_month = function(npc)
{
    // determine how much of their rent the npc can pay this month

    npc = setup.people.get_name(npc);
    let pdata = setup.people.get_person(npc);

    const hkey = this.player_owned_housing().find(key => (this.get_roommates_raw(key) || []).includes(npc));
    if (!hkey) return;

    const building = V.pchousing[hkey].building;
    let paiduntil = setup.ob_housing.paid_until(building);
    let remaining = paiduntil - V.gameday;
    if (remaining > 7) return;

    const prev = pdata.playerOwedRent;
    if (prev && (prev.paidUntil == undefined || prev.paidUntil == paiduntil)) return prev;

    const latelastmonth = prev?.short;

    let owed = this.get_individual_rent(hkey);

    let oddsofbeingshort = 0;

    let submissive = (setup.ob_relationships.relationship_with(npc) == "submissive" && setup.people.is_bratty_sub(npc)) || (setup.people.willing_sex(npc) && setup.people.has_any_inclination(npc, "submissive"));

    let poor = (setup.people.wealth_to_income(setup.people.get_wealth(npc)) * 0.25) < owed;

    if (!latelastmonth)
    {
        if (poor)
            oddsofbeingshort += 0.4;
        if (submissive)
            oddsofbeingshort += 0.4;
    }

    let short = State.random() < oddsofbeingshort;
    let willingTrade = short && submissive && setup.people.pc_attracted_to(npc);

    pdata.playerOwedRent = {
        paidUntil: paiduntil,
        short,
        willingTrade,
        paid: false,
        informed: false,
    };

    return pdata.playerOwedRent;
}

