setup.ob_housing.pathfind = function(plan, startNode, endNode)
{
    // returns path to walk from one room to another

    // get map info
    const mapinfo = plan in this.plans ? this.plans[plan] : this.plans[V.pchousing[plan].plan]; // see if we got an actual plan or a housing unit key

    // Create an open set to store nodes to be evaluated
    const openSet = [startNode];

    // Create a dictionary to store the parent of each node
    const cameFrom = {};

    // Create a dictionary to store the cost of reaching each node from the start node
    const gScore = { [startNode]: 0 };

    // Create a dictionary to store the total estimated cost for each node (f-score)
    const fScore = { [startNode]: this.pathheuristic(plan, startNode, endNode) };

    while (openSet.length > 0) {
      // Find the node with the lowest f-score in the open set
      const currentNode = openSet.reduce((minNode, node) =>
        fScore[node] < fScore[minNode] ? node : minNode
      );

      if (currentNode === endNode) {
        // Reconstruct the path and return it
        return this.pathreconstruct(cameFrom, startNode, endNode);
      }

      // Remove the current node from the open set
      openSet.splice(openSet.indexOf(currentNode), 1);

      // Iterate through the neighbors of the current node
      if (!mapinfo.rooms[currentNode].exits) return null;
      for (const neighbor of mapinfo.rooms[currentNode].exits) {
        // Calculate the tentative g-score
        const tentativeGScore = gScore[currentNode] + 1; // Assuming uniform cost

        if (
          tentativeGScore < (gScore[neighbor] || Infinity)
        ) {
          // This path is better than any previous one, so record it
          cameFrom[neighbor] = currentNode;
          gScore[neighbor] = tentativeGScore;
          fScore[neighbor] = gScore[neighbor] + this.pathheuristic(plan, neighbor, endNode);

          if (!openSet.includes(neighbor)) {
            openSet.push(neighbor);
          }
        }
      }
    }

    // No path found
    return null;
}

setup.ob_housing.pathheuristic = function(plan, node, endNode)
{
    return 1;
}

setup.ob_housing.pathreconstruct = function(cameFrom, startNode, current)
{
    const path = [current];
    while (cameFrom[current]) {
    current = cameFrom[current];
    path.unshift(current);

    if (current == startNode)
        return path;
    }
    return path;
}

