setup.ob_enrolled = (function () {
    let course_cache = {};
    let last_updated_day = null;

    const updateCache = function () {
        course_cache = {};
        last_updated_day = V.gameday;

        for (const [studentname, studentinfo] of Object.entries(setup.people_db())) {
            const enrolledActivities = [...(studentinfo.courses || []), ...(studentinfo.sports || [])];
            enrolledActivities.forEach(activity => {
                if (!course_cache[activity]) course_cache[activity] = [];
                course_cache[activity].push(studentname);
            });
        }
    };

    const enrolledLookup = function (course) {
        if (V.gameday !== last_updated_day) updateCache();
        return course_cache[course] || [];
    };

    return enrolledLookup;
})();

setup.generate_student_body = function(rng = new RNG())
{
    let db = setup.people_db();
    let niches = setup.people_niches();

    let gender = V.studentgenderdistribution;

    const homeless = [];

    const multiplier = setup.ob_npc_generation_multiplier();

    // generate students
    // here's how it ended up working out:
    //      Block A: course required for majors
    //      Block B: lecture required for major
    //      Blocks C and D: common electives or reqs for other majors

    // start by filling Block A... we'll use this to determine some majors
    const firstfill = setup.School.available_courses(null, "Block A", 1);

    const archetypesused = [];
    let studentcount = 0;

    for (let i = 0; i < firstfill.length; i++)
    {
        let course = firstfill[i];
        let cinfo = setup.School.courses[course];
        let major = cinfo.major;
        const archetypes = setup.School.majors[major].archetypes;
        for (let n = 0; n < Math.round(cinfo.seats * multiplier); n++)
        {
            //if (n == 0 && major == V.pcmajor) n++;   // save a space for the PC

            let altered = false;
            let thisarchetypes = [...archetypes];
            if (studentcount > Math.round(40 * multiplier))
            {
                // are we missing an archetype? time to overemphasize it
                // leave nothing to chance!
                for (let j = 0; j < thisarchetypes.length; j += 2)
                {
                    if (!archetypesused.includes(thisarchetypes[j]))
                    {
                        thisarchetypes[j + 1] *= 100;
                        altered = true;
                    }
                }
            }
            //if (altered) console.log(thisarchetypes);

            let student = setup.people.add_random(  rng.randomrelfreq(gender),
                                                    rng.randomrelfreq(thisarchetypes),
                                                    "student", rng);
            studentcount++;

            let archetype = db[student].archetype;
            if (!archetypesused.includes(archetype)) archetypesused.push(archetype);
            //console.log(archetypesused);

            db[student].major = cinfo.major;
            this.enroll_student(student, course);

            homeless.push(student);

            // also enroll them in required lecture
            const lectures = setup.School.available_courses(cinfo.major, "Block B", 1);
            if (lectures.length > 0)
            {
                this.enroll_student(student, lectures[0]);
            }

            // pick something in either C or D for their major, but the other as an elective
            const blockcformajor = setup.School.available_courses(cinfo.major, "Block C", 1);
            const blockdformajor = setup.School.available_courses(cinfo.major, "Block D", 1);

            if (blockcformajor.length > 0 && blockdformajor.length > 0)
            {
                if (rng.random() < 0.5)
                {
                    this.enroll_student(student, blockcformajor[0]);
                    const blockd = setup.School.available_courses(null, "Block D", 1);
                    if (blockd.length > 0) this.enroll_student(student, rng.randomchoice(blockd));
                }
                else
                {
                    this.enroll_student(student, blockdformajor[0]);
                    const blockc = setup.School.available_courses(null, "Block C", 1);
                    if (blockc.length > 0) this.enroll_student(student, rng.randomchoice(blockc));
                }
            }
            else if (blockcformajor.length > 0)
            {
                this.enroll_student(student, blockcformajor[0]);
                const blockd = setup.School.available_courses(null, "Block D", 1);
                if (blockd.length > 0) this.enroll_student(student, rng.randomchoice(blockd));
            }
            else if (blockdformajor.length > 0)
            {
                this.enroll_student(student, blockdformajor[0]);
                const blockc = setup.School.available_courses(null, "Block C", 1);
                if (blockc.length > 0) this.enroll_student(student, rng.randomchoice(blockc));
            }
        }
    }

    // place students in residences, including putting the PC in the designated PC residence and finding their roommate

    console.log("WorldGen: placing students in residences");

    for (const [residence, rinfo] of Object.entries(setup.School.residences))
    {
        if (rinfo.pc)
        {
            console.log("WorldGen: placing PC's roommate");
            const genders = setup.ob_get_gender_node(V.pcgender, "roommate genders");
            State.setVar("$pcresidence", residence);
            let roommate = this.random_homeless_student(homeless, [], null, genders, null, rng, true);
            this.place_into_residence(roommate, residence);
            homeless.delete(roommate);
            State.setVar("$pcroommate", roommate);
            db[roommate].roommate = "PC";
            db[roommate].archetype = "Fashionista";
            db[roommate]["desired relationship"] = "rival";
            db[roommate].special = true;
            db[roommate].schedule = rng.randomchoice([2, 3, 4]);
            db[roommate].attraction = "bi";
            niches["The Roommate"] = roommate;
            setup.people.learn_number(roommate);

            console.log("WorldGen: placing roommate's partner");
            let genderstuff = setup.ob_orientation_and_gender_for(rng);
            let rmpartner = this.people.add_random(genderstuff.gender, "Bully", "student", rng);
            db[rmpartner].special = true;
            db[rmpartner].attraction = genderstuff.attraction;
            db[rmpartner].residence = "off-campus";
            db[rmpartner].major = "psychology";
            if (genderstuff.gender.indexOf("female") != -1)
                niches["The Roommate's Girlfriend"] = rmpartner;
            else if (genderstuff.gender.indexOf("male") != -1)
                niches["The Roommate's Boyfriend"] = rmpartner;
            else
                niches["The Roommate's Partner"] = rmpartner;

            setup.ob_nPCSimulation.set_relationship(roommate, rmpartner, "partner");

            db[rmpartner]["muscle"] = rng.rir(700, 800);
            db[rmpartner].schedule = rng.randomchoice([2, 3, 4]);
        }

        let n = 0;
        while (setup.ob_residents(residence).length < Math.round(rinfo.capacity * multiplier) - 1)    // -1 because we're adding by pairs
        {
            // let's make sure the PC's residence has every archetype
            let findtypes = (rinfo.pc && archetypesused.length > 0) ? archetypesused : null;

            let rando = setup.random_homeless_student(homeless, [], null, null, findtypes, rng);
            if (rando == null)
            {
                break;
            }
            else
            {
                n++;
                this.place_into_residence(rando, residence);
                homeless.delete(rando);
                db[rando].schedule = n < Math.round(20 * multiplier) ? 1 : 3;

                if (rinfo.pc)
                {
                    let k = archetypesused.indexOf(db[rando].archetype);
                    if (k > -1) archetypesused.splice(k);
                }

                let randoroommate = this.find_roommate_for(rando, homeless, rng);
                if (randoroommate != null && randoroommate != rando)
                {
                    n++;
                    this.place_into_residence(randoroommate, residence);
                    homeless.delete(randoroommate);
                    this.set_roommates(rando, randoroommate);
                    db[randoroommate].schedule = n < Math.round(20 * multiplier) ? 2 : 4;

                    if (rinfo.pc)
                    {
                        let k = archetypesused.indexOf(db[randoroommate].archetype);
                        if (k > -1) archetypesused.splice(k);
                    }
                }
            }
        }
    }

    console.log("WorldGen: placing remaining students off-campus");

    for (let i = 0; i < homeless.length; i++)
    {
        db[homeless[i]].residence = "off-campus";
        db[homeless[i]].schedule = rng.randomchoice([1, 2, 3, 4]);
    }

    this.generate_noncohort(rng);

    console.log("WorldGen: filling sports teams");

    this.fill_football_team();
    this.fill_swim_team();
    this.fill_cheer_team();
    this.fill_esports_team();

    console.log("WorldGen: filling Greek houses");
    if (!V.houses) setup.ob_houses.init_houses();
    setup.ob_houses.fill_houses();
}

setup.generate_noncohort = function(rng = new RNG(inthash(V.seed)))
{
    if (!V.noncohortgen)
    {
        const multiplier = setup.ob_npc_generation_multiplier();

        State.setVar("$noncohortgen", true);

        if (!V.removedpeople) V.removedpeople = [];

        console.log("WorldGen: generating non-cohort students");

        let db = setup.people_db();
        let niches = setup.people_niches();

        const students = setup.people.people_of_type("student");
        for (const student of students)
        {
            if (!("year" in db[student]))
            {
                db[student].year = 1;
                db[student].cohort = true;
            }
        }

        const majors = Object.keys(setup.School.majors);

        let gender = V.studentgenderdistribution;

        const homeless = [];

        for (const [year, info] of Object.entries(setup.School.noncohort))
        {
            if (!info.initial) continue;

            let n = 0;

            const archetypes = info.distribution;

            for (let [archetype, count] of Object.entries(info.static))
            {
                count = Math.round(count * multiplier);
                for (let i = 0; i < count; i++)
                {
                    let major = rng.randomchoice(majors);

                    let student = setup.people.add_random(  rng.randomrelfreq(gender),
                                                            archetype,
                                                            "student", rng);
                    db[student].major = major;
                    db[student].year = info.year;
                    db[student].cohort = false;
                    homeless.push(student);
                    n++;
                }
            }

            let random = Math.round((info.count - n) * multiplier);
            for (let i = 0; i < random; i++)
            {
                let major = rng.randomchoice(majors);
                let thisarchetype = rng.randomrelfreq(archetypes);

                let student = setup.people.add_random(  rng.randomrelfreq(gender),
                                                        thisarchetype,
                                                        "student", rng);
                db[student].major = major;
                db[student].year = info.year;
                db[student].cohort = false;
                homeless.push(student);
                n++;
            }
        }

        console.log("WorldGen: placing non-cohort students in residences");

        const residences = Object.keys(setup.School.residences);
        residences.push("off-campus");

        while (homeless.length > 0)
        {
            let rando = homeless[0];
            if (homeless.length == 1)
            {
                db[rando].residence = "off-campus";
            }
            else
            {
                let residence = rng.randomchoice(residences);
                this.place_into_residence(rando, residence);

                let randoroommate = this.find_roommate_for(rando, homeless, rng);
                if (randoroommate != null)
                {
                    this.place_into_residence(randoroommate, residence);
                    this.set_roommates(rando, randoroommate);
                    db[randoroommate].schedule = rng.randomchoice([1, 2, 3, 4]);

                    homeless.delete(randoroommate);
                }
            }
            homeless.delete(rando);
            db[rando].schedule = rng.randomchoice([1, 2, 3, 4]);
        }
    }
}

setup.generate_professors = function(rng = new RNG())
{
    let db = setup.people_db();
    let niches = setup.people_niches();

    // generate two professors per major: one covering blocks A and C, the other blocks B and D

    const profsarepartners = ["Drawing I", "General Psychology"];

    let genders = V.facultygenderdistribution;
    let prefgenders = [];
    for (let gender of V.pcsexualprefs)
    {
        let i = genders.indexOf(gender);
        if (i >= 0)
            prefgenders.push(genders[i], genders[i + 1]);
    }
    if (prefgenders.length == 0) prefgenders = genders;

    const majors = Object.keys(setup.School.majors);
    for (let i = 0; i < majors.length; i++)
    {
        let major = setup.School.majors[majors[i]];
        let archetype = major["professor archetype"][0];
        const courses = setup.School.courses_for_major(majors[i], 1);

        let thisgender0, thisgender1;
        let thisattraction0, thisattraction1;
        if (profsarepartners.includes(courses[0]) || rng.random() <= 0.4)
        {
            thisgender0 = rng.randomrelfreq(prefgenders);
            thisattraction0 = this.orientation_for(thisgender0);
        }
        else
        {
            thisgender0 = rng.randomrelfreq(genders);
        }
        if (profsarepartners.includes(courses[1]) || rng.random() <= 0.4)
        {
            thisgender1 = rng.randomrelfreq(prefgenders);
            thisattraction1 = this.orientation_for(thisgender1);
        }
        else
        {
            thisgender1 = rng.randomrelfreq(genders);
        }

        let prof1 = setup.people.add_random( thisgender0,
                                            archetype,
                                            "faculty",
                                            rng);

        let prof2 = setup.people.add_random( thisgender1,
                                            archetype,
                                            "faculty",
                                            rng);

        if (thisattraction0) db[prof1].attraction = thisattraction0;
        if (thisattraction1) db[prof2].attraction = thisattraction1;

        db[prof1].courses = [];
        db[prof2].courses = [];

        const allcourses = Object.keys(setup.School.courses);
        for (let j = 0; j < allcourses.length; j++)
        {
            let course = setup.School.courses[allcourses[j]];
            if (course.major == majors[i] && course.year == 1)
            {
                if (course.schedule == "Block A" || course.schedule == "Block C")
                {
                    db[prof1].courses.push(allcourses[j]);
                }
                else if (course.schedule == "Block B" || course.schedule == "Block D")
                {
                    db[prof2].courses.push(allcourses[j]);
                }
            }
        }
    }

    console.log("WorldGen: generating second round professors");

    this.revise_professors(rng);

    console.log("WorldGen: Assigning professors to advanced courses");

    this.revise_professors_again(rng);

    console.log("WorldGen: creating spouses for married professors");

    this.marry_professors();

    console.log("WorldGen: creating spouses for some townies");

    setup.ob_marry_some_townies();
}

setup.revise_professors = function(rng = new RNG(inthash(V.seed + "prof")))
{
    // add new professors for blocks C and D, take away those courses from existing professors

    if (!V.profsrevised)
    {
        State.setVar("$profsrevised", true);

        let db = setup.people_db();
        let niches = setup.people_niches();

        const faculty = setup.people.people_of_type("faculty");

        const profsarepartners = ["Drawing I", "General Psychology"];

        let genders = V.facultygenderdistribution;
        let prefgenders = [];
        for (let gender of V.pcsexualprefs)
        {
            let i = genders.indexOf(gender);
            if (i >= 0)
                prefgenders.push(genders[i], genders[i + 1]);
        }
        if (prefgenders.length == 0) prefgenders = genders;

        const majors = Object.keys(setup.School.majors);
        for (let i = 0; i < majors.length; i++)
        {
            let major = setup.School.majors[majors[i]];
            let archetype = major["professor archetype"][1];
            const courses = setup.School.courses_for_major(majors[i], 1);

            let thisgender2, thisgender3;
            let thisattraction2, thisattraction3;
            if (profsarepartners.includes(courses[2]) || rng.random() <= 0.4)
            {
                thisgender2 = rng.randomrelfreq(prefgenders);
                thisattraction2 = this.orientation_for(thisgender2);
            }
            else
            {
                thisgender2 = rng.randomrelfreq(genders);
            }
            if (profsarepartners.includes(courses[3]) || rng.random() <= 0.4)
            {
                thisgender3 = rng.randomrelfreq(prefgenders);
                thisattraction3 = this.orientation_for(thisgender3);
            }
            else
            {
                thisgender3 = rng.randomrelfreq(genders);
            }

            let prof3 = setup.people.add_random( thisgender2,
                        archetype,
                        "faculty",
                        rng);

            let prof4 = setup.people.add_random( thisgender3,
                        archetype,
                        "faculty",
                        rng);

            if (thisattraction2) db[prof3].attraction = thisattraction2;
            if (thisattraction3) db[prof4].attraction = thisattraction3;

            db[prof3].courses = [];
            db[prof4].courses = [];

            const allcourses = Object.keys(setup.School.courses);
            for (let j = 0; j < allcourses.length; j++)
            {
                let course = setup.School.courses[allcourses[j]];
                if (course.major == majors[i] && course.year == 1)
                {
                    let takeaway = false;
                    if (course.schedule == "Block C")
                    {
                        //console.log("giving " + courses[j] + " to " + prof3);
                        db[prof3].courses.push(allcourses[j]);
                        takeaway = true;
                    }
                    else if (course.schedule == "Block D")
                    {
                        //console.log("giving " + courses[j] + " to " + prof4);
                        db[prof4].courses.push(allcourses[j]);
                        takeaway = true;
                    }
                    if (takeaway)
                    {
                        for (let oldprof of faculty)
                        {
                            if (db[oldprof].courses && db[oldprof].courses.includes(allcourses[j]))
                            {
                                //console.log("removing " + courses[j] + " from " + oldprof);
                                db[oldprof].courses.delete(allcourses[j]);
                            }
                        }
                    }
                }
            }
        }
    }
}

setup.revise_professors_again = function(rng = new RNG(inthash(V.seed + "prof3")))
{
    // for 0.8
    // this time we're slotting in professors to take the years 2-4 courses

    let rng2 = setup.ob_newRNG(`schedule${V.seed}`);

    for (let [p, pinfo] of Object.entries(V.people))
        if (pinfo.type == "faculty")
        {
            pinfo.schedule = rng2.randomchoice([1, 2, 3, 4]);
            if (pinfo.courses)
            {
                let sched = [null, null, null, null];
                let major;
                for (let course of pinfo.courses)
                {
                    major = setup.School.get_course_attribute(course, "major");
                    let block = setup.School.get_course_attribute(course, "schedule");
                    let i = ["Block A", "Block B", "Block C", "Block D"].indexOf(block);
                    sched[i] = course;
                }

                if (sched[0])
                {
                    pinfo.courses.push(setup.School.find_course(major, "Block B", 2));
                    pinfo.courses.push(setup.School.find_course(major, "Block C", 3));
                    pinfo.courses.push(setup.School.find_course(major, "Block D", 4));
                }
                else if (sched[1])
                {
                    pinfo.courses.push(setup.School.find_course(major, "Block A", 2));
                    pinfo.courses.push(setup.School.find_course(major, "Block C", 4));
                    pinfo.courses.push(setup.School.find_course(major, "Block D", 3));
                }
                else if (sched[2])
                {
                    pinfo.courses.push(setup.School.find_course(major, "Block A", 3));
                    pinfo.courses.push(setup.School.find_course(major, "Block B", 4));
                    pinfo.courses.push(setup.School.find_course(major, "Block D", 2));
                }
                else
                {
                    pinfo.courses.push(setup.School.find_course(major, "Block A", 4));
                    pinfo.courses.push(setup.School.find_course(major, "Block B", 3));
                    pinfo.courses.push(setup.School.find_course(major, "Block C", 2));
                }
            }
        }
}

setup.ob_fix_multiple_professors_for_course = function(vars = V)
{
    // a save-repairing method, does not run for normal worldgen

    for (let [p, pdata] of Object.entries(vars.people))
    {
        if (pdata.type != "faculty" || !pdata.courses || pdata.courses.length == 0) continue;

        let maincourse;
        let major;
        let mainblock;

        for (let course of pdata.courses)
        {
            let tmajor = setup.School.get_course_attribute(course, "major");
            let tblock = setup.School.get_course_attribute(course, "schedule");
            if (setup.School.find_course(tmajor, tblock, 1) == course)
            {
                maincourse = course;
                major = tmajor;
                mainblock = tblock;
                break;
            }
        }

        let newcourses = [maincourse];

        switch (mainblock)
        {
            case "Block A":
            {
                newcourses.push(setup.School.find_course(major, "Block B", 2));
                newcourses.push(setup.School.find_course(major, "Block C", 3));
                newcourses.push(setup.School.find_course(major, "Block D", 4));
                break;
            }
            case "Block B":
            {
                newcourses.push(setup.School.find_course(major, "Block A", 2));
                newcourses.push(setup.School.find_course(major, "Block C", 4));
                newcourses.push(setup.School.find_course(major, "Block D", 3));
                break;
            }
            case "Block C":
            {
                newcourses.push(setup.School.find_course(major, "Block A", 3));
                newcourses.push(setup.School.find_course(major, "Block B", 4));
                newcourses.push(setup.School.find_course(major, "Block D", 2));
                break;
            }
            case "Block D":
            {
                newcourses.push(setup.School.find_course(major, "Block A", 4));
                newcourses.push(setup.School.find_course(major, "Block B", 3));
                newcourses.push(setup.School.find_course(major, "Block C", 2));
                break;
            }
        }

        pdata.courses = newcourses;
    }
}

