    for (let npc of rng.shuffle(Object.keys(V.people)).filter(p => setup.people.get_type(p) == "townie" && corearchetypes.includes(setup.people.archetype(p)) && !setup.people.is_special(p) && !setup.ob_relationships.partner(p) && !setup.people.is_personally_relevant(p)))
