setup.validate_course_has_professor = function(course)
{
    // a save-repairing method

    let prof = setup.School.professor_of_course(course);
    let db = V.people;

    if (prof == undefined)
    {
        let rng = setup.ob_newRNG(V.seed + "prof");

        let genders = V.facultygenderdistribution;
        let prefgenders = [];
        for (let gender of V.pcsexualprefs)
        {
            let i = genders.indexOf(gender);
            if (i >= 0)
                prefgenders.push(genders[i], genders[i + 1]);
        }
        if (prefgenders.length == 0) prefgenders = genders;

        let thisgender;
        let thisattraction;

        if (rng.random() <= 0.4)
        {
            thisgender = rng.randomrelfreq(prefgenders);
            thisattraction = this.orientation_for(thisgender);
        }
        else
        {
            thisgender = rng.randomrelfreq(genders);
        }

        let major = setup.School.majors[setup.School.courses[course].major];
        let archetype = major["professor archetype"][0];

        let prof = setup.people.add_random( thisgender,
            archetype,
            "faculty",
            rng);

        if (thisattraction) db[prof].attraction = thisattraction;

        db[prof].courses = [course];

        return prof;
    }
}

