setup.ob_place_bff = function()
{
    let seed = inthash(V.seed)
    let rng = new RNG(seed);

    let db = setup.people_db();

    let bffname = V.bestfriend;
    let bff = setup.people.get_person(bffname);
    const copyprops = ["residence", "roommate", "major", "courses", "schedule"];

    var studentkeys = rng.shuffle(Object.keys(db));
    for (let i = 0; i < studentkeys.length; i++)
    {
        let studentkey = studentkeys[i];
        let student = db[studentkey];
        if (student.type == "student" && student.residence == V.pcresidence
            && student.species[1] == bff.species[1] && student.roommate != "PC" && studentkey != bffname)
        {
            for (let j = 0; j < copyprops.length; j++)
            {
                bff[copyprops[j]] = student[copyprops[j]];
            }

            if (db[bff.roommate])
                db[bff.roommate].roommate = bffname;

            student.roommate = null;
            student.residence = "off-campus";

            break;
        }
    }

    let bffrm = V.people[bffname].roommate;
    for (const [p, pdata] of Object.entries(V.people))
        if (pdata.roommate == bffname && p != bffrm)
            pdata.roommate = null;

    return bff;
}

setup.random_homeless_student = function(homeless, exclude, year = null, genders = null, types = null, rng = new RNG(), generateifnonefound = false)
{
    let db = setup.people_db();
    let found = false;
    let tries = 0;
    while (!found && tries < 100)
    {
        tries++;
        let skey = rng.randomchoice(homeless);
        let sinfo = db[skey];
        if ((genders == null || genders.includesAny(sinfo.species[1])) &&
            !exclude.includes(skey) &&
            (types == null || tries > 50 || types.includes(sinfo.archetype)) &&
            (!year || tries > 75 || db[skey].year == year)
            )
        {
            found = true;
            return skey;
        }
    }

    if (generateifnonefound)
    {
        let newnpc = this.add_random_npc(year, genders, types);

        return newnpc;
    }

    return null;
}

setup.add_random_npc = function(year = null, genders = null, types = null, rng = null)
{
    // mostly for adding npcs after the game has started
    // not very good, just useful as a last resort fallback when we can't find a fitting npc

    let db = setup.people_db();

    if (!rng) rng = setup.ob_newRNG(`${V.seed}${Object.keys(V.people).length}`);

    if (!year) year = 1;
    if (!genders) genders = ["male", "female", "transgender male", "transgender female", "nonbinary amab", "nonbinary afab"];
    if (!types) types = ["student"];

    const type = rng.randomchoice(types);

    const archetypes = type == "student"
        ? setup.School.majors["psychology"].archetypes.filter(el => typeof el == "string")
        : Object.keys(setup.ob_archetypes).filter(arch => setup.ob_archetypes[arch]["townie count"]);

    const archetype = rng.randomchoice(archetypes);

    const gender = rng.randomchoice(genders);

    let newnpc = setup.people.add_random(gender, archetype, type, rng);

    if (type == "student")
    {
        db[newnpc].year = year;
        db[newnpc].major = rng.randomchoice(Object.keys(setup.School.majors));
        db[newnpc].cohort = year == V.gameyear;
        setup.place_into_residence(newnpc, rng.randomchoice(setup.School.residences));
    }

    return newnpc;
}

