setup.assign_employees = function(business)
{
    const data = setup.ob_business.db[business];
    let count = data.count - setup.people.employees(business).length;
    if (count <= 0) return;
    console.log("Finding employees for business " + business);
    let studentcount, towniecount;

    let studentratio = data.studentRatio;
    let archetypes = data.townieArchetypes;

    studentcount = Math.round(count * studentratio);
    towniecount = count - studentcount;

    let db = setup.people_db();
    let people = Object.keys(db);
    let peopleshuffle = [...people];
    peopleshuffle = setup.ob_shuffle(peopleshuffle);

    const emps = [];
    for (let i = 0; i < peopleshuffle.length; i++)
    {
        let person = peopleshuffle[i];
        let pdata = db[person];
        if (towniecount > 0 && pdata.type == "townie" && archetypes.includes(pdata.archetype) && !("job" in pdata))
        {
            setup.ob_business.place_npc_in_job(person, business);
            emps.push(person);
            towniecount--;
        }
        else if (studentcount > 0 && pdata.type == "student" && !("job" in pdata) && !pdata.special)
        {
            setup.ob_business.place_npc_in_job(person, business);
            emps.push(person);
            studentcount--;
        }

        if (studentcount <= 0 && towniecount <= 0) break;
    }

    V.businesses[business] = {employees: Object.keys(V.people).filter(p => V.people[p].job == business)};
    // ^^ we do it this way even though the array was already built so that we can capture special NPCs too
}

