setup.revise_professor_archetypes = function()
{
    State.setVar("$profarchetypesrevised", true);
    const pccourses = V.pccourses;
    const rng = new RNG(inthash(V.seed));
    let people = V.people;
    for (const [course, courseinfo] of Object.entries(setup.School.courses))
    {
        let newarch;
        if (pccourses.includes(course) && courseinfo["archetypes for player"])
        {
            newarch = rng.randomchoice(courseinfo["archetypes for player"]);
        }
        else if (courseinfo["archetypes"])
        {
            newarch = rng.randomchoice(courseinfo["archetypes"]);
        }

        if (newarch)
        {
            const prof = setup.School.professor_of_course(course);
            people[prof].archetype = newarch;
        }
    }
    console.log("WorldGen: revised professor archetypes");
}

setup.pick_male_jock = function(years = [1, 2, 3, 4])
{
    // looks through people database for a male physically-inclined student not already involved in a sport
    // if no men are available it'll pick somebody else

    const db = V.people;
    const people = setup.ob_shuffle(Object.keys(db));

    let skill = 10;
    let maxdiff = 4;
    let genders = ["male", "transgender male"];
    let found = false;
    let peep = null;

    while (!found)
    {
        for (const p of people)
        {
            if (genders.includes(setup.people.get_gender(p)) && years.includes(setup.people.get_year(p)) && !db[p].sports && setup.people.get_type(p) == "student" && Math.abs(skill - setup.people.skill_level(p, "Physical")) <= maxdiff && !setup.people.is_special(p))
            {
                peep = p;
                found = true;
                break;
            }
        }
        if (!found)
        {
            if (maxdiff < 10)
                maxdiff++;
            else if (genders.length == 2)
                genders = ["male", "transgender male", "nonbinary afab", "nonbinary amab"];
            else if (genders.length == 4)
                genders = ["male", "transgender male", "nonbinary afab", "nonbinary amab", "female", "transgender female"];
            else
                return null;
        }
    }
    return peep;
}

