setup.ob_establish_existing_relationships = function(rng = new RNG(inthash("rel" + V.seed)))
{
    const existingRelationshipChanceBase = 0.1;
    const reltypes = ["student", "townie"];
    for (const [p, pdata] of rng.shuffle(Object.entries(V.people)))
    {
        if (reltypes.includes(pdata.type) &&
            !pdata.attitude &&
            !pdata.special &&
            (!V.boybff || V.boybff != p) &&
            (!V.girlbff || V.girlbff != p) &&
            setup.ob_relationships.dates(p) == 0 &&
            !setup.people.is_sexpartner(p))
        {
            const archinfo = setup.ob_archetypes[pdata.archetype];
            let chance = existingRelationshipChanceBase * archinfo.existingRelationshipChanceModifier;
            if (!pdata.partner && rng.random() <= chance)
            {
                const inclinations = setup.people.inclinations(p);
                if (!inclinations.includesAny(["Aromantic"]))
                {
                    this.find_romantic_partner(p, rng);
                }
            }
        }
    }
}

setup.find_romantic_partner = function(npc, rng = new RNG())
{
    const type = V.people[npc].type;
    for (const npc2 of rng.shuffle(Object.keys(V.people)))
        if (npc != npc2 &&
            !V.people.special &&
            (!V.boybff || V.boybff != npc2) &&
            (!V.girlbff || V.girlbff != npc2) &&
            !V.people[npc2].partner &&
            !V.people[npc2].attitude &&
            type == V.people[npc2].type &&
            setup.people.npc_mutual_attraction(npc, npc2) &&
            !setup.people.has_any_inclination(npc2, ["Aromantic"]) &&
            setup.ob_relationships.dates(npc2) == 0 &&
            !setup.people.is_sexpartner(npc2) &&
            rng.random() <= setup.people.npc_association_factor(npc, npc2))
        {
            let partnertype = "partner";
            if (setup.people.has_inclination(npc, "Polyamorous") && setup.people.has_any_inclination(npc2, ["Polyamorous", "Open Relationships"]))
                partnertype = "poly partner";
            else if (setup.people.has_inclination(npc, "Open Relationships") && setup.people.has_any_inclination(npc2, ["Polyamorous", "Open Relationships"]))
                partnertype = "open partner";

            setup.ob_nPCSimulation.set_relationship(npc, npc2, partnertype);
            console.log(`Partnering ${npc} with ${npc2}.`);
            break;
        }
}

setup.determine_virginity = function(npc, rng = new RNG())
{
    // I have actual sources for these numbers! tho of course it is fudged a little bit for gameplay (also the sources don't completely agree)

    npc = setup.people.get_name(npc);
    if ("virginity" in V.people[npc]) return V.people[npc].virginity;

    let chance = 0.4;

    let type = setup.people.get_type(npc);
    let age = setup.people.get_age(npc);
    if (type == "student")
    {
        let year = setup.people.get_year(npc);
        if (year == 1)
            chance = 0.4;
        else if (year == 2)
            chance = 0.3;
        else if (year == 3)
            chance = 0.2;
        else if (year == 4)
            chance = 0.1;
    }
    else
    {
        let age = setup.people.get_age(npc);
        if (age < 18)       // this game does not allow for the existence of minors but may as well be thorough
            chance = 1;
        else if (age == 18)
            chance = 0.4;
        else if (age == 19)
            chance = 0.3;
        else if (age == 20)
            chance = 0.2;
        else if (age < 30)
            chance = 0.05;
        else if (age < 40)
            chance = 0.025;
        else
            chance = 0.0125;
    }

    let mainchance = 1, analchance = 1, mouthchance = 1;

    if (chance < 1)
    {
        if (setup.people.has_any_inclination(npc, ["Insecure", "Loner"]))
            chance *= 4;
        if (setup.people.has_any_inclination(npc, ["Forward", "Confident", "Dominant", "Dominant Vibe", "Breaker", "Taker"]))
            chance = age > 25 ? 0 : chance / 2;
        if (setup.people.has_any_inclination(npc, ["Slut", "Casual Hookup", "Cumslut"]))
            chance = age > 20 ? 0 : chance / 4;
        if (setup.people.has_any_inclination(npc, ["Whore", "Whore Connoisseur", "Paypig", "Findom"]))
            chance = 0;

        if (V.people[npc].partner && !setup.people.has_inclination(npc, "Chaste")) chance /= 2;

        mainchance = chance;
        analchance = Math.clamp(chance * 2, 0.4, 1);
        mouthchance = Math.clamp(chance * 0.75, 0, 1);

        let attraction = setup.people.attraction(npc).genders;
        if (!attraction.includes("male"))
        {
            if (attraction.includesAny(["transgender female", "nonbinary amab"]))
                analchance = 0.95;
            else
                analchance = 1;
        }

        if (setup.people.has_any_inclination(npc, ["Chaste"]))
        {
            mainchance = Math.max(mainchance, 0.95);
            analchance = Math.max(analchance, 0.8);
            mouthchance = 0.95;
        }
    }

    const virginity = [];

    if (!V.pc || !setup.people.has_had_sex(npc))
    {
        if (rng.random() <= mainchance || age < 18)
        {
            virginity.push(setup.people.has_part(npc, "penis") ? "penis" : "vagina");
        }

        let mightanal = virginity.length == 0 || setup.people.has_inclination(npc, "Chaste");
        if (!mightanal)
        {
            virginity.push("anus");
        }
        else if (rng.random() <= analchance || age < 18)
        {
            virginity.push("anus");
        }

        if (rng.random() <= mouthchance || age < 18)
        {
            virginity.push("mouth");
        }
    }

    V.people[npc].virginity = virginity;

    return virginity;
}

