setup.ob_streaming.potential_viewers = function()
{
    const stream = V.stream;
    const hour = V.hour;
    const hourmult = [
                        1.0, 0.7, 0.6, 0.5, // 12am to 3am
                        0.4, 0.3, 0.2, 0.2, // 4am to 7am
                        0.3, 0.4, 0.5, 0.6, // 8am to 11am
                        0.6, 0.7, 0.7, 0.7, // 12pm to 3pm
                        0.8, 0.9, 0.9, 0.9, // 4pm to 7pm
                        1.0, 1.0, 1.0, 1.0, // 8pm to 11pm
                        ][hour];

    let pop = this.popularity(stream.type);
    let qual = stream.quality;

    let randfactor = 0.8 + (0.4 * State.random());
    let interestfactor = 0.5;
    if (stream.interest > 500 && stream.rounds > 3)
    {
        interestfactor = 1.0 + (((stream.interest - 500) / 500) * 0.2);
    }
    let viewerbonus = stream.viewerbonus || 1.0;
    let maxviews = Math.round(pop * hourmult * randfactor * interestfactor * viewerbonus);
    qual *= viewerbonus;
    maxviews = Math.max(Math.min(maxviews, qual), 10);
    return maxviews;
}

setup.ob_streaming.viewer_change = function()
{
    const stream = V.stream;
    const current = stream.viewers;
    const potential = this.potential_viewers();
    let interest = Math.min(Math.max(stream.interest, 50), 1000);
    let interestmult = interest / 1000.0;
    let diff = potential - current;
    if (diff > 0)
    {
        diff *= interestmult;
    }
    return Math.round(diff);
}

setup.ob_streaming.chatter_of_attitude = function(attitude, exclude = [])
{
    const stream = V.stream;
    for (const [name, info] of setup.ob_shuffle(Object.entries(stream.chatters)))
    {
        if (info.attitude == attitude && !exclude.includes(name))
            return name;
    }
    return null;
}

setup.ob_streaming.target_hour_tips = function()
{
    const stream = V.stream;
    let mult = 0.7 + (0.6 * State.random());

    mult *= 1.42;

    let target = 10.0 + (20.0 * (stream.viewers / 1000)) * mult;
    if (stream.rounds <= 1)
        target /= 2;
    else if (stream.rounds <= 2)
        target /= 1.5;
    return Math.round(target);
}

setup.ob_streaming.tip_spread = function()
{
    const stream = V.stream;
    let total = this.target_hour_tips();

    if (stream.type == "CollegeCams")
    {
        total /= 4;
    }

    const tips = [];
    while (total > 0)
    {
        let amt = 2;
        if (total >= 10 && State.random() < 0.2)
            amt = 10;
        else if (State.random() < 0.4)
            amt = 5;
        else
            amt = 2;

        if (tips.length == stream.viewers - 1)
            amt = total;

        total -= amt;
        tips.push(amt);
    }
    return tips;
}

