// track location-based inventory
// basically, things that are generally not carried on one's person but live at a location, like furniture and decor

setup.ob_locationInventory = {};

setup.ob_locationInventory.location_for_thing = function(location, thing)
{
    const key = typeof thing == "string" ? thing : thing.item;
    return setup.ob_dormstuff[key]?.universal ? "universal" : location;
}

setup.ob_locationInventory.contents = function(location, thing = null, init = false)
{
    const actualloc = thing ? this.location_for_thing(location, thing) : location;
    if (!V.LocationInventory)
    {
        if (!init) return [];
        V.LocationInventory = {};
    }
    if (!V.LocationInventory[actualloc])
    {
        if (!init) return [];
        V.LocationInventory[actualloc] = [];
    }
    return V.LocationInventory[actualloc];
}

setup.ob_locationInventory.all_contents = function(location, thing = null, init = false)
{
    // get the given location's contents plus universal contents

	const actualloc = thing ? this.location_for_thing(location, thing) : location;
    let retval = this.contents(actualloc, thing, init);
    if (location != "universal")
        retval = [...retval, ...this.contents("universal", thing, init)];
    return retval;
}

setup.ob_locationInventory.current_location = function()
{
    // attempt to determine player's current location intelligently
    if (V.lastlocpassage == "YourDorm")
        return "dorm";
    else if (V.lastlocpassage == "YourGreekHouseRoom")
        return "greekroom";
    else if (V.housing && V.pc.equals(V.housing.owner))
    {
        return `${V.housing.key}:${V.housing.roomID}`;
    }
    else
        return "packed";
}
setup.ob_locationInventory.myloc = setup.ob_locationInventory.current_location;

setup.ob_locationInventory.last_location = function()
{
    return V.lastInventoryLocation || "dorm";
}
setup.ob_locationInventory.lastloc = setup.ob_locationInventory.last_location;

setup.ob_locationInventory.set_last_location = function(location)
{
    const ignore = ["universal", "packed"];
    if (!ignore.includes(location))
        V.lastInventoryLocation = location;
}

setup.ob_locationInventory.has = function(location, thing, findinvisible = false, countalsohas = true)
{
    thing = typeof thing == "object" ? thing.item : thing;
    let dormstuff = this.all_contents(location, thing);

	let has = dormstuff.filter(item => (item.item == thing && (!item.hidden || findinvisible))).length > 0;
	if (has)
		return has;
	else if (countalsohas && setup.ob_dormstuff[thing]?.alsoHasIf)
		return Scripting.evalTwineScript(setup.ob_dormstuff[thing].alsoHasIf);
	else if (setup.ob_dormstuff[thing]?.availableInComputerLab && V.lastloctags?.includes("computerlab"))
		return true;
    else
        return false;
}

setup.ob_locationInventory.get = function(location, thing)
{
    thing = typeof thing == "object" ? thing.item : thing;
    let dormstuff = this.all_contents(location, thing);

	let matching = dormstuff.filter(item => item.item == thing);
	let retval = matching.length > 0 ? matching[0] : null;

    return retval
}

setup.ob_locationInventory.has_any = function(location, things, findinvisible = false)
{
	return things.filter(thing => this.has(location, thing, findinvisible)).length > 0;
}

setup.ob_locationInventory.add = function(location, thing)
{
    let dormstuff = this.contents(location, thing, true);
    setup.ob_locationInventory.set_last_location(location);

	if (typeof thing == "string")
		thing = {item: thing};
	dormstuff.push(thing);

	if (location != "packed" && setup.ob_dormstuff[thing.item]?.collectedOn)
		if (!this.has(location, setup.ob_dormstuff[thing.item].collectedOn))
			this.add(location, setup.ob_dormstuff[thing.item].collectedOn);
}

setup.ob_locationInventory.remove = function(location, thing)
{
	let dormstuff = this.contents(location, thing);

    let i = dormstuff.indexOf(thing);
    if (i >= 0)
    {
        dormstuff.splice(i, 1);

        if (thing.item == "rock tumbler")
            delete V.rocktumbling;
    }
    else
    {
        dormstuff.deleteWith(item => item.item == thing);
        if (thing == "rock tumbler")
            delete V.rocktumbling;
    }
}

setup.ob_locationInventory.hide = function(location, thing)
{
    thing = typeof thing == "object" ? thing.item : thing;
    let dormstuff = this.all_contents(location, thing);

	for (let i = 0; i < dormstuff.length; i++)
		if ((typeof thing == "string" && thing == dormstuff[i].item) || (typeof thing == "object" && thing.item == dormstuff[i].item))
			dormstuff[i].hidden = true;
}

setup.ob_locationInventory.unhide = function(location, thing)
{
    thing = typeof thing == "object" ? thing.item : thing;
    let dormstuff = this.all_contents(location, thing);

	for (let i = 0; i < dormstuff.length; i++)
		if (dormstuff[i].hidden && ((typeof thing == "string" && thing == dormstuff[i].item) || (typeof thing == "object" && thing.item == dormstuff[i].item)))
