setup.ob_locationInventory.name = function(location, thing, addaoran = false)
{
    let dormstuff = this.all_contents(location, thing);

	if (typeof thing == "string")
	{
		for (let item of dormstuff)
		{
			if (item.item == thing)
			{
				thing = item;
			}
		}
	}
	if (typeof thing == "string") return thing;
	let name = thing.name || thing.item;

	let contents = this.collected_on(location, thing);
	if (contents.length > 0)
	{
		name += " containing " + setup.ob_and(contents.map(c => this.name(location, c)));
	}

	return (addaoran ? setup.ob_a_or_an(name) + " " : "") + name;
