setup.ob_locationInventory.collected_on = function(location, thing)
{
    let dormstuff = this.all_contents(location, thing);

	if (typeof thing == "string")
	{
		for (let item of dormstuff)
		{
			if (item.item == thing)
			{
				thing = item;
			}
		}
	}
	if (typeof thing == "string") return [];
	const retval = [];
	for (let item of dormstuff)
