setup.ob_locationInventory.set_collection_name = function(location, collection)
{
	let featured = this.collection_featured(location, collection);
	let allinv = this.collection_inventory(location, collection);
	let names = featured.length > 0 ? featured : allinv;

	if (names.length == 1)
		collection.name = setup.ob_strip_a_or_an(names[0]);
	else if (names.length <= 5)
		collection.name = collection.item + " consisting of " + setup.ob_and(names);
	else
		collection.name = collection.item + " consisting of " + setup.ob_and(names.slice(0, 5));

	return collection.name;
}

setup.ob_locationInventory.display_name = function(location, collection)
{
	// for non-destructive name alterations

	let featured = this.collection_featured(location, collection);
	let allinv = this.collection_inventory(location, collection);
	if (allinv.length == 0 && featured.length == 0)
		return collection.name;

	if (collection.item == "trophy drawer")
	{
		let names = featured.length > 0 ? featured : allinv;
		names = [...names];

		for (let i = 0; i < names.length; i++)
		{
			let name = names[i];
			let underwear = setup.people.underwear_collected_from(name);

			let prefix = "";

			if (underwear && underwear.person)
			{
				if (setup.people.is_known(underwear.person))
					prefix = setup.people.fullname(underwear.person)+"'s";
				else if (setup.people.is_femme(underwear.person))
					prefix = "some girl's";
				else if (setup.people.is_masc(underwear.person))
					prefix = "some guy's";
				else
					prefix = "somebody's";

				if (underwear.stolen)
					prefix += " stolen";

				names[i] = prefix + " " + names[i];
			}
		}

		if (names.length == 1)
			return setup.ob_strip_a_or_an(names[0]);
		else if (names.length <= 5)
			return collection.item + " consisting of " + setup.ob_and(names);
		else
			return collection.item + " consisting of " + setup.ob_and(names.slice(0, 5));
	}

	return collection.name;
}

setup.ob_locationInventory.remove_from_collection = function(location, item, collectionname)
{
    let collection = this.get(location, collectionname);
	if (!collection) return;
	let i = collection.collection.indexOf(item);
	if (i >= 0)
    	collection.collection.deleteAt(i);
    if (collection.collection.length == 0)
    {
        this.remove(location, collectionname);
        return [];
    }
    else
    {
        this.set_collection_name(location, collection);
        if (collection.featured && collection.featured.includes(item))
		{
			let j = collection.featured.indexOf(item);
            collection.featured.deleteAt(j);
		}

        return collection.collection;
    }
}

