	const info = setup.ob_dormstuff[key];
	if (!info || info.universal || info.builtIn) return;

	const contents = this.collected_on(location, thing);

	for (const content of contents)
	{
		this.remove(location, content);
		this.add("packed", content);
	}

    this.remove(location, thing);
    this.add("packed", thing);
}

setup.ob_locationInventory.pack_all = function(location)
