setup.ob_locationInventory.unpack = function(location, thing)
{
	const contents = this.collected_on("packed", thing);

    this.remove("packed", thing);
    this.add(location, thing);

	for (const content of contents)
	{
		this.remove("packed", content);
		this.add(location, content);
	}
