	if (!found && includebasefurniture && V.pchousing)
	{
		for (const [house, houseinfo] of Object.entries(V.pchousing))
		{
			for (const [room, roominfo] of Object.entries(setup.ob_housing.plans[houseinfo.plan].rooms))
			{
				const roomclass = setup.ob_housing.room_class_raw(house, room);
				const classinfo = setup.ob_housing.roomClasses[roomclass];
				if (classinfo.furnitureBase?.includes(thing))
					return true;
