setup.ob_locationInventory.bed = function(location)
{
    let bed = this.category_item(location, "bed");
    if (!bed && ["dorm", "greekroom"].includes(location))
        return "dorm room cot";
    else
        return bed?.item;
}

setup.ob_locationInventory.has_fridge = function()
{
    return this.has_anywhere("minifridge") || this.has_anywhere("refrigerator");
}

setup.ob_locationInventory.packed_furniture = function()
{
    return this.contents("packed");
}

setup.ob_locationInventory.packable_furniture = function(location = null)
{
    if (location == null)
        location = this.current_location() || this.last_location();

    if (!location) return [];

    let contents = this.contents(location);
    return contents.filter(thing => this.can_pack(location, thing));
}

setup.ob_locationInventory.can_pack = function(location, thing)
{
    const info = setup.ob_dormstuff[thing.item];

    if (!info || info.universal || info.builtIn) return false;

	if (info.collectedOn && this.can_act_as_container(info.collectedOn)) return false;

    return true;
}

setup.ob_locationInventory.can_unpack = function(location, thing)
{
    const info = setup.ob_dormstuff[thing.item];

    if (!info || info.builtIn) return false;

	if (info.collectedOn && this.can_act_as_container(info.collectedOn)) return false;

    let housingtype;
    if (["dorm", "greekroom", "universal", "packed"].includes(location))
        housingtype = location;
    else if (V.housing)
    {
        housingtype = setup.ob_housing.buildings[V.housing.building].placeType;

        const rclass = setup.ob_housing.this_room_class();
        const allowedfurniture = [...(setup.ob_housing.roomClasses[rclass].furnitureNPC || []), ...(setup.ob_housing.roomClasses[rclass].furnitureAdditional || [])];

        if (info.addHousingFurniture && !allowedfurniture.includes(info.addHousingFurniture))
            return false;

        if (info.requiredHousingFurniture)
        {
            const flags = setup.ob_housing.get_flags(V.housing.key, V.housing.roomID, V.housing.owner);
            if (!flags.includesAny(info.requiredHousingFurniture))
                return false;
        }
    }

    if (info.housingTypes && !info.housingTypes.includes(housingtype))
        return false;

    if (setup.ob_locationInventory.has(location, thing.item, false, false) && !info.canDuplicate)
        return false;

    return true;
}

setup.ob_locationInventory.unpackable_furniture = function()
{
    return this.packed_furniture().filter(thing => this.can_unpack(this.current_location(), thing));
}

setup.ob_locationInventory.can_act_as_container = function(key)
{
	const info = setup.ob_dormstuff[key];
	return info && !info.universal && !info.builtIn;
}

setup.ob_locationInventory.all_housing_locations = function(location)
{
	// takes one location (something like "Apartment 101:living room") and will return all locations matching "Apartment 101"

	let key = location.substring(0, location.indexOf(":"));
	if (key == -1) return [location];
	return Object.keys(V.LocationInventory).filter(okey => okey.indexOf(key) == 0);
}

setup.ob_locationInventory.has_multiple_of_item = function(location, thing)
{
	const key = typeof thing == "string" ? thing : thing.item;
	let count = 0;
	for (const loc of this.all_housing_locations(location))
		if (this.has(loc, thing))
		{
			count++;
			if (count > 1)
				return true;
		}
	return false;
}

setup.ob_locationInventory.has_multiple_of_category = function(location, category)
{
	let count = 0;
	for (const loc of this.all_housing_locations(location))
		if (this.category_item(loc, category))
		{
			count++;
			if (count > 1)
				return true;
		}
	return false;
}

setup.ob_locationInventory.food_stash = function(location = setup.ob_locationInventory.myloc(), loctags = V.lastloctags)
{
	if (typeof loctags == "string") // passage, probably
		loctags = Story.get(loctags)?.tags || [];

	const locflags = setup.ob_housing.flags_here(); // todo: look up based on location to be consistent with the rest of this method being present location agnostic
	let dryfoods, perishablefoods, minimumstock;
	if (location == "dorm" || location == "greekroom")
		dryfoods = true;
	else
		dryfoods = locflags.includes("food storage");

	if (location == "dorm" || location == "greekroom")
		perishablefoods = this.has(location, "minifridge");
	else
		perishablefoods = locflags.includesAny(["minifridge", "refrigerator"]);

	minimumstock = this.has(location, "smart fridge") || (loctags.includesAll(["greekhouse", "roomtypekitchen"]) && V.greekhouse == V.pchouse && setup.ob_houses.has_upgrade("smart fridge"));

	if (dryfoods && !V.dormfoodstash)
		V.dormfoodstash = {};
	if (perishablefoods && !V.dormfridge)
		V.dormfridge = {};
	if (minimumstock && !V.specialfoodstash)
		V.specialfoodstash = {};

	if (minimumstock)
		setup.ob_houses.restock_free_basic_ingredients();

	let retval = {};
	if (dryfoods)
		for (const [food, qty] of Object.entries(V.dormfoodstash))
			retval[food] = qty;
	if (perishablefoods)
		for (const [food, qty] of Object.entries(V.dormfridge))
			retval[food] = qty;
	if (minimumstock)
		for (const [food, qty] of Object.entries(V.specialfoodstash))
			if (!retval[food])
			retval[food] = Infinity;

	return retval;
}

setup.ob_locationInventory.food_quantity = function(food, location = setup.ob_locationInventory.myloc(), tags = V.lastloctags)
{
	let stored = this.food_stash(location, tags);
	if (!stored[food])
		return 0;
	else
		return stored[food];
}

setup.ob_locationInventory.add_food = function(item, qty = 1)
{
	const foodinfo = setup.ob_food[item];
	let storage = foodinfo.flags?.includes("nonperishable") ? "dormfoodstash" : "dormfridge";

	if (!V[storage]) V[storage] = {};

	if (!V[storage][item])
		V[storage][item] = qty;
	else
		V[storage][item] += qty;

	return V[storage][item];
}

setup.ob_locationInventory.remove_food = function(item, qty = 1)
{
	const foodinfo = setup.ob_food[item];
	let storage = foodinfo.flags?.includes("nonperishable") ? "dormfoodstash" : "dormfridge";

	if (!V[storage]?.[item])
		return 0;
	else
	{
		V[storage][item] -= qty;
		if (V[storage][item] <= 0)
		{
			delete V[storage][item];
			return 0;
		}
	}

	return V[storage][item];
}

setup.ob_locationInventory.pack_everything_at_housing = function(hkey)
{
	// pack everything at locationinventory matching this housing key

	if (!V.LocationInventory) return;

	for (const key of Object.keys(V.LocationInventory).filter(k => k.indexOf(hkey + ":") == 0))
	{
		V.LocationInventory[key].forEach(item => this.add("packed", item));
		delete V.LocationInventory[key];
	}
}

setup.ob_locationInventory.pack_orphaned_items = function()
{
	// find items that are in a no-longer-valid location and put them in packed inventory
	if (!V.LocationInventory || !V.pchousing) return;
	const ignore = ["packed", "universal", "dorm", "greekroom"];
	for (const key of Object.keys(V.LocationInventory).filter(k => !ignore.includes(k) && k.indexOf(":") > 0))
	{
		let hkey = key.substring(0, key.indexOf(":"));
		if (!(hkey in V.pchousing))
		{
			console.error(`Packing inventory from invalid inventory location ${key}`);
			V.LocationInventory[key].forEach(item => this.add("packed", item));
			delete V.LocationInventory[key];
		}
	}
}
