Macro.add('viewperson', {
	skipArgs : true,
	tags     : [],
	handler  : function () {
		try {
            let person = this.payload[0].args.raw;
            if (person.substring(0, 1) == "$" || person.substring(0, 1) == "_")
                person = State.getVar(person);
            else
                person = Scripting.evalJavaScript(person);

            if (typeof person == "object")
			{
				if (person.temporary)
				{
					// handle temporary NPCs that don't get a link
					let gender = person.gender;
					let style = '"color: ' + setup.get_color(gender + "emlink") + ';"';
					jQuery(this.output).wiki('<span style=' + style + '>' + this.payload[0].contents + '</span>');
					return;
				}
                person = person.person;
			}
            else if (person in setup.people_niches())
                person = setup.people_niches()[person];

            person = setup.people.get_name(person);
            let name = setup.people.is_known(person) ? setup.people.fullname(person) : setup.people.anonymous_name(person);
			let gender = setup.people.pronouns(person).gender;

			let openelement = "";
			let onclick = '"SugarCube.setup.ob_display_npc_dialog(\'' + person.split('\'').join('_apos_').split('&#39;').join('_apos_') + '\', \'' + name.split('\'').join('_apos_').split('&#39;').join('_apos_') + '\')"';
			let style = '"color: ' + setup.get_color(gender + "emlink") + ';"';
			T.npchovertooltip = setup.ob_get_tooltip_person(person);

			openelement += '<a href="#" onclick=' + onclick + ' class="nokeys" style=' + style + '>';
			let closeelement = '</a>';

			if (setup.pc().equals(person))
			{
				openelement = "";
				closeelement = "";
			}

			for (var i = 0, len = this.payload.length; i < len; ++i) {
				{
					let payload = openelement + this.payload[i].contents + closeelement;
					if (window.matchMedia('(hover: hover)').matches && !setup.pc().equals(person))
					{
						payload = '<<hovertip _npchovertooltip null tooltip-npc>>' + payload + '<</hovertip>>';
					}
					jQuery(this.output).wiki(payload);
					break;
				}
			}
		}
		catch (ex) {
			return this.error('view person link error: ' + ex.message);
		}
	}
});

