Macro.add(['enginegoto', 'egoto', 'go'], {
	handler  : function () {
		try {
            if (this.args.length === 0) {
				return this.error('no passage specified');
			}

			let passage;

			if (typeof this.args[0] === 'object') {
				// Argument was in wiki link syntax.
				passage = this.args[0].link;
			}
			else {
				// Argument was simply the passage name.
				passage = this.args[0];
			}

			if (!Story.has(passage)) {
				return this.error(`passage "${passage}" does not exist`);
			}
			Engine.play(passage);
		}
		catch (ex) {
			return this.error('malformed egoto or bad passage "' + passage + '": ' + ex.message);
		}
	}
});

Macro.delete(["button", "link"]);
Macro.add(['button', 'link'], {
	isAsync : true,
	tags    : null,

	handler() {
		if (this.args.length === 0) {
			return this.error(`no ${this.name === 'button' ? 'button' : 'link'} text specified`);
		}

		const $link = jQuery(document.createElement(this.name === 'button' ? 'button' : 'a'));
		let passage, text, emoji, emojifrom, noemoji, shop, kink;
		const noemojitext = ["Continue", "Next"];

		if (typeof this.args[0] === 'object') {
			if (this.args[0].isImage) {
				// Argument was in wiki image syntax.
				const $image = jQuery(document.createElement('img'))
					.attr('src', this.args[0].source)
					.appendTo($link);

				$link.addClass('link-image');

				if (this.args[0].hasOwnProperty('passage')) {
					$image.attr('data-passage', this.args[0].passage);
				}

				if (this.args[0].hasOwnProperty('title')) {
					$image.attr('title', this.args[0].title);
				}

				if (this.args[0].hasOwnProperty('align')) {
					$image.attr('align', this.args[0].align);
				}

				passage = this.args[0].link;
				text = this.args[0].text;
				emoji = this.args[0].emoji;
				emojifrom = this.args[0].emojifrom;
				noemoji = this.args[0].noemoji;
				shop = this.args[0].shop;
				kink = this.args[0].kink;
			}
			else {
				// Argument was in wiki link syntax.
				$link.append(document.createTextNode(this.args[0].text));
				passage = this.args[0].link;
				text = this.args[0].text;
				emoji = this.args[0].emoji;
				emojifrom = this.args[0].emojifrom;
				noemoji = this.args[0].noemoji;
				shop = this.args[0].shop;
				kink = this.args[0].kink;
			}

		}
		else {
			// Argument was simply the link text.
			$link.wikiWithOptions({ profile : 'core' }, this.args[0]);
			text = this.args[0];
			passage = this.args.length > 1 ? this.args[1] : undefined;
			emoji = this.args.length > 2 ? this.args[2] : undefined;
		}

		if (emojifrom && Story.has(emojifrom))
			emoji = setup.ob_passage_emoji(emojifrom);

		if (shop)
		{
			if (!passage) passage = "ShopMenu";
			if (!emoji) emoji = setup.ob_shops.db[shop].emoji;
		}

		if (passage != null) { // lazy equality for null
			$link.attr('data-passage', passage);

			if (Story.has(passage)) {
				$link.addClass('link-internal');

				if (Config.addVisitedLinkClass && State.hasPlayed(passage)) {
					$link.addClass('link-visited');
				}

				if (emoji == undefined && !noemojitext.includes(text)) emoji = setup.ob_passage_emoji(passage);
				if (!kink) kink = setup.ob_passage_kink(passage);

			}
			else {
				$link.addClass('link-broken');
			}
		}
		else {
			$link.addClass('link-internal');
		}

		if (tags().includesAny("suppressemoji"))
			noemoji = true;
		else if (tags().includes("event"))
			noemoji = !tags().includes("dialogue");
		if (emoji && !noemoji)
		{
			$link.data('emoji', emoji);
		}
		if (kink && passage && !tags().includes("kinkconfirm"))
		{
			$link.data('kink', kink);
			if (!V.kinklinks) V.kinklinks = [];
			V.kinklinks.push({text: text, passage: passage, kink: kink});
		}
		if (shop)
		{
			$link.data('shop', shop);
			V.shop = shop;
		}

		$link
			.addClass(`macro-${this.name}`)
			.ariaClick({
				namespace : '.macros',
				role      : passage != null ? 'link' : 'button',
				one       : passage != null
			}, this.createShadowWrapper(
				this.payload[0].contents !== ''
					? () => Wikifier.wikifyEval(this.payload[0].contents.trim())
					: null,
				passage != null
					? () => Engine.play(passage)
					: null
			))
			.appendTo(this.output);
	}
});

