// #region tabs

Macro.add('tabgroup', {
	tags     : ['tab'],
	handler  : function () {
		try {
			if (!setup.ob_savedTabs) setup.ob_savedTabs = {};

			const groupID = this.args[0];

			const tabs = [];
			for (const payloadel of this.payload)
				if (payloadel.name == "tab")
				{
					const label = payloadel.args[0];
					const emoji = payloadel.args[1];
					const code = payloadel.args[2];
					const condition = payloadel.args.length < 4 ? true : payloadel.args[3];

					if (condition)
					{
						tabs.push({
							label: label,
							emoji: emoji,
							code: code,
							contents: payloadel.contents,
						});
					}
				}

			if (tabs.length == 0)
				return this.error("tabgroup has no tabs");

			let currentTabIndex = (groupID && setup.ob_savedTabs[groupID]) || 0;
			if (currentTabIndex < 0 || currentTabIndex >= tabs.length) currentTabIndex = 0;

			V.dHist = "";
			V.dialogCloseFn = function(){setup.ob_debug.cDialogHist(V.dHist); delete V.dHist};

			let $wrapper = $(document.createElement('div'))
				.addClass(groupID ? `tabgroup tabgroup-${groupID}` : `tabgroup`);

			let $tabbar = $(document.createElement('div'))
				.addClass(`tabgroup-bar`).appendTo($wrapper);

			tabs.forEach((tab, i) => {
				let $btn = $(document.createElement('button'))
					.addClass(`tabgroup-button`)
					.attr({
						'data-tab-index': i,
						'type': "button",
						'role': "tab",
						'aria-selected': i == currentTabIndex ? "true" : "false",
					})
					.toggleClass(`active`, i == currentTabIndex)
					.appendTo($tabbar);

				if (tab.emoji)
				{
					$(document.createElement('span'))
						.addClass(`tabgroup-button-emoji`)
						.text(tab.emoji)
						.appendTo($btn);
				}

				$(document.createElement('span'))
					.addClass(`tabgroup-button-label`)
					.text(tab.label)
					.appendTo($btn);
			});

			let $content = $(document.createElement('div'))
				.addClass(`tabgroup-content`)
				.attr({
					'role': "tabpanel",
				})
				.appendTo($wrapper);

			const renderTab = (index) => {
				$content.empty()
					.wiki(tabs[index].contents);
			};

			if (groupID) setup.ob_savedTabs[groupID] = currentTabIndex;
			renderTab(currentTabIndex);

			$tabbar.on('click', '.tabgroup-button', function() {
				const i = parseInt(this.getAttribute('data-tab-index'));

				if (i == currentTabIndex) return;

				$tabbar.find(".tabgroup-button").removeClass("active").attr("aria-selected", "false");

				$(this).addClass("active").attr("aria-selected", "true");

				if (groupID) setup.ob_savedTabs[groupID] = i;
				currentTabIndex = i;

				if (tabs[i].code && V.dHist) V.dHist += tabs[i].code;

				renderTab(i);
			});

			$(this.output).append($wrapper);
		}
		catch (ex) {
			return this.error('invalid tabgroup: ' + ex.message);
		}
	}
});

Macro.add('accordion', {
	tags     : null,
	handler  : function () {
		try {

			if (this.args.length == 0)
				return this.error("accordion has no label");

			const label = this.args[0];
			const startOpen = this.args[1] ?? false;
			const contents = this.payload[0].contents;

			let $wrapper = $(document.createElement('div'))
				.addClass('accordion')
				.toggleClass('open', startOpen);

			let $header = $(document.createElement('div'))
				.addClass('accordion-header')
				.appendTo($wrapper);

			$(document.createElement('span'))
				.addClass('accordion-header-label')
				.text(label)
				.appendTo($header);

			$(document.createElement('span'))
				.addClass('accordion-minrestore')
				.text(String.fromCharCode(0xe81c))
				.appendTo($header);

			let $contents = $(document.createElement('div'))
				.addClass('accordion-contents-wrapper')
				.appendTo($wrapper);

			$(document.createElement('div'))
				.addClass('accordion-contents')
				.appendTo($contents)
				.wiki(contents);

			$header.on('click', function(event) {
				if ($(event.target).is('a, input, label, select, textarea, button, .link-internal')) {
					return;
				}
				$wrapper.toggleClass('open');
			});

			$(this.output).append($wrapper);
		}
		catch (ex) {
			return this.error('invalid accordion: ' + ex.message);
		}
	}
});
/* twine-user-script #49: "miscinventory.js" */
setup.miscinventory = function()
{
    return V.miscinventory || {};
}

setup.miscinventory_count = function(item)
{
    return this.miscinventory()[item] ? this.miscinventory()[item].count : 0;
}

setup.ob_miscinventory_add = function(item, count = 1)
{
    if (!V.miscinventory) V.miscinventory = {};
    let key, itemobj;
    if (typeof item == "object")
    {
        key = item.item;
        itemobj = item;
        if (!itemobj.count) itemobj.count = 0;
        delete itemobj.item;
    }
    else
    {
        key = item;
        itemobj = {count: setup.miscinventory_count(key) || 0};
    }
    itemobj.count += count;
    V.miscinventory[key] = itemobj;
    return itemobj;
}

setup.ob_miscinventory_remove = function(item, count = 1)
{
    if (!V.miscinventory) return;
    let key = typeof(item) == "object" ? item.key : item;
    if (!V.miscinventory[key]) return;
    V.miscinventory[key].count -= count;
    if (V.miscinventory[key].count <= 0)
    {
        delete V.miscinventory[key];
        return null;
    }
    else
        return V.miscinventory[key];
}

setup.ob_medication = function()
{
    const retval = [];
    for (let item of Object.keys(setup.ob_miscitems).filter(item => setup.ob_miscitems[item].medication))
        if (this.miscinventory_count(item))
            retval.push(item);
    return retval;
}
/* twine-user-script #50: "namespace.js" */
function makeGlobalOne(object, name, global = window) {
	if (!object || typeof object !== "object") return console.log("invalid object: "+name);
	if (!name || typeof name !== "string") return console.log("invalid name");

	if (global[name] === object) return console.log(name, "is already global");
	if (global[name]) return console.log("name already taken:", name);

	Object.defineProperty(global, name, { value: object, writeable: false })
	return global[name];
}

function makeGlobal(objects) {
	if (!objects || typeof objects !== "object") return;
	for (const name in objects) makeGlobalOne(objects[name], name);
}

