				// and then, sometimes, another event will fire that doesn't set $attemptednavigation
				// but does use the <<continuelink>> macro
				// and the result of this edge case is the player gets warped somewhere unexpected
				// the next time <<continuelink>> is used
				// but here should be a successful navigation, where I think it's logically sound to clear it out
				// if it isn't, I'm sure I'll notice lol
				delete State.variables.attemptednavigation;
				delete State.variables.usealtlocimg;
			}
		}

		return false;
	}
	catch (error)
	{
		console.log("Error in navigation override:")
		console.error(error);
		return false;
	}
