if (!("ob_needs" in setup)) setup.ob_needs = {};

setup.ob_needs.decrease_need = function(need, amt)
{
    if (!setup.ob_needs.plainlist.includes(need)) return;

    if (amt < 0) amt = -amt;

    if (typeof amt != "number") return;

    State.variables.pcneeds[need] -= amt;
    if (State.variables.pcneeds[need] <= 0)
    {
        State.variables.pcneeds[need] = 0;
    }
    const newamt = State.variables.pcneeds[need];

    let pc = setup.pc();
    setup.pc().sync_pc_fleeting_stats();

    if (newamt == 0)
    {
        if (need == "Hygiene")
            setup.inclinations.unlock_with_req("Natural Odor");
        else if (need == "Attention")
            setup.inclinations.unlock_with_req("Loner");
    }
}

setup.ob_needs.increase_need = function(need, amt, maxamt=1000)
{
    if (!setup.ob_needs.plainlist.includes(need)) return;

    const affected_by_composure = ["Relaxation", "Attention"];
    if (affected_by_composure.includes(need))
    {
        let composure = this.get_need("Composure");
        if (composure <= 250)
            amt *= 0.33;
        else if (composure <= 500)
            amt *= 0.667;
        else if (composure < 750)
            amt *= 0.85;
    }

    if (need == "Arousal" && V.pc.has_inclination("Fur Enthusiast") && V.pc.wearing_fur())
    {
        amt *= 1.25;
    }

    if (typeof amt != "number") return;

    State.variables.pcneeds[need] += amt;
    if (State.variables.pcneeds[need] > maxamt)
    {
        State.variables.pcneeds[need] = maxamt;
    }

    if (need == "Release" && State.variables.pcneeds[need] > 250 && State.variables.pchorny > 0)
    {
        State.variables.pchorny = V.pc.has_inclination("Always Horny") ? 1 : 0;
    }
    else if (need == "Release" && State.variables.pcneeds[need] > 0 && State.variables.pchorny > 1)
    {
        State.variables.pchorny = 1;
    }
    else if (need == "Bladder")
    {
        delete State.variables.passnextbladdercheck;
        delete State.variables.bladderchecks;
    }
    else if (need == "Hygiene")
    {
        setup.pc().clean_cum_covering();
    }

    let pc = setup.pc();
    if (need == "Pain" && pc.has_inclination("Masochist"))
    {
        this.increase_need("Arousal", amt / 3);
    }
    else if (need == "Humiliation" && pc.has_inclination("Humiliation Kink"))
    {
        this.increase_need("Arousal", amt / 3);
    }

    setup.pc().sync_pc_fleeting_stats();
}

setup.ob_needs.get_need = function(need)
{
    need = need.toUpperFirst();
    return State.variables.pcneeds[need];
}

setup.ob_needs.decay_need = function(need, amt)
{
    if (V.pausedneeds && V.pausedneeds.includes(need)) return;

    // auto-pause certain needs under certain circumstances

    if (V.exhibitionsneak && need == "Arousal") return;

    if (V.hangout && ["Drunkenness", "Arousal", "Attention", "Relaxation"].includes(need) && !tags().includes("postencounter"))
        return;

    let cur = V.pcneeds[need];

    amt *= V.optneeddecaymultiplier;

    if (need == "Attention")
    {
        if (setup.pc().has_inclination("Loner")) amt *= 0.8;
        if (setup.pc().has_inclination("Gregarious")) amt /= 0.8;
    }
    else if (need == "Hygiene" && setup.pc().wearing_dirty_clothes())
    {
        amt *= 2;
    }
    else if (need == "Rest" && V.caffeine)
    {
        if (V.caffeine >= 800)
            amt *= 1.5;
        else if (V.caffeine >= 600)
            amt *= 1.3;
        else if (V.caffeine >= 400)
            amt *= 1.2;
        else if (V.caffeine >= 200)
            amt *= 1.1;
    }

    let trimester = setup.ob_pregnancy.trimester(V.pc);
    if (trimester > 0)
    {
        if (need == "Food")
        {
            if (trimester == 1) amt *= 1.1;
            else if (trimester == 2) amt *= 1.2;
            else if (trimester == 3) amt *= 1.3;
        }
        else if (need == "Rest")
        {
            if (trimester == 1) amt *= 1.2;
            else if (trimester == 2) amt *= 1.05;
            else if (trimester == 3) amt *= 1.3;
        }
        else if (need == "Bladder")
        {
            if (trimester == 1) amt *= 1.1;
            else if (trimester == 2) amt *= 1.2;
            else if (trimester == 3) amt *= 1.4;
        }
    }

    if (cur == 0) return;
    else if (cur < amt) amt = cur;

    if (need == "Arousal")
    {
        if (setup.ob_equipped_wearable_toys().length > 0 || (V.riverrat && V.riverrat.working)) amt /= 10;
        let min = 100 * V.pchorny;
        if (cur - min < amt) amt = cur - min;
    }

    if (need == "Release" && setup.pc().has_inclination("Slut")) amt *= 2;
    else if (need == "Release" && setup.pc().has_any_inclination(["Chaste", "Asexual"])) amt /= 2;

    this.decrease_need(need, amt);

    // translate fleeting stats into their longer term effects as they decay
    if (need == "Arousal")
    {
        this.decrease_need("Release", amt / 5);
    }
    else if (need == "Satisfaction")
    {
        this.increase_need("Composure", amt / 4);
        this.increase_need("Release", amt * 1.5);
        if (V.pc.has_inclination("No Rest for the Wicked"))
        {
            if (!V.bonusrest) V.bonusrest = 0;
            if (V.bonusrest < 1000)
            {
                V.bonusrest += amt;
                this.increase_need("Rest", amt / 10);
            }
        }
    }
    else if (need == "Pain")
    {
        this.decrease_need("Relaxation", amt / 3);
    }
    else if (need == "Humiliation")
    {
        this.decrease_need("Composure", amt / 4);
    }
}

setup.ob_needs.eat = function(food)
{
    let foodobj = typeof food == "object" ? food : setup.ob_food[food];
    let prevneed = this.get_need("Food");
    this.increase_need("Food", foodobj["restore hunger"]);
    if ("reduce bladder" in foodobj)
    {
        this.decrease_need("Bladder", foodobj["reduce bladder"]);
    }
    if ("restore energy" in foodobj)
    {
        let restamt = foodobj["restore energy"];
        if (!V.caffeine)
            V.caffeine = restamt;
        else
        {
            V.caffeine = Math.min(V.caffeine + restamt, 1000);
            if (V.caffeine >= 1000)
                restamt = 0;
            else if (V.caffeine >= 800)
                restamt *= 0.1;
            else if (V.caffeine >= 600)
                restamt *= 0.3;
            else if (V.caffeine >= 400)
                restamt *= 0.65;
            else if (V.caffeine >= 200)
                restamt *= 0.8;
            else if (V.caffeine >= 100)
                restamt *= 0.9;
        }
        this.increase_need("Rest", restamt);
    }
    if ("restore relaxation" in foodobj)
    {
        this.increase_need("Relaxation", foodobj["restore relaxation"]);
    }
    if ("plumpness" in foodobj && prevneed > 500)
    {
        let fitness = V.fitness;
        if (!("plumpness" in fitness))
            fitness.plumpness = foodobj.plumpness;
        else
            fitness.plumpness += foodobj.plumpness;
    }

    if (foodobj.flags.includes("muscle boost"))
    {
        V.proteinshake = true;
    }

    if (foodobj.flags.includes("warming"))
    {
        V.warmingbuff = V.warmingbuff ? V.warmingbuff + 120 : 120;
    }
    if (foodobj.flags.includes("cooling"))
    {
        V.coolingbuff = V.coolingbuff ? V.coolingbuff + 120 : 120;
    }
}

setup.ob_needs.drink = function(drink, divide = 1)
