setup.ob_needs.sleep = function(minutes, sleeprate = 125, advancetime = true)
{
    let pc = setup.pc();
    if ((setup.ob_is_homebase() || V.postencounterpassage) && V.sleepoutfit)
    {
        if (pc.has_outfit(V.sleepoutfit) && setup.ob_is_homebase())
        {
            State.setVar("$prebedclothes", [...pc.clothes]);
            pc.wear_outfit(V.sleepoutfit);
        }
    }

    let extrarelax = 0;
    let extraarousal = 0;
    if (["YourDorm", "YourGreekHouseRoom", "HousingRoom"].includes(V.location))
    {
        extrarelax = setup.ob_dormstuff_bonus('relaxationPerSleepHour');
        extraarousal = setup.ob_dormstuff_bonus('arousalPerSleepHour');
    }

    let ttbladderlow = this.minutes_to_drain("Bladder", 100, true);
    let ttfoodlow = this.minutes_to_drain("Food", 100, true);

    if (ttfoodlow > 0 && ttfoodlow < minutes)
    {
        minutes = ttfoodlow;
        State.setVar("$wakemsg", "You wake up early feeling urgently hungry.");
    }
    if (ttbladderlow > 0 && ttbladderlow < minutes)
    {
        minutes = ttbladderlow;
        State.setVar("$wakemsg", "You wake up early with the urgent need to pee.");
    }

    let recovery = (sleeprate / 60) * minutes;
    if (extrarelax)
    {
        extrarelax = extrarelax * (minutes / 60);
        this.increase_need("Relaxation", extrarelax);
    }
    if (extraarousal)
    {
        extraarousal = extraarousal * (minutes / 60);
        this.increase_need("Arousal", extraarousal);
    }
    this.increase_need("Rest", recovery);

    if (V.caffeine)
    {
        V.caffeine -= recovery;
        if (V.caffeine <= 0) delete V.caffeine;
    }

    State.setVar("$sleeping", true);

    if (advancetime) setup.ob_time.advance_time(minutes);
    delete State.variables.sleeping;
}

