setup.ob_needs.minutes_to_drain = function(need, level = 0, sleeping = false)
{
    const pcneeds = V.pcneeds;
    let cur = pcneeds[need];
    if (cur <= level)
    {
        return 0;
    }
    else
    {
        const rates = sleeping ? setup.ob_time.sleep_decay_time : setup.ob_time.natural_decay_time;
        let rate = rates[need];
        if (rate <= 0) return 0;
        let dpm = 1000 / rate;
        return Math.ceil((cur - level) / dpm);
    }
}

