if (!setup.ob_nPCSimulation) setup.ob_nPCSimulation = {};

setup.ob_nPCSimulation.logEvents = true;
setup.ob_nPCSimulation.logPosts = false;
setup.ob_nPCSimulation.maxPairingAttempts = 5;

setup.ob_nPCSimulation.valid_events = function()
{
    // assemble a list of all valid events for the day
    const retval = [];
    const people = Object.keys(V.people);
    const peopleCanSim = people.filter(p => this.will_simulate(p, true));
    const peopleWithNPCRels = people.filter(p => V.people[p].NPCRelationships && Object.keys(V.people[p].NPCRelationships).length > 0);
    const peopleCanAddRel = peopleCanSim.filter(p => this.can_add_new_relationship(p));

    const exclude = []; // main exclude list... one event per npc per day (avoids logic collisions)

    let slicespassed = setup.ob_time.day_slices_passed();

    let setConfigForNPC = function(mainnpc, config)
    {
        if (!("simulate" in config)) config.simulate = true;
        if (!("specialok" in config)) config.specialok = true;

        if (config.hasnosimflagwith)
            config.hasnosimflagwith = [config.hasnosimflagwith, mainnpc];
        if (config.hasnosimflagswith)
            config.hasnosimflagswith = [config.hasnosimflagswith, mainnpc];
        if (config.npcwillingsex)
        {
            if (typeof config.npcwillingsex != "string")
                config.npcwillingsex = mainnpc;
            else if (["hand", "oral", "anal", "full"].includes(config.npcwillingsex))
                config.npcwillingsex = [mainnpc, config.npcwillingsex];
        }
        if (config.attractionbtnnpcs && typeof config.attractionbtnnpcs != "string")
            config.attractionbtnnpcs = mainnpc;
        if (config.npcassociation && typeof config.npcassociation != "string")
            config.npcassociation = mainnpc;
        if (config.nonpcrel && typeof config.nonpcrel != "string")
            config.nonpcrel = mainnpc;
        if (config.assocgt && !Array.isArray(config.assocgt))
            config.assocgt = [mainnpc, config.assocgt];
        if (config.assoclt && !Array.isArray(config.assoclt))
            config.assoclt = [mainnpc, config.assoclt];
        if (config.relhealthgt && !Array.isArray(config.relhealthgt))
            config.relhealthgt = [mainnpc, config.relhealthgt];
        if (config.relhealthlt && !Array.isArray(config.relhealthlt))
            config.relhealthlt = [mainnpc, config.relhealthlt];
        if (config.hassimflagwith)
            config.hassimflagwith = [config.hassimflagwith, mainnpc];
        if (config.hassimflagofagewith)
            config.hassimflagofagewith = [...config.hassimflagofagewith, mainnpc];
        if (config.cheatingpartner)
            config.cheatingpartner = mainnpc;

        return config;
    }

    for (const [event, eventinfo] of this.sort_events())
    {
        try
        {
            let currentinstances = this.event_instances(event) || 0;
            if (    !eventinfo.manual &&
                    (!eventinfo.maxInstances || currentinstances < eventinfo.maxInstances) &&
                    (this.event_roll(event)) &&
                    (!eventinfo.fromDay || V.gameday >= eventinfo.fromDay) &&
                    (!eventinfo.untilDay || V.gameday < eventinfo.untilDay) &&
                    (!eventinfo.checkvar || Scripting.evalTwineScript(eventinfo.checkvar)))
            {
                let maxinstances = eventinfo.maxInstances || 1;
                let basechance = eventinfo.chance ?? 1;
                let justpost = eventinfo.justPost;

                let timeweight = eventinfo.timeWeight || setup.ob_nPCSimulation.default_time_weight;
                let ftimeweight = [];
                for (let i = 0; i < timeweight.length; i += 2)
                    if (!slicespassed.includes(timeweight[i]))
                        ftimeweight.push(timeweight[i], timeweight[i + 1]);

                if (ftimeweight.length == 0) continue;

                let lastloopsuccess = true;

                for (let i = currentinstances; i < maxinstances; i++) // iterate through the maximum number of instances of this event per day
                {
                    if (State.random() > this.instance_chance(i, maxinstances) * basechance || !lastloopsuccess) break; // instances have decreasing likelihood
                    lastloopsuccess = false;

                    let thisevent = Object.assign({}, eventinfo);
                    thisevent.key = event;

                    let attemptedprimaries = [];
                    const maxattempts = setup.ob_nPCSimulation.maxPairingAttempts;
                    let found = false;

                    for (let attempts = 0; attempts < maxattempts; attempts++) // for the purposes of finding paired NPCs, allow multiple attempts to find pairs rather than discarding the whole event if our first try doesn't succeed
                    {
                        let thisexclude = [];

                        if (thisevent.findnpc)
                        {
                            let config = Object.assign({}, thisevent.findnpc);

                            config.exclude = [...(config.exclude || []), ...exclude, ...thisexclude, ...attemptedprimaries];

                            if (!("simulate" in config) && !justpost) config.simulate = true;
                            if ("specialok" in eventinfo)
                            {
                                config.specialok = eventinfo.specialok;
                            }
                            else if (!("specialok" in config))
                            {
                                config.specialok = justpost;
                            }

                            let searchpool = people;
                            if (config.hasanynpcrel) searchpool = peopleWithNPCRels;
                            else if (config.canaddrelationship) searchpool = peopleCanAddRel;
                            if (eventinfo.prefilter) searchpool = eventinfo.prefilter(searchpool);

                            thisevent.npc1 = setup.ob_events.pick_person(config, searchpool);
                            //if (!thisevent.npc1) console.log("npc1 fail:", event);

                            if (!thisevent.npc1) break; // break rather than continue, because failing to find a primary NPC means this event is no good

                            thisexclude.push(thisevent.npc1);

                            attemptedprimaries.push(thisevent.npc1);
                        }

                        if (thisevent.findnpc2)
                        {
                            let config = Object.assign({}, thisevent.findnpc2);

                            config.exclude = [...(config.exclude || []), ...exclude, ...thisexclude];

                            config = setConfigForNPC(thisevent.npc1, config);

                            let thispeople = people;
                            if (config.findmatchingrel)
                                thispeople = this.npcs_of_relationship_types(thisevent.npc1, thisevent.findnpc.hasanynpcrel);

                            thisevent.npc2 = setup.ob_events.pick_person(config, thispeople);

                            if (!thisevent.npc2) continue; // failed to find a pairing, so try again with a different primary NPC

                            thisexclude.push(thisevent.npc2);
                        }

                        if (thisevent.findnpc3)
                        {
                            let config = Object.assign({}, thisevent.findnpc3);

                            config.exclude = [...(config.exclude || []), ...exclude, ...thisexclude];

                            config = setConfigForNPC(thisevent.npc1, config);

                            thisevent.npc3 = setup.ob_events.pick_person(config, people);

                            if (!thisevent.npc3) continue;

                            thisexclude.push(thisevent.npc3);
                        }

                        if (thisevent.findnpc4)
                        {
                            let config = Object.assign({}, thisevent.findnpc4);

                            config.exclude = [...(config.exclude || []), ...exclude, ...thisexclude];

                            config = setConfigForNPC(thisevent.npc1, config);

                            thisevent.npc4 = setup.ob_events.pick_person(config, people);

                            if (!thisevent.npc4) continue;

                            thisexclude.push(thisevent.npc4);
                        }

                        found = true; // we found a valid pair (or group)
                        break;
                    }

                    if (!found) continue;

                    // no more failure points past here, we are definitely adding this event to the queue

                    for (let prospectivenpc of [thisevent.npc1, thisevent.npc2, thisevent.npc3, thisevent.npc4])
                        if (prospectivenpc)
                            exclude.push(prospectivenpc);

                    let rngseed = V.gameday.toString() + (thisevent.npc1 || "") + event;
                    let rng = setup.ob_newRNG(rngseed);

                    thisevent.time = rng.randomrelfreq(ftimeweight);

                    thisevent.storeAs = [
                        thisevent.id,
                        inthash(rngseed),
                        V.year,
                        V.month,
                        V.day,
                        ["morning", "afternoon", "evening", "night"].indexOf(thisevent.time),
                        this.get_advice_id(thisevent.advice),
                    ];
                    for (let key of ["npc1", "npc2", "npc3", "npc4"])
                        if (thisevent[key])
                            thisevent.storeAs.push(this.get_id(thisevent[key]));

                    thisevent.post = setup.ob_dialogue.pick(["elkbook", event], thisevent.npc1, null, setup.ob_newRNG(rngseed))?.line;

                    retval.push(thisevent);
                    lastloopsuccess = true;
                }
            }
        }
        catch (error)
        {
            console.error(`Malformed sim event: "${event}" ${error}`);
        }
    }
    return retval;
}

setup.ob_nPCSimulation.queue_events = function()
{
    // find valid sim events and queue them to execute
    const queued = [];
    let queuedperperson = {};
    const maxqueued = idb.active ? 90 : 30;
    const maxperperson = idb.active ? 9 : 3;
    let valid = setup.ob_shuffle(this.valid_events());
    for (let event of valid)
    {
        if (event.npc1 && queuedperperson?.[event.npc1] && queuedperperson[event.npc1] >= maxperperson) continue;

        let ids = [event.npc1, event.npc2, event.npc3, event.npc4].filter(p => p != undefined);
        if (new Set(ids).size < ids.length)
        {
            console.warn("skipping sim event with duplicate NPC references:", event.id, ids)
            continue;
        }

        let advice = this.event_info(event.id).advice;
        if (!this.wants_advice(event.npc1, advice, event.npc2))
            event.storeAs[6] = 0;

        queued.push(event);

        if (event.npc1)
        {
            if (queuedperperson[event.npc1]) queuedperperson[event.npc1]++;
            else queuedperperson[event.npc1] = 1;
        }

        if (queued.length >= maxqueued) break;
    }

    V.queuedsimevents = queued.map(item => item.storeAs);

    return queued;
}

setup.ob_nPCSimulation.sort_events = function()
{
    // sort the sim event database by first shuffling it and then sorting by priority
    // returns in Object.entries format, so an array of [key, value]
    return Object.entries(setup.ob_nPCSimulation.db)
        .shuffle()
        .sort((a, b) => (b[1].priority ?? 100) - (a[1].priority ?? 100));
}

setup.ob_nPCSimulation.process_manual_event = function(event, npc1, npc2, npc3, npc4)
{
    // process a manual sim event (just advice, as of this writing)
    // meaning this isn't an automatically scheduled event, it's being pushed by something else

    let rngseed = V.gameday.toString() + (npc1 || "") + event;
    let storeAs = [
        this.get_event_id(event),
        inthash(rngseed),
        V.year,
        V.month,
        V.day,
        ["morning", "afternoon", "evening", "night"].indexOf(setup.ob_time.timeofday()),
        0,
    ];
    for (let key of [npc1, npc2, npc3, npc4])
        if (key)
            storeAs.push(this.get_id(key));

    this.process_event(storeAs);
}

setup.ob_nPCSimulation.adviceTypes = ["friendship", "romance", "rivalry", "sex", "inclination", "pregnancy", "abortion", "relationship"];

setup.ob_nPCSimulation.get_advice_id = function(advice)
{
    // turn string advice type into numeric ID
    return this.adviceTypes.indexOf(advice) + 1;
}

setup.ob_nPCSimulation.from_advice_id = function(id)
{
    // turn advice numeric ID into string
    return this.adviceTypes[id - 1];
}

setup.ob_nPCSimulation.instance_chance = function(i, maxinstances)
{
    // the chance of another instance of an event
    let base = 1 + Math.pow(0.5, (maxinstances - 1) / 4);
    return 1 / Math.pow(base, i - 1);
}

setup.ob_nPCSimulation.execute_effects = function(effects, npc1, npc2, npc3, npc4)
{
    // execute whatever changes should be made
    for (const [effect, args] of Object.entries(effects))
    {
        this.execute_effect(effect, args, npc1, npc2, npc3, npc4);
    }
}

setup.ob_nPCSimulation.execute_effect = function(effect, args, npc1, npc2, npc3, npc4)
{
    switch (effect)
    {
        case "addRelationship":
        {
            this.set_relationship(npc1, npc2, args);
            break;
        }
        case "removeRelationship":
        {
            this.clear_relationship(npc1, npc2);
            break;
        }
        case "addInclination":
        {
            let incs = Array.isArray(args) ? args : [args];
            let pdata = setup.people.get_person(npc1);
            if (!pdata.addinclinations) pdata.addinclinations = [];
            incs.forEach(inc => pdata.addinclinations.push(inc));

            break;
        }
        case "removeInclination":
        {
            let incs = Array.isArray(args) ? args : [args];
            let pdata = setup.people.get_person(npc1);
            if (!pdata.subinclinations) pdata.subinclinations = [];
            incs.forEach(inc => pdata.subinclinations.push(inc));

            break;
        }
        case "increaseSkill":
        {
            let skill = args;
            let pdata = setup.people.get_person(npc1);
            if (!pdata.skills) pdata.skills = {};
            let clvl = setup.people.skill_level(npc1, skill);
            if (clvl < 10)
                pdata.skills[skill] = clvl + 1;

            break;
        }
        case "decreaseSkill":
        {
            let skill = args;
            let pdata = setup.people.get_person(npc1);
            if (!pdata.skills) pdata.skills = {};
            let clvl = setup.people.skill_level(npc1, skill);
            if (clvl > 0)
                pdata.skills[skill] = clvl - 1;

            break;
        }
        case "addSimFlag":
        {
            let flags = Array.isArray(args) ? args : [args];
            for (let npc of [npc1, npc2, npc3, npc4])
                if (npc)
                {
                    flags.forEach(flag => this.set_flag(npc, flag, npc == npc1 ? npc2 : npc1));
                }

            break;
        }
        case "remSimFlag":
        {
            let flags = Array.isArray(args) ? args : [args];
            for (let npc of [npc1, npc2, npc3, npc4])
                if (npc)
                {
                    flags.forEach(flag => this.remove_flag(npc, flag, npc == npc1 ? npc2 : npc1));
                }

            break;
        }
        case "gainExperience":
        {
            let skills = Array.isArray(args) ? args : [args];
            for (let npc of [npc1, npc2, npc3, npc4])
                if (npc)
                {
                    skills.forEach(skill => this.gain_experience(npc, skill));
                }

            break;
        }
        case "loseVirginity":
        {
            let parts = Array.isArray(args) ? args : [args];
            for (let npc of [npc1, npc2, npc3, npc4])
                if (npc)
                    parts.forEach(part => setup.people.lose_virginity(npc, part));

            break;
        }
        case "cheat":
        {
            // kind of a meta-effect
            let cheatflag = args[0];
            let npcis = args[1];

            let npcs = npcis.map(i => [npc1, npc2, npc3, npc4][i]);

            this.execute_effect("addSimFlag", cheatflag, ...npcs);
            this.execute_effect("haveSex", undefined, ...npcs);
            this.execute_effect("gainExperience", ["bits", "disinhibition"], ...npcs);

            break;
        }
        case "maybeAddCheatPartner":
        {
            let chance = args[0];
            let npcis = args[1];

            let npcs = npcis.map(i => [npc1, npc2, npc3, npc4][i]);

            if (State.random() < chance)
            {
                setup.ob_relationships.set_cheating_partner(npcs[0], npcs[1]);
            }

            break;
        }
        case "removeCheatPartner":
        {
            setup.ob_relationships.unset_cheating_partner(npc1);
            setup.ob_relationships.unset_cheating_partner(npc2);

            break;
        }
        case "removeAllCheatPartners":
        {
            [npc1, npc2, npc3, npc4].forEach(npc => { if (npc) setup.ob_relationships.unset_cheating_partner(npc) });

            break;
        }
        case "haveSex":
        {
            setup.ob_pregnancy.simulate_npc_sex(npc1, npc2);

            break;
        }
        case "takeMorningAfterPill":
        {
            setup.ob_pregnancy.take_morning_after_pill(npc1);

            break;
        }
        case "takePregnancyTest":
        {
            setup.ob_pregnancy.take_pregnancy_test(npc1);

            break;
        }
        case "endPregnancy":
        {
            setup.ob_pregnancy.remove_pregnancy(npc1);

            break;
        }
        case "giveBirth":
        {
            let pcinvolved = V.pc.equals(setup.ob_pregnancy.donor(npc1));
            let newoffspring = setup.ob_pregnancy.give_birth(npc1);

            if (pcinvolved)
            {
                if (!V.pendingbirths) V.pendingbirths = [];
                V.pendingbirths.push(...newoffspring);
            }
            else
            {
                setup.ob_pregnancy.remove_pregnancy_if_birthed(npc1);
            }

            break;
        }
    }
}

setup.ob_nPCSimulation.process_queued_events = function()
{
    // see which sim events are due to be processed, process them, retain the still-pending ones in the list
    if (!V.queuedsimevents) return;
    let newqueued = [];
    const currentdayslice = setup.ob_time.timeofday();
    const previousdayslice = setup.ob_time.previous_timeofday();
    const slicespassed = setup.ob_time.day_slices_passed();
    for (let queued of V.queuedsimevents)
    {
        let requeue = true;
        if (V.year > queued[2] || (V.year == queued[2] && V.month > queued[3]) || (V.year == queued[2] && V.month == queued[3] && V.day == queued[4]))
        {
            if (!queued[6])  // only process if not awaiting pc advice
            {
                let dayslice = this.get_day_slice(queued[5]);
                if (slicespassed.includes(dayslice))
                {
                    // process the event if we have passed the slice it is in
                    requeue = false;
                    this.process_event(queued);
                }
                else if ((dayslice == currentdayslice && this.event_info(queued[0]).justPost) || (dayslice == previousdayslice && this.event_info(queued[0]).postAhead))
                {
                    let posttime = this.post_time(queued);
                    if (V.hour > posttime[0] || (V.hour == posttime[0] && V.minute >= posttime[1]))
                    {
                        // process the event if it has a post time and we've passed it
                        requeue = false;
                        this.process_event(queued);
                    }
                }
            }
        }
        if (requeue) newqueued.push(queued);
    }
    V.queuedsimevents = newqueued;
}

setup.ob_nPCSimulation.process_surfaced_event = function(event)
{
    // process a sim event that's been surfaced by a narrative event

    this.delete_from_queue(event);
    this.process_event(event);
}

setup.ob_nPCSimulation.events_equal = function(event1, event2)
{
    // test if two events (expecting integer array format) are equal
    for (let i = 0; i < event1.length; i++)
        if (event1[i] != event2[i]) return false;
    return true;
}

setup.ob_nPCSimulation.delete_from_queue = function(event)
{
    // deletes the given event from the queue (expects stored format)
    if (!V.queuedsimevents) return;
    if (typeof event == "object" && !Array.isArray(event))
    {
        if (event.storeAs)
            event = event.storeAs;
        else
            return;
    }
    for (let i = 0; i < V.queuedsimevents.length; i++)
        if (this.events_equal(event, V.queuedsimevents[i]))
        {
            V.queuedsimevents.deleteAt(i);
            if (setup.ob_nPCSimulation.logEvents)
                console.log(`Simulation event "${this.from_event_id(event[0])}" has been deleted from the queue`);
            return;
        }
}

setup.ob_nPCSimulation.clear_advice = function(event)
{
    // clear the pending advice requirement from a queued event
    if (!V.queuedsimevents) return;
    if (typeof event == "object" && !Array.isArray(event))
    {
        if (event.storeAs)
            event = event.storeAs;
        else
            return;
    }
    for (let i = 0; i < V.queuedsimevents.length; i++)
    {
        if (this.events_equal(event, V.queuedsimevents[i]))
        {
            if (setup.ob_nPCSimulation.logEvents)
                console.log(`Simulation event "${this.from_event_id(event[0])}" has had its advice flag cleared`);
            V.queuedsimevents[i][6] = 0;
        }
    }
}

setup.ob_nPCSimulation.event_info = function(id)
{
    // return an event's info from its numeric id or string key
    if (typeof id == "number")
        id = this.from_event_id(id);
    return this.db[id];
}

setup.ob_nPCSimulation.process_event = function(event)
{
    // process an event: execute its effects and surface on elkbook

    const eventkey = this.from_event_id(event[0]);
    const eventinfo = this.db[eventkey];

    if (eventinfo.processIf && !Scripting.evalTwineScript(eventinfo.processIf))
        return;

    let npcs = this.get_event_npcs(event);
    let npc = npcs.length > 0 ? npcs[0] : undefined;

    if (eventinfo.effect)
    {
        this.execute_effects(eventinfo.effect, ...npcs);
    }

    let elkbookline = this.get_elkbook_line(event);
    if (elkbookline)
    {
        this.post_to_elkbook(event);
    }
    this.register_sim_event(eventkey, npc);

    if (this.logEvents && (this.logPosts || !eventinfo.justPost))
    {
        console.log(`Simulation event "${eventkey}" executing involving ${setup.ob_and(npcs)}`);
    }
}

setup.ob_nPCSimulation.build_lookup_table = function()
{
    // create a lookup table of NPCs to numeric IDs
    // this adds a bit to save size but will save us in the long run

    if (!V.NPCLookupTable) V.NPCLookupTable = [];

    let i = -1;
    for (const [p, pdata] of Object.entries(V.people))
    {
        i++;
        if (pdata.id == null || typeof pdata.id != "number" || !Number.isInteger(pdata.id))
        {
            while (i in V.NPCLookupTable) i++;
            V.NPCLookupTable[i] = p;
            pdata.id = i;
        }
    }

    return V.NPCLookupTable;
}

setup.ob_nPCSimulation.get_id = function(name)
{
    // take NPC name string and return integer ID
    // (if no ID exists, rebuilds lookup table)
    // strictly expects name string, but setup.people.get_id will accept name or object

    const pdata = V.people[name];
    if (pdata.id == null || typeof pdata.id != "number" || !Number.isInteger(pdata.id)) this.build_lookup_table();
    return pdata.id;
}

setup.ob_nPCSimulation.from_id = function(id)
{
    // return an NPC string key from numeric ID
    if (V.NPCLookupTable)
        return V.NPCLookupTable[id];
}

// this stuff accepts NPC name strings only
setup.ob_nPCSimulation.clear_relationship = function(npc1, npc2)
{
    // nullify the relationship between two NPCs

    let rel = this.get_relationship(npc1, npc2);

    let id1 = this.get_id(npc1);
    let id2 = this.get_id(npc2);

    let pdata1 = V.people[npc1];
    let pdata2 = V.people[npc2];

    if (pdata1.NPCRelationships) delete pdata1.NPCRelationships[id2];
    if (pdata2.NPCRelationships) delete pdata2.NPCRelationships[id1];

    if (rel && setup.ob_relationships.db[rel]?.setPartner)
    {
        if (pdata1.partner == setup.people.get_name(npc2))
        {
            delete pdata1.partner;
            delete pdata1.partnerType;
            delete pdata1.relStart;
        }
        if (pdata2.partner == setup.people.get_name(npc1))
        {
            delete pdata2.partner;
            delete pdata2.partnerType;
            delete pdata2.relStart;
        }
    }
}

setup.ob_nPCSimulation.set_relationship = function(npc1, npc2, rel)
{
    // save relationships between two NPCs
    // set this on one side only to scrounge as much save size savings as we can

    if (setup.people.get_id(npc1) == setup.people.get_id(npc2)) return;

    this.clear_relationship(npc1, npc2);
    let id2 = this.get_id(npc2);
    let relid = setup.ob_relationships.get_id(rel);

    let pdata1 = V.people[npc1];
    let pdata2 = V.people[npc2];
    if (!pdata1.NPCRelationships) pdata1.NPCRelationships = {};

    pdata1.NPCRelationships[id2] = relid;

    if (setup.ob_relationships.db[rel].setPartner)
    {
        pdata1.partner = setup.people.get_name(npc2);
        pdata2.partner = setup.people.get_name(npc1);

        if (rel != "partner")
        {
            pdata1.partnerType = rel;
            pdata2.partnerType = rel;
        }
        else
        {
            let partnertype = "partner";
            if (setup.people.has_inclination(npc1, "Polyamorous") && setup.people.has_any_inclination(npc2, ["Polyamorous", "Open Relationships"]))
                partnertype = "poly partner";
            else if (setup.people.has_inclination(npc1, "Open Relationships") && setup.people.has_any_inclination(npc2, ["Polyamorous", "Open Relationships"]))
                partnertype = "open partner";

            if (partnertype != "partner")
            {
                pdata1.partnerType = partnertype;
                pdata2.partnerType = partnertype;
            }
        }
        pdata1.relStart = V.gameday;
        pdata2.relStart = V.gameday;

        setup.ob_relationships.unset_cheating_partner(npc1);
        setup.ob_relationships.unset_cheating_partner(npc2);

        setup.ob_housing.rearrange_roommates_for(npc1);
        setup.ob_housing.rearrange_roommates_for(npc2);

        /*
        going back and forth on this... should we need to find out again what an npc's partner is, or can we assume we're keeping up with their life changes? particularly since they'd be getting surfaced by elkbook
        setup.people.unlearn_partner(npc1);
        setup.people.unlearn_partner(npc2);
        */
    }
}

setup.ob_nPCSimulation.get_relationship = function(npc1, npc2)
{
    // get the relationship between two NPCs
    // (returns a string from Relationships.db)

    // could have been recorded on either so check both

    npc1 = setup.people.get_name(npc1);
    npc2 = setup.people.get_name(npc2);

    let id1 = this.get_id(npc1);
    let id2 = this.get_id(npc2);

    let pdata1 = V.people[npc1];
    let pdata2 = V.people[npc2];

    if (pdata1.NPCRelationships?.[id2] != null)
        return setup.ob_relationships.from_id(pdata1.NPCRelationships[id2]);
    else if (pdata2.NPCRelationships?.[id1] != null)
        return setup.ob_relationships.from_id(pdata2.NPCRelationships[id1]);
}

setup.ob_nPCSimulation.get_relationship_type = function(npc1, npc2)
{
    // get the relationship type (friendship, romantic, etc) between two NPCs

    let rel = this.get_relationship(npc1, npc2);
    if (rel)
        return setup.ob_relationships.db[rel].type;
}

setup.ob_nPCSimulation.get_relationship_start_day = function(npc)
{
    // return the day an NPC began their relationship with the PC
    let pdata = setup.people.get_person(npc);
    return pdata.relStart ?? 1;
}

setup.ob_nPCSimulation.relationship_age = function(npc)
{
    // return the number of days an NPC has had their relationship with the PC
    return V.gameday - this.get_relationship_start_day(npc);
}

setup.ob_nPCSimulation.relationships_raw = function(npc)
{
    // return raw NPC-to-NPC relationship data
    npc = setup.people.get_name(npc);
    let pdata = V.people[npc];
    return pdata.NPCRelationships || {};
}

setup.ob_nPCSimulation.relationships = function(npc)
{
    // parse NPC to NPC relationship data, return as dictionary of relationship strings
    npc = setup.people.get_name(npc);
    let rels = this.relationships_raw(npc);
    let retval = {};
    for (let [npc2, rel] of Object.entries(rels))
        retval[setup.people.get_name(npc2)] = setup.ob_relationships.from_id(rel);
    return retval;
}

setup.ob_nPCSimulation.relationships_by_type = function(npc)
{
    // return a dictionary of relationships => NPCs array
    let rels = this.relationships_raw(npc);
    let retval = {};
    for (let [npc2, rel] of Object.entries(rels))
    {
        rel = setup.ob_relationships.from_id(rel);
        npc2 = setup.people.get_name(parseInt(npc2));
        if (retval[rel])
            retval[rel].push(npc2);
        else
            retval[rel] = [npc2];
    }
    return retval;
}

setup.ob_nPCSimulation.npcs_of_relationship_type = function(npc, type)
{
    // return NPCs this NPC has the given relationship with
    return this.relationships_by_type(npc)[type] ?? [];
}

setup.ob_nPCSimulation.npcs_of_relationship_types = function(npc, types)
{
    // return NPCs this NPC has any of the given relationships with
    let retval = [];
    for (let type of types)
        retval = [...retval, ...this.npcs_of_relationship_type(npc, type)];
    return retval;
}

setup.ob_nPCSimulation.has_relationship_type = function(npc, checktypes)
{
    // return whether this NPC has the given relationship types with any NPC
    return Object.keys(this.relationships_by_type(npc)).includesAny(checktypes);
}

setup.ob_nPCSimulation.has_relationship_type_with = function(npc, checktypes, npc2)
{
    // return whether this NPC has the given relationship with the given NPC
    let types = this.relationships_by_type(npc);
    npc2 = setup.people.get_name(npc2);
    // can make this faster by avoiding name lookup when possible, if needed
    for (let type of checktypes)
        if (types?.[type]?.includes(npc2)) return true;
    return false;
}

setup.ob_nPCSimulation.can_cheat = function(npc)
{
    // can this NPC autonomously cheat?
    let partner = setup.ob_relationships.partner(npc);
    return !partner || partner != "PC" || V.kinkcontent.includes("cheating");
}

setup.ob_nPCSimulation.will_simulate = function(npc)
{
    // do we want to simulate this NPC in such a way that we add information about them to the save?
    // the main function of this is to reduce save size and general clutter
    // by not storing or surfacing stuff about NPCs the player doesn't care about

    if (typeof npc != "string")
        npc = setup.people.get_name(npc);

    if (!setup.people.is_relevant(npc)) return false;

    return  (V.favoritepeople && V.favoritepeople.includes(npc)) ||
            setup.ob_relationships.relationship_with(npc) ||
            (V.gameday - setup.people.get_person(npc).lastInteraction < 14 && setup.people.attitude_magnitude(npc) >= setup.people.intro_threshold && setup.people.is_known(npc));
}

setup.ob_nPCSimulation.can_add_new_relationship = function(npc)
{
    // can we add a new relationship? (is this NPC already at max relationship count? are we simulating it?)
    return Object.keys(this.relationships_raw(npc)).length < this.max_relationships && this.will_simulate(npc);
}

setup.ob_nPCSimulation.likelihood = function(minDays, maxDays, avgDays, daysSince)
{
    // return the likelihood of a given event happening today given how often it's supposed to happen
    if (daysSince < minDays) return 0;
    else if (daysSince > maxDays) return 1;
    else
    {
        const preSlope = 1.5;
        const postSlope = 0.75;
        if (daysSince <= avgDays)
        {
            return 0.5 * Math.pow((daysSince - minDays) / (avgDays - minDays), preSlope);
        }
        else
        {
            return 0.5 + 0.5 * Math.pow((daysSince - avgDays) / (maxDays - avgDays), postSlope);
        }
    }
}

setup.ob_nPCSimulation.event_roll = function(event)
{
    // roll whether the event happens today
    const eventinfo = this.db[event];
    let chances = this.likelihood(eventinfo.minDays, eventinfo.maxDays, eventinfo.avgDays, V.gameday - this.last_event_day(event));
    return State.random() < chances;
}

setup.ob_nPCSimulation.register_sim_event = function(event, npc)
{
    // put a sim event into gamestate memory
    if (!V.simeventmemory) V.simeventmemory = {};

    if (V.simeventmemory[event] && V.gameday - V.simeventmemory[event][0] <= this.db[event].maxDays)
    {
        V.simeventmemory[event][1]++;
    }
    else
    {
        V.simeventmemory[event] = [V.gameday, 1];
    }
}

setup.ob_nPCSimulation.last_event_day = function(event)
{
    // returns the last gameday that the given event happened
    return V?.simeventmemory?.[event]?.[0] || 0;
}

setup.ob_nPCSimulation.event_instances = function(event)
{
    // returns the number of instances of the event in memory within its maximum interval
    if (V?.simeventmemory?.[event])
    {
        let dayssince = V.gameday - V.simeventmemory[event][0];
        if (dayssince > this.db[event].maxDays)
            return 0;
        else
            return V.simeventmemory[event][1];
    }
    else
    {
        return 0;
    }
}

setup.ob_nPCSimulation.event_instances_today = function(event)
{
    // returns the number of instances of the event today
    if (V?.simeventmemory?.[event] && V.simeventmemory[event][0] == V.gameday)
    {
        return V.simeventmemory[event][1];
    }
    else
    {
        return 0;
    }
}

setup.ob_nPCSimulation.get_event_id = function(event)
{
    // take a string event key, return its numeric ID
    return this.db[event].id;
}

setup.ob_nPCSimulation.from_event_id = function(id)
{
    // get a numeric ID, return event string
    for (const [event, eventinfo] of Object.entries(this.db))
        if (eventinfo.id == id)
            return event;
}

setup.ob_nPCSimulation.get_elkbook_line = function(data)
{
    // pull a line from the dialogue database for the purposes of elkbook, parse and return
    let eventid = data[0];
    let rng = setup.ob_newRNG(data[1]);
    let year = data[2];
    let month = data[3];
    let day = data[4];
    let dayslice = data[5];
    let npcs = setup.ob_nPCSimulation.get_event_npcs(data);

    const event = this.from_event_id(eventid);
    const eventinfo = this.db[event];

    let tags = ["elkbook", event];
    let line = setup.ob_dialogue.pick(tags, npcs[0], null, rng);
    if (!line) return;
    line = line.line;

    if (line.match("%class") || line.match("%professor"))
    {
        let classes = setup.School.all_classes_today().filter(item => setup.people.courses(npcs[0]).includes(item));
        if (classes.length == 0)
        {
            classes = setup.people.courses(npcs[0]);
            if (classes.length == 0)
                classes = Object.keys(setup.School.courses).filter(course => ["Block C", "Block D"].includes(setup.School.courses[course].schedule) && setup.School.courses[course].year == setup.people.get_year(npcs[0]));
        }

        let course = rng.randomchoice(classes);
        let prof = setup.School.professor_of_course(course);
        line = line.replace("%class", course).replace("%professor", "Professor " + setup.people.lastname(prof));
    }

    return line;
}

setup.ob_nPCSimulation.queued_sim_event_keys = function()
{
    // return an array of string event keys that are queued
    if (!V.queuedsimevents) return [];
    else return V.queuedsimevents.map(item => this.from_event_id(item[0]));
}

setup.ob_nPCSimulation.get_day_slice = function(i)
{
    // turn a numeric day slice identifier into a string
    return ["morning", "afternoon", "evening", "night"][i];
}

setup.ob_nPCSimulation.is_queued = function(tag, foradvice = false)
{
    // is the given event key queued to happen today? (returns event if so)
    if (!V.queuedsimevents) return false;

    for (let queued of V.queuedsimevents)
    {
        if (this.from_event_id(queued[0]) == tag)
        {
            if (V.year == queued[2] && V.month == queued[3] && V.day == queued[4] && (queued[6] || setup.ob_time.timeofday() == this.get_day_slice(queued[5])) && ((!foradvice && !queued[6]) || (foradvice && queued[6])))
            {
                return queued;
            }
        }
    }
    return null;
}

setup.ob_nPCSimulation.is_queued_for = function(tag, npc, foradvice = false)
{
    // is the given event key queued to happen today for a specific npc? (returns event if so)
    if (!V.queuedsimevents) return false;

    npc = setup.people.get_id(npc);

    for (let queued of V.queuedsimevents)
    {
        if (this.from_event_id(queued[0]) == tag)
        {
            if (npc == queued[7] && V.year == queued[2] && V.month == queued[3] && V.day == queued[4] && (queued[6] || setup.ob_time.timeofday() == this.get_day_slice(queued[5])) && ((!foradvice && !queued[6]) || (foradvice && queued[6])))
            {
                return queued;
            }
        }
    }
    return null;
}

setup.ob_nPCSimulation.any_advice_queued = function(npc)
{
    // is there anybody at all waiting for advice?
    if (!V.queuedsimevents) return false;

    return V.queuedsimevents.some(queued => queued[6]);
}

setup.ob_nPCSimulation.is_queued_for_any_advice = function(npc)
{
    // is this npc waiting for any advice at all?
    if (!V.queuedsimevents) return false;

    npc = setup.people.get_id(npc);

    for (let queued of V.queuedsimevents)
    {
        if (npc == queued[7] && V.year == queued[2] && V.month == queued[3] && V.day == queued[4] && queued[6])
        {
            return queued;
        }
    }
    return null;
}

setup.ob_nPCSimulation.get_event_npcs = function(data)
{
    // retrieve all NPCs from an event in its stored form
    return data.slice(7).map(item => setup.people.get_name(item));
}

setup.ob_nPCSimulation.post_to_elkbook = function(data)
{
    // add an event to the elkbook timeline
    if (!V.elkbooktimeline) V.elkbooktimeline = [];
    V.elkbooktimeline.push([V.gameday, 0, ...data]);
}

setup.ob_nPCSimulation.prune_elkbook_timeline = function()
{
    // keep our record of Elkbook timeline events within certain limits to restrain save file size
    if (!V.elkbooktimeline || V.elkbooktimeline.length == 0) return;
    const daylimit = idb.active ? 28 * 3 : 7;
    const countlimit = idb.active ? 1000 : 100;
    V.elkbooktimeline = V.elkbooktimeline.splice(-countlimit).filter(entry => V.gameday - entry[0] <= daylimit);
}

setup.ob_nPCSimulation.set_flag = function(npc, flag, onpc)
{
    // set a simulation flag on an NPC
    let pdata = setup.people.get_person(npc);
    if (!pdata.simFlags) pdata.simFlags = [];

    let oid = onpc ? setup.people.get_id(onpc) : undefined;
    pdata.simFlags = pdata.simFlags.filter(eflag => eflag[0] != flag || eflag[2] != oid);

    let newflag = [flag, V.gameday];
    if (oid) newflag.push(oid);

    pdata.simFlags.push(newflag);
}

setup.ob_nPCSimulation.remove_flag = function(npc, flag, onpc)
{
    // delete a simulation flag from an NPC
    let pdata = setup.people.get_person(npc);
    if (!pdata.simFlags) return;
    if (onpc) onpc = this.get_id(onpc);
    for (let i = 0; i < pdata.simFlags.length; i++)
        if (pdata.simFlags[i][0] == flag && ((!onpc && !pdata.simFlags[i][2]) || onpc == pdata.simFlags[i][2]))
        {
            pdata.simFlags.deleteAt(i);
            if (pdata.simFlags.length == 0)
                delete pdata.simFlags;
            break;
        }
}

setup.ob_nPCSimulation.sim_flags = function(npc)
{
    // return all sim flags on an NPC
    const pdata = setup.people.get_person(npc);
    return pdata.simFlags ?? [];
}

setup.ob_nPCSimulation.has_flag = function(npc, flag)
{
    // does this NPC have this flag?
    flag = Array.isArray(flag) ? flag[0] : flag;
    return this.sim_flags(npc).map(el => el[0]).includes(flag);
}

setup.ob_nPCSimulation.has_flag_of_age = function(npc, flag, age)
{
    // does this NPC have this flag that's at least this many days old?
    flag = Array.isArray(flag) ? flag[0] : flag;
    return this.sim_flags(npc).some(el => el[0] == flag && V.gameday - el[1] >= age);
}

setup.ob_nPCSimulation.has_flag_with = function(npc, flag, onpc)
{
    // does this NPC have this flag with this other NPC?
    let id = setup.people.get_id(onpc);
    flag = Array.isArray(flag) ? flag[0] : flag;
    return this.sim_flags(npc).some(el => el[0] == flag && el[2] == id);
}

setup.ob_nPCSimulation.has_any_flag_with = function(npc, flags, onpc)
{
    // does this NPC have any of these flags with this other NPC?
    for (let flag of flags)
        if (this.has_flag_with(npc, flag, onpc))
            return true;
    return false;
}

setup.ob_nPCSimulation.has_flag_of_age_with = function(npc, flag, age, onpc)
{
    // does this NPC have this flag with this other NPC that's at least this many days old?
    flag = Array.isArray(flag) ? flag[0] : flag;
    let id = setup.people.get_id(onpc);
    return this.sim_flags(npc).some(el => el[0] == flag && V.gameday - el[1] >= age && el[2] == id);
}

setup.ob_nPCSimulation.post_time = function(event)
{
    // determine exactly what time an event's elkbook post should happen
    let rngseed = event[1];
    let rng = setup.ob_newRNG(rngseed);
    let slice = this.get_day_slice(event[5]);
    if (this.event_info(event[0]).postAhead) slice = setup.ob_time.previous_timeofday(slice);
    let starthour, endhour;
    switch (slice)
    {
        case "morning":
        {
            starthour = 6;
            endhour = 12;

            break;
        }
        case "afternoon":
        {
            starthour = 12;
            endhour = 18;

            break;
        }
        case "evening":
        {
            starthour = 18;
            endhour = 22;

            break;
        }
        case "evenning":
        {
            // one typo and now this has to be here forever
            // (it can be deleted at some point)
            starthour = 18;
            endhour = 22;

            break;
        }
        case "night":
        {
            starthour = 22;
            endhour = 24;

            break;
        }
    }

    let hour = rng.rir(starthour, endhour);
    let minute = rng.rir(0, 60);
    return [hour, minute];
}

setup.ob_nPCSimulation.gain_experience = function(npc, skill, chance = 0.1)
{
    // an NPC gains experience with the given skill
    // which is represented (by default) as a 10% chance of gaining a skill level each time they use the skill
    if (State.random() < chance)
    {
        if (skill == "bits")
            skill = setup.people.has_part(npc, "penis") ? "Penetrative" : "Vaginal";

        if (skill == "D/s")
            skill = setup.people.has_any_inclination(npc, "just_dominant") ? "Dominance" : "Submission";

        skill = skill.toUpperFirst();
        let pdata = setup.people.get_person(npc);
        if (!pdata.skills) pdata.skills = {};
        let clvl = setup.people.skill_level(npc, skill);
        if (clvl < 10)
            pdata.skills[skill] = clvl + 1;
    }
}

setup.ob_nPCSimulation.wants_advice = function(npc, about, npc2 = undefined)
{
    // does this NPC want advice from the PC about the given topic?

    if (!about) return false;

    if (about == "sex" && npc2 && setup.ob_nPCSimulation.has_flag_with(npc, 210, npc2))
        return false;

    if (about == "relationship" && setup.ob_relationships.relationship_type_with(npc) == "romantic")
        return true;

    let rel = setup.ob_relationships.relationship_with(npc);

    if (about == "pregnancy")
    {
        // less 'advice' (although sometimes advice) and more just informing we're pregnant
        if (setup.ob_pregnancy.pc_is_donor(npc)) // always inform the PC when the baby is theirs
            return true;
        else if (V.pc.equals(setup.ob_relationships.partner(npc))) // or if we're in a relationship
            return true;
        else if (setup.ob_relationships.in_positive_relationship(npc)) // or if we're friends or whatever
            return true;
        else
            return false;
    }
    else if (about == "abortion" && setup.ob_pregnancy.pc_is_donor(npc))
    {
        // some special handling for this
        // re: abortion, firstly, keep in mind we're only here if it's already been determined the NPC wants to end the pregnancy
        // realistically, this would be a whole discussion that doesn't always go the PC's way
        // more practically, i think it will be frustrating and an overall bad experience if the player's input here is ignored
        // (in the case of a romantic or other positive relationship anyway)
        // maybe there are better ways to handle it, but we'll do this for now

        return setup.ob_relationships.relationship_type_with(npc) == "romantic" || ["best friend", "friend", "fuckbuddy"].includes(rel);
    }
    else if (about == "abortion" && setup.people.has_inclination(npc, "Nature Prevails"))
        return false;
    else
    {
        if (rel == "submissive")
            return true;
        else if (rel == "dominant")
            return false;
        else if (rel == "best friend")
            if (about == "sex")
                return setup.people.has_any_inclination(npc, "sexshy");
            else if (about == "romance")
                return true;
            else if (about == "abortion")
            {
                if (setup.people.has_any_inclination(npc, "Careful"))
                    return false;
                else
                    return true;
            }
            else if (setup.people.has_inclination(npc, "Confident"))
                return false;
            else
                return true;
        else if (rel == "fuckbuddy" && about == "sex")
            return false;
        else if (rel == "friend" || rel == "fuckbuddy")
            if (about == "inclination")
                return false;
            else if (setup.people.has_inclination(npc, "Insecure"))
                return true;
            else if (about == "sex" && setup.people.has_any_inclination(npc, "sexshy"))
                return true;
            else if ((about == "friendship" || about == "romance") && setup.people.has_inclination(npc, "Shy"))
                return true;
            else
                return false;
        else if (setup.ob_relationships.relationship_type_with(npc) == "romantic")
            if (about == "sex" && rel != "poly partner")
                return false;
            else if (setup.people.has_inclination(npc, "Insecure"))
                return true;
            else if (about == "inclination")
                return true;
            else if (setup.people.has_inclination(npc, "Confident"))
                return false;
            else
                return false;
        else
            return false;
    }
}

setup.ob_nPCSimulation.takes_advice = function(npc, about, todoit = true, mod = 0)
{
    // does this NPC actually take the PC's advice once it's given?
    // (todoit = true: we're advising them to do something, otherwise advising them not to do something)
    // use 'mod' to modify the chances of the thing happening, >0 means more likely

    let chance = 1;
    if (about == "abortion" && setup.ob_pregnancy.pc_is_donor(npc))
    {
        // see comments in above method for an explanation
        return true;
    }
    else
    {
        if (about == "relationship" && setup.ob_relationships.relationship_type_with(npc) == "romantic")
            return true;

        let rel = setup.ob_relationships.relationship_with(npc);
        if (rel == "submissive")
            if (about == "abortion" || about == "pregnancy")
                chance = 0.5;
            else if (setup.people.has_inclination(npc, "Brat"))
                chance = 0.5;
            else
                chance = 1;
        else if (rel == "dominant")
            if (about == "abortion" || about == "pregnancy")
                chance = 0.5;
            else
                chance = 0;
        else if (rel == "best friend")
            if (about == "sex")
                chance = todoit ? 0.9 : 0.5;
            else if (about == "abortion" || about == "pregnancy")
                chance = 0.5;
            else if (about == "romance")
                chance = todoit ? 0.95 : setup.people.skill_level(npc, "Intellectual") / 2000;
            else if (setup.people.has_inclination(npc, "Confident"))
                chance = todoit ? 0.9 : 0.2;
            else
                chance = todoit ? 0.8 : 0.65;
        else if (rel == "fuckbuddy" && about == "sex")
            chance = todoit ? 0.95 : 0.25;
        else if (rel == "friend" || rel == "fuckbuddy")
            if (about == "abortion" || about == "pregnancy")
                chance = 0.5;
            else if (about == "inclination")
                chance = 0.5;
            else if (setup.people.has_inclination(npc, "Insecure"))
                chance = 0.9;
            else if (about == "sex" && setup.people.has_any_inclination(npc, "sexshy"))
                chance = todoit ? 0.7 : 0.95;
            else if ((about == "friendship" || about == "romance") && setup.people.has_inclination(npc, "Shy"))
                chance = todoit ? 0.7 : 0.95;
            else
                chance = 0.5;
        else if (setup.ob_relationships.relationship_type_with(npc) == "romantic")
            if (about == "abortion" || about == "pregnancy")
                chance = 0.8;
            else if (about == "sex" && rel != "poly partner")
                chance = todoit ? 0.99 : 0.5;
            else if (setup.people.has_inclination(npc, "Insecure"))
                chance = 1;
            else if (about == "inclination")
                chance = 1;
            else if (setup.people.has_inclination(npc, "Confident"))
                chance = todoit ? 0.99 : 0.5;
            else
                chance = 0.5;
        else
            chance = 0;
    }

    chance += mod;

    if (chance < 1 && !setup.people.likes_pc(npc)) // first pass a likability check
        return false;
    else
        return State.random() < chance;
}

setup.ob_nPCSimulation.relationship_health = function(npc1, npc2, day = V.gameday)
{
    // use simplex noise to add natural-feeling variation to how well NPCs get along over time

    // find numeric IDs for each NPC
    let id1 = setup.people.get_id(npc1);
    let id2 = setup.people.get_id(npc2);

    // assemble unique seed for this pairing, init rng and simplex noise
    let seed = inthash(`relhealth_${Math.min(id1, id2)}x${Math.max(id1, id2)}_${V.seed}`);
    let rng = setup.ob_newRNG(seed);
    let simplex = new SimplexNoise(() => rng.random());

    // find long term, medium term, and short term noise
    let basenoise = simplex.noise2D(day / 45, 0);
    let mediumnoise = simplex.noise2D(day / 12, 100);
    let smallnoise = simplex.noise2D(day / 4, 200);

    // compile three noise tracks into one value
    let rawhealth = (basenoise * 0.5) + (mediumnoise * 0.3) + (smallnoise * 0.2);

    // bias health in a slightly positive direction, more so if NPCs have good association value, and factor in inclination compatibility
    let bias = 0.2 + (setup.people.npc_association_factor(npc1, npc2, true) * 0.15) + (this.compatibility(npc1, npc2) * 0.15);

    // an amplitude/volatility value — a higher number means any thresholds in the simulation will be crossed more often
    let drama = V.optdrama ?? 0.4;

    // put it all together and return
    let retval = (rawhealth * drama) + bias;
    return retval;
}

setup.ob_nPCSimulation.compatibility = function(npc1, npc2)
{
    // returns a number between -1 and 1 representing compatibility between NPCs based on inclinations and stuff
    // (demographic-type stuff is already covered by NPC association factor)

    let matrix = [
        {match: ["basic_exhibitionist"], compatible: ["basic_exhibitionist", "basic_voyeur", "just_dominant"], opposed: ["chaste"],},
        {match: ["basic_voyeur"], compatible: ["basic_exhibitionist", "just_dominant"], opposed: ["chaste"],},
        {match: ["just_dominant"], compatible: ["submissive"], opposed: ["chaste", "just_dominant"],},
        {match: ["just_submissive"], compatible: ["dominant"], opposed: ["just_submissive"],},
        {match: ["masochist"], compatible: ["sadist"], opposed: ["chaste"],},
        {match: ["sadist"], compatible: ["masochist"], opposed: ["chaste"],},
        {match: ["nocasualsex"], compatible: ["nocasualsex"], opposed: ["casualsex"],},
        {match: ["bragger"], compatible: [], opposed: ["shy", "sexshy"],},
        {match: ["sexshy"], compatible: [], opposed: ["bragger"],},
        {match: ["arrogant"], compatible: [], opposed: ["kind"],},
        {match: ["kind"], compatible: ["kind"], opposed: ["arrogant"],},
        {match: ["passive"], compatible: ["active"], opposed: ["passive"],},
        {match: ["active"], compatible: ["passive", "active"], opposed: [],},
    ];

    function has_inclination(npc, inc)
    {
        if (Array.isArray(inc) || inc in setup.ob_archetypes.inclination_sets)
            return setup.people.has_any_inclination(npc, inc);
        else
            return setup.people.has_inclination(npc, inc);
    }

    function raw_compatibility(npc1, npc2)
    {
        let compat = 0;
        let oppose = 0;
        for (let posmatch of matrix)
        {
            if (posmatch.match.some(m_inc => has_inclination(npc1, m_inc)))
            {
                if (posmatch.compatible.some(c_inc => has_inclination(npc2, c_inc)))
                    compat++;
                else if (posmatch.opposed.some(o_inc => has_inclination(npc2, o_inc)))
                    oppose++;
            }
        }
        return [compat, oppose];
    }

    let compat1 = raw_compatibility(npc1, npc2);
    let compat2 = raw_compatibility(npc2, npc1);

    let t_compat = compat1[0] + compat2[0];
    let t_oppose = compat1[1] + compat2[1];

    return Math.clamp((t_compat - t_oppose) * 0.16, -1, 1);
}

setup.ob_nPCSimulation.make_test_events = function(days = 7)
{
    // run a bunch of simulated events
    // mostly just useful for populating elkbook posts
    let oday = V.gameday;
    V.gameday -= days;
    for (let i = 0; i < days; i++)
    {
        setup.ob_nPCSimulation.queue_events();

        for (let event of V.queuedsimevents)
            setup.ob_nPCSimulation.process_event(event);

        V.queuedsimevents = [];

        V.gameday++;
    }

    V.gameday = oday;
}

setup.ob_nPCSimulation.homebody_rating = function(name, day = setup.ob_time.weekday())
{
    // how likely an NPC is to stay home rather than going out to a nightlife activity on the given day
    // base scale 0 to 1, but fine if it exceeds 1
    // (ends up being a multiplier for home activities)

    let factor = 0.5;

    if (setup.people.has_any_inclination(name, "shy"))
        factor += 0.5;

    if (setup.people.has_inclination(name, "Loner"))
        factor += 0.5;

    if (setup.people.has_any_inclination(name, "rowdy"))
        factor /= 2;

    if (setup.people.has_any_inclination(name, "chaste"))
        factor *= 1.25;

    return Math.max(0, factor);
}

setup.ob_nPCSimulation.activity_attraction_rating = function(activity, name)
{
    // rate how much this NPC enjoys a specific home activity
    // (same scale as setup.ob_business.attraction_rating)

    const actinfo = setup.ob_nPCSimulation.homeActivities[activity];
    return setup.ob_business.raw_attraction_rating(actinfo, name);
}

setup.ob_nPCSimulation.unread_message_count = function(onlyfriends = true)
{
    // return the number of elkbook posts not seen yet
    if (!V.elkbooktimeline) return 0;
    return V.elkbooktimeline.filter(line => !line[1] && V.gameday - line[0] <= 1 && (!onlyfriends || setup.ob_nPCSimulation.get_event_npcs(line.slice(2)).some(npc => setup.people.is_friend(npc)))).length;
}

setup.ob_nPCSimulation.unread_text_count = function()
{
    // return the number of texts not seen yet (unimplemented, awaiting texting refactor)
    return 0;
}

setup.ob_nPCSimulation.remove_duplicate_sim_flags = function()
{
    // repair sim flag data when we have duplicates of the same pairing
    for (let pdata of Object.values(V.people))
    {
        if (!pdata.simFlags) continue;
        let latest = {};
        for (let flag of pdata.simFlags)
        {
            let key = flag[0] + "|" + (flag[2] || "");
            if (!latest[key] || flag[1] > latest[key][1])
                latest[key] = flag;
        }
        pdata.simFlags = Object.values(latest);
        if (pdata.simFlags.length == 0) delete pdata.simFlags;
    }
}
