setup.ob_nPCSimulation.validate_ids = function()
{
    let ids = Object.keys(this.db).map(key => this.db[key].id);
    const duplicates = ids.filter((item, i) => ids.indexOf(item) !== i);
    if (duplicates.length > 0)
        console.error("Duplicate NPC simulation IDs found:", duplicates);
}
setup.ob_nPCSimulation.validate_ids();
/* twine-user-script #55: "people.js" */
// this is a set of functions mostly for dealing with entries in the people database
// that is, retrieving and setting properties of people who are not currently Person objects

if (!setup.people) setup.people = {};

setup.people.add_random = function(gender, archetype, type, rng = new RNG())
{
    let bibonus = V.bibonus;
    let gaybonus = V.gaybonus;
    if (bibonus > 0) bibonus *= 2;
    if (gaybonus > 0) gaybonus *= 2;

    let db = setup.people_db();
    let name = setup.ob_unique_random_name(gender, rng);

    let attractionpos = setup.ob_get_gender_node(gender, "attraction");

    if (V.optstraightfrequency && V.optqueerfrequency && V.optbifrequency)
    {
        for (let i = 0; i < attractionpos.length; i+=2)
        {
            if (attractionpos[i].label == "bi") attractionpos[i+1] = V.optbifrequency;
            else if (attractionpos[i].label != "straight") attractionpos[i+1] = V.optqueerfrequency;
            else attractionpos[i+1] = V.optstraightfrequency;

            if (typeof attractionpos[i+1] == "string")
                attractionpos[i+1] = parseInt(attractionpos[i+1]);
        }
    }
    else
    {
        for (let i = 0; i < attractionpos.length; i+=2)
        {
            if (attractionpos[i].label == "bi") attractionpos[i+1] += bibonus;
            else if (attractionpos[i].label != "straight") attractionpos[i+1] += gaybonus;
        }
    }

    let attraction = rng.randomrelfreq(attractionpos);

    let newperson = {"special": false, "archetype": archetype, "type": type, "species": ["human", gender], "attraction": attraction.label};
    db[name] = newperson;
    return name;
}

setup.people.get_person = function(i)
{
    let db = setup.people_db();
    if (typeof i == "string" || typeof i == "object")
    {
        i = this.get_name(i);
        return db[i];
    }
    else
    {
        return db[Object.keys(db)[i]];
    }
}

setup.people.niche = function(name)
{
    name = this.get_name(name);
    const niches = V.niches;
    for (const niche of Object.keys(niches))
        if (niches[niche] == name)
            return niche;
    return null;
}

setup.people.reverse_niches = function()
{
    let retval = {};
    for (const [niche, p] of Object.entries(V.niches))
        retval[p] = niche;
    return retval;
}

setup.people.get_name = function(name)
{
    // accepts name, niche, or person object and returns people database key (their full name)
    // (this is not necessarily player-readable now that display names are a thing)

    if (name in V.people) return name; // quick shortcut since this is most cases

    if (typeof name == "object") name = name.person;

    if (typeof name == "number") return setup.ob_nPCSimulation.from_id(name);

    if (name == "PC") return name;

    if (name in setup.people_niches())
        name = setup.people_niches()[name];

    if (!(name in setup.people_db()))
    {
        // forgive me for what i must do
        let matches = Object.keys(setup.people_db()).filter(item => item.indexOf(name + "'") == 0)
        if (matches) name = matches[0];
    }

    return name;
}

setup.people.get_display_name = function(name)
{
    // returns their full name

    name = this.get_name(name);
    if (name == "PC")
    {
        return setup.pc().name;
    }
    else
    {
        const pdata = this.get_person(name);
        if (!pdata) return name;
        return pdata.displayname || name;
    }
}

setup.people.get_type = function(name)
{
    try
    {
        return this.get_person(name).type;
    }
    catch
    {
        return "temp";
    }
}

setup.people.students_and_townies = function()
{
    return Object.keys(V.people).filter(p => ["student", "townie"].includes(this.get_type(p)));
}

setup.people.get_year = function(name)
{
    return this.get_person(name).year;
}

setup.people.get_job = function(name)
{
    let job = this.get_person(name).job;
    if (job == null || job == undefined)
    {
        return null;
    }
    else
    {
        return job;
    }
}

setup.people.get_school_year = function(name)
{
    const pdata = this.get_person(name);
    if (pdata.type != "student" || !pdata.year)
        return undefined;
    else
    {
        for (const [year, info] of Object.entries(setup.School.noncohort))
            if (info.year == pdata.year)
                return year;
    }
}

setup.people.is_cohort = function(name)
{
    const pdata = this.get_person(name);
    if (pdata.type != "student" || !pdata.year)
        return true;
    else
    {
        return pdata.year == V.gameyear;
    }
}

setup.people.same_cohort = function(name1, name2)
{
    return this.get_school_year(name1) == this.get_school_year(name2);
}

setup.people.is_enrolled = function(name, course)
{
    if (V.pc.equals(name))
    {
        return V.pccourses.includes(course) || V.pcsports?.includes(course);
    }
    else
    {
        const pdata = this.get_person(name);
        if (pdata.courses && pdata.courses.includes(course))
            return this.get_type(name) == "student";
        else if (pdata.sports && pdata.sports.includes(course))
            return this.get_type(name) == "student";
        else
            return false;
    }
}

setup.people.all_enrolled = function(course)
{
    return Object.keys(V.people).filter(p => this.is_enrolled(p, course));
}

setup.people.sports = function(name)
{
    const pdata = this.get_person(name);
    return pdata.sports || [];
}

setup.people.get_attitude = function(name, type="friendship")
{
    let attitudes;
    if (this.cached_attitudes && this.cached_attitudes[0] == name && Date.now() - this.cached_attitudes[1] < 1000)
    {
        attitudes = this.cached_attitudes[2];
    }
    else
    {
        let pinfo = this.get_person(name);
        if (!pinfo) return 0;
        if (!("attitude" in pinfo))
        {
            this.cached_attitudes = [name, Date.now(), {}];
            return 0;
        }
        else
        {
            attitudes = pinfo.attitude;
            this.cached_attitudes = [name, Date.now(), attitudes];
        }
    }
    if (!type.includes("_or_"))
        return attitudes[type] || 0;
    else
    {
        // this is a bit of a hack, but what isn't these days?
        // this is coming from the relationships system initially
        let types = type.split("_or_");
        let amounts = types.map(itype => attitudes[itype] || 0);
        return Math.max(...amounts);
    }
}

setup.people.is_friend = function(name)
{
    //return this.get_attitude(name, "friendship") > 333 && !this.is_removed(name);
    return setup.ob_relationships.relationship_type_with(name) == "friendship" && !this.is_removed(name);
}

setup.people.is_friendly = function(name)
{
    return this.get_attitude(name, "friendship") > 333 && !this.is_removed(name);
}

setup.people.is_crush = function(name)
{
    let att = this.get_attitude(name, "romance");
    return (att > 333 || (this.is_known(name) && this.desired_relationship(name) == "date" && att > 0)) && !this.is_removed(name);
