setup.people.set_attitude = function(name, type, value)
{
    const nevernegative = ["anger", "suspicion", "favor"];
    let pinfo = this.get_person(name);
    if (!("attitude" in pinfo))
    {
        pinfo.attitude = {};
    }
    if (typeof value == "number")
        pinfo.attitude[type] = value;
    else
        console.warn("invalid attitude value");

    if (nevernegative.includes(type) && pinfo.attitude[type] < 0)
        pinfo.attitude[type] = 0;

    if (pinfo.attitude[type] == 0)
    {
        delete pinfo.attitude[type];

        if (Object.keys(pinfo.attitude).length == 0)
            delete pinfo.attitude;
    }
}

setup.people.alter_attitude = function(name, type, value, updateinteraction = true)
{
    let pinfo = this.get_person(name);
    if (!("attitude" in pinfo))
    {
        pinfo.attitude = {};
    }
    if (!(type in pinfo.attitude))
    {
        pinfo.attitude[type] = 0;
    }

    const affectedbyhygiene = ["friendship", "lust", "romance"];
    if (value > 0 && affectedbyhygiene.includes(type) && setup.ob_needs.get_need("Hygiene") < 200 && !V.pc.has_inclination("Natural Odor"))
    {
        value /= 10;
    }

    if (value > 0 && type == "lust")
    {
        if (!this.attracted_to_pc(name) && !pinfo.attractionFluid) return;
        let tf = this.npc_turnon_factor(name);
        if (tf == -2) value /= 2;
        else if (tf == -1) value /= 1.25;
        else if (tf == 1) value *= 1.25;
        else if (tf == 2) value *= 1.5;
    }

    if (value > 0 && type == "romance" && pinfo.attitude["friendship"] && pinfo.attitude["friendship"] < -100)
        return;

    let capvalue = Math.max(value, 100); // big swings are already big... only multiply the smaller cumulative changes
    if (value > 0)
    {
        let mult = V.optrelationmultiplier || 1;
        value *= mult;
        value = Math.min(value, capvalue);
    }

    if (type == "friendship" && value > 0 && V.pc.has_inclination("Gregarious"))
    {
        value *= 1.2;
        value = Math.min(value, capvalue);
    }

    const max = type == "romance" ? setup.ob_relationships.max_romance(name) : 1000;
    this.set_attitude(name, type, Math.clamp(pinfo.attitude[type] + value, -1000, max));

    if (updateinteraction)
        pinfo.lastInteraction = V.gameday;

    if (!V.statusChangeLog)
		V.statusChangeLog = [];

	let change = {};
	change["name"] = name;
	change["type"] = type;
	change["value"] = value;

	V.statusChangeLog.push(change);
    //console.log(change);
}

setup.people.attitude_to_mean = function(name)
{
    // adjusts attitudes back toward 100 or -100
    name = this.get_name(name);
    const degrade = ["friendship", "lust", "romance", "trust"];
    const degrademoreslowly = ["trust"];
    for (const attitude of degrade)
    {
        let delta = degrademoreslowly.includes(attitude) ? 5 : 10;
        let amt = this.get_attitude(name, attitude);
        if (amt > 100)
        {
            amt = Math.max(amt - delta, 100);
            this.set_attitude(name, attitude, amt);
        }
        else if (amt < -100)
        {
            amt = Math.min(amt + delta, -100);
            this.set_attitude(name, attitude, amt);
        }
    }
}

setup.people.decay_special_attitudes = function(name)
{
    name = this.get_name(name);
    const specdegrade = ["anger", "suspicion"];
    for (const attitude of specdegrade)
    {
        let amt = this.get_attitude(name, attitude);
        if (amt > 0)
        {
            let reduce = Math.min(amt, 25);
            amt = Math.max(amt - reduce, 0);
            this.set_attitude(name, attitude, amt);

            // bleed off decaying attitudes into topline attitude changes (for example, anger fades but damages friendship)
            if (attitude == "anger")
            {
                this.alter_attitude(name, "friendship", -reduce / 3, false);
            }
            else if (attitude == "suspicion")
            {
                this.alter_attitude(name, "romance", -reduce / 3, false);
                this.alter_attitude(name, "trust", -reduce / 2, false);
            }
        }
        else if (amt < 0)
        {
            amt = 0;
            this.set_attitude(name, attitude, amt);
        }
    }
}

setup.people.decay_attitudes = function()
{
    // decay attitudes of any person not encountered within the last 14 days
    for (const p of Object.keys(V.people))
    {
        if (V.people[p].attitude)
        {
            if (V.people[p].lastInteraction && V.gameday - V.people[p].lastInteraction > 14)
                this.attitude_to_mean(p);
            if (Object.keys(V.people[p].attitude).includesAny(["anger", "suspicion"]))
