setup.people.skill_level = function(name, skill)
{
    let arcdata, subarcdata, rng;
    if (typeof name == "object" && name.temporary)
    {
        let obj = name;
        name = obj.name;

        arcdata = setup.ob_archetypes[obj.archetype];
        subarcdata = setup.ob_subarchetypes["none"];
        rng = new RNG(inthash(name));
    }
    else
    {
        name = this.get_name(name);

        if (setup.pc() && setup.pc().equals(name)) return setup.pc().skill_level(skill);

        if (V.people[name] && V.people[name].skills && V.people[name].skills[skill])
            return V.people[name].skills[skill];

        arcdata = setup.ob_archetypes[this.archetype(name)];
        subarcdata = setup.ob_subarchetypes[this.subarchetype(name)];
        rng = new RNG(inthash(name));
    }

    let lvl;
    if (arcdata.perfected.includes(skill) || subarcdata.perfected.includes(skill))
    {
        lvl = rng.randomrelfreq([10, 60, 9, 30, 8, 10]);
    }
    else if (arcdata.proficient.includes(skill) || subarcdata.proficient.includes(skill))
    {
        lvl = rng.randomrelfreq([8, 25, 7, 65, 6, 10]);
    }
    else if (arcdata.skilled.includes(skill) || subarcdata.skilled.includes(skill))
    {
        lvl = rng.randomrelfreq([6, 20, 5, 60, 4, 20]);
    }
    else if (arcdata.dabbling.includes(skill) || subarcdata.dabbling.includes(skill))
    {
        lvl = rng.randomrelfreq([4, 20, 3, 70, 2, 10]);
    }
    else
    {
        lvl = rng.randomrelfreq([2, 30, 1, 70]);
    }

    const people = setup.people_db();

    if (people[name] && people[name].courses && this.get_type(name) == "faculty")
    {
        // boost relevant professor skill levels
        for (const course of setup.ob_fixBadArray(setup.people_db()[name].courses))
            if (setup.School.get_course_attribute(course, "skills").includes(skill))
                lvl = Math.max(lvl, 6);
    }

    return lvl;
}

setup.people.skillcheck = function(name, skill, lvl)
{
    if (V.pc && V.pc.equals(name))
        return V.pc.skillcheck(skill, lvl);
    else
    {
        if (typeof name == "object")
            return name.skillcheck(skill, lvl);
        else
        {
            name = this.expand(name);
            return name.skillcheck(skill, lvl);
        }
    }
}

setup.people.skillleveled = function(name, skill, lvl)
{
    if (V.pc && V.pc.equals(name))
        return V.pc.skillleveled(skill, lvl);
    if (typeof name == "object")
        return name.skillleveled(skill, lvl);

    let level = this.skill_level(name, skill);
    return lvl <= level || lvl == 1;
}

setup.people.get_gender = function(name)
{
    if (typeof name == "object" && name.temporary)
        return name.gender;

    name = this.get_name(name);
    if (name == "PC" || name == V.pcname)
    {
        return V.pcgender;
    }
    else
    {
        let pdata = this.get_person(name);
        return pdata.species[1];
    }
}

setup.people.get_orientation = function(name)
{
    name = this.get_name(name);
    if (name == "PC" || name == V.pcname)
    {
        return V.pcsexpref;
    }
    else
    {
        let pdata = this.get_person(name);
        return pdata.attraction;
    }
}

