setup.people.anonymous_name = function(name, options = {})
{
    let anon = "";
    if (name == "PC")
    {
        anon = setup.pc().anonymous_name;
    }
    else if (typeof name == "object")
    {
        anon = name.anonymous_name;
    }
    else
    {
        name = this.get_name(name);
        let pobj = new Person({person: name, onlyname: !this.costume(name)});
        anon = pobj.anonymous_name;
    }

    if (options.aoran)
        anon = setup.ob_a_or_an(anon) + " " + anon;
    if (options.cap)
        anon = setup.ob_capitalize(anon);

    return anon;
}

setup.people.fullname = function(name)
{
    return this.get_display_name(name);
}

setup.people.nickname = function(name)
{
    if (name == "PC" || name == V.pcname)
    {
        return setup.pc().nickname || this.firstname(name);
    }
    else if (typeof name == "object")
    {
        return name.nickname || this.firstname(name);
    }
    else
    {
        const pdata = this.get_person(name);
        return pdata && pdata.nickname ? pdata.nickname : this.firstname(name);
    }
}

setup.people.firstname = function(name)
{
    if (name == "PC" || name == V.pcname || V.pc.equals(name))
    {
        return setup.pc().firstname();
    }
    let fullname = this.fullname(name);
    return fullname.split(' ')[0];
}

setup.people.lastname = function(name)
{
    let fullname = this.fullname(name);
    let list = fullname.split(' ');
    if (list.length == 1) return list[0];
    else return list.slice(1).join(" ");
}

setup.people.attraction = function(name)
{
    if (typeof name == "object" && name.temporary)
    {
        const attdata = setup.ob_get_gender_node(name.gender, "attraction", name.species);
        for (let i = 0; i < attdata.length; i++)
        {
            if (typeof(attdata[i]) == "object" && attdata[i].label == "bi")
            {
                return attdata[i];
            }
        }

        let att = name.attraction;
        if (["queer", "gay", "lesbian"].includes(att))
        {
            for (let i = 0; i < attdata.length; i++)
            {
                if (typeof(attdata[i]) == "object" && (attdata[i].label == "gay" || attdata[i].label == "lesbian" || attdata[i].label == "queer"))
                {
                    return attdata[i];
                }
            }
        }
        console.warn("Failed to get attraction for " + name + " with attraction \"" + att + "\". Is the save edited?");
        return null;
    }
    else
    {
        let pdata = this.get_person(name);
        let att = pdata.attraction;
        if (typeof att == "string")
        {
            const attdata = setup.ob_get_gender_node(pdata.species[1], "attraction", pdata.species[0]);
            for (let i = 0; i < attdata.length; i++)
            {
                if (typeof(attdata[i]) == "object" && attdata[i].label == att)
                {
                    return attdata[i];
                }
            }

            if (["queer", "gay", "lesbian"].includes(att))
            {
                for (let i = 0; i < attdata.length; i++)
                {
                    if (typeof(attdata[i]) == "object" && (attdata[i].label == "gay" || attdata[i].label == "lesbian" || attdata[i].label == "queer"))
                    {
                        return attdata[i];

                    }
                }
            }
            console.warn("Failed to get attraction for " + name + " with attraction \"" + att + "\". Is the save edited?");
            return null;
        }
        return att;
    }
}

setup.people.attracted_to_pc = function(name)
{
    // whether the pc's gender presentation is among this character's sexual preferences
    const genders = this.attraction(name).genders;
    return genders.includes(setup.ob_pcgender()) || (V.pc && setup.ob_relationships.partner(name) == "PC");
}

setup.people.attracted_enough_to_pc = function(name)
{
    // when we want to look at more than gender presentation and make sure the pc isn't a turnoff
    const pdata = this.get_person(name);
    if (!pdata)
        return true;
    else if ("desired relationship" in pdata && ["date", "fuckbuddy", "hatefuck"].includes(pdata["desired relationship"]))
        return true;
    else if (pdata.special || pdata.type == "faculty") // shouldn't really leave this to chance
        return this.attracted_to_pc(name);
    else if (tags().includes("chargen"))
        return this.attracted_to_pc(name);
    else
        return this.attracted_to_pc(name);
        //return this.attracted_to_pc(name) && (this.npc_turnon_factor(name) >= 0 || this.get_attitude(name, "lust") >= 200 || this.get_attitude(name, "romance") >= 200);
}

setup.people.pc_attracted_to = function(name, inclusive = true)
{
    // whether the npc's gender presentation is among the pc's sexual preferences
    let gender;
    if (typeof name == "object")
        gender = name.gender;
    else
    {
        let pdata = this.get_person(name);
        if (!pdata)
        {
            let compet = setup.School.name_to_game_competitor(name);
            if (compet)
                gender = compet.gender;
            else
                gender = V.pcgender;
        }
        else
        {
            if (setup.ob_relationships.relationship_type_with(name) == "romantic" || ["fuckbuddy", "hatefuck"].includes(setup.ob_relationships.relationship_with(name)))
                return true;

            gender = pdata.species[1];
        }
    }
    const genders = [...V.pcsexualprefs];
    if (inclusive && !genders.includesAny(["male", "female"]))
    {
        let cis = setup.ob_nearest_cisgender(genders[0]);
        genders.push(cis);
    }
    return genders.includes(gender);
}

setup.people.npc_attracted_to = function(name1, name2)
{
    let pdata1 = this.get_person(name1);
    let pdata2 = this.get_person(name2);
    const genders = this.attraction(name1).genders;
    let gender = pdata2.species[1];
    return genders.includes(gender);
}

setup.people.npc_mutual_attraction = function(name1, name2)
{
    if (this.get_name(name1) == this.get_name(name2)) return false;
    let pdata1 = this.get_person(name1);
    let pdata2 = this.get_person(name2);
    const genders1 = this.attraction(name1).genders;
    let gender2 = pdata2.species[1];
    const genders2 = this.attraction(name2).genders;
    let gender1 = pdata1.species[1];
    return genders1.includes(gender2) && genders2.includes(gender1);
}

setup.people.mutual_attraction = function(name)
{
    return this.attracted_enough_to_pc(name) && this.pc_attracted_to(name);
}

setup.people.inclinations = function(name)
{
    name = this.get_name(name);
    let rng = setup.ob_newRNG(this.get_name(name) + "inclinations");

    if (setup.pc() && setup.pc().equals(name))
    {
        return V.pcinclinations;
    }

    let arch,subarch,pdata,inclins;
    if (typeof name == "object" && name.temporary)
    {
        arch = setup.ob_archetypes[name.archetype];
        subarch = setup.ob_subarchetypes["none"];
        inclins = [];
    }
    else
    {
        pdata = this.get_person(name) || setup.School.name_to_game_competitor(name);
        if (!pdata) return [];
        if (pdata.inclinations)
        {
            pdata.inclinations = [...new Set(pdata.inclinations)];
            inclins = [...pdata.inclinations];
        }
        else
        {
            arch = setup.ob_archetypes[pdata.archetype];
            subarch = setup.ob_subarchetypes[this.subarchetype(name)];

            inclins = [...arch.inclinations];
        }
    }

    if (subarch)
    {
        for (let subarchinc of subarch.inclinations)
        {
            if (!inclins.includes(subarchinc) && !inclins.includesAny(this.opposing_inclinations(subarchinc)))
                inclins.push(subarchinc);
        }
    }

    if (arch && "additional inclinations" in arch)
    {
        let incs = arch["additional inclinations"];
        let rng = new RNG(inthash(name + " addinclinations"));
        for (let i = 0; i < incs.length; i += 2)
        {
            if (rng.random() <= incs[i + 1] && !inclins.includesAny(this.opposing_inclinations(incs[i])))
            {
                inclins.push(incs[i]);
            }
        }
    }

    if (!pdata || !this.is_special(name))
    {
        // Filter the special seeds that exist, map a chance value if followed by an int, sort them, and return the array of the used ones
        const ordered_specialseeds = Object.keys(setup.ob_worldgen.special_seeds)
            .filter(special => V.seed.includes(special))
            .map(specialseed => {
                const index = V.seed.indexOf(specialseed);
                const nextChar = V.seed[index + specialseed.length];
                const chance =
                    (nextChar >= '1' && nextChar <= '9')
                        ? (nextChar.charCodeAt(0) - '0'.charCodeAt(0)) / 10
                        : 1;

                return {specialseed, index, chance};
            })
            .sort((a, b) => a.index - b.index);

        for (let { specialseed, chance } of ordered_specialseeds)
        {
            if (rng.random() < chance) {
                for (let inc of setup.ob_worldgen.special_seeds[specialseed].addinclinations ?? []) {
                    if (!inclins.includes(inc)) inclins.push(inc);
                }

                for (let inc of setup.ob_worldgen.special_seeds[specialseed].reminclinations ?? []) {
                    inclins = inclins.filter(i => i !== inc);
                }
            }
        }
    }

    if (pdata && pdata.addinclinations)
    {
        for (let inc of pdata.addinclinations)
            if (!inclins.includes(inc))
                inclins.push(inc);
    }

    if (V.polybonus == undefined) V.polybonus = 1;
    if (!inclins.includesAny(["Open Relationships", "Polyamorous", "Chaste", "Aromantic", "Casual Hookup", "Insecure"]))
    {
        if (inclins.includesAny(["Slut", "Cheater"]) && rng.random() < [0, 0.4, 0.8, 1][V.polybonus])
        {
            inclins.push("Open Relationships");
        }
        else if (inclins.includesAny(["Forward"]) && rng.random() < [0, 0.1, 0.4, 1][V.polybonus])
        {
            inclins.push("Open Relationships");
        }
        else if (inclins.includesAny(["Confident"]) && rng.random() < [0, 0.1, 0.4, 1][V.polybonus])
        {
            inclins.push("Polyamorous");
        }
        else if (rng.random() < [0, 0, 0.2, 0.5][V.polybonus])
        {
            if (rng.random() < 0.5)
                inclins.push("Polyamorous");
            else
                inclins.push("Open Relationships");
        }
    }

    if (!inclins.includesAny(["Chaste", "Asexual"]))
    {
        let posprefchances = {"Likes Standing Position": 0.02, "Likes Missionary": 0.1, "Likes Doggy Style": 0.1, "Likes Spooning": 0.08, "Likes Cowgirl": 0.1};
        if (inclins.includesAny(["Dominant", "Dominant Vibe"]))
            if (this.has_part(name, "penis"))
                posprefchances["Likes Doggy Style"] += 0.2;
            else
                posprefchances["Likes Cowgirl"] += 0.1;
        if (inclins.includesAny(["Submissive", "Submissive Vibe"]))
            if (this.has_part(name, "penis"))
                posprefchances["Likes Cowgirl"] += 0.2;
            else
                posprefchances["Likes Doggy Style"] += 0.1;

        if (!this.is_femme(name) && !this.attraction(name).genders.includesAny(["female", "transgender female"]))
            posprefchances["Likes Cowgirl"] = 0; // nothing PARTICULARLY wrong with this happening as it's a valid position except it'd read a bit funny I think

        for (const [pospref, poschance] of Object.entries(posprefchances))
            if (rng.random() < poschance)
                inclins.push(pospref);
    }

    if (pdata && pdata.subinclinations)
    {
        for (let inc of pdata.subinclinations)
            if (inclins.includes(inc))
                inclins.delete(inc);
    }

    return [...new Set(inclins)];
}

setup.people.opposing_inclinations = function(inclination)
{
    // list of all inclinations opposing the given one
    const incinfo = setup.inclinations[inclination];
    if (!incinfo.requires || !incinfo.requires.noinclinations) return [];
    return incinfo.requires.noinclinations;
}

setup.people.prereq_inclinations = function(inclination)
{
    // list of all prereqs for the given inclination
    const incinfo = setup.inclinations[inclination];
    if (!incinfo.requires || !incinfo.requires.inclinations) return [];
    return incinfo.requires.inclinations;
}

setup.people.supporting_inclinations = function(inclination)
{
    // list of all inclinations that have the given inclination as a prereq
    const retval = [];
    for (const [inc, incinfo] of Object.entries(setup.inclinations))
        if (this.prereq_inclinations(inc).includes(inclination))
            retval.push(inc);
    return [...new Set(retval)];
}

setup.people.has_inclination = function(name, inclination)
{
    if (V.pc && V.pc.equals(name) && inclination == "Lucky" && setup.ob_dorm_has("seven-leaf clover")) return true;

    return this.inclinations(name).includes(inclination);
}

setup.people.add_inclination = function(name, inclination)
{
    let pdata = this.get_person(name);
    if (!pdata.addinclinations)
        pdata.addinclinations = [];
    if (!pdata.addinclinations.includes(inclination))
        pdata.addinclinations.push(inclination);
    return pdata.addinclinations;
}

setup.people.body_parts = function(name)
{
    if (typeof name == "object") return name.body_parts;
    name = this.get_name(name);
    if (name == "PC")
        return setup.pc().body_parts;
    else
    {
        let pdata = this.get_person(name);
        return setup.ob_get_gender_node(pdata.species[1], "parts", pdata.species[0]);
