}

setup.people.is_special = function(name)
{
    let pdata = this.get_person(name);
    return pdata ? pdata.special : false;
}

setup.people.allow_free_interaction = function(name)
{
    let pdata = this.get_person(name);
    return !pdata.special || pdata.allowfree || setup.ob_relationships.relationship_type_with(name) == "romantic";
}

setup.people.has_any_inclination = function(name, inclinationscheck)
{
    if (V.pc && V.pc.equals(name)) return V.pc.has_any_inclination(inclinationscheck);
    let inclinations;
    name = this.get_name(name);
    if (this.cached_inclinations && this.cached_inclinations[0] == name && Date.now() - this.cached_inclinations[1] < 1000)
    {
        inclinations = this.cached_inclinations[2];
    }
    else
    {
        inclinations = this.inclinations(name);
        this.cached_inclinations = [name, Date.now(), inclinations];
    }

    if (typeof inclinationscheck == "string" && inclinationscheck in setup.ob_archetypes.inclination_sets)
        inclinationscheck = setup.ob_archetypes.inclination_sets[inclinationscheck];
    else if (typeof inclinationscheck == "string")
        inclinationscheck = [inclinationscheck];

    return inclinations.includesAny(inclinationscheck);
}

setup.people.sexually_passive = function(name)
{
    return this.has_any_inclination(name, setup.ob_archetypes.inclination_sets.passive)
        && !this.has_any_inclination(name, setup.ob_archetypes.inclination_sets.active);
}

setup.people.people_of_type = function(type, people = Object.keys(V.people))
{
    if (this.cached_people_of_type && this.cached_people_of_type[type] && Date.now() - this.cached_people_of_type[type][1] < 1000)
    {
        return this.cached_people_of_type[type][0];
    }

    const retval = [];
    for (let i = 0; i < people.length; i++)
    {
        if ((type == "all" || this.get_type(people[i]) == type) && !this.is_removed(people[i]))
        {
            retval.push(people[i]);
        }
    }

    if (!this.cached_people_of_type) this.cached_people_of_type = {};
    this.cached_people_of_type[type] = [retval, Date.now()];

    return retval;
}

setup.people.people_of_archetype = function(type, people = Object.keys(setup.people_db()))
{
    const retval = [];
    for (let i = 0; i < people.length; i++)
    {
        if ((type == "all" || this.archetype(people[i]) == type) && !this.is_removed(people[i]))
        {
            retval.push(people[i]);
        }
    }
    return retval;
}

setup.people.get_job = function(name)
{
