setup.people.employees = function(job)
{
    if (!V.businesses[job]) return [];
    else return V.businesses[job].employees;
}

setup.people.add_employee = function(name, business)
{
    name = this.get_name(name);
    V.people[name].job = business;
    if (!V.businesses[business].employees.includes(name))
        V.businesses[business].employees.push(name);
}

setup.people.get_age = function(name)
{
    // only use this when an approximation is good enough
    // we need to build the npc to get their actual age
    if (V.pc && V.pc.equals(name)) return V.pcage;

    if (typeof name == "object" && name.age) return name.age;

    name = this.get_name(name);
    let pdata = this.get_person(name);
    if (pdata && pdata.age) return Math.max(pdata.age, 18);
    let archetype = setup.ob_archetypes[pdata.archetype];
    let age = (archetype.age[0] + archetype.age[1]) / 2;
    return Math.max(age, 18);
}

setup.people.get_wealth = function(name)
{
    name = this.get_name(name);
    let pdata = this.get_person(name);
    if (pdata.wealth) return pdata.wealth;
    let archetype = setup.ob_archetypes[pdata.archetype];
    let rng = new RNG(inthash(name));
    let wealth = rng.rir(archetype.wealth[0], archetype.wealth[1]);
    return wealth;
}

setup.people.wealthTable = [
    [0, 500],
    [50, 1200],
    [150, 1700],
    [250, 2300],
    [350, 3200],
    [450, 4400],
    [550, 6200],
    [650, 9000],
    [750, 14000],
    [850, 24000],
    [950, 60000],
    [1000, 100000]
];
setup.people.wealth_to_income = function(wealth)
{
    // monthly income
    // wealth is meant to be a bit abstracted, so don't set your watch by this algorithm, but for certain things (rent) it's helpful to imagine wealth as an actual income level

    const table = this.wealthTable;
    wealth = Math.clamp(wealth, 0, 1000);

    let i = 0;
    while (i < table.length - 2 && wealth > table[i + 1][0])
        i++;

    const [w0, m0] = table[i];
    const [w1, m1] = table[i + 1];
    const f = (wealth - w0) / (w1 - w0);

    return Math.round(m0 * Math.pow(m1 / m0, f));
}

setup.people.get_styles = function(name)
{
    const pdata = this.get_person(name);
    if (pdata.style)
        return [pdata.style];
    else
        return setup.ob_archetypes[this.archetype(name)].style;
}

setup.people.likability_factor = function(name, ignoredesrel = false)
{
    // combine various factors to build a difficulty level to be checked against pc's charisma

    const profile = false;
    let now;
    if (profile)
    {
        now = Date.now();
        if (!setup.ob_likeprofiler)
        {
            setup.ob_likeprofiler = {};
            setup.ob_likeprofilerinstances = 1;
            for (let i = 1; i <= 10; i++)
                if (!setup.ob_likeprofiler[i])
                    setup.ob_likeprofiler[i] = 0;
        }
        else
        {
            setup.ob_likeprofilerinstances++;
        }
    }

    name = this.get_name(name);

    let inclinations = this.inclinations(name);
    let pdata = this.get_person(name);
    let archetype = setup.ob_archetypes[pdata.archetype];
    let moods = this.moods_for_pc(name);

    let friendmod = pdata["friendliness mod"] || archetype["friendliness mod"] || 0;

    let age = Math.max((archetype.age[0] + archetype.age[1]) / 2, 18);
    let agefactor = Math.max(Math.floor(((age - 20) / 10) / 1.25), 0);
    let wealth = (archetype.wealth[0] + archetype.wealth[1]) / 2;
    let wealthfactor = Math.max(Math.floor(((wealth - 300) / 100) / 1.667), 0);

    if (profile) setup.ob_likeprofiler[1] += Date.now() - now;

    let usingspecialseed = false;
    for (let spseed of Object.keys(setup.ob_worldgen.special_seeds))
        if (V.seed.includes(spseed))
        {
            usingspecialseed = true;
            break;
        }

    if (profile) setup.ob_likeprofiler[2] += Date.now() - now;

    let incfactor = 0;
    if (inclinations.includesAny(["Breaker", "Taker", "Whore Connoisseur"]) && !usingspecialseed)
        incfactor += 4;
    if (inclinations.includesAny(["Sadist"]) && !usingspecialseed)
        incfactor += 2;
    if (inclinations.includesAny(["Loner"]))
        incfactor += 1;
    if (inclinations.includesAny(["Pleaser", "Submissive", "Paypig", "Stoner"]) && !usingspecialseed)
        incfactor -= 2;
    if (inclinations.includesAny(["Insecure"]))
        incfactor -= 1;
    if (inclinations.includesAny(["Dominant"]) && !usingspecialseed)
        incfactor += 1;
    if (inclinations.includesAny(["Bully"]) && !setup.pc().has_inclination("Bully"))
        incfactor += 3;

    if (profile) setup.ob_likeprofiler[3] += Date.now() - now;

    let relfactor = 0;
    if (pdata.type == "student")
        relfactor -= 1;

    let desfactor = 0;
    let promisc = this.get_reputation("promiscuity", this.get_type(name));
    if (setup.pc().will_notice_cum_covering() && !setup.pc().cummed_on_by(name))
        promisc += 500;
    let promiscdiff = Math.max(promisc / 100, 0);
    let kindness = this.get_reputation("kindness", this.get_type(name));
    let meanness = this.get_reputation("meanness", this.get_type(name));

    if (profile) setup.ob_likeprofiler[4] += Date.now() - now;

    if (!ignoredesrel)
    {
        let desired = this.desired_relationship(name);

        if (V.bestfriend == name)
            desfactor -= 5;
        else if (desired == "rival")
            desfactor += 5 + promiscdiff;
        else if (desired == "hatefuck")
            desfactor += 4;
        else if (desired == "date")
            desfactor += -2 + promiscdiff;
        else if (desired == "friend")
            desfactor += -2 + (promiscdiff / 2);
        else if (desired == "fuckbuddy")
            desfactor += -2;
        else
            desfactor += promiscdiff;
    }

    if (profile) setup.ob_likeprofiler[5] += Date.now() - now;

    let turnonfactor = Math.min(0, -this.npc_friendship_factor(name));

    let momentumfactor = Math.floor((this.get_attitude(name, "friendship") / 100)) / 2;

    let hygienefactor = 0;
    let hygiene = setup.ob_needs.get_need("Hygiene");
    if (hygiene <= 0) hygienefactor = 4;
    else if (hygiene <= 100) hygienefactor = 3;
    else if (hygiene <= 250) hygienefactor = 2;
    else if (hygiene <= 500) hygienefactor = 1;
    if (setup.pc().wearing_dirty_clothes()) hygienefactor += 2;

    let moodfactor = 0;
    if (moods.includes("happy"))
        moodfactor -= 1;
    else if (moods.includes("mildly irritated"))
        moodfactor += 1;
    else if (moods.includes("angry"))
        moodfactor += 3;

    if (profile) setup.ob_likeprofiler[6] += Date.now() - now;

    let factor = 2 + agefactor + wealthfactor + incfactor + relfactor + desfactor - momentumfactor + hygienefactor + friendmod + turnonfactor + moodfactor;

    // reputation effects
    // (these will be kind of... just how society works, for better or worse)
    if (promisc > 0 && factor >= 0 && this.is_femme(V.pc) && this.is_femme(name) && !this.has_any_inclination(name, "casualsex") && this.has_any_inclination(name, "judgmentalaboutsex") && !this.attracted_to_pc(name) && V.kinkcontent.includes("slutshaming") && !["friendship", "romantic"].includes(setup.ob_relationships.relationship_type_with(name)))
        factor += promisc / 4;
    if (promisc > 0 && this.is_masc(name) && this.attracted_to_pc(name))
        factor -= promisc / 4;
    if (factor > 0)
        if (kindness > 0)
            factor += kindness / 4;
        if (meanness > 0)
            factor -= meanness / 4;
    else if (factor < 0)
        if (kindness > 0)
            factor -= kindness / 4;
        if (meanness > 0)
            factor += meanness / 4;

    if (profile) setup.ob_likeprofiler[7] += Date.now() - now;

    // highly specific stuff:

    // relations for sports people
    const teammate = this.is_teammate(name);
    if (setup.is_jock())
        if (this.cares_about_sports(name)) // sports fans like you if you're on the team
            factor -= 1;
        else if (teammate) // teammates really like if you're doing well
            factor -= 4;
    else if (teammate) // teammate but we're not a jock
        factor -= 2;
    else if (pdata.sports && pdata.sports.includes("football") && V.pcsports && V.pcsports.includes("cheerleading")) // football players like their cheerleaders
        factor -= 4;
    else if (pdata.sports && pdata.sports.includes("cheerleading") && V.pcsports && V.pcsports.includes("football")) // and cheerleaders like their football players, a bit
        factor -= 2;

    if (profile) setup.ob_likeprofiler[8] += Date.now() - now;

    // helleborine boys are upset if you didn't take the milkshake deal!
    let quadparty = V.quadparty;
    if (quadparty)
    {
        if (pdata.residence == "Helleborine Hall" && quadparty.milkshakeproposal && !quadparty.milkshakedeal && this.get_gender(name) == "male")
        {
            factor += 5;
        }
        else if (name == quadparty.greeter)
        {
            // nicer greeter
            factor += -4;
        }
    }

    if (profile) setup.ob_likeprofiler[9] += Date.now() - now;

    // Greek house relations
    if (setup.ob_houses.in_same_house(name))
    {
        factor += -4;
    }
    else if (setup.ob_houses.in_allied_house(name))
    {
        factor += -3;
    }
    else if (setup.ob_houses.in_rival_house(name) && !["friendship", "romantic"].includes(setup.ob_relationships.relationship_type_with(name)))
    {
        factor += 4;
    }
    if (V.lefthouse)
    {
        let house = setup.ob_houses.get_house(name);
        if (V.lefthouse.includes(house))
            factor += 2;
    }

    if (profile) setup.ob_likeprofiler[10] += Date.now() - now;

    // niche relations
    const nichemodifiers = {
        "The Best Friend": -20,
        "The Greek Mentor": -5,
        "The Greek Rival": 8,
        };
    for (const [niche, nichemod] of Object.entries(nichemodifiers))
        if (V.niches[niche] == name)
            factor += nichemod;

    // emphasize difficulty... otherwise at charisma 10 everybody loves you
    let difficulty = Math.round(Math.max(Math.min(factor, 10), 0));

    let conversion = [
        difficulty,     // 0
        difficulty,     // 1
        difficulty,     // 2
        difficulty,     // 3
        5,              // 4
        6,              // 5
        8,              // 6
        10,             // 7
        12,             // 8
        15,             // 9
        20,             // 10
    ];

    let retval = conversion[difficulty];

    return retval;
}

setup.people.attraction_modifier = function(name)
{
    // for when we want to modify a likability check by attraction factor
    if (!this.attracted_to_pc(name)) return 10;
    let base = -this.npc_turnon_factor(name);

    let physfactors = 0;
    if (V.pc.is_showing_cleavage()) physfactors++;
    if (V.pc.nipple_erectness_visible()) physfactors++;
    if (V.pc.is_in_short_skirt() || V.pc.is_in_short_shorts()) physfactors++;
    if (V.pc.has_visible_muscles()) physfactors++;
    if (V.pc.bulge_visible()) physfactors++;
    physfactors = -Math.min(2, physfactors);

    return base + physfactors;
}

setup.people.residence = function(npc)
{
    if (this.has_greek_house_room(npc)) return false;
    const pdata = this.get_person(npc);
    return pdata.residence;
}

setup.people.lives = function(npc)
{
    const pdata = this.get_person(npc);
    if (pdata?.residenceType) return pdata.residenceType;

    let type = this.get_type(npc);
    if (type == "student")
    {
        if (this.has_greek_house_room(npc))
        {
            return setup.ob_houses.get_house(npc);
        }
        else
        {
            let hall = this.residence(npc) || "off-campus";
            if (hall != "off-campus")
            {
                return hall;
            }
        }
    }

    if (setup.ob_relationships.is_married(npc))
    {
        // well, we probably don't live in two different places, so let's keep this consistent
        let name1 = this.get_name(npc);
        let name2 = this.get_name(setup.ob_relationships.partner(npc));

        if (name2 == [name1, name2].sort()[0])
        {
            // use spouse's residence
            return setup.people.lives(name2);
            // else we fall through to the random pick below
        }
    }

    let houseodds = 20;
    if (setup.ob_relationships.is_married(npc))
        houseodds += 20;
    if (setup.people.get_wealth(npc) >= 500)
        houseodds += 30;

    let rng = new RNG(inthash(this.get_name(npc)));
    return rng.randomrelfreq(["house", houseodds, "apartment", 100 - houseodds]);
}

setup.people.npcs_live_together = function(npc1, npc2)
{
    // whether these two NPCs live together
    // (in theory, that is... whether they actually occupy the same housing unit is a different question)

    const partners = setup.ob_relationships.all_partners(npc1);
    if (!partners.includes(npc2)) return false;

    if (setup.ob_relationships.is_married(npc1))
        return true;


    return false;
}

setup.people.npc_lives_with_a_partner = function(npc)
{
    const partners = setup.ob_relationships.all_partners(npc);
    return partners.some(partner => !V.pc.equals(partner) && this.npcs_live_together(npc, partner));
}

setup.people.lives_on_campus = function(npc)
{
    // whether they live on campus in a residence hall or greek house
    // just assume something else is making sure this person is actually a student
    if (this.has_greek_house_room(npc))
        return true;
    else
        return this.residence(npc) != "off-campus";
}

setup.people.prefers_motel = function(npc)
{
    if (setup.ob_housing.is_roommate(npc))
        return false;

    let type = this.get_type(npc);
    if (type == "student")
    {
        let hall = this.residence(npc) || "off-campus";
        if (hall != "off-campus")
        {
            return setup.ob_relationships.npc_is_cheating(npc);
        }
    }

    let rng = setup.ob_newRNG(this.get_name(npc));
    return setup.ob_relationships.npc_is_cheating(npc) || (setup.people.is_professor(npc) && setup.people.professor_reaction(npc) == "Married Professor") || rng.random() < 0.1;
}

setup.people.npc_association_factor = function(npc1, npc2, raw = false)
{
    // how likely two NPCs are to associate with each other, taking some demographic type stuff into account

    if (!raw)
    {
        // first handle simulated relationships
        let rel = setup.ob_nPCSimulation.get_relationship(npc1, npc2);
        if (rel)
        {
            const relinfo = setup.ob_relationships.db[rel];
            if (["friendship", "romantic"].includes(relinfo.type))
                return 1;
            else if (["enemy"].includes(relinfo.type))
                return 0;
        }
    }

    let pdata1 = this.get_person(npc1);
    let archetype1 = setup.ob_archetypes[pdata1.archetype];
    let age1 = (archetype1.age[0] + archetype1.age[1]) / 2;
    let wealth1 = (archetype1.wealth[0] + archetype1.wealth[1]) / 2;
    let type1 = pdata1.type;
    let job1 = pdata1.job;

    let pdata2 = this.get_person(npc2);
    let archetype2 = setup.ob_archetypes[pdata2.archetype];
    let age2 = (archetype2.age[0] + archetype2.age[1]) / 2;
    let wealth2 = (archetype2.wealth[0] + archetype2.wealth[1]) / 2;
    let type2 = pdata2.type;
    let job2 = pdata2.job;

    if (pdata1.partner == pdata2) return 1;

    let factor = 0.0;

    if (type1 == "student")
    {
        if (Math.abs(wealth1 - wealth2) < 300)
            factor += 0.05;
        if (Math.abs(wealth1 - wealth2) < 100)
            factor += 0.05;
        if (this.same_cohort(npc1, npc2))
            factor += 0.25;
        if (archetype1 == archetype2)
            factor += 0.55;
        if (job1 && job1 == job2)
            factor += 0.1;
    }
    else
    {
        if (Math.abs(age1 - age2) < 20)
            factor += 0.1;
        if (Math.abs(age1 - age2) < 10)
            factor += 0.1;
        if (Math.abs(wealth1 - wealth2) < 300)
            factor += 0.1;
        if (Math.abs(wealth1 - wealth2) < 100)
            factor += 0.1;
        if (type1 == type2)
            factor += 0.1;
        if (archetype1 == archetype2)
            factor += 0.2;
        if (job1 && job1 == job2)
            factor += 0.3;
    }

    return factor;
}

setup.people.get_relationship = function(npc1, npc2)
{
    npc1 = this.get_name(npc1);
    npc2 = this.get_name(npc2);

    if (setup.ob_relationships.partner(npc1) == npc2)
    {
        return this.get_person(npc1).partnerType || "partner";
    }

    let rel = setup.ob_nPCSimulation.get_relationship(npc1, npc2);
    if (rel) return rel;

    let seed = [npc1, npc2].sort().join(' ');
    let rng = setup.ob_newRNG(seed);
    let assocfactor = this.npc_association_factor(npc1, npc2);

    let friendresistancefactor = 1.8; // the higher this is, the less often high associations result in firmed-up friendship
    let rivalresistancefactor = 6.0;
    let friendchance = assocfactor < 0.5 ? 0 : ((assocfactor - 0.5) / 0.5 / friendresistancefactor);
    let rivalchance = assocfactor >= 0.5 || assocfactor <= 0.1 ? 0 : ((0.5 - assocfactor) / 0.5 / rivalresistancefactor);

    let rnd = rng.random();
    if (rnd < friendchance)
        return "friend";
    else if (rnd < rivalchance)
        return "rival";
}

setup.people.is_dating = function(name)
{
    return this.date_count(name) > 0;
}

setup.people.date_count = function(name)
{
    name = this.get_name(name);
    return V.hangoutmemory?.[name]?.date || 0;
}

setup.people.willing_date = function(name)
{
    let basecheck =
            this.desired_relationship(name) == "date" || this.desired_relationship(name, false) == "date" ||
            ((this.desired_relationship(name) == "fuckbuddy" || this.desired_relationship(name, false) == "fuckbuddy") ||
            (this.desired_relationship(name) == "indifferent" && this.attracted_to_pc(name) && !setup.ob_relationships.in_relationship(name) && this.likability_factor(name) <= 2 && this.npc_turnon_factor(name) >= 0)
            && !this.has_any_inclination(name, "nodating"));

    if (!basecheck) return false;

    let repcheck = this.reputation_mismatch(name);
    if (!repcheck[0] && setup.ob_relationships.partner(name) != "PC") return false;

    return true;
}

setup.people.reputation_mismatch = function(name)
{
    // determine if PC's reputation and this NPC's inclinations will make them not want to date
    if (this.get_attitude(name, "friendship") >= 1000 || this.get_attitude(name, "lust") >= 800 || this.get_attitude(name, "romance") >= 600)
        return [true];

    let type = this.get_type(name);

    if ((V.pc.has_inclination("Kind") || setup.people.kindness_reputation(type) >= 400) && this.has_inclination(name, "Bully"))
        return [false, "You're just too... nice"];
    else if ((V.pc.has_inclination("Bully") || setup.people.meanness_reputation(type) >= 400) && this.has_inclination(name, "Kind"))
        return [false, "You're a bully"];

    if ((V.pc.has_inclination("Slut") || setup.people.promiscuity_reputation(type) >= 500) && this.has_inclination(name, "Chaste"))
        return [false, "You sleep around too much for my liking"];

    if (this.is_student(name))
    {
        let score = setup.School.current_average_score();
        if (this.is_exceptional_student(name) && score != -1 && score < 0.6)
            return [false, "You're... kind of a doofus, to be completely honest"];
    }

    return [true];
}

setup.people.desired_relationship = function(name, existingrelationshipoverride = true)
{
    // determine what sort of relationship the npc desires with the pc
    // (we're really just sort of labeling emergent behavior rather than hardcoding something here, mostly)

    // from 0.5, relationships the player has established with NPCs help guide their behavior.
    // relationships have their own exit conditions, so if the NPC's attitude changes,
    // the relationships system will exit them from it
    // and the older 'desired relationship' system will again take precedence
    const relationship = setup.ob_relationships.relationship_with(name);
    if (existingrelationshipoverride && relationship && setup.ob_relationships.db[relationship].closestDesiredRelationship)
    {
        let desrel = setup.ob_relationships.db[relationship].closestDesiredRelationship;
        let desrelactual = this.desired_relationship(name, false);

        let override = {
            "date": ["friend", "fuckbuddy"],
            "fuckbuddy": ["friend"],
            "hatefuck": ["rival"],
        };
        if (desrelactual in override && override[desrelactual].includes(desrel))
            return desrelactual;

        return desrel;
    }

    // sorry for reductive gender-y stuff but I think, in a general sense, events will ring truer this way
    // and anyway there's a lot of overlap so there's not much effective difference
    let femme = ["female", "transgender female", "nonbinary afab"];
    let masc = ["male", "transgender male", "nonbinary amab"];
    name = this.get_name(name);
    let gender = this.get_gender(name);
    let isfemme = femme.includes(gender);
    let ismasc = masc.includes(gender);

    const attracted = this.attracted_enough_to_pc(name);

    const incsets = setup.ob_archetypes.inclination_sets;
    const isex = setup.ob_relationships.is_ex(name);
    const ispartner = setup.ob_relationships.partner(name) == "PC";

    let pdata = this.get_person(name);
    if ("desired relationship" in pdata) {
        return pdata["desired relationship"];
    }

    const arch = setup.ob_archetypes[pdata.archetype];
    const age = arch.age[0];
    const faculty = this.get_type(name) == "faculty";
    const professor = faculty && this.get_person(name).courses;

    if (professor)
    {
        if (!this.attracted_to_pc(name))
            return "indifferent";
        else if (this.professor_intimacy(name) >= 2)
            return this.get_attitude(name, "romance") > this.get_attitude(name, "lust") ? "date" : "fuckbuddy";
        else
            return "indifferent";
    }

    const dates = this.is_dating(name) || 0;
    const sexpartner = this.is_sexpartner(name);

    const inrelationship = setup.ob_relationships.in_exclusive_relationship(name) && setup.ob_relationships.partner(name) != "PC";
    const inrelationshipwithpc = setup.ob_relationships.partner(name) == "PC";
    const inotherrelationship = inrelationship && !inrelationshipwithpc;

    const mistrusts = this.get_attitude(name, "trust") <= -200;

    let turnon = this.npc_turnon_factor(name);
    let lusttippoint;
    if (turnon == 2)
        lusttippoint = 100;
    else if (turnon == 1)
        lusttippoint = 200;
    else if (turnon == -1)
        lusttippoint = 400;
    else if (turnon == -2)
        lusttippoint = 500;
    else
        lusttippoint = 300;
    if (isfemme) lusttippoint += 100;
    if (this.has_any_inclination(name, "slut")) lusttippoint -= 200;
    if (this.has_inclination(name, "Chaste")) lusttippoint += 800;

    const datespeople = !faculty && !this.has_any_inclination(name, "nodating");
    const asexual = this.has_inclination(name, "Asexual");
    const casualsex = this.has_any_inclination(name, "casualsex");

    const mightcheat = !this.has_inclination(name, "Loyal") && (this.has_inclination(name, "Cheater") || this.get_attitude(name, "lust") >= lusttippoint + (setup.ob_nPCSimulation.has_flag(name, 181) ? 200 : (setup.ob_nPCSimulation.has_flag(name, 180) ? 400 : 600)));

    const repcheck = setup.people.reputation_mismatch(name);

    //console.log(casualsex, isex);
    if (ispartner && this.get_attitude(name, "friendship") >= 0 && this.get_attitude(name, "romance") >= 100)
        return "date";
    else if (isex)
    {
        if (setup.ob_relationships.is_recent_ex(name))
        {
            if (this.get_attitude(name, "lust") >= 800 && casualsex && !inotherrelationship && !mistrusts)
                if (this.get_attitude(name, "friendship") <= -100)
                    return "hatefuck";
                else
                    return "fuckbuddy";
            else if (this.get_attitude(name, "friendship") >= 0)
                return "friend";
            else
                return "rival";
        }
        else
        {
            if (ispartner)
                return "date";
            else if (this.get_attitude(name, "romance") >= 600 && this.get_attitude(name, "romance") > this.get_attitude(name, "lust") && repcheck[0] && !mistrusts && attracted)
                return "date";
            else if (this.get_attitude(name, "lust") >= 200 && casualsex && !inotherrelationship && !mistrusts)
                if (this.get_attitude(name, "friendship") <= -100)
                    return "hatefuck";
                else
                    return "fuckbuddy";
            else if (this.get_attitude(name, "friendship") >= 0)
                return "friend";
            else if (this.get_attitude(name, "friendship") <= -100)
                return "rival";
            else
                return "indifferent";
        }
    }
    else if (ispartner)
    {
        return "date";
    }
    else if (this.get_attitude(name, "romance") > 0 && this.get_attitude(name, "romance") > this.get_attitude(name, "lust") && dates && !inotherrelationship && repcheck[0] && !mistrusts && attracted)
        return "date";  // make desire to date 'sticky' if already been dating
    else if (this.get_attitude(name, "romance") >= 100 && age < 35 && !inotherrelationship && attracted)
    {
