setup.people.likes_pc = function(name, difficulty = 0)
{
    const now = Date.now();
    name = this.get_name(name);
    if (this.cached_likes && this.cached_likes[name] && now - this.cached_likes[name][0] < 100 && this.cached_likes[name][1] == difficulty)
    {
        // caching makes things faster and also ensures that if this is checked in rapid succession, results are consistent
        return this.cached_likes[name][2];
    }

    let retval = V.pc.skillcheck("Charisma", this.likability_factor(name) + difficulty);

    if (!this.cached_likes) this.cached_likes = {};
    this.cached_likes[name] = [now, difficulty, retval];

    return retval;
}

