setup.people.find_hobby = function(name, random = true)
{
    const skills = setup.ob_skills.otherskills;
    const relfreq = [];
    if (name == "PC" || name == V.pcname || (setup.pc() && setup.pc().equals(name)))
    {
        let pc = setup.pc();
        for (let i = 0; i < skills.length; i++)
        {
            let skill = skills[i].name;
            if (skills[i]["hobby name"])
            {
                let lvl = pc.skill_level(skill);
                if (lvl > 0)
                    relfreq.push(skills[i]["hobby name"], 2 ** lvl);
            }
        }
    }
    else
    {
        //let pdata = this.get_person(name);
        for (let i = 0; i < skills.length; i++)
        {
            let skill = skills[i];
            let lvl = this.skill_level(name, skill.name);
            if (lvl > 3 && skill["hobby name"])
                relfreq.push(skill["hobby name"], 2 ** lvl);
        }
    }
    return (random ? setup.ob_randomrelfreq(relfreq) : setup.ob_maxrelfreq(relfreq)) || "pop culture stuff";
}

