setup.people.pc_turnon_factor = function(name, turnonmult = 1, turnoffmult = 2, scale = 2)
{
    if (!V.pcturnons || !V.pcturnoffs) return 0;
    //return this.turnon_factor(name, V.pcturnons, V.pcturnoffs, 1, 2);

    let npc = this.expand(name);

    let actual = 0;
    let maxpositive = 0;
    let maxnegative = 0;

    let lackingmusthave = false;
    let hasdealbreaker = false;

    for (let turnon of V.pcturnons)
    {
        let key = this.turnon_key(turnon);
        let priorityname = this.pc_turnon_priority(turnon);
        let priority = this.turnon_priority_value(priorityname);

        const tinfo = setup.turnons[key];

        let possible = tinfo.precondition ? tinfo.precondition(npc) : true;

        if (possible)
        {
            maxpositive += priority * turnonmult;
            if (npc.has_turnon_characteristic(key))
                actual += priority * turnonmult;
            else if (priorityname == "must-have")
                lackingmusthave = true;
        }
    }

    for (let turnon of V.pcturnoffs)
    {
        let key = this.turnon_key(turnon);
        let priorityname = this.pc_turnon_priority(turnon);
        let priority = this.turnon_priority_value(priorityname);

        const tinfo = setup.turnons[key];

        let possible = tinfo.precondition ? tinfo.precondition(npc) : true;

        if (possible)
        {
            maxnegative += priority * turnoffmult;
            if (npc.has_turnon_characteristic(key))
            {
                actual -= priority * turnoffmult;
                if (priorityname == "must-have")
                    hasdealbreaker = true;
            }
        }
    }

    if (hasdealbreaker)
        return -scale;

    const normalization = 6; // a magic number to ensure people with minimal turnons don't find everybody EXTREMELY HOT
    let magnitude = Math.min(Math.abs(actual) / normalization, 1);

    let scaled = 0;
    if (actual > 0 && maxpositive > 0)
        scaled = (actual / maxpositive) * scale * magnitude;
    else if (actual < 0 && maxnegative > 0)
        scaled = (actual / maxnegative) * scale * magnitude;

    if (lackingmusthave)
        return Math.min(Math.round(scaled), 0);

    return Math.clamp(Math.round(scaled), -scale, scale);
}

