setup.people.base_crush_chance = function()
{
    // factor between 0 and 1 of how likely the PC is to develop a crush right now
    if (V.gameday < 10) return 0;
    else if (V.crush || (V.lastcrush && V.gameday - V.lastcrush < 28) || (V.lastRelEvent && V.gameday - V.lastRelEvent < 1)) return 0;
    else if (!V.pcturnons || !V.pcturnoffs) return 0;
    else
    {
        let chance = setup.ob_events.base_event_chance();
        if (setup.ob_relationships.in_exclusive_relationship())
        {
            if (V.pc.has_inclination("Loyal")) return 0;
            else if (!V.pc.has_inclination("Cheater")) chance /= 4;
        }
        else
        {
            let since = V.lastcrush ? V.gameday - V.lastcrush : V.gameday - 10;

            if (since >= 112)
                chance *= 6;
            else if (since >= 84)
                chance *= 4;
            else if (since >= 56)
                chance *= 2;
            else if (since >= 36)
                chance *= 1.33;
        }
        return chance;
    }
}

setup.people.crush_chance = function(name)
{
    // factor between 0 and 1 of how likely the PC is to crush on this person
    const pdata = this.get_person(name);
    if (setup.ob_relationships.is_ex(name) || setup.ob_relationships.is_ex(name, "crush") || this.is_dating(name) || setup.ob_relationships.relationship_type_with(name) == "romantic") return 0;
    else if (pdata.lastRelEvent && V.gameday - pdata.lastRelEvent < 7) return 0;
    else
    {
        const tof = (V.pcturnons.length == 0 && V.pcturnoffs.length == 0) ? 0.5 : this.pc_turnon_factor(name);
        let chance;
        if (tof < 0)
            return 0;
        else if (tof < 1)
            chance = 0.1;
        else if (tof < 2)
            chance = 0.5;
        else
            chance = 1;

        if (pdata.type == "townie")
            chance /= 2;
        else if (pdata.type == "faculty")
            chance /= 2;
        else if (pdata.type == "outsider")
            return 0;

        if (setup.people.get_attitude(name) < 0)
            chance /= 3;

        if (setup.people.get_age(name) > 29)
            chance /= 4;

        if (V.favoritepeople && V.favoritepeople.includes(name))
            chance *= 3;

        return chance;
    }
}

