    if (pdata.sports && V.pcsports && V.pcsports.includesAny(pdata.sports))
        if (pdata.type == "faculty")
            rels.push("coach");
        else
            rels.push("teammate");

    let greekhouse = setup.ob_houses.house("PC");
    if (greekhouse && setup.ob_houses.house(name) == greekhouse)
    {
        if (setup.ob_houses.get_president(greekhouse) == name)
            rels.push("house president");
        else if (setup.ob_houses.get_rushchair(greekhouse) == name)
            rels.push("house rush chair");
        else if (V.tradgreeks && setup.ob_houses.is_fraternity(greekhouse) && setup.people.is_masc(name))
            rels.push("fraternity brother");
        else if (V.tradgreeks && setup.ob_houses.is_sorority(greekhouse) && setup.people.is_femme(name))
            rels.push("sorority sister");
        else if (V.tradgreeks && setup.ob_houses.is_fraternity(greekhouse))
            rels.push("fraternity kin");
        else if (V.tradgreeks && setup.ob_houses.is_sorority(greekhouse))
            rels.push("sorority kin");
        else
            rels.push("house kin");
    }

    let rel = setup.ob_relationships.relationship_with(name);
    if (rel)
    {
        let label = setup.ob_relationships.label(rel, name);
        rels.push(label);
    }
    else if (Math.abs(setup.people.get_attitude(name, "friendship")) >= 25)
    {
        let desrel = setup.people.desired_relationship(name);
        switch (desrel)
        {
            case "friend":
            case "fuckbuddy":
            {
                if (this.get_attitude(name, "friendship") > 0)
                    rels.push("friendly acquaintance");
                else
                    rels.push("acquaintance");
                break;
            }
            case "rival":
            case "hatefuck":
            {
                if (this.get_attitude(name, "friendship") < 0)
                    rels.push("annoying acquaintance");
                else
                    rels.push("acquaintance");
                break;
            }
            case "date":
            {
                rels.push("admirer");
            }
            default:
            {
                if (this.get_attitude(name, "friendship") >= this.intro_threshold)
                    rels.push("acquaintance");
            }
        }
    }

    if (V.crush == name)
        rels.push("crush");

    for (let ignoreitem of ignore)
        rels.delete(ignoreitem);

    return rels;
}

setup.people.text_msg = function(name, msg)
{
    let dumbdownchance = 0.2;
    const archetype = setup.ob_archetypes[this.archetype(name)];
    let age = (archetype.age[0] + archetype.age[1]) / 2;
    let wealth = (archetype.wealth[0] + archetype.wealth[1]) / 2;
    let intellect = this.skill_level(name, "Intellectual");

    if (age >= 30 || wealth >= 700 || intellect >= 6)
        dumbdownchance = 0.1;
    else if (age < 21 && intellect < 6)
        dumbdownchance = 0.75;
    else if (age < 21 && intellect < 9)
        dumbdownchance = 0.45;

    let rng = new RNG(inthash(this.get_name(name)));
    if (rng.random() < dumbdownchance)
    {
        if (!Array.isArray(msg)) msg = [msg];
        for (let i = 0; i < msg.length; i++)
            msg[i] = msg[i].toLowerCase();
        return msg;
    }
    else
    {
        return msg;
    }
}

