setup.people.recognize_faculty = function(student, faculty)
{
    // does this npc recognize this faculty member?
    // (will return false if this check doesn't even apply, so safe to use freely)
    if (!this.is_student(student) && !this.is_faculty(student)) return false;
    if (!this.is_faculty(faculty)) return false;
    if (this.is_faculty(student)) return true;

    const studentcourses = this.get_person(student).courses || [];
    const studentsports = this.get_person(student).sports || [];
    const facultycourses = this.get_person(faculty).courses || [];
    const facultysports = this.get_person(faculty).sports || [];

    if (studentcourses.includesAny(facultycourses) || studentsports.includesAny(facultysports)) return true;

    let rng = setup.ob_newRNG(this.get_name(student) + "recog");
    return rng.random() <= 0.2;
}

