setup.people.has_personality_trait = function(name, trait)
{
    const traitinfo = this.personality_traits[trait];

    if (traitinfo.noinclinationset && this.has_any_inclination(name, traitinfo.noinclinationset)) return false;
    if (traitinfo.noinclination && this.has_inclination(name, traitinfo.noinclination)) return false;

    return  (traitinfo.inclination && this.has_inclination(name, traitinfo.inclination)) ||
            (traitinfo.inclinationset && this.has_any_inclination(name, traitinfo.inclinationset)) ||
            (traitinfo.skill && this.skill_level(name, traitinfo.skill[0]) >= traitinfo.skill[1]) ||
            (traitinfo.hobby && this.has_hobby(name, traitinfo.hobby));
}

setup.people.get_personality_traits = function(name)
{
    return Object.keys(this.personality_traits).filter(trait => this.has_personality_trait(name, trait));
}


setup.people.filter_known_traits = function(name, traits)
{
    const retval = [];

    for(const trait of traits)
    {
        const traitinfo = this.personality_traits[trait];
        if (traitinfo == undefined) continue;
        var relationship_score = 0;

        if (traitinfo.type == "personality")
        {
            const friendship_score = this.get_attitude(name, "friendship")
            relationship_score = Math.max(friendship_score, -2*friendship_score, this.get_attitude(name, "romance"));
        }
        else if (traitinfo.type == "sex" && this.is_sexpartner(name))
        {
            relationship_score = this.get_attitude(name, "lust");
        }

        if (relationship_score > traitinfo.threshold)
            retval.push(trait);
    }

    return retval;
}

setup.people.known_personality_traits = function(name)
{
    name = this.get_name(name);
    let traits = this.get_personality_traits(name);
    return this.filter_known_traits(name, traits);
}


