setup.people.calculate_reputation = function()
{
    const populations = ["student", "townie", "faculty"];
    let rep = {exhibitionism: {}, promiscuity: {}, studiousness: {}, reservedness: {}, kindness: {}, meanness: {}, popularity: {}};
    for (let pop of populations)
    {
        rep["exhibitionism"][pop] = this.exhibitionism_reputation(pop);
        rep["promiscuity"][pop] = this.promiscuity_reputation(pop);
        rep["studiousness"][pop] = this.studiousness_reputation(pop);
        rep["reservedness"][pop] = this.reservedness_reputation(pop);
        rep["kindness"][pop] = this.kindness_reputation(pop);
        rep["meanness"][pop] = this.meanness_reputation(pop);
        rep["popularity"][pop] = this.popularity_reputation(pop);
    }
    State.setVar("$reputation", rep);
    return rep;
}

setup.people.get_reputation = function(type, population = "student")
{
    const rep = V.reputation;
    if (!rep || !rep[type]) return 0;

    if (population == "all")
    {
        let total = 0;
        for (let subrep of Object.keys(rep[type]))
            total += rep[type][subrep];
        return total / Object.keys(rep[type]).length;
    }
    else
    {
        return rep[type][population] || 0;
    }
}

setup.people.summarize_reputation = function()
{
    let bytype = {};
    const types = {"student":"students", "townie":"townies", "faculty":"faculty"};
    const reps = {"exhibitionism":"exhibitionist", "promiscuity":"promiscuous", "studiousness":"studious", "reservedness":"reserved", "kindness":"kind", "meanness":"mean"};

    for (const [type, label] of Object.entries(types))
    {
        let pop = this.get_reputation("popularity", type);

        let intro;
        if (Math.abs(pop) < 50)
            intro = `You're mostly unknown among the <<highlight>>${label}<</highlight>>.`;
        else if (pop > 800)
            intro = `You're wildly popular among the <<highlight>>${label}<</highlight>>.`;
        else if (pop > 600)
            intro = `You're extremely popular among the <<highlight>>${label}<</highlight>>.`;
        else if (pop > 400)
            intro = `You're very popular among the <<highlight>>${label}<</highlight>>.`;
        else if (pop > 300)
            intro = `You're quite popular among the <<highlight>>${label}<</highlight>>.`;
        else if (pop > 200)
            intro = `You're pretty popular among the <<highlight>>${label}<</highlight>>.`;
        else if (pop > 100)
            intro = `You're somewhat popular among the <<highlight>>${label}<</highlight>>.`;
        else if (pop >= 50)
            intro = `You're mostly unknown but relatively well-regarded among the <<highlight>>${label}<</highlight>>.`;
        else if (pop < -800)
            intro = `You're wildly disliked among the <<highlight>>${label}<</highlight>>.`;
        else if (pop < -600)
            intro = `You're quite disliked among the <<highlight>>${label}<</highlight>>.`;
        else if (pop < -400)
            intro = `You're very disliked among the <<highlight>>${label}<</highlight>>.`;
        else if (pop < -300)
            intro = `You're not well liked among the <<highlight>>${label}<</highlight>>.`;
        else if (pop < -200)
            intro = `You're not particularly well liked among the <<highlight>>${label}<</highlight>>.`;
        else if (pop < -100)
            intro = `You're somewhat unpopular among the <<highlight>>${label}<</highlight>>.`;
        else if (pop <= -50)
            intro = `You're mostly unknown but generally not well-liked among the <<highlight>>${label}<</highlight>>.`;

        const compiledreps = [];
