                compiledreps.push(`very ${replabel}`);
            else if (repvalue > 150)
                compiledreps.push(`pretty ${replabel}`);
            else if (repvalue > 100)
                compiledreps.push(`somewhat ${replabel}`);
            else if (repvalue >= 50)
                compiledreps.push(`occasionally ${replabel}`);
        }

        let repline = "";
        if (compiledreps.length > 0)
        {
            let and = setup.ob_and(compiledreps);
            repline = `They regard you as ${and}.`;
        }

        bytype[type] = intro + " " + repline;
    }

    return bytype;
}

setup.people.get_rumor_strength = function(name, type="promiscuity")
{
    let rumors;
    if (this.cached_rumors && this.cached_rumors[0] == name && Date.now() - this.cached_rumors[1] < 1000)
    {
        rumors = this.cached_rumors[2];
    }
    else
    {
        let pinfo = this.get_person(name);
        if (!("rumors" in pinfo))
        {
            this.cached_rumors = [name, Date.now(), {}];
            return 0;
        }
        else
        {
            rumors = pinfo.rumors;
            this.cached_rumors = [name, Date.now(), rumors];
        }
    }
    return rumors[type] || 0;
}

setup.people.set_rumor_strength = function(name, type, value)
{
    let pinfo = this.get_person(name);
    if (!("rumors" in pinfo))
    {
        pinfo.rumors = {};
    }
    pinfo.rumors[type] = value;

    return value;
}

setup.people.alter_rumor_strength = function(name, type, value)
{
    /* note: things that create memories (sex, flashing) build reputation with no need to call this */
    const opposites = { promiscuity: "reservedness", reservedness: "promiscuity",
                        kindness: "meanness", meanness: "kindness",
                        };
    let pinfo = this.get_person(name);
    if (!("rumors" in pinfo))
    {
        pinfo.rumors = {};
    }
    if (!(type in pinfo.rumors))
    {
        pinfo.rumors[type] = 0;
    }

    if (opposites[type] && pinfo.rumors[opposites[type]] > 0)
    {
        pinfo.rumors[opposites[type]] -= value;
        pinfo.rumors[opposites[type]] = Math.min(Math.max(pinfo.rumors[opposites[type]], 0), 1000);
    }
    else
    {
        pinfo.rumors[type] += value;
        pinfo.rumors[type] = Math.min(Math.max(pinfo.rumors[type], 0), 1000);
    }

    return pinfo.rumors[type];
}

