setup.people.accept_sex_for_money = function(name, amount, diffmod = 0)
{
    // whether the npc is willing to purchase sex for the given amount
    // whether they can afford it is the largest factor
    // but they'll get more or less spendy depending on attraction and inclinations

    if (!this.attracted_enough_to_pc(name)) return false;
    if (amount <= 5) return true;

    let diff;
    if (amount <= 10)
        diff = 2;
    else if (amount <= 25)
        diff = 3;
    else if (amount <= 50)
        diff = 4;
    else if (amount <= 75)
        diff = 5;
    else if (amount <= 100)
        diff = 6;
    else if (amount <= 125)
        diff = 7;
    else if (amount <= 150)
        diff = 8;
    else if (amount <= 200)
        diff = 9;
    else
        diff = 10;

    diff -= this.npc_turnon_factor(name);

    if (this.has_inclination(name, "Whore Connoisseur")) diff -= 1;
    if (this.has_inclination(name, "Paypig")) diff -= 2;
    if (this.has_inclination(name, "Insecure")) diff += 1;
    if (this.has_inclination(name, "Chaste")) diff += 8;
    if (!this.is_masc(name)) diff += 1;

    let wealth = Math.floor(this.get_wealth(name) / 100);

    let rate = setup.pc().skillcheck_rate(wealth, diff + diffmod);

    return State.random() <= rate;
}

setup.people.amount_for_sex = function(name, multiplier = 1, maxamount = 100, minamount = 5, diffmod = 0)
{
    let iterations = 0;
    let amount = maxamount;
    while (amount >= minamount)
    {
        iterations++;
        if (iterations > 100) return 5;
        if (this.accept_sex_for_money(name, amount, diffmod))
            return Math.round(amount * multiplier);
        else
        {
            if (amount == 5)
                amount = 0;
            else if (amount == 10)
                amount = 5;
            else if (amount == 20)
                amount = 10;
            else if (amount == 50)
                amount = 20;
            else if (amount == 70)
                amount = 50;
            else if (amount == 100)
                amount = 70;
            else if (amount <= 200)
                amount = 100;
            else
                amount = Math.floor(amount / 2);
        }
    }
    return 0;
}

