    const weekendenterpref = setup.ob_business.entertainment_choice_frequency(name, true);
    const week = [];
    for (let i = 0; i < 7; i++)
    {
        let dest = rng.randomrelfreq((i == 0 || i == 6) ? weekendenterpref : enterpref);
        week.push(dest);
    }
    V.people[name].nightlife = week;
    return week;
}

