setup.people.selectively_rebake_schedule = function(name, business)
{
    name = this.get_name(name);
    const rng = setup.ob_newRNG(name);
    let nightlife = this.get_person(name).nightlife;
    for (let i = 0; i < nightlife.length; i++)
    {
        if (nightlife[i] == business)
        {
            let currentrating = setup.ob_business.attraction_rating(business, name);
            if (currentrating < 800)
            {
                let freq = setup.ob_business.entertainment_choice_frequency(name, (i == 0 || i == 6));
                let pick = rng.randomrelfreq(freq);
                nightlife[i] = pick;
                //console.log(name + " didn't like River Rat enough -- now " + pick);
            }
        }
        else
        {
            let currentrating = setup.ob_business.attraction_rating(nightlife[i], name);
            let newrating = setup.ob_business.attraction_rating(business, name);
            if (newrating > currentrating)
            {
                let freq = setup.ob_business.entertainment_choice_frequency(name, (i == 0 || i == 6));
                let pick = rng.randomrelfreq(freq);
                nightlife[i] = pick;
                //console.log(name + " likes River Rat better than current pick -- now " + pick);
            }
        }
    }
    return nightlife;
}

