    const days = rng.shuffle([0, 1, 2, 3, 4, 5, 6]);
    let friendreq = (days.indexOf(day) + 1) * 100;
    if (this.get_attitude(name, "friendship") >= friendreq) return true;

    let pdata = this.get_person(name);
    if (!pdata || !pdata.nightlife) return false;
    let known = pdata.nightlife_known || 0;
    return (known & (1 << day)) !== 0;
}

