// to add a new badge: alter .has_badge() below and .all_possible_badges() below that
// each case in .has_badge() must match a tooltip from .all_possible_badges()
setup.people.has_badge = function(name, badge)
{
    name = this.get_name(name);
    let pdata = this.get_person(name);
    switch (badge)
    {
        case "Favorite":
            return V.favoritepeople.includes(name);
        case "Dating":
            return this.is_romantic_partner(name);
        case "Friend":
            return this.is_friend(name);
        case "Hatefuck":
            return setup.ob_relationships.relationship_with(name) == "hatefuck";
        case "Rival":
            return this.is_rival(name);
        case "Fuckbuddy":
            return setup.ob_relationships.relationship_with(name) == "fuckbuddy";
        case "Professor":
            return this.is_professor(name);
        case "Coworker":
