setup.people.harvesteve_costume = function(name)
{
    if (this.get_type(name) != "student") return;
    const pdata = this.get_person(name);
    if (pdata.costume) return pdata.costume;

    const mascheroes = ["Freedom Man", "The Bat Knight", "The Webber", "The Black Fox", "The Green Hunter", "Osamu the Tech", "Stefan the Brute", "Herbie the Cabbie Builder", "Archie the Chimney-Sweep"];
    const femmeheroes = ["The Webber", "The Amazonian", "The Cat Burglar", "The Corvid", "Star Sailor Water", "Star Sailor Thunder", "Star Sailor Flame", "Star Sailor Light", "Umbria the Unscarred"];
    const geeky = ["Medieval Knight", "Retrofuture Astronaut", "Alien", "Renaissance Knight", "Decapod Surgeon", "Paladin", "St. Owens University Host Club", "Vampire Slasher Corp Uniform", "Zenomurphy"];
    const basic = ["Alien", "Zombie", "Werewolf", "Wizard", "Witch", "Lazy Ghost", "Pirate", "Pirate Captain", "Burglar", "Fairy"];
    const sexyfemme = ["The Cat Burglar", "Sexy Nurse", "Sexy Maid", "Sexy Cheerleader", "Mummy", "Imprisoned Princess", "Sexy Fairy", "Barbarian", "Sexy Angel", "Sultry Angel", "Nocturnal Seducer", "Naughty Tempter", "Basement Bunny", "Mermaid"];
    const sexymasc = ["Sexy Cheerleader", "Wizard", "The Webber", "Mummy", "High Fae", "Sexy Fairy", "Barbarian", "Basement Bunny", "The Mad Dog", "The Dragon Brawler"];

    let rng = setup.ob_newRNG(name);
    if (this.has_inclination(name, "Oral Fixation") && rng.random() < 0.15)
        return "Lazy Ghost";
    else if (this.has_any_inclination(name, "basic_exhibitionist") && rng.random() < 0.8)
        if (setup.people.is_femme(name))
            return rng.randomchoice(sexyfemme);
        else if (setup.people.is_masc(name))
            return rng.randomchoice(sexymasc);
        else
            return rng.randomchoice([...sexymasc, ...sexyfemme]);
    else if (this.has_hobby(name, "nerd stuff") && rng.random() < 0.5)
        return rng.randomchoice(geeky);
    else if ((this.has_hobby(name, "nerd stuff") && rng.random() < 0.7) || rng.random() < 0.4)
        if (setup.people.is_femme(name))
            return rng.randomchoice(femmeheroes);
        else if (setup.people.is_masc(name))
            return rng.randomchoice(mascheroes);
        else
            return rng.randomchoice([...mascheroes, ...femmeheroes]);
    else
        return rng.randomchoice(basic);
}

setup.people.costume = function(name)
{
    if ((V.lastloctags && V.lastloctags.includes("nocostume")) || tags().includes("nocostume"))
        return;

    let costumeoverride = V.lastloctags && (V.lastloctags.includes("costume") || tags().includes("costume"));

    name = this.get_name(name);

    const pdata = this.get_person(name);
    if (!pdata) return null;

    if (costumeoverride)
        return this.harvesteve_costume(name);

    let rng = setup.ob_newRNG(name);

    let daysuntil = setup.ob_days_until_harvesteve();

    if (daysuntil == -1 && V.hour <= 4 && setup.ob_time.month() == "Gourdtober")
        return this.harvesteve_costume(name);

    if (daysuntil < 0) return;

    else if (
         daysuntil <= 1 ||
        (daysuntil <= 2 && rng.random() <= 0.9)  ||
        (daysuntil <= 3 && rng.random() <= 0.75) ||
        (daysuntil <= 4 && rng.random() <= 0.6)  ||
        (daysuntil <= 5 && rng.random() <= 0.3)  ||
        (daysuntil <= 6 && rng.random() <= 0.2)  ||
        (daysuntil <= 7 && rng.random() <= 0.1)
    )
    {
        if (setup.ob_is_harvesteve() && (V.hour < 4 || V.hour >= 18))
            return this.harvesteve_costume(name);
    }
}

