setup.people.npc_popularity = function(name)
{
    // get a rough popularity value (-1000 to 1000) for an NPC

    const factors = [];

    let wealth = this.get_wealth(name);
    if (wealth < 100)
        factors.push(-200);
    else if (wealth >= 900)
        factors.push(1000);
    else if (wealth >= 700)
        factors.push(800);
    else if (wealth >= 500)
        factors.push(400);
    else if (wealth >= 300)
        factors.push(100);

    let cha = this.skill_level(name, "Charisma");
    if (cha >= 10)
        factors.push(600);
    else if (cha >= 9)
        factors.push(550);
    else if (cha >= 8)
        factors.push(500);
    else if (cha >= 7)
        factors.push(400);
    else if (cha >= 6)
        factors.push(300);
    else if (cha >= 5)
        factors.push(200);
    else if (cha >= 4)
        factors.push(100);
    else if (cha >= 3)
        factors.push(0);
    else if (cha >= 2)
        factors.push(-100);
    else if (cha >= 1)
        factors.push(-200);
    else
        factors.push(-400);

    if (this.has_inclination(name, "Bully"))
        factors.push(0);

    if (this.has_inclination(name, "Loner"))
        factors.push(-600);

    if (this.has_inclination(name, "Insecure"))
        factors.push(-400);

    if (this.has_any_inclination(name, ["Slob", "Natural Odor"]))
        factors.push(-500);

    if (this.has_any_inclination(name, ["Target"]))
        factors.push(-400);

    if (this.has_inclination(name, "Kind"))
        factors.push(400);

    if (this.has_inclination(name, "Confident"))
        factors.push(500);

    if (this.has_any_inclination(name, ["Slut", "Whore", "Chaste"]))
        factors.push(200);

    let sum = factors.reduce((a, b) => a + b, 0);
    let avg = sum / factors.length;

    return Math.floor(avg);
}

