setup.people.command_difficulty = function(name)
{
    // the difficulty of getting this person to do what you want, checked against Dominance

    if (setup.ob_relationships.relationship_with(name) == "submissive")
        return -10;
    else if (setup.ob_relationships.relationship_with(name) == "dominant")
        return 20;
    else
    {
        let diff;
        if (this.has_any_inclination(name, "submissive"))
            if (V.pc.has_inclination("Dominant Vibe"))
                diff = 3;
            else
                diff = 6;
        else if (this.has_any_inclination(name, "dominant"))
            if (V.pc.has_inclination("Dominant Vibe"))
                diff = 8;
            else
                diff = 12;
        else if (V.pc.has_inclination("Dominant Vibe"))
            diff = 6;
        else
            diff = 8;

        if (this.has_any_inclination(name, ["Submissive Vibe", "Accommodating", "Humiliation Kink", "Whore", "Slut", "Pleaser", "Insecure", "Target"]))
            diff -= 2;

        if (this.has_any_inclination(name, ["Particular"]))
            diff += 2;

        if (this.has_any_inclination(name, ["Bully", "Chaste", "Breaker"]))
            diff += 5;

        if (setup.ob_relationships.in_exclusive_relationship_not_with("PC", name))
            if (this.has_inclination(name, "Loyal"))
                diff += 10;
            else if (!this.has_inclination(name, "Cheater"))
                if (setup.ob_nPCSimulation.has_flag(name, 181))
                    diff += 2;
                else if (setup.ob_nPCSimulation.has_flag(name, 180))
                    diff += 4;
                else
                    diff += 5;

        if (setup.ob_relationships.partner(name) == "PC")
            diff -= 2;

        if (!this.likes_pc(name))
            diff += 4;

        if (this.is_sexpartner(name))
            diff -= 2;

        if (this.get_attitude(name, "friendship") >= 800 || this.get_attitude(name, "lust") >= 800 || this.get_attitude(name, "romance") >= 800 || this.get_attitude(name, "control") >= 400)
            diff -= 4;
        else if (this.get_attitude(name, "friendship") >= 500 || this.get_attitude(name, "lust") >= 500 || this.get_attitude(name, "romance") >= 500 || this.get_attitude(name, "control") >= 200)
            diff -= 3;
        else if (this.get_attitude(name, "friendship") >= 300 || this.get_attitude(name, "lust") >= 300 || this.get_attitude(name, "romance") >= 300 || this.get_attitude(name, "control") >= 100)
            diff -= 2;
        else if (this.get_attitude(name, "friendship") >= 150 || this.get_attitude(name, "lust") >= 150 || this.get_attitude(name, "romance") >= 150)
            diff -= 1;

        if (this.get_attitude(name, "control") >= 800)
            diff += 10;
        else if (this.get_attitude(name, "control") >= 600)
            diff += 8;
        else if (this.get_attitude(name, "control") >= 400)
            diff += 6;
        else if (this.get_attitude(name, "control") >= 200)
            diff += 4;
        else if (this.get_attitude(name, "control") > 0)
            diff += 2;

        return diff;
    }
}

