    return assoc;
}

setup.people.expand = function(npc)
{
    // why did it take me so long to make this function
    if (V.pc && V.pc.equals(npc))
        return V.pc;
    else if (typeof npc == "string")
    {
        setup.ob_expandedNPCCache = setup.ob_expandedNPCCache ?? new Map();
        if (!V.npcclothingmemory?.[npc])
        {
            let cached = setup.ob_expandedNPCCache.get(npc);
            if (cached) return cached;
        }
        let newp = new Person({person: this.get_name(npc)});
        setup.ob_expandedNPCCache.set(npc, newp);
        return newp;
    }
    else
        return npc;
}

setup.people.remove_from_expand_cache = function(npc)
{
    if (V.pc && V.pc.equals(npc))
