setup.people.graduate = function(npc)
{
    // do stuff to make a student not a student anymore
    // subsequently they will be either converted to a townie or removed from the game entirely

    // note: year will be advanced by 1 after this runs, which is important when we need to find students to fill vacating positions

    let pdata = this.get_person(npc);
    let name = this.get_name(npc);

    let rm = pdata.roommate;

    let sport = pdata.sports && pdata.sports.length > 0 ? pdata.sports[0] : undefined;

    // delete stuff only relevant to students
    delete pdata.residence;
    delete pdata.major;
    delete pdata.courses;
    delete pdata.sports;
    delete pdata.year;
    delete pdata.cohort;
    delete pdata.schedule;
    delete pdata.roommate;
    delete pdata.house;

    if (rm)
    {
        // delete roommate data on their roommate
        let rmpdata = this.get_person(rm);
        if (rmpdata) delete rmpdata.roommate;
    }

    const collegeadvisors = [
        "The Serious Student Advisor",
        "The Jaded Student Advisor",
        "The Chipper Student Advisor",
    ];
    const collegeniches = [
        ...collegeadvisors,
        "The Resident Advisor",
        "The Star Quarterback",
        "The Well-Meaning Athlete",
        "The E-girl",
        "The 360 No-scoper",
        "The Cheer Captain",
        "The Ambitious Athlete",
        "The Quietly Determined Athlete",
    ];

    let niche = this.find_niche(npc);
    if (collegeniches.includes(niche))
    {
        delete V.niches[niche];
        delete pdata.special;
        delete pdata.allowfree;
    }

    const students = setup.people.people_of_type("student");

    if (this.is_student_advisor(npc))
    {
        V.studentadvisors.delete(npc);
        let advisor =   setup.ob_events.pick_person({year: 2, goodstudent: true, notanyniche: true, studentadvisor: false}, students) ||
                        setup.ob_events.pick_person({year: 3, goodstudent: true, notanyniche: true, studentadvisor: false}, students) ||
                        setup.ob_events.pick_person({year: 2, notanyniche: true, studentadvisor: false}, students) ||
                        setup.ob_events.pick_person({year: 3, notanyniche: true, studentadvisor: false}, students);
        if (advisor) V.studentadvisors.push(advisor);
    }

    if (sport)
    {
        if (V.sportsteams[sport].captain == name)
            delete V.sportsteams[sport].captain; // we'll pick a new captain when we reform teams after everybody has advanced a year
        V.sportsteams[sport].team.delete(name);
    }

    for (let [reshall, reshallinfo] of Object.entries(V.residences))
        if (reshallinfo.RA == name)
        {
            let advisor =   setup.ob_events.pick_person({year: 2, goodstudent: true, notanyniche: true, residentadvisor: false, resident: reshall}, students) ||
                            setup.ob_events.pick_person({year: 3, goodstudent: true, notanyniche: true, residentadvisor: false, resident: reshall}, students) ||
                            setup.ob_events.pick_person({year: 2, notanyniche: true, residentadvisor: false, resident: reshall}, students) ||
                            setup.ob_events.pick_person({year: 3, notanyniche: true, residentadvisor: false, resident: reshall}, students);
            if (advisor) reshallinfo.RA = advisor;
        }

    for (let [house, houseinfo] of Object.entries(V.houses))
        if (houseinfo.members.includes(npc))
        {
            houseinfo.members.delete(npc);
            if (houseinfo.president == npc)
                houseinfo.president = undefined;
            if (houseinfo.rushchair == npc)
                houseinfo.rushchair = undefined;
        }
}

