setup.people.graduate_students = function()
{
    // remove or convert graduating seniors
    let keeping = [];
    let possiblyremove = [];
    let count = 0;
    for (const [p, pinfo] of Object.entries(V.people))
    {
        try
        {
            if (pinfo.type == "student" && !this.is_removed(p) && pinfo.year == 4)
            {
                console.log(`YearAdvancement: ${p} is graduating!`);
                count++;
                this.graduate(p);
                if (setup.people.is_personally_relevant(p))
                {
                    console.log(`YearAdvancement: converting ${p} to townie`);
                    this.convert_to_townie(p);
                    keeping.push(p);
                }
                else
                {
                    possiblyremove.push(p);
                }
            }
        }
        catch (error)
        {
            console.error(`YearAdvancement: failed on ${p}: ${error}`);
        }
    }

    let keptpercent = keeping.length / count;
    if (keptpercent < 0.25)
    {
        let diff = Math.round(count * 0.25) - keeping.length;
        possiblyremove.shuffle();
        for (let i = 0; i < diff; i++)
        {
            let p = possiblyremove[0];
            console.log(`YearAdvancement: converting ${p} to townie`);
            this.convert_to_townie(p);
            keeping.push(p);
            possiblyremove.delete(p);
        }
    }

    for (let p of possiblyremove)
    {
        try
        {
            console.log(`YearAdvancement: removing ${p}`);
            this.remove_from_game(p);
        }
        catch (error)
        {
            console.error(`YearAdvancement: failed on ${p}: ${error}`);
        }
    }
}

