setup.people.add_incoming_freshmen = function()
{
    // generate and set up new incoming freshmen

    console.log("YearAdvancement: generating incoming freshmen");

    let count = Object.keys(V.people).length;

    let rng = setup.ob_newRNG(V.seed + V.gameyear + "freshmen");

    const majors = Object.keys(setup.School.majors);

    let gender = V.studentgenderdistribution;

    const homeless = [];

    const info = setup.School.noncohort["freshman"];

    let n = 0;

    const archetypes = info.distribution;

    const multiplier = setup.ob_npc_generation_multiplier();

    let db = setup.people_db();

    let majori = 0;

    for (let [archetype, count] of Object.entries(info.static))
    {
        count = Math.round(count * multiplier);
        for (let i = 0; i < count; i++)
        {
            let major = majors[majori];
            majori++;
            if (majori >= majors.length) majori = 0;

            let student = setup.people.add_random(  rng.randomrelfreq(gender),
                                                    archetype,
                                                    "student", rng);
            db[student].major = major;
            db[student].year = info.year;
            db[student].cohort = false;
            homeless.push(student);
            n++;
        }
    }

    let random = Math.round((info.count - n) * multiplier);
    for (let i = 0; i < random; i++)
    {
        let major = rng.randomchoice(majors);
        let thisarchetype = rng.randomrelfreq(archetypes);

        let student = setup.people.add_random(  rng.randomrelfreq(gender),
                                                thisarchetype,
                                                "student", rng);
        db[student].major = major;
        db[student].year = info.year;
        db[student].cohort = false;
        homeless.push(student);
        n++;
    }

    console.log(`YearAdvancement: generated ${Object.keys(V.people).length - count} freshmen`);

    console.log("YearAdvancement: placing freshman students in residences");

    const residences = Object.keys(setup.School.residences);
    residences.push("off-campus");

    while (homeless.length > 0)
    {
        let rando = homeless[0];
        if (homeless.length == 1)
        {
            db[rando].residence = "off-campus";
        }
        else
        {
            let residence = rng.randomchoice(residences);
            setup.place_into_residence(rando, residence);

            let randoroommate = setup.find_roommate_for(rando, homeless, rng);
            if (randoroommate != null)
            {
                setup.place_into_residence(randoroommate, residence);
                setup.set_roommates(rando, randoroommate);
                db[randoroommate].schedule = rng.randomchoice([1, 2, 3, 4]);

                homeless.delete(randoroommate);
            }
        }
        homeless.delete(rando);
        db[rando].schedule = rng.randomchoice([1, 2, 3, 4]);
    }

    console.log("YearAdvancement: enrolling freshman students in year 1 courses");
    setup.people.enroll_new_freshmen();
}

setup.people.enroll_new_freshmen = function()
{
    // find courses for freshmen lacking courses

    const freshmen = Object.keys(V.people).filter(p => this.get_type(p) == "student" && this.get_year(p) == 1 && (!this.get_person(p).courses || this.get_person(p).courses.length == 0));
    for (let p of freshmen)
    {
        const major = V.people[p].major;

        if (!major)
        {
            console.warn(`${p} does not have a major`);
            continue;
        }

        for (let block of ["Block A", "Block B", "Block C", "Block D"])
        {
            let course = setup.School.course_for_year(major, 1, block);
            setup.enroll_student(p, course);
        }
    }
}

setup.people.refill_sports_teams = function()
{
    // refill sports teams with freshmen

    console.log("YearAdvancement: topping up sports teams with incoming freshmen");

    const sports = ["football", "cheerleading", "swimming", "esports"];
    let db = setup.people_db();
    let sportsteams = V.sportsteams;

    for (let sport of sports)
    {
        let count = setup.School.sports[sport]["team size"];
        const team = sportsteams[sport].team;

        let seekpartners = !setup.pc_cis_straight();

        let years = [1];

        console.log(`YearAdvancement: ${sport} is short ${count - team.length} members`);

        while (team.length < count)
        {
            let p;

            switch (sport)
            {
                case "football":
                {
                    if (!V.tradsports)
                        p = (seekpartners && State.random() < 0.33) ? setup.pick_potential_partner_jock(years) : setup.pick_proportional_jock(years);
                    else
                        p = (seekpartners && State.random() < 0.33) ? setup.pick_potential_partner_male_jock(years) : setup.pick_male_jock(years);
                    break;
                }
                case "cheerleading":
                {
                    if (!V.tradsports)
                        p = (seekpartners && State.random() < 0.5) ? setup.pick_potential_partner_cheerleader(years) : setup.pick_proportional_cheerleader(years);
                    else
                        p = (seekpartners && State.random() < 0.5) ? setup.pick_potential_partner_cheerleader(years) : setup.pick_cheerleader(years);
                    break;
                }
                case "swimming":
                {
                    p = State.random() < 0.4 ? setup.pick_male_jock(years) : setup.pick_any_jock(years);
                    break;
                }
                case "esports":
                {
                    if ((V.tradsports && State.random() < 0.95) || (!V.tradsports && State.random() < 0.5))
                        p = setup.pick_male_gamer(years);
                    else
                        p = setup.pick_female_gamer(years);
                    break;
                }
            }

            if (p)
            {
                db[p].sports = [sport];
                team.push(p);
                console.log(`YearAdvancement: putting ${p} on ${sport} team`);
            }
            else if (years.length < 4)
            {
                years.push(years.length + 1);
            }
            else
            {
                console.warn(`YearAdvancement: couldn't find a person to fill in the ${sport} team`);
                count = -1;
            }
        }

        if (!sportsteams[sport].captain)
        {
            let skill = sport == "esports" ? "Video Gaming" : "Physical";

            let cap = setup.ob_events.pick_person({skills: [skill], year: [3, 4]}, sportsteams[sport].team);
            sportsteams[sport].captain = cap;
            console.log(`YearAdvancement: selected ${cap} as new ${sport} team captain`);
        }
    }
}

