setup.people.mood_factor = function(npc, mood = "general", bias = 0, applydrama = true, dramaeffect = 1, day = V.gameday)
{
    // use simplex noise to give NPCs drifting moods
    // (this is a useful enough trick that we want a generic implementation so we can use it for lots of stuff)
    // mood: any unique string, use whatever you need
    // bias: a number (some kind of positive bias is often a good idea) or a function to resolve here
    // day: the mood on this specific day... always deterministic
    // returns number between -1 and 1

    // find numeric ID for NPC
    let id = setup.people.get_id(npc);

    // assemble unique seed for this NPC+mood, init rng and simplex noise
    let seed = inthash(`${mood}_${id}_${V.seed}`);
    let rng = setup.ob_newRNG(seed);
    let simplex = new SimplexNoise(() => rng.random());

    // find long term, medium term, and short term noise
    let basenoise = simplex.noise2D(day / 45, 0);
    let mediumnoise = simplex.noise2D(day / 12, 100);
    let smallnoise = simplex.noise2D(day / 4, 200);

    // compile three noise tracks into one value
    let rawmood = (basenoise * 0.5) + (mediumnoise * 0.3) + (smallnoise * 0.2);

    // determine bias if it's not a number
    if (typeof bias == "function")
        bias = bias(npc, mood);

    // an amplitude/volatility value — a higher number means any thresholds in the simulation will be crossed more often
    // we'll use the player-facing drama slider option, but since that's tuned for relationship health, we'll normalize it
    let dramascale = applydrama ? (V.optdrama ?? 0.4) * dramaeffect : 0;
    let noisescale = Math.max(0, 1 - Math.abs(bias));

    // put it all together and return
    let retval = Math.clamp((rawmood * dramascale * noisescale) + bias, -1, 1);
    return retval;
}

setup.people.cheerfulness = function(npc)
{
    // bias toward happiness

    let retval = 0;

    if (this.has_inclination(npc, "Kind"))
        retval += 0.1;
    if (this.has_inclination(npc, "Confident"))
        retval += 0.1;
    if (this.has_inclination(npc, "Masochist"))
        retval -= 0.1;
    if (this.has_inclination(npc, "Insecure"))
        retval -= 0.2;
    if (this.has_inclination(npc, "Bully"))
        retval -= 0.1;

    return retval;
}

setup.people.compliance = function(npc)
{
    // bias against brattiness

    let retval = 0;

    if (this.has_inclination(npc, "Pleaser"))
        retval += 0.3;
    if (this.has_inclination(npc, "Dominant"))
        retval -= 0.1;
    if (this.has_inclination(npc, "Submissive"))
        retval += 0.2;
    if (this.has_inclination(npc, "Brat"))
        retval -= 0.5;

    return retval;
}

setup.people.libido_factor = function(npc)
{
    // bias toward horniness

    let retval = 0;

    if (this.has_any_inclination(npc, "casualsex"))
        retval += 0.3;
    if (this.has_inclination(npc, "Asexual"))
        retval += 0.2;
    if (this.has_inclination(npc, "Chaste"))
        retval -= 0.1;
    if (this.has_inclination(npc, "Demisexual"))
        retval -= 0.05;
    if (this.has_any_inclination(npc, "basic_exhibitionist") || this.has_any_inclination(npc, "basic_voyeur"))
        retval += 0.1;

    let age = this.get_age(npc);
    if (age < 25)
        retval += 0.15;
    else if (age < 30)
        retval += 0.1;
    else if (age >= 60)
        retval -= 0.2;
    else if (age >= 50)
        retval -= 0.1;

    if (setup.participating_in_nnn(npc))
        retval += 0.1;

    return retval;
}

setup.people.irritation = function(npc)
{
    // bias toward being annoyed

    let retval = 0;

    if (this.has_inclination(npc, "Kind"))
        retval -= 0.4;
    if (this.has_inclination(npc, "Bully"))
        retval += 0.4;
    if (this.has_inclination(npc, "Pleaser"))
        retval -= 0.3;
    if (this.has_inclination(npc, "Particular"))
        retval += 0.2;
    if (this.has_any_inclination(npc, ["Sadist", "Breaker", "Taker"]))
        retval += 0.1;
    if (this.has_inclination(npc, "Shy"))
        retval -= 0.1;
    if (this.has_any_inclination(npc, "just_submissive"))
        retval -= 0.1;

    return retval;
}

setup.people.happiness = function(npc)
{
    return this.mood_factor(npc, "happy", this.cheerfulness(npc));
}

setup.people.brattiness = function(npc)
{
    return this.mood_factor(npc, "brat", -this.compliance(npc));
}

setup.people.horniness = function(npc)
{
    return this.mood_factor(npc, "horny", this.libido_factor(npc));
}

setup.people.annoyance = function(npc)
{
    return this.mood_factor(npc, "annoyed", this.irritation(npc));
}

