setup.people.moods_db = {
    // list most impactful / higher priority moods last — they get overwritten by category as the algo iterates

    // happiness
    "content":
    {
        category: "happiness", // category, used internally so we don't have mutually exclusive moods
        description: "[description — unwritten #2004]", // readable description for tooltip
        condition: (npc, conditions) => (conditions.happiness >= 0.1 && conditions.happiness < 0.4) || setup.people.days_since_cheered_up(npc) <= 2,  // condition for npc generally having this mood
        pccondition: (npc, conditions) => (conditions.happiness >= 0.1 && conditions.happiness < 0.4 && conditions.attitudes.trust >= 0) || setup.people.days_since_cheered_up(npc) <= 2, // condition for npc having this mood in reactions to pc (in addition to the general condition)
        overriddenByAny: true, // mood is overridden (removed) if any other mood is present
        overriddenBy: [], // mood is overridden (deleted) if one of the given moods is present
        display: true, // whether to surface for the player
    },
    "happy":
    {
        category: "happiness",
        description: "[description — unwritten #2005]",
        condition: (npc, conditions) => conditions.happiness >= 0.4,
        pccondition: (npc, conditions) => conditions.happiness >= 0.4 && conditions.attitudes.trust >= 0,
        overriddenBy: ["mildly irritated", "angry"],
        display: true,
    },
    "sad":
    {
        category: "happiness",
        description: "[description — unwritten #2006]",
        condition: (npc, conditions) => conditions.happiness <= -0.1 || setup.ob_relationships.sad_about_recent_breakup(npc) && setup.people.days_since_cheered_up(npc) > 2,
        pccondition: (npc, conditions) => conditions.attitudes.trust <= -200 && setup.people.days_since_cheered_up(npc) > 2,
        overriddenBy: ["mildly irritated", "angry"],
        display: true,
    },

    // anger
    "mildly irritated":
    {
        category: "anger",
        description: "[description — unwritten #2007]",
        condition: (npc, conditions) => conditions.annoyance >= 0.2 && conditions.happiness < 0.1 && setup.people.days_since_cheered_up(npc) > 2,
        pccondition: (npc, conditions) => conditions.attitudes.anger >= 200 && conditions.attitudes.anger < 400 && setup.people.days_since_cheered_up(npc) > 2,
        display: true,
    },
    "angry":
    {
        category: "anger",
        description: "[description — unwritten #2008]",
        condition: (npc, conditions) => conditions.annoyance >= 0.4 && conditions.happiness < 0.1 && setup.people.days_since_cheered_up(npc) > 2,
        pccondition: (npc, conditions) => conditions.attitudes.anger >= 400 && setup.people.days_since_cheered_up(npc) > 2,
        display: true,
    },

    // horniness
    "horny":
    {
        category: "horniness",
        description: "[description — unwritten #2009]",
        condition: (npc, conditions) => conditions.horniness >= 0.3 && conditions.horniness < 0.65,
        display: true,
    },
    "extremely horny":
    {
        category: "horniness",
        description: "[description — unwritten #2010]",
        condition: (npc, conditions) => conditions.horniness >= 0.65,
        display: true,
    },

    // subbiness
    "bratty":
    {
        category: "subbiness",
        description: "[description — unwritten #2011]",
        pccondition: (npc, conditions) => setup.people.is_sub(npc) && setup.people.is_bratty_today(npc) && setup.ob_relationships.relationship_with(npc) == "submissive",
        display: true,
    },
    "compliant":
    {
        category: "subbiness",
        description: "[description — unwritten #2012]",
        pccondition: (npc, conditions) => setup.people.is_sub(npc) && !setup.people.is_bratty_today(npc) && setup.ob_relationships.relationship_with(npc) == "submissive",
        display: true,
    },

    // relationship-related moods
    "neglected":
    {
        category: "relationship",
        description: "[description — unwritten #2013]",
        pccondition: (npc, conditions) => {
            if (setup.people.days_since_cheered_up(npc) <= 7)
                return false;
            else if (setup.ob_relationships.relationship_with(npc) == "fuckbuddy")
                return Math.min(conditions.dayssince.sex, conditions.dayssince.relationshipChange) > 14;
            else if (setup.ob_relationships.relationship_type_with(npc) == "romantic")
                return Math.min(conditions.dayssince.date, conditions.dayssince.relationshipChange) > 14 || conditions.dayssince.interaction > 7;
            else if (setup.ob_relationships.relationship_type_with(npc) == "friendship")
                return Math.min(conditions.dayssince.any, conditions.dayssince.relationshipChange) > 28 || conditions.dayssince.interaction > 14;
            else if (setup.people.is_friendly(npc))
                return conditions.dayssince.interaction > 28;
        },
        display: true,
    }
}

