        attitudes: {
            friendship: setup.people.get_attitude(npc, "friendship"),
            lust: setup.people.get_attitude(npc, "lust"),
            romance: setup.people.get_attitude(npc, "romance"),
            anger: setup.people.get_attitude(npc, "anger"),
            suspicion: setup.people.get_attitude(npc, "suspicion"),
            favor: setup.people.get_attitude(npc, "favor"),
            trust: setup.people.get_attitude(npc, "trust"),
        },

        dayssince: {
            // note that none of these return reliable tests of whether this has -ever- taken place
            // so gate behind another condition
            hangout: setup.people.days_since_last_hangout(npc, "hangout"),
            date: setup.people.days_since_last_hangout(npc, "date"),
            any: setup.people.days_since_last_hangout(npc),
