}

setup.people.resolve_moods = function(npc, conditions, type)
{
    // base method for resolving mood categories
    // return array of matching moods

    const moodsbycategory = {};

    for (const [mood, moodinfo] of Object.entries(setup.people.moods_db))
        if (moodinfo[type] && moodinfo[type](npc, conditions))
            moodsbycategory[moodinfo.category] = mood;

    return moodsbycategory;
}

setup.people.resolve_mood_overrides = function(moods)
{
    return moods.filter(mood => {
        const moodinfo = this.moods_db[mood];
        const othermoods = moods.filter(omood => omood != mood);

        if (moodinfo.overriddenByAny && othermoods.length > 0)
            return false;
        if (moodinfo.overriddenBy && moodinfo.overriddenBy.includesAny(othermoods))
            return false;

        return true;
    });
}

setup.people.moods = function(npc, displayonly = false)
{
    // return an array of moods this npc is experiencing generally

    const conditions = this.get_mood_conditions(npc);
    let moods = this.resolve_mood_overrides(Object.values(this.resolve_moods(npc, conditions, "condition")));

    if (displayonly)
        moods = moods.filter(mood => this.moods_db[mood].display);

    return moods;
}

setup.people.moods_for_pc = function(npc, displayonly = false)
{
    // return an array of moods this npc is experiencing as affected by the pc

    const conditions = this.get_mood_conditions(npc);
    const generalmoods = this.resolve_moods(npc, conditions, "condition");
    const pcmoods = this.resolve_moods(npc, conditions, "pccondition");

    // spread/combine with pcmoods second so they override generalmoods
    let moods = this.resolve_mood_overrides(Object.values({...generalmoods, ...pcmoods}));

    if (displayonly)
        moods = moods.filter(mood => this.moods_db[mood].display);

    return moods;
}

setup.people.has_mood = function(npc, mood)
{
    return this.moods(npc).includes(mood);
}

setup.people.has_mood_for_pc = function(npc, mood)
