setup.people.angry_at_pc = function(npc)
{
    const basemoods = this.moods(npc);
    const pcmoods = this.moods_for_pc(npc);

    return pcmoods.includesAny(["mildly irritated", "angry"]) && !basemoods.includesAny(["mildly irritated", "angry"]);
}

setup.people.sad_because_of_pc = function(npc)
{
    const basemoods = this.moods(npc);
    const pcmoods = this.moods_for_pc(npc);

    return pcmoods.includesAny(["sad"]) && !basemoods.includesAny(["sad"]);
}

