setup.people.desynced_from_cohort = function()
{
    // detect a situation where year advancement failed to move player's cohort students ahead (year advancement partially failed)

    if (V.gameyear == 1) return false;

    return Object.values(V.people).some(p => p.type == "student" && p.cohort && p.year < V.gameyear);
}

setup.people.repair_cohort_desync = function()
{
    // repair the situation when we've ended up desynced from our cohort (year advancement partially failed)

    for (const [p, pdata] of Object.entries(V.people))
    {
        if (pdata.type != "student" || !pdata.cohort) continue;

        while (pdata.year < V.gameyear)
            this.advance_student_year(p);

        if ((!pdata.courses || pdata.courses.length == 0) && pdata.major)
        {
            pdata.courses = [];
            for (let block of ["Block A", "Block B", "Block C", "Block D"])
            {
                let course = setup.School.find_course(pdata.major, block, pdata.year);
                if (course) pdata.courses.push(course);
            }
        }
    }
}

