setup.people.last_hangout = function(npc, type = "any")
{
    // return the day of last hangout
    // (does not reliably test whether the pc has ever hung out with this npc — gate this after a check)
    // this is mostly the step before getting days since a last hangout, and the minimum value is day 1, giving a buffer from game start before it's been too long

    npc = this.get_name(npc);
    if (!V.hangoutmemory?.[npc]) // not present, default to first day
        return 1;

    if (!V.hangoutmemory[npc].last) // no 'last' recorded but we've done hangouts? legacy, give a break by returning today
        return V.gameday;

    if (type == "any") // get the latest hangout of any type
    {
        return Math.max(...Object.values(V.hangoutmemory[npc].last));
    }
    else // get the latest hangout of specific type
    {
        return V.hangoutmemory[npc].last[type] ?? 1;
    }
}

setup.people.register_hangout = function(npc, type = "hangout", activity = null)
{
    npc = this.get_name(npc);

    if (!V.hangoutmemory)
        V.hangoutmemory = {};

    if (!V.hangoutmemory[npc])
        V.hangoutmemory[npc] = {};

    if (!V.hangoutmemory[npc][type])
        V.hangoutmemory[npc][type] = 1;
    else
        V.hangoutmemory[npc][type]++;

    if (activity)
    {
        if (!V.hangoutmemory[npc].activities)
            V.hangoutmemory[npc].activities = {};

        if (!V.hangoutmemory[npc].activities[type])
            V.hangoutmemory[npc].activities[type] = {};

        if (!V.hangoutmemory[npc].activities[type][activity])
            V.hangoutmemory[npc].activities[type][activity] = 1;
        else
            V.hangoutmemory[npc].activities[type][activity]++;
    }

    if (!V.hangoutmemory[npc].last)
        V.hangoutmemory[npc].last = {};

    V.hangoutmemory[npc].last[type] = V.gameday;
}

setup.people.days_since_last_hangout = function(npc, type = "any")
{
    // return days since last hangout

    return V.gameday - this.last_hangout(npc, type);
}

