setup.people.ready_to_move_in = function(name)
{
    if (!["student", "townie"].includes(setup.people.get_type(name))) return false;
    const reltype = setup.ob_relationships.relationship_type_with(name);
    if (reltype == "romantic")
        return this.get_attitude(name, "romance") >= 800 && (!V.optdatesim || setup.ob_relationships.milestone_count(name) > 4) && this.get_attitude(name, "trust") >= 0 && this.get_attitude(name, "suspicion") <= 0 && this.get_attitude(name, "anger") <= 0 && (setup.ob_relationships.relationship_age(name) >= 28*2 || setup.ob_relationships.relationship_with(name) == "soulmate");
    else if (reltype == "friendship")
        return this.get_attitude(name, "friendship") >= 800 && this.get_attitude(name, "trust") >= 0 && this.get_attitude(name, "suspicion") <= 0 && this.get_attitude(name, "anger") <= 0 && (setup.ob_relationships.relationship_age(name) >= 28*2 || setup.ob_relationships.relationship_with(name) == "best friend");
    else
        return false;
}

