setup.people.cheer_up_difficulty = function(npc, alterdiff = 0)
{
    if (!this.likes_pc(npc)) // itself a semi-random roll, but it checks important stuff
        return false;

    let diff = 3 + alterdiff;

    if (this.angry_at_pc(npc))
        diff += 8;

    if (this.sad_because_of_pc(npc))
        diff += 6;

    let desrel = this.desired_relationship(npc);
    if (desrel == "date")
        diff -= 2;
    else if (desrel == "indifferent")
        diff += 2;
    // we want friends to be neutral here
    else if (desrel == "rival" || desrel == "hatefuck")
        diff += 6;

    return diff;
}

