setup.ob_people_at_location = function(loc = V.location, locblock = V.locationblock, hkey = V.housing?.key, roomid = V.housing?.roomID)
{
	//setup.ob_build_cache();

	let people_here_list = [];
	const db = this.people_db();
	const niches = this.people_niches();

	const roomcap = V.optnpcroomcap || 200;

	let locpassage = Story.get(setup.ob_housing.is_housing() ? "HousingRoom" : loc);
	const loctags = locpassage ? locpassage.tags : [];

	let campus = ["Campus", "BlodgettGym", "ChamberlainHall", "EmersonBuilding", "HallowellBuilding", "SmithLibrary", "SummitMarket", "ThoreauBuilding", "BangCoffee"];
	let campusfood = ["ChamberlainHall", "SummitMarket"];
	let campusrec = ["UniMall", "ChamberlainHall", "SummitMarket", "SmithLibrary", "BlodgettGym", "BangCoffee"];
	let campusrecminor = ["Greenhouse"];
	let town = ["Town", "QuickieBurger", "RiversidePlaza", "RiverRat", "Arcade", "Cinema", "Licketysplits", "CommunityCenter"];
	let transport = ["Bus"];
	let quadparty = ["HelleborineTrilliumQuad", "HelleborineHall"];
	let harvesteveparty = ["ChamberlainHallInterior"];
	let renfestparty = ["ResidentsLounge"];
	let springrilsplashparty = ["UniMall"];
	let outsidequadparty = "HannaRdS";
	let nightlife = ["RiverRat", "Arcade", "Cinema", "Licketysplits"];
	let greekhouses = ["GreekHouseAXA", "GreekHouseDDR", "GreekHouseSOT", "GreekHouseZKX"];

	let alwaysalone = ["RiversideMotelRoom"];

	let motel = ["RiversideMotel"];
	let motelmgrday = V.niches["The Motel Day Manager"];
	let motelmgrnight = V.niches["The Motel Night Manager"];
	let ismotelday = V.hour >= 10 && V.hour < 22;
	let ismotelnight = !ismotelday;

	let hour = V.hour;
	let weekday = setup.ob_time.weekday();
	let timeofday = setup.ob_time.timeofday();

    let genders = setup.ob_location_allowed_genders(loc);

	let badweather = setup.ob_weather.is_bad();

	const alwayspartywithniches = ["The Best Friend"];

	if (loctags.includes("nobodyhere") || alwaysalone.includes(loc))
	{
		people_here_list = [];
	}
	else if (setup.ob_housing.is_housing() && hkey in V.pchousing)
	{
		let owner = V.pchousing[hkey].owner;
		let housemates = [];
		if (!V.pc.equals(owner))
			housemates.push(owner);
		for (let rm of (setup.ob_housing.get_roommates_raw(hkey) || []))
			if (!V.pc.equals(rm) && !housemates.includes(rm))
				housemates.push(rm);

		const scheduleslots = setup.ob_time.current_schedule_slot_calcall();

		const lookingahead = roomid != V.housing.roomID;
		const roomclass = setup.ob_housing.room_class_raw(hkey, roomid);
		if (lookingahead || !setup.ob_housing.roomClasses[roomclass].private)
		{
			for (let p of housemates)
			{
				const rmlocation = setup.ob_housing.roommate_location(hkey, p);
				if (!rmlocation) continue;

				let here = roomid == rmlocation;

				if (here)
					people_here_list.push(p);
			}
		}
	}
	else if (quadparty.includes(loc) && setup.ob_is_quad_party_time())
	{
		people_here_list = [...get_quad_party_people()];
		for (let niche of alwayspartywithniches)
			if (V.niches[niche] && !people_here_list.includes(V.niches[niche]))
				people_here_list.push(V.niches[niche]);
	}
	else if (harvesteveparty.includes(loc) && setup.ob_is_harvesteve_party_time())
	{
		people_here_list = [...add_student_attendees_with_chance(0.8)];
		for (let niche of alwayspartywithniches)
			if (V.niches[niche] && !people_here_list.includes(V.niches[niche]))
				people_here_list.push(V.niches[niche]);

	}
	else if (springrilsplashparty.includes(loc) && setup.ob_is_springrilsplash_party_time())
		{
			people_here_list = [...add_student_attendees_with_chance(0.8)];
			for (let niche of alwayspartywithniches)
				if (V.niches[niche] && !people_here_list.includes(V.niches[niche]))
					people_here_list.push(V.niches[niche]);

		}
	else if (renfestparty.includes(loc) && setup.ob_is_renfest_party_time())
	{
		people_here_list = [...add_student_attendees_with_chance(0.9)].filter(p => setup.people.residence(p) == "Chicory Hall");
		for (let niche of alwayspartywithniches)
			if (V.niches[niche] && !people_here_list.includes(V.niches[niche]))
				people_here_list.push(V.niches[niche]);
	}

	else if (loc == "LibraryBasement" && V.librarystory?.doms && V.librarystory.doms.length > 0)
	{
		people_here_list = [V.niches["The Librarian"], ...V.librarystory.doms, ...V.librarystory.subs];
	}
	else if (setup.ob_time.nightlife_time() && setup.ob_nightlife_location())
	{
		// nightlife locations have special handling!
		// put everybody here who favors this location today

		let seed = V.day.toString() + V.hour.toString();
		let rng = setup.ob_newRNG(seed);

		let business = setup.job_at_location();
		let day = setup.ob_time.day_of_week.indexOf(setup.ob_time.weekday());
