			if (p == motelmgrday && ismotelday) continue;
			else if (p == motelmgrnight && ismotelnight) continue;
			else if ((setup.people.is_relevant(p) || people_here_list.length < 20 || rng.random() < 0.2) && validtypes.includes(setup.people.get_type(p)) && setup.people.nightlife_choice_today(p, day) == business)
				people_here_list.push(p);
