								"BFFDorm": {"schedule block": "home", "free time chance": 0.0},
							};


		if (!passagelocs[loc])
		{
			console.error(`Bad schedule lookup, searching at location ${loc}`);
			return people_here_list;
		}
		const scheduleblock = passagelocs[loc]["schedule block"];
		let freetimechance = passagelocs[loc]["free time chance"];

		if (setup.School.current_eventday() == "Renewal Festival" && V.hour >= 18 && loc == "ResidentsLounge")
			freetimechance = 0.6;

		const classestoday = setup.School.classes_today() && hour <= setup.School.last_bell();
		const classestomorrow = setup.School.classes_tomorrow();
		const dayoffconstants = ["showers", "restroom", "food", "home"];

		const scheduleslots = setup.ob_time.current_schedule_slot_calcall();

		for (const [person, pinfo] of Object.entries(db).shuffle())
		{
			if (people_here_list.length >= roomcap) break;

			const thisscheduleslots = setup.ob_time.schedule_slots_for(person, scheduleslots);

			let belonghere = false;
			if (pinfo.residence == "Chicory Hall")
				belonghere = true;
			else if (pinfo.schedule && (!classestoday || hour > setup.School.last_bell()) && loc == "ResidentsLounge")
				belonghere = State.random() <= 0.1;

			if (pinfo.type == "student" && belonghere)
			{
				const slot = typeof pinfo.schedule == "number" ? thisscheduleslots[pinfo.schedule - 1] : setup.ob_time.current_schedule_slot(setup.get_student_schedule(pinfo.schedule));
				const dayoff_location = slot?.location ? dayoffconstants.includes(slot.location) : {};
				let slotloc = (classestoday || dayoff_location) ? slot?.location : "free time";
				if (!classestomorrow && V.hour >= 22 && slotloc == "home") slotloc = "free time";

				if (loc == "ResidentsLounge" && badweather)
					freetimechance *= 2; // more people indoors in bad weather

				if (loc == "ResidentsLounge" && people_here_list.length >= 40)
