				if (loc == "YourDorm")
				{
					if (pinfo.roommate == "PC")
					{
						if (slotloc == "home")
							people_here_list.push(person);
						else if (slotloc == "free time" && State.random() <= 0.4)
							people_here_list.push(person);
					}
				}
				else if (loc == "BFFDorm")
				{
					let bff = V.niches["The Best Friend"];
					if (person == bff)
					{
						people_here_list.push(bff);
					}
					else if (pinfo.roommate == bff)
					{
						if (slotloc == "home")
							people_here_list.push(person);
						else if (slotloc == "free time" && State.random() <= 0.2)
							people_here_list.push(person);
					}
				}
				else if (slotloc == scheduleblock)
				{
					people_here_list.push(person);
				}
				else if ((slotloc == "showers" || slotloc == "restroom") && loc == "MainHall" && State.random() <= 0.2)
				{
					people_here_list.push(person);
				}
				else if (slotloc == "free time" && State.random() <= freetimechance)
				{
					people_here_list.push(person);
				}
				else if (slotloc == "food" && State.random() <= (freetimechance / 3.0))
				{
					people_here_list.push(person);
				}
			}
		}
	}
	else if (greekhouses.includes(locblock))
	{
		// we are currently in one of the Greek houses... mostly its residents will be around, if they're free
		// and maybe some guests
		const passagelocs = {	"HouseAXALaundry": {"schedule block": "showers", "free time chance": 0.05},
								"HouseDDRLaundry": {"schedule block": "showers", "free time chance": 0.05},
								"HouseSOTLaundry": {"schedule block": "showers", "free time chance": 0.05},
								"HouseZKXLaundry": {"schedule block": "showers", "free time chance": 0.05},
								"HouseAXABathroom": {"schedule block": "restroom", "free time chance": 0.1},
								"HouseDDRBathroom": {"schedule block": "restroom", "free time chance": 0.1},
								"HouseSOTBathroom": {"schedule block": "restroom", "free time chance": 0.1},
								"HouseZKXBathroom": {"schedule block": "restroom", "free time chance": 0.1},
								"HouseAXABathroom": {"schedule block": "showers", "free time chance": 0.1},
								"HouseDDRBathroom": {"schedule block": "showers", "free time chance": 0.1},
								"HouseSOTBathroom": {"schedule block": "showers", "free time chance": 0.1},
								"HouseZKXBathroom": {"schedule block": "showers", "free time chance": 0.1},
								"HouseAXAKitchen": {"schedule block": null, "free time chance": 0.1},
								"HouseDDRKitchen": {"schedule block": null, "free time chance": 0.1},
								"HouseSOTKitchen": {"schedule block": null, "free time chance": 0.1},
								"HouseZKXKitchen": {"schedule block": null, "free time chance": 0.1},
								"HouseAXAMainRoom": {"schedule block": null, "free time chance": 0.8},
								"HouseDDRMainRoom": {"schedule block": null, "free time chance": 0.8},
								"HouseSOTMainRoom": {"schedule block": null, "free time chance": 0.8},
								"HouseZKXMainRoom": {"schedule block": null, "free time chance": 0.8},
							};

		if (!(loc in passagelocs)) return people_here_list;

		const greekparty = setup.ob_houses.is_greek_party_time() && setup.ob_houses.greek_party_host() == V.greekhouse;

		const scheduleblock = passagelocs[loc]["schedule block"];
		let freetimechance = passagelocs[loc]["free time chance"];

		const house = setup.ob_houses.house_from_letters(loc);

		if (setup.School.current_eventday() == "Renewal Festival" && V.hour >= 18 && loc.match("MainRoom"))
			freetimechance = 0.6;

		const classestoday = setup.School.classes_today() && hour <= setup.School.last_bell();
		const classestomorrow = setup.School.classes_tomorrow();
		const dayoffconstants = ["showers", "restroom", "food", "home"];

		const scheduleslots = setup.ob_time.current_schedule_slot_calcall();

		if (!house)
		{
			// most likely we're in the player's bedroom
			return people_here_list;
		}

		const officers = [V.houses[house].president, V.houses[house].rushchair];

		for (const [person, pinfo] of Object.entries(db).filter(([_, pinfo]) => pinfo.type === "student").shuffle())
		{
			if (people_here_list.length >= roomcap) break;

			const thisscheduleslots = setup.ob_time.schedule_slots_for(person, scheduleslots);

			if (greekparty)
			{
				if (setup.ob_houses.house(person) || State.random() < 0.2)
					people_here_list.push(person);
				continue;
			}

			let belonghere = false;
			if (pinfo.house == house)
				belonghere = true;
			else if (pinfo.schedule && (!classestoday || hour > setup.School.last_bell()) && loc.match("MainRoom"))
				belonghere = State.random() <= 0.025;

			if (pinfo.type == "student" && belonghere)
			{
				const slot = typeof pinfo.schedule == "number" ? thisscheduleslots[pinfo.schedule - 1] : setup.ob_time.current_schedule_slot(setup.get_student_schedule(pinfo.schedule));
				const dayoff_location = slot?.location ? dayoffconstants.includes(slot.location) : {};
				let slotloc = (classestoday || dayoff_location) ? slot?.location : "free time";

				if (!classestomorrow && V.hour >= 22 && slotloc == "home") slotloc = "free time";

				if (loc == "YourGreekHouseRoom")
				{

				}
				else if (slotloc == "free time" && officers.includes(person) && loc.indexOf("MainRoom") > 0 && setup.ob_houses.is_rush_week())
				{
					people_here_list.push(person);
				}
				else if (slotloc == scheduleblock)
				{
					people_here_list.push(person);
				}
				else if ((slotloc == "showers" || slotloc == "restroom") && loc.match("MainRoom") && State.random() <= 0.2)
				{
					people_here_list.push(person);
				}
				else if (slotloc == "free time" && State.random() <= freetimechance)
				{
					people_here_list.push(person);
				}
				else if (slotloc == "food" && State.random() <= (freetimechance / 3.0))
				{
					people_here_list.push(person);
				}
				else if (slotloc == "food" && loc.match("Kitchen"))
				{
					people_here_list.push(person);
				}
			}
		}
	}
	else if (setup.School.is_pc_at_class(true) && (V.inclass || V.prevclass))
	{
		// who's in class with the pc?
		// will also retrieve the professor since we're not restricting this check to students
		V.absentees = [];
		let course = setup.School.current_class();
		if (course.type == "sports" && setup.School.sports[course.course].peoplefrom)
		{
			// show people from other sport instead
			course.course = setup.School.sports[course.course].peoplefrom;
		}
		for (const [person, pinfo] of Object.entries(db).shuffle())
		{
			if (((course.type == "class" && pinfo.courses && Array.isArray(pinfo.courses) && pinfo.courses.includes(course.course)) || (course.type == "sports" && pinfo.sports && Array.isArray(pinfo.sports) && pinfo.sports.includes(course.course))))
			{
				if (State.random() < 0.95 || pinfo.type == "faculty")
				{
					people_here_list.push(person);
				}
				else
				{
					V.absentees.push(person);
				}
			}
		}

		// things with gawkers

		let gawkercap = Math.max(roomcap - people_here_list.length, 20);

		if (course.course == "cheerleading" || course.course == "football")
		{
			let gawkers = [];
			for (const [person, pinfo] of Object.entries(db).shuffle())
			{
				if (gawkers.length >= gawkercap) break;

				if (pinfo.type == "student")
				{
					if (!pinfo.sports && ((setup.people.has_any_inclination(person, "voyeur") && State.random() <= 0.25) || State.random() <= 0.05) && gawkers.length < 10)
					if (course.course == "cheerleading" && (setup.people.attracted_enough_to_pc(person) || setup.people.attraction(person).genders.includes("female")))
					{
						people_here_list.push(person);
						gawkers.push(person);
					}
					else if (course.course == "football" && (setup.people.attracted_enough_to_pc(person) || setup.people.attraction(person).genders.includes("male")))
					{
						people_here_list.push(person);
						gawkers.push(person);
					}
				}
			}
		}
	}
	else if (campus.includes(locblock))
	{
		// who's around on campus?
		// a bit loose but it doesn't matter too much really
		// may have to play with percentages if there are too many/too few people in the average 'room'

		if (loc == "MediaProductionLab" && V.hour >= 18 && V.niches["The Classroom Harasser"] && (!V.removedpeople || !V.removedpeople.includes(V.niches["The Classroom Harasser"])) && setup.ob_events.assemble_set(["harasser mpl"]).length > 0)
		{
			// place harasser alone in MPL at certain hours if event available
			people_here_list.push(V.niches["The Classroom Harasser"]);
		}
		else
		{
			let anybodyhere = true;
			let quadpartyhere = loc == outsidequadparty && setup.ob_is_quad_party_time();

			const classestoday = setup.School.classes_today();
			const currentclass = setup.School.current_class();

			if (timeofday == "night" && State.random() > 0.4 && !quadpartyhere)
				anybodyhere = false;

			if (setup.ob_is_closed(loc))
				anybodyhere = false;

			if (V.breakingin)
				anybodyhere = false;

			if (anybodyhere)
			{
				const scheduleslots = setup.ob_time.current_schedule_slot_calcall();
				for (const [person, pinfo] of Object.entries(db).shuffle())
				{
					if (people_here_list.length >= roomcap) break;

					const thisscheduleslots = setup.ob_time.schedule_slots_for(person, scheduleslots);

					if (pinfo.type == "student" && "schedule" in pinfo)
					{
						if (genders.length == 0 || genders.includes(pinfo.species[1]))
						{
							let slot = typeof pinfo.schedule == "number" ? thisscheduleslots[pinfo.schedule - 1] : setup.ob_time.current_schedule_slot(setup.get_student_schedule(pinfo.schedule));
							let slotloc = slot?.location;
							if (slotloc == "class" && (!classestoday || !currentclass)) slotloc = "free time";
							let herechance = 0.025;

							if (quadpartyhere)
								herechance = 0.1;
							else if (slotloc == "food" && campusfood.includes(locblock))
								herechance = 0.1;
							else if (slotloc == "free time" && (campusrec.includes(locblock) || campusrec.includes(loc)))
								herechance = 0.1;
							else if (slotloc == "free time" && (campusrecminor.includes(locblock) || campusrecminor.includes(loc)))
								herechance = 0.05;
							else if (hour >= 6 && hour <= 8 && loc == "UniMall")
								herechance = 0.1;
							else if (slotloc == "food" && loc == "UniMall")
								herechance = 0.075;
							else if (slotloc == "class" && classestoday)
								herechance = 0.005;
							else if (slotloc == "home")
								if (timeofday == "night")
									herechance = 0.0025;
								else
									herechance = 0.05;
							else if (slotloc == "restroom" || slotloc == "showers")
								herechance = 0.0075;

							if (loc == "UniMall" && badweather)
								herechance /= 2; // not as many people hanging out in the park in bad weather
							else if (campusfood.includes(locblock) && badweather)
								herechance *= 2; // they're hanging out indoors instead

							if (State.random() <= herechance)
								people_here_list.push(person);
						}
					}
				}
			}
			if (timeofday == "night" && State.random() <= 0.1)
			{
				const cop = V.niches["The Campus Cop"];
				people_here_list.push(cop);
			}
		}
	}
	else if (transport.includes(locblock))
	{
		// the bus!

		let studentherechance = 0.0;
		let townieherechance = 0.0;

		if ((hour >= 7 && hour <= 9) || (hour >= 16 && hour <= 18))
		{
			// morning/evening rush hour
			townieherechance = 0.04;
			studentherechance = 0.01;
		}
		else if (hour >= 11 && hour <= 13)
		{
			// lunch rush
			townieherechance = 0.02;
			studentherechance = 0.005;
		}
		else if (hour >= 6 && hour <= 22)
		{
			// daytime
			townieherechance = 0.01;
			studentherechance = 0.005;
		}
		else
		{
			// a weird time
			townieherechance = 0.005;
			studentherechance = 0.0001;
		}

		for (const [person, pinfo] of Object.entries(db).shuffle())
		{
			if (people_here_list.length >= roomcap) break;

			if ((pinfo.type == "student" && State.random() <= studentherechance)
				|| (pinfo.type == "townie" && State.random() <= townieherechance))
				{
					people_here_list.push(person);
				}
		}
	}
	else if (motel.includes(loc))
	{
		if (motelmgrday && ismotelday)
			people_here_list.push(motelmgrday);
		else if (motelmgrnight && ismotelnight)
			people_here_list.push(motelmgrnight);
	}
	else if (town.includes(locblock))
	{
		// who's in town?
		// mostly townies, but students can be here too, especially if there's no class today
		// as is usually the case, how we handle townies is relatively simple

		let towniecount = 0;

		for (const [archetype, arcinfo] of Object.entries(setup.ob_archetypes))
    	{
	        if ("townie count" in arcinfo) towniecount += arcinfo["townie count"];
		}

		let targetdensitybyhour = [4, 2, 2, 1, 1, 1, 2, 3, 4, 4, 6, 6, 8, 7, 7, 6, 6, 6, 6, 6, 5, 5, 4, 4];
		if (nightlife.includes(locblock))
		{
			targetdensitybyhour = [8, 6, 4, 4, 3, 2, 1, 1, 2, 3, 3, 3, 6, 6, 7, 8, 10, 14, 16, 16, 16, 14, 12, 10];
		}

		let targetdensity = targetdensitybyhour[hour];
		if (setup.ob_time.is_weekend()) targetdensity *= 1.25;
		let townieherechance = targetdensity / towniecount;

		if (badweather && setup.ob_location_is_outdoors())
			townieherechance /= 2; // not as many people outside in bad weather

		if (setup.ob_is_closed(loc))
			townieherechance = 0;

		let ppl = Object.keys(db).shuffle();
		let inippllen = ppl.length;
		if (locblock == "Arcade")
		{
			ppl = setup.people.order_by_skills("Video Gaming");
			ppl = ppl.slice(0, ppl.length / 2);
			townieherechance /= (ppl.length / inippllen);
		}

		let studentherechance = 0.0;
		if (setup.School.classes_today() && hour < 18)
		{
			studentherechance = townieherechance / 6.0;
		}
		else if (setup.School.classes_today())
		{
			studentherechance = townieherechance / 3.0;
		}
		else
		{
			studentherechance = townieherechance / 1.5;
		}

		for (const person of ppl)
		{
			if (people_here_list.length >= roomcap) break;

			let pinfo = setup.people.get_person(person);
			if ((pinfo.type == "student" && State.random() <= studentherechance)
				|| (pinfo.type == "townie" && State.random() <= townieherechance))
				{
					if (genders.length == 0 || genders.includes(pinfo.species[1]))
                	{
						people_here_list.push(person);
					}
				}
		}

		const staticppl = ["barpeople", "tablemates"];
		for (let i = 0; i < staticppl.length; i++)
		{
			let staticvar = V[staticppl[i]];
			if (staticvar)
			{
				for (let j = 0; j < staticvar.length; j++)
					if (!people_here_list.includes(staticvar[j]))
						people_here_list.unshift(staticvar[j]);
			}
		}
	}

	if (loc === "RiverRat") {
		const owner = V.niches["The River Rat Owner"];
		people_here_list = people_here_list.filter(p => p !== owner);

		const riverrat_additions = [V.waiter, V.bartender];
		if (V.hour >= 12 && V.hour < 22) riverrat_additions.unshift(owner);

		people_here_list = [...new Set([...riverrat_additions, ...people_here_list])];
	}

	let job = setup.job_at_location();
	let employeefound = 0;
	let minemployees = nightlife.includes(locblock) ? 2 : 1;
	if (job != null)
	{
		let employees = setup.ob_find_employees(job);
		employees = setup.ob_shuffle(employees);

		for (let emp of employees)
			if (setup.ob_business.is_working(emp, job))
			{
				if (!people_here_list.includes(emp))
					people_here_list.unshift(emp);
				employeefound++;
			}


		if (employeefound < minemployees)
		{
			for (let i = 0; i < employees.length; i++)
			{
				let pdata = db[employees[i]];

				if ((pdata.type == "townie" || (pdata.type == "student" && (!setup.School.classes_today() || V.hour >= 17)))
					&& !people_here_list.includes(employees[i])
					&& employeefound < minemployees)
					{
						if (!pdata.special) employeefound++;
						people_here_list.unshift(employees[i]);
					}
			}
		}
		if (employeefound == 0)
		{
			// almost certainly means we have a student-only workplace but it's during class
			// unfortunately for them, capitalism waits for nobody
			for (let i = 0; i < employees.length; i++)
			{
				let pdata = db[employees[i]];

				if (!people_here_list.includes(employees[i]) && employeefound < minemployees)
					{
						employeefound++;
						people_here_list.unshift(employees[i]);
					}
			}
		}
	}

	// highly specific stuff

	// put QuickieBurger employees on picket line
	if (loc == "NutmegSt" && V.quickieburgerjob &&
		V.quickieburgerjob.strike && V.quickieburgerjob.strike >= V.gameday &&
		!setup.ob_is_closed("QuickieBurger"))
	{
		let employees = setup.ob_find_employees("QuickieBurger");
		employees = setup.ob_shuffle(employees);
		for (let i = 0; i < employees.length; i++)
		{
			let pdata = db[employees[i]];

			if ((pdata.type == "townie" || (pdata.type == "student" && (!setup.School.classes_today() || V.hour >= 17)))
				&& !people_here_list.includes(employees[i])
				&& (State.random() <= 0.33 || !employeefound))
				{
					employeefound = true;
					people_here_list.unshift(employees[i]);
				}
		}
		if (!people_here_list.includes(V.quickieburgerjob.unionleader))
			people_here_list.unshift(V.quickieburgerjob.unionleader);
	}

	if (loc == "Arcade" && V.arcade)
	{
		people_here_list = [...new Set([...(V.arcade.competitors ?? []), ...people_here_list])]
	}

	if (loc == "MailCenter") {
		people_here_list = [...new Set([V.niches["The Mail Center Worker"], ...people_here_list])];
	}

	if (loc == "QuadTabletop" && V.tabletopgroup) {
		people_here_list = V.tabletopgroup.map(p => p.person);
	}

	// are we on a hangout? make sure we're with our person
	people_here_list = V.hangout ? [...new Set([V.hangout.partner, ...people_here_list])] : people_here_list;

	const excised_from_game_people = new Set(V.removedpeople);
	people_here_list = people_here_list.filter(p => !excised_from_game_people.has(p));

	return people_here_list.filter(Boolean);


	// Internal helpers (will lift) for grabbing specific students. Try and keep DRY

