		const attendees = [];
		const students = Object.entries(db).filter(([_, pinfo]) => pinfo.type === "student").shuffle();
		const roomcap = V.optnpcroomcap || 200;

		const per_person_change_function = typeof chance_input === "function"
			? chance_input
			: () => chance_input ?? 1;

		for (const [person, pinfo] of students) {
			if (attendees.length >= roomcap) break;
			const chance = per_person_change_function(person, pinfo);
			if (State.random() <= chance) {
				attendees.push(person);
			}
		}
		return attendees;
