			party_attendees = [...new Set([...[niches["The Rich Kid"], niches["The Best Friend"], V.quadparty?.invitedby],
										   ...(V.quadparty?.chatgroup || [])])];
		}

		const location_and_weather_chance_function = (_, pinfo) => {
			let chance = pinfo.residence === "Helleborine Hall" ? 0.33 : 0.1;
			const quieter_inside = loc === "HelleborineHall" && !badweather;
			const quieter_outside = loc !== "HelleborineHall" && badweather;
			if (quieter_inside || quieter_outside) chance /= 1.5;
			return chance;
		};

		return [...new Set([...party_attendees, ...add_student_attendees_with_chance(location_and_weather_chance_function)])];
