//#region Petitions Functions

setup.ob_petitions.get_data = function(petition)
{
    return this.db[petition];
}

setup.ob_petitions.set_status = function(petition, status)
{
    if (!this.get_data(petition)) return;
    if (!V.petitions) V.petitions = {};
    if (V.petitions[petition] == status) return;

    V.petitions[petition] = status;
}

setup.ob_petitions.devise = function(petition)
{
    if (petition == this.get_current())
    {
        V.petition_signed = [];
        V.petition_refused = [];
    }
    this.set_status(petition, "devised");
}

setup.ob_petitions.start = function(petition)
{
    V.petition_signed = [];
    V.petition_refused = [];
    this.set_status(petition, "started");
}

setup.ob_petitions.finish = function(petition)
{
    V.petition_signed = [];
    V.petition_refused = [];
    this.set_status(petition, "finished");

    const data = this.get_data(petition);
    if (data.override) this.devise(data.override);
}

setup.ob_petitions.get_by_status = function(status)
{
    if (!V.petitions) return [];
    return Object.keys(this.db).filter((key) => V.petitions[key] == status);
}

setup.ob_petitions.get_devised = function()
{
    return this.get_by_status("devised");
}

setup.ob_petitions.get_current = function()
{
    const current = this.get_by_status("started");
    if (!current || current.length == 0) return null;
    return current[0];
}

setup.ob_petitions.get_finished = function()
{
    return this.get_by_status("finished");
}

setup.ob_petitions.is_finished = function(petition)
{
    return V.petitions && V.petitions[petition] == "finished";
}

setup.ob_petitions.get_people = function()
{
    let people = [];
    let refused = [];

    for (let i = 0; i < V.peopleatlocation.length; i++)
    {
        if (V.petition_signed.includes(V.peopleatlocation[i])) continue;
        if (V.petition_refused.includes(V.peopleatlocation[i]))
            refused.push(V.peopleatlocation[i]);
        else
            people.push(V.peopleatlocation[i]);
    }

    return [...setup.ob_shuffle(people), ...setup.ob_shuffle(refused)];
}

setup.ob_petitions.sign = function(npc)
{
    if (!V.petition_signed.includes(npc))
        V.petition_signed.push(npc);
}

setup.ob_petitions.refuse = function(npc)
{
    if (!V.petition_refused.includes(npc))
        V.petition_refused.push(npc);
}

setup.ob_petitions.has_refused = function(npc)
{
    return V.petition_refused.includes(npc);
}

setup.ob_petitions.target = function()
{
    let result = 100;

    if (setup.ob_npc_generation_multiplier() > 1)
        result = Math.round(result * setup.ob_npc_generation_multiplier() / 10) * 10;

    return result;
}

setup.ob_petitions.current_signatures = function()
{
    return V.petition_signed ? V.petition_signed.length : 0;
}

setup.ob_petitions.target_reached = function()
{
    return this.current_signatures() >= this.target();
}

setup.ob_petitions.target_half_reached = function()
{
    return this.current_signatures() >= this.target() / 2;
}

setup.ob_petitions.npc_swimwear = function(npc)
{
    if (!this.is_finished("CampusSwimwear")) return false;
    if (!setup.people.is_student(npc)) return false;
    if (!setup.people.has_any_inclination(npc, "basic_exhibitionist")) return false;
    if (setup.ob_weather_is_cold() || setup.ob_weather_is_wet()) return false;
    if (setup.ob_weather_is_hot()) return State.random() < 0.25;
    else return State.random() < 0.05;
}
