setup.ob_phone.get_response = function(npc, responsetype, subs = [])
{

    let niche = setup.people.find_niche(npc);

    let tags = [];
    if (Array.isArray(responsetype))
        tags = [...tags, ...responsetype];
    else
        tags = [...tags, responsetype];
    if (!tags.includes("phone response")) tags.unshift("phone response");

    try
    {
        let response;

        if (niche)
        {
            response = setup.ob_dialogue.pick([...tags, niche], npc);
        }
        if (!response)
        {
            response = setup.ob_dialogue.pick(tags, npc);
        }

        if (response && !V.pc.equals(npc))
        {
            V.npctextresponse = response;

            if (response.alterAttitudes && !V.textedtoday.includes(npc))
            {
                for (const [attitude, val] of Object.entries(response.alterAttitudes))
                    setup.people.alter_attitude(npc, attitude, val);
                V.textedtoday.push(npc);
            }
        }

        if (response)
        {
            response = setup.ob_dialogue.parse(response, npc, subs);
            return response?.line;
        }
    }
    catch (error)
    {
        console.log("error finding response line", error, "tags=", tags);
        return "huh?";
    }
}

setup.ob_phone.execute_pc_response = function(response, npc)
{
    // runs when the player picks a phone texting menu option
    if (response.adviseFor != undefined)
    {
        let queued = setup.ob_nPCSimulation.is_queued_for(response.adviseFor[0], npc, true);
        if (response.adviseFor[1])
        {
            setup.ob_nPCSimulation.clear_advice(queued);
        }
        else
        {
            setup.ob_nPCSimulation.delete_from_queue(queued);
        }
    }
}

setup.ob_phone.notifications = function()
