}

setup.ob_phone.open_shortcuts = function()
{
    const menu = document.getElementById("phone-shortcuts-menu");
    const arrow = document.getElementById("phone-dropdown-arrow");
    if (!menu || !arrow) return;
    menu.classList.add("open");
    arrow.setAttribute("aria-expanded", "true");
    setTimeout(function() {
        document.addEventListener("click", setup.ob_phone.shortcuts_outside_click);
        document.addEventListener("keydown", setup.ob_phone.shortcuts_escape);
    }, 0);
};

setup.ob_phone.close_shortcuts = function()
{
    const menu = document.getElementById("phone-shortcuts-menu");
    const arrow = document.getElementById("phone-dropdown-arrow");
    if (menu) menu.classList.remove("open");
    if (arrow) arrow.setAttribute("aria-expanded", "false");
    document.removeEventListener("click", setup.ob_phone.shortcuts_outside_click);
    document.removeEventListener("keydown", setup.ob_phone.shortcuts_escape);
};

setup.ob_phone.toggle_shortcuts = function(event)
{
    if (event) event.stopPropagation();
    const menu = document.getElementById("phone-shortcuts-menu");
    const arrow = document.getElementById("phone-dropdown-arrow");
    if (!menu || !arrow) return;
    if (!menu.classList.contains("open"))
        setup.ob_phone.open_shortcuts();
    else
        setup.ob_phone.close_shortcuts();
};

setup.ob_phone.shortcuts_outside_click = function(event)
{
    const menu = document.getElementById("phone-shortcuts-menu");
    if (!menu) return;
    if (!menu.contains(event.target))
        setup.ob_phone.close_shortcuts();
};

setup.ob_phone.shortcuts_escape = function(event)
{
    if (event.key == "Escape")
        setup.ob_phone.close_shortcuts();
};
