    }

    odds += boostodds;

    let rng = setup.ob_newRNG(setup.people.get_name(npc) + "risk");
    return rng.random() < odds;
}

setup.ob_pregnancy.cycle_start = function(npc)
{
    // get the day of the month (1-28) that this NPC's cycle starts

    if (V.pc.equals(npc) && V.pccyclestart)
        return V.pccyclestart;
    else
    {
        let pdata = setup.people.get_person(npc);
        if (pdata?.cycleStart)
            return pdata.cycleStart;
    }

    let rng = setup.ob_newRNG(setup.people.get_name(npc) + "cycle");
    return rng.rir(1, 28, true);
}

setup.ob_pregnancy.override_cycle_start = function(npc, startday)
