setup.ob_pregnancy.cycle_day = function(npc, day = V.gameday, cyclestartday = null)
{
    // get the day of the monthly cycle this NPC is on
    let start = (cyclestartday || this.cycle_start(npc));
    let current =  (((day - start) % 28) + 28) % 28 + 1;
    return current;
}

setup.ob_pregnancy.pills_missed = function()
{
    // just for the PC, returns how many pills the PC has missed taking this week
    // (today doesn't count)
    if (!V.bcpillstaken || V.bcpillstaken.length == 0) return 7;
    let retval = 0;
    if (!V.bcpillstaken.includes(V.gameday - 3))
        retval++;
    if (!V.bcpillstaken.includes(V.gameday - 2))
        retval++;
    if (!V.bcpillstaken.includes(V.gameday - 1))
        retval++;
    return retval;
}

setup.ob_pregnancy.fertility_today = function(npc, day = V.gameday, raw = false)
{
    // the odds that this NPC is fertile today

    if (V.optfertility == undefined) V.optfertility = 1;

    if (!this.is_fertile(npc, raw)) return 0;

    if (this.can_get_pregnant(npc))
    {
        if (this.has_iud(npc) && !raw)
            return 0;

        // establish baseline based on cycle day

        let cycleday = this.cycle_day(npc, day);
        let odds;

        if (cycleday <= 7)
            return 0;
        else if (cycleday <= 9)
            odds = 0.05;
        else if (cycleday <= 10)
            odds = 0.1;
        else if (cycleday <= 11)
            odds = 0.15;
        else if (cycleday <= 12)
            odds = 0.2;
        else if (cycleday <= 13)
            odds = 0.3;
        else if (cycleday <= 14)
            odds = 0.25;
        else if (cycleday <= 15)
            odds = 0.05;
        else
            odds = 0.002;

        if (raw)
            return odds;

        // modify by fertility multiplier option
        odds *= V.optfertility * this.is_fertile(npc);

        // check birth control, and how well NPC is adhering to pill schedule
        if (this.on_birth_control(npc))
        {
            if (V.pc.equals(npc))
            {
                let pillsmissed = this.pills_missed();
                if (pillsmissed == 0)
                {
                    odds *= 0.02;
                }
                else if (pillsmissed == 1)
                {
                    odds *= 0.4;
                }
                // after two missed days, the PC is effectively no longer on birth control, so we don't modify the odds
            }
            else
            {
                if (this.remembered_birth_control(npc))
                {
                    odds *= 0.02;
                }
                else
                {
                    odds *= 0.4;
                }
            }
        }

        return odds;
    }
    else if (this.has_vasectomy(npc))
    {
        return 0;
    }
    else
    {
        return this.is_fertile(npc);
    }
}

setup.ob_pregnancy.is_protected = function(npc)
{
    // whether the given npc (an object, not just a name) is using any kind of protection

    if (!this.is_fertile(npc)) return true;

    if (this.can_get_pregnant(npc))
    {
        return this.on_any_bc(npc);
    }
    else
    {
        return npc.condom || this.on_any_bc(npc);
    }
}

