setup.ob_pregnancy.believes_pc_on_bc = function(npc)
{
    let reltype = setup.ob_relationships.relationship_type_with(npc);
    let odds = 1;
    switch (reltype)
    {
        case "romantic":
        {
            if (V.pc.has_inclination("Cheater"))
                odds = 0.5;
            else
                odds = 1;
            break;
        }
        case "friendship":
        {
            odds = 1;
            break;
        }
        case "enemy":
        {
            if (this.can_get_pregnant(V.pc))
                odds = 0.1;
            else
                odds = 0;
            break;
        }
        default:
        {
            let desrel = setup.people.desired_relationship(npc);
            switch (desrel)
            {
                case "date":
                {
                    odds = 1;
                    break;
                }
                case "friend","fuckbuddy":
                {
                    odds = 1;
                    break;
                }
                case "hatefuck":
                case "rival":
                {
                    if (this.can_get_pregnant(V.pc))
                        odds = 0.1;
                    else
                        odds = 0;
                    break;
                }
                default:
                {
                    if (this.can_get_pregnant(V.pc))
                        odds = 0.5;
                    else
                        odds = 0.1;
                }
            }
        }
    }

    let rng = setup.ob_newRNG(setup.people.get_name(npc) + "believe");
    return rng.random() < odds;
}

setup.ob_pregnancy.will_become_pregnant = function(donor, receiver)
{
    // a final determination with random roll for whether an insemination event results in a pregnancy
    // donor and receiver must be objects

    let donorF = this.fertility_today(donor);
    let receiverF = this.fertility_today(receiver);

    if (!donorF || !receiverF) return; // we don't need to worry

    if (donor.using_condom() && !donor.condom_broke)
    {
        const condominfo = setup.ob_miscitems[donor.condom];
        donorF *= condominfo.fertilityMultiplier;
    }

    return State.random() < donorF && State.random() < receiverF;
}

setup.ob_pregnancy.simulate_npc_sex = function(npc1, npc2)
{
    // simulate two NPCs having sex
    // potentially PiV but we don't know for sure yet, this probably just comes from a 'having sex' simulation event
    // has some overlap with what this.inseminated() does but that's because these NPCs are probably not objects

    let donor;
    let receiver;
    if (this.can_get_pregnant(npc1) && !this.can_get_pregnant(npc2))
    {
        donor = npc2;
        receiver = npc1;
    }
    else if (this.can_get_pregnant(npc2) && !this.can_get_pregnant(npc1))
    {
        donor = npc1;
        receiver = npc2;
    }
    else if (this.mpreg && setup.people.has_part(npc1, "penis") && this.can_get_pregnant(npc2))
    {
        donor = npc1;
        receiver = npc2;
    }
    else return;

    if (!this.is_fertile(donor) || !this.is_fertile(receiver)) return;

    let tryingtogetpregnant = this.wants_pregnancy(donor, receiver) && this.wants_pregnancy(receiver, donor);

    if (!tryingtogetpregnant)
    {
        let condomchance = (this.carries_condom(donor) || this.carries_condom(receiver)) ? 0.95 : 0.8;
        let condom = State.random() < condomchance;

        if (condom && State.random() > 0.02) return; // simulate a slight break rate
        else if (!condom && State.random() > 0.2) return; // pullout success rate
    }

    let donorF = this.fertility_today(donor);
    let receiverF = this.fertility_today(receiver);

    this.register_creampie_given(donor, receiver);
    this.register_creampie_taken(receiver, donor);

    if (State.random() < donorF && State.random() < receiverF)
    {
        // well, this is it
        this.initiate_pregnancy(donor, receiver);
    }
}

setup.ob_pregnancy.register_creampie_given = function(npc, givento)
