setup.ob_pregnancy.possible_donors = function(npc)
{
    // get all possible donors who are in some sort of window to possibly be the correct one

    if (!this.is_pregnant(npc)) return [];

    const preginfo = this.get_pregnancy_info(npc);

    let retval = [];

    let takenfrom = V.pc.equals(npc) ? V.lastcreampietakenfrom : setup.people.get_person(npc).lastcreampietakenfrom;
    if (!takenfrom)
    {
        retval = [];
    }
    else
    {
        const pregday = preginfo.start;
        const startwindow = pregday - 7;
        const endwindow = pregday + 7;

        for (const [donor, donorday] of Object.entries(takenfrom))
            if (donorday >= startwindow && donorday <= endwindow)
                retval.push(donor);
    }

    if (preginfo && !retval.includes(preginfo.donor)) // shouldn't happen, but you know
        retval.push(preginfo.donor);

    return retval;
}

