setup.ob_pregnancy.initiate_pregnancy = function(donor, receiver)
{
    // set up and initiate a pregnancy in 'receiver' fertilized by 'donor'
    console.log(`Pregnancy initiated: ${setup.people.get_name(receiver)} by ${setup.people.get_name(donor)}`);

    let preg = {
        donor: V.pc.equals(donor) ? "PC" : setup.people.get_name(donor),
        start: V.gameday,
        progress: 0,
        days: 0,
        trimester: 1,
        known: false,
        knownbydonor: false,
        due: false,
        wanted: V.pc.equals(receiver) ? undefined : this.wants_pregnancy(receiver, donor),
    };
    if (V.pc.equals(receiver))
    {
        V.pc.pregnant = preg;
    }
    else
