setup.ob_pregnancy.duration = function()
{
    // return duration in days based on current options
    return Math.round(this.baseDuration * V.optpregduration);
}

setup.ob_pregnancy.advance_day = function(npc)
{
    let preg = V.pc.equals(npc) ? V.pc.pregnant : setup.people.get_person(npc).pregnant;
    preg.days++;
    let progperday = 1 / this.duration();
    preg.progress += progperday;

    if (preg.progress >= 0.667)
        preg.trimester = 3;
    else if (preg.progress >= 0.333)
        preg.trimester = 2;
    else
        preg.trimester = 1;

    if (preg.progress >= 1)
    {
        preg.progress = 1;
        preg.due = true;
    }

    return preg;
}

setup.ob_pregnancy.daily_tick = function()
{
    // advance progress on all pregnancies

    if (this.is_pregnant("PC"))
    {
        this.remove_pregnancy_if_birthed("PC");
        if (this.is_pregnant("PC"))
            this.advance_day("PC");
    }

    for (let npc of Object.keys(V.people))
        if (this.is_pregnant(npc))
        {
            this.remove_pregnancy_if_birthed(npc);
            if (this.is_pregnant(npc))
                this.advance_day(npc);
        }
}

setup.ob_pregnancy.advance_minutes = function(mins)
{
    // called when we advance game time
    // used to check whether the PC's pregnancy is due and determine whether they should go into labor

    if (!V.pc || V.sleeping || !V.pc.pregnant || !V.pc.pregnant.due || V.pc.pregnant.born) return;

    let oddsperminute = 0.002;
    let odds = oddsperminute * mins;

    if (State.random() <= odds)
    {
        let newoffspring = this.give_birth("PC"); // this effecively queues up the relevant event almost immediately, at the next location-to-location transition
        if (!V.pendingbirths) V.pendingbirths = newoffspring;
        else V.pendingbirths.push(...newoffspring);
    }
}

