}

setup.ob_pregnancy.positive_test_likelihood = function(npc)
{
    if (!this.is_pregnant(npc))
        return 0;

    // before a certain point the hormone being tested for isn't present enough to produce a positive result
    // and there is a chance of a false negative for a while after
    let mindays = Math.round(this.duration() * 0.035);
    let maxdays = Math.round(this.duration() * 0.0833);

    let days = this.days_pregnant(npc);
    if (days < mindays) return 0;
    else if (days >= maxdays || mindays == maxdays) return 1;
    else
    {
        let odds = (days - mindays) / (maxdays - mindays);
        return Math.clamp(odds, 0, 1);
    }
}

setup.ob_pregnancy.positive_test = function(npc)
{
    // roll for whether an individual pregnancy test has a positive result
    let odds = this.positive_test_likelihood(npc);
    return State.random() < odds;
}

