setup.ob_pregnancy.days_since_creampie_taken = function(npc)
{
    if (V.pc.equals(npc))
    {
        if (!V.lastcreampietaken) return -1;
        else return V.gameday - V.lastcreampietaken;
    }
    else
    {
        let last = setup.people.get_person(npc).lastcreampietaken;
        if (!last) return -1;
        else return V.gameday - last;
    }
}

setup.ob_pregnancy.wants_pregnancy = function(npc, donor = null)
{
    // whether this NPC wants to be pregnant / get someone pregnant

    // todo: for now NPCs tend to magically know who's responsible for their pregnancy
    // we're not really tracking confusion in that area, except for the PC

    if (!donor)
        return false;
    else
    {
        // evaluating whether we want current pregnancy

        let rel;
        if (V.pc.equals(donor))
            rel = setup.ob_relationships.relationship_with(npc);
        else
            rel = setup.ob_nPCSimulation.get_relationship(npc, donor);
        let reltype = setup.ob_relationships.db[rel]?.type;

        let chance = 0.5;

        let age = setup.people.get_age(npc);
        if (age <= 18)
            return false;
        else if (age <= 20)
            chance = 0.01;
        else if (age <= 25)
            chance = 0.05;
        else if (age <= 29)
            chance = 0.2;
        else if (age <= 34)
            chance = 0.25;
        else if (age <= 39)
            chance = 0.2;
        else if (age <= 44)
            chance = 0.1;
        else if (age <= 49)
            chance = 0.02;
        else
            return false;

        let type = setup.people.get_type(npc);
        if (type == "faculty" && (V.pc.equals(donor) || setup.people.get_type(donor) == "student"))
            return false;
        else if (type == "student")
            chance /= 4;

        if (reltype == "enemy")
            return false;
        else if (rel == "soulmate")
            chance *= 4;
        else if (reltype == "romantic")
            chance *= 2;

        if (setup.people.has_any_inclination(npc, "Careful"))
            chance /= 2;
        else if (setup.people.has_any_inclination(npc, "Breeding Kink"))
            chance *= 2;

        if (!this.known(npc))
        {
            // evaluate on the basis of not already being pregnant
            chance /= 2;
            if (chance < 0.4)
                return false;
        }
        else
        {
            // evaluate on the basis of already being pregnant
            if (this.pc_is_donor(npc))
            {
                // PC's opinion is a strong influence on NPC's preferred course of action
                let pcapproves = this.pc_approves(npc);
                if (pcapproves == true)
                    chance *= 2;
                else if (pcapproves == false)
                    chance /= 2;
            }
        }

        let rng = setup.ob_newRNG(setup.people.get_name(npc) + "preg");
        return rng.random() < chance;
    }
}

setup.ob_pregnancy.wants_morningafter_pill = function(npc)
{
    // whether an NPC wants to take a morning after pill

    let donor = this.donor(npc);
    if (!this.can_get_pregnant(npc) || this.days_since_creampie_taken(npc) == -1 || this.wants_pregnancy(npc, donor) || this.days_since_creampie_taken(npc) > 3) return false;

    if (this.known(npc) && this.days_pregnant(npc) > 3) return false;

    if (setup.people.has_inclination(npc, "Nature Prevails"))
        return false;

    if (setup.ob_pregnancy.last_morning_after_pill(npc) && V.gameday - setup.ob_pregnancy.last_morning_after_pill(npc) < this.days_since_creampie_taken(npc))
        return false;

    if (setup.people.has_inclination(npc, "Careful"))
        return true;

    let odds = 0.7;

    if (setup.people.has_any_inclination(npc, ["Breeding Kink", "Risktaker"]))
        odds -= 0.2;

    return State.random() < odds;
}

setup.ob_pregnancy.wants_pregnancy_test = function(npc)
{
    // whether an NPC wants to take a pregnancy test

    if (!this.can_get_pregnant(npc) || this.known(npc) || this.days_since_creampie_taken(npc) == -1 || (this.days_since_creampie_taken(npc) < 3 && !this.is_late(npc)))
        return false;

    if (setup.ob_pregnancy.last_pregnancy_test(npc) && V.gameday - setup.ob_pregnancy.last_pregnancy_test(npc) < 7)
        return false;

    if (setup.people.has_inclination(npc, "Careful"))
        return true;

    if (this.is_really_late(npc) || this.is_showing(npc))
        return true;

    let odds = 0.8;

    if (setup.people.has_any_inclination(npc, ["Nature Prevails"]))
        odds += 0.2;
    if (setup.people.has_any_inclination(npc, ["Risktaker"]))
        odds -= 0.2;

    return State.random() < odds;
}

setup.ob_pregnancy.is_late = function(npc)
