setup.ob_pregnancy.abortion_allowed = function(npc)
{
    // whether abortion is allowed at this stage of pregnancy

    // we'll try to do this as neutrally as possible i guess
    // in the US (where the game is set) prior to 2022 (our starting year is 2019, not that it ever comes up)
    // abortion had to be legal up until about 22-24 weeks (earlier limits were routinely struck down by courts)
    // so states could not restrict abortion before that point but could restrict it later than that point (most didn't)
    // after that point, abortion was legal only when necessary for the health of the mother
    // however, this game won't simulate such situations
    // all of this to say: this is the most straightforwardly factual/objective guideline for whether abortion is allowed
    // the cutoff is at ~60% of the way through a pregnancy, so we'll just go with that

    // further, a minimum time of 3 days, not because it literally isn't allowed but because a morning after pill will cover that

    let cutoff = this.duration() * 0.6;
    let dayspregnant = this.days_pregnant(npc);
    return dayspregnant > 3 && dayspregnant <= cutoff;
}

setup.ob_pregnancy.wants_abortion = function(npc)
{
    // whether the given npc wants an abortion

    // not going to get into the weeds with this one too much either
    // a study conducted in the US in 2020 found that about 17% of pregnancies ended in abortion

    if (!V.optabortion || !this.abortion_allowed(npc)) return false;

    if (!this.is_pregnant(npc) || !this.known(npc)) return false;

    if (this.wants_pregnancy(npc, this.donor(npc))) return false;

    if (V.pc.equals(this.donor(npc)) && this.pc_approves(npc)) return false;

    if (setup.people.has_inclination(npc, "Nature Prevails")) return false;

    let odds = 0.17;

    if (setup.people.has_inclination(npc, "Careful")) odds *= 2;

    let rng = setup.ob_newRNG(setup.people.get_name(npc) + this.get_pregnancy_info(npc).start.toString());
    return rng.random() < odds;
}

