setup.ob_pregnancy.determine_gender = function(npc)
{
    // determine the gender of this pregnancy
    // (should this use gender slider settings?? for now i'll go with no)
    let info = this.get_pregnancy_info(npc);

    if (info.genders) return;

    if (!info.count)
        this.determine_twins(npc);

    info.genders = [];
    for (let i = 0; i < info.count; i++)
        info.genders.push(setup.ob_randomrelfreq(["male", 50, "female", 50]));

    return info;
}

