setup.ob_pregnancy.filter_desc_subs = function(subs, expression)
{
    return subs.filter(sub =>
        !setup.distinguishing_marks[sub].pconly && !setup.distinguishing_marks[sub].adult &&
        (!setup.distinguishing_marks[sub].coding || setup.distinguishing_marks[sub].coding.includes(expression))
    );
}

setup.ob_pregnancy.determine_desc_subs = function(offspring)
{
    let info = offspring;

    info.traits = {};

    // todo: need to always roll a natural hair color for npcs
    // todo: retain pc natural hair color

    let donor = info.donor;
    let npc1 = setup.people.expand(offspring.deliverer || this.infer_deliverer(offspring.name));
    let npc2 = setup.people.expand(donor);

    info.traits = this.determine_traits(npc1, npc2, info);

    return info.traits;
}

setup.ob_pregnancy.determine_traits = function(npc1, npc2, offspring, rng)
{
    // roll traits etc

    npc1 = setup.people.expand(npc1);
    npc2 = setup.people.expand(npc2);

    if (!rng)
        rng = setup.ob_newRNG(`${offspring.birthGameDay}_${npc1}_${npc2}`);

    let retval = {};

    const traits = [
		"eye color",
		"hair color",
		"skin color",
    ];

    for (let trait of traits)
    {
        let val = rng.random() < 0.5 ? npc1[trait] : npc2[trait];
        retval[trait] = val;
    }

    let expression = offspring.sex == "male" ? "masc" : "femme";
    let dmarks = [...this.filter_desc_subs(npc1["distinguishing_marks"] || [], expression), ...this.filter_desc_subs(npc2["distinguishing_marks"] || [], expression)];
    if (dmarks.length > 0)
    {
        let dmark = rng.randomchoice(dmarks);
        retval["distinguishing_marks"] = [dmark];
    }

    return retval;
}

setup.ob_pregnancy.describe_offspring = function(offspring)
{
    // DESCRIBE
    //         THAT
    //             BABY
    if (!offspring.traits) offspring.traits = this.determine_desc_subs(offspring);
    let traits = offspring.traits;
    let boygirl = offspring.sex == "male" ? "boy" : "girl";
    let psc = offspring.sex == "male" ? "He" : "She";
    let desc = `baby ${boygirl} with ${traits["skin color"]} skin, ${traits["eye color"]} eyes, and ${traits["hair color"]} hair.`;
    if (traits["distinguishing_marks"])
    {
        let dmark = traits["distinguishing_marks"][0];
        desc += ` ${psc} also has ${(setup.distinguishing_marks[dmark].plural ? "" : setup.ob_a_or_an(dmark) + " ") + dmark}.`;
    }
    return desc;
}

setup.ob_pregnancy.give_birth = function(npc)
{
    // handles stuff we have to do to give birth, clear pregnancy, etc

    let preginfo = this.get_pregnancy_info(npc);
    preginfo.born = true;
    preginfo.deliverer = setup.people.get_name(npc);

    if (!preginfo.count) this.determine_twins(npc);
    if (!preginfo.genders) this.determine_gender(npc);
    if (!preginfo.traits) this.determine_desc_subs(preginfo);

    let donor = preginfo.donor;

    this.reset_cycle(npc);

    let offspring;
    if (!V.pc.equals(npc))
    {
        let pdata = setup.people.get_person(npc);
        if (pdata.offspring == undefined) pdata.offspring = {};
        offspring = pdata.offspring;
    }
    else
    {
        if (V.offspring == undefined) V.offspring = {}
        offspring = V.offspring;
        delete V.informedofpregnancy;
    }
    let allnewoffspring = [];
    for (let i = 0; i < preginfo.genders.length; i++)
    {
        let name = setup.ob_random_name(preginfo.genders[i]);
        let firstname = name.split(' ')[0];
        let lastname = setup.people.lastname(npc);

        name = `${firstname} ${lastname}`;
        while (setup.ob_name_in_use(name, true))
        {
            name = setup.ob_random_name(preginfo.genders[i]);
            firstname = name.split(' ')[0];
            name = `${firstname} ${lastname}`;
        }

        let newoffspring = {
            sex: preginfo.genders[i],
            birthday: [setup.ob_time.month(), V.day],
            birthYear: V.year,
            birthGameDay: V.gameday,
            donor: donor,
            presumedDonor: this.presumed_donor(npc) || donor,
            status: "unborn", // yeah this is kinda creepy
        }
        offspring[name] = newoffspring;

        let newoffspringinstance = Object.assign({}, newoffspring);

        newoffspringinstance.name = name;
        newoffspringinstance.deliverer = V.pc.equals(npc) ? "PC" : setup.people.get_name(npc);

        allnewoffspring.push(newoffspringinstance);
    }

    delete setup.ob_cached_offspring_names;

    return allnewoffspring;
}

