setup.ob_pregnancy.all_pc_offspring = function()
{
    // return all of the pc's offspring
    let retval = V.offspring || {};

    for (let npc of Object.keys(V.people).filter(p => this.offspring(p)))
    {
        let offspring = this.offspring(npc);
        for (let [name, data] of Object.entries(offspring))
            if (V.pc.equals(data.presumedDonor || data.donor))
                retval[name] = data;
    }

    return retval;
}

setup.ob_pregnancy.check_babyname = function(npc, babyname, newname)
{
    if (newname == babyname)
        return {pass: true};

    let firstname = newname.split(' ')[0];
    if (firstname.length < 2)
        return {pass: false, reason: "That name is too short."};
    else if (firstname.length > 30)
        return {pass: false, reason: "That name is too long."};
    else if (setup.ob_name_in_use(newname, true))
        return {pass: false, reason: "That name is already in use."};
    else
        return {pass: true};
}

setup.ob_pregnancy.set_baby_data = function(npc, babyname, newname, newstatus, traits)
{
    // replace baby data depending on player choices

    let offspring = V.pc.equals(npc) ? V.offspring : setup.people.get_person(npc).offspring;

    if (traits)
        offspring[babyname].traits = traits;

    if (newstatus)
        offspring[babyname].status = newstatus;

    if (newname && newname != babyname)
    {
        offspring[newname] = Object.assign({}, offspring[babyname]);
        delete offspring[babyname];
    }
}

setup.ob_pregnancy.get_baby_data = function(npc, babyname)
