    let offspring = V.pc.equals(npc) ? V.offspring : setup.people.get_person(npc).offspring;
    return offspring[babyname];
}

setup.ob_pregnancy.infer_deliverer = function(babyname)
{
    // figure out who the mom is

    if (V.offspring && babyname in V.offspring)
        return "PC";
    else if (V.pendingbirths && babyname in V.pendingbirths)
        return setup.ob_pregnancy.can_get_pregnant("PC") ? "PC" : setup.ob_relationships.all_partners("PC").filter(p => setup.ob_pregnancy.can_get_pregnant(p))[0];
    else
    {
        return Object.keys(V.people).filter(p => V.people[p].offspring && babyname in V.people[p].offspring)[0];
    }
}

