if (!setup.ob_relationships) setup.ob_relationships = {};

setup.ob_relationships.qualification_matches = function(name, qualificationkey, qualificationvalue)
{
    switch (qualificationkey)
    {
        case "inclinations":
            return setup.people.has_any_inclination(name, qualificationvalue);
        case "noinclinations":
            return !setup.people.has_any_inclination(name, qualificationvalue);
        case "sexualhistory":
            return setup.people.is_sexpartner(name) == qualificationvalue;
        default:
            let gte = qualificationkey.indexOf(">") >= 0;
            let lt = qualificationkey.indexOf("<") >= 0;
            if (gte || lt)
            {
                let attitude = qualificationkey.substring(0, qualificationkey.length - 1);
                return (gte && setup.people.get_attitude(name, attitude) >= qualificationvalue) ||
                    (lt && setup.people.get_attitude(name, attitude) < qualificationvalue);
            }
    }
}

setup.ob_relationships.matches_qualifications_all = function(name, qualifications)
{
    for (const [key, value] of Object.entries(qualifications))
    {
        if (!this.qualification_matches(name, key, value))
            return false;
    }
    return true;
}

setup.ob_relationships.matches_qualifications_any = function(name, qualifications)
{
    for (const [key, value] of Object.entries(qualifications))
    {
        if (this.qualification_matches(name, key, value))
            return true;
    }
    return false;
}

setup.ob_relationships.qualified = function(name, relationship, includecooldowns = true, includeexclusivity = true)
{
    const relinfo = this.db[relationship];
    if (relinfo.static) return false;
    name = setup.people.get_name(name);
    const pdata = setup.people.get_person(name);
    if (pdata.type == "faculty" && !relinfo.faculty) return false;
    let lastrelevent = pdata.lastRelEvent;
    const currel = this.relationship_with(name);

    /*
    console.log(this.matches_qualifications_all(name, relinfo.qualifying));
    console.log(!this.matches_qualifications_any(name, relinfo.disqualifying));
    console.log((relinfo.allowSpecial || setup.people.allow_free_interaction(name)));
    console.log((!relinfo.prereqRelationship || currel == relinfo.prereqRelationship));
    console.log((!relinfo.Ds || !pdata.noDs));
    console.log((!currel || this.db[currel].prereqRelationship != relationship));
    console.log((relinfo.type != "romantic" || !pdata.breakupDay || V.gameday - pdata.breakupDay >= 28));
    console.log(!this.in_exclusive_relationship_not_with(name, "PC", relinfo.type));
    console.log(!includeexclusivity || !relinfo.exclusive || !this.in_relationship_not_with(name, "PC", relinfo.type));
    console.log((!relinfo.setPartner || !this.partner(name) || this.partner(name) == "PC"));
    console.log((relinfo.desiredRelationships && relinfo.desiredRelationships.includes(setup.people.desired_relationship(name, false))));
    */

    return (!includecooldowns || !lastrelevent || V.gameday - lastrelevent > this.eventCooldown || relinfo.unilateralEntry) && // long enough since rel event?
        setup.people.is_known(name) && // do we know this person?
        this.matches_qualifications_all(name, relinfo.qualifying) && // matches all qualifying conditions
        !this.matches_qualifications_any(name, relinfo.disqualifying) && // matches no disqualifying conditions
        (relinfo.allowSpecial || setup.people.allow_free_interaction(name)) && // allowed with special NPCs, or NPC isn't special, or free interaction is allowed
        (relationship != "friend" || !includecooldowns || this.add_friends_today()) && // are we adding friends today?
        (!relinfo.prereqRelationship || this.is_prereq(relinfo.prereqRelationship, currel)) && // fulfill prereq?
        (!relinfo.Ds || !pdata.noDs) && // are we pursuing D/s with this person?
        (!relinfo.antiprereqRelationships || !relinfo.antiprereqRelationships.includes(currel)) && // not any antiprereqs?
        (!currel || !this.is_prereq(this.db[currel].prereqRelationship, relationship)) && // is this not a prereq of current relationship? (avoid tiering down)
        (relinfo.type != "romantic" || !pdata.breakupDay || V.gameday - pdata.breakupDay >= 28) && // not recently broken up?
        (relinfo.type != "romantic" || (!V.pc.has_inclination("Aromantic") && !setup.people.has_inclination(name, "Aromantic"))) && // not aromantic?
        !this.in_exclusive_relationship_not_with(name, "PC", relinfo.type) && // not already in exclusive relationship of this type
        (!includeexclusivity || !relinfo.exclusive || !this.in_relationship_not_with(name, "PC", relinfo.type)) && // won't start out violating exclusivity
        (!relinfo.setPartner || !this.partner(name) || this.partner(name) == "PC") && // don't overwrite partner
        (relinfo.type != "friendship" || !setup.people.is_exfriend(name)) && // are we contemplating a friendship that was deliberately ended?
        (relinfo.desiredRelationships && relinfo.desiredRelationships.includes(setup.people.desired_relationship(name, false))); // matches required desrel
}

setup.ob_relationships.is_prereq = function(prereq, rel)
{
    if (!prereq) return false;
    return Array.isArray(prereq) ? prereq.includes(rel) : prereq == rel;
};

setup.ob_relationships.disqualified = function(name, relationship, includecooldowns = true)
{
    const relinfo = this.db[relationship];
    const pdata = setup.people.get_person(name);
    let lastrelevent = pdata.lastRelEvent;
    return (!includecooldowns || !lastrelevent || V.gameday - lastrelevent > this.eventCooldown) &&
        (this.matches_qualifications_any(name, relinfo.disqualifying) ||
        (relinfo.desiredRelationships && !relinfo.desiredRelationships.includes(setup.people.desired_relationship(name, false))));
}

setup.ob_relationships.qualifying = function(name, includecooldowns = true)
{
    name = setup.people.get_name(name);
    const retval = [];
    for (const relationship of Object.keys(this.db))
    {
        if (this.qualified(name, relationship, includecooldowns))
            {
                retval.push(relationship);
            }
    }
    return retval;
}

setup.ob_relationships.disqualifying = function(name, includecooldowns = true)
{
    name = setup.people.get_name(name);
    const retval = [];
    for (const relationship of Object.keys(this.db))
    {
        if (this.disqualified(name, relationship, includecooldowns))
            {
                retval.push(relationship);
            }
    }
    return retval;
}

setup.ob_relationships.find_pending_relationships = function()
{
    V.pendingaddrelationships = {};
    V.pendingremoverelationships = {};

    for (let name of Object.keys(V.people))
    {
        if (!V.people[name].attitude) continue;
        let currel = V.people[name].relationship;
        let newrels = setup.ob_relationships.qualifying(name);
        if (newrels.includes(currel))
            newrels.splice(newrels.indexOf(currel), 1);
        if (newrels.length > 0)
            V.pendingaddrelationships[name] = newrels;

        if (currel && this.disqualified(name, currel))
            V.pendingremoverelationships[name] = currel;
    }

    if (V.optfreezeaddrels)
        V.pendingaddrelationships = {};
    if (V.optfreezeremrels)
        V.pendingremoverelationships = {};

    return [V.pendingaddrelationships, V.pendingremoverelationships];
}

setup.ob_relationships.relationship_with = function(name)
{
