    if (!pinfo) return undefined;
    if (pinfo.relationship)
    {
        const relinfo = setup.ob_relationships.db[pinfo.relationship];
        return relinfo.type;
    }
    else
        return undefined;
}

setup.ob_relationships.in_exclusive_relationship = function(name = "PC", type = "romantic")
{
    if (V.pc?.equals(name))
    {
        for (const [p, pinfo] of Object.entries(V.people))
        {
            if (pinfo.relationship && setup.ob_relationships.db[pinfo.relationship].exclusive && setup.ob_relationships.db[pinfo.relationship].type == type)
                return true;
        }
        return false;
    }
    else
    {
        const pinfo = setup.people.get_person(name);
        const partnertype = setup.ob_relationships.partner_type(name);

        if (pinfo.relationship && setup.ob_relationships.db[pinfo.relationship].exclusive && setup.ob_relationships.db[pinfo.relationship].type == type)
            return true;
        else if (pinfo.partner && setup.ob_relationships.db[partnertype].exclusive && setup.ob_relationships.db[partnertype].type == type)
            return true;
        else
            return false;
    }
}

setup.ob_relationships.in_exclusive_relationship_not_with = function(other, name = "PC", type = "romantic")
{
    if (V.pc?.equals(name))
    {
        for (const [p, pinfo] of Object.entries(V.people))
        {
            if (p != other && pinfo.relationship && setup.ob_relationships.db[pinfo.relationship].exclusive && setup.ob_relationships.db[pinfo.relationship].type == type)
                return true;
        }
        return false;
    }
    else
    {
        const pinfo = setup.people.get_person(name);
        if (pinfo.relationship && pinfo.partner != other && setup.ob_relationships.db[pinfo.relationship].exclusive && setup.ob_relationships.db[pinfo.relationship].type == type)
            return true;
        else if (pinfo.partner && pinfo.partner != other && setup.ob_relationships.db[setup.ob_relationships.partner_type(name)].exclusive && setup.ob_relationships.db[setup.ob_relationships.partner_type(name)].type == type)
            return true;
        else
            return false;
    }
}

