setup.ob_relationships.is_cheating = function(name)
{
    // if the PC will be cheating with the given NPC
    if (V.pc?.equals(name) || this.partner(name) == "PC") return false;
    for (const [p, pinfo] of Object.entries(V.people))
    {
        if (pinfo.relationship && !setup.ob_relationships.db[pinfo.relationship].allowNonPartnerDabbling && setup.ob_relationships.db[pinfo.relationship].type == "romantic")
            return true;
    }
    return false;
}

setup.ob_relationships.npc_is_cheating = function(name)
{
    // if the given NPC will be cheating with the PC
    const partner = this.partner(name);
    if (!partner || partner == "PC") return false;
    const ptype = (setup.people.get_person(name).partnerType ? setup.people.get_person(name).partnerType : setup.people.get_relationship(name, partner)) || "partner";
    if (!ptype) return;
    const relinfo = setup.ob_relationships.db[ptype];
    if (relinfo.allowNonPartnerDabbling)
        return false;
    else
    {
        if (setup.people.has_any_inclination(name, ["Polyamorous", "Open Relationships"]) && setup.people.has_any_inclination(partner, ["Polyamorous", "Open Relationships"]))
            return false;
        else
            return true;
    }
}

setup.ob_relationships.partner = function(name)
{
    if (V.pc?.equals(name))
    {
        for (const [p, pinfo] of Object.entries(V.people))
        {
            if (pinfo.relationship && (pinfo.partner == "PC" || this.relationship_type_with(p) == "romantic"))
            {
                pinfo.partner = "PC";
                return p;
            }
        }
    }
    else
    {
        const pinfo = setup.people.get_person(name);
        if (pinfo.partner == name)
            delete pinfo.partner;
        return pinfo.partner;
    }
}

