setup.ob_relationships.set = function(name, relationship, updateeventcounter = true)
{
    // set NPC's relationship to the PC
    const relinfo = this.db[relationship];
    name = setup.people.get_name(name);
    let currel = V.people[name].relationship;

    if (!relinfo.secondary)
    {
        if (currel)
        {
            V.people[name].previousrelationship = currel;
            if (relinfo.type == "romantic" && this.db[currel].type != "romantic")
                V.people[name].previousplatonicrelationship = currel;
        }
        V.people[name].relationship = relationship;
    }

    if (!V.people[name].allrelationships) V.people[name].allrelationships = [];
    if (relationship) V.people[name].allrelationships.push(relationship);

    if (relinfo.setPartner)
    {
        V.people[name].partner = "PC";
        V.people[name].partneredday = V.gameday;
        if (!relinfo.allowNonPartnerDabbling)
            this.convert_fuckbuddies_to_friends();
        if (setup.people.get_attitude(name, "romance") < 0) // give this a chance to go up if it's negative for some reason
            setup.people.set_attitude(name, "romance", 0);

        // if we're embarking on a brand new romantic relationship, assume everybody is happy with it (for the moment) and clear cheating partners
        this.unset_cheating_partner(name);
        this.unset_cheating_partner("PC");

        // this person might be sleeping with the PC now...
        setup.ob_housing.rearrange_roommates_for(name);
    }
    else if (V.people[name].partner == "PC")
    {
        delete V.people[name].partner;
        V.people[name].lastBreakup = V.gameday;
    }
    V.people[name].relationshipChangeDay = V.gameday;

    if (updateeventcounter && !relinfo.unilateralEntry)
    {
        V.people[name].lastRelEvent = V.gameday;
        V.lastRelEvent = V.gameday;
    }
    else if (updateeventcounter && currel && !this.db[currel].unilateralExit)
    {
        V.people[name].lastRelEvent = V.gameday;
        V.lastRelEvent = V.gameday;
    }

    if(setup.ob_isNonEmptyObject(V.pendingaddrelationships))
        delete V.pendingaddrelationships[name];
    if(setup.ob_isNonEmptyObject(V.pendingremoverelationships))
        delete V.pendingremoverelationships[name];

    if (relinfo.type == "crush")
    {
        V.lastcrush = V.gameday;
        V.crush = name;
    }

    if (!this.in_exclusive_relationship(name) || this.partner(name) != "PC")
    {
        this.clear_cheating_tracking(name);
    }

    return V.people[name];
}

setup.ob_relationships.unset = function(name, relationship, updateeventcounter = true)
{
    // generally you only want to call this for relationships where 'secondary' is true
    // though it attempts to handle unsetting primary relationships
    const relinfo = this.db[relationship];
    name = setup.people.get_name(name);
    let currel = V.people[name].relationship;

    if (currel == relationship)
    {
        if (this.db[currel].type == "romantic" && V.people[name].previousplatonicrelationship)
        {
            this.set(name, V.people[name].previousplatonicrelationship, false);
            delete V.people[name].previousplatonicrelationship;
            if (V.people[name].partner == "PC") delete V.people[name].partner;
        }
        else if (this.db[currel].type != "romantic" && V.people[name].previousrelationship && this.db[V.people[name].previousrelationship].type != "romantic")
        {
            this.set(name, V.people[name].previousrelationship, false);
        }
        V.people[name].previousrelationship = currel;
    }

    if (relinfo.type == "crush")
    {
        V.lastcrush = V.gameday;
        delete V.crush;
        delete V.crushconfessed;
    }

    if (updateeventcounter && currel && !this.db[currel].unilateralExit)
    {
        V.people[name].lastRelEvent = V.gameday;
        V.lastRelEvent = V.gameday;
    }

    if (!this.in_exclusive_relationship(name) || this.partner(name) != "PC")
    {
        this.clear_cheating_tracking(name);
    }

    V.people[name].relationshipChangeDay = V.gameday;

    return V.people[name];
}

setup.ob_relationships.set_acquaintance = function(name, updateeventcounter = true)
{
    // remove all relationship status, return to being just an acquaintance
    name = setup.people.get_name(name);
    let currel = V.people[name].relationship;

    if (currel)
    {
        const relinfo = this.db[currel];
        if (false && relinfo.type == "crush")
        {
            V.lastcrush = V.gameday;
            delete V.crush;
        }
    }

    delete V.people[name].relationship;
    delete V.people[name].previousrelationship;
    delete V.people[name].previousplatonicrelationship;
    if (V.people[name].partner == "PC")
    {
        delete V.people[name].partner;
        V.people[name].lastBreakup = V.gameday;
    }

    if (updateeventcounter)
    {
        V.people[name].lastRelEvent = V.gameday;
        V.lastRelEvent = V.gameday;
    }

    if(setup.ob_isNonEmptyObject(V.pendingaddrelationships))
        delete V.pendingaddrelationships[name];
    if(setup.ob_isNonEmptyObject(V.pendingremoverelationships))
        delete V.pendingremoverelationships[name];

    this.clear_cheating_tracking(name);

    return V.people[name];
}

setup.ob_relationships.reject_change = function(name, relationship, updateeventcounter = true)
