setup.ob_relationships.label = function(rel, partnername)
{
    const relinfo = this.db[rel];
    let label = relinfo.label;
    if (label[0] != "%")
    {
        return label;
    }
    else
    {
        label = label.substring(1);
        const pronouns = setup.people.pronouns(partnername);
        if (pronouns[label])
            return pronouns[label];
        else if (setup.ob_get_gender_node(pronouns.gender, label))
            return setup.ob_get_gender_node(pronouns.gender, label);
        else
            return label;
    }
}

setup.ob_relationships.dates = function(name)
{
