}

setup.ob_relationships.is_ex = function(name, type = "romantic")
{
    name = setup.people.get_name(name);
    const pdata = V.people[name];
    setup.ob_fixBadArray(pdata.allrelationships);
    if (!pdata.allrelationships || pdata.allrelationships.length == 0)
        return false;
    else
    {
        for (const rel of pdata.allrelationships)
            if (rel && rel != pdata.relationship && this.db[rel].type == type)
                return true;
        return false;
    }
}

setup.ob_relationships.is_recent_ex = function(name)
{
    const isex = this.is_ex(name);
    return isex && V.gameday - setup.people.get_person(name).breakupDay < 28;
}

setup.ob_relationships.convert_fuckbuddies_to_friends = function()
{
