    {
        if (this.relationship_with(name) == "fuckbuddy")
            this.set(name, "friend");
    }
}

setup.ob_relationships.valid_subrule = function(name, rule)
{
    const ruleinfo = this.subrules[rule];
    let testobj;
    if (V.pc.equals(name))
    {
        testobj = V.pc;
    }
    else
    {
        name = setup.people.get_name(name);
        testobj = new Person({person: name});
    }

    const currentrules = !V.pc.equals(name) ? this.get_subrules(name, "PC", false) : this.get_subrules(name);
    if (currentrules.includes(rule)) return false;
    if (!ruleinfo.flags.includes("for npc") && !testobj.is_pc) return false;
    if (!ruleinfo.flags.includes("for player") && testobj.is_pc) return false;
    if (ruleinfo.parts && !testobj.has_any_of_parts(ruleinfo.parts)) return false;
    if (ruleinfo.presentation && !ruleinfo.presentation.includes(setup.people.gender_presentation(name))) return false;
    if (ruleinfo.incompatible && currentrules.includesAny(ruleinfo.incompatible)) return false;

    testobj.enable_all_toys();
    if (rule == "chastity" && testobj.using_chastity_device()) return false;

    if (!V.pc.equals(name) && ruleinfo.skilltoadd)
    {
        for (const [skill, lvl] of Object.entries(ruleinfo.skilltoadd))
            if (!V.pc.skillleveled(skill, lvl)) return false;
    }

    if (V.pc.equals(name) && ruleinfo.skilltoreceive)
    {
        for (const [skill, lvl] of Object.entries(ruleinfo.skilltoreceive))
            if (!V.pc.skillleveled(skill, lvl)) return false;
    }

    return true;
}

setup.ob_relationships.possible_subrules = function(name)
{
    return Object.keys(this.subrules).filter(rule => this.valid_subrule(name, rule));
}

setup.ob_relationships.get_subrules = function(name, npc, considerbreak = true)
{
    // returns an array of rule strings
    // (only those set by the given npc, or all rules if no npc is provided)

    this.validate_subrules();
    name = setup.people.get_name(name);
    if (V.pc.equals(name))
    {
        let subrules = V.subrules || [];
        return subrules.filter(rule =>
            typeof rule == "string" ||
            !npc ||
            rule.issuer == setup.people.get_name(npc)
        ).map(rule => typeof rule == "string" ? rule : rule.rule);
    }
    else
    {
        let pdata = setup.people.get_person(name);
        if (pdata == null || (considerbreak && setup.ob_relationships.on_subrules_break(name)))
        {
            return [];
        }
        return pdata.subrules || [];
    }
}

setup.ob_relationships.add_subrule = function(name, rule, npc)
{
    // add a new rule
    // (if for the pc, and an npc is provided, then the rule will be an object with additional info)

    name = setup.people.get_name(name);
    if (V.pc.equals(name))
    {
        if (!V.subrules) V.subrules = [];
        let existing = this.get_subrules("PC");
        if (!existing.includes(rule))
        {
            if (npc)
            {
                rule = {rule: rule, issuer: setup.people.get_name(npc), issued: V.gameday};
            }
            V.subrules.push(rule);
        }
        return V.subrules;
    }
    else
    {
        let pdata = setup.people.get_person(name);
        if (!pdata.subrules) pdata.subrules = [];
        if (!pdata.subrules.includes(rule)) pdata.subrules.push(rule);
        return pdata.subrules;
    }
}

setup.ob_relationships.remove_subrule = function(name, rule)
{
    name = setup.people.get_name(name);
    if (V.pc.equals(name))
    {
        if (!V.subrules) V.subrules = [];
        for (let i = 0; i < V.subrules.length; i++)
        {
            if (V.subrules[i] == rule || (typeof V.subrules[i] == "object" && V.subrules[i].rule == rule))
            {
                V.subrules.deleteAt(i);
                break;
            }
        }
        return V.subrules;
    }
    else
    {
        let pdata = setup.people.get_person(name);
        if (!pdata.subrules) pdata.subrules = [];
        pdata.subrules.delete(rule);
        if (pdata.subrules.length > 0)
            return pdata.subrules;
        else
        {
            delete pdata.subrules;
            return [];
        }
    }
}

setup.ob_relationships.following_subrule = function(name, rule, allowweatherexception = true)
{
    if (typeof rule == "object")
        rule = rule.rule;

    const ruleinfo = this.subrules[rule];
    let testobj;
    if (V.pc.equals(name))
    {
        testobj = V.pc;
    }
    else
    {
        name = setup.people.get_name(name);
        testobj = setup.people.expand(name);
    }

    const weatherexception = allowweatherexception && V.opttemperatureeffects && setup.ob_weather_is_cold(); // whether weather is a factor in dress code compliance

    switch (rule)
    {
        case "wear collar":
        {
            return testobj.get_occupying_clothing_flags("neck").includes("collar");
        }
        case "no bra":
        {
            return !testobj.wearing_bra() || testobj.wearing_swimwear_top() || !testobj.is_bra_exhibitionist();
        }
        case "no underwear":
        {
            return !testobj.wearing_underwear() || (testobj.outermost_covering("crotch").equals(testobj.underwear_covering("crotch")) && !testobj.is_underwear_underwear());
        }
        case "show belly":
        {
            return weatherexception || testobj.is_part_visible("stomach");
        }
        case "only skirt":
        {
            return weatherexception || testobj.under_access();
        }
        case "skintight top":
        {
            if (weatherexception)
                return true;
            else if (!testobj.is_part_covered("chest"))
                return true;
            else
                return setup.ob_outfit_has_skintight_top(testobj.clothes);
        }
        case "skintight pants":
        {
            if (weatherexception)
                return true;
            else if (!testobj.is_part_covered("crotch"))
                return true;
            else
                return setup.ob_outfit_has_skintight_pants(testobj.clothes);
        }
        case "chastity":
        {
            testobj.enable_all_toys();
            return testobj.using_chastity_device();
        }
        case "enough sleep":
        {
            // todo: make this kind of thing work for NPCs
            return !testobj.is_pc || (V.hour < 12 && setup.ob_needs.get_need("Rest") >= 700) || (V.hour >= 12 && setup.ob_needs.get_need("Rest") >= 400);
        }
        case "enough to eat":
        {
            return !testobj.is_pc || setup.ob_needs.get_need("Food") >= 500;
        }
        case "good hygiene":
        {
            return !testobj.is_pc || setup.ob_needs.get_need("Hygiene") >= 250 || testobj.has_inclination("Natural Odor");
        }
        case "shaved pubes":
        {
            return ["shaved", "stubble"].includes(testobj.pubic_style);
        }
    }
}

setup.ob_relationships.subrule_compliance = function(name, npc)
{
    let rules = this.get_subrules(name, npc);
    const following = [], broken = [];
    for (let rule of rules)
        if (this.following_subrule(name, rule))
            following.push(rule);
        else
            broken.push(rule);

    return [following, broken];
}

setup.ob_relationships.is_sub = function(name)
{
    // is this NPC the player's submissive?
    return this.relationship_with(name) == "submissive";
    return this.relationship_with(name) == "submissive" || (!this.is_dom(name) && this.relationship_type_with(name) == "romantic" && setup.people.has_any_inclination(name, "submissive") && setup.people.get_attitude(name, "control") <= -100);
}

setup.ob_relationships.is_dom = function(name)
{
    // is this NPC the player's dominant?
    return this.relationship_with(name) == "dominant";
}

setup.ob_relationships.has_dom = function()
{
    for (let p of Object.keys(V.people))
        if (this.is_dom(p)) return true;
    return false;
}

setup.ob_relationships.has_sub = function()
{
    for (let p of Object.keys(V.people))
        if (this.is_sub(p)) return true;
    return false;
}

setup.ob_relationships.can_adjust_subrules = function(name)
{
    // can we adjust this NPC's sub rules?
    return this.is_sub(name) && (this.get_subrules(name).length > 0 || this.possible_subrules(name).length > 0);
}

setup.ob_relationships.outstanding_player_subrules = function(name)
{
    // are there any rules that an NPC dom can set for the PC?
    this.validate_subrules();
    return (!name || this.is_dom(name)) && this.possible_subrules(V.pc).length > 0 && (!V.lastsubruleschange || V.gameday - V.lastsubruleschange > 7) && (!V.pendingrules || !V.pendingrules["PC"]);
}

setup.ob_relationships.undiscussed_confirmed_cheating = function(name)
{
    const retval = [];
    const pdata = setup.people.get_person(name);
    if (!pdata.cheatingconfirmed)
        return retval;
    else
    {
        for (const [otherperson, chdata] of Object.entries(pdata.cheatingconfirmed))
            if (!chdata.discussed)
                retval.push(otherperson);
    }
    return retval;
}

setup.ob_relationships.most_suspicious_cheating = function(name, includediscussed = false, threshold = 0)
{
    const pdata = setup.people.get_person(name);
    if (!pdata.cheatingsusof)
        return null;
    let highest = null;
    let highestamt = -1;
    for (const [otherperson, susinfo] of Object.entries(pdata.cheatingsusof))
        if (susinfo.amount >= highestamt && (includediscussed || !susinfo.discussed) && susinfo.amount > threshold)
        {
            highestamt = susinfo.amount;
            highest = otherperson;
        }
    return highest;
}

setup.ob_relationships.partner_wants_to_discuss_cheating = function()
{
    if (V.optfreezeremrels) return false;
    let partner = this.partner("PC");
    if (partner)
    {
        return setup.ob_relationships.undiscussed_confirmed_cheating(partner).length > 0 || setup.ob_relationships.most_suspicious_cheating(partner, false, 500);
    }
    return false;
}

setup.ob_relationships.clear_cheating_tracking = function(name)
{
    let pdata = setup.people.get_person(name);
    delete pdata.cheatingconfirmed;
    delete pdata.cheatingsusof;
    delete pdata.caughtyoucheating;
}

setup.ob_relationships.favorite_date = function(name)
{
    let rng = setup.ob_newRNG(setup.people.get_name(name));

    if (setup.people.has_any_inclination(name, "shy"))
        if (rng.random() < 0.4 && setup.people.get_type(name) == "student" && setup.people.skill_level(name, "Intellectual") >= 5)
            return "study together";
        else if (rng.random() < 0.2 && setup.people.get_type(name) == "student")
            return "have a park picnic";
        else
            return "just chill";
    else if (setup.people.has_any_inclination(name, "slut"))
        return "booty call";
    else if (setup.people.has_any_inclination(name, "casualsex") && rng.random() < 0.3)
        return "booty call";

    const arch = setup.people.archetype(name);
    if (arch && setup.ob_archetypes[arch] && setup.ob_archetypes[arch].favoriteDate)
    {
        return rng.randomrelfreq(setup.ob_archetypes[arch].favoriteDate);
    }
    else
    {
        if (setup.people.skill_level(name, "Intellectual") > 5)
            if (rng.random() < 0.5 && setup.people.get_type(name) == "student")
                return rng.randomrelfreq(["study together", 100, "go to the planetarium", 70, "see a movie", 100]);
            else
                return rng.randomrelfreq(["go to the planetarium", 30, "see a movie", 100]);
        else if (setup.people.skill_level(name, "Physical") > 5 && setup.people.get_type(name) == "student")
            return "hit the gym";
        else if (setup.people.skill_level(name, "Video Gaming") > 5)
            return "hit the arcade";
        else if (rng.random() < 0.5)
            return "see a movie";
        else
            return "have dinner";
    }
}

setup.ob_relationships.add_friends_today = function()
{
    // given the way these systems interact, the relationship pipeline tends to get clogged with new friends
    // so this algorithm will give it some room to flow
    const friendsn = setup.people.all_friends().length;
    const day = V.gameday;
    if (friendsn < 3)
        return true;
    else if (friendsn < 6)
        return day % 2 == 0;
    else if (friendsn < 9)
        return day % 3 == 0;
    else
        return day % 4 == 0;
}

