setup.ob_relationships.milestone_available = function(name, milestone)
{
    const minfo = setup.ob_relationships.milestones[milestone];
    T.milestonetarget = setup.people.get_name(name);
    return setup.ob_evaluate(minfo.availableif);
}

setup.ob_relationships.milestone_reached = function(name, milestone)
{
    const minfo = setup.ob_relationships.milestones[milestone];
    T.milestonetarget = setup.people.get_name(name);
    return setup.ob_evaluate(minfo.metif);
}

setup.ob_relationships.reached_milestones = function(name)
{
    let retval = [];

    for (let milestone of Object.keys(this.milestones))
        if (this.milestone_available(name, milestone) && this.milestone_reached(name, milestone))
            retval.push(milestone);

    return retval;
}

setup.ob_relationships.possible_milestones = function(name)
{
    let retval = [];

    for (let milestone of Object.keys(this.milestones))
        if (this.milestone_available(name, milestone))
            retval.push(milestone);

    return retval;
}

setup.ob_relationships.milestone_count = function(name)
{
    return this.reached_milestones(name).length;
}

setup.ob_relationships.max_romance = function(name)
{
    if (!V.optdatesim || this.ignoring_datesim(name))
        return 1000;
    else
    {
        let count = this.milestone_count(name);
        switch (count)
        {
            case 0:
                return 100;
            case 1:
                return 200;
            case 2:
                return 400;
            case 3:
                return 600;
            case 4:
                return 800;
            case 5:
                return 999;
            default:
                return 1000;
        }
    }
}

setup.ob_relationships.check_milestones = function(name, silent = false)
{
    let pinfo = setup.people.get_person(name);
    let mknown = pinfo.milestones || [];

    const achieved = this.reached_milestones(name);
    if (achieved.length == 0) return;

    for (let milestone of achieved)
    {
        if (!mknown.includes(milestone))
        {
            let label = setup.ob_pronoun_sub(name, this.milestones[milestone].label);
            let dname = setup.people.is_known(name) ? setup.people.get_display_name(name) : setup.people.anonymous_name(name);

            if (this.show_dating_milestones(name) && !silent)
            {
                /*let msg = `Romance milestone achieved with ${dname}: <<highlight romantic>>${label}<</highlight>>!`;
                setup.add_notification(msg); */
                setup.ob_add_catnotification("milestone", dname, label);


                let amt = mknown.length == 0 ? 25 : 50;
                setup.people.alter_attitude(name, "romance", amt);
            }

            mknown.push(milestone);
        }
    }

    if (mknown.length > 0)
        pinfo.milestones = mknown;
}

setup.ob_relationships.show_dating_milestones = function(name)
{
    if (!V.optdatesim || setup.ob_relationships.ignoring_datesim(name)) return false;
    return ["student", "townie", "faculty"].includes(setup.people.get_type(name)) && setup.people.attracted_to_pc(name) && (setup.ob_relationships.dates(name) > 0 || setup.people.get_attitude(name, "romance") >= 100);
}

