setup.ob_relationships.breakup = function(name)
{
    // for breaking up two (or more) NPCs
    // for the PC, there's the <<breakup>> widget and that's all we need (so far)

    name = setup.people.get_name(name);

    let pdata = setup.people.get_person(name);

    delete pdata.partner;
    delete pdata.partnerType;

    pdata.lastBreakup = V.gameday;

    for (let [p, pdata2] of Object.entries(V.people))
        if (pdata2.partner == name)
        {
            delete pdata2.partner;
            delete pdata2.partnerType;
            pdata2.lastBreakup = V.gameday;
        }
}

setup.ob_relationships.breakup_friendship = function(name)
{
    // for the PC ending a friendship with an NPC

    name = setup.people.get_name(name);

    let pdata = setup.people.get_person(name);
    pdata.exfriendship = true;
}

setup.ob_relationships.scan_for_invalid = function()
{
    // look for NPCs who are (literally) decoupled from each other
    // not sure what the ultimate cause of this is, but this will clean it up somewhat

    for (let [p, pdata] of Object.entries(V.people))
    {
        let partner = pdata.partner;
        if (partner && !V.pc.equals(partner))
        {
            let pdata2 = V.people[partner];
            if (!pdata2 || !pdata2.partner)
            {   // found a mismatch
                console.warn(`relationship mismatch cleared: ${p} partnered to ${partner} who does not reciprocate`);
                delete pdata.partner;
                delete pdata.partnerType;
            }
        }
    }
}

setup.ob_relationships.need_to_sneak = function(npc)
{
    // if dating this npc should be a secret
    return setup.ob_relationships.npc_is_cheating(npc) || (setup.people.is_professor(npc) && setup.people.professor_reaction(npc) == "Married Professor") || setup.ob_relationships.is_cheating(npc) || setup.people.get_type(npc) == "faculty";
}

setup.ob_relationships.relationship_suspicion = function(npc)
{
    let name = setup.people.get_name(npc);
    if (!V.secretrelationships || !V.secretrelationships[name])
        return 0;
    else
        return V.secretrelationships[name].suspicion;
}

setup.ob_relationships.add_relationship_suspicion = function(npc, amt = 250)
{
    let name = setup.people.get_name(npc);
    if (!V.secretrelationships) V.secretrelationships = {};
    if (!V.secretrelationships[name]) V.secretrelationships[name] = {
        suspicion: 0,
        lastsuspicion: 0,
        exposed: false,
    };

    V.secretrelationships[name].suspicion = Math.clamp(V.secretrelationships[name].suspicion + amt, 0, 1000);
    V.secretrelationships[name].lastchange = V.gameday;

    return V.secretrelationships[name];
}

setup.ob_relationships.decay_relationship_suspicion = function()
{
    if (!V.secretrelationships) return;
    for (let [name, info] of Object.entries(V.secretrelationships))
    {
        if (V.gameday - info.lastchange >= 2)
        {
            info.suspicion -= 100;
            info.suspicion = Math.clamp(info.suspicion, 0, 1000);
            info.lastsuspicion = info.suspicion;
            if (info.suspicion <= 0) info.exposed = false;
        }
    }
}

setup.ob_relationships.maybe_expose_secret_relationships = function()
{
    if (!V.secretrelationships) return;
    for (let [name, info] of Object.entries(V.secretrelationships))
    {
        if (!info.exposed && info.suspicion >= 1000)
        {
            info.exposed = true;
            if (setup.people.is_faculty(name))
            {
                // todo: consequences for secretly dating faculty

            }
            if (setup.ob_relationships.is_cheating(name))
            {
                // consequences for cheating
                for (let partner of setup.ob_relationships.all_partners())
                {
                    if (partner == name) continue;
                    let pdata = setup.people.get_person(partner);
                    if (!pdata.cheatingconfirmed)
                        pdata.cheatingconfirmed = {};

                    pdata.cheatingconfirmed[name] = {day: V.gameday};

                    if (pdata.cheatingsusof && pdata.cheatingsusof[name])
                        delete pdata.cheatingsusof[name];
                }
            }
        }
    }
}

setup.ob_relationships.react_to_activity_proposal = function(npc, type="hangout", activity=null, day=null)
{
    // looks up some reasons not to date or hang out with a person in a specific instance
    // (not to be confused with whether we'll date a person at all, though it can handle a bit of that in Step One, but must remain consistent with setup.people.willing_date)
    let name = setup.people.get_name(npc);
    if (!activity)
    {
        // step one: no activity proposed yet, just asking for date/hangout in general
        if (setup.people.is_professor(npc) || setup.people.is_coach(npc))
        {
            if (setup.people.professor_intimacy(npc) >= 2)
                return [true];
            else if (setup.people.professor_intimacy(npc) >= 1)
                return [false, "I don't think that would be a good idea..."]
            else
                return [false, "That wouldn't be appropriate"];
        }
        else if (setup.people.is_faculty(npc))
        {
            return [false, "That wouldn't be appropriate"];
        }
        else if (!setup.people.willing_date(npc) && !setup.people.reputation_mismatch(npc)[0])
        {
            let repcheck = setup.people.reputation_mismatch(npc);
            return [false, "I don't think so... " + repcheck[1]];
        }
        else
        {
            return [true];
        }
    }
    else if (!day)
    {
        // step two: activity proposed
        if (activity.public && this.need_to_sneak(npc) && this.relationship_suspicion(npc) >= 1000)
        {
            return [false, "I don't know, I feel like we'll be found out... I think I'll have to pass"];
        }
        else
        {
            return [true];
        }
    }
    else
    {
        // step three: day proposed
        let partner = setup.ob_relationships.partner(name) == "PC";
        if (day == V.gameday)
        {
            if (V.busytoday && V.busytoday.includes(name))
                return [false, "Like I said, I'm busy today, sorry"];
            else
            {
                if (((!partner && State.random() < 0.5) || (partner && State.random() < 0.1)) && (!V.busytoday || V.busytoday.length < 3))
                {
                    if (!V.busytoday) V.busytoday = [];
                    V.busytoday.push(name);
                    return [false, "Ah, sorry, I'm busy today"];
                }
                else
                    return [true];
            }
        }
        else
        {
            return [true];
        }
    }
}

setup.ob_relationships.implied_sexual_relationship = function(npc)
{
    // whether we're in a romantic relationship or fuckbuddies or hatefucks...
    return this.relationship_type_with(npc) == "romantic" || ["fuckbuddy", "hatefuck"].includes(this.relationship_with(npc));
}

setup.ob_relationships.in_positive_relationship = function(npc)
{
    // whether we're friends, dating
    return ["friendship", "romantic"].includes(this.relationship_type_with(npc));
}

setup.ob_relationships.in_negative_relationship = function(npc)
{
    // whether we have an established hatred
    return ["enemy"].includes(this.relationship_type_with(npc));
}

setup.ob_relationships.hookup_disinhibition = function(npc, pcinitiated = false)
{
    // what disinhib level should be required for a casual hookup with this person?

    let desrel = setup.people.desired_relationship(npc);
    let baselevel = 1;
    if (this.relationship_type_with(npc) == "romantic")
        baselevel = 1;
    else if (this.relationship_type_with(npc) == "friendship")
        baselevel = 2;
    else if (desrel == "hatefuck" || desrel == "rival")
        baselevel = 4;
    else if (desrel == "indifferent")
        baselevel = 3;
    else
        baselevel = 2;

    if (pcinitiated)
        baselevel++;

    if (V.pchorny)
        baselevel -= V.pchorny;
    else if (V.pc.drunkenness() >= 300)
        baselevel--;

    return Math.clamp(baselevel ?? 10, 1, 10);
}

setup.ob_relationships.validate_subrules = function()
{
    // remove subrules issued by NPCs who are no longer the PC's dominant

    if (!V.subrules) return;

    let doms = this.all_partners("PC").filter(npc => this.relationship_with(npc) == "dominant");

    V.subrules = V.subrules.filter(rule => !rule.issuer || doms.includes(rule.issuer));

    return V.subrules;
}

setup.ob_relationships.all_rule_issuers = function()
{
    // find all doms who have rules they'd want to inspect for

    if (!V.subrules) return [];

    if (V.subrulesbreak)
        for (let [ruleissuer, breakuntil] of Object.entries(V.subrulesbreak))
            if (V.gameday >= breakuntil)
                delete V.subrulesbreak[ruleissuer];

    let breakfrom = V.subrulesbreak ? Object.keys(V.subrulesbreak) : [];

    let doms = this.all_partners("PC").filter(npc =>
        !breakfrom.includes(npc) &&
        this.relationship_with(npc) == "dominant" &&
        V.subrules.some(rule => !rule.issuer || rule.issuer == npc)
    );

    return doms;
}

setup.ob_relationships.on_subrules_break = function(npc)
{
    // whether this NPC (the PC's sub) has been granted a break from following the PC's rules
    let pdata = setup.people.get_person(npc);
    if (!pdata.subrulesbreak) return false;
    if (V.gameday >= pdata.subrulesbreak)
    {
        delete pdata.subrulesbreak;
        return false;
    }
    return true;
}

setup.ob_relationships.get_id = function(rel)
{
    // take relationship string, return id
    return this.db[rel].id;
}

setup.ob_relationships.from_id = function(id)
{
    // take numerical id, return relationship
    return Object.keys(this.db).filter(rel => this.db[rel].id == id)[0];
}

setup.ob_relationships.fraction_partnered = function(type = "student")
{
    // how many NPCs of this type have a partner, 0-1
    let all = Object.keys(V.people).filter(p => setup.people.get_type(p) == type);
    let withpartners = all.filter(p => this.partner(p));
    return withpartners.length / all.length;
}

setup.ob_relationships.has_dominant_partner = function(person, includepc = false)
{
    // whether this person has a dominant partner
    let partner = this.partner(person);
    if (!partner) return false;
    if (!includepc && partner == "PC") return false;
    return setup.people.has_any_inclination(partner, "just_dominant");
}

setup.ob_relationships.has_submissive_partner = function(person, includepc = false)
{
    // whether this person has a submissive partner
    let partner = this.partner(person);
    if (!partner) return false;
    if (!includepc && partner == "PC") return false;
    return setup.people.has_any_inclination(partner, "just_submissive");
}

setup.ob_relationships.is_married = function(person)
{
    // whether this person is married
    let pdata = setup.people.get_person(person);
    return pdata.partnerType == "spouse";
}

setup.ob_relationships.cheating_partner = function(person)
{
    // retrieve this person's cheating partner (aka side piece)
    if (V.pc.equals(person))
        return V.cheatingPartner;
    else
    {
        const pdata = setup.people.get_person(person);
        return pdata.cheatingPartner;
    }
}

setup.ob_relationships.set_cheating_partner = function(person, partner, twoway = true)
{
    // save a new cheating partner
    if (V.pc.equals(person))
        V.cheatingPartner = setup.people.get_name(partner);
    else
    {
        let pdata = setup.people.get_person(person);
        pdata.cheatingPartner = setup.people.get_name(partner);

        if (twoway && setup.ob_relationships.in_exclusive_relationship(partner))
            this.set_cheating_partner(partner, person);
    }
}

setup.ob_relationships.unset_cheating_partner = function(person)
{
    // remove cheating partner (either because they fell out or are in an official relationship now)
    let partner;
    if (V.pc?.equals(person))
    {
        partner = V.cheatingPartner;
        delete V.cheatingPartner;
    }
    else
    {
        let pdata = setup.people.get_person(person);
        partner = pdata.cheatingPartner;
        delete pdata.cheatingPartner;
    }

    if (partner && this.cheating_partner(partner) == setup.people.get_name(person))
        this.unset_cheating_partner(person);
}

setup.ob_relationships.can_gift_collar = function(npc)
{
    // check a bunch of things to see whether we can gift an npc a collar and also give them the 'wear collar' subrule
    return this.relationship_with(npc) == "submissive" && setup.ob_gifts.giftable_collars().length > 0 && !this.get_subrules(npc).includes("wear collar") && !setup.people.collar(npc);
}

setup.ob_relationships.days_since_breakup = function(npc)
{
    // days since this npc last lost a romantic partner

    let pdata = setup.people.get_person(npc);

    // some legacy stuff happening here... breakupDay is from PC/NPC relationships, lastBreakup is from any relationship
    let breakup;
    if (pdata.lastBreakup && pdata.breakupDay)
        breakup = Math.max(pdata.lastBreakup, pdata.breakupDay);
    else
        breakup = pdata.lastBreakup || pdata.breakupDay;

    if (!breakup) return -1;
    else return V.gameday - breakup;
}

setup.ob_relationships.had_recent_breakup = function(npc)
{
    // have we had a breakup within the last two weeks?
    let dayssincebreakup = this.days_since_breakup(npc);
    if (dayssincebreakup == -1) return false;
    else return dayssincebreakup <= 14;
}

setup.ob_relationships.sad_about_recent_breakup = function(npc)
{
    // are we sad about our recent breakup? (yes unless we have a new relationship)
    if (!this.had_recent_breakup(npc))
        return false;
    else
        return !setup.ob_nPCSimulation.has_relationship_type(npc, ["partner", "open partner", "poly partner", "soulmate", "dominant", "submissive"]);
}

setup.ob_relationships.pc_witness_partner_cheating = function(partner, other)
{
    // record an instance of the player witnessing or discovering their partner is cheating

    let day = V.gameday;

    let pdata = setup.people.get_person(partner);
    if (!pdata.PCWitnessedCheating)
        pdata.PCWitnessedCheating = {};

    let otherid = setup.people.get_name(other);

    if (!pdata.PCWitnessedCheating[otherid])
        pdata.PCWitnessedCheating[otherid] = {count: 1, lastDay: day};
    else
    {
        pdata.PCWitnessedCheating[otherid].count++;
        pdata.PCWitnessedCheating[otherid].lastDay = day;
    }
}

setup.ob_relationships.has_pc_witnessed_cheating = function(partner)
{
    let pdata = setup.people.get_person(partner);
    if (!pdata.PCWitnessedCheating) return false;
    return Object.keys(pdata.PCWitnessedCheating).length > 0;
}

setup.ob_relationships.has_pc_witnessed_cheating_with = function(partner, other)
{
    other = setup.people.get_name(other);
    let pdata = setup.people.get_person(partner);
    if (!pdata.PCWitnessedCheating) return false;
    return pdata.PCWitnessedCheating[other]?.count > 0;
}

setup.ob_relationships.has_pc_witnessed_recent_cheating = function(partner, excludediscussed = true)
{
    let pdata = setup.people.get_person(partner);
    if (!pdata.PCWitnessedCheating) return false;
    return Object.values(pdata.PCWitnessedCheating).some(value => V.gameday - value.lastDay <= 14 && (!excludediscussed || !value.discussed));
}

setup.ob_relationships.pc_witnessed_cheating_with = function(partner, excludediscussed = true)
{
    let pdata = setup.people.get_person(partner);
    if (!pdata.PCWitnessedCheating) return [];
    return Object.keys(pdata.PCWitnessedCheating).filter(key => { let value = pdata.PCWitnessedCheating[key]; return !excludediscussed || !value.discussed });
}

setup.ob_relationships.pc_witnessed_cheatinf_discussed = function(partner)
{
    let pdata = setup.people.get_person(partner);
    if (!pdata.PCWitnessedCheating) return;
    Object.keys(pdata.PCWitnessedCheating).forEach(key => pdata.PCWitnessedCheating[key].discussed = true);
}

setup.ob_relationships.relationship_age = function(partner)
{
    // return the age of the PC's current relationship with the given NPC

    const pdata = setup.people.get_person(partner);

    if (V.pc.equals(pdata.partner))
    {
        if (!pdata.partneredday)
            return 0;
        else
            return V.gameday - pdata.partneredday;
    }
    else if (!pdata.relationshipChangeDay)
        return 0;
    else
        return V.gameday - pdata.relationshipChangeDay;
}
