setup.ob_revive_class = function(this_class, config)
{
    let debuggen = false;
    if (debuggen) console.warn("Reviving class: ",this_class.constructor.name);
    if (debuggen) console.log(config);
    for (const [key, value] of Object.entries(config))
    {
        var handled = false
        var tmp = value
        let faked_array = false;
        if (Array.isArray(tmp) && tmp[0] == "(revive:eval)")
        {
            // Push it into an array in order to allow common logic
            tmp = [tmp]
            faked_array = true;
        }
        if (Array.isArray(tmp))
        {
            var result = []
            for (var idx in tmp)
            {
                if (Array.isArray(tmp[idx]) && tmp[idx][0] == "(revive:eval)")
                {

                    try
                    {
                        if (debuggen) console.log("Reviving ",key,tmp[idx])
                        if (Array.isArray(tmp[idx][1]))
                        {
                            const $ReviveData$ = tmp[idx][1][1]
                            result[idx] = eval(tmp[idx][1][0])
                            handled = true;
                        }
                        else
                        {
                            result[idx] = eval(tmp[idx][1])
                            handled = true;
                        }
                    }
                    catch (ex)
                    {
                        console.error("Failed to revive ",key, tmp[idx], ex)
                    }
                }
            }
            if (handled)
            {
                if (faked_array && tmp.length == 1)
                {
                    this_class[key] = result[0]
                }
                else
                {
                    this_class[key] = result
                }
            }
        }
        if (!handled)
        {
            this_class[key] = clone(value)
        }
    }
    if (debuggen) console.warn("Revived class: ",this_class.constructor.name)
}

setup.ob_store_class = function(this_class, class_path="")
{
    //console.warn("Storing Class: ",this_class.constructor.name)
    // Return a code string that will create a new instance containing our
	// own data.
    let debuggen = false;
    if (debuggen) console.warn("Storing class: ",this_class.constructor.name)
    var result;
	var ownData = {};
	Object.keys(this_class).forEach(function (pn) {
        // ignore values that are indicated as a 'cache', they don't get saved.
        if (pn.indexOf("_cache") == -1)
        {
		    ownData[pn] = clone(this_class[pn]);
        }
	    }, this_class);
    if (class_path.length > 0 && class_path.slice(-1) != ".")
    {
        // add the period if it is missing
        class_path += ".";
    }
    result = JSON.reviveWrapper('new '+class_path+this_class.constructor.name+'($ReviveData$)', ownData);
    if (debuggen) console.warn("Stored class: ",this_class.constructor.name,result);
	return result;
}

setup.ob_check_revive = function(check_this)
{
    var result = check_this;
    if (Array.isArray(check_this) && check_this[0] == "(revive:eval)")
    {
        try
        {
            const $ReviveData$ = check_this[1][1]
            result = eval(result[1][0])
        }
        catch (ex)
        {
            console.error("Failed to revive: ",check_this);
        }
    }
    return result;
}

setup.ob_remove_failed_revives = function(revives)
{
    if (!Array.isArray(revives)) return revives;
    const remove = [];
    for (let item of revives)
    {
        if (Array.isArray(item) && item[0] == "(revive:eval)")
        {
            console.error("Failed revive removed: " + item[1]);
            remove.push(item);
        }
    }
    for (let item of remove)
        revives = revives.delete(item);
    return revives;
}
