Save.onLoad.add(function (save) {
	/* code to process the save object before it's loaded */

	let crosssaveoptions = recall("crosssaveoptions");
	let importcrossdata = crosssaveoptions?.optimportcrossdata ?? true;

	if (save.state.history && save.state.history.length > 0)
	{
		// apply saved color options if they exist
		let vars = save.state.history[save.state.history.length - 1].variables;
		if (vars.coloroptions)
		{
			memorize("coloroptions", vars.coloroptions);
		}

		// restore history length
		Config.history.maxStates = Math.min(vars.opthistorylength || 5, !idb.active ? 5 : 40);
	}

	if (importcrossdata && Array.isArray(save.crosssavebooks))
	{
		// merge in books coming with the save
        const existing = recall("crosssavebooks") || [];
        const merged = [...existing];

        // add books that don't already exist
        for (const newbook of save.crosssavebooks)
            if (!existing.some(book => book.name == newbook.name))
                merged.push(newbook);

        memorize("crosssavebooks", merged);
    }

	setup.ob_close_dialog();

});

