function add_used_storage_locations(history_frames) {
	const unique_locations = new Set();
	const storageLocationsZero = history_frames[0].variables?.pc?.storage_locations;
	if (!storageLocationsZero) return;

	for (let frame = 1; frame < history_frames.length; frame++) {
		const storageLocations = history_frames[frame].variables.pc.storage_locations;
		if (storageLocations && typeof storageLocations === 'object') {
			Object.keys(storageLocations).forEach(key => unique_locations.add(key));
		}
	}

	unique_locations.forEach(location => {
		if (!storageLocationsZero.hasOwnProperty(location)) {
			console.log(`Adding to Save frame 0 storage location: ${location}`);
			storageLocationsZero[location] = new ClothingGroup();
		}
	});
}

