setup.ob_import_player = function(plr, target = V.pc)
{
	let exported = setup.ob_get_exported_characters();
	if (!(plr in exported))
		return false;
	else
	{
		V.pcnickname = "";

		for (let key of Object.keys(exported[plr]))
		{
			if (key.indexOf("V.") == 0)
			{
				let tkey = key.substring(2);
				V[tkey] = exported[plr][key];
			}
			else if (target)
			{
				target[key] = exported[plr][key];
			}
		}

		if (target)
		{
			delete target.nickname;
			const pronouns = setup.people.pronouns(exported[plr]["pronouns"]);
			const ignorepronouns = ["expression", "partner", "spouse", "gender", "sex"];
			for (let key of Object.keys(pronouns))
				if (!ignorepronouns.includes(key))
					target[key] = pronouns[key];
		}

		if (V.pccustomgenderinfo)
		{
			setup.ob_add_custom_gender(...V.pccustomgenderinfo);
			setup.ob_gender_db().custom["roommate genders"] = setup.ob_get_gender_node(setup.ob_pcgender(), "roommate genders");
		}

		return true;
	}
}

