setup.School.find_grade = function(score)
{
    for (const [grade, info] of Object.entries(this.grades))
    {
        if (score >= info.minscore) return grade;
    }
    return "F";
}

setup.School.find_gpa = function(score)
{
    let grade = this.find_grade(score);
    return this.grades[grade].gpa;
}

setup.School.courses_for_major = function(major, year)
{
    const retval = [];
    for (const [course, cinfo] of Object.entries(this.courses))
    {
        if (major == cinfo.major && (!year || cinfo.year == year))
        {
            retval.push(course);
        }
    }
    return retval;
}

setup.School.courses_for_block = function(block, year)
{
    const retval = [];
    for (const [course, cinfo] of Object.entries(this.courses))
    {
        if (block == cinfo.schedule && (!year || cinfo.year == year))
        {
            retval.push(course);
        }
    }
    return retval;
}

setup.School.find_course = function(major, block, year)
{
    const courses = this.courses_for_major(major);
    for (let i = 0; i < courses.length; i++)
    {
        if (this.courses[courses[i]].schedule == block && (!year || this.courses[courses[i]].year == year))
            return courses[i];
    }
    return null;
}

setup.School.available_courses = function(major = null, block = null, year)
{
    const retval = [];
    for (const [course, cinfo] of Object.entries(this.courses))
    {
        if (setup.ob_enrolled(course).length < cinfo.seats && (block == null || block == cinfo.schedule) && (major == null || major == cinfo.major) && (!year || cinfo.year == year))
        {
            retval.push(course);
        }
    }
    return retval;
}

setup.School.classes_today = function(day = V.day, month = V.month)
{
    let weekday = setup.ob_time.weekday(day);

    if (weekday == "Sunday" || weekday == "Saturday")
    {
        return false;
    }
    else if (setup.ob_time.seasons[month] == "summer")
    {
        return false;
    }
    else if (this.current_holiday(day, month) != null)
    {
        return false;
    }
    else
    {
        return true;
    }
}

setup.School.classes_tomorrow = function(day = V.day, month = V.month)
{
    day = day + 1;
    if (day > 28)
    {
        month = month + 1;
        day = 1;
        if (month >= setup.ob_time.months.length)
            month = 0;
    }
    let weekday = setup.ob_time.weekday(day);

    if (weekday == "Sunday" || weekday == "Saturday")
    {
        return false;
    }
    else if (setup.ob_time.seasons[month] == "summer")
    {
        return false;
    }
    else if (this.current_holiday(day, month) != null)
    {
        return false;
    }
    else
    {
        return true;
    }
}

setup.School.is_class_today = function(course)
{
