{
    if (!this.classes_today()) return [];

    return Object.keys(this.courses).filter(item => this.is_class_today(item));
}

setup.School.current_holiday = function(day = V.day, month = V.month)
{
    const holidays = Object.keys(setup.School.holidays);
    for (let i = 0; i < holidays.length; i++)
        if (this.is_within_holiday(holidays[i], day, month))
            return holidays[i];

    return null;
}

setup.School.current_eventday = function(day = V.day, month = V.month)
{
    for (const [event, eventinfo] of Object.entries(setup.School.eventdays))
        if (day == eventinfo.day && month == setup.ob_time.months.indexOf(eventinfo.month))
            return event;
}

setup.School.is_within_holiday = function(holiday, day = V.day, month = V.month)
{
    let holidayinfo = setup.School.holidays[holiday];
    let startmonth = setup.ob_time.months.indexOf(holidayinfo.start.month);
    let startday = holidayinfo.start.day;
    let endmonth = setup.ob_time.months.indexOf(holidayinfo.end.month);
    let endday = holidayinfo.end.day;

    let countdays = (m, d) => m * setup.ob_time.month_length + d;
    let current = countdays(month, day);
    return current >= countdays(startmonth, startday) && current <= countdays(endmonth, endday);
}

setup.School.is_current_or_upcoming_holiday = function()
{
    if (this.current_holiday()) return true;

    let day = V.day + 7;
    let month = V.month;
    if (day > 28)
    {
        day -= 28;
        month++;

        if (month >= setup.ob_time.months.length)
            month = 0;
    }

    if (this.current_holiday(day, month)) return true;
    else return false;
}

setup.School.last_bell = function(day = V.day)
{
    return setup.ob_time.weekday(day) == "Friday" ? 15 : 17;
}

setup.School.course_for_year = function(major, year, block)
{
    for (let [course, courseinfo] of Object.entries(setup.School.courses))
        if (courseinfo.major == major && courseinfo.year == year && courseinfo.schedule == block)
            return course;
}

setup.School.get_course_attribute = function(course, att)
{
    let courseinfo = setup.School.courses[course];
    if (!(att in courseinfo))
    {
        let basecourse = this.course_for_year(courseinfo.major, 1, courseinfo.schedule)
        return setup.School.courses[basecourse][att];
    }
    else
        return courseinfo[att];
}

setup.School.next_class = function(hour = V.hour, day = V.day, month = V.month, blocks = Object.keys(setup.School.blocks))
{
    while (!setup.School.classes_today(day, month) || hour >= this.last_bell(day))
    {
        day++;
        hour = 0;
        if (day > setup.ob_time.month_length)
        {
            day -= setup.ob_time.month_length;
            month++;
            if (month >= setup.ob_time.months.length) month -= setup.ob_time.months.length;
            while (setup.ob_time.seasons[month] == "summer")
            {
                month++; // the above code would get here anyway but we'll save ourselves a bunch of pointless iterating through days
                if (month >= setup.ob_time.months.length) month -= setup.ob_time.months.length;
            }
        }
    }

    let weekday = setup.ob_time.weekday(day);

    let nextblock = null;
    let minhour = 24;

    let myblocks = [];
    for (const course of V.pccourses)
        if (blocks.includes(setup.School.courses[course].schedule) && !myblocks.includes(setup.School.courses[course].schedule))
            myblocks.push(setup.School.courses[course].schedule);
    if (V.pcsports)
        for (const sport of V.pcsports)
            if (blocks.includes(setup.School.sports[sport].schedule) && !myblocks.includes(setup.School.sports[sport].schedule))
                myblocks.push(setup.School.sports[sport].schedule);

    blockloop: for (let i = 0; i < myblocks.length; i++)
    {
        let blockinfo = setup.School.blocks[myblocks[i]];
        for (const slot of blockinfo)
        {
            if (weekday == slot.day && hour < slot.hour && slot.hour < minhour)
            {
                nextblock = {...blockinfo};
                nextblock.name = myblocks[i];
                nextblock.month = month;
                nextblock.day = day;
                nextblock.hour = slot.hour;
                nextblock.weekday = weekday;
                minhour = slot.hour;
                //break blockloop;
            }
        }
    }

    let possiblenext;

    if (nextblock)
    {
        const courses = V.pccourses;
        for (let course of courses)
        {
            if (setup.School.courses[course].schedule == nextblock.name)
            {
                possiblenext = {course: course, type: "class", block: nextblock.name, weekday: nextblock.weekday, month: nextblock.month, day: nextblock.day, hour: nextblock.hour};
            }
        }
        const sports = V.pcsports || [];
        for (let course of sports)
        {
            if (setup.School.sports[course].schedule == nextblock.name)
            {
                possiblenext = {course: course, type: "sports", block: nextblock.name, weekday: nextblock.weekday, month: nextblock.month, day: nextblock.day, hour: nextblock.hour};
            }
        }
    }

    if (V.gameschedule && blocks.length > 1)
    {
        const gameschedule = V.gameschedule;
        for (const [sport, schedule] of Object.entries(gameschedule))
        {
            if (schedule.day == day)
            {
                const pcsports = V.pcsports || [];
                let insport = (pcsports.includes(sport) || pcsports.includesAny(setup.School.sports[sport].attached));
                if (insport)
                {
                    let name = sport + " " + setup.School.sports[sport].gamelabel;
                    let block = {
                        name: name,
                        course: name,
                        month: setup.ob_time.months.indexOf(schedule.month),
                        day: schedule.day,
                        hour: schedule.hour,
                        weekday: weekday,
                    }
                    if (!possiblenext || possiblenext.hour > block.hour)
                    {
                        return block;
                    }
                }
            }
        }
    }
    return possiblenext || this.next_class(1, day + 1, month, blocks);
}

setup.School.next_class_specific = function(course)
{
    let hour = V.hour;
    let day = V.day;
    let month = V.month;
    let block = course in setup.School.courses ? setup.School.courses[course].schedule : setup.School.sports[course].schedule;

    return this.next_class(hour, day, month, [block]);
}

setup.School.show_next_class_specific = function(course)
{
    let time = this.next_class_specific(course);
    if (setup.ob_time.is_today(time.month, time.day))
    {
        return "Today at " + setup.ob_time.clock(time.hour, 0);
    }
    else if (setup.ob_time.is_tomorrow(time.month, time.day))
    {
        return "Tomorrow at " + setup.ob_time.clock(time.hour, 0);
    }
    else
    {
        return setup.ob_time.date(time.month, time.day);
    }
}

setup.School.current_class = function(hour = V.hour, day = V.day, minute = V.minute, hoursearly = 1)
{
    if (!this.classes_today()) return null;

    let weekday = setup.ob_time.weekday(day);

    let block = null;

    const blocks = Object.keys(setup.School.blocks);
    blockloop: for (let i = 0; i < blocks.length; i++)
    {
        let blockinfo = setup.School.blocks[blocks[i]];
        for (const slot of blockinfo)
        {
            if (weekday == slot.day && hour >= slot.hour - hoursearly && hour < slot.hour + slot.length)
            {
                block = {...blockinfo};
                block.name = blocks[i];
                block.day = day;
                block.hour = slot.hour;
                block.length = slot.length;
                block.early = hour < slot.hour;
                block.late = hour > slot.hour || (hour == slot.hour && minute > 0);
                break blockloop;
            }
        }
    }

    if (block != null)
    {
        const courses = V.pccourses;
        for (let course of courses)
        {
            if (setup.School.courses[course].schedule == block.name)
            {
                let major = setup.School.courses[course].major;
                let retval = {course: course, type: "class", block: block.name, day: block.day, hour: block.hour, length: block.length, early: block.early, late: block.late, emoji: setup.School.get_course_attribute(course, "emoji") || setup.School.majors[major].emoji};
                let outside = setup.School.get_course_attribute(course, "outside") || setup.School.majors[major].outside;
                if (outside) retval.outside = outside;
                return retval;
            }
        }
        const sports = V.pcsports || [];
        for (let course of sports)
        {
            if (setup.School.sports[course].schedule == block.name)
            {
                return {course: course, type: "sports", block: block.name, day: block.day, hour: block.hour, length: block.length, early: block.early, late: block.late, outside: setup.School.sports[course].outside, emoji: setup.School.sports[course].emoji};
            }
        }
    }
    return null;
}

setup.School.is_exam_week = function(month = V.month, day = V.day)
{
    for (let i = 0; i < setup.School.exam_weeks.length; i++)
        if (setup.ob_time.is_this_week(setup.School.exam_weeks[i].month, setup.School.exam_weeks[i].day, month, day))
            return setup.School.exam_weeks[i].label;

    return null;
}

setup.School.is_exam_day = function(course, month = V.month, day = V.day)
{
    if (this.is_exam_week(month, day) && course in setup.School.courses)
    {
        const days = setup.School.blocks[setup.School.courses[course].schedule];
        let lastday = days[days.length - 1];
        return setup.ob_time.weekday(day) == lastday.day;
    }
    return false;
}

setup.School.class_location = function(course)
{
    if (course in setup.School.courses)
    {
        let courseinfo = setup.School.courses[course];
        let major = setup.School.majors[courseinfo.major];
        return major.location;
    }
    else
    {
        let courseinfo = setup.School.sports[course];
        return courseinfo.location;
    }
}

setup.School.at_class_location = function(course, loc = V.location)
{
    return loc == this.class_location(course);
}

setup.School.is_pc_at_class = function(earlyok = false)
{
    // true if PC is at their current class location... not late and not early!
    // however not necessarily if they are in the classroom... $inclass will cover that
    let current = this.current_class();
    return current != null && (!current.early || earlyok) && this.at_class_location(current.course);
}

setup.School.attend_class = function()
{
    let current = this.current_class();

    // set story variables we might need while in class

    State.setVar("$inclass", current.course);

    State.setVar("$professor", setup.School.professor_of_course(current.course));

    State.setVar("$classevents", []);

    let peoplehere = setup.ob_people_at_location();
    State.setVar("$peopleatlocation", peoplehere);

    V.roomtype = "classroom";

    if (setup.ob_houses.is_task_available("attend class in full costume when it's not Harvest Eve week") && V.pc.perceived_in_costume() && !setup.ob_is_harvesteve())
        setup.ob_houses.set_task_flag("costumeclass");

    // discover who we're seated next to
    // important for socializing and other stuff
    let seatedwith = [];
    let tries = 0;
    let seatedcount = setup.School.get_course_attribute(current.course, "seated with");
    let newrels = V.peopleatlocation.filter(p => (setup.ob_isNonEmptyObject(V.pendingaddrelationships) && V.pendingaddrelationships[p] || setup.ob_isNonEmptyObject(V.pendingremoverelationships) && V.pendingremoverelationships[p]) && setup.people.get_type(p) == "student");
    while (seatedwith.length < seatedcount && tries < 40)
    {
        tries++;
        let rand = State.random();

        let lustcutoff = V.pchorny == 2 ? 0.55 : (V.pchorny == 1 ? 0.45 : 0.3);
        let add;
        if (newrels.length > 0 && rand <= 0.5)  // people with pending relationship changes
            add = setup.ob_events.pick_person({attitudes: ["friendship", "romance", "lust"], specialok: true}, newrels);
        else if (V.crush && rand <= 0.4 && !seatedwith.includes(V.crush) && V.peopleatlocation.includes(V.crush) && setup.people.get_type(V.crush) == "student")  // crush
            add = V.crush;
        else if (rand <= lustcutoff)       // lustful
            add = setup.ob_events.pick_person({attitudes: ["lust", "random"], attractiontopc: true, inclinations: setup.ob_archetypes.inclination_sets.not_shy, specialok: true, type: "student", specialok: true});
        else if (rand <= 0.7)      // friendly
            add = setup.ob_events.pick_person({attitudes: ["friendship", "romance", "random"], specialok: true, type: "student"});
        else                        // totally random
            add = setup.ob_events.pick_person({attitudes: [], specialok: true, type: "student"});

        if (!add)
            add = setup.ob_events.pick_person({attitudes: [], type: "student", specialok: true});

        if (add && !seatedwith.includes(add))
        {
            seatedwith.push(add);
            if (newrels.includes(add))
                newrels.splice(newrels.indexOf(add), 1);
        }
    }
    State.setVar("$seatedwith", seatedwith);
    State.setVar("$tellseatedwith", true);

    if (current.early)
    {
        // pass time until class actually begins
        //let earlytime = setup.ob_time.minutes_until(current.hour, 0);
        //setup.ob_time.advance_time(earlytime);
        // this got replaced by a passage where the player can choose what to do before class
    }

    // record that we attended class
    let attendance = V.classesattended;
    if (attendance == undefined)
    {
        attendance = {};
        State.setVar("$classesattended", attendance);
    }

    if (current.course in attendance)
    {
        attendance[current.course]++;
    }
    else
    {
        attendance[current.course] = 1;
    }

    if (["Block A", "Block B"].includes(current.block))
    {
        for (let student of setup.School.students_in_course(current.course))
            setup.people.learn_major(student);
    }
}

setup.School.attend_practice = function()
