setup.School.repair_course_data = function(course)
{
    let studying = V.studying;
    let homework = V.homework;
    if (!(course in studying)) studying[course] = {covered: 0, studied: 0};
    if (!(course in homework)) homework[course] = {assigned: 0, completed: 0, pasthomework: [], lastscore: -1};

    // repair data
    if (isNaN(homework[course].lastscore))
        homework[course].lastscore = 0;
    for (let i = 0; i < homework[course].pasthomework.length; i++)
        if (isNaN(homework[course].pasthomework[i]))
            homework[course].pasthomework[i] = 0;
    if (V.exams && V.exams[course])
    {
        if (isNaN(V.exams[course].performance))
            V.exams[course].performance = 0;
        for (let i = 0; i < V.exams[course].scores.length; i++)
            if (isNaN(V.exams[course].scores[i]))
                V.exams[course].scores[i] = 0;
    }
    if (V.gpa && V.gpa[course])
    {
        if (isNaN(V.gpa[course].currentgrade))
            if (V.exams && V.exams[course])
                V.gpa[course].currentgrade = V.exams[course].performance;
            else
                V.gpa[course].currentgrade = 0.6;
    }
}

setup.School.assign_work = function(course)
{
    // initialize tracking of studying/homework if we haven't already
    let cinfo = setup.School.courses[course];
    if (!cinfo) return; // got called with a bogus course (it's sports)
    let studying = V.studying;
    let homework = V.homework;
    if (!(course in studying)) studying[course] = {covered: 0, studied: 0};
    if (!(course in homework)) homework[course] = {assigned: 0, completed: 0, pasthomework: [], lastscore: -1};

    this.repair_course_data(course);

    // if homework was assigned last class, record score
    if (homework[course].assigned > 0)
    {
        let perc = Math.min(homework[course].completed / homework[course].assigned, 1);

        homework[course].assigned = 0;
        homework[course].completed = 0;

        if (V.homeworklevel && V.homeworklevel[course])
        {
            // someone else did this homework
            perc *= V.homeworklevel[course];
            delete V.homeworklevel[course];
            if (Object.keys(V.homeworklevel).length == 0) delete V.homeworklevel;
        }
        else
        {
            // we did this homework
            let study = V.preclassstudying || studying[course];
            delete V.preclassstudying;

            if (!study.studied) perc = 0;
            else if (!study.covered) perc *= 1;
            else perc *= (study.studied / study.covered); // modify by understanding

            let skills = setup.School.get_course_attribute(course, "skills") || ["Intellectual"];
            let skill = setup.ob_randomchoice(skills);
            let diff = setup.School.get_course_attribute(course, "difficulty") || 3;
            if (!V.pc.skillcheck(skill, diff))
            {
                // drop a letter grade if we fail the skillcheck
                perc -= 0.1;
            }

            if (perc > 0.0)
                perc += (-0.05 + (0.1 * State.random()));
        }

        perc = Math.max(Math.min(perc, 1.0), 0);
        //console.log("Homework score: " + Math.round(perc * 100.0) + "%");

        homework[course].pasthomework.push(perc);
        homework[course].lastscore = perc;
    }

    if (!Number.isFinite(studying[course].covered))
        studying[course].covered = 0;

    // add new studying time and homework
    if (!this.is_exam_day(course))
        studying[course].covered += Math.floor(120 * setup.School.get_course_attribute(course, "new material rate"));

    let hw = 0;
    let chomework = setup.School.get_course_attribute(course, "homework");
    if (this.is_exam_day(course))
        hw = 0;
    else if (chomework == 1)
    {
        hw = Math.floor(setup.ob_randomrelfreq([0, 5, 0.25, 25, 0.5, 55, 1, 25]) * 30);
        homework[course].assigned += hw;
    }
    else if (chomework == 2)
    {
        hw = Math.floor(setup.ob_randomrelfreq([0.25, 20, 0.5, 25, 1, 50, 1.5, 5]) * 30);
        homework[course].assigned += hw;
    }
    else if (chomework == 3)
    {
        hw = Math.floor(setup.ob_randomrelfreq([0.5, 5, 1, 45, 1.5, 50]) * 30);
        homework[course].assigned += hw;
    }

    return hw;
}

setup.School.end_unit = function(course)
{
    // runs immediately after completing (or missing) an exam

    // reset studying for this unit
    let studying = V.studying;
    studying[course].studied = 0;
    studying[course].covered = 0;

    this.calc_unit_grade(course);
}

setup.School.calc_unit_grade = function(course)
{
    // calc avg homework grade
    let homework = V.homework;
    let hw = 0;
    if (!homework || !(course in homework) || homework[course].pasthomework.length == 0)
    {
        hw = -1;
    }
    else
    {
        let total = 0;
        let count = 0;
        for (const score of homework[course].pasthomework)
            if (score != null)
            {
                count++;
                total += score;
            }
        hw = total / count;
    }
    //homework[course].pasthomework = [];

    // calc avg exam grade
    let exams = V.exams;
    let ex = 0;
    if (!exams || !(course in exams) || exams[course].scores.length == 0)
    {
        ex = -1;
    }
    else
    {
        let total = 0;
        let count = 0;
        for (const score of exams[course].scores)
            if (score != null)
            {
                count++;
                total += score;
            }
        ex = total / count;
    }

    let grade = 0;
    if (hw == -1 && ex == -1)
    {
        // should never end up here but, well, you know
        grade = 0.75;
    }
    else if (hw == -1)
    {
        grade = ex;
    }
    else if (ex == -1)
    {
        grade = hw;
    }
    else
    {
        grade = (hw * 0.4) + (ex * 0.6);
    }

    const extra = V.extracredit;
    if (extra && extra[course])
    {
        let boost = this.extra_credit_boost(extra[course]);
        grade += boost;
    }

    if (!("gpa" in State.variables)) State.setVar("$gpa", {});

    let gpaval = V.gpa;
    if (!(course in gpaval))
    {
        gpaval[course] = {lastgrade: -1, currentgrade: grade};
    }
    else
    {
        gpaval[course].currentgrade = grade;
    }

    return grade;
}

setup.School.extra_credit_boost = function(credits)
{
    const base = 0.05;
    const max = 0.1;
    return Math.min(max, base * Math.sqrt(credits));
}

setup.School.end_term_for_course = function(course)
{
    let gpa = V.gpa;
    if (gpa[course]) // this is probably only false if we cheated a huge forward time skip
    {
        gpa[course].lastgrade = gpa[course].currentgrade;
        gpa[course].currentgrade = -1;
        setup.add_notification("Your final grade for " + course + " was <<highlight>>" + this.find_grade(gpa[course].lastgrade * 100.0) + "<</highlight>>.");
    }
}

setup.School.end_term = function()
{
    for (const course of V.pccourses)
    {
        this.end_term_for_course(course);
    }
    if (V.pcsports && V.pcsports.length > 0)
    {
        const sport = V.pcsports[0];
        setup.add_notification("Your " + sport + " season has ended! But you can rejoin when signups open, or pick a different sport!");
        V.pcsports = [];
    }
    delete V.pcquitsports;

    State.setVar("$homework", {});
    State.setVar("$studying", {});
    State.setVar("$extracredit", {});
    V.lasttermend = V.gameday;
    console.log("The term has ended!");
}

setup.School.current_average_score = function()
{
    let gpa = V.gpa;
    if (!gpa) return -1;
    let total = 0;
    let count = 0;
    for (const [course, score] of Object.entries(gpa))
    {
        if (V.pccourses.includes(course) && score.currentgrade != -1)
        {
            count++;
            total += score.currentgrade;
        }
    }
    return count == 0 ? -1 : total / count;
}

setup.School.last_average_score = function()
{
    let gpa = V.gpa;
    if (!gpa) return -1;
    let total = 0;
    let count = 0;
    for (const [course, score] of Object.entries(gpa))
    {
        if (V.pccourses.includes(course) && score.lastgrade != -1)
        {
            count++;
            total += score.lastgrade;
        }
    }
    return count == 0 ? -1 : total / count;
}

setup.School.init_exam = function(course)
{
    let exams = V.exams;
