        {
            exams[course] = {performance: 0, scores: []};
        }
    }
}

setup.School.pay_attention = function(course, undo = false)
{
    let time = Math.round((30 * setup.School.get_course_attribute(course, "new material rate")) * 0.8);
    let studying = V.studying;
    if (!(course in studying)) studying[course] = {studied: 0, covered: 0};
    if (!V.preclassstudying) V.preclassstudying = studying[course];
    studying[course].studied += (undo ? -time : time);
    studying[course].studied = Math.max(studying[course].studied, 0);
}

setup.School.pay_no_attention = function(course, undo = false)
{
    let time = Math.round((30 * setup.School.get_course_attribute(course, "new material rate")) * 0.5);
    let studying = V.studying;
    if (!(course in studying)) studying[course] = {studied: 0, covered: 0};
    if (!V.preclassstudying) V.preclassstudying = studying[course];
    studying[course].studied += (undo ? -time : time);
    studying[course].studied = Math.max(studying[course].studied, 0);
}

setup.School.unit_understanding = function(course)
{
    let studying = V.studying;
    if (!(course in studying) || !studying[course].covered) return 1;
    return studying[course].studied / studying[course].covered;
}

setup.School.rate_understanding = function(course)
{
    let perc = this.unit_understanding(course);
    if (perc <= 0.1)
        return "basically nil";
    else if (perc <= 0.25)
        return "very poor";
    else if (perc <= 0.5)
        return "poor";
    else if (perc <= 0.7)
        return "middling";
    else if (perc <= 0.8)
        return "good";
    else if (perc <= 0.9)
        return "very good";
    else
        return "near perfect";
}

setup.School.study_difficulty = function(course)
{
    let perc = this.unit_understanding(course);

    let base = 0;
    if (perc <= 0.1)
        base = 0;
    else if (perc <= 0.25)
        base = 1;
    else if (perc <= 0.5)
        base = 2;
    else if (perc <= 0.7)
        base = 3;
    else if (perc <= 0.8)
        base = 4;
    else if (perc <= 0.9)
        base = 5;
    else
        base = 6;

    let covered = V.studying[course].covered;

    if (covered <= 120)
        return Math.max(base - 5, 0);
    else if (covered <= 180)
        return Math.max(base - 4, 0);
    else if (covered <= 240)
        return Math.max(base - 3, 0);
    else if (covered <= 360)
        return Math.max(base - 2, 0);
    else if (covered <= 420)
        return Math.max(base - 1, 0);
    else
        return base;
}

setup.School.do_study = function(course, minutes)
{
    let studying = V.studying;
    studying[course].studied += minutes;
    studying[course].studied = Math.clamp(studying[course].studied, 0, studying[course].covered);
}

setup.School.do_homework = function(course, minutes)
{
    let homework = V.homework;
    homework[course].completed += minutes;
    homework[course].completed = Math.clamp(homework[course].completed, 0, homework[course].assigned);
}

