setup.School.next_game = function(type = null, day = V.day, month = V.month, hour = V.hour)
{
    let numeraldays = (28 * month) + day;
    let sorted = [];
    for (const gameday of setup.School.gamedays)
    {
        let numeralgameday = (28 * setup.ob_time.months.indexOf(gameday.month)) + gameday.day;
        if (((numeralgameday == numeraldays && gameday.hour > hour) || numeralgameday > numeraldays) && (!type || type == gameday.type))
            sorted.push([gameday, numeralgameday]);
    }

    if (sorted.length == 0)
    {
        if (day == 1 && month == 0)
            return null;
        else
            return this.next_game(type, 1, 0);
    }
    else
    {
        sorted.sort(function(a,b) {
            return a[1]-b[1]
        });

        return sorted[0][0];
    }
}

setup.School.rival_team = function()
{
    for (const [team, teaminfo] of Object.entries(setup.School.other_teams))
        if (teaminfo.rival)
