setup.School.pick_regular_match = function(type, exclude = [])
{
    let allteams = Object.keys(setup.School.other_teams);

    allteams = allteams.filter(team => !setup.School.other_teams[team].rival && !exclude.includes(team));

    let teams = [...allteams];

    let gamehistory = V.gamehistory;
    if (gamehistory && gamehistory[type])
    {
        for (let result of gamehistory[type])
        {
            let i = teams.indexOf(result.team);
            if (i >= 0)
                teams.splice(i, 1);
        }
    }
    if (teams.length > 0)
        return setup.ob_randomchoice(teams);
    else
        return setup.ob_randomchoice(allteams);
}

setup.School.pick_best_opponent_team = function(type, exclude = [])
{
    let allteams = Object.keys(setup.School.other_teams);
    let windict = {};
    let gamehistory = V.gamehistory;
    if (gamehistory && gamehistory[type])
    {
        for (let result of gamehistory[type])
        {
            let team = Array.isArray(result.team) ? result.team[0] : result.team;
            if (!result.win)
                windict[team] = windict[team] ? windict[team]+1 : 1;
        }
    }
    let teams = [];
    for (const [team, wins] of Object.entries(windict))
        teams.push(team, wins);

    if (teams.length > 0)
        return setup.ob_randomrelfreq(teams);
    else
        return setup.ob_randomchoice(allteams);
}

setup.School.team_ability = function(team, type)
{
    return team == setup.School.team.name ? 7 : setup.School.other_teams[team].ability[type];
}

setup.School.team_ability_random = function(team, type)
{
    let base = this.team_ability(team, type);
    const variation = [base - 1, 25, base, 50, base + 1, 25];
    return setup.ob_randomrelfreq(variation);
}

setup.School.seed_playoffs = function(type)
{
    let teams = setup.ob_shuffle(Object.keys(setup.School.other_teams));
    let bestteam = null;
    let bestrating = -1;
    for (const team of teams)
    {
        let teamability = this.team_ability_random(team, type);
        if (bestrating == -1 || teamability > bestrating)
        {
            bestrating = teamability;
            bestteam = team;
        }
    }
    const playoffs = [];

    playoffs.push([bestteam, "bye"]);
    teams.splice(teams.indexOf(bestteam), 1);
    teams.push("Fighting Elks");

    for (let i = 0; i < teams.length; i+=2)
    {
        playoffs.push([teams[i], teams[i+1]]);
    }

    let storedplayoffs = V.playoffs || {};
    storedplayoffs[type] = [playoffs];
    State.setVar("$playoffs", storedplayoffs);

    return playoffs;
}

setup.School.resolve_game = function(team1, team2, type)
{
    if (typeof team2 == "string")
    {
        let team1chance = setup.pc().skillcheck_rate(this.team_ability_random(team1, type), this.team_ability_random(team2, type));
        let winner = State.random() < team1chance ? team1 : team2;
        return winner;
    }
    else if (Array.isArray(team2))
    {
        // handle divisionals etc
        let winner = team1;
        for (let otherteam of team2)
        {
            let retainwinchance = setup.pc().skillcheck_rate(this.team_ability_random(winner, type), this.team_ability_random(otherteam, type));
            if (State.random() >= retainwinchance)
                winner = otherteam;
        }
        return winner;
    }
    else
    {
        return team1;
    }
}

setup.School.resolve_playoff_round = function(type, round)
{
    let playoffs = V.playoffs;
    let thisround = playoffs[type][round - 2];
    const thisteam = setup.School.team.name;
    const winners = [];
    for (const matchup of thisround)
    {
        let team1 = matchup[0];
        let team2 = matchup[1];

        if (team2 == "bye")
        {
            // odd number of teams = somebody gets a free pass sometimes
            winners.push(team1);
        }
        else if (team1 == thisteam || team2 == thisteam)
        {
            // involved home team... let's see if the player witnessed it and saw the result
            // otherwise we resolve it as normal
            let oteam = team1 == thisteam ? team2 : team1;
            let result = this.last_game_result_against(type, oteam);
            if (result.playoffround == round - 1)
            {
                let winner = result.win ? thisteam : oteam;
                winners.push(winner);
            }
            else
            {
                let winner = this.resolve_game(team1, team2, type);
                winners.push(winner);
            }
        }
        else
        {
            let winner = this.resolve_game(team1, team2, type);
            winners.push(winner);
        }
    }

    let newround = setup.ob_shuffle(winners);
    let newplayoffs = [];
    if (winners.length == 1)
    {
        // todo: better handle championship
        this.record_playoff_champion(winners[0], type);
        delete playoffs[type];
        newplayoffs = playoffs;
    }
    else
    {
        for (let i = 0; i < newround.length; i+=2)
        {
            if (i == newround.length - 1)
                newplayoffs.push([newround[i], "bye"]);
            else
                newplayoffs.push([newround[i], newround[i+1]]);
        }

        playoffs[type].push(newplayoffs);
    }
    State.setVar("$playoffs", playoffs);

    return newplayoffs;
}

setup.School.is_team_in_playoffs = function(team, type)
{
    let playoffs = V.playoffs;
    if (playoffs?.[type])
    {
        const latest = playoffs[type][playoffs[type].length - 1];
        if (latest.length == 1 && latest[0].includes(setup.School.team.name) && latest[0].includes("bye"))
        {
            this.record_playoff_champion(setup.School.team.name, type);
            delete V.playoffs[type];
            return false;
        }
        return !!this.playoffs_against(team, type);
    }

    if (V.playoffchamp?.[type]) return false;

    return V.month != 0;
}

setup.School.record_playoff_champion = function(team, type)
{
    if (!V.playoffchamp) V.playoffchamp = {};
    V.playoffchamp[type] = team;
}

setup.School.playoffs_against = function(team, type)
{
    let playoffs = V.playoffs;
    if (!playoffs || !playoffs[type]) return null;
    let i = playoffs[type].length - 1;
    for (const matchup of playoffs[type][i])
        if (matchup[0] == team)
            return matchup[1];
        else if (matchup[1] == team)
            return matchup[0];
}

setup.School.game_end = function(type, team, gameday, win, day = V.day, month = V.month, hour = V.hour)
{
    let gamehistory = V.gamehistory || {};
    if (!gamehistory[type]) gamehistory[type] = [];

    let result = {team: team, win: win};
    if (gameday.playoffround)
        result.playoffround = gameday.playoffround;
    gamehistory[type].push(result);
    State.setVar("$gamehistory", gamehistory);

    delete State.variables.gameschedule[type];
    if (V.sport && V.sport.type == type)
        delete V.sport;

    this.configure_upcoming_games(day, month, hour);

    return gamehistory;
}

setup.School.last_game_result = function(type)
{
    let gamehistory = V.gamehistory;
    if (!gamehistory || !gamehistory[type]) return null;
    const reversehistory = [...gamehistory[type]].reverse();
    for (const matchup of reversehistory)
        return matchup;
    return null;
}

setup.School.last_game_result_against = function(type, team)
{
    let gamehistory = V.gamehistory;
    if (!gamehistory || !gamehistory[type]) return null;
    const reversehistory = [...gamehistory[type]].reverse();
    for (const matchup of reversehistory)
        if (matchup.team == team)
            return matchup;
    return null;
}

setup.School.configure_upcoming_games = function(day = V.day, month = V.month, hour = V.hour)
{
    const thisteam = setup.School.team.name;
    let schedule = V.gameschedule || {};
    if (!V.gamehistory) State.setVar("$gamehistory", {});
    for (const [game, gameinfo] of Object.entries(setup.School.sports))
    {
        if (gameinfo.games && !schedule[game])
        {
            let gameday = Object.assign({}, this.next_game(game, day, month, hour));
            gameday.gametype = gameday.against;
            // team games
            if (gameday.against == "regular")
            {
                gameday.against = this.pick_regular_match(game);
            }
            else if (gameday.against == "rivalry")
            {
                gameday.against = this.rival_team();
            }
            else if (gameday.against == "playoff")
            {
                if (gameday.round == 1)
                {
                    this.seed_playoffs(game);
                }
                else if (!V.playoffs || !V.playoffs[gameday.type])
                {
                    // resumed an old save mid-playoffs
                    continue;
                }
                else
                {
                    this.resolve_playoff_round(game, gameday.round);
                }
                if (!this.is_team_in_playoffs(thisteam, game))
                {
                    continue;
                }
                else
                {
                    gameday.against = this.playoffs_against(thisteam, game);
                    if (gameday.against == "bye") // we're done, actually
                        continue;
                    if (V.playoffs[game] && V.playoffs[game][V.playoffs[game].length - 1].length == 1)
                        gameday.championship = true;
                }
                gameday.playoffround = gameday.round;
            }
            // swim meets
            else if (gameday.against == "dual")
            {
                gameday.against = [this.pick_regular_match(game)];
            }
            else if (gameday.against == "invitational")
            {
                gameday.against = [];
                for (let i = 0; i < 3; i++)
                    gameday.against.push(this.pick_regular_match(game, gameday.against));
            }
            else if (gameday.against == "championship")
            {
                gameday.against = [this.pick_best_opponent_team(game)];
            }
            // cheerleading
            else if (gameday.against == "division")
            {
                gameday.against = setup.ob_shuffle(Object.keys(setup.School.other_teams));
            }

            const allteams = Object.keys(setup.School.other_teams)
            if (typeof gameday.against == "string" && !allteams.includes(gameday.against))
            {
                // apparently this can fail, which needs some investigation
                // but in the meantime, this will stop games from breaking
                console.log("Failed to find other team! .against was " + gameday.against);
                gameday.against = setup.ob_randomchoice(allteams);
                if (gameday.type == "swimming")
                    gameday.against = [gameday.against];
            }

            schedule[game] = gameday;
        }
    }
    State.setVar("$gameschedule", schedule);
    return schedule;
}

setup.School.expand_opposing_team = function(game, teams)
{
    if (!Array.isArray(teams)) teams = [teams];
    const retval = [];
    for (const team of teams)
    {
        let rng = new RNG(inthash(team));
        const teaminfo = setup.School.other_teams[team];
        if (teaminfo.rival)
        {
            if (!V.rivalsportsteams[game] || !V.rivalsportsteams[game].team) return;
            const teamnames = V.rivalsportsteams[game].team;
            for (const name of teamnames)
            {
                let p = new Person({person: name});
                p.sportsteam = team;
                retval.push(p);
            }
        }
        else
        {
            const sportinfo = setup.School.sports[game];
            for (let i = 0; i < sportinfo["team size"]; i++)
            {
                let gender = rng.randomrelfreq(sportinfo.outsidergenders);
                let temp = new Person({temporary: true, gender: gender, type: "outsider", archetype: rng.randomchoice(sportinfo.outsiderarchetypes)});
                temp.sportsteam = team;
                retval.push(temp);
            }
        }
    }
    return retval;
}

