setup.School.office_hours_time = function()
{
    if (V.hour < 7 || V.hour > 18)
        return false;

    if (setup.School.current_class()) return false;

    if (setup.ob_time.is_weekend()) return false;

    return true;
}

setup.School.special_task_time = function()
{
    if (!V.profspecialtask) return false;

    if (V.profspecialtask.type != "observatory" && (V.hour < 7 || V.hour > 18))
        return false;
    else if (V.profspecialtask.type == "observatory" && (V.hour < 3 || V.hour >= 5))
        return false;

    if (setup.School.current_class()) return false;

    if (setup.ob_time.is_weekend() && V.profspecialtask.type != "observatory") return false;

    return true;
}

setup.School.has_homework = function()
{
    const hw = V.homework;
    if (!hw) return false;
    for (const [course, hwinfo] of Object.entries(hw))
    {
        if (hwinfo.assigned && hwinfo.completed < hwinfo.assigned)
            return true;
    }
    return false;
}

setup.School.unfinished_homework_classes = function()
{
    const hw = V.homework;
    if (!hw) return [];
    const retval = [];
    for (const [course, hwinfo] of Object.entries(hw))
    {
        if (hwinfo.assigned && hwinfo.completed < hwinfo.assigned)
            retval.push(course);
    }
    return retval;
}

setup.School.enrolled_courses = function(student)
{
    const pdata = setup.people.get_person(student);
    const courses = pdata.courses || [];
    const sports = pdata.sports || [];
    return [...courses, ...sports];
}

