if (!("ob_shops" in setup)) setup.ob_shops = {};

setup.ob_shops.can_purchase = function(shop, type, item, subs, quantity = 1, friend = false)
{
    //console.log("can_purchase: ", shop, type, item, subs, quantity);
    let retval = {};
    let itemobj;
    let current = null;
    const shopitem = V.shopitem;
    if (type == "food")
    {
        itemobj = setup.ob_food[item];
    }
    else if (type == "clothes")
    {
        //console.log("Clothes type!", shop, item, subs);
        itemobj = new ClothingItem(item);
        if ("subs" in shop)
        {
            //console.log("adding subs: ",shop.subs);
            itemobj.add_sub_prefixes(shop.subs);
        }
        itemobj.set_subs(subs);
        if (setup.pc().already_has_clothing(itemobj.get_data_structure()) && friend == false)
        {
            retval.result = false;
            retval.reason = "You already own something exactly like that."
            return retval;
        }
        //console.log("Through clothing logic, re-defining to data structure.")
        itemobj = itemobj.get_current_archetype();
    }
    else if (type == "alcohol")
    {
        if (setup.ob_pregnancy.known("PC"))
        {
            retval.result = false;
            retval.reason = "It's a bad time in your life to be drinking.";
            return retval;
        }
        else
            itemobj = setup.ob_alcohol[item];
    }
    else if (type == "dormstuff")
    {
        itemobj = setup.ob_dormstuff[item];
        current = setup.ob_locationInventory.category_item("packed", itemobj.category);

        if (itemobj.prereq && !setup.ob_locationInventory.has("packed", itemobj.prereq) && !setup.ob_locationInventory.has(setup.ob_locationInventory.lastloc(), itemobj.prereq))
        {
            retval.result = false;
            retval.reason = "You're missing a needed item: " + itemobj.prereq + ".";
            return retval;
        }
    }
    else if (type == "sextoys")
    {
        itemobj = setup.sextoys[item];
    }
    else if (type == "makeup")
    {
        itemobj = setup.ob_cosmetics.makeup[item];
        let name = itemobj.name;
        const current = V.makeup || {};
        if (Object.keys(current).includes(name)  && friend == false)
        {
            retval.result = false;
            retval.reason = "You already own something exactly like that."
            return retval;
        }
    }
    else if (type == "piercings")
    {
        itemobj = setup.ob_cosmetics.piercings[item];
    }
    else if (type == "outfit")
    {
        if (shopitem.clothes.length == 0 && friend == false)
        {
            retval.result = false;
            retval.reason = "You already own all of these clothes"

            let outfitname = shopitem.label;
            let found = false;
            let outfits = V.outfits || [];
            for (let outfit of outfits)
                if (outfit.name == outfitname)
                {
                    found = true;
                    break;
                }
            if (!found)
            {
                let newoutfit = {name: outfitname, type: "Uniform", clothes: shopitem.allclothes};
                outfits.push(newoutfit);
                retval.reason += ", but they have been put together into an outfit for you."
            }
            else
            {
                retval.reason += ".";
            }

            return retval;
        }
        itemobj = shopitem;
        if (setup.ob_outfits[shopitem.item].sports && !V.firsttime.boughtsportsuniform)
            itemobj.price = 0;
        else if (V.riverrat && V.riverrat.uniformcredit == shopitem.item)
            itemobj.price = 0;
    }
    else if (type == "books")
    {
        if (setup.ob_books.has(item) && friend == false)
        {
            retval.result = false;
            retval.reason = "You already own this book."
            return retval;
        }
        itemobj = setup.ob_books.book_info(item);
    }
    else if (type == "miscitem" || type == "misc")
    {
        itemobj = setup.ob_miscitems[item];
    }

    let price = itemobj.price || 0;
    price *= quantity;
    price = Math.floor(price * this.price_multiplier(shop));
    let tradein = 0;
    if (current && itemobj.tradein)
    {
        tradein = Math.round(setup.ob_dormstuff[current.item || current].price / 2);
        price -= tradein;
    }

    if (price > 0 && V.pcmoney < price)
    {
        retval.result = false;
        retval.reason = "You don't have enough money."
    }
    else if (type == "food" && !shop["eat immediately"] && friend == false)
    {
        if (!setup.ob_locationInventory.has_fridge() && !itemobj.flags.includes("nonperishable"))
        {
            retval.result = false;
            retval.reason = "You would need a fridge to safely store that.";
        }
        else if (itemobj.cooking && !setup.pc().skillleveled("Cooking", itemobj.cooking))
        {
            retval.result = false;
            retval.reason = "You don't have the cooking skill to deal with that. May as well save your money.";
        }
        else if (itemobj["cook with"] && !setup.ob_locationInventory.has_any_anywhere(itemobj["cook with"]))
        {
            retval.result = false;
            retval.reason = "You don't have anything to prepare that with.";
        }
        else
        {
            retval.result = true;
        }
    }
    else if (type == "dormstuff" && friend == false)
    {
        if (itemobj.category == "pet" && setup.ob_locationInventory.category_item_anywhere(itemobj.category))
        {
            retval.result = false;
            retval.reason = "You already own a pet.";
        }
        else if (false && setup.ob_locationInventory.has("packed", item) && !itemobj.canDuplicate) // currently disabled — let the player decide whether they want duplicate items
        {
            retval.result = false;
            retval.reason = "You already own this item.";
        }
        else
        {
            retval.result = true;
        }
    }
    else
    {
        retval.result = true;
    }

    let missing_styles = []
    for (const [k, v] of Object.entries(subs))
    {
        if (v == null)
        {
            missing_styles.push(k)
        }
    }
    if (missing_styles.length > 0)
    {
        retval.result = false;
        if (missing_styles.length == 1)
        {
            retval.reason = "You must choose an option for " + missing_styles[0] + ".";
        }
        else
        {
            retval.reason = "You must choose options for " + setup.ob_and(missing_styles) + ".";
        }
    }

    return retval;
}

setup.ob_shops.purchase = function(shop, type, item, subs = {}, usenow = false, free = false, quantity = 1, friend = false)
{
    // put a purchased item (of several different possible types) where it belongs
    // and also set it up and stuff
    let itemobj; // get info from database
    let current = null;
    if (type == "food")
    {
        itemobj = setup.ob_food[item];
    }
    else if (type == "clothes")
    {
        itemobj = setup.clothes[item];
    }
    else if (type == "alcohol")
    {
        itemobj = setup.ob_alcohol[item];
    }
    else if (type == "dormstuff")
    {
        itemobj = setup.ob_dormstuff[item];
