    {
        itemobj = V.shopitem;
    }
    else if (type == "books")
    {
        itemobj = setup.ob_books.book_info(item);
    }
    else if (type == "miscitem" || type == "misc")
    {
        itemobj = setup.ob_miscitems[item];
    }
    itemobj = Object.assign({}, itemobj);
    itemobj.shoptype = type;
    itemobj.shopitem = item;
    itemobj.shopsubs = subs;

    let name = "name" in itemobj ? itemobj.name : item.toLowerCase(); // determine name
    if (type == "dormstuff" && !itemobj.name && itemobj.add)
        name = itemobj.add;

    if (name.indexOf("%") >= 0)
    {
        // perform substitutions
        for (const [sub, sel] of Object.entries(subs))
        {
            name = name.replace("%"+sub, sel);
        }
    }
    let rname = name; // determine player-readable name
    if (type == "books")
    {
        rname = "a copy of '" + item + "'";
    }
    else
    {
        rname = `${itemobj?.aoran ?? setup.ob_a_or_an(rname)} ${rname}`;
    }

    itemobj.shopname = rname;

    let retval = "";
    let price = itemobj.price || 0;
    price *= quantity;
    price = Math.floor(price * this.price_multiplier(shop));
    let tradein = 0;
    if (current && itemobj.tradein && setup.ob_dormstuff[current.item || current])
    {
        tradein = Math.round(setup.ob_dormstuff[current.item || current].price / 2);
