        }
        else if (price == 0)
        {
            retval = "After trade-in, it's essentially free to get ";
        }
        else
        {
            if (Number.isFinite(price))
                State.setVar("$pcmoney", V.pcmoney - price);
            retval = "You pay $" + price + " for ";
            V.lastpurchaseamount = price;
        }
    }
    else if (shop.mailorder)
    {
        retval = "You pay $" + price + " to order ";
        V.lastpurchaseamount = price;
    }
    else if (type == "outfit" && setup.ob_outfits[itemobj.item].sports && !V.firsttime.boughtsportsuniform)
    {
        let firsttime = V.firsttime;
        firsttime.boughtsportsuniform = true;
        retval = "The Campus Recreation department agrees to pay for "
    }
    else if (type == "outfit" && V.riverrat && V.riverrat.uniformcredit == itemobj.item)
    {
        delete V.riverrat.uniformcredit;
        retval = "The owner has provided ";
    }
    else
