        // ways to handle food
        if (shop["eat immediately"] || usenow)
        {
            // eat immediately and advance time
            setup.ob_needs.eat(itemobj);
            setup.ob_time.advance_time(5);
            retval += ".";
        }
        else if (itemobj.flags.includes("nonperishable"))
        {
            // nonperishables go in dorm food stash
            setup.ob_locationInventory.add_food(item, itemobj["purchase quantity"]);
            retval += " to keep in your food stash."
        }
        else
        {
