            drink.sips_taken = 0;
            State.setVar("$bardrink", drink);
        }
        else
        {
            retval += " and a minute later, "
            if (V.waiter)
            {
                retval += "<<anonorfullname $waiter>>"
            }
            else
            {
                retval += State.random() <= 0.5 ? "the waiter" : "the waitress";
            }
            retval += " brings it to your table and sets it down in front of you."
            let drink = Object.assign({}, itemobj);
            drink.sips_taken = 0;
            State.setVar("$bardrink", drink);
        }
    }
    else if (type == "dormstuff")
    {
        if (friend == false)
        {
            // handle furniture, decor type stuff
            if (itemobj.addCollection)
            {
                setup.ob_add_to_collection(rname, itemobj.add);
            }
            else
            {
                let add = itemobj.add;
                if (add)
