                    if (add == "minifridge") State.setVar("$dormfridge", {});
                    add = {item: add};
                    if (Object.keys(subs).length > 0)
                    {
                        add.name = name;
                    }
                    else if (itemobj.name && itemobj.name.indexOf('%') < 0)
                    {
                        add.name = itemobj.name;
                    }
                    setup.ob_locationInventory.add("packed", add);
                }
