        let outfitname = itemobj.label;
        let found = false;
        let outfits = V.outfits || [];
        for (let outfit of outfits)
            if (outfit.name == outfitname)
            {
                found = true;
                break;
            }
        if (!found)
        {
            let newoutfit = {name: outfitname, type: "Uniform", clothes: itemobj.allclothes};
            outfits.push(newoutfit);
        }
        retval += " for your closet. <<highlight>>You can now find this set as a premade outfit in your wardrobe!<</highlight>>";
