        {
            let invkey = itemobj.add || item;
            setup.ob_miscinventory_add(invkey, itemobj["purchase quantity"] || 1);

            retval += " to add to your stuff.";
        }
        else
        {
            retval += " to send to your friend.";
        }
    }

    return retval;
}

setup.ob_shops.maybe_purchase = function(shop, type, item, subs = {}, usenow = false, free = false, quantity = 1, errorhandled = false, friend = false)
{
    let check = this.can_purchase(shop, type, item, subs, quantity, friend);

    if (!check.result)
    {
        if (!errorhandled)
        {
            State.setVar("$shopbuyresult", "<<highlight bad>>" + check.reason + "<</highlight>>");
        }
    }
    else
    {
        let buy = this.purchase(shop, type, item, subs, usenow, free, quantity, friend);
        V.justpurchased = [shop, type, item];
        V.shopbuyresult = "<<highlight cash>>" + buy + "<</highlight>>";
        if (V.lastpurchaseamount)
            V.shopbuyresult += "<<purchaseeffects " + V.lastpurchaseamount + ">>";
    }
    return check;
}

setup.ob_shops.add_mailorder = function(item, day)
{
	let mail = V.mailorder || [];
	mail.push([item, day]);
	State.setVar("$mailorder", mail);
}

setup.ob_shops.collect_mailorder = function()
{
    const retval = [];
    let ordered = V.mailorder || [];
    const day = V.gameday;
    const remove = [];
    for (const itemorder of ordered)
    {
        if (day >= itemorder[1])
        {
            let item = itemorder[0];
            setup.ob_shops.purchase("", item.shoptype, item.shopitem, item.shopsubs, false, true);
            retval.push(item.shopname);
            remove.push(itemorder);
        }
    }

    for (const item of remove)
        ordered.splice(ordered.indexOf(item), 1);
    State.setVar("$mailorder", ordered);

    return retval;
}

setup.ob_shops.is_mailorder_ready = function()
{
    const ordered = V.mailorder || [];
    const day = V.gameday;
    for (const itemorder of ordered)
    {
        if (day >= itemorder[1])
        {
            return true;
        }
    }
    return false;
}

// Take a shop's items and parse them into categories
// We can cache the result in some cases to make it faster (not doing this currently)
// Or change the database itself to match the desired format, but this is invasive
setup.ob_shops.parse_categories = function(shopItems)
{
    const categories = [];
    let currentCategory = "Unsorted";
    let itemsInCategory = [];
    for (const item of shopItems)
    {
        // If there's no type, consider it a category
        if (item.type == null && (!item.checkvar || Scripting.evalTwineScript(item.checkvar)))
        {
            if (itemsInCategory.length > 0)
            {
                categories.push(
                    {
                        "name": currentCategory,
                        "items": itemsInCategory
                    }
                );
                itemsInCategory = [];
            }
            currentCategory = item.label;
        }
        else
        {
            itemsInCategory.push(item);
        }
    }
    if(itemsInCategory.length > 0) {
        categories.push({
            "name": currentCategory,
            "items": itemsInCategory
        });
    }

    return categories;
}

setup.ob_shops.price_multiplier = function(shop)
{
    const shopinfo = (typeof shop == "string" ? this.db[shop] : shop) || {};
    let mult = 1.0;

    if (shopinfo.employeeDiscount && V.jobs.includes(shopinfo.employeeDiscount[0]))
        mult *= shopinfo.employeeDiscount[1];

    if (shopinfo.free)
        mult = 0;

    if (shopinfo.priceMultiplier)
        mult *= shopinfo.priceMultiplier;

    return mult;
}

setup.ob_shops.randomize_name = function(item, specialsubprefix = false)
{
    // takes an item from a properly-formatted shop item database and applies random substitutions and returns a name string

    let name = item.name || item.add;

    let subs = {};

    for (const [ikey, ivalue] of Object.entries(item))
    {
        if (specialsubprefix && ikey.indexOf(specialsubprefix + " ") == 0 && Array.isArray(ivalue))
        {
            let subname = ikey.substring(specialsubprefix.length + 1);
            const sublist = ikey in item ? item[ikey] : ivalue;
            let sub = setup.ob_randomchoice(sublist);
            name = name.replace("%" + subname, sub);

            subs[subname] = sub;
        }
        else if (ikey.indexOf("sub") == 0)
        {
            let subname = ikey.substring(4);
            const sublist = ikey in item ? item[ikey] : ivalue;
            let sub = setup.ob_randomchoice(sublist);
            name = name.replace("%" + subname, sub);

            subs[subname] = sub;
        }
    }

    return [name, subs];
}

setup.ob_shops.find_dynamic_items = function(shop)
{
    if (shop == "Alakaz.on")
    {
        let books = recall("crosssavebooks") || [];
        books = books.filter(book => !setup.ob_books.has(book));

        let cats = {};

        for (let book of books)
        {
            let cat = book.type;
            if (!cats[cat]) cats[cat] = [];
            cats[cat].push(book);
        }

        let menu = [];
        for (let [cat, catbooks] of Object.entries(cats))
        {
            menu.push({label: cat});
            for (let book of catbooks)
                menu.push({label: book.name, type: "books", item: book.name});
        }

        return menu;
    }

     if (shop == "Valkyrie Books")
        /* setup.ob_books_2.db doesn't have categories, so we go through the shops to get it */
    {
        let cats = "books";

         /*This gives us a list of books, categories, and stores, dropping items that aren't in a store */
        let grouped = {};
        let order = [];

        Object.entries(setup.ob_shops.db)
            .filter(([storeName, store]) =>
                !("eat immediately" in store) &&
                ("items" in store) &&
                !storeName.startsWith("Valkyrie") &&
                (V.pchouse || storeName !== "Greek Life") &&
                (V.wildFantasiesKnown || storeName !== "Wild Fantasies") &&
                (setup.ob_is_harvesteve() || storeName !== "Costume Shop")
            )
            .forEach(([shopName, store]) => {

                const items = store.items;

                let category = "";

                items.forEach((item, index) => {

                    const isBook = item.type === "books";
                    const isBookLabel =
                        !isBook &&
                        items[index + 1]?.type === "books";

                    // Set the current category only for valid book categories
                    if (isBookLabel) {
                        category= item.label ?? "";
                        if (category.includes("Manga") || category.includes("Comics")) {
                            category = "Comics & Manga";
                        }
                        if (category === "Books" || category.includes("Crafting & Hobbies") || category.includes ("Intellectual Skills") || category.includes ("Physical Skills") || category.includes ("Sports & Fitness")) {
                            category = "Crafting & Hobbies";
                        }

                        if (category.includes ("Erotic") || category.includes ("Romance") || category.includes ("Sex")) {
                            category = "Erotica & Romance";
                        }

                        if (category.includes ("SciFi") || category.includes ("Fiction")) {
                            category = "Fiction";
                        }

                        if (category.includes ("History & Politics") || category.includes("Self-Help")) {
                            category = "Non-Fiction";
                        }

                    return;
                    }

                     if (!isBook) {
                        return;
                     }

                    if (!grouped[category]) {
                        grouped[category] = [];
                        order.push(category);
                    }

                    if (shopName.startsWith("NobblyBarn")) {
                        shopName = "Nobbly Barns";
                    }

                    grouped[category].push({
                        ...item,
                        shop: shopName
                    });
                });
            });

        let menu = order.flatMap(category => [
            { label: category },
            ...grouped[category]
        ]);

        let uniqueMenu = [
            ...new Set(menu.map(JSON.stringify))
        ].map(JSON.parse);

        return uniqueMenu;
    }

    if (shop == "Valkyrie Clothing")
    {
        let cats = "clothes";

        /*This gives us a list of clothing, categories, and stores, dropping items that aren't in a store */
        let grouped = {};
        let order = [];

        Object.entries(setup.ob_shops.db)
            .filter(([storeName, store]) =>
                !("eat immediately" in store) &&
                ("items" in store) &&
                !storeName.startsWith("Valkyrie") &&
                (V.pchouse || storeName !== "Greek Life") &&
                (V.streaming?.xscreenname || storeName !== "CollegeCams") &&
                (V.streaming?.screenname || storeName !== "Niche.tv") &&
                (V.wildFantasiesKnown || storeName !== "Wild Fantasies") &&
                (setup.ob_is_harvesteve() || storeName !== "Costume Shop")
            )
            .forEach(([shopName, store]) => {

                const items = store.items;

                items.forEach(item => {

                    if (item.type !== "clothes") {
                        return;
                    }

                    const clothing = setup.clothes[item.item];

                    if (!clothing) {
                        return;
                    }

                    const category = clothing.category;

                    if (!grouped[category]) {
                        grouped[category] = [];
                        order.push(category);
                    }

                    grouped[category].push({
                        ...item,
                        shop: shopName
                    });
                });
            });

        let menu = order.flatMap(category => [
            { label: category },
            ...grouped[category]
        ]);

        return menu;

    }
}

setup.ob_shops.get_price = function(item, type) {

    switch (type)
    {
        case "clothes":
            return setup.clothes[item].price;
            break;
        case "food":
            return setup.ob_food[item].price;
            break;
        case "dormstuff":
            return setup.ob_dormstuff[item].price;
            break;
        case "sextoys":
            return setup.sextoys[item].price;
            break;
        case "makeup":
            return setup.ob_cosmetics.makeup[item].price;
            break;
        case "piercings":
            return setup.ob_cosmetics.piercings[item].price;
            break;
        case "outfit":
            return setup.ob_outfits[item].price;
            break;
        case "books":
            return setup.ob_books.book_info(item).price;
            break;
        case "miscitem":
            return setup.ob_miscitems[item].price;
            break;
        case "misc":
            return setup.ob_miscitems[item].price;
            break;
    }
}
