setup.ob_sponsors.get_shuffled_sponsors = function(categoryName)
{
    let categoryInfo = setup.ob_sponsors.db[categoryName];
    let original = categoryInfo.entries;
    if(original.length <= 0)
    {
        return [];
    }
    let shuffled = setup.ob_shuffle(original.slice());
    return shuffled;
}

setup.ob_sponsors.random_category = function(requireTopBilling = true)
{
    let choices = [];
    for(const category of setup.ob_sponsors.ordered_categories) {
        let categoryInfo = this.db[category];
        if (!requireTopBilling || categoryInfo.topBilling)
        {
            choices.push(category);
            choices.push(categoryInfo.entries.length);
        }
    }
    // we now have the relative size of each of the lists, choose one to move forward
    return setup.ob_randomrelfreq(choices);
}
setup.ob_sponsors.random_sponsor = function(category)
{
    let categoryInfo = this.db[category];
    return setup.ob_randomchoice(categoryInfo.entries);
}

