setup.ob_sports.get_routine = function(routine)
{
    // pull routine info from the database
    if (typeof routine == "object") return routine;

    if (routine in this.prebuiltRoutines)
        return this.prebuiltRoutines[routine];

    for (let sport of Object.values(V.sportsteams))
    {
        if (sport.routines && routine in sport.routines)
            return sport.routines[routine];
    }
}

setup.ob_sports.get_segments = function(routine)
{
    // return an array of the segments that make up a routine
    if (Array.isArray(routine)) return routine;
    return this.get_routine(routine).segments.map(seg => typeof seg == "string" ? seg : seg.name);
}

setup.ob_sports.segment_info = function(segment)
{
    // pull segment info from the database
    if (typeof segment == "object") return segment;
    let seginfo = Object.assign({}, this.routineSegments[segment]);
    seginfo.name = segment;
    return seginfo;
}

setup.ob_sports.routine_difficulty = function(routine)
{
    // determine the difficulty of a routine by averaging the difficulty score of its segments
    let segments = this.get_segments(routine);
    let tdifficulty = 0;
    for (let segment of segments)
        tdifficulty += this.segment_info(segment).difficulty;
    return Math.round(tdifficulty / segments.length);
}

setup.ob_sports.practice_segment = function(sport, segment)
{
    // practice a segment, increasing a team's experience with it
    let sportinfo = V.sportsteams[sport];
    if (!sportinfo.practice) sportinfo.practice = {};
    if (!sportinfo.practice[segment])
        sportinfo.practice[segment] = [1, V.gameday];
    else
    {
        sportinfo.practice[segment][0]++;
        sportinfo.practice[segment][1] = V.gameday;
    }
}

setup.ob_sports.individually_practice_segment = function(sport, segment)
{
    // practice a segment individually, increasing the player's experience with it (not the team's)
    if (!V.individualpractice) V.individualpractice = {};
    if (!V.individualpractice[sport]) V.individualpractice[sport] = {};
    let sportinfo = V.individualpractice[sport];
    if (!sportinfo[segment])
        sportinfo[segment] = [1, V.gameday];
    else
    {
        sportinfo[segment][0]++;
        sportinfo[segment][1] = V.gameday;
    }
}

setup.ob_sports.practice_routine = function(sport, routine)
{
    // practice a routine, specifically by practicing all segments that are a part of it
    let segments = this.get_segments(routine);
    for (let segment of segments)
        this.practice_segment(sport, segment);
}

setup.ob_sports.individually_practice_routine = function(sport, routine)
{
    // practice a routine, specifically by practicing all segments that are a part of it (for the player only)
    let segments = this.get_segments(routine);
    for (let segment of segments)
        this.individually_practice_segment(sport, segment);
}

setup.ob_sports.get_practice_level = function(sport, segment)
{
    // get the number of times a segment has been practiced by the team
    if (typeof segment == "object") segment = segment.name;
    let sportinfo = V.sportsteams[sport];
    if (!sportinfo?.practice?.[segment])
        return 0;
    else
        return Math.min(sportinfo.practice[segment][0], 21);
}

setup.ob_sports.get_individual_practice_level = function(sport, segment)
{
    // get the number of times a segment has been practiced by the player
    if (!V.individualpractice) return 0;
    if (typeof segment == "object") segment = segment.name;
    let sportinfo = V.individualpractice[sport];
    if (!sportinfo?.[segment])
        return 0;
    else
        return Math.min(sportinfo[segment][0], 21);
}

setup.ob_sports.most_difficult_individual_practiced_segment_of_type = function(sport, type)
{
    if (!V.individualpractice) return;
    if (!V.individualpractice[sport]) return;

    let keys = Object.keys(V.individualpractice[sport]).filter(key => setup.ob_sports.routineSegments[key].type == type);
    let sorted = [];
    for (let key of keys)
        sorted.push([key, this.get_individual_practice_difficulty_modifier(sport, key)]);

    sorted.sort((a, b) => b[1] - a[1]);

    if (sorted.length > 0)
        return sorted[0][0];
}

setup.ob_sports.get_practice_difficulty_modifier = function(sport, segment)
{
    // determine the modifier to difficulty based on amount of practice by the team
    let practice = this.get_practice_level(sport, segment);
    return this.practice_level_to_difficulty_modifier(practice);
}

setup.ob_sports.get_individual_practice_difficulty_modifier = function(sport, segment)
{
    // determine the modifier to difficulty based on amount of practice by the player
    let practice = this.get_individual_practice_level(sport, segment);
    return this.practice_level_to_difficulty_modifier(practice);
}

setup.ob_sports.practice_level_to_difficulty_modifier = function(practice)
{
    // convert number of practices into skill difficulty modifier
    if (!practice)
        return 4;
    else if (practice < 2)
        return 3;
    else if (practice < 4)
        return 2;
    else if (practice < 6)
        return 1;
    else if (practice < 8)
        return 0;
    else if (practice < 11)
        return -1;
    else if (practice < 15)
        return -2;
    else if (practice < 21)
        return -3;
    else
        return -4;
}

setup.ob_sports.get_average_routine_difficulty_modifier = function(sport, routine)
{
    let segments = this.get_segments(routine);
    let tmod = 0;
    for (let segment of segments)
        tmod += this.get_practice_difficulty_modifier(sport, segment);
    return Math.round(tmod / segments.length);
}

setup.ob_sports.selected_routine = function(sport)
{
    // return the currently selected routine for a sports team
    return V.sportsteams[sport]?.selectedRoutine;
}

setup.ob_sports.prepare_routine = function(sport, routine, exclude = [])
{
    // convert a routine string into a routine object, do role assignments
    let routineobj = Object.assign({}, this.get_routine(routine));
    routineobj.name = typeof routine == "object" ? routine.name : routine;
    this.populate_assignments(sport, routineobj, exclude);
    return routineobj;
}

setup.ob_sports.prepare_routine_with_pc = function(sport, routine)
{
    // convert a routine string into a routine object, do role assignments (assigning PC to all roles)
    let routineobj = Object.assign({}, this.get_routine(routine));
    routineobj.name = typeof routine == "object" ? routine.name : routine;
    this.populate_assignments_with_pc(sport, routineobj);
    return routineobj;
}

setup.ob_sports.select_routine = function(sport, routine)
{
    // assign a specific routine to a sports team to be practiced and eventually scored
    return V.sportsteams[sport].selectedRoutine = this.prepare_routine(sport, routine);
}

setup.ob_sports.get_routine_name = function(routine)
{
    // get the name string for the routine, which might be an object or already a string
    if (typeof routine == "string")
        return routine;
    else
        return routine.name;
}

setup.ob_sports.has_succeeded_at_routine = function(sport, routine)
{
    // has the team succeeded at this routine before?
    if (!V.sportsteams[sport].routineHistory) return false;
    let name = this.get_routine_name(routine);
    if (!(name in V.sportsteams[sport].routineHistory)) return false;
    return V.sportsteams[sport].routineHistory[name][0];
}

setup.ob_sports.has_attempted_routine = function(sport, routine)
{
    // has the team attempted this routine before?
    if (!V.sportsteams[sport].routineHistory) return false;
    let name = this.get_routine_name(routine);
    if (!(name in V.sportsteams[sport].routineHistory)) return false;
    else return true;
}

setup.ob_sports.pick_routine = function(sport, team = setup.School.team.name, exclude = [])
{
    // select a routine for the team to attempt next, based on past successes
    const progression = ["cheerleading"]; // these sports attempt one routine until they succeed at it
    const practiceall = ["swimming"]; // these sports have routines that don't get scored in a game as such, so use practice progression only
    let routines = this.routines_for(sport).filter(r => !exclude.includes(r));
    routines = this.sort_by_difficulty(routines);

    let ability = setup.School.team_ability_random(team, sport);
    let ourteam = team == setup.School.team.name && V.pcsports.includes(sport);
    let incheerleading = V.pcsports && V.pcsports.includes("cheerleading");

    let maxaccomplished = 0;
    if (!ourteam && incheerleading)
        for (let routine of routines)
            if (this.has_succeeded_at_routine(sport, routine))
            {
                let diff = this.routine_difficulty(routine);
                if (diff > maxaccomplished)
                    maxaccomplished = diff;
            }

    if (progression.includes(sport) || !ourteam)
    {
        for (let routine of routines)
            if (ourteam && !this.has_succeeded_at_routine(sport, routine))
                return routine;
            else if (routine == routines[routines.length - 1])
                return routine;
            else if (!ourteam && ability >= this.routine_difficulty(routine))
                // other teams pick routine based on what Elks have accomplished, so there's progressive difficulty
                if (!incheerleading)
                    return routine;
                else if (this.routine_difficulty(routine) > maxaccomplished)
                    continue;
                else if (!maxaccomplished && routine == routines[0])
                    return routine;
                else
                    return routine;
    }
    else if (practiceall.includes(sport))
    {
        // look at practice progress only
        let possible = [];
        for (let routine of routines)
        {
            let difficulty = this.routine_difficulty(routine) + this.get_average_routine_difficulty_modifier(sport, routine);

            let score = 100;
            if (difficulty <= 2)
                score = 20;
            else if (difficulty <= 5)
                score = 200;
            else if (difficulty <= 7)
                score = 40;
            else
                score = 5;

            possible.push(routine, score);
        }
        return setup.ob_randomrelfreq(possible);
    }
    else
    {
        // need to be less deterministic
        let possible = [];
        for (let routine of routines)
        {
            let score = 100;
            if (this.has_succeeded_at_routine(sport, routine))
                score = 40;
            else if (this.has_attempted_routine(sport, routine))
                score = 200;
            else if (!maxaccomplished)
            {
                if (this.routine_difficulty(routine) > 3)
                    score = 5;
                else
                    score = 200;
            }
            else if (maxaccomplished && this.routine_difficulty(routine) > maxaccomplished + 2)
                score = 10;

            possible.push(routine, score);
        }
        return setup.ob_randomrelfreq(possible);
    }

    return routines[routines.length - 1];
}

setup.ob_sports.pick_play = function(sport)
{
    // similar to pick_routine, but we're specifically seeking out a well-practiced play to use during a game, with no direct interest in the one currently being practiced

    let routines = this.routines_for(sport);
    let sorted = [];

    for (let routine of routines)
    {
        let diff = this.get_average_routine_difficulty_modifier(sport, routine);
        let pickscore = {"-4": 100, "-3": 80, "-2": 60, "-1": 50, "0": 50, "1": 40, "2": 25, "3": 10, "4": 5}[diff.toString()];
        if (diff <= 2)
            sorted.push(routine, pickscore);
    }

    if (sorted.length == 0) return;

    return setup.ob_randomrelfreq(sorted);
}

setup.ob_sports.role_info = function(segment, role)
{
    // convert a role array into an object
    if (Array.isArray(role))
        return {name: role[0], skill: role[1], difficulty: role[2]};

    const seginfo = this.segment_info(segment);
    const roles = seginfo.roles;
    for (let roleinfo of roles)
        if ((typeof role == "string" && roleinfo[0] == role) || (typeof role == "object" && roleinfo[0] == role.name))
            return {name: roleinfo[0], skill: roleinfo[1], difficulty: roleinfo[2]};
}

setup.ob_sports.skill_level = function(npc, skill)
{
    // get the skill level, with handling for pseudoskills like physicality and athleticism
    npc = V.pc.equals(npc) ? V.pc : setup.people.expand(npc);
    if (skill == "Physicality")
        return npc.physicality();
    else if (skill == "Athleticism")
        return npc.athleticism();
    else
        return npc.skill_level(skill);
}

setup.ob_sports.get_team = function(sport)
{
    // return the NPCs on a team, plus the PC if applicable
    let team = [...V.sportsteams[sport].team];

    if (V.pcsports && V.pcsports.includes(sport))
    {
        let playing;
        if (sport != "football")
            playing = true;
        else if (!V.sport)
            playing = true;
        else
            playing = V.sport.playeringame;

        if (playing)
            team.unshift("PC");
    }

    return team;
}

setup.ob_sports.most_skilled_on_team = function(sport, skill, exclude = [])
{
    // get the most skilled NPC on the team

    let team = this.get_team(sport);

    if (V.gameyear > 1 && team.length < setup.School.sports[sport]["team size"])
        setup.people.refill_sports_teams();

    let skilllist = [];

    for (let npc of team)
        if (!exclude.includes(npc))
            skilllist.push([npc, this.skill_level(npc, skill)])
    return skilllist.sort((a, b) => b[1] - a[1])[0][0];
}

setup.ob_sports.suitable_roles = function(npc, segment)
{
    // get all the roles that an NPC has the skills for

    if (setup.people.find_niche(npc) == "The Star Quarterback")
        return ["quarterback"];

    if (V.pc.equals(npc) && V.pcsports && V.pcsports.includes("esports") && V?.esports?.character)
    {
        switch (V.esports.character)
        {
            case "Umbria":
            case "Osamu":
            {
                return ["shooter", "flanker", "distraction", "ambusher", "bait", "maneuverer", "scout", "utility"]
            }
            case "Irina":
            case "Stefan":
            {
                return ["shooter", "flanker", "distraction", "ambusher", "bait", "maneuverer", "tank"]
            }
            case "Liv":
            case "Rudy":
            {
                return ["shooter", "flanker", "distraction", "ambusher", "maneuverer"]
            }
            case "Leon":
            case "Asuka":
            {
                return ["shooter", "flanker", "distraction", "ambusher", "bait", "maneuverer", "healer"]
            }
        }
    }

    const seginfo = this.segment_info(segment);
    let retval = [];
    for (let role of seginfo.roles)
    {
        if (role[0] == "quarterback") continue;
        let roleinfo = this.role_info(segment, role);
        if (!retval.includes(role[0]) && this.skill_level(npc, roleinfo.skill) >= roleinfo.difficulty)
            retval.push(role[0]);
    }
    return retval;
}

setup.ob_sports.sort_roles = function(sport, segment, exclude = [])
{
    // find an NPC for each role of a segment
    // return an array of role objects each with an npc assigned
    let roles = [...this.segment_info(segment).roles];

    for (let i = 0; i < roles.length; i++)
        roles[i] = this.role_info(segment, roles[i]);

    let used = [...exclude];

    // first, grab NPCs who can pretty much only do one thing and slot them in
    let team = this.get_team(sport);
    let shortteam = team.includes("PC") ? team.slice(0, -1) : team;
    for (let npc of shortteam)
    {
        if (used.includes(npc)) continue;
        let suitable = this.suitable_roles(npc, segment);
        if (suitable.length == 1)
            for (let role of roles)
                if (!role.npc)
                {
                    role.npc = npc;
                    used.push(npc);
                    break;
                }
    }

    // fill remaining roles with the best fit
    let remaining = roles.filter(role => !role.npc);
    for (let role of remaining)
    {
        if (role == remaining[remaining.length - 1] && !used.includes("PC"))
        {
            role.npc = "PC";
            used.push("PC");
        }
        else
        {
            let best = this.most_skilled_on_team(sport, role.skill, used);
            role.npc = best;
            used.push(best);
        }
    }

    return [roles, used];
