setup.ob_sports.populate_assignments = function(sport, routine, exclude = [])
{
    // assign NPCs to roles within each routine segment
    // in this case, 'routine' must come from the stored routine in V.sportsteams

    let used = [...exclude];

    let multi = setup.School.sports[sport].roleInEachSegment;

    for (let i = 0; i < routine.segments.length; i++)
    {
        let segment = routine.segments[i];
        if (typeof segment == "string") segment = Object.assign({}, this.segment_info(segment));
        let sorted = this.sort_roles(sport, segment, multi ? [] : used);
        segment.assignments = sorted[0];
        used = [...used, ...sorted[1]];
        routine.segments[i] = segment;
    }
    return routine.segments;
}

setup.ob_sports.populate_assignments_with_pc = function(sport, routine)
{
    // assign PC to roles within each routine segment
    // in this case, 'routine' must come from the stored routine in V.sportsteams

    for (let i = 0; i < routine.segments.length; i++)
    {
        let segment = routine.segments[i];
        if (typeof segment == "string") segment = Object.assign({}, this.segment_info(segment));

        let roles = [...this.segment_info(segment).roles];
        for (let i = 0; i < roles.length; i++)
        {
            roles[i] = this.role_info(segment, roles[i]);
            roles[i].npc = "PC";
        }

        segment.assignments = roles;
        routine.segments[i] = segment;
    }
    return routine.segments;
}

setup.ob_sports.scored_difficulty = function(segment)
{
    // the difficulty of a segment as used for scoring
    let seginfo = this.segment_info(segment);
    return seginfo.difficulty;
}

setup.ob_sports.adjusted_role_difficulty = function(sport, segment, role, pc = false)
{
    // the difficulty of a specific role with modifier for practice
    segment = this.segment_info(segment);
    let roleinfo = this.role_info(segment, role);
    let diff = roleinfo.difficulty;
    let diffmod = pc ? this.get_individual_practice_difficulty_modifier(sport, segment) : this.get_practice_difficulty_modifier(sport, segment);
    diff += diffmod;
    return Math.max(1, diff);
}

setup.ob_sports.roll_routine = function(sport, routine, diffmod = 0, raiseskill = true)
{
    // roll success or failure for each segment and the routine as a whole, and determine scoring
    // in this case, 'routine' must come from the stored routine in V.sportsteams
    let retval = {routine: routine, name: this.get_routine_name(routine)};
    retval.segments = [...routine.segments];

    let segmentsuccesses = 0;
    let segmentfailures = 0;

    let totalscore = 0;

    for (let segment of retval.segments)
    {
        let successes = 0;
        let failures = 0;
        for (let role of segment.assignments)
        {
            // is it an accident that we're calling skillchecks on V.pc instead of expanding the NPC and calling it on them?
            // no! it's exactly the same result, but far less expensive... we'd be expanding the NPC twice!
            let npc = role.npc;
            let diff = this.adjusted_role_difficulty(sport, segment, role, V.pc.equals(npc)) + diffmod;

            if (role.skill == "Athleticism")
                role.success = setup.people.expand(npc).athleticism_check(diff);
            else if (role.skill = "Physicality")
                role.success = setup.people.expand(npc).physicality_check(diff);
            else
                role.success = V.pc.skillcheck(this.skill_level(npc, role.skill), diff);

            if (V.pc.equals(npc))
            {
                if (role.success && raiseskill)
                {
                    let skill = ["Athleticism", "Physicality"].includes(role.skill) ? "Physical" : role.skill;
                    V.pc.raise_skill(skill, diff);
                }
                segment.pcsuccess = role.success;
                segment.pcrole = role.name;
            }

            if (role.success)
                successes++;
            else
                failures++;
        }
        segment.success = successes > failures;
        segment.criticalsuccess = !failures;
        segment.criticalfailure = !successes;

        let score = segment.difficulty;
        score *= (successes / (successes + failures));
        segment.score = score;

        totalscore += score;

        if (segment.success)
            segmentsuccesses++;
        else
            segmentfailures++;
    }

    retval.success = segmentsuccesses > segmentfailures;
    retval.score = totalscore / retval.segments.length;
    retval.score = parseFloat(retval.score.toFixed(1));

    return retval;
}

setup.ob_sports.record_score = function(sport, routineresult)
{
    // take a routine result and record its success and score in the history for that sport
    if (!V.sportsteams[sport].routineHistory)
        V.sportsteams[sport].routineHistory = {};

    let name = routineresult.name;

    V.sportsteams[sport].routineHistory[name] = [routineresult.success, routineresult.score];
}

setup.ob_sports.routines_for = function(sport)
{
    // all routines valid for the given sport, whether prebuilt or added later
    let retval = Object.keys(this.prebuiltRoutines).filter(routine => this.prebuiltRoutines[routine].sports.includes(sport));

    if (V.sportsteams[sport].routines)
        retval = [...retval, ...Object.keys(V.sportsteams[sport].routines)];

    return retval;
}

setup.ob_sports.sort_by_difficulty = function(routines)
{
    // return a list of the given routines sorted by difficulty
    let retval = [];
    for (let routine of routines)
    {
        let diff = this.routine_difficulty(routine);
        retval.push([routine, diff]);
    }
    retval.sort((a, b) => b[1] - a[1]);
    return retval.map(el => el[0]);
}

setup.ob_sports.segments_for_sport = function(sport)
{
    return Object.keys(this.routineSegments).filter(seg => this.routineSegments[seg].sports.includes(sport));
}

setup.ob_sports.pc_role = function(segment)
{
    // find the pc's role within a given segment
    // (must be a complete segment with assignments populated)
    for (let role of segment.assignments)
        if (V.pc.equals(role.npc))
            return role;
}

setup.ob_sports.captain = function(sport)
{
    let team = V.sportsteams[sport];
    return team.captain;
}
