setup.record_sex_memory = function(person, act, secret = false)
{
	let key = typeof person == "object" ? person.person : person;
	key = setup.people.get_name(key);
	if (!V.sexmemoryanon) State.setVar("$sexmemoryanon", {});
	let memory = secret ? V.sexmemoryanon : V.sexmemory;
	if (!(key in memory)) memory[key] = {};
	if (!(act in memory[key]))
	{
		memory[key][act] = 1;
	}
	else
	{
		memory[key][act]++;
	}

	this.add_to_sex_stats(act);

	const notsex = ["kissed", "disciplined", "cheated on", "cheated with", "helped cheat", "orgasm received", "orgasm given", "virginity taken", "oral virginity taken", "anal virginity taken", "remote orgasm given", "remote orgasm received", "lastDay"];
	const butstillamilestone = ["kissed"];

	if (!notsex.includes(act))
	{
		if (!V.pc.equals(person))
			V.lastsexday = V.gameday;
		else
			memory[key].lastSexDay = V.gameday;
	}

	if (!V.pc.equals(person) && (!notsex.includes(act) || butstillamilestone.includes(act)))
		setup.ob_relationships.check_milestones(person);

	return memory[key][act];
}

setup.count_sex_memory = function(person, act)
{
	let key = typeof person == "object" ? person.person : person;
	key = setup.people.get_name(key);
	let memory = V.sexmemory;
	if (!memory) return 0;
	if (!memory[key]) return 0;
	return memory[key][act] || 0;
}

setup.add_to_sex_stats = function(act)
{
	let sexstats = V.sexstats;
	if (!(act in sexstats))
		sexstats[act] = 1;
	else
		sexstats[act]++;
}

setup.ob_count_sex_stat = function(act)
{
	let sexstats = V.sexstats;
	if (!(act in sexstats))
		return 0;
	else
		return sexstats[act];
}

setup.last_sex_day = function(person)
{
	// the day we last had sex with this person
	// (not a reliable test of whether we've had sex ever)

	let last = this.count_sex_memory(person, "lastSexDay"); // a bit of a hack since this is not actually a count but rather a gameday
	if (!last && setup.people.has_had_sex(person)) // legacy — if we've had sex but last day wasn't recorded, return today
		return V.gameday;
	else if (!last)
		return 1;
	return last;
}

setup.ob_days_since_sex = function(person)
{
	return V.gameday - this.last_sex_day(person);
}

setup.build_outfit = function(gender, parts, outfit, rng = new RNG(), coloroverride = [], forpc=false, day = V.day, fornpc = null, findtight = [])
{
	// convert outfit profile into array of actually worn clothing objects
	const items = setup.ob_outfits[outfit]["items"];
	const retval = [];
	let underwearrng = new RNG(rng.seed);
	day = day - 1;
    while (day > 6) day -= 7;
	while (day > 0) { day--; underwearrng.random(); }

	let palette;
	if (setup.ob_outfits[outfit]["reuse_palette"] && setup.ob_last_palette)
	{
		palette = setup.ob_last_palette;
	}
	else if (setup.ob_outfits[outfit]["palette_group"])
	{
		let pgroup = setup.ob_palette.groups[setup.ob_outfits[outfit]["palette_group"]];
		palette = setup.ob_palette.colors[rng.randomrelfreq(pgroup)];
		setup.ob_last_palette = palette;
	}

	for (let i = 0; i < items.length; i++)
	{
		let item = items[i];
		// some items have prereqs, so we might be skipping them
		// if we're building the outfit for a custom gender, ignore "if gender" prereqs in favor of "if custom gender" prereqs
		// use "if part" and "if not part" checks regardless of custom gender, though
		if (gender != "custom" && "if gender" in item && item["if gender"].indexOf(gender) == -1) continue;
		else if (gender == "custom" && "if custom gender" in item && item["if custom gender"].indexOf(setup.ob_get_gender_node("custom", "pronouns")) == -1) continue;
		else if ("if part" in item && parts.indexOf(item["if part"]) == -1) continue;
		else if ("if not part" in item && parts.indexOf(item["if not part"]) != -1) continue;
		else if ("if outdoors" in item && item["if outdoors"] != setup.ob_location_is_outdoors()) continue;  // weather clothes
		else if ("if weather" in item && item["if weather"].indexOf(setup.ob_get_weather()) == -1) continue;  // weather clothes
		else if ("if temperature" in item && item["if temperature"].indexOf(setup.ob_get_temperature()) == -1) continue;  // weather clothes
		else if ("if cold" in item && item["if cold"] != setup.ob_weather_is_cold()) continue;  // weather clothes
		else if ("if hot" in item && item["if hot"] != setup.ob_weather_is_hot()) continue;  // weather clothes
		else if ("if wet" in item && item["if wet"] != setup.ob_weather_is_wet()) continue;  // weather clothes
		else if (fornpc && "if subrules" in item && !setup.ob_relationships.get_subrules(fornpc).includesAll(item["if subrules"])) continue;
		else if (fornpc && "if no subrules" in item && setup.ob_relationships.get_subrules(fornpc).includesAny(item["if no subrules"])) continue;
		else
		{
			let cinfo = setup.clothes[item["item"]];

			let tightsubs = null;
			if (findtight.includes("pants") && cinfo.category == "bottoms" && cinfo.covers.includes("crotch"))
				tightsubs = setup.ob_skintight_pants_subs;
			else if (findtight.includes("top") && cinfo.category == "tops" && cinfo.covers.includes("chest"))
				tightsubs = setup.ob_skintight_top_subs;

			let trng = cinfo.category == "underwear" && !forpc ? underwearrng : rng;
			let name = cinfo.name;
			let colors_used = [];
			// how the item is displaced (unzipped, pulled up) which will mostly be an empty array for a new item but sometimes will not
			const displacements = [];
			const subs = {};
			for (const [ckey, cvalue] of Object.entries(cinfo))
			{
				if (ckey.indexOf("sub") == 0)
				{
					// handle substitutions in the name string (mostly color)
					// the outfit profile can override the sub selection so we check that too
					let subname = ckey.substring(4);
					let sublist = [...(ckey in item ? item[ckey] : cvalue)];

					// use only colors from the palette, if possible
					if (palette && palette.length > 0)
					{
						let subpalette = palette.filter(col => sublist.includes(col));
						if (subpalette.length > 0) sublist = subpalette;
					}

					// don't use the same color twice for the same item (no "blue and blue striped sweater")
					if (subname.indexOf("color") == 0 && sublist.length > colors_used.length && colors_used.length > 0)
					{
						for (let j = 0; j < colors_used.length; j++)
						{
							let k = sublist.indexOf(colors_used[j]);
							if (k >= 0) sublist.splice(k, 1);
						}
					}

					if (tightsubs)
					{
						let tightonly = sublist.filter(v => tightsubs.includes(v));
						if (tightonly.length > 0) sublist = tightonly;
					}

					let sub = trng.randomchoice(sublist);

					if (coloroverride.length > 0)
					{
						if (subname == "color" || subname == "color1")
							sub = coloroverride[0] || sub;
						else if (subname == "color2")
							sub = coloroverride[coloroverride.length - 1] || sub;
						else if (subname == "color3")
							sub = coloroverride[coloroverride.length - 2] || sub;
					}
					name = name.replace("%" + subname, sub);
					subs[subname] = sub;
					if (subname.indexOf("color") == 0) colors_used.push(sub);
				}
				else if (ckey.indexOf("displace") == 0 && cinfo.flags.indexOf("default open") != -1 && displacements.length == 0)
				{
					// apply a displacement if this item is usually worn open (unzipped, unbuttoned)
					let displace = ckey.substring(9);
					displacements.push(displace);
				}
			}

			// put it all together into object that will live on the entity
			// we just need to store stuff that can be unique about this specific item of clothing
			// any static info we can look up from the clothing database as needed
			let thisitem = {"name": name, "item": item["item"], "displacements": displacements, subs: subs};
			retval.push(thisitem);
		}
	}
	return retval;
}

setup.ob_all_underwear = function(name)
{
	// all underwear that an npc wears
	let npc = new Person({person: setup.people.get_name(name)});
