setup.ob_english_clothing = function(clothing, short = false)
{
	const retval = [];
	for (let i = 0; i < clothing.length; i++)
	{
		let clothstr;
		let pair = clothing[i].indexOf("pair of") != -1 || clothing[i].indexOf("glasses") != -1 || clothing[i].indexOf("set of") != -1;
		if (short)
		{
			let words = clothing[i].split(' ');
			let preps = ["that's", "on", "in", "with", "embossed", "for", "embroidered", "lined"];
			for (let i = 0; i < preps.length; i++)
			{
				let j = words.indexOf(preps[i]);
				if (j > 0) words = words.slice(0, j);
			}

			let j = words.indexOf("and");
			if (j > 0 && words[j + 1] == "cuffs") // special exception just for collar + cuffs
				words = words.slice(0, j);

			for (let k = 0; k < words.length; k++)
				if (words[k].endsWith("'"))
				{
					words = words.slice(k + 1);
					break;
				}

			let stain = null;
			for (let i = 0; i < words.length; i++)
			{
				if (words[i].indexOf("stained") >= 0)
					stain = words[i];
			}
			if (words.length == 1) clothstr = (stain ? stain + " " : "") + words[0];
			else clothstr = (stain ? stain : words[words.length - 2]) + " " + words[words.length - 1];

			if (clothstr.indexOf("of ") == 0) clothstr = clothstr.slice(3);
		}
		else
		{
			clothstr = clothing[i].replace("plain ", "");
		}
		//let plural = clothing[i].substring(clothing[i].length - 1) == "s";
		clothstr = ((pair) ? "" : (setup.ob_a_or_an(clothstr) + " ")) + clothstr;
		clothstr = clothstr.replace("pair of ", "");
		clothstr = clothstr.replace("set of ", "");
		clothstr = clothstr.replace("a piece ", "a ");
		clothstr = clothstr.replace("a sleeve ", "a ");
		clothstr = clothstr.replace("a height ", "a ");
		retval.push(clothstr);
	}
	let and = setup.ob_and(retval);
	return and;
}

