setup.ob_get_tooltip_person = function(person)
{
	let retval = "";
	let pobj = new Person({person: person});

	if (!pobj.is_pc && !pobj.temporary && V.opttooltips)
	{
		let relwith = setup.ob_relationships.relationship_with(person);
		let anon = setup.people.is_anonymous(pobj);

		// name or description
		if (setup.people.can_identify_name(pobj) || relwith)
		{
			retval += pobj.fullname();
			let niches = setup.people_niches();
			let nichekeys = Object.keys(niches);
			for (let i = 0; i < nichekeys.length; i++)
			{
				if (niches[nichekeys[i]] == person)
				{
					retval += " (" + nichekeys[i] + ")";
					break;
				}
			}
		}
		else
		{
			retval += setup.people.anonymous_name(person);
		}

		// emoji
		let badges = setup.people.get_badges(person).filter(badge => !badge.invisible);
		if (badges.length > 0 && V.optshowemojis)
		{
			retval += " ";
			for (let i = 0; i < badges.length; i++)
				retval += badges[i].icon;
		}
		retval += "\n";

		if (!anon || relwith)
		{
			// relationship
			if (relwith)
				retval += setup.ob_relationships.label(relwith, person) + "\n";
			else if (V.crush && V.crush == person)
				retval += "crush\n";
			else if (setup.people.is_ex(person))
				retval += "ex\n";
			else if (setup.people.is_admirer(person))
				retval += "admirer\n";

			// had sex
			if (setup.people.has_had_sex(person))
				retval += "You've had sex with " + setup.people.pronouns(person).po + ".\n";
			else if (setup.people.is_sexpartner(person))
				retval += "You've messed around with " + setup.people.pronouns(person).po + ".\n";

			// attitude
			let friendship = setup.people.get_attitude(person, "friendship") / 10;
			if (friendship >= 0)
			{
				friendship = Math.min(friendship, 100);
				retval += "Friendship:\t" + Math.round(friendship) + "%\n";
			}
			else
			{
				friendship = Math.min(Math.abs(friendship), 100);
				retval += "Dislike:\t\t" + Math.round(friendship) + "%\n";
			}

			let lust = setup.people.get_attitude(person, "lust") / 10;
			lust = Math.min(lust < 0 ? 0 : lust, 100);
			retval += "Lust:\t\t" + Math.round(lust) + "%\n";

			let romance = setup.people.get_attitude(person, "romance") / 10;
			romance = Math.min(romance < 0 ? 0 : romance, 100);
			retval += "Romance:\t" + Math.round(romance) + "%\n";

			if (Math.abs(setup.people.get_attitude(person, "control")) >= 100 || ((setup.people.has_any_inclination(person, "submissive") || setup.people.has_any_inclination(person, "dominant")) && Math.abs(setup.people.get_attitude(person, "control")) > 0))
			{
				let control = setup.people.get_attitude(person, "control") / 10;
				if (control > 0)
				{
					control = Math.min(control, 100);
					retval += "Dominance:\t" + Math.round(control) + "%\n";
				}
				else
				{
					control = Math.min(Math.abs(control), 100);
					retval += "Submission:\t" + Math.round(control) + "%\n";
				}
			}
		}
	}

	if (retval != "") retval += "\n";
	return retval + "Click to view person";
}

