setup.orientation_for = function(gender, rng = new RNG())
{
	// with the given gender, what orientation do they need to be to be attracted to the pc?
	let orientations = setup.ob_get_gender_node(gender, "attraction");
	let weighted = [];
	for (let i = 0; i < orientations.length; i++)
	{
		if (typeof orientations[i] == "object" && orientations[i].genders.includes(setup.ob_pcgender()))
		{
			weighted.push(orientations[i].label, orientations[i + 1]);
		}
	}
	return rng.randomrelfreq(weighted);
}

setup.ob_orientation_and_gender_for = function(rng = new RNG(), niche = null, gender = setup.ob_pcgender(), prefs = V.pcsexualprefs)
{
	// find a gender/sexual orientation that will result in an NPC mutually attracted to the PC
	// used for lots of NPC generation stuff, naturally

	if (niche && setup.people.allowed_genderpick_niches.includes(niche) && V.nichegenderpicks && V.nichegenderpicks[niche] && V.pcsexualprefs.includes(V.nichegenderpicks[niche]))
		prefs = [V.nichegenderpicks[niche]];

	if (typeof prefs == "string")
	{
		// look up orientation genders if we got a label instead of a list
		let queer = ["queer", "gay", "lesbian"];
		orientations = setup.ob_get_gender_node(gender, "attraction");
		for (let i = 0; i < orientations.length; i++)
		{
			if (typeof orientations[i] == "object")
			{
				if (orientations[i].label == prefs)
				{
					prefs = orientations[i].genders;
					break;
				}
				else if (queer.includes(orientations.label) && queer.includes(prefs))
				{
					prefs = orientations[i].genders;
					break;
				}
			}
		}
	}

	const othergenders = [];
	let distrib = V.studentgenderdistribution;
	for (let i = 0; i < distrib.length; i += 2)
	{
		if (prefs.includes(distrib[i]))
			othergenders.push(distrib[i], distrib[i + 1]);
	}

	let othergender = rng.randomrelfreq(othergenders);

	const otherprefs = [];
	for (let i = 0; i < setup.ob_get_gender_node(othergender, "attraction").length; i++)
	{
		let tpref = setup.ob_get_gender_node(othergender, "attraction")[i];
		if (typeof tpref == "object" && tpref.genders.includes(gender))
			otherprefs.push(tpref, setup.ob_get_gender_node(othergender, "attraction")[i + 1]);
	}

	let otherpref = rng.randomrelfreq(otherprefs);

	return {gender: othergender, attraction: otherpref.label};
}

