							retval += '<img id="maparrowclassimg-mobile" src="https://cdn.jsdelivr.net/gh/PEEPEEBOY69/nohbdy-assets@obscura-v20/obscura/img/locmarker_social.png" style="left: ' + marker[0] + 'px; top: ' + marker[1] + 'px; width: ' + markerwidth + 'px; height: ' + markerheight + 'px">';
						}
						else if (V.location != dateloc && dateloc in setup.ob_maps.Town.nodes && locblock == "Town")
						{
							let node = setup.ob_maps.Town.nodes[dateloc];
							let marker = {...node.markercoords_mobile};
							marker[0] *= (markerwidth / 11);
							marker[1] *= (markerheight / 11);
							marker[0] -= (3 * (markerwidth / 11));
							marker[1] -= (18 * (markerheight / 11));

							retval += '<img id="maparrowclassimg-mobile" src="https://cdn.jsdelivr.net/gh/PEEPEEBOY69/nohbdy-assets@obscura-v20/obscura/img/locmarker_social.png" style="left: ' + marker[0] + 'px; top: ' + marker[1] + 'px; width: ' + markerwidth + 'px; height: ' + markerheight + 'px">';
						}
					}
				}
			}

			retval += '</div>';

			if (!("nolinks" in config))
			{
				retval += '<map id="imgmap-mobile" name="' + img + '-mobile" class="nokeys">';

				const nodes = setup.ob_maps[locblock].nodes;
				for (const [nodekey, othernode] of Object.entries(nodes))
				{
					let onodename = othernode.name;
					let coords = othernode.imgcoords_mobile;
					let passage = "passage" in othernode ? othernode.passage : nodekey;
					if (node.exits.includes(nodekey))
					{
						let onodetime = "time" in othernode ? othernode.time : setup.ob_travel_time(passage);
						retval += '<area shape="poly" title="' + onodename + '" coords="' + coords + '" data-passage="' + passage + '" onclick="SugarCube.setup.ob_time.advance_time(' + onodetime + ')">';
					}
					else if (nodekey != loc && canfasttravel)
					{
						let path = setup.ob_maps.pathfind(locblock, loc, nodekey);
						if (path)
						{
							let pathlength = path.length - 1;
							let onodetime = "time" in othernode ? othernode.time : setup.ob_travel_time(passage);
							onodetime *= pathlength;
							retval += '<area shape="poly" title="' + onodename + '" coords="' + coords + '" data-passage="' + passage + '" onclick="{SugarCube.setup.ob_time.advance_time(' + onodetime + '); SugarCube.State.setVar(\'' + '$' + 'nextbaseeventchance\', SugarCube.setup.ob_events.base_event_chance() * ' + pathlength + ');}">';
						}
					}
				}

				retval += '</map>';
			}
		}
	}

	return retval;
}

