setup.ob_class_time_status = function()
{
    let currentclass = setup.School.current_class();
	if (currentclass != null && setup.School.classes_today())
	{
		const inclass = V.inclass;
		if (inclass)
		{
			if (inclass in setup.School.sports)
				return { "message": 'At practice: ' + inclass };
			else
				return { "message": 'In class: ' + inclass };
		}
		else if (setup.School.at_class_location(currentclass.course))
		{
			if (currentclass.early)
			{
				return { "message": 'Early for ' + currentclass.course };
			}
			else
			{
				return { "message": 'Time for ' + currentclass.course + '!' };
			}
		}
		else
		{
			let loc = setup.School.class_location(currentclass.course);
			let locname;

			if (loc in setup.ob_maps)
			{
				locname = setup.ob_maps[loc].name;
				loc = setup.ob_maps[loc].outside;
			}
			else if (loc == "BlodgettGymInterior")
			{
				loc = "BlodgettGym";
				locname = setup.ob_maps[loc].name;
			}
			else if (currentclass.course in setup.School.sports)
			{
				loc = setup.School.sports[currentclass.course].outside;
				locname = setup.ob_maps["Campus"].nodes[loc].name;
			}

			if (currentclass.early)
			{
				return { "message": 'Almost time for ' + currentclass.course + ' at ' + locname + '!', "shortcut": loc };
			}
			else
			{
				if (V.pcsports?.includes(currentclass.course) && V.firstpracticeday && V.day < V.firstpracticeday)
					return { "message": 'Optional ' + currentclass.course + ' practice at ' + locname + '!', "shortcut": loc };
				else
					return { "message": '<span class="bad">Late for ' + currentclass.course + ' at ' + locname + '!</span>', "shortcut": loc };
			}
		}
	}
	else if (setup.School.current_game(true))
	{
		const game = setup.School.current_game(true);
		let loc = setup.School.sports[game.type].outside;
		let locname = setup.ob_maps["Campus"].nodes[loc].name;
		if (game.hour > V.hour)
		{
			return { "message": 'Almost time for ' + game.type + ' ' + setup.School.sports[game.type].gamelabel + ' at ' + locname + '!', "shortcut": loc };
		}
		else
		{
			return { "message": '<<highlight bad>>Time for ' + game.type + ' ' + setup.School.sports[game.type].gamelabel + ' at ' + locname + '!<</highlight>>', "shortcut": loc };
		}
	}
	else
	{
		let nextclass = setup.School.next_class();

		if (nextclass.month == V.month && nextclass.day == V.day)
		{
			return { "message": nextclass.course.toUpperFirst() + ' at ' + setup.ob_time.clock(nextclass.hour, 0) };
		}
		else if (setup.ob_time.is_tomorrow(nextclass.month, nextclass.day))
		{
			return { "message": nextclass.course.toUpperFirst() + ' tomorrow at ' + setup.ob_time.clock(nextclass.hour, 0) };
		}
		else
		{
			return { "message": 'Next classes on ' + setup.ob_time.date(nextclass.month, nextclass.day) };
		}
	}
}

