setup.ob_parse_catnotifications = function()
{
	const categorizednotifs = [];
	if (V.catnotifications?.length > 0)
	{
		if (V.catnotifications.filter(item => item[0] === "skilllearn").length > 1)
		{
			const _skills = V.catnotifications.filter(item => item[0] === "skilllearn").map(item => item[1]).join(', ');
			categorizednotifs.push(`You have learned these skills: <span class="notice">` + _skills + `</span>. Keep using them daily to level them up!`);

		}
		else if (V.catnotifications.filter(item => item[0] === "skilllearn").length === 1)
		{
			const _skill = V.catnotifications.filter(item => item[0] === "skilllearn").map(item => item[1]);
			categorizednotifs.push(`You have learned the <span class="notice">` + _skill + `</span> skill. Keep using it daily to level it up!`);
		}

		if (V.catnotifications.filter(item => item[0] === "skilllevel").length > 1)
		{
			const _skills = V.catnotifications.filter(item => item[0] === "skilllevel").map(item => item[1]);
			const _levels = V.catnotifications.filter(item => item[0] === "skilllevel").map(item => item[2]);
			const _list = [];
			for (let i = 0; i < _skills.length; i++) {
    			_list.push(_skills[i] + ": " + _levels[i]);
			}
			categorizednotifs.push(`Your skills have increased! <span class="notice">` + _list.join('; ') + `</span>`);

		}
		else if (V.catnotifications.filter(item => item[0] === "skilllevel").length === 1)
		{
			const _skill = V.catnotifications.filter(item => item[0] === "skilllevel").map(item => item[1]);
			const _level = V.catnotifications.filter(item => item[0] === "skilllevel").map(item => item[2]);
			categorizednotifs.push(`Your <span class="notice">` + _skill + `</span> skill has increased to <span class="notice">` + _level + `</span>!`);
		}

		if (V.catnotifications.filter(item => item[0] === "skillcap").length > 1)
		{
			const _skills = V.catnotifications.filter(item => item[0] === "skillcap").map(item => item[1]).join(', ');
			categorizednotifs.push(`You feel like you've learned all you can today about these skills: <span class="notice">` + _skills + `</span>.`);

		}
		else if (V.catnotifications.filter(item => item[0] === "skillcap").length === 1)
		{
			// Convert to set to fix the rare case where you can cross over to midnight and max out the same skill twice before seeing this notification, causing the same skill to appear twice. Might be better ways to do this.
			const _skill = [...new Set(V.catnotifications.filter(item => item[0] === "skillcap").map(item => item[1]))];
			categorizednotifs.push(`You feel like you've learned all you can today about the <span class="notice">` + _skill + `</span> skill.`);
		}

		if (V.catnotifications.filter(item => item[0] === "milestone").length > 1)
		{
			const _list = V.catnotifications.filter(item => item[0] === "milestone");
			const _milestones = V.catnotifications.filter(item => item[0] === "milestone").map(item => item[2]);

			const _PersonsWithMultipleMilestones = Object.entries(
    			_list.reduce((counts, item) => {
            		counts[item[1]] = (counts[item[1]] || 0) + 1;
            		return counts;
        		}, {}
				)
			).filter(([name, count]) => count > 1)
			 .map(([name]) => name);

			 for (let i = 0; i < _PersonsWithMultipleMilestones.length; i++)
				 {
					categorizednotifs.push(
						`Romance milestones achieved with ` +
						(_PersonsWithMultipleMilestones[i] +
							`: <<highlight romantic>>` +
							V.catnotifications.filter(item => item[0] === "milestone" && item[1] === _PersonsWithMultipleMilestones[i]).map(item => item[2]).join(', ')) +
							 `<</highlight>>`);
				}

			const _PersonsWithSingleMilestones = Object.entries(
    			_list.reduce((counts, item) => {
            		counts[item[1]] = (counts[item[1]] || 0) + 1;
            		return counts;
        		}, {}
				)
			).filter(([name, count]) => count == 1)
			 .map(([name]) => name);

			for (let i = 0; i < _PersonsWithSingleMilestones.length; i++)
				 {
					categorizednotifs.push(`Romance milestones achieved with ` + (_PersonsWithSingleMilestones[i] + `: <<highlight romantic>>` + V.catnotifications.filter(item => item[0] === "milestone" && item[1] === _PersonsWithSingleMilestones[i]).map(item => item[2])) + `<</highlight>>`);
			}
		}
		else if (V.catnotifications.filter(item => item[0] === "milestone").length === 1)
		{
			const _milestones = V.catnotifications.filter(item => item[0] === "milestone").map(item => item[2]);
			categorizednotifs.push(`Romance milestone achieved with ` + V.catnotifications.filter(item => item[0] === "milestone").map(item => item[1]) + `: <<highlight romantic>>` + _milestones + `<</highlight>>`);
		}
		delete V.catnotifications;
	}

	else
	{
		return [];
	}

	return categorizednotifs;

}


