// Get the hours a passage is open based on its tags
// Min inclusive, max exclusive
setup.get_opening_hours = function(passage)
{
	let job = setup.job_at_location(passage);
	if (job && job in setup.ob_business.db && setup.ob_business.db[job].hours)
	{
		return setup.ob_business.db[job].hours;
	}
	else
	{
		let passageObj = Story.get(passage);

		const openHourPrefix = "openhour";
		const closeHourPrefix = "closehour";
		const tags = passageObj.tags;

		if(!tags.includes("location"))
		{
			return null;
		}

		let openHour = 0;
		let closeHour = 0;

		for (const tag of tags)
		{
			if (tag.indexOf(openHourPrefix) == 0)
			{
				openHour = parseInt(tag.substring(openHourPrefix.length));
			}
			else if(tag.indexOf(closeHourPrefix) == 0)
			{
				closeHour = parseInt(tag.substring(closeHourPrefix.length));
			}
		}

		if (openHour == 0 || closeHour == 0 || openHour == closeHour)
		{
			return null;
		}
		return [openHour, closeHour];
	}
}

setup.is_open = function(passage)
{
	if (passage == "ChamberlainHallInterior")
	{
		// harvest eve party exception
		if (setup.ob_is_harvesteve_party_time()) return true;
	}
	const openingHours = this.get_opening_hours(passage);
	if(openingHours == null)
	{
		return true;
	}
	let openHour = openingHours[0];
	let closeHour = openingHours[1];
	let currentHour = V.hour;

	if(closeHour > openHour)
	{
		return openHour <= currentHour && currentHour < closeHour;
	}
	else
	{
		// openHour > closeHour
		return openHour <= currentHour || currentHour < closeHour;
	}
}

setup.ob_is_closed = function(passage)
{
