setup.ob_is_opening_soon = function(passage)
{
	const openingHours = this.get_opening_hours(passage);
	if(openingHours == null)
	{
		return false;
	}
	let openHour = openingHours[0];
	let currentHour = V.hour;

	// If it's the hour right before and 20 minutes (1 wait interval before opening, can wait to open)
	return ((currentHour + 1) % 24 == openHour && V.minute >= 60 - 20);
}

