setup.ob_get_location = function(passage)
{
	let passageobj = Story.get(passage);
	let tags = passageobj.tags;
	for (let i = 0; i < tags.length; i++)
		if (tags[i].indexOf("loc") == 0 && tags[i].indexOf("locblock") == -1 && tags[i].indexOf("location") == -1)
			return tags[i].substring(3);
	return null;
}

setup.ob_get_location_block = function(passage)
{
	let passageobj = Story.get(passage);
	let tags = passageobj.tags;
	if (tags.includes("usepreviouslocblock")) return V.locationblock;
	for (let i = 0; i < tags.length; i++)
		if (tags[i].indexOf("locblock") == 0)
			return tags[i].substring(8);
	return null;
}

setup.ob_get_location_name = function(location)
{
	if (location == "HousingRoom")
		return "your place";
	for (const map of Object.values(setup.ob_maps))
	{
		if (map.nodes)
		{
			for (const [nodename, node] of Object.entries(map.nodes))
			{
				if (nodename == location)
				{
					return node.name;
				}
			}
		}
	}
}

