setup.ob_location_is_outdoors = function(location = V.location)
{
	try
	{
		if (tags().includes("chargen") || !location) return false;
		const passage = Story.get(location);
		const loctags = passage ? Story.get(location).tags : [];
		if (V.hangout && V.hangout.activity != "have a park picnic") return false;
		if (tags().includes("indoors")) return false;
		return loctags.includes("outdoors");

		//if (!location || !setup.ob_maps[location]) return false;
		//return setup.ob_maps[location].outdoors || false;
	}
