setup.restrictive_gender_prefs = function(gender, pref)
{
	// a smaller list so as not to 'surprise' the player
	// mostly about coddling straight people

	let prefs = [];
	const queer = ["gay", "lesbian", "queer"];
	let attraction = setup.ob_get_gender_node(gender, "attraction");
	for (let i = 0; i < attraction.length; i+=2)
		if (attraction[i].label == pref)
			prefs = attraction[i].genders;
		else if (queer.includes(attraction[i].label) && queer.includes(pref))
			prefs = attraction[i].genders;

	if (gender == "male" && pref == "straight")
	{
		prefs = ["female"];
	}
	else if (gender == "female" && pref == "straight")
	{
		prefs = ["male"];
	}

	if (!prefs.includesAny(["male", "female"]))
	{
		// this only happens with custom genders and tends to result in not finding enough NPCs
		let cis = setup.ob_nearest_cisgender(prefs[0]);
		prefs.push(cis);
	}

	return prefs;
}

setup.find_video_game_competitor = function(count = 1, skill = setup.pc().skill_level("Video Gaming"), maxdiff = 1, specialok = false)
{
	// a very specific function used for arcade side bet stuff
	const genders = this.restrictive_gender_prefs(V.pcgender, V.pcsexualpref);
	const retval = [];
	const people = setup.ob_shuffle(Object.keys(V.people));
	for (const p of people)
	{
		if (genders.includes(setup.people.get_gender(p)) && setup.people.get_type(p) != "faculty" && setup.people.get_type(p) != "outsider" && setup.people.attracted_to_pc(p) && Math.abs(skill - setup.people.skill_level(p, "Video Gaming")) <= maxdiff && (specialok || !setup.people.is_special(p)) && !setup.people.is_removed(p))
		{
			retval.push(p);
			if (retval.length == count)
				return retval;
		}
	}
	if (retval.length == 0 && maxdiff < 10)
	{
		return this.find_video_game_competitor(count, skill, maxdiff + 1);
	}
	else
	{
		return retval;
	}
}

