setup.ob_computer = function()
{
	let comp = setup.ob_locationInventory.category_item(setup.ob_locationInventory.myloc(), "computer");
	let laptop = setup.ob_locationInventory.category_item_anywhere("laptop");
	if (V.lastloctags.includes("homebase"))
	{
		if (laptop && comp)
		{
			if (setup.ob_dormstuff[laptop.item].streamQuality.base > setup.ob_dormstuff[comp.item].streamQuality.base)
			{
				return laptop.item;
			}
			else
			{
				return comp.item;
			}
		}
		else if (comp)
		{
			return comp.item;
		}
		else if (laptop)
		{
			return laptop.item;
		}
	}
	else if (setup.ob_housing.is_housing())
	{
		let flags = setup.ob_housing.flags_here();
		if (flags.includes("computer"))
			return setup.ob_housing.room_player_owned() ? (comp?.item || laptop?.item) : "mid-range desktop computer";
		else if (laptop && flags.includesAny(["desk", "chair", "armchair", "futon", "bed", "couch"]))
			return laptop.item;
	}
	else if (V?.lastloctags?.includes("hascomputer") && !V.pc.has_laptop())
	{
		return "mid-range desktop computer";
	}
	else if (!V.pc.has_laptop())
	{
		return null;
	}
	else if (laptop)
	{
		return laptop.item;
	}
}

