setup.is_jock = function()
{
	// whether the PC is successful at sports!!
	// should have specific conditions for each sport
	// but will return true by default if enrolled in any sport

	const pcsports = V.pcsports;
	if (!pcsports || pcsports.length == 0)
		return false;
	else
	{
		let sport = pcsports[0];
		const info = V[sport];
		if (!info)
			return false;
		else
		{
			switch (sport)
			{
				case "esports":
				{
					return !!(info.kills && (info.kills / info.deaths) > 1.5);
				}
				case "football":
				{
					return !!info.proven;
				}
				case "swimming":
				{
					return !!(info.meetpoints && info.meetpoints > 10);
				}
				case "cheerleading":
				{
					return false;
				}
				default:
				{
					return true;
				}
			}
		}
	}
}

