	const retval = [];
	const people = setup.ob_shuffle(Object.keys(V.people));
	for (const p of people)
	{
		if ((genders.includes(setup.people.get_gender(p) || State.random() < 0.2)) && setup.people.get_type(p) != "faculty" && setup.people.get_type(p) != "outsider" && (setup.people.attracted_to_pc(p) || State.random() < 0.2) && Math.abs(skill - setup.people.skill_level(p, "Artistic")) <= maxdiff && (specialok || !setup.people.is_special(p)) && !setup.people.is_removed(p))
