setup.underwear_sell_value = function(underwear)
{
	// I once saw a thread on reddit that was something like
	// "code snippets that reveal you're definitely making an adult game"
	// and sometimes as I'm working I think of it
	let minprice = 10;
	let base = minprice;
	if (!underwear.properties || !underwear.properties.stains)
	{
		base = minprice;
	}
	else
	{
		const stains = underwear.properties.stains;
		if (stains.includes("arousal"))
		{
			if (V.pc.has_part("vagina"))
				base += 100;
			else
				base += 50;
		}
		if (stains.includes("cum"))
		{
			if (V.pc.has_part("penis"))
				base += 100;
			else
				base += 50;
		}
		if (stains.includes("pee"))
		{
			base += 50;
		}
	}

	return Math.min(Math.max(minprice, Math.round(base * this.underwear_sell_multiplier())), 200); // this is math
}

setup.underwear_sell_multiplier = function()
{
	let sold = V.underwearsolddays;
	if (sold == undefined)
	{
		return 2;
	}
	else
	{
		let recentlysold = [];
		for (let day of sold)
			if (V.gameday - day <= 14)
				recentlysold.push(day);
		V.underwearsolddays = recentlysold;
		return 0.5**recentlysold.length; // this is math
	}
}

