setup.ob_get_roomtype = function(tpassage)
{
	// determine roomtype dynamically

	if (tpassage)
	{
		let tags = Story.get(tpassage).tags;
		for (let tag of tags)
			if (tag.indexOf("roomtype") == 0)
				return tag.substring(8);
		return "empty";
	}
	else if (V.attemptednavigation && setup.ob_get_roomtype(V.lastlocpassage) == V.roomtype)
	{
		return setup.ob_get_roomtype(V.attemptednavigation);
	}
	else return setup.ob_roomtype();
}

setup.room_contents = function()
{
	if (setup.ob_housing.is_housing())
	{
		// we're in housing! build contents dynamically from what's actually in the room
		let furniturekeys = ["large floor", "wall", "window"];
		const flags = setup.ob_housing.get_flags(V.housing.key, V.housing.roomID, V.housing.owner);
		furniturekeys = [...furniturekeys, ...flags.filter(flag => flag in setup.ob_roomTypes.furniture)];

		let retval = {};
		for (let furniture of furniturekeys)
			retval[furniture] = {};

		return retval;
	}
	else
	{
		let rt = setup.ob_get_roomtype();
		const rtinfo = setup.ob_roomTypes.db[rt];
		if (!rtinfo)
		{
			console.warn(`Invalid roomtype ${V.roomtype} at location ${V.location}`);
			return setup.ob_roomTypes.db['empty'].contents;
		}
		else
		{
			return rtinfo.contents;
		}
	}
}

