setup.ob_roll_random_outfit = function(config = {})
{
	let top,bottom,shoes,bra,underwear,bag;
	let tops = [];
	let bottoms = [];
	let shoeses = []; // shoes is already plural, what else can i do
	let dresses = [];
	let bras = [];
	let underwears = [];
	let binders = [];
	let bags = [];

	const clothingitems = [...V.pc.get_storage_location("dormcloset").clothes, ...V.pc.clothes];

	tops = clothingitems.filter(item => setup.clothes[item.item].category == "tops" && (!setup.clothes[item.item]["style factor"] || !setup.clothes[item.item]["style factor"]["costume"]) && item.item != "QuickieBurger Polo");
	bottoms = clothingitems.filter(item => setup.clothes[item.item].category == "bottoms" && (!setup.clothes[item.item]["style factor"] || !setup.clothes[item.item]["style factor"]["costume"]));
	shoeses = clothingitems.filter(item => setup.clothes[item.item].category == "footwear" && (!setup.clothes[item.item]["style factor"] || !setup.clothes[item.item]["style factor"]["costume"]));
	dresses = clothingitems.filter(item => setup.clothes[item.item].category == "dresses" && (!setup.clothes[item.item]["style factor"] || !setup.clothes[item.item]["style factor"]["costume"]));
	bras = clothingitems.filter(item => setup.clothes[item.item].category == "underwear" && (!setup.clothes[item.item]["style factor"] || !setup.clothes[item.item]["style factor"]["costume"]) && setup.clothes[item.item].covers.includes("breasts") && !setup.clothes[item.item].flags.includes("hide breasts"));
	binders = clothingitems.filter(item => setup.clothes[item.item].category == "underwear" && (!setup.clothes[item.item]["style factor"] || !setup.clothes[item.item]["style factor"]["costume"]) && setup.clothes[item.item].covers.includes("breasts") && setup.clothes[item.item].flags.includes("hide breasts"));
	underwears = clothingitems.filter(item => setup.clothes[item.item].category == "underwear" && (!setup.clothes[item.item]["style factor"] || !setup.clothes[item.item]["style factor"]["costume"]) && setup.clothes[item.item].covers.includes("crotch"));
	bags = clothingitems.filter(item => setup.clothes[item.item].category == "bags" && setup.clothes[item.item].storage.length > 2);

	top = setup.ob_randomchoice([...tops, ...dresses]);

	if (!top) return;
	if (!dresses.includes(top))
	{
		bottom = setup.ob_randomchoice(bottoms);
		if (!bottom) return;
	}

	if (!("includebra" in config) || config.includebra)
	{
		bra = setup.ob_randomchoice(bras);
		if (!bra && !config.includebinder) return;
	}

	if (!("includeunderwear" in config) || config.includeunderwear)
	{
		underwear = setup.ob_randomchoice(underwears);
		if (!underwear) return;
	}

	if (config.includebinder)
	{
		bra = setup.ob_randomchoice(binders);
		if (!bra) return;
	}

	if (!("includeshoes" in config) || config.includeshoes)
	{
		shoes = setup.ob_randomchoice(shoeses);
		if (!shoes) return;
	}

	if (!("includebag" in config) || config.includebag)
		{
			bag = setup.ob_randomchoice(bags);
			if (!bag) return;
		}

	let outfit = [];
	if (top) outfit.push(top);
	if (bottom) outfit.push(bottom);
	if (bra) outfit.push(bra);
	if (underwear) outfit.push(underwear);
	if (shoes) outfit.push(shoes);
	if (bag) outfit.push(bag);

	outfit = outfit.map(item => item instanceof ClothingItem ? item.get_data_structure() : item);

	if (!V.pc.test_wear_outfit(outfit)) return;

	let name = top.item;
	if (bottom) name += " and " + bottom.item;

	let oname = name;
	let n = 1;
	while (V.pc.is_outfit_name_taken(name))
	{
		name = oname + " " + n;
		n++;
	}

	return {name: name, clothes: outfit, type: "Casual"};
}

