setup.ob_implement_proclivity = function(proclivity)
{
	// strictly for chargen... set everything up according to the proclivity the player chose
	let info = setup.ob_sexualities[proclivity];
	for (let [skill, lvl] of Object.entries(info.skills))
	{
		if (skill == "bits")
		{
			if (V.pc.has_part("penis"))
				skill = "Penetrative";
			else
				skill = "Vaginal";
		}
		lvl *= 100;
		if (!V.pcskills[skill])
			V.pcskills[skill] = lvl;
		else
			V.pcskills[skill] += lvl;
	}

	if (!V.pcstartinginclinations) V.pcstartinginclinations = [];
	if (info.inclinations)
	{
		for (let inc of info.inclinations)
		{
			if (!V.pcstartinginclinations.includes(inc)) V.pcstartinginclinations.push(inc);
		}
	}

	if ("Oral" in info.skills)
		V.pc.lose_virginity("mouth", "a high school fling");

	if (!info.virginity)
	{
		if (V.pc.has_part("penis")) V.pc.lose_virginity("penis", "a high school fling");
		if (V.pc.has_part("vagina")) V.pc.lose_virginity("vagina", "a high school fling");
	}
	if ("analvirginity" in info && !info.analvirginity)
	{
		V.pc.lose_virginity("anus", "a high school fling");
	}
}

