			if (tag.match("quickielocation"))
			{
				let loc = tag.substring("quickielocation".length);
				if (!V.pc.clothes_ok(loc))
					return false;
				if (loc == "QuickieBurger" && V.quickieburgerjob && V.quickieburgerjob.strike && V.quickieburgerjob.strike <= V.gameday)
					return false;
				return setup.is_open(loc);
			}
			else if (tag.match("quickieifresident") && npc)
			{
				let hall = tag.substring("quickieifresident".length).replace("_", " ");
				if (setup.people.lives(npc) == hall)
					return true;
			}
			else if (tag.match("quickieroomtype"))
			{
				return true;
			}
		}
	}
	return false;
}

setup.quickie_info = function(partners, witnessing = false)
{
	if (!Array.isArray(partners))
		partners = [partners];
	let npc = setup.people.get_name(partners[0]);

	let quickieinfo = {};
	let eventtag;

	if (V.housing)
	{
		const hkey = V.housing.key;
		quickieinfo.location = "HousingRoom";
		quickieinfo.locationblock = V.housing.building;
		quickieinfo.lastlocpassage = quickieinfo.location;

		const alone = V.peopleatlocation.length == 0 || (V.peopleatlocation.length == 1 && V.peopleatlocation.includes(npc));
		let roomid = alone ? V.housing.roomID : setup.ob_housing.reserved_bedroom_for_pc(hkey) || setup.ob_housing.bedroom_for_npc(hkey, npc) || setup.ob_housing.find_bedroom_for_npc(hkey, npc) || setup.ob_housing.all_roomids(hkey).some(rid => setup.ob_housing.room_class_raw(hkey, rid) == "bedroom");

		quickieinfo.housingRoomID = roomid;
		const roomclass = setup.ob_housing.room_class_raw(hkey, roomid);
		quickieinfo.roomtype = setup.ob_housing.roomClasses[roomclass].roomtype;
	}
	else
	{
		for (let tag of V.lastloctags)
		{
			if (tag.match("quickielocation"))
			{
				quickieinfo.location = tag.substring("quickielocation".length);
				quickieinfo.lastlocpassage = quickieinfo.location;
				let theretags = Story.get(quickieinfo.location).tags;
				for (let tag2 of theretags)
				{
					if (tag2.match("quickieroomtype"))
					{
						quickieinfo.roomtype = tag2.substring("quickieroomtype".length);
					}
					else if (tag2.match("locblock"))
					{
						quickieinfo.locationblock = tag2.substring("locblock".length);
					}
				}
			}
			else if (tag.match("quickieifresident") && npc)
			{
				quickieinfo.roomtype = "dorm";
				let hall = tag.substring("quickieifresident".length).replace("_", " ");
				if (hall == "Chicory Hall")
				{
					quickieinfo.location = "MainHall";
					quickieinfo.locationblock = "ResidenceHall";
					quickieinfo.lastlocpassage = quickieinfo.location;
				}
			}
			else if (tag.match("quickieroomtype"))
			{
				quickieinfo.roomtype = tag.substring("quickieroomtype".length);
				if (!eventtag) eventtag = quickieinfo.roomtype;
			}
			else if (tag.match("quickieeventtag"))
			{
				eventtag = tag.substring("quickieeventtag".length);
			}
		}
	}

	if (eventtag && !witnessing)
		quickieinfo.midevent = setup.ob_events.encounter_midevent(["encounter event", "quickie", eventtag]);

	return quickieinfo;
}

setup.ob_init_quickie = function(partners, makeout = true)
{
	if (!Array.isArray(partners))
		partners = [partners];
	let npc = partners[0];

