	if (quickieinfo.housingRoomID)
	{
		V.housing.roomID = quickieinfo.housingRoomID;
		delete quickieinfo.housingRoomID;
	}

	for (const [k, v] of Object.entries(quickieinfo))
		V[k] = v;

	if (!makeout || partners.length > 1)
	{
		setup.build_encounter({people: ["PC", ...partners], endpassage: "QuickiePost", abortpassage: "QuickieAbort", aftercare: false});
		return "EncounterRound";
	}
	else
	{
