setup.participating_in_nnn = function(npc)
{
	if (!setup.ob_is_nnn_time() && !setup.is_nnn_dayafter_time()) return false;

	if (setup.is_nnn_dayafter_time() && V.gameday - V.lastorgasmday <= 1) return false;

	if (V.pc.equals(npc))
		if (this.is_nnn_dayafter_time())
			return V.nnn?.participating && !V.nnn.lost && !V.nnn.steam;
		else
			return V.nnn?.participating && !V.nnn.lost;
	else
	{
		npc = setup.people.get_name(npc);
		let pdata = setup.people.get_person(npc);

		if (pdata.nnn?.lost) return false;
		if (this.is_nnn_dayafter_time() && pdata.nnn?.steam) return false;
		if (pdata.nnn?.participating) return true;
		else if (pdata.nnn?.participating != undefined && !pdata.nnn?.participating) return false;
		if (npc == V.niches["The Master of Willpower"]) return true;
		if (pdata.age > 30) return false;
		if (pdata.type == "faculty") return false;

		let chance = 0;

		if (["Gamer", "Young Scientist", "Intellectual"].includes(setup.people.archetype(npc)))
			chance += 0.5;

		if (setup.people.get_type(npc) == "student")
		{
			let year = setup.people.get_year(npc);
			chance += [0.2, 0.1, 0, 0][year];
		}

		if (setup.people.skillleveled(npc, "Intellectual", 5))
			chance += 0.2;

		let rng = setup.ob_newRNG(npc);
		return rng.random() < chance;
	}
}

