setup.ob_next_saturday_that_isnt_too_close = function(day = V.day, month = V.month, year = V.year)
{
	// returns the day and month of the next saturday, unless we're <3 days away from it, in which case we return the saturday after that
	let omonth = month;
	let remainder = day % 7;
	let next;
	if (remainder == 0)
		next = day;
	else
	{
		next = day + (7 - remainder);
		if (next > 28)
		{
			next = 7;
			month++;
		}
	}

	if (next - day >= 0 && next - day <= 3)
	{
		next += 7;
		if (next > 28)
		{
			next = 7;
			month++;
		}
	}

	if (month >= setup.ob_time.months.length)
		month = 0;
	if (omonth != month && month == setup.ob_time.months.indexOf("Frostuary"))
		year++;

	if ([2].includes(month)) // ended up in a summer month...
		return [7, 3, year];

	return [next, month, year];
}

