//#region Card Gen. Functions

setup.ob_tcg.init = function(rng = new RNG())
{
    if (V.tcg) return;
    V.tcg = {};
    this.generate_cards(rng);
}

setup.ob_tcg.generate_cards = function(rng = new RNG())
{
    V.tcg.cards_db = [];

    let words = {};
    for (const [wkey, wvalue] of Object.entries(this.words))
    {
        if (wkey == "character")
        {
            const allnames = [...setup.ob_names.female, ...setup.ob_names.male, ...setup.ob_names.neutral, ...setup.ob_names.femalefantasy, ...setup.ob_names.malefantasy, ...setup.ob_names.neutralfantasy, ...setup.ob_names.fun];
            const uniquenames = allnames.filter((item, pos) => allnames.indexOf(item) === pos).filter((item) => /^[a-z]*$/gi.test(item));
            words[wkey] = rng.shuffle(uniquenames);
        }
        else
            words[wkey] = rng.shuffle([...wvalue]);
    }

    for (const pkey of Object.keys(this.planets))
    {
        for (const [rkey, rvalue] of Object.entries(this.rarities))
        {
            for (let i = 0; i < rvalue.cards_total / 5; i++)
            {
                let name = rng.randomrelfreq(rvalue.patterns);

                for (const [wkey, wvalue] of Object.entries(words))
                {
                    if (name.indexOf("%" + wkey) < 0) continue;

                    if (wkey == "character")
                        name = name.replace("%" + wkey, this.generate_character(wvalue.shift(), rng));
                    else
                        name = name.replace("%" + wkey, wvalue.shift());
                }

                let card = this.create_card(name, rkey, pkey, V.tcg.cards_db.length, rng);
                V.tcg.cards_db.push(card);
            }
        }
    }
}

setup.ob_tcg.generate_character = function(firstname, rng = new RNG())
{
    const fromletter = "aceilnouyz";
    const   toletter = "åčęíłñøüỷż";

    // make the reverse a little less weird
    firstname = firstname.charAt(0).toLowerCase() + firstname.slice(1);
    if (firstname.charAt(0) == "j") firstname = firstname.slice(1);
    firstname = firstname.replace("ea", "æ");
    firstname = firstname.replace("sh", "hs");
    firstname = firstname.replace("th", "ht");
    firstname = firstname.replace("ch", "hc");
    firstname = firstname.replace("ph", "hp");
    firstname = firstname.replace("ck", "kc");
    firstname = firstname.replace("qu", "uq");
    firstname = firstname.replace("wh", "w");

    // reverse
    firstname = firstname.split("").reverse().join("");
    if ("aeiouyæ".indexOf(firstname.charAt(0)) < 0 && "aeiouyæ".indexOf(firstname.charAt(1)) < 0)
        firstname = firstname.charAt(0).toUpperCase() + "'" + firstname.charAt(1).toUpperCase() + firstname.slice(2);
    else
        firstname = firstname.charAt(0).toUpperCase() + firstname.slice(1);

    if (rng.random() < 0.25)
    {
        // randomly add diacritics
        let pos = Math.floor(rng.random() * fromletter.length);
        firstname = firstname.replace(fromletter.charAt(pos), toletter.charAt(pos));
    }

    return firstname;
}

setup.ob_tcg.create_card = function(cardname, rarity, planet, index, rng = new RNG())
{
    let retval = {
        name: cardname,
        rarity: rarity,
        planet: planet,
        index: index,
        known: false,
        total: 0,
    };

    let bestval = 0;
    let beststats = [];
    for (const [skey, svalue] of Object.entries(this.planets[planet].max_stats))
    {
        const min_stat = svalue * this.rarities[rarity].min_stats_perc / 100;
        const max_stat = svalue * this.rarities[rarity].max_stats_perc / 100;
        retval[skey] = Math.round((max_stat - min_stat) * rng.random() + min_stat);
        retval.total += retval[skey];
        if (retval[skey] > bestval)
        {
            bestval = retval[skey];
            beststats = [skey];
        }
        else if (retval[skey] == bestval)
        {
            beststats.push(skey);
        }
    }
    retval.upgrade = rng.randomchoice(beststats);

    return retval;
}

setup.ob_tcg.card_price = function(card)
{
    let retval = this.card(card).total / 3;

    if (this.card(card).rarity == "rare") retval *= 2;
    else if (this.card(card).rarity == "common") retval /= 2;

    return Math.max(Math.round(retval), 1);
}


//#region Card Functions

setup.ob_tcg.card = function(card)
{
    if (Number.isInteger(card) && card < V.tcg.cards_db.length)
        return Object.assign({}, V.tcg.cards_db[card]);
    else if (typeof card == "object")
        return this.card(card.index);
    else
        return null;
}

setup.ob_tcg.rarity_icon = function(card)
{
    const _card = this.card(card);
    return this.rarities[_card.rarity].icon;
}

setup.ob_tcg.planet_icon = function(card)
{
    const _card = this.card(card);
    return this.planets[_card.planet].icon;
}

setup.ob_tcg.planet_highlight = function(card)
{
    const _card = this.card(card);
    return this.planets[_card.planet].highlight;
}


//#region Collection Functions

setup.ob_tcg.cards = function(filter)
{
    if (filter?.owned && !V.tcg.pccoll) return[];
    let cards = [...V.tcg.cards_db];

    if (filter)
    {
        if (filter.name) cards = cards.filter((card) => card.name == filter.name);
        if (filter.rarity) cards = cards.filter((card) => card.rarity == filter.rarity);
        if (filter.planet) cards = cards.filter((card) => card.planet == filter.planet);
        if (filter.owned) cards = cards.filter((card) => V.tcg.pccoll[card.index] > 0);
        if (filter.playset) cards = cards.filter((card) => V.tcg.pccoll[card.index] >= this.decks.max_copies);
    }

    return cards.sort((a,b) => (a.name > b.name) ? 1 : ((b.name > a.name) ? -1 : 0));
}

setup.ob_tcg.create_collection = function()
{
    return new Array(V.tcg.cards_db.length).fill(0);
}

setup.ob_tcg.generate_boosters = function(num = 1, rng = new RNG())
{
    let retval = this.create_collection();

    for (const [rkey, rvalue] of Object.entries(this.rarities))
    {
        let lastcards;
        for (let i = 0; i < num; i++)
        {
            let cards = rng.shuffle([...this.cards({rarity: rkey})]);

            if (lastcards && cards.every((card, i) => card == lastcards[i]))
            {
                rng = new RNG();
                cards = rng.shuffle([...this.cards({rarity: rkey})]);
            }
            lastcards = [...cards];

            for (let j = 0; j < rvalue.cards_booster; j++)
            {
                let card = cards.shift();
                retval[card.index]++;
            }
        }
    }

    return retval;
}

setup.ob_tcg.join_collections = function(source, target)
{
    if (Array.isArray(source) && Array.isArray(target) && source.length == target.length)
    {
        for (let i = 0; i < source.length; i++)
            target[i] += source[i];
    }

    return target;
}

setup.ob_tcg.set_known = function(card_or_collection)
{
    if (Array.isArray(card_or_collection))
    {
        for (let i = 0; i < card_or_collection.length; i++)
        {
            if (card_or_collection[i] > 0)
                this.set_known(i);
        }
    }
    else
    {
        const card = this.card(card_or_collection);
        if (!card) return;
        V.tcg.cards_db[card.index].known = true;
    }
}


setup.ob_tcg.collection_cards = function(collection, max_copies = setup.ob_tcg.decks.max_copies)
{
    let retval = [];

    for (let i = 0; i < collection.length; i++)
    {
        const num = Math.min(collection[i], max_copies);
        for (let j = 0; j < num; j++)
            retval.push(this.card(i));
    }

    return retval;
}

//#region Deck Functions

setup.ob_tcg.generate_deck = function(collection, planets, rng = new RNG())
{
    let retval = this.collection_cards(collection).filter((card) => planets.includes(card.planet));
    // remove cards with negative synergy due to the number of planets
    retval = retval.filter((card) => (card.Synergy - 2 * (planets.length - 1)) >= 0 );
    if (retval.length < this.decks.cards) return null;

    // sort by stats total, throwing in a little randomness in case of ties
    retval = retval.sort((a,b) => (a.total > b.total) ? 1 : ((b.total > a.total) ? -1 : ((rng.random() < 0.5) ? 1 : -1)));

    // return best cards only
    while (retval.length > this.decks.cards) retval.shift();
    return retval;
}

setup.ob_tcg.planets_in_deck = function(deck)
{
    let retval = [];

    for (const pkey of Object.keys(setup.ob_tcg.planets))
    {
        for (let i = 0; i < deck.length; i++)
        {
            if (deck[i].planet == pkey)
            {
                retval.push(pkey);
                break;
            }
        }
    }

    return retval;
}

setup.ob_tcg.deck_stats = function(deck, build)
{
    let retval = {
        Power: 0,
        Disruption: 0,
        Synergy: 0,
        Speed: 0,
        planets: this.planets_in_deck(deck),
    };
    retval.synmod = -2 * (retval.planets.length - 1);
    if (build) retval.buildval = 0;

    for (let i = 0; i < deck.length; i++)
    {
        retval.Power += deck[i].Power;
        retval.Disruption += deck[i].Disruption;
        retval.Synergy += (deck[i].Synergy + retval.synmod);  // number of planets reduces synergy
        retval.Speed += deck[i].Speed;
        if (build) retval.buildval += deck[i].buildval;
    }

    retval.total = (retval.Power + retval.Disruption + retval.Speed + retval.Synergy) / deck.length;
    retval.Power /= deck.length;
    retval.Disruption /= deck.length;
    retval.Synergy /= deck.length;
    retval.Speed /= deck.length;
    if (build) retval.buildval /= deck.length;
    return retval;
}

setup.ob_tcg.planet_combinations = function(planets = Object.keys(setup.ob_tcg.planets))
{
    var combi = [];

    for (var i = 0; i < Math.pow(2, planets.length); i++)
    {
        var temp = [];
        for (var j = 0; j < planets.length; j++)
        {
            if ((i & Math.pow(2, j)))
                temp.push(planets[j]);
        }
        if (temp.length > 0)
            combi.push(temp);
    }

    combi.sort((a,b) => a.length - b.length);
    return combi;
}

setup.ob_tcg.random_top_deck = function(collection, rng = new RNG())
{
    return this.top_decks(collection, rng)[0];
}

setup.ob_tcg.top_decks = function(collection, rng = new RNG())
{
    let retval = [];
    const combi = this.planet_combinations();

    for (let i = 0; i < combi.length; i++)
    {
        const deck = this.generate_deck(collection, combi[i], rng);
        if (!deck) continue;
        if (this.planets_in_deck(deck).length != combi[i].length) continue;
        retval.push(deck);
    }
    retval = retval.sort((a,b) => this.deck_stats(a).total - this.deck_stats(b).total);

    while (retval.length > this.decks.top) retval.shift();
    return rng.shuffle(retval);
}


//#region Deck Building Functions

setup.ob_tcg.build_deck = function(collection, build)
{
    if (build.planets && build.planets.length > 0)
    {
        return this.generate_build_deck(collection, build.planets, build);
    }
    else
    {
        let retval;
        const combi = this.planet_combinations();

        for (let i = 0; i < combi.length; i++)
        {
            const deck = this.generate_build_deck(collection, combi[i], build);
            if (!deck) continue;
            if (this.planets_in_deck(deck).length != combi[i].length) continue;
            if (!retval || this.deck_stats(deck, build).buildval > this.deck_stats(retval, build).buildval)
                retval = deck;
        }
        return retval;
    }
}

setup.ob_tcg.generate_build_deck = function(collection, planets, build)
{
    let retval = this.collection_cards(collection).filter((card) => planets.includes(card.planet));
    // remove cards with negative synergy due to the number of planets
    const synmod = -2 * (planets.length - 1)
    retval = retval.filter((card) => (card.Synergy + synmod) >= 0 );
    if (retval.length < this.decks.cards) return null;

    for (const card of retval)
    {
        card.buildval = 0;
        for (const stat of Object.keys(build))
        {
            if (!card[stat]) continue;
            if (stat == "Synergy")
                card.buildval += ((card[stat] + synmod) * this.build_stat_multiplier(build, stat));
            else
                card.buildval += (card[stat] * this.build_stat_multiplier(build, stat));
        }
    }

    retval = retval.sort((a,b) => a.buildval - b.buildval);

    // return best cards only
    while (retval.length > this.decks.cards) retval.shift();
    return retval;
}

setup.ob_tcg.build_stat_text = function(value)
{
    switch (value)
    {
        case "0":
            return "negligible";
        case "1":
            return "relevant";
        case "2":
            return "important";
        default:
            return "";
    }
}

setup.ob_tcg.build_stat_multiplier = function(build, stat)
{
    switch (build[stat])
    {
        case "0":
            return 0.01;
        case "1":
            return 1;
        case "2":
            return 2;
        default:
            return 0;
    }
}

setup.ob_tcg.save_build = function(deckname, build)
{
    if (!deckname) return;
    if (!V.tcg.builds) V.tcg.builds = {}

    if (build) V.tcg.builds[deckname] = build;
    else delete V.tcg.builds[deckname];
}


//#region Game Functions

setup.ob_tcg.init_game = function(build, oppname, rng = new RNG())
{
    let pcdeck;

    if (build)
        pcdeck = this.build_deck(V.tcg.pccoll, build);
    else
        pcdeck = this.random_top_deck(V.tcg.pccoll, rng);

    const oppcoll = this.npc_collection(oppname);
    let oppdeck = this.random_top_deck(oppcoll, rng);

    let pcsynmod = this.deck_stats(pcdeck).synmod;
    pcdeck = rng.shuffle(pcdeck);
    let pchand = [];
    let oppsynmod = this.deck_stats(oppdeck).synmod;
    oppdeck = rng.shuffle(oppdeck);
    let opphand = [];
    for (let i = 0; i < this.decks.handsize; i++)
    {
        pchand.push(pcdeck.shift());
        opphand.push(oppdeck.shift());
    }

    const pcstart = (rng.random() < 0.5);
    V.tcg.game = {
        pcdeck: pcdeck,
        pchand: pchand,
        pcupgrades: this.add_upgrade(null, "Synergy", pcsynmod),
        pccontrol: 0,
        pcstart: pcstart,
        pcturn: pcstart,
        oppname: oppname,
        oppdeck: oppdeck,
        opphand: opphand,
        oppupgrades: this.add_upgrade(null, "Synergy", oppsynmod),
        oppcontrol: 0,
        opparousal: 0,
        round: 1,
    };
}

setup.ob_tcg.mulligan = function(rng = new RNG())
{
    const handsize = V.tcg.game.pchand.length - 1;
    V.tcg.game.pcdeck = [...V.tcg.game.pcdeck, ...V.tcg.game.pchand];
    V.tcg.game.pchand = [];

    V.tcg.game.pcdeck = rng.shuffle(V.tcg.game.pcdeck);
    for (let i = 0; i < handsize; i++)
    {
        V.tcg.game.pchand.push(V.tcg.game.pcdeck.shift());
    }
}

setup.ob_tcg.add_upgrade = function(upgrades, stat, val)
{
    let retval = upgrades;
    if (!retval) retval = {};

    if (retval[stat]) retval[stat] += val;
    else retval[stat] = val;

    return retval;
}

setup.ob_tcg.upgrade = function(upgrades, stat)
{
    if (!upgrades || !upgrades[stat]) return 0;
    return upgrades[stat];
}

setup.ob_tcg.stat_value = function(card, upgrades, stat)
{
    return Math.min(card[stat] + this.upgrade(upgrades, stat), 10);
}

setup.ob_tcg.upgrade_string = function(upgrades, stat)
{
    const val = this.upgrade(upgrades, stat);
    if (val == 0) return "";

    return '<<highlight "'
        + (val < 0 ? "bad" : "unbad")
        + '">>('
        + (val < 0 ? "" : "+")
        + val
        + ')<</highlight>>';
}

setup.ob_tcg.pick_card = function(hand, upgrades, othercontrol)
{
    let indexmax = -1;
    let indexmin = -1;
    let maxval = -1;
    let minval = 99;

    for (let i = 0; i < hand.length; i++)
    {
        let eff = 1 + this.stat_value(hand[i], upgrades, "Synergy") / 10;
        let val = this.stat_value(hand[i], upgrades, "Power") * eff + Math.min(this.stat_value(hand[i], upgrades, "Disruption") * eff, othercontrol);
        if (val < minval)
        {
            indexmin = i;
            minval = val;
        }
        if (this.stat_value(hand[i], upgrades, "Speed") < 11 - V.tcg.game.round) continue;
        if (val > maxval)
        {
            indexmax = i;
            maxval = val;
        }
    }

    if (indexmax >= 0) return { handindex: indexmax, discard: false };
    return { handindex: indexmin, discard: true };
}

