setup.ob_tcg.get_results = function(name)
{
    const wins = this.get_npcdata(name, "wins");
    const losses = this.get_npcdata(name, "losses");

    if (!wins && !losses) return null;

    const winshard = this.get_npcdata(name, "winshard");
    const losseshard = this.get_npcdata(name, "losseshard");

    return {
