setup.ob_tcg.cards_needed = function(thiscoll, othercoll, excludeindex, minkeep = 1)
{
    let retval = [];

    for (let i = 0; i < thiscoll.length; i++)
    {
        if (i == excludeindex) continue;
        if (thiscoll[i] >= this.decks.max_copies) continue;
        if (othercoll[i] > minkeep) retval.push(this.card(i));
    }

    return retval;
}

setup.ob_tcg.trade_cards_needed = function(thiscoll, othercoll, rarity, excludeindex, minkeep = 1)
{
    let retval;

    let needed = this.cards_needed(thiscoll, othercoll, excludeindex, minkeep);
    if (rarity)
    {
        retval = needed.filter((card) => card.rarity == rarity);
    }
    else
    {
        retval = needed.filter((card) => card.rarity == "rare");
        if (retval.length == 0)
        {
            retval = needed.filter((card) => card.rarity == "uncommon");
            if (retval.length == 0) retval = needed;
        }
    }

    return retval.sort((a,b) => (a.name > b.name) ? 1 : ((b.name > a.name) ? -1 : 0));
}

