}

setup.ob_time.clock = function(hour = V.hour, min = V.minute)
{
    let digits = this.clockdigits(hour, min);
    return digits.fullhour + ":" + digits.fullminute + digits.ampm;
}

setup.ob_time.clockdigits = function(hour = V.hour, min = V.minute)
{
    // time handled internally in 24 hour format, but we want to display it in american format
    // cuz that's where the game is set
    let ampm;
    if (!V.optamericlock)
    {
        // OR DO WE
        ampm = "";
    }
    else if (hour == 12)
    {
        ampm = "pm";
    }
    else if (hour > 12)
    {
        hour -= 12;
        ampm = "pm";
    }
    else if (hour == 0)
    {
        hour = 12;
        ampm = "am";
    }
    else
    {
        ampm = "am";
    }
    min = min.toString();
    hour = hour.toString();
    if (min.length == 1) min = "0" + min;
    return {
        fullhour: hour,
        fullminute: min,
        hour0: hour.length > 1 ? hour[0] : "",
        hour1: hour.length > 1 ? hour[1] : hour[0],
        min0: min[0],
        min1: min[1],
        ampm: ampm,
    };
}

setup.ob_time.clockshort = function(hour = V.hour, min = V.minute)
{
    let clock = this.clock(hour, min);
    return clock.replace(":00pm", "pm").replace(":00am", "am");
}

setup.ob_time.display_interval = function(minutes, allhourdigits = false)
{
    let hours = 0;
    while (minutes >= 60)
    {
        hours++;
        minutes -= 60;
    }
    hours = hours.toString();
    minutes = minutes.toString();
    if (allhourdigits && hours.length == 1) hours = "0" + hours;
    if (minutes.length == 1) minutes = "0" + minutes;
    return hours + ":" + minutes;
}

