    let min = V.minute;
    let hour = V.hour;
    let day = V.day;
    let month = V.month;
    let year = V.year;
    let gameday = V.gameday;
    let origtime = [min, hour, day, month, year, gameday];

    let last_month_index = this.months.length - 2;
    let year_boundary_minutes = (last_month_index * this.month_length + this.month_length - 1) * 24 * 60 + 23 * 60 + 59;
    let current_year_minutes = (month * this.month_length + day - 1) * 24 * 60 + hour * 60 + min;
