                        if (gameday.championship)
                            notice += " They lost the championship...";
                        else if (gameday.playoffround)
                            notice += " Sadly, that's knocked them out of the playoffs.";
                        else if (gameday.trophy)
                            notice += " That's lost the school the " + gameday.trophy + ".";
                    }

                    setup.add_notification(notice);
                }
            }
        }
        setup.ob_nPCSimulation.process_queued_events();
    }

    this.special_time_handling(origminutes);

    return [min, hour, day, month, year, gameday];
}

setup.ob_time.true_month_index = function(month = V.month)
{
    let yearstart = this.months.indexOf("Frostuary");
    return (month - yearstart + this.months.length) % this.months.length;
}

setup.ob_time.special_time_handling = function(minutes)
{
    // super specific time advancement stuff can go in here

    if (V.rocktumbling)
    {
        V.rocktumbling = Math.max(0, V.rocktumbling - minutes);
    }

    if (V.warmingbuff)
    {
        V.warmingbuff -= minutes;
        if (V.warmingbuff <= 0) delete V.warmingbuff;
    }
    if (V.coolingbuff)
    {
        V.coolingbuff -= minutes;
        if (V.coolingbuff <= 0) delete V.coolingbuff;
    }

    setup.ob_pregnancy.advance_minutes(minutes);
}

setup.ob_time.advance_clock = function(minutes)
{
    let prevhour = V.hour;
    let prevgameday = V.gameday;
    let prevday = V.day;
    let prevweek = Math.ceil(prevday / 7);

    const newtime = this.add_minutes(minutes);

    State.setVar("$minute", newtime[0]);
    State.setVar("$hour", newtime[1]);
    State.setVar("$day", newtime[2]);
    State.setVar("$month", newtime[3]);
    State.setVar("$year", newtime[4]);
    State.setVar("$gameday", newtime[5]);

    if (prevhour != newtime[1])
    {
        if (V.weather)
        {
            const todaysWeather = V.weather.todaysWeather;
            const yesterdaysWeather = V.weather.yesterdaysWeather;
            V.weather = setup.ob_weather.state();
            V.weather.todaysWeather = todaysWeather;
            V.weather.yesterdaysWeather = yesterdaysWeather;
        }
        else
        {
            V.weather = setup.ob_weather.state();
        }
    }

    let newweek = Math.ceil(newtime[2] / 7);

    if ((newtime[5] > prevgameday && newtime[1] >= 6) || (newtime[5] == prevgameday && prevhour < 6 && newtime[1] >= 6))
    {
        this.do_new_day();
        if (V.weather)
        {
            V.weather.yesterdaysWeather = V.weather.todaysWeather;
            setup.ob_weather.add_daily_weather_info();
        }
    }

    if (newweek != prevweek)
        this.do_new_week();

    if (prevhour < 6 && newtime[1] >= 6 && (setup.ob_autosaveOnTrigger("onTime0600") || (setup.ob_time.weekday(newtime[2]) == "Sunday" && setup.ob_autosaveOnTrigger("onWeekly"))))
        Save.autosave.save();
    else if (prevhour < 12 && newtime[1] >= 12 && setup.ob_autosaveOnTrigger("onTime1200"))
        Save.autosave.save();
    else if (prevhour < 18 && newtime[1] >= 18 && setup.ob_autosaveOnTrigger("onTime1800"))
        Save.autosave.save();
    else if (prevhour < 24 && newtime[1] >= 0 && newtime[1] < prevhour && setup.ob_autosaveOnTrigger("onTime0000"))
        Save.autosave.save();

}

setup.ob_time.minutes_until = function(newhour, newmin)
{
    let min = V.minute;
    let hour = V.hour;

    let dayminutes = (hour * 60) + min;
    let newdayminutes = (newhour * 60) + newmin;

    if (newdayminutes == dayminutes)
    {
        return 0;
    }
    else if (newdayminutes > dayminutes)
    {
        return newdayminutes - dayminutes;
    }
    else
    {
        return (24 * 60) - (dayminutes - newdayminutes);
    }
}

setup.ob_time.skip_summer = function()
{
    try
    {
        State.setVar("$day", 1);
        State.setVar("$month", this.months.indexOf("Autumber"));
        State.setVar("$hour", 8);
        State.setVar("$minute", 0);

        let gameyear = V.gameyear;
        if (gameyear)
            State.setVar("$gameyear", gameyear + 1);
        else
            State.setVar("$gameyear", 1);

        setup.ob_needs.magic_restore();
        setup.ob_needs.reset_fleeting_needs();

        setup.ob_time.do_new_year();

        // advance age if birthday is during summer
        if (V.pcbirthday && ["Solune", "Jaugust"].includes(V.pcbirthday[0]))
        {
            V.pcage++;
            V.pcage = Math.max(V.pcage, 18);
            V.pc.age = V.pcage;
        }
    }
    catch (error)
    {
        console.error(`Summer skip failed! ${error}`);
    }
}

setup.ob_time.is_weekend = function(day = V.day)
{
    let weekday = setup.ob_time.weekday(day);
    return weekday == "Sunday" || weekday == "Saturday";
}

setup.ob_time.is_today = function(month, day)
{
    return month == V.month && day == V.day;
}

setup.ob_time.is_tomorrow = function(month, day)
{
    let thismonth = V.month;
    let isnextmonth = month == thismonth + 1 || month == 0 && thismonth == (this.months.length - 1);
    let thisday = V.day;
    return (day == thisday + 1 && !isnextmonth) || (thisday == this.month_length && day == 1 && isnextmonth);
}

setup.ob_time.is_this_week = function(month, day, thismonth = V.month, thisday = V.day)
{
    // expects weeks defined as starting on days 1, 8, 15, or 22
    if (typeof month == "string") month = this.months.indexOf(month);
    return month == thismonth && thisday >= day && thisday < day + 7;
}

setup.ob_time.is_same_week = function(month, day)
{
    // true if we're in the same day 1 to 7, 8 to 14, 15 to 21, or 22 to 28 chunk
    let thismonth = V.month;
    let thisday = V.day;
    if (typeof month == "string") month = this.months.indexOf(month);
    if (month == thismonth)
    {
        return (thisday <= 7 && day <= 7)
            || (thisday > 7 && thisday <= 14 && day > 7 && day <= 14)
            || (thisday > 14 && thisday <= 21 && day > 14 && day <= 21)
            || (thisday > 21 && thisday <= 28 && day > 21 && day <= 28);
    }
    return false;
}

setup.ob_time.adjust_needs = function(minutes)
{
    for (const [need, decayrate] of Object.entries(this.natural_decay_time))
    {
        let rate = decayrate;
        if (V.sleeping)
        {
            rate = this.sleep_decay_time[need];
        }

        if (rate == -1) continue; // does not decay

        let dpm = 1000 / rate;
        if (dpm > 0)
            setup.ob_needs.decay_need(need, dpm * minutes);
        else
            setup.ob_needs.increase_need(need, -dpm * minutes);
    }
}

setup.ob_time.wet_clothes = function(minutes)
{
    if (!setup.ob_location_is_outdoors() || V.pc.has_rain_protection() || !V.optweathereffects) return;

    let wet;
    switch (setup.ob_get_weather())
    {
        case "rain":
            wet = 60;
            break;
        case "drizzle":
            wet = 20;
            break;
        case "snow":
            wet = 30;
            break;
        case "flurries":
            wet = 15;
            break;
    }

    if (wet)
        V.pc.add_wetness_all(wet * minutes, true);
}

setup.ob_time.dry_clothes = function(minutes)
{
    let dry_fully;
    switch (setup.ob_get_temperature())
    {
        case "hot":
            dry_fully = 4 * 60;
            break;
        case "warm":
            dry_fully = 6 * 60;
            break;
        case "comfortable":
            dry_fully = 8 * 60;
            break;
        case "chilly":
            dry_fully = 10 * 60;
            break;
        case "freezing":
            dry_fully = 12 * 60;
            break;
    }
    const dry = minutes / dry_fully * -1000;

    V.pc.add_wetness_all(dry);

    /* dry clothes in closet - currently not  implemented
    let closet = V.pc.get_storage_location("dormcloset");
    for (let i = 0; i < closet.get_item_count(); i++)
    {
        cItem = new ClothingItem(closet.get_item(i));
        cItem.add_wetness(dry);
    }*/
}

setup.ob_time.advance_time = function(minutes)
{
    this.advance_clock(minutes);
    this.adjust_needs(minutes);
    this.wet_clothes(minutes);
    this.dry_clothes(minutes);

    if (V.laundrytime)
    {
        State.setVar("$laundrytime", Math.max(0, V.laundrytime - minutes));
    }
    if (V.riverrat?.working)
    {
        setup.ob_riverRat.add_minutes_worked(minutes);
    }
    if (V.greekunderwearraid?.active)
    {
        setup.ob_houses.progress_raid(minutes);
    }
    if (V.greekparty?.freeuse)
    {
        if (V.greekparty.minutessincefreeuse == undefined)
            V.greekparty.minutessincefreeuse = 0;
        V.greekparty.minutessincefreeuse += minutes;
    }
}

setup.ob_time.timeofday = function(hour = V.hour)
{
    if (hour < 6)
        return "night";
    else if (hour < 12)
        return "morning";
    else if (hour < 18)
        return "afternoon";
    else if (hour < 22)
        return "evening";
    else
        return "night";
}

setup.ob_time.previous_timeofday = function(slice)
{
    let current = slice || this.timeofday();
    return {"morning":"morning", "afternoon":"morning", "evening":"afternoon", "night":"evening"}[current];
}

setup.ob_time.day_slices_passed = function()
{
    // which day slices have already come and gone today?
    let slice = this.timeofday();
    return {
        "morning":      [],
        "afternoon":    ["morning"],
        "evening":      ["morning", "afternoon"],
        "night":        ["morning", "afternoon", "evening"],
    }[slice];
}

setup.ob_time.current_time_gte = function(timeobj)
{
    // is current time at the given time or over it?
    // expecting an object with 'hour' and possibly 'minute' properties
    if (V.hour < timeobj.hour)
    {
        return false;
    }
    else if (V.hour == timeobj.hour && "minute" in timeobj && V.minute < timeobj.minute)
    {
        return false;
    }
    else
    {
        return true;
    }
}

setup.ob_time.current_schedule_slot = function(schedule) {
  if (!Array.isArray(schedule)) return null;
  return schedule.slice().reverse().find(slot => this.current_time_gte(slot)) || null;
}

setup.ob_time.current_schedule_slot_calcall = function()
{
    // there are only 4 possible schedules, so let's find all four slots for the current hour/minute
    // otherwise we end up recalculating this for individual NPCs a LOT
    const student = [];
    const townie = [];
    for (let i = 1; i <= 4; i++)
    {
        student.push(this.current_schedule_slot(setup.get_student_schedule(i)));
        townie.push(this.current_schedule_slot(setup.get_townie_schedule(i)));
    }
    return {student, townie};
}

setup.ob_time.schedule_slots_for = function(npc, slots)
{
    if (setup.people.get_type(npc) == "student")
        return slots["student"];
    else
        return slots["townie"];
}

setup.ob_time.schedule_block_today = function(block)
{
    let day = this.weekday(V.day);
    const blocks = setup.School.blocks[block];
    for (let i = 0; i < blocks.length; i++)
    {
        if (blocks[i].day == day)
            return blocks[i];
    }
}

setup.ob_time.subjective_time_of_day = function(hour = V.hour)
{
    if (hour >= 5 && hour < 11)
        return "morning";
    else if (hour < 18)
        return "day";
    else if (hour < 22)
        return "afternoon";
    else
        return "night";
}

setup.ob_time.nightlife_time = function(hour = V.hour)
{
    return this.subjective_time_of_day(hour) == "afternoon" || (this.is_weekend() && hour >= 22);
}

setup.ob_time.nearest_x_minute = function(x, minute = V.minute, hour = V.hour)
{
    // if hour == 5 and x == 30, this will output 5:00 am or 5:30 am, whatever's closest to minute.
    // this func rounds down in order to cut time into blocks that match x
    // (e.g. a 30 minute time block will start at 5:30 rather than at 5:15)
    minute = (Math.floor(minute * (1/x)) * x)
    return this.clock(hour, minute)
}

setup.ob_time.do_new_year = function()
