setup.ob_time.do_new_week = function()
{
    // executes when saturday rolls over to sunday at midnight

    if (V?.sportsteams?.["football"]?.selectedRoutine)
        delete V.sportsteams["football"].selectedRoutine;

    if (V?.sportsteams?.["esports"]?.selectedRoutine)
        delete V.sportsteams["esports"].selectedRoutine;

    if (V?.sportsteams?.["swimming"]?.selectedRoutine)
        delete V.sportsteams["swimming"].selectedRoutine;
}

setup.ob_time.dayslice_to_time = function(gameday, slice)
{
    let label;
    if (gameday == V.gameday)
    {
        label = "this " + slice;
    }
    else if (gameday == V.gameday + 1)
    {
        label = "tomorrow " + slice;
    }
    else if (gameday == V.gameday - 1)
    {
        label = "yesterday " + slice;
    }
    else
    {
        label = "some other " + slice;
    }
    const replacements = {"this night": "tonight", "yesterday night": "last night"};
    if (replacements[label]) label = replacements[label];
    return label;
}

