        delete State.variables.costumecontest;
    }
    if (!setup.ob_is_renfest())
    {
        delete State.variables.stealthysionnach;
    }
    if (V.nnn && !setup.ob_is_nnn_time())
    {
        if (!setup.is_nnn_dayafter_time())
            setup.ob_cleanup_nnn();
        else if (!V.nnn.success && !V.nnn.lost && V.nnn.participating)
            V.nnn.success = true;
    }

    if (profilenewday) console.log("Conditional var reset time:", performance.now() - start);

    // call other functions that need to happen daily
    setup.ob_relationships.scan_for_invalid();
    if (profilenewday) console.log("Invalid relationships scan time:", performance.now() - start);
    setup.ob_relationships.maybe_expose_secret_relationships();
    if (profilenewday) console.log("Secret relationships scan time:", performance.now() - start);
    setup.ob_relationships.decay_relationship_suspicion();
    if (profilenewday) console.log("Relationship decay time:", performance.now() - start);
    setup.ob_riverRat.daily_tick();
    if (profilenewday) console.log("River Rat tick time:", performance.now() - start);
    setup.ob_clickbaitTV.daily_tick();
    if (profilenewday) console.log("ClickBait tick time:", performance.now() - start);
    setup.ob_creating.daily_tick_books();
    setup.ob_creating.daily_tick_art();
    if (profilenewday) console.log("Creation side gigs tick time:", performance.now() - start);
    setup.ob_amateurPornTown.daily_tick();
    if (profilenewday) console.log("APT tick time:", performance.now() - start);
    setup.ob_pregnancy.daily_tick();
    if (profilenewday) console.log("Pregnancy tick time:", performance.now() - start);

    if (setup.ob_is_homebase())
        setup.ob_housing.delete_temporary_housing();

    // check hair growth

    let growth_multiplier = V.opthairgrowthspeedmultiplier;

    if (growth_multiplier > 0)
    {
        let headhairgrowsafter = Math.ceil(21 / growth_multiplier);
        if (!("lasthairgrowthday" in State.variables))
        {
            State.setVar("$lasthairgrowthday", V.gameday)
        }
        else if (V.gameday - V.lasthairgrowthday >= headhairgrowsafter)
        {
            State.setVar("$lasthairgrowthday", V.gameday);

            let len = setup.ob_hairlengths.indexOf(V.pchairlength) + 1;
            if (len < setup.ob_hairlengths.length)
            {
                let newlenstr = setup.ob_hairlengths[len];

                let pc = V.pc;
                State.setVar("$pchairlength", newlenstr);
                pc["hair length"] = newlenstr;

                setup.add_notification("Your hair is now " + newlenstr + ".");

                let styleinfo = setup.ob_hairstyles[V.pchairstyle];
                if ("maximum length" in styleinfo && setup.ob_hairlengths.indexOf(styleinfo["maximum length"]) < len)
                {
                    setup.add_notification("Your hair has grown too long to maintain its style. Time to visit the stylist!");

                    State.setVar("$pchairstyle", "unstyled");
                    pc["hair style"] = "unstyled";
                }
            }
        }
    }

    if (profilenewday) console.log("Hair growth time:", performance.now() - start);

    // check pubic hair growth
    if (!("lastpubicstyle" in State.variables))
    {
        let day = V.gameday;
        State.setVar("$lastpubicstyle", day);
    }
    else
    {
        let pc = V.pc;
        let pstyle = pc.pubic_style;
        let styleinfo = setup.ob_cosmetics.pubic_styles[pstyle];

        // calculate growth_day based on current amount of hair and the PC's natural hairiness
        let growth_day = (9 + styleinfo.shavelevel * setup.ob_cosmetics.body_hair_growth[pc.body_hair_growth].growth_rate);
        // apply the multiplier cheat
        if (growth_multiplier == 0){ // we don't wanna grow hair ever
            growth_day = V.gameday + 1 // every day, procratinate hair growth until tomorrow (so it never grows)
        } else {
            growth_day = growth_day / growth_multiplier;
        }
        if (V.gameday - V.lastpubicstyle >= growth_day)
        {
            if (styleinfo.shavelevel < 4)
            {
                let nextstyle = pstyle;
                let pstyleinfo = setup.ob_cosmetics.pubic_styles[pstyle];
                for (const style of Object.keys(setup.ob_cosmetics.pubic_styles)){
                    let styleinfo = setup.ob_cosmetics.pubic_styles[style];
                    if (styleinfo.unstyled && styleinfo.shavelevel == (pstyleinfo.shavelevel + 1)){
                        nextstyle = style;
                        break;
                    }
                }
                pc.pubic_style = nextstyle;
                State.setVar("$lastpubicstyle", V.gameday);
                styleinfo = setup.ob_cosmetics.pubic_styles[nextstyle];
                setup.add_notification("Your pubic hair is now " + styleinfo.descriptor + ".");
            }
        }
    }

    if (profilenewday) console.log("Pubic hair growth time:", performance.now() - start);

    // check extra body hair growth
    let allbodyhairstyles = ["butt", "armpit", "tummy", "leg", "arm", "chest"];
    if (!V.lastbodyhairstyles){
        let day = V.gameday;
        State.setVar("$lastbodyhairstyles",
        {
            "butt": day,
            "armpit": day,
            "tummy": day,
            "leg": day,
            "arm": day,
            "chest": day,
        });
    } else {
        let newbodyhairstyle = V.lastbodyhairstyles;
        for (const hair of Object.keys(newbodyhairstyle)){
            let pc = V.pc;

            let hairgrowth = setup.ob_cosmetics.body_hair_growth[pc.body_hair_growth]
            let lookup = hair + "_hair_styles";
            let pcstyle = pc.body_hair[hair];
            let all_styles = setup.ob_cosmetics[lookup];
            let pcstyleinfo = all_styles[pcstyle];

            if (pcstyleinfo == undefined) continue;

            // calculate growth_day based on current amount of hair and the PC's natural hairiness
            let growth_day = (9 + pcstyleinfo.shavelevel * hairgrowth.growth_rate);
            // apply the multiplier cheat
            if (growth_multiplier == 0 || !V.optextrabodyhair){ // we don't wanna grow hair ever
                growth_day = V.gameday + 1 // every day, procratinate hair growth until tomorrow (so it never grows)
            } else {
                growth_day = growth_day / growth_multiplier;
            }
            // if it's time for hair to grow...
            if (V.gameday - V.lastbodyhairstyles[hair] >= growth_day){
                // try to find the next-hairiest natural hair style dynamically, and grab it
                let nextstyle = pcstyle;
                for (const style of Object.keys(all_styles)){
                    let styleinfo = all_styles[style];
                    if (styleinfo.unstyled && styleinfo.shavelevel == (pcstyleinfo.shavelevel + 1)){
                        nextstyle = style;
                        break;
                    }
                }

                // if we found a next hair style, grow the hair and send a notification
                if (nextstyle != pcstyle){
                    pc.body_hair[hair] = nextstyle;
                    newbodyhairstyle[hair] = V.gameday;
                    if (V.optextrabodyhair)
                        setup.add_notification("Your "+ hair + " hair is now " + all_styles[nextstyle].descriptor.replaceAll("%pp", "your") + ".");
                }
            }
        }
        for (const missingstyle of allbodyhairstyles)
            if (!(missingstyle in newbodyhairstyle))
                newbodyhairstyle[missingstyle] = V.gameday;
        State.setVar("$lastbodyhairstyles", newbodyhairstyle); // overwrite original dictionary to lock it in
    }
    if (profilenewday) console.log("Body hair growth time:", performance.now() - start);

    // check facial hair(beard) growth
    let pc = setup.pc()
    if (growth_multiplier > 0)
    {
        let facialhairgrowsafter = Math.ceil((2**(pc.beard_length+1)) / growth_multiplier);
        if (!pc.grows_beard){}
        else if (!("lastbeardgrowth" in State.variables))
        {
            State.setVar("$lastbeardgrowth", V.gameday)
        }
        else if (V.gameday - V.lastbeardgrowth >= facialhairgrowsafter)
        {
            let bstyle = pc.beard_style;
            let oldstyleinfo = setup.ob_cosmetics.beard_styles[bstyle];

            if (pc.beard_length < setup.ob_cosmetics.beard_lengths.length-1)
            {
                pc.beard_length++;
                let length_string = setup.ob_cosmetics.beard_lengths[pc.beard_length]
                setup.add_notification("Your facial hair is now "+ length_string + ".")
                State.setVar("$lastbeardgrowth", V.gameday);

                if ("max_length" in oldstyleinfo && oldstyleinfo.max_length < pc.beard_length){
                    if (length_string === setup.ob_cosmetics.beard_lengths[1]){
                        pc.beard_style = "stubble"
                    }
