setup.ob_weather.weather_block_label = function(day = V.day, month = V.month)
{
    if (typeof month == "number")
        month = setup.ob_time.months[month];

    let pre;
    if (day < setup.ob_time.month_length / 2) pre = "early";
    else pre = "late";

    return `${pre} ${month}`;
}

setup.ob_weather.season = function(day = V.day, month = V.month)
{
    return this.blocks[this.weather_block_label(day, month)].season;
}

setup.ob_weather.state = function(hour = V.hour, day = V.day, month = V.month, year = V.year)
{
    // the method that determines what the weather is

    // first determine a seed! this makes weather predictable and also defines our weather block size
    // (as in, if we want weather to only be rerolled once a day, use the seed that doesn't factor in hours)
    const hourseed = inthash(`${String(hour).padStart(2, "0")}${String(day).padStart(2, "0")}${String(month).padStart(2, "0")}${year}${V.seed}`);
    const dayseed = inthash(`${String(day).padStart(2, "0")}${String(month).padStart(2, "0")}${year}${V.seed}`);

    const rng = setup.ob_newRNG(hourseed);
    const simplex = new SimplexNoise(() => rng.random());

    // we also need to set some standards based on current time of year
    const weatherinfo = this.blocks[this.weather_block_label(day, month)];

    // we'll say the low temp typically happens around 5am and the high temp is around 3pm
    let radians = ((hour - 5) / 24) * 2 * Math.PI;
    let timeofdayfactor = Math.cos(radians) * -0.5 + 0.5;

    const daynoise = simplex.noise2D(dayseed, 0);
    const maxdailyvariation = 3;
    const dailyoffset = (daynoise + 1) / 2 * (maxdailyvariation * 2) - maxdailyvariation;

    const hournoise = simplex.noise2D(hourseed, 100);
    const maxhourlyvariation = 1.5;
    const houroffset = (hournoise + 1) / 2 * (maxhourlyvariation * 2) - maxhourlyvariation;
    // set this aside for a moment, we need to figure out a couple other things before we finalize temp

    // precipitation
    const precipnoise = simplex.noise2D(hourseed, 200);
    let precipvalue = (precipnoise + 1) / 2;
    precipvalue += (weatherinfo.avgPrecip - 0.5);
    precipvalue = Math.clamp(precipvalue, 0, 1);

    const precipcutoff = 0.6;
    const heavyprecipcutoff = precipcutoff + ((1 - precipcutoff) / 2);

    // don't make week one too complicated, also springril splash exception
    if (V.gameday <= 7 || setup.ob_is_springrilsplash_party_time())
        precipvalue = Math.min(precipvalue, 0.5);

    // cloud cover
    const cloudnoise = simplex.noise2D(hourseed, 202); // should be somewhat but not completely correlated with precipitation chance
    let cloudvalue = (cloudnoise + 1) / 2;

    if (setup.ob_is_springrilsplash_party_time())
        cloudvalue = Math.min(cloudvalue, 0.5);

    // resolve some of this into a weather string for top-level decisions
    let weather;
    if (precipvalue > heavyprecipcutoff)
        weather = "rain";
    else if (precipvalue > precipcutoff)
        weather = "drizzle";
    else if (cloudvalue > 0.8)
        weather = "overcast";
    else if (cloudvalue > 0.6)
        weather = "mostly cloudy";
    else if (cloudvalue > 0.3)
        weather = "partly cloudy";
    else
        weather = "clear";

    const maxcloudcooling = 4;
    const maxcloudwarming = 2;
    let sunlightfactor;
    if (hour >= 6 && hour <= 18)
    {
        sunlightfactor = 1 - Math.abs(12 - hour) / 6;
    }
    else
    {
        sunlightfactor = 0;
    }
    const cloudtemppadding = cloudvalue * (sunlightfactor == 0 ? maxcloudwarming : 0);
    const cloudtemppenalty = cloudvalue * sunlightfactor * maxcloudcooling;
    const adjustedhigh = weatherinfo.avgHigh - cloudtemppenalty;
    const adjustedlow = weatherinfo.avgLow + cloudtemppadding;

    // finally finish determining temperature
    let basetemp = adjustedlow + (adjustedhigh - adjustedlow) * timeofdayfactor;
    let temp = basetemp + dailyoffset + houroffset;

    const maxtemp = 38;
    const mintemp = -10;
    temp = Math.clamp(temp, mintemp, maxtemp);

    if (cloudvalue < 0.2 && sunlightfactor >= 0.5)
        temp += 0.5;

    // now revisit precipitation
    if (temp <= 2)
    {
        if (weather == "drizzle")
            weather = "flurries";
        else if (weather == "rain")
            weather = "snow";
    }

    let state = {
        temperature: Math.round(temp),
        cloudiness: cloudvalue,
        precipitation: precipvalue < precipcutoff ? 0 : precipvalue,
        description: weather,
        timeofday: setup.ob_time.timeofday(hour),
    };

    return state;
}

