setup.ob_weather.forecast_for_hours = function(start, end, day = V.day, month = V.month)
{
    // return lowest low and highest high and greatest precipitation chance for a given range of hours
    let forecast = {
        low: 99,
        high: -99,
        precipitation: 0,
        cloudiness: 0,
        description: "",
        descriptions: [],
    };

    if (end < start) end += 24;

    const descriptionseverity = ["clear", "partly cloudy", "mostly cloudy", "overcast", "drizzle", "flurries", "rain", "snow"];

    for (let i = start; i <= end; i++)
    {
        let thour = i >= 24 ? i - 24 : i;
        let tday = i >= 24 ? day + 1 : day;
        let tmonth = month;
        if (tday > setup.ob_time.month_length)
        {
            tday = 1;
            tmonth++;
            if (tmonth >= setup.ob_time.months.length)
                tmonth = 0;
        }
        let weather = setup.ob_weather.state(thour, tday, tmonth);

        if (weather.temperature < forecast.low)
            forecast.low = weather.temperature;
        if (weather.temperature > forecast.high)
            forecast.high = weather.temperature;
        if (weather.precipitation > forecast.precipitation)
            forecast.precipitation = weather.precipitation;
        if (weather.cloudiness > forecast.cloudiness)
            forecast.cloudiness = weather.cloudiness;

        forecast.descriptions.push(weather.description);

        if (!forecast.timeofday) forecast.timeofday = weather.timeofday;

        forecast.temperature = (forecast.low + forecast.high) / 2;
    }

    let counts = [];
    for (let desc of new Set(forecast.descriptions))
        counts.push([desc, forecast.descriptions.count(desc) * (descriptionseverity.indexOf(desc) + 1)]);
    counts.sort((a, b) => (b[1]-a[1]));

    forecast.description = counts[0][0];
    delete forecast.descriptions;

    return forecast;
}

